def _verify_detached_signature(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None) -> dict[str, Any]:
    package_name = package_name or _package_name()
    signing_payload = _signing_payload(project_id=project_id, package_name=package_name, zip_path=zip_path)
    signature = _read_signature_json(signature_path)
    if signature is None:
        rows = [{"name": "detached-signature", "status": "warn", "message": "No detached signature supplied; artifact remains unsigned."}]
        result = _normalized_signature_trust_result(supplied=False, valid=False, trusted=False, status="warn", public_fingerprint=None, rows=rows)
        return {**result, "rows": rows, "message": "No detached signature supplied; unsigned artifact is warn/ok only.", "signing_payload": signing_payload}
    rows: list[dict[str, Any]] = []
    if "_read_error" in signature:
        rows.append({"name": "signature-file", "status": "blocked", "message": signature["_read_error"]})
        result = _normalized_signature_trust_result(supplied=True, valid=False, trusted=False, status="blocked", public_fingerprint=None, rows=rows)
        return {**result, "rows": rows, "message": "Detached signature file could not be read.", "signing_payload": signing_payload}
    rows.extend(_signature_sidecar_validation_rows(signature, signing_payload))
    sig_text = signature.get("signature")
    public_fingerprint = None
    valid = False
    verify_message = "signature not attempted"
    schema_rows_clear = _status_from(rows) in {"pass", "warn"}
    if schema_rows_clear and signature.get("signature_algorithm") == "rsa-pss-sha256" and isinstance(sig_text, str) and sig_text.strip():
        valid, verify_message, public_fingerprint = _rsa_pss_sha256_verify(public_key_path, _canonical_bytes(signing_payload), sig_text)
    rows.append({"name": "cryptographic-verification", "status": "pass" if valid else "blocked", "message": verify_message})
    if public_fingerprint:
        rows.append({"name": "public-key-fingerprint", "status": "pass" if signature.get("public_key_fingerprint") == public_fingerprint else "blocked", "message": public_fingerprint})
    trusted_values = _trusted_fingerprints(trusted_fingerprint)
    trusted = bool(valid and public_fingerprint and public_fingerprint.lower() in trusted_values)
    rows.append({"name": "trust-policy", "status": "pass" if trusted else "warn" if valid else "blocked", "message": "trusted fingerprint accepted" if trusted else "signature valid but fingerprint is not trusted" if valid else "signature did not verify"})
    status = _status_from(rows)
    result = _normalized_signature_trust_result(supplied=True, valid=valid, trusted=trusted, status=status, public_fingerprint=public_fingerprint, rows=rows)
    return {
        **result,
        "rows": rows,
        "message": "Detached signature verified and trusted." if trusted else "Detached signature verified but signer fingerprint is not trusted." if valid else "Detached signature verification failed.",
        "signing_payload": signing_payload,
        "signature_metadata": {k: v for k, v in signature.items() if k != "signature"},
    }



def build_signing_readiness_audit(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v29.1: audit whether release artifacts are stable enough for future signing."""
    package_name = package_name or _package_name()
    manifest = _canonical_manifest_payload(project_id=project_id, package_name=package_name, zip_path=zip_path)
    evidence = _canonical_evidence_payload(project_id=project_id, package_name=package_name, zip_path=zip_path)
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    readme = _read_text(ROOT_DIR / "README_NEXT_STEPS.md")
    rows = [
        {"name": "canonical-manifest-format", "status": "pass" if manifest.get("schema_version") else "blocked", "message": manifest.get("schema_version", "missing")},
        {"name": "canonical-evidence-schema", "status": "pass" if evidence.get("schema_version") else "blocked", "message": evidence.get("schema_version", "missing")},
        {"name": "package-hash-explicit", "status": "pass" if evidence.get("package_sha256") or not zip_path else "blocked", "message": str(evidence.get("package_sha256") or "zip not supplied")},
        {"name": "deterministic-manifest-hash", "status": "pass" if manifest.get("deterministic_manifest_hash") else "blocked", "message": str(manifest.get("deterministic_manifest_hash"))},
        {"name": "unsigned-status-clear", "status": "warn", "message": "Release artifacts are explicitly unsigned; no signature trust is claimed."},
        {"name": "reports-excluded", "status": str(privacy.get("status", "warn")), "message": "Source-only privacy scan protects reports/ and generated evidence from release zips."},
        {"name": "volatile-metadata-excluded-from-signing-inputs", "status": "pass", "message": ", ".join(manifest.get("volatile_metadata_paths", []))},
        {"name": "readme-unsigned-status", "status": "pass" if "unsigned" in readme.lower() and f"v{SELF_MAINTENANCE_VERSION}" in readme else "warn", "message": "README should document current unsigned signing-prep status."},
        {"name": "verification-commands-reproducible", "status": "pass" if evidence.get("verification_commands") else "blocked", "message": f"{len(evidence.get('verification_commands', []))} command(s)"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v29.1", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "manifest_hash": manifest.get("deterministic_manifest_hash"), "evidence_hash": evidence.get("evidence_hash"), "rows": rows, "message": "Signing readiness audit completed; artifacts remain unsigned."}
    if save: _write_json(SIGNING_READINESS_AUDIT, report)
    else: report["preview_only"] = True
    return report


