def build_release_signing_status(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, save: bool = True) -> dict[str, Any]:
    """v29.4/v30.4/v31.5: report explicit signing and trust status without pretending unsigned artifacts are trusted."""
    package_name = package_name or _package_name()
    package_sha = _sha256_file(Path(zip_path)) if zip_path and Path(zip_path).exists() else None
    readiness = build_signing_readiness_audit(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    detached = _verify_detached_signature(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint)
    rows = [
        {"name": "signing-ready", "status": "pass" if readiness.get("ok") else "blocked", "message": readiness.get("message", "")},
        {"name": "package-hash", "status": "pass" if package_sha or not zip_path else "blocked", "message": str(package_sha or "zip not supplied")},
        {"name": "signed", "status": "pass" if detached.get("signed") and detached.get("signature_trusted") else "warn", "message": f"signed={detached.get('signed')} trusted={detached.get('signature_trusted')}"},
        {"name": "safe-to-publish", "status": "pass" if detached.get("safe_to_publish") else "warn", "message": "Only trusted detached signatures can set safe_to_publish=true."},
    ] + list(detached.get("rows", []))
    status = _status_from(rows)
    report = {
        "version": SELF_MAINTENANCE_VERSION,
        "checked_at": _now(),
        "project_id": project_id,
        "stage": "v29.4",
        "status": status,
        "ok": _ok_from(status),
        "operational_ok": readiness.get("ok") and status != "blocked",
        "package_name": package_name,
        "zip_path": zip_path,
        "package_sha256": package_sha,
        "signed": bool(detached.get("signed")),
        "signing_status": detached.get("signing_status", "unsigned"),
        "signature_valid": bool(detached.get("signature_valid")),
        "signature_trusted": bool(detached.get("signature_trusted")),
        "safe_to_publish": bool(detached.get("safe_to_publish")),
        "trust_level": detached.get("trust_level", "unsigned"),
        "public_key_fingerprint": detached.get("public_key_fingerprint"),
        "signing_ready": readiness.get("ok"),
        "reason": detached.get("message", "No cryptographic signature supplied."),
        "signing_payload": detached.get("signing_payload"),
        "rows": rows,
        "message": "Release signing status reported with explicit trust fields.",
    }
    if save: _write_json(RELEASE_SIGNING_STATUS, report)
    else: report["preview_only"] = True
    return report


