def build_source_data_sanitizer(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v30.3: verify packaged source defaults are stripped of mutable runtime timestamps."""
    candidate_paths = [ROOT_DIR / "data" / "projects.json", ROOT_DIR / "data" / "settings.json", ROOT_DIR / "data" / "workspaces" / "projects.json", ROOT_DIR / "data" / "workspaces" / "active_project.json"]
    rows: list[dict[str, Any]] = []
    sanitized_preview: dict[str, Any] = {}
    for path in candidate_paths:
        rel = str(path.relative_to(ROOT_DIR)).replace(os.sep, "/")
        raw = _read_json(path, None)
        if raw is None:
            rows.append({"name": rel, "status": "warn", "message": "source data default missing or invalid JSON"})
            continue
        sanitized = _source_json_sanitized(raw)
        sanitized_preview[rel] = sanitized
        changed = sanitized != raw
        rows.append({"name": rel, "status": "pass", "message": "sanitizer would strip runtime fields" if changed else "already free of mutable runtime fields"})
    packaging = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    rows.append({"name": "zip-writer-sanitizer", "status": "pass" if "_sanitized_source_payload" in packaging else "blocked", "message": "release zip writer uses sanitized payloads for allowlisted JSON defaults"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v30.3", "status": status, "ok": _ok_from(status), "sanitized_preview_paths": sorted(sanitized_preview), "rows": rows, "message": "Source data sanitizer audit completed."}
    if save: _write_json(SOURCE_DATA_SANITIZER, report)
    else: report["preview_only"] = True
    return report


def build_signing_trust_model(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, save: bool = True) -> dict[str, Any]:
    """v30.4: split operational health from cryptographic trust."""
    signing = build_release_signing_status(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    trust_model = {
        "operational_ok": bool(signing.get("operational_ok")),
        "signed": bool(signing.get("signed")),
        "signature_valid": bool(signing.get("signature_valid")),
        "signature_trusted": bool(signing.get("signature_trusted")),
        "safe_to_publish": bool(signing.get("safe_to_publish")),
        "trust_level": signing.get("trust_level", "unsigned"),
    }
    rows = [
        {"name": "operational-ok-separate", "status": "pass" if "operational_ok" in signing else "blocked", "message": str(trust_model["operational_ok"])},
        {"name": "signature-trust-separate", "status": "pass" if "signature_trusted" in signing else "blocked", "message": str(trust_model["signature_trusted"])},
        {"name": "safe-to-publish-separate", "status": "pass" if "safe_to_publish" in signing else "blocked", "message": str(trust_model["safe_to_publish"])},
        {"name": "unsigned-not-trusted", "status": "pass" if not trust_model["signed"] and not trust_model["signature_trusted"] and not trust_model["safe_to_publish"] else "blocked", "message": "unsigned releases cannot be trusted or publish-approved"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v30.4", "status": status, "ok": _ok_from(status), "trust_model": trust_model, "rows": rows, "message": "Signing trust model split completed."}
    if save: _write_json(SIGNING_TRUST_MODEL, report)
    else: report["preview_only"] = True
    return report


def build_release_signing_tamper_drill(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v30.5: exercise signing validators against malformed/tampered fixtures."""
    manifest = _canonical_manifest_payload(project_id=project_id, package_name=package_name, zip_path=zip_path)
    evidence = _canonical_evidence_payload(project_id=project_id, package_name=package_name, zip_path=zip_path)
    drills: list[dict[str, Any]] = []
    bad_manifest = json.loads(json.dumps(manifest))
    if bad_manifest.get("files"):
        bad_manifest["files"] = list(reversed(bad_manifest["files"]))
    drills.append({"name": "manifest-unsorted-files", "expected": "blocked", "status": _status_from(_validate_canonical_manifest_payload(bad_manifest, zip_path=zip_path))})
    bad_hash_manifest = json.loads(json.dumps(manifest))
    bad_hash_manifest["deterministic_manifest_hash"] = "0" * 64
    drills.append({"name": "manifest-hash-tamper", "expected": "blocked", "status": _status_from(_validate_canonical_manifest_payload(bad_hash_manifest, zip_path=zip_path))})
    bad_evidence = json.loads(json.dumps(evidence))
    bad_evidence["signing_status"] = "signed"
    bad_evidence["signed"] = True
    drills.append({"name": "fake-signed-evidence", "expected": "blocked", "status": _status_from(_validate_canonical_evidence_payload(bad_evidence, zip_path=zip_path))})
    fake_sig = _verify_detached_signature(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=None, public_key_path=None)
    drills.append({"name": "unsigned-detached-missing", "expected": "warn", "status": _status_from(fake_sig.get("rows", []))})
    rows = [{"name": item["name"], "status": "pass" if item["status"] == item["expected"] else "blocked", "message": f"expected={item['expected']} observed={item['status']}"} for item in drills]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v30.5", "status": status, "ok": _ok_from(status), "drills": drills, "rows": rows, "message": "Release signing tamper drill completed."}
    if save: _write_json(RELEASE_SIGNING_TAMPER_DRILL, report)
    else: report["preview_only"] = True
    return report


