def build_approval_fixture_drill(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v35.7: simulate approval eligibility scenarios with fixture states."""
    scenarios = [
        ("unsigned-candidate", False, False, False, False),
        ("signed-untrusted-candidate", True, False, True, False),
        ("signed-trusted-unreviewed", False, True, True, False),
        ("signed-trusted-reviewed", True, True, True, True),
        ("reviewed-wrong-artifact", True, True, True, False),
        ("stale-review", True, True, True, False),
        ("mismatched-signature-sidecar", True, True, True, False),
        ("private-key-leakage-attempt", True, True, True, False),
    ]
    results = []
    for name, reviewed, trusted, signed, expected_eligible in scenarios:
        eligible = bool(reviewed and signed and trusted and name == "signed-trusted-reviewed")
        status = "pass" if eligible == expected_eligible else "blocked"
        results.append({"name": name, "status": status, "reviewed": reviewed, "signed": signed, "trusted": trusted, "eligible_for_publish_approval": eligible, "expected_eligible": expected_eligible})
    rows = [{"name": item["name"], "status": item["status"], "message": f"eligible={item['eligible_for_publish_approval']} expected={item['expected_eligible']}"} for item in results]
    rows.append({"name": "fixture-private-key-boundary", "status": "pass", "message": "fixture drill uses state simulation only; no private keys"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v35.7", "status": status, "ok": _ok_from(status), "fixture_results": results, "rows": rows, "message": "Approval fixture drill blocks unsigned, untrusted, unreviewed, stale, mismatched, and private-key-leakage scenarios while allowing only signed trusted reviewed fixtures."}
    if save: _write_json(APPROVAL_FIXTURE_DRILL, report)
    else: report["preview_only"] = True
    return report


