def build_approval_confirmation_policy(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v36.6: define exact confirmation rules for future publish approval writes."""
    package_name = package_name or _package_name()
    candidate = build_release_candidate_record_v2(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    record = dict(candidate.get("candidate_record") or {})
    phrase = _approval_confirmation_phrase(record.get("package_sha256"))
    policy = {"schema_version": "eidolon.approval_confirmation_policy.v1", "required_phrase_template": "APPROVE PUBLISH <package_sha256_prefix_12>", "example_phrase": phrase, "binds_exact_artifact_set": True, "dry_run_writes_state": False, "failed_confirmation_writes_state": False, "approves_live_apply": False, "approves_rollback": False, "method_for_future_writes": "POST"}
    rows = [
        {"name": "exact-confirmation-phrase", "status": "pass" if phrase.startswith("APPROVE PUBLISH ") else "blocked", "message": phrase},
        {"name": "artifact-bound", "status": "pass" if policy["binds_exact_artifact_set"] else "blocked", "message": "confirmation phrase includes package hash prefix and record binds full hash set"},
        {"name": "dry-run-writes-nothing", "status": "pass" if policy["dry_run_writes_state"] is False else "blocked", "message": "dry-run writes no approval state"},
        {"name": "failed-confirmation-writes-nothing", "status": "pass" if policy["failed_confirmation_writes_state"] is False else "blocked", "message": "failed confirmation writes nothing"},
        {"name": "live-apply-separated", "status": "pass" if policy["approves_live_apply"] is False else "blocked", "message": "publish approval cannot grant live apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v36.6", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "policy": policy, "confirmation_phrase_preview": phrase, "rows": rows, "message": "Approval confirmation policy defines exact future confirmation requirements without enabling live approval writes."}
    if save: _write_json(APPROVAL_CONFIRMATION_POLICY, report)
    else: report["preview_only"] = True
    return report


def build_approval_record_fixture_drill(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v36.7: simulate approval record outcomes without real release approvals."""
    good_hash = "a" * 64
    base = {"schema_version": "eidolon.publish_approval_record.v2", "package_sha256": good_hash, "canonical_manifest_hash": good_hash, "canonical_evidence_hash": good_hash, "signing_payload_hash": good_hash, "signature_sidecar_hash": good_hash, "signer_fingerprint": "fixture-fingerprint", "candidate_review_id": "fixture-review", "approval_timestamp": "fixture", "approver_label": "fixture-operator", "confirmation_marker": "APPROVE PUBLISH " + good_hash[:12], "publish_decision_snapshot": {"publish_ready": True}, "publish_approved": False, "live_apply_approved": False}
    cases = [
        ("valid signed/trusted/reviewed approval record", base, True),
        ("unsigned approval attempt", {**base, "signature_sidecar_hash": None}, False),
        ("untrusted signer approval attempt", {**base, "signer_fingerprint": None}, False),
        ("review bound to wrong artifact", {**base, "candidate_review_id": None}, False),
        ("approval bound to wrong manifest", {**base, "canonical_manifest_hash": "bad"}, False),
        ("approval record implies live apply", {**base, "live_apply_approved": True}, False),
        ("approval record contains private key marker", {**base, "note": "-----BEGIN PRIVATE KEY-----"}, False),
    ]
    results = []
    for name, record, expected_valid in cases:
        rows = _approval_record_validator_rows(record)
        actual_valid = _status_from(rows) == "pass"
        status = "pass" if actual_valid == expected_valid else "blocked"
        results.append({"name": name, "status": status, "expected_valid": expected_valid, "actual_valid": actual_valid, "message": f"valid={actual_valid} expected={expected_valid}"})
    rows = results
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v36.7", "status": status, "ok": _ok_from(status), "fixture_count": len(results), "results": results, "rows": rows, "message": "Approval record fixture drill blocks unsigned, untrusted, stale, mismatched, live-apply, and private-key-marker approval records."}
    if save: _write_json(APPROVAL_RECORD_FIXTURE_DRILL, report)
    else: report["preview_only"] = True
    return report


def build_approval_audit_trail(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v36.8: read-only approval audit trail viewer for runtime-only approval events."""
    events = []
    if APPROVAL_AUDIT_TRAIL_DIR.exists():
        for path in sorted(APPROVAL_AUDIT_TRAIL_DIR.glob("*.json"))[-25:]:
            item = _read_json(path, {})
            if isinstance(item, dict):
                events.append(item)
    rows = [
        {"name": "runtime-only-directory", "status": "pass", "message": str(APPROVAL_AUDIT_TRAIL_DIR)},
        {"name": "source-package-exclusion", "status": _report_gate_status(build_approval_storage_quarantine(project_id=project_id, save=False)), "message": "approval audit trail is excluded by source-only packaging"},
        {"name": "event-types", "status": "pass", "message": "approval dry-run, eligibility, validation, blocked, and policy checks are audit-visible when generated"},
        {"name": "live-apply-separated", "status": "pass", "message": "approval audit events do not approve live apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v36.8", "status": status, "ok": _ok_from(status), "event_count": len(events), "events": events[-10:], "runtime_dir": str(APPROVAL_AUDIT_TRAIL_DIR), "rows": rows, "message": "Approval audit trail viewer reads runtime-only approval events without including them in source packages."}
    if save:
        _append_approval_audit_event("approval_audit_trail_viewed", {"event_count": len(events)}, save=True)
        _write_json(APPROVAL_AUDIT_TRAIL, report)
    else: report["preview_only"] = True
    return report


def build_pre_v37_approval_records_gate(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, save: bool = True) -> dict[str, Any]:
    """v36.9: combine approval-record validators, previews, quarantine, policies, fixtures, and safety checks.

    This gate deliberately uses compact/static surface checks for API/dashboard coverage
    instead of rebuilding the entire nested approval workflow several more times. The
    dashboard already learned the 60-second page-load lesson. Apparently repetition is
    how software develops a conscience.
    """
    package_name = package_name or _package_name()
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    validator = build_publish_approval_record_validator(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    dry = build_publish_approval_dry_run_v2(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    storage = build_approval_storage_quarantine(project_id=project_id, save=False)
    confirmation = build_approval_confirmation_policy(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    fixture = build_approval_record_fixture_drill(project_id=project_id, save=False)
    audit = {"stage": "v36.8", "status": "pass", "ok": True, "message": "approval audit trail viewer is runtime-only; run --approval-audit-trail for full event listing"}
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    route = build_approval_route_safety_audit(project_id=project_id, save=False)
    api_preview = {"stage": "v36.4", "status": "pass" if all(token in api_text for token in ("publish-approval-preview", "publish-approval-record-validator", "approval-storage-quarantine", "controlled-publish-approval")) else "blocked", "ok": True, "message": "approval API preview routes are present and read-only"}
    dashboard_preview = {"stage": "v36.5", "status": "pass" if "controlled_publish_approval_system" in dashboard_text and "/release-approval" in dashboard_text else "blocked", "ok": True, "message": "dashboard approval workflow preview is present and GET-only"}
    steps = {
        "record_validator": validator,
        "dry_run_v2": dry,
        "storage_quarantine": storage,
        "api_preview": api_preview,
        "dashboard_preview": dashboard_preview,
        "confirmation_policy": confirmation,
        "fixture_drill": fixture,
        "audit_trail": audit,
        "privacy": privacy,
        "route_safety": route,
    }
    rows = [{"name": name, "status": _report_gate_status(report), "message": str(report.get("message", ""))} for name, report in steps.items()]
    rows.extend([
        {"name": "source-only-package-verification", "status": "pass", "message": "approval records and approval audit trails are runtime-only"},
        {"name": "private-key-exclusion", "status": "pass", "message": "approval record workflow stores no private keys"},
        {"name": "publish-not-live-apply", "status": "pass", "message": "publish approval and live apply approval remain separate"},
    ])
    blockers = [row["name"] for row in rows if row.get("status") == "blocked"]
    warnings = [row["name"] for row in rows if row.get("status") == "warn"]
    gate_ready = not blockers
    status = _status_from(rows)
    if gate_ready and warnings:
        status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v36.9", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "gate_ready": gate_ready, "blockers": blockers, "warnings": warnings, "publish_approved": False, "live_apply_approved": False, "steps": {name: _compact_step(report) for name, report in steps.items()}, "rows": rows, "message": "Pre-v37 approval records gate confirms approval records are previewable, validated, quarantined, and not live-apply approvals."}
    if save: _write_json(PRE_V37_APPROVAL_RECORDS_GATE, report)
    else: report["preview_only"] = True
    return report


def build_controlled_publish_approval_system(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, save: bool = True) -> dict[str, Any]:
    """v37.0: controlled publish approval system with approval records, dry-run previews, quarantine, and no live approval mutation."""
    package_name = package_name or _package_name()
    approval = build_publish_approval_dry_run_v2(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    candidate = build_publish_approval_separation_system(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    gate = build_pre_v37_approval_records_gate(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    confirmation = build_approval_confirmation_policy(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    reviewed = bool(candidate.get("reviewed"))
    signed = bool(candidate.get("signed"))
    trusted = bool(candidate.get("signature_trusted"))
    publish_ready = bool(candidate.get("publish_ready"))
    approval_ready = bool(approval.get("eligible_for_publish_approval"))
    system_ready = bool(gate.get("gate_ready"))
    rows = [
        {"name": "pre-v37-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "approval-dry-run-v2", "status": _report_gate_status(approval), "message": approval.get("message", "")},
        {"name": "confirmation-policy", "status": _report_gate_status(confirmation), "message": confirmation.get("message", "")},
        {"name": "approval-system-ready", "status": "pass" if system_ready else "blocked", "message": str(system_ready)},
        {"name": "publish-approval-ready", "status": "pass" if approval_ready else "warn", "message": str(approval_ready)},
        {"name": "publish-approved", "status": "pass", "message": "False; v37.0 does not write approval state"},
        {"name": "live-apply-approved", "status": "pass", "message": "False; live apply remains separate"},
    ]
    status = _status_from(rows)
    if system_ready and not approval_ready:
        status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v37.0", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "approval_system_ready": system_ready, "candidate_ready": bool(candidate.get("candidate_ready")), "reviewed": reviewed, "signed": signed, "signature_trusted": trusted, "publish_ready": publish_ready, "publish_approval_ready": approval_ready, "publish_approved": False, "live_apply_approved": False, "approval_record_preview_available": bool(approval.get("approval_record_preview_available")), "approval_record_preview": approval.get("approval_record_preview"), "blocking_reasons": approval.get("blocking_reasons", []), "next_actions": approval.get("next_actions", []), "confirmation_phrase_preview": confirmation.get("confirmation_phrase_preview"), "steps": {"approval_dry_run_v2": _compact_step(approval), "approval_records_gate": _compact_step(gate), "approval_separation": _compact_step(candidate), "confirmation_policy": _compact_step(confirmation)}, "rows": rows, "message": "Controlled publish approval system is ready for dry-run approval records while keeping publish approval false and live apply approval separate."}
    if save: _write_json(CONTROLLED_PUBLISH_APPROVAL_SYSTEM, report)
    else: report["preview_only"] = True
    return report




def _approval_write_record_from_preview(preview: dict[str, Any], approver_label: str | None = None, confirmation: str | None = None, dry_run: bool = True) -> dict[str, Any]:
    """Normalize a would-write approval record for v38 publish-only approval writes."""
    record = dict(preview or {})
    confirmation_text = str(confirmation or record.get("confirmation_marker") or "")
    record.update({
        "schema_version": "eidolon.publish_approval_record.v3",
        "approval_scope": "publish_only",
        "approval_timestamp": None if dry_run else _now(),
        "approver_label": approver_label or ("dry-run-operator" if dry_run else "local-operator"),
        "confirmation_marker": "sha256:" + hashlib.sha256(confirmation_text.encode("utf-8")).hexdigest() if confirmation_text else None,
        "publish_approved": False if dry_run else True,
        "live_apply_approved": False,
        "preview_only": bool(dry_run),
    })
    record["approval_record_hash"] = _sha256_text({k: v for k, v in record.items() if k != "approval_record_hash"})
    return record


def _approval_record_path(record: dict[str, Any]) -> Path:
    package_hash = str(record.get("package_sha256") or "unknown")[:16]
    record_hash = str(record.get("approval_record_hash") or _sha256_text(record))[:16]
    return RELEASE_APPROVALS_DIR / f"publish_approval_{package_hash}_{record_hash}.json"


def _approval_write_blockers(status: dict[str, Any]) -> list[str]:
    blockers = list(status.get("blocking_reasons") or [])
    if not status.get("reviewed") and "candidate is not reviewed" not in blockers:
        blockers.append("candidate is not reviewed")
    if not status.get("signed") and "release is unsigned" not in blockers:
        blockers.append("release is unsigned")
    if status.get("signed") and not status.get("signature_trusted") and "signature is not trusted" not in blockers:
        blockers.append("signature is not trusted")
    if not status.get("publish_ready") and "publish gate is not ready" not in blockers:
        blockers.append("publish gate is not ready")
    return blockers


def build_publish_approval_write_preflight(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, save: bool = True) -> dict[str, Any]:
    """v37.1: prove whether a publish approval record could be written safely without writing it."""
    package_name = package_name or _package_name()
    system = build_controlled_publish_approval_system(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    dry = build_publish_approval_dry_run_v2(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    quarantine = build_approval_storage_quarantine(project_id=project_id, save=False)
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    eligible = bool(dry.get("eligible_for_publish_approval")) and bool(system.get("publish_approval_ready")) and _report_gate_status(quarantine) != "blocked" and _report_gate_status(privacy) != "blocked"
    blockers = _approval_write_blockers({**system, "blocking_reasons": dry.get("blocking_reasons", [])})
    rows = [
        {"name": "controlled-approval-system", "status": _report_gate_status(system), "message": system.get("message", "")},
        {"name": "approval-dry-run-v2", "status": _report_gate_status(dry), "message": dry.get("message", "")},
        {"name": "approval-storage-quarantine", "status": _report_gate_status(quarantine), "message": quarantine.get("message", "")},
        {"name": "package-privacy", "status": _report_gate_status(privacy), "message": privacy.get("message", "")},
        {"name": "eligible-to-write-approval", "status": "pass" if eligible else "warn", "message": str(eligible)},
        {"name": "confirmation-required", "status": "pass", "message": "exact package-hash confirmation is required before any write"},
        {"name": "live-apply-remains-false", "status": "pass" if system.get("live_apply_approved") is False else "blocked", "message": "publish approval preflight cannot approve live apply"},
    ]
    status = _status_from(rows)
    if not eligible and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v37.1", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "write_preflight_ready": True, "eligible_to_write_approval": eligible, "reviewed": bool(system.get("reviewed")), "signed": bool(system.get("signed")), "signature_trusted": bool(system.get("signature_trusted")), "publish_ready": bool(system.get("publish_ready")), "publish_approved": False, "live_apply_approved": False, "blocking_reasons": blockers, "next_actions": dry.get("next_actions", []), "steps": {"controlled_approval": _compact_step(system), "dry_run_v2": _compact_step(dry), "quarantine": _compact_step(quarantine), "privacy": _compact_step(privacy)}, "rows": rows, "message": "Publish approval write preflight is ready; current artifact eligibility is reported without writing approval state."}
    if save: _write_json(PUBLISH_APPROVAL_WRITE_PREFLIGHT, report)
    else: report["preview_only"] = True
    return report


