    schema = {"schema_version": "eidolon.publish_approval_record.v3", "required_fields": ["schema_version", "artifact_binding", "candidate_review_binding", "signature_binding", "decision_snapshot", "confirmation_marker", "approval_scope", "live_apply_approved", "created_at", "created_by_label"], "approval_scope_allowed": ["publish_only"], "live_apply_approved_required_value": False, "private_key_material_allowed": False}
