def build_publish_approval_confirmation_validator(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, confirmation: str | None = None, save: bool = True) -> dict[str, Any]:
    """v37.3: validate exact operator confirmation against the current package hash prefix without writing state."""
    package_name = package_name or _package_name()
    candidate = build_release_candidate_record_v2(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    record = dict(candidate.get("candidate_record") or {})
    expected = _approval_confirmation_phrase(record.get("package_sha256"))
    supplied = str(confirmation or "")
    valid = supplied == expected
    rows = [
        {"name": "expected-phrase", "status": "pass" if expected.startswith("APPROVE PUBLISH ") else "blocked", "message": expected},
        {"name": "confirmation-supplied", "status": "pass" if supplied else "warn", "message": "supplied" if supplied else "missing"},
        {"name": "confirmation-matches", "status": "pass" if valid else "warn", "message": "matches current package hash prefix" if valid else "missing or mismatched confirmation writes nothing"},
        {"name": "artifact-bound", "status": "pass" if _is_hex_sha256(record.get("package_sha256")) else "blocked", "message": str(record.get("package_sha256"))},
        {"name": "dry-run-writes-nothing", "status": "pass", "message": "validator never writes approval state"},
    ]
    status = _status_from(rows)
    if not valid and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v37.3", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "expected_confirmation": expected, "confirmation_supplied": bool(supplied), "confirmation_valid": valid, "would_write_approval": False, "publish_approved": False, "live_apply_approved": False, "rows": rows, "message": "Publish approval confirmation validator checked the exact phrase without writing approval state."}
    if save: _write_json(PUBLISH_APPROVAL_CONFIRMATION_VALIDATOR, report)
    else: report["preview_only"] = True
    return report


