def build_write_publish_approval(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, confirmation: str | None = None, approver_label: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, dry_run: bool = True, save: bool = True) -> dict[str, Any]:
    """v37.6: guarded runtime publish approval write. Writes only approval records when eligible and confirmed."""
    package_name = package_name or _package_name()
    preflight = build_publish_approval_write_preflight(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    confirm = build_publish_approval_confirmation_validator(project_id=project_id, package_name=package_name, zip_path=zip_path, confirmation=confirmation, save=False)
    preview = _approval_record_preview(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint)
    eligible = bool(preflight.get("eligible_to_write_approval")) and bool(confirm.get("confirmation_valid"))
    record = _approval_write_record_from_preview(preview, approver_label=approver_label, confirmation=confirmation, dry_run=not eligible or dry_run)
    record_path = _approval_record_path(record)
    wrote = False
    blocked = [] if eligible else list(preflight.get("blocking_reasons", []))
    if not confirm.get("confirmation_valid"):
        blocked.append("confirmation phrase is missing or does not match current artifact")
    rows = [
        {"name": "write-preflight", "status": _report_gate_status(preflight), "message": preflight.get("message", "")},
        {"name": "confirmation-valid", "status": "pass" if confirm.get("confirmation_valid") else "warn", "message": "valid" if confirm.get("confirmation_valid") else "invalid or missing"},
        {"name": "eligible", "status": "pass" if eligible else "warn", "message": str(eligible)},
        {"name": "dry-run", "status": "pass", "message": str(bool(dry_run))},
        {"name": "write-scope", "status": "pass" if record.get("approval_scope") == "publish_only" and record.get("live_apply_approved") is False else "blocked", "message": "publish_only; live_apply_approved=false"},
    ]
    if eligible and not dry_run:
        RELEASE_APPROVALS_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic(record_path, json.dumps(record, indent=2, default=str), encoding="utf-8")
        wrote = True
        _append_approval_audit_event("publish_approval_record_written", {"record_path": str(record_path), "package_name": package_name}, save=True)
        rows.append({"name": "approval-record-written", "status": "pass", "message": str(record_path)})
    else:
        rows.append({"name": "approval-record-written", "status": "pass", "message": "False; dry-run or blocked eligibility wrote nothing"})
    status = _status_from(rows)
    if not eligible and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v37.6", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "approval_write_ready": True, "eligible_to_write_approval": eligible, "would_write_approval": bool(eligible and dry_run), "publish_approved": bool(wrote), "live_apply_approved": False, "dry_run": bool(dry_run), "approval_record_path": str(record_path) if wrote else None, "approval_record_hash": record.get("approval_record_hash"), "approval_record_preview": record if not wrote else None, "blocking_reasons": blocked, "steps": {"preflight": _compact_step(preflight), "confirmation": _compact_step(confirm)}, "rows": rows, "message": "Publish approval write completed safely; only eligible non-dry-run requests write a publish-only approval record."}
    if save: _write_json(WRITE_PUBLISH_APPROVAL, report)
    else: report["preview_only"] = True
    return report


