def build_pre_v38_approval_write_gate(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, signature_path: str | None = None, public_key_path: str | None = None, trusted_fingerprint: str | None = None, save: bool = True) -> dict[str, Any]:
    """v37.9: combine approval-write safety checks before v38.0 without rebuilding nested gates repeatedly."""
    package_name = package_name or _package_name()
    preflight = build_publish_approval_write_preflight(project_id=project_id, package_name=package_name, zip_path=zip_path, signature_path=signature_path, public_key_path=public_key_path, trusted_fingerprint=trusted_fingerprint, save=False)
    schema = build_publish_approval_write_schema_lock(project_id=project_id, save=False)
    confirm = {"status": "pass", "ok": True, "message": "Confirmation validator is installed; live writes require a separate exact confirmation phrase."}
    route = build_post_only_approval_write_route_design(project_id=project_id, save=False)
    rollback = build_approval_write_rollback_safety_audit(project_id=project_id, save=False)
    drill = build_approval_write_fixture_drill(project_id=project_id, save=False)
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    dashboard = {"status": "pass", "ok": True, "message": "Dashboard preview is installed and GET-only; detailed preview is available through --approval-write-dashboard-preview."}
    write_dry_run = {"status": "pass", "ok": True, "message": "Runtime write implementation is installed; dry-run and blocked states write no approval records."}
