def build_publish_approval_record_reader(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v38.1: read existing publish approval records safely without mutating them."""
    records = _read_approval_record_summaries()
    malformed = [row for row in records if not row.get("valid")]
    live_apply = [row for row in records if row.get("live_apply_approved")]
    rows = [
        {"name": "approval-storage-directory", "status": "pass", "message": _report_path(str(RELEASE_APPROVALS_DIR))},
        {"name": "approval-records-readable", "status": "pass" if not malformed else "blocked", "message": f"{len(records)} records; {len(malformed)} malformed"},
        {"name": "live-apply-separated", "status": "pass" if not live_apply else "blocked", "message": "no approval record grants live apply" if not live_apply else f"{len(live_apply)} records incorrectly imply live apply"},
        {"name": "read-only", "status": "pass", "message": "reader performs no writes or deletions"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v38.1", "status": status, "ok": _ok_from(status), "approval_record_count": len(records), "valid_record_count": len([r for r in records if r.get("valid")]), "malformed_record_count": len(malformed), "records": records, "publish_approved": any(r.get("publish_approved") and r.get("valid") and not r.get("live_apply_approved") for r in records), "live_apply_approved": False, "rows": rows, "message": "Publish approval record reader inspected the runtime-only approval ledger without mutating approval state."}
    if save: _write_json(PUBLISH_APPROVAL_RECORD_READER, report)
    else: report["preview_only"] = True
    return report


def build_approval_artifact_revalidation(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v38.2: revalidate persisted approval records against the current artifact binding."""
    package_name = package_name or _package_name()
    binding = _current_artifact_binding(project_id=project_id, package_name=package_name, zip_path=zip_path)
    reader = build_publish_approval_record_reader(project_id=project_id, save=False)
    records = list(reader.get("records", []))
    matching = [r for r in records if r.get("valid") and _approval_record_matches_binding(r, binding)]
    stale = [r for r in records if r.get("valid") and not _approval_record_matches_binding(r, binding)]
    live_apply = [r for r in matching if r.get("live_apply_approved")]
    rows = [
        {"name": "current-artifact-binding", "status": "pass" if binding.get("package_sha256") else "warn", "message": str(binding.get("package_sha256") or "package hash unavailable")},
        {"name": "matching-approval-records", "status": "pass" if matching else "warn", "message": f"{len(matching)} matching records"},
        {"name": "stale-approval-records", "status": "pass" if not stale else "warn", "message": f"{len(stale)} stale records"},
        {"name": "publish-only-scope", "status": "pass" if not live_apply else "blocked", "message": "matching approvals do not grant live apply"},
        {"name": "candidate-review-binding", "status": "pass" if all(r.get("candidate_review_id") for r in matching) or not matching else "blocked", "message": "matching approvals bind to candidate review IDs when present"},
    ]
    status = _status_from(rows)
    if not matching and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v38.2", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "artifact_binding": binding, "matching_approval_count": len(matching), "stale_approval_count": len(stale), "matching_approval_records": matching[:10], "stale_approval_records": stale[:10], "matching_approval_found": bool(matching), "publish_approved": bool(matching), "live_apply_approved": False, "rows": rows, "message": "Approval artifact revalidation compared runtime approval records to the current artifact hash set."}
    if save: _write_json(APPROVAL_ARTIFACT_REVALIDATION, report)
    else: report["preview_only"] = True
    return report


def build_approval_record_conflict_detector(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v38.3: detect conflicting or malformed approval records."""
    reader = build_publish_approval_record_reader(project_id=project_id, save=False)
    records = list(reader.get("records", []))
    ids: dict[str, int] = {}
    hash_keys: dict[str, int] = {}
    conflicts: list[dict[str, Any]] = []
    for record in records:
        rid = str(record.get("approval_id") or "")
        ids[rid] = ids.get(rid, 0) + 1
        if record.get("valid"):
            key = "|".join(str(record.get(k) or "") for k in ("package_sha256", "canonical_manifest_hash", "canonical_evidence_hash", "signing_payload_hash"))
            hash_keys[key] = hash_keys.get(key, 0) + 1
        if record.get("live_apply_approved"):
            conflicts.append({"type": "live_apply_implied", "approval_id": rid, "message": "approval record incorrectly grants live apply"})
        if not record.get("valid"):
            conflicts.append({"type": "malformed", "approval_id": rid, "message": record.get("error") or "record failed validation"})
    duplicate_ids = [rid for rid, count in ids.items() if rid and count > 1]
    for rid in duplicate_ids:
        conflicts.append({"type": "duplicate_approval_id", "approval_id": rid, "message": "multiple records share an approval ID"})
    unique_artifact_sets = len(hash_keys)
    if unique_artifact_sets > 1:
        conflicts.append({"type": "multiple_artifact_sets", "message": f"approval ledger contains {unique_artifact_sets} distinct artifact bindings"})
    rows = [
        {"name": "malformed-records", "status": "pass" if not [c for c in conflicts if c["type"] == "malformed"] else "blocked", "message": str(len([c for c in conflicts if c["type"] == "malformed"]))},
        {"name": "duplicate-approval-ids", "status": "pass" if not duplicate_ids else "blocked", "message": ", ".join(duplicate_ids) if duplicate_ids else "none"},
        {"name": "artifact-binding-conflicts", "status": "pass" if unique_artifact_sets <= 1 else "warn", "message": f"{unique_artifact_sets} distinct artifact bindings"},
        {"name": "live-apply-boundary", "status": "pass" if not [c for c in conflicts if c["type"] == "live_apply_implied"] else "blocked", "message": "approval records cannot imply live apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v38.3", "status": status, "ok": _ok_from(status), "approval_record_count": len(records), "conflict_count": len(conflicts), "conflicts": conflicts, "publish_approved": any(r.get("publish_approved") and r.get("valid") for r in records) and not conflicts, "live_apply_approved": False, "rows": rows, "message": "Approval record conflict detector checked duplicate IDs, malformed records, conflicting artifact sets, and live-apply leakage."}
    if save: _write_json(APPROVAL_RECORD_CONFLICT_DETECTOR, report)
    else: report["preview_only"] = True
    return report


def build_approval_status_viewer(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v38.4: read-only dashboard/API approval ledger viewer."""
    package_name = package_name or _package_name()
    reader = build_publish_approval_record_reader(project_id=project_id, save=False)
