def build_approval_revocation_dry_run(project_id: str = "eidolon", approval_record_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v38.6: preview approval revocation without writing a revocation record."""
    reader = build_publish_approval_record_reader(project_id=project_id, save=False)
    records = list(reader.get("records", []))
    target = None
    if approval_record_id:
        target = next((record for record in records if str(record.get("approval_id")) == str(approval_record_id) or str(record.get("approval_record_hash")) == str(approval_record_id)), None)
    elif records:
        target = records[0]
    eligible = bool(target and target.get("valid") and target.get("publish_approved") and not target.get("live_apply_approved"))
    target_hash = target.get("approval_record_hash") if isinstance(target, dict) else None
    phrase = f"REVOKE PUBLISH {str(target_hash or 'APPROVAL')[:12]}"
    blockers: list[str] = []
    if not target: blockers.append("no target approval record found")
    elif not target.get("valid"): blockers.append("target approval record is malformed")
    elif target.get("live_apply_approved"): blockers.append("target approval record incorrectly implies live apply")
    elif not target.get("publish_approved"): blockers.append("target approval record is not an active publish approval")
    rows = [
        {"name": "target-record-found", "status": "pass" if target else "warn", "message": str(approval_record_id or "latest available")},
        {"name": "eligible-to-revoke", "status": "pass" if eligible else "warn", "message": str(eligible)},
        {"name": "would-write-revocation", "status": "pass", "message": "False; dry-run writes no revocation state"},
        {"name": "rollback-separated", "status": "pass", "message": "revocation preview does not approve rollback"},
        {"name": "live-apply-separated", "status": "pass", "message": "revocation preview does not approve live apply"},
    ]
    status = _status_from(rows)
    if not eligible and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v38.6", "status": status, "ok": _ok_from(status), "approval_record_id": approval_record_id, "target_approval_record_hash": target_hash, "eligible_to_revoke": eligible, "would_write_revocation": False, "required_confirmation_phrase": phrase, "blocking_reasons": blockers, "revoked": False, "rollback_approved": False, "live_apply_approved": False, "rows": rows, "message": "Approval revocation dry-run targets an exact approval record and writes no revocation or rollback state."}
    if save: _write_json(APPROVAL_REVOCATION_DRY_RUN, report)
    else: report["preview_only"] = True
    return report


