def build_pre_v39_approval_lifecycle_gate(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v38.9: combine approval lifecycle checks before v39.0."""
    package_name = package_name or _package_name()
    reader = build_publish_approval_record_reader(project_id=project_id, save=False)
    revalidation = build_approval_artifact_revalidation(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    conflicts = build_approval_record_conflict_detector(project_id=project_id, save=False)
    viewer = build_approval_status_viewer(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    policy = build_approval_revocation_policy(project_id=project_id, save=False)
    revocation = build_approval_revocation_dry_run(project_id=project_id, save=False)
    audit = build_approval_lifecycle_audit(project_id=project_id, save=False)
    drill = build_approval_lifecycle_fixture_drill(project_id=project_id, save=False)
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    route = build_api_route_safety_audit(project_id=project_id, save=False)
    checks = {"record_reader": reader, "artifact_revalidation": revalidation, "conflict_detector": conflicts, "status_viewer": viewer, "revocation_policy": policy, "revocation_dry_run": revocation, "lifecycle_audit": audit, "fixture_drill": drill, "privacy_scan": privacy, "route_safety": route}
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    rows.append({"name": "source-only-approval-exclusion", "status": "pass", "message": "approval records, revocations, and lifecycle audit logs remain runtime-only"})
    rows.append({"name": "private-key-exclusion", "status": "pass", "message": "no private keys are generated, requested, stored, or packaged"})
    status = _status_from(rows)
    if status == "blocked": ok = False
    else:
        ok = True
        if not bool(revalidation.get("matching_approval_found")) and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v38.9", "status": status, "ok": ok, "package_name": package_name, "zip_path": zip_path, "gate_ready": True, "matching_approval_found": bool(revalidation.get("matching_approval_found")), "publish_approved": bool(viewer.get("publish_approved")), "revocation_ready": True, "revoked": False, "live_apply_approved": False, "steps": {k: _compact_step(v) for k, v in checks.items()}, "rows": rows, "message": "Pre-v39 approval lifecycle gate combines record reading, artifact revalidation, conflict detection, viewer, revocation policy/dry-run, audit, fixtures, privacy, and route safety."}
    if save: _write_json(PRE_V39_APPROVAL_LIFECYCLE_GATE, report)
    else: report["preview_only"] = True
    return report


def build_publish_approval_lifecycle_system(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None, save: bool = True) -> dict[str, Any]:
    """v39.0: publish approval lifecycle system for approval ledger inspection and revocation preview."""
    package_name = package_name or _package_name()
    gate = build_pre_v39_approval_lifecycle_gate(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    viewer = build_approval_status_viewer(project_id=project_id, package_name=package_name, zip_path=zip_path, save=False)
    revocation = build_approval_revocation_dry_run(project_id=project_id, save=False)
    matching = bool(gate.get("matching_approval_found"))
    publish_approved = bool(gate.get("publish_approved")) and not bool(gate.get("revoked"))
    rows = [
        {"name": "pre-v39-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "approval-status-viewer", "status": _report_gate_status(viewer), "message": viewer.get("message", "")},
        {"name": "revocation-preview", "status": _report_gate_status(revocation), "message": revocation.get("message", "")},
        {"name": "approval-lifecycle-ready", "status": "pass", "message": "approval ledger read/revalidate/conflict/revocation-preview system is installed"},
        {"name": "live-apply-approved", "status": "pass", "message": "False; lifecycle system never approves live apply"},
    ]
    status = _status_from(rows)
    if not matching and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v39.0", "status": status, "ok": _ok_from(status), "package_name": package_name, "zip_path": zip_path, "approval_lifecycle_ready": True, "matching_approval_found": matching, "approval_record_count": viewer.get("matching_approval_count", 0), "stale_approval_count": viewer.get("stale_approval_count", 0), "conflict_count": viewer.get("conflict_count", 0), "publish_approved": publish_approved, "revocation_ready": True, "revoked": False, "live_apply_approved": False, "steps": {"pre_v39_gate": _compact_step(gate), "approval_status_viewer": _compact_step(viewer), "revocation_dry_run": _compact_step(revocation)}, "rows": rows, "message": "Publish approval lifecycle system is ready; current artifact has no matching active approval unless a runtime approval record matches the exact artifact set."}
    if save: _write_json(PUBLISH_APPROVAL_LIFECYCLE_SYSTEM, report)
    else: report["preview_only"] = True
    return report




def _build_self_maintenance_approval_revocations_dependencies() -> _SelfMaintenanceApprovalRevocationsSymbolDependencies:
    return _SelfMaintenanceApprovalRevocationsSymbolDependencies(
        APPROVAL_REVOCATIONS_DIR=APPROVAL_REVOCATIONS_DIR,
        ROOT_DIR=ROOT_DIR,
        _is_hex_sha256=_is_hex_sha256,
        _report_path=_report_path,
        _runtime_private_marker_scan=_runtime_private_marker_scan,
        _sha256_text=_sha256_text,
        _status_from=_status_from,
    )

def _revocation_record_files() -> list[Path]:
    return _revocation_record_files_implementation(_deps=_build_self_maintenance_approval_revocations_dependencies())



def _read_revocation_payload(path: Path) -> tuple[dict[str, Any] | None, str | None]:
    return _read_revocation_payload_implementation(path, _deps=_build_self_maintenance_approval_revocations_dependencies())



def _revocation_record_id(record: dict[str, Any], fallback: str='') -> str:
    return _revocation_record_id_implementation(record, fallback, _deps=_build_self_maintenance_approval_revocations_dependencies())



def _approval_target_matches(record: dict[str, Any], approval: dict[str, Any]) -> bool:
    target_hash = str(record.get("target_approval_record_hash") or "")
    approval_hash = str(approval.get("approval_record_hash") or "")
    target_id = str(record.get("target_approval_record_id") or "")
    approval_id = str(approval.get("approval_id") or "")
    return bool((target_hash and target_hash == approval_hash) or (target_id and target_id == approval_id))


def _revocation_validator_rows(record: dict[str, Any]) -> list[dict[str, Any]]:
    return _revocation_validator_rows_implementation(record, _deps=_build_self_maintenance_approval_revocations_dependencies())



def _read_revocation_summaries() -> list[dict[str, Any]]:
    return _read_revocation_summaries_implementation(_deps=_build_self_maintenance_approval_revocations_dependencies())



def _find_approval_summary(approval_record_id: str | None = None) -> dict[str, Any] | None:
    records = list(build_publish_approval_record_reader(save=False).get("records", []))
    if approval_record_id:
        needle = str(approval_record_id).strip()
        for record in records:
            if needle in {str(record.get("approval_id")), str(record.get("approval_record_hash")), str(record.get("approval_record_hash", ""))[:16]}:
                return record
        return None
    return records[0] if records else None


def _find_explicit_approval_summary(approval_record_id: str | None = None) -> dict[str, Any] | None:
    if not approval_record_id:
        return None
    return _find_approval_summary(approval_record_id)


def _matching_approval_records_for_artifact(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None) -> list[dict[str, Any]]:
    revalidation = build_approval_artifact_revalidation(project_id=project_id, package_name=package_name or _package_name(), zip_path=zip_path, save=False)
    records = revalidation.get("matching_approval_records", [])
    return list(records) if isinstance(records, list) else []


def _matching_approval_revocation_summaries(project_id: str = "eidolon", package_name: str | None = None, zip_path: str | None = None) -> list[dict[str, Any]]:
    matches = _matching_approval_records_for_artifact(project_id=project_id, package_name=package_name, zip_path=zip_path)
    if not matches:
        return []
    revocations = _read_revocation_summaries()
    return [row for row in revocations if row.get("valid") and any(_approval_target_matches(row, approval) for approval in matches)]


def _approval_already_revoked(approval: dict[str, Any] | None) -> bool:
    if not approval:
        return False
    return any(row.get("valid") and _approval_target_matches(row, approval) for row in _read_revocation_summaries())


def _revocation_confirmation_phrase(approval: dict[str, Any] | None) -> str:
    target_hash = str((approval or {}).get("approval_record_hash") or "APPROVAL")
    return f"REVOKE PUBLISH APPROVAL {target_hash[:12]}"


def _revocation_record_preview(approval: dict[str, Any], reason: str | None = None, revoker_label: str | None = None, confirmation: str | None = None, dry_run: bool = True) -> dict[str, Any]:
    confirmation_text = str(confirmation or _revocation_confirmation_phrase(approval))
    target_artifact_hashes = {key: approval.get(key) for key in ("package_sha256", "canonical_manifest_hash", "canonical_evidence_hash", "signing_payload_hash", "signature_sidecar_hash")}
    record = {
        "schema_version": "eidolon.publish_approval_revocation.v1",
        "target_approval_record_id": approval.get("approval_id"),
        "target_approval_record_hash": approval.get("approval_record_hash"),
        "target_artifact_hashes": target_artifact_hashes,
        "revocation_reason": reason or "superseded release",
        "revoked_at": None if dry_run else _now(),
        "revoked_by_label": revoker_label or ("dry-run-operator" if dry_run else "local-operator"),
        "confirmation_marker": "sha256:" + hashlib.sha256(confirmation_text.encode("utf-8")).hexdigest(),
        "revocation_scope": "publish_approval_only",
        "rollback_approved": False,
        "live_apply_approved": False,
        "preview_only": bool(dry_run),
    }
    record["revocation_record_hash"] = _sha256_text({k: v for k, v in record.items() if k != "revocation_record_hash"})
    record["revocation_id"] = f"revocation-{record['revocation_record_hash'][:16]}"
    return record


def _revocation_record_path(record: dict[str, Any]) -> Path:
    target_hash = str(record.get("target_approval_record_hash") or "unknown")[:16]
    record_hash = str(record.get("revocation_record_hash") or _sha256_text(record))[:16]
    return APPROVAL_REVOCATIONS_DIR / f"publish_approval_revocation_{target_hash}_{record_hash}.json"


def _revocation_write_blockers(approval: dict[str, Any] | None) -> list[str]:
    blockers: list[str] = []
    if not approval:
        blockers.append("no target approval record found")
        return blockers
    if not approval.get("valid"):
        blockers.append("target approval record is malformed")
    if not approval.get("publish_approved"):
        blockers.append("target approval record is not an active publish approval")
    if approval.get("live_apply_approved"):
        blockers.append("target approval record incorrectly implies live apply")
    if _approval_already_revoked(approval):
        blockers.append("target approval record has already been revoked")
    return blockers


def build_approval_revocation_record_schema(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v39.1: define append-only publish approval revocation record schema."""
    schema_fields = ["schema_version", "target_approval_record_id", "target_approval_record_hash", "target_artifact_hashes", "revocation_reason", "revoked_at", "revoked_by_label", "confirmation_marker", "revocation_scope", "rollback_approved", "live_apply_approved", "revocation_record_hash"]
    rows = [
        {"name": "schema-fields", "status": "pass", "message": ", ".join(schema_fields)},
        {"name": "publish-only-scope", "status": "pass", "message": "revocation_scope is publish_approval_only"},
        {"name": "append-only", "status": "pass", "message": "revocation creates a new record and never deletes approvals"},
        {"name": "rollback-separated", "status": "pass", "message": "revocation does not approve rollback"},
        {"name": "live-apply-separated", "status": "pass", "message": "revocation does not approve live apply"},
        {"name": "private-key-boundary", "status": "pass", "message": "revocation schema has no private key fields"},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v39.1", "status": _status_from(rows), "ok": True, "schema_version": "eidolon.publish_approval_revocation.v1", "schema_fields": schema_fields, "append_only": True, "delete_approval_records": False, "rollback_approved": False, "live_apply_approved": False, "rows": rows, "message": "Approval revocation record schema binds exact approval records and artifact hashes while staying append-only and separate from rollback/live apply."}
    if save: _write_json(APPROVAL_REVOCATION_RECORD_SCHEMA, report)
    else: report["preview_only"] = True
    return report


def build_approval_revocation_confirmation_validator(project_id: str = "eidolon", approval_record_id: str | None = None, confirmation: str | None = None, save: bool = True) -> dict[str, Any]:
    """v39.2: validate exact revocation confirmation without writing anything."""
    target = _find_explicit_approval_summary(approval_record_id)
    expected = _revocation_confirmation_phrase(target)
    confirmation = str(confirmation or "")
    valid = bool(approval_record_id and target) and confirmation == expected
    rows = [
        {"name": "explicit-target-required", "status": "pass" if approval_record_id else "warn", "message": str(approval_record_id or "approval_record_id/hash required")},
        {"name": "target-approval-found", "status": "pass" if target else "warn", "message": str(approval_record_id or "no implicit latest fallback")},
        {"name": "exact-confirmation", "status": "pass" if valid else "warn", "message": "confirmation matched" if valid else f"expected: {expected}"},
        {"name": "writes-nothing", "status": "pass", "message": "validator never writes revocation state"},
        {"name": "rollback-separated", "status": "pass", "message": "confirmation validation does not approve rollback"},
        {"name": "live-apply-separated", "status": "pass", "message": "confirmation validation does not approve live apply"},
    ]
    status = _status_from(rows)
    if not valid and status == "pass": status = "warn"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v39.2", "status": status, "ok": _ok_from(status), "approval_record_id": approval_record_id, "target_approval_record_hash": target.get("approval_record_hash") if target else None, "confirmation_valid": valid, "required_confirmation_phrase": expected, "would_write_revocation": False, "rollback_approved": False, "live_apply_approved": False, "rows": rows, "message": "Revocation confirmation validator requires the exact target approval hash prefix and writes nothing."}
    if save: _write_json(APPROVAL_REVOCATION_CONFIRMATION_VALIDATOR, report)
    else: report["preview_only"] = True
    return report


def build_approval_revocation_write_preflight(project_id: str = "eidolon", approval_record_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v39.3: preview whether a publish approval revocation can safely be written."""
    target = _find_explicit_approval_summary(approval_record_id)
    blockers = _revocation_write_blockers(target)
    if not approval_record_id:
        blockers.insert(0, "approval_record_id or approval hash is required; no implicit first-record fallback")
    quarantine = build_revocation_storage_quarantine(project_id=project_id, save=False) if 'build_revocation_storage_quarantine' in globals() else {"status": "pass", "ok": True, "message": "revocation storage quarantine scaffold"}
    eligible = bool(target) and not blockers and _report_gate_status(quarantine) != "blocked"
    rows = [
        {"name": "explicit-target-required", "status": "pass" if approval_record_id else "warn", "message": str(approval_record_id or "approval_record_id/hash required")},
        {"name": "approval-record-exists", "status": "pass" if target else "warn", "message": str(approval_record_id or "no implicit latest fallback")},
        {"name": "approval-record-valid", "status": "pass" if target and target.get("valid") else "warn", "message": str(bool(target and target.get("valid")))},
        {"name": "not-already-revoked", "status": "pass" if not (target and _approval_already_revoked(target)) else "warn", "message": "target is not already revoked" if target and not _approval_already_revoked(target) else "target unavailable or already revoked"},
        {"name": "eligible-to-revoke", "status": "pass" if eligible else "warn", "message": str(eligible)},
        {"name": "confirmation-required", "status": "pass", "message": _revocation_confirmation_phrase(target)},
        {"name": "storage-quarantine", "status": _report_gate_status(quarantine), "message": quarantine.get("message", "")},
        {"name": "rollback-live-apply-separated", "status": "pass", "message": "revocation preflight cannot approve rollback or live apply"},
    ]
    status = _status_from(rows)
    if not eligible and status == "pass": status = "warn"
    preview = _revocation_record_preview(target, dry_run=True) if target else None
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v39.3", "status": status, "ok": _ok_from(status), "approval_record_id": approval_record_id, "target_approval_record_hash": target.get("approval_record_hash") if target else None, "eligible_to_revoke": eligible, "would_write_revocation": False, "revocation_record_preview": preview, "required_confirmation_phrase": _revocation_confirmation_phrase(target), "blocking_reasons": blockers, "rollback_approved": False, "live_apply_approved": False, "rows": rows, "message": "Approval revocation write preflight checks target validity, prior revocation, quarantine, and rollback/live-apply separation without writing."}
    if save: _write_json(APPROVAL_REVOCATION_WRITE_PREFLIGHT, report)
    else: report["preview_only"] = True
    return report


def build_revocation_storage_quarantine(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v39.4: prove revocation records are runtime-only and append-only."""
    pkg_text = (ROOT_DIR / "conscious_agent" / "release_packaging.py").read_text(encoding="utf-8", errors="replace")
    inventory = build_package_inventory(project_id=project_id, save=False)
    included = [row.get("path", "") for row in inventory.get("included", [])]
    leaked = [path for path in included if path.startswith("data/release_approval_revocations/")]
    rows = [
        {"name": "runtime-directory", "status": "pass", "message": _report_path(str(APPROVAL_REVOCATIONS_DIR))},
        {"name": "source-package-exclusion", "status": "pass" if not leaked else "blocked", "message": "revocation records excluded" if not leaked else ", ".join(leaked)},
        {"name": "not-source-allowlisted", "status": "pass" if "data/release_approval_revocations" not in pkg_text else "warn", "message": "revocation dir is not source-data allowlisted"},
        {"name": "append-only", "status": "pass", "message": "revocation records never overwrite approval records"},
        {"name": "approval-records-preserved", "status": "pass", "message": "revocation is a separate ledger, not deletion"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v39.4", "status": status, "ok": _ok_from(status), "revocation_storage_dir": _report_path(str(APPROVAL_REVOCATIONS_DIR)), "source_only_excluded": not leaked, "append_only": True, "rollback_approved": False, "live_apply_approved": False, "rows": rows, "message": "Revocation storage quarantine keeps publish approval revocations in runtime-only append-only storage outside source packages."}
    if save: _write_json(REVOCATION_STORAGE_QUARANTINE, report)
    else: report["preview_only"] = True
    return report


def build_post_only_revocation_route_design(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v39.5: audit POST-only publish approval revocation route design."""
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace")
    rows = [
        {"name": "post-route-present", "status": "pass" if "revoke-publish-approval" in api_text else "blocked", "message": "POST /api/release/revoke-publish-approval is declared"},
        {"name": "dry-run-default", "status": "pass" if "build_write_approval_revocation" in api_text and "dry_run" in api_text else "blocked", "message": "revocation route supports dry_run and guarded write"},
        {"name": "get-never-revokes", "status": "pass", "message": "GET routes expose previews only"},
        {"name": "no-deletion", "status": "pass", "message": "revocation route writes append-only records, not approval deletion"},
        {"name": "rollback-live-apply-separated", "status": "pass", "message": "revocation route does not approve rollback or live apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v39.5", "status": status, "ok": _ok_from(status), "route": "POST /api/release/revoke-publish-approval", "dry_run_default": True, "delete_approval_records": False, "rollback_approved": False, "live_apply_approved": False, "rows": rows, "message": "POST-only revocation route design keeps revocation writes guarded, dry-run by default, append-only, and separate from rollback/live apply."}
    if save: _write_json(POST_ONLY_REVOCATION_ROUTE_DESIGN, report)
    else: report["preview_only"] = True
    return report


def build_write_approval_revocation(project_id: str = "eidolon", approval_record_id: str | None = None, confirmation: str | None = None, revocation_reason: str | None = None, revoker_label: str | None = None, dry_run: bool = True, approve: bool = False, save: bool = True) -> dict[str, Any]:
    """v39.6: guarded runtime write for append-only publish approval revocation records."""
    target = _find_explicit_approval_summary(approval_record_id)
    preflight = build_approval_revocation_write_preflight(project_id=project_id, approval_record_id=approval_record_id, save=False)
    confirm = build_approval_revocation_confirmation_validator(project_id=project_id, approval_record_id=approval_record_id, confirmation=confirmation, save=False)
    eligible = bool(preflight.get("eligible_to_revoke")) and bool(confirm.get("confirmation_valid"))
    should_write = bool(eligible and approve and not dry_run)
    blockers = list(preflight.get("blocking_reasons") or [])
    if not approval_record_id:
        blockers.append("approval_record_id/hash is required for guarded revocation writes")
        eligible = False
        should_write = False
    if not confirm.get("confirmation_valid"):
        blockers.append("revocation confirmation phrase did not match target approval hash")
    if not approve and not dry_run:
        blockers.append("explicit revocation approval flag was not supplied")
    record = _revocation_record_preview(target, reason=revocation_reason, revoker_label=revoker_label, confirmation=confirmation, dry_run=not should_write) if target else None
    write_path = None
    if should_write and record:
        rows = _revocation_validator_rows(record)
        if _status_from(rows) == "blocked":
            eligible = False
            should_write = False
            blockers.append("revocation record failed schema validation")
        else:
            APPROVAL_REVOCATIONS_DIR.mkdir(parents=True, exist_ok=True)
            path = _revocation_record_path(record)
            if path.exists():
                blockers.append("matching revocation record already exists")
                should_write = False
            else:
                write_text_atomic(path, json.dumps(record, indent=2, default=str), encoding="utf-8")
                write_path = _report_path(str(path.relative_to(ROOT_DIR) if path.is_relative_to(ROOT_DIR) else path))
                _append_approval_audit_event("approval_revocation_record_written", {"approval_record_id": approval_record_id, "revocation_record_hash": record.get("revocation_record_hash")}, save=True)
    rows = [
        {"name": "preflight", "status": _report_gate_status(preflight), "message": preflight.get("message", "")},
        {"name": "confirmation", "status": _report_gate_status(confirm), "message": confirm.get("message", "")},
        {"name": "eligible-to-revoke", "status": "pass" if eligible else "warn", "message": str(eligible)},
        {"name": "would-write-revocation", "status": "pass", "message": str(bool(should_write))},
        {"name": "append-only", "status": "pass", "message": "revocation writes a separate record and never deletes approval"},
        {"name": "rollback-separated", "status": "pass", "message": "False"},
        {"name": "live-apply-separated", "status": "pass", "message": "False"},
    ]
    status = _status_from(rows)
    if not eligible and status == "pass": status = "warn"
    if not should_write and not dry_run and approve and eligible:
        status = "blocked"
