def _classify_patch_risk(files: list[str]) -> str:
    joined = " ".join(files).lower()
    if any(token in joined for token in ("approval", "revocation", "self_maintenance", "release_packaging", "api_server")): return "high"
    if "dashboard" in joined or "api" in joined: return "medium"
    if "readme" in joined or joined.endswith(".md"): return "low"
    return "medium"


