    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.0", "status": status, "ok": _ok_from(status), "autonomy_ready": _ok_from(status), "dry_run_planning_ready": True, "sandbox_patch_ready": True, "human_checkpoint_required": True, "self_modification_allowed": False, "live_apply_allowed": False, "destructive_actions_allowed": False, "approval_writes_allowed": False, "steps": {"pre_v41_gate": _compact_step(gate), "policy": _compact_step(policy), "sandbox": _compact_step(sandbox), "checkpoint": _compact_step(checkpoint)}, "rows": rows, "message": "Autonomy readiness boundary is installed: dry-run planning and sandbox previews are ready while self-modification, approval writes, destructive actions, and live apply remain blocked."}
    if save: _write_json(AUTONOMY_READINESS_BOUNDARY_SYSTEM, report)
