# ---------------------------------------------------------------------------
# v41.1-v42.0 Autonomous Patch Proposal System
# ---------------------------------------------------------------------------


def _autonomy_goal(goal: str | None = None) -> str:
    text = (goal or "prepare a safe autonomous patch proposal").strip()
    return text[:240] if text else "prepare a safe autonomous patch proposal"


def _proposal_id_for_goal(goal: str | None = None) -> str:
    return "patch-" + hashlib.sha256(_autonomy_goal(goal).encode("utf-8")).hexdigest()[:12]


def _proposal_path(proposal_id: str) -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]", "-", proposal_id or "latest")[:80]
    return AUTONOMY_PATCH_PROPOSALS_DIR / f"{safe}.json"


def _select_autonomy_targets(goal: str | None = None) -> list[str]:
    text = _autonomy_goal(goal).lower()
    files: list[str] = []
    if "dashboard" in text or "page" in text or "render" in text:
        files.extend(["conscious_agent/dashboard.py", "conscious_agent/self_maintenance.py"])
    if "api" in text or "route" in text or "endpoint" in text:
        files.extend(["conscious_agent/api_server.py", "conscious_agent/self_maintenance.py"])
    if "smoke" in text or "test" in text or "version" in text:
        files.extend(["tools/smoke_check.py", "conscious_agent/self_maintenance.py"])
    if "package" in text or "zip" in text or "release" in text:
        files.extend(["conscious_agent/release_packaging.py", "conscious_agent/self_maintenance.py"])
    if not files:
        files.extend(["conscious_agent/self_maintenance.py", "conscious_agent/dashboard.py"])
    files.append("README_NEXT_STEPS.md")
    return list(dict.fromkeys(files))


def _planned_sandbox_edits(goal: str | None = None, files: list[str] | None = None) -> list[dict[str, Any]]:
    goal_text = _autonomy_goal(goal)
    selected = files or _select_autonomy_targets(goal_text)
    edits: list[dict[str, Any]] = []
    for rel in selected:
        if rel == "README_NEXT_STEPS.md":
            append = f"\n- Sandbox proposal note: {goal_text} remains preview-only until human review.\n"
        elif rel.endswith(".py"):
            append = f"\n# Autonomous sandbox proposal note: {goal_text} (preview-only, not applied to source).\n"
        else:
            append = f"\n# Sandbox proposal note: {goal_text}\n"
        edits.append({"path": rel, "operation": "append_text", "append_text": append})
    return edits


def _build_patch_proposal_record(project_id: str = "eidolon", goal: str | None = None, proposal_id: str | None = None) -> dict[str, Any]:
    goal_text = _autonomy_goal(goal)
    selected = _select_autonomy_targets(goal_text)
    risk_report = build_autonomous_patch_risk_classifier(project_id=project_id, files=selected, save=False)
    tests = build_autonomous_test_selection(project_id=project_id, files=selected, save=False)
    pid = proposal_id or _proposal_id_for_goal(goal_text)
    edits = _planned_sandbox_edits(goal_text, selected)
    return {
        "schema_version": "autonomous_patch_proposal.v1",
        "proposal_id": pid,
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "risk_level": risk_report.get("risk_level", "medium"),
        "files_expected_to_change": selected,
        "reasoning_summary": "Select the smallest source/doc set needed for the goal, stage preview edits in runtime sandbox, validate in a temp copy, then wait for human review before any source write.",
        "planned_edits": edits,
        "required_checks": tests.get("recommended_checks", []),
        "requires_human_review": True,
        "source_write_allowed": False,
        "live_apply_allowed": False,
        "destructive_actions_allowed": False,
        "approval_writes_allowed": False,
    }


def _write_patch_proposal_record(record: dict[str, Any]) -> Path:
    AUTONOMY_PATCH_PROPOSALS_DIR.mkdir(parents=True, exist_ok=True)
    path = _proposal_path(str(record.get("proposal_id") or "latest"))
    write_text_atomic(path, json.dumps(record, indent=2, default=str), encoding="utf-8")
    return path


def _load_patch_proposal(proposal_id: str | None = None, goal: str | None = None) -> dict[str, Any]:
    pid = proposal_id or _proposal_id_for_goal(goal)
    path = _proposal_path(pid)
    if path.exists():
        record = _read_json(path, {})
        if isinstance(record, dict):
            record["_persisted"] = True
            record["_proposal_path"] = _report_path(str(path))
        return record
    record = _build_patch_proposal_record(goal=goal, proposal_id=pid)
    record["_persisted"] = False
    record["_proposal_path"] = _report_path(str(path))
    return record


def _proposal_diff_lines(record: dict[str, Any]) -> list[str]:
    lines: list[str] = []
    for edit in record.get("planned_edits", []):
        rel = str(edit.get("path", ""))
        before_text = _read_text(ROOT_DIR / rel)
        after_text = before_text + str(edit.get("append_text", ""))
        before = before_text.splitlines(keepends=True)
        after = after_text.splitlines(keepends=True)
        lines.extend(difflib.unified_diff(before, after, fromfile=f"a/{rel}", tofile=f"b/{rel}", lineterm=""))
    return [line.rstrip("\n") for line in lines]


def build_patch_proposal_schema(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v41.1: define the autonomous patch proposal record schema."""
    required = ["proposal_id", "goal", "risk_level", "files_expected_to_change", "reasoning_summary", "planned_edits", "required_checks", "requires_human_review", "source_write_allowed", "live_apply_allowed"]
    example = _build_patch_proposal_record(project_id=project_id, goal="speed up release dashboard rendering", proposal_id="patch-example")
    rows = [{"name": f"field-{field.replace('_','-')}", "status": "pass", "message": field} for field in required]
    rows.append({"name": "source-write-blocked", "status": "pass" if example.get("source_write_allowed") is False else "blocked", "message": "proposals cannot write source"})
    rows.append({"name": "human-review-required", "status": "pass" if example.get("requires_human_review") else "blocked", "message": "patch review checkpoint required"})
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.1", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "schema_fields": required, "example_proposal": example, "source_write_allowed": False, "live_apply_allowed": False, "rows": rows, "message": "Patch proposal schema records goals, target files, planned edits, checks, and review gates without source mutation."}
    if save: _write_json(PATCH_PROPOSAL_SCHEMA, report)
    else: report["preview_only"] = True
    return report


def build_autonomous_change_target_selector(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.2: select likely source targets for an autonomous patch goal."""
    goal_text = _autonomy_goal(goal)
    files = _select_autonomy_targets(goal_text)
    risk = build_autonomous_patch_risk_classifier(project_id=project_id, files=files, save=False)
    checks = build_autonomous_test_selection(project_id=project_id, files=files, save=False)
    reasons = []
    for rel in files:
        if rel == "README_NEXT_STEPS.md": why = "README update is required for project code changes."
        elif "dashboard" in rel: why = "Dashboard surface likely affects operator workflow or page rendering."
        elif "api_server" in rel: why = "API route surface likely affects read-only/POST-only behavior."
        elif "self_maintenance" in rel: why = "Self-maintenance gates and reports coordinate autonomy behavior."
        elif "smoke_check" in rel: why = "Smoke checks validate release labels and install gates."
        else: why = "File matched the goal keywords."
        reasons.append({"path": rel, "why": why})
    rows = [{"name": "target-" + rel.replace("/", "-"), "status": "pass" if (ROOT_DIR / rel).exists() else "warn", "message": next((r["why"] for r in reasons if r["path"] == rel), "selected")} for rel in files]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.2", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "goal": goal_text, "likely_files": files, "why_each_file_matters": reasons, "risk_level": risk.get("risk_level"), "suggested_patch_scope": "sandbox proposal only; no source apply", "recommended_checks": checks.get("recommended_checks", []), "source_write_allowed": False, "rows": rows, "message": "Autonomous target selector maps a goal to likely files, reasons, risk, and checks without modifying source."}
    if save: _write_json(AUTONOMOUS_CHANGE_TARGET_SELECTOR, report)
    else: report["preview_only"] = True
    return report


def build_generate_sandbox_patch(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.3: write a sandbox-only patch proposal record."""
    record = _build_patch_proposal_record(project_id=project_id, goal=goal)
    path: Path | None = None
    if save:
        AUTONOMY_SANDBOX_DIR.mkdir(parents=True, exist_ok=True)
        path = _write_patch_proposal_record(record)
        write_text_atomic((AUTONOMY_SANDBOX_DIR / "latest_proposal_id.txt"), str(record["proposal_id"]), encoding="utf-8")
    rows = [
        {"name": "sandbox-only", "status": "pass", "message": "proposal written under data/autonomy when saved"},
        {"name": "source-write-blocked", "status": "pass", "message": "real source remains unchanged"},
        {"name": "approval-state-blocked", "status": "pass", "message": "no approval/revocation state touched"},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.3", "status": _status_from(rows), "ok": True, "proposal": record, "proposal_id": record.get("proposal_id"), "proposal_path": _report_path(str(path)) if path else None, "writes_source": False, "writes_runtime_state": bool(save), "rows": rows, "message": "Sandbox patch generator stages a structured patch proposal in runtime-only autonomy storage and does not alter source files."}
    if save: _write_json(GENERATE_SANDBOX_PATCH, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_patch_diff(project_id: str = "eidolon", proposal_id: str | None = None, goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.4: render a diff preview for a sandbox patch proposal."""
    record = _load_patch_proposal(proposal_id=proposal_id, goal=goal)
    diff_lines = _proposal_diff_lines(record)
    rows = [
        {"name": "proposal-loaded", "status": "pass" if record else "blocked", "message": str(record.get("proposal_id", ""))},
        {"name": "diff-preview", "status": "pass" if diff_lines else "warn", "message": f"{len(diff_lines)} diff lines"},
        {"name": "source-write-blocked", "status": "pass", "message": "diff viewer is read-only"},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.4", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "proposal_id": record.get("proposal_id"), "files_affected": record.get("files_expected_to_change", []), "risk_level": record.get("risk_level"), "required_checks": record.get("required_checks", []), "diff_preview": "\n".join(diff_lines[:400]), "diff_line_count": len(diff_lines), "source_write_allowed": False, "rows": rows, "message": "Sandbox patch diff viewer exposes proposed edits, affected files, risk, and required checks without applying them."}
    if save: _write_json(SANDBOX_PATCH_DIFF, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_patch_validation(project_id: str = "eidolon", proposal_id: str | None = None, goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.5: validate a sandbox proposal before any source apply exists."""
    record = _load_patch_proposal(proposal_id=proposal_id, goal=goal)
    files = [str(x) for x in record.get("files_expected_to_change", [])]
    code_files = [rel for rel in files if rel.endswith(".py") or rel.startswith("conscious_agent/") or rel.startswith("tools/")]
    bad_targets = [rel for rel in files if rel.startswith("data/") or ".." in rel or rel.startswith("/")]
    missing = [rel for rel in files if not (ROOT_DIR / rel).exists()]
    readme_ok = (not code_files) or "README_NEXT_STEPS.md" in files
    forbidden_blob = json.dumps(record, default=str)
    private_markers = [marker for marker in PRIVATE_KEY_MARKERS if marker in forbidden_blob]
    risk_report = build_autonomous_patch_risk_classifier(project_id=project_id, files=files, save=False)
    rows = [
        {"name": "target-files-exist", "status": "pass" if not missing else "blocked", "message": ", ".join(missing) if missing else "all targets exist"},
        {"name": "no-runtime-private-targets", "status": "pass" if not bad_targets else "blocked", "message": ", ".join(bad_targets) if bad_targets else "no data/runtime targets"},
        {"name": "readme-included-for-code", "status": "pass" if readme_ok else "blocked", "message": "README_NEXT_STEPS.md included" if readme_ok else "code changes require README update"},
        {"name": "no-private-key-markers", "status": "pass" if not private_markers else "blocked", "message": ", ".join(private_markers) if private_markers else "none"},
        {"name": "risk-classifier", "status": "pass", "message": str(risk_report.get("risk_level"))},
        {"name": "source-write-blocked", "status": "pass", "message": "validation writes no source"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.5", "status": status, "ok": _ok_from(status), "proposal_id": record.get("proposal_id"), "validated_files": files, "missing_targets": missing, "forbidden_targets": bad_targets, "readme_included_for_code": readme_ok, "risk_level": risk_report.get("risk_level"), "source_write_allowed": False, "rows": rows, "message": "Sandbox patch validation checks targets, README coverage, runtime exclusions, private-key markers, and risk before any source apply."}
    if save: _write_json(SANDBOX_PATCH_VALIDATION, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_patch_test_run(project_id: str = "eidolon", proposal_id: str | None = None, goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.6: apply sandbox proposal to a temp copy and run lightweight selected checks."""
    record = _load_patch_proposal(proposal_id=proposal_id, goal=goal)
    validation = build_sandbox_patch_validation(project_id=project_id, proposal_id=str(record.get("proposal_id", "")), goal=goal, save=False)
    test_results: list[dict[str, Any]] = []
    temp_apply_ok = False
    source_unchanged = True
    with tempfile.TemporaryDirectory(prefix="eidolon_autonomy_patch_") as tmp:
        tmp_root = Path(tmp) / "Eidolon"
        ignore = shutil.ignore_patterns(".git", ".venv", "__pycache__", "data/self_maintenance", "data/autonomy", "reports")
        shutil.copytree(ROOT_DIR, tmp_root, ignore=ignore)
        for edit in record.get("planned_edits", []):
            target = tmp_root / str(edit.get("path", ""))
            if target.exists() and str(edit.get("operation")) == "append_text":
                append_text_atomic(target, str(edit.get("append_text", "")), encoding="utf-8", errors="replace")
        temp_apply_ok = True
        commands = [[sys.executable, "-m", "py_compile", "conscious_agent/self_maintenance.py", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "tools/smoke_check.py"]]
        for cmd in commands:
            proc = subprocess.run(cmd, cwd=tmp_root, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=45)
            test_results.append({"command": " ".join(cmd), "returncode": proc.returncode, "status": "pass" if proc.returncode == 0 else "blocked", "stdout": proc.stdout[-1200:], "stderr": proc.stderr[-1200:]})
    rows = [
        {"name": "validation", "status": _report_gate_status(validation), "message": validation.get("message", "")},
        {"name": "temp-apply", "status": "pass" if temp_apply_ok else "blocked", "message": "proposal applied to temp copy only"},
        {"name": "selected-checks", "status": _status_from(test_results), "message": f"{len(test_results)} checks"},
        {"name": "source-unchanged", "status": "pass" if source_unchanged else "blocked", "message": "real source not modified"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.6", "status": status, "ok": _ok_from(status), "proposal_id": record.get("proposal_id"), "temp_apply_ok": temp_apply_ok, "real_source_unchanged": source_unchanged, "selected_check_results": test_results, "source_write_allowed": False, "rows": rows, "message": "Sandbox patch test run applies the proposal to a temporary copy and runs lightweight compile checks without changing real source."}
    if save: _write_json(SANDBOX_PATCH_TEST_RUN, report)
    else: report["preview_only"] = True
    return report


def build_patch_review_checkpoint(project_id: str = "eidolon", proposal_id: str | None = None, goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.7: model human patch review checkpoints without source apply approval."""
    record = _load_patch_proposal(proposal_id=proposal_id, goal=goal)
    checkpoint = {
        "proposal_id": record.get("proposal_id"),
        "proposal_hash": _sha256_text(record),
        "plan_reviewed": False,
        "patch_reviewed": False,
        "tests_passed": False,
        "source_apply_approved": False,
        "release_packaged": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    rows = [
        {"name": "artifact-binding", "status": "pass", "message": checkpoint["proposal_hash"]},
        {"name": "patch-reviewed-not-source-approved", "status": "pass", "message": "patch review remains separate from source apply approval"},
        {"name": "publish-not-live-apply", "status": "pass", "message": "publish approval remains separate from live apply"},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.7", "status": _status_from(rows), "ok": True, "proposal_id": record.get("proposal_id"), "checkpoint": checkpoint, "human_review_required": True, "source_apply_approved": False, "live_apply_approved": False, "rows": rows, "message": "Human patch review checkpoint binds the proposal hash while keeping patch review, source apply approval, publish approval, and live apply approval separate."}
    if save: _write_json(PATCH_REVIEW_CHECKPOINT, report)
    else: report["preview_only"] = True
    return report


def build_source_apply_dry_run(project_id: str = "eidolon", proposal_id: str | None = None, goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.8: preview what source apply would do while writing nothing."""
    record = _load_patch_proposal(proposal_id=proposal_id, goal=goal)
    validation = build_sandbox_patch_validation(project_id=project_id, proposal_id=str(record.get("proposal_id", "")), goal=goal, save=False)
    test_run = build_sandbox_patch_test_run(project_id=project_id, proposal_id=str(record.get("proposal_id", "")), goal=goal, save=False)
    files = record.get("files_expected_to_change", [])
    rows = [
        {"name": "would-modify-files", "status": "pass", "message": ", ".join(files)},
        {"name": "would-update-readme", "status": "pass" if "README_NEXT_STEPS.md" in files else "blocked", "message": "README_NEXT_STEPS.md"},
        {"name": "validation", "status": _report_gate_status(validation), "message": validation.get("message", "")},
        {"name": "temp-test-run", "status": _report_gate_status(test_run), "message": test_run.get("message", "")},
        {"name": "would-write-source", "status": "pass", "message": "False"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.8", "status": status, "ok": _ok_from(status), "proposal_id": record.get("proposal_id"), "would_modify_files": files, "would_update_readme": "README_NEXT_STEPS.md" in files, "would_run_checks": record.get("required_checks", []), "would_create_release_zip": False, "would_write_source": False, "source_apply_allowed": False, "rows": rows, "message": "Source apply dry-run previews file changes, README update, checks, and package implications while writing no source."}
    if save: _write_json(SOURCE_APPLY_DRY_RUN, report)
    else: report["preview_only"] = True
    return report


def build_pre_v42_autonomous_patch_gate(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v41.9: combine autonomous patch proposal checks."""
    record_report = build_generate_sandbox_patch(project_id=project_id, goal=goal, save=False)
    pid = str(record_report.get("proposal_id", ""))
    checks = {
        "proposal_schema": build_patch_proposal_schema(project_id=project_id, save=False),
        "target_selector": build_autonomous_change_target_selector(project_id=project_id, goal=goal, save=False),
        "sandbox_generator": record_report,
        "diff_viewer": build_sandbox_patch_diff(project_id=project_id, proposal_id=pid, goal=goal, save=False),
        "patch_validation": build_sandbox_patch_validation(project_id=project_id, proposal_id=pid, goal=goal, save=False),
        "temp_apply_test": build_sandbox_patch_test_run(project_id=project_id, proposal_id=pid, goal=goal, save=False),
        "human_checkpoint": build_patch_review_checkpoint(project_id=project_id, proposal_id=pid, goal=goal, save=False),
        "source_apply_dry_run": build_source_apply_dry_run(project_id=project_id, proposal_id=pid, goal=goal, save=False),
        "privacy_scan": build_package_privacy_scan(project_id=project_id, save=False),
        "route_safety": build_api_route_safety_audit(project_id=project_id, save=False),
    }
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    rows.extend([
        {"name": "source-apply-blocked", "status": "pass", "message": "v42 does not apply source patches"},
        {"name": "live-apply-blocked", "status": "pass", "message": "v42 cannot perform live apply"},
        {"name": "approval-writes-blocked", "status": "pass", "message": "patch proposal cannot write release approvals"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v41.9", "status": status, "ok": _ok_from(status), "gate_ready": _ok_from(status), "proposal_id": pid, "source_apply_allowed": False, "live_apply_allowed": False, "steps": {k: _compact_step(v) for k, v in checks.items()}, "rows": rows, "message": "Pre-v42 gate verifies proposal schema, target selection, sandbox generation, diff, validation, temp tests, checkpoint, source-apply dry-run, privacy, and route safety without source mutation."}
    if save: _write_json(PRE_V42_AUTONOMOUS_PATCH_GATE, report)
    else: report["preview_only"] = True
    return report


def build_autonomous_patch_proposal_system(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v42.0: autonomous patch proposal system, sandbox-only and human-reviewed."""
    gate = build_pre_v42_autonomous_patch_gate(project_id=project_id, goal=goal, save=False)
    proposal = build_generate_sandbox_patch(project_id=project_id, goal=goal, save=save)
