# ---------------------------------------------------------------------------
# v45.1-v46.0 Multi-Task Work Queue for Self-Maintenance
# ---------------------------------------------------------------------------

MAINTENANCE_TASK_STATES = {"queued", "selected", "cycle_running", "checkpoint_required", "apply_handoff_ready", "blocked", "completed"}


def _maintenance_task_id_for_goal(goal: str | None = None, title: str | None = None) -> str:
    seed = (_autonomy_goal(goal) + "|" + (title or "maintenance-task")).encode("utf-8")
    return "mtask-" + hashlib.sha256(seed).hexdigest()[:12]


def _maintenance_task_path(task_id: str) -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]", "-", task_id or "latest")[:80]
    return AUTONOMY_MAINTENANCE_TASKS_DIR / f"{safe}.json"


def _maintenance_queue_path(queue_id: str = "default") -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]", "-", queue_id or "default")[:80]
    return AUTONOMY_MAINTENANCE_QUEUE_DIR / f"{safe}.json"


def _maintenance_queue_goals(goal: str | None = None) -> list[str]:
    goals: list[str] = []
    if goal:
        goals.append(_autonomy_goal(goal))
    goals.extend([
        "improve release dashboard performance",
        "tighten source-only package privacy around maintenance queue records",
        "add dashboard and API queue visibility for self-maintenance tasks",
        "expand fixture coverage for supervised queue selection",
    ])
    return list(dict.fromkeys(goals))[:8]


def _maintenance_task_title(goal: str) -> str:
    return " ".join(_autonomy_goal(goal)[:72].split()).capitalize()


def _score_maintenance_goal(goal: str | None = None, files: list[str] | None = None) -> dict[str, Any]:
    text = _autonomy_goal(goal).lower()
    selected = files or _select_autonomy_targets(text)
    return _score_maintenance_goal_components(text, selected)


def _build_maintenance_task_record(project_id: str = "eidolon", goal: str | None = None, title: str | None = None, state: str = "queued") -> dict[str, Any]:
    goal_text = _autonomy_goal(goal)
    task_title = title or _maintenance_task_title(goal_text)
    score = _score_maintenance_goal(goal_text)
    return {
        "schema_version": "eidolon.self_maintenance_task.v1",
        "task_id": _maintenance_task_id_for_goal(goal_text, task_title),
        "project_id": project_id,
        "created_at": _now(),
        "title": task_title,
        "goal": goal_text,
        "state": state if state in MAINTENANCE_TASK_STATES else "queued",
        "priority_score": score["priority_score"],
        "risk_score": score["risk_score"],
        "risk_level": score["risk_level"],
        "scoring_reasons": score["reasons"],
        "planned_files": score["planned_files"],
        "cycle_id": _maintenance_cycle_id_for_goal(goal_text),
        "checkpoint_binding_required": True,
        "one_cycle_at_a_time": True,
        "no_concurrent_source_apply": True,
        "source_apply_requires_confirmation": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "runtime_only": True,
    }


def _write_maintenance_task(record: dict[str, Any]) -> Path:
    AUTONOMY_MAINTENANCE_TASKS_DIR.mkdir(parents=True, exist_ok=True)
    path = _maintenance_task_path(str(record.get("task_id") or "latest"))
    write_text_atomic(path, json.dumps(record, indent=2, default=str), encoding="utf-8")
    return path


def _load_maintenance_tasks(project_id: str = "eidolon", goal: str | None = None) -> list[dict[str, Any]]:
    tasks: list[dict[str, Any]] = []
    if AUTONOMY_MAINTENANCE_TASKS_DIR.exists():
        for path in sorted(AUTONOMY_MAINTENANCE_TASKS_DIR.glob("*.json")):
            value = _read_json(path, {})
            if isinstance(value, dict) and value.get("task_id"):
                value["_task_path"] = _report_path(str(path))
                tasks.append(value)
    if not tasks:
        return [_build_maintenance_task_record(project_id=project_id, goal=item) for item in _maintenance_queue_goals(goal)]
    if goal:
        for item in _maintenance_queue_goals(goal):
            candidate = _build_maintenance_task_record(project_id=project_id, goal=item)
            if not any(str(task.get("task_id")) == candidate["task_id"] for task in tasks):
                tasks.append(candidate)
    return tasks


def build_maintenance_task_record_schema(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    required = ["task_id", "goal", "state", "priority_score", "risk_score", "risk_level", "cycle_id", "checkpoint_binding_required", "source_apply_approved", "publish_approved", "live_apply_approved", "runtime_only"]
    example = _build_maintenance_task_record(project_id=project_id, goal="improve release dashboard performance")
    rows = [{"name": "field-" + field.replace("_", "-"), "status": "pass" if field in example else "blocked", "message": field} for field in required]
    rows += [
        {"name": "runtime-only", "status": "pass" if example.get("runtime_only") is True else "blocked", "message": "task records live under data/autonomy and stay out of source packages"},
        {"name": "source-apply-not-approved", "status": "pass" if example.get("source_apply_approved") is False else "blocked", "message": "task schema cannot approve source apply"},
        {"name": "publish-not-approved", "status": "pass" if example.get("publish_approved") is False else "blocked", "message": "task schema cannot approve publish"},
        {"name": "live-apply-not-approved", "status": "pass" if example.get("live_apply_approved") is False else "blocked", "message": "task schema cannot approve live apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.1", "status": status, "ok": _ok_from(status), "schema_fields": required, "example_task": example, "rows": rows, "message": "Maintenance task schema tracks supervised queue work without granting source apply, publish, or live approval."}
    if save: _write_json(MAINTENANCE_TASK_RECORD_SCHEMA, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_task_priority_risk_scoring(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    tasks = [_build_maintenance_task_record(project_id=project_id, goal=item) for item in _maintenance_queue_goals(goal)]
    rows = [{"name": task["task_id"], "status": "pass" if task.get("risk_level") in {"low", "medium", "high"} else "blocked", "message": f"priority={task.get('priority_score')} risk={task.get('risk_level')} goal={task.get('goal')}"} for task in tasks]
    rows += [
        {"name": "bounded-scores", "status": "pass" if all(0 <= int(t.get("priority_score", 0)) <= 100 and 0 <= int(t.get("risk_score", 0)) <= 100 for t in tasks) else "blocked", "message": "priority/risk scores are 0-100"},
        {"name": "risk-aware-selection", "status": "pass", "message": "queue selection sorts by priority, then lower risk"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.2", "status": status, "ok": _ok_from(status), "tasks": tasks, "rows": rows, "message": "Maintenance task scoring assigns bounded priority/risk values and keeps risky mutation-adjacent work visible instead of invisible."}
    if save: _write_json(MAINTENANCE_TASK_PRIORITY_RISK_SCORING, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_task_queue_registry(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    tasks = _load_maintenance_tasks(project_id=project_id, goal=goal)
    persisted_paths: list[str] = []
    queue_path: Path | None = None
    if save:
        for task in tasks:
            persisted_paths.append(_report_path(str(_write_maintenance_task(task))))
        AUTONOMY_MAINTENANCE_QUEUE_DIR.mkdir(parents=True, exist_ok=True)
        queue_path = _maintenance_queue_path("default")
        queue_record = {"schema_version": "eidolon.self_maintenance_queue.v1", "project_id": project_id, "updated_at": _now(), "task_ids": [task.get("task_id") for task in tasks], "runtime_only": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False}
        write_text_atomic(queue_path, json.dumps(queue_record, indent=2, default=str), encoding="utf-8")
    queued = [task for task in tasks if str(task.get("state", "queued")) == "queued"]
    rows = [
        {"name": "task-count", "status": "pass" if tasks else "blocked", "message": f"{len(tasks)} task(s)"},
        {"name": "runtime-only-storage", "status": "pass", "message": "data/autonomy/maintenance_tasks and data/autonomy/maintenance_work_queue"},
        {"name": "queued-count", "status": "pass" if queued else "warn", "message": f"{len(queued)} queued task(s)"},
        {"name": "approval-boundary", "status": "pass" if all(not t.get("source_apply_approved") and not t.get("publish_approved") and not t.get("live_apply_approved") for t in tasks) else "blocked", "message": "task registry grants no approvals"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.3", "status": status, "ok": _ok_from(status), "queue_id": "default", "queue_path": _report_path(str(queue_path)) if queue_path else None, "task_count": len(tasks), "tasks": sorted(tasks, key=_queue_sort_key), "persisted_paths": persisted_paths, "runtime_only": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "rows": rows, "message": "Maintenance task queue registry is runtime-only and does not enter source-only packages."}
    if save: _write_json(MAINTENANCE_TASK_QUEUE_REGISTRY, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_task_selection_policy(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal, save=False)
    tasks = registry.get("tasks", []) if isinstance(registry, dict) else []
    selected, active, candidates = _select_next_maintenance_task(tasks)
    rows = [
        {"name": "active-cycle-scan", "status": "pass" if not active else "warn", "message": f"{len(active)} active task(s)"},
        {"name": "candidate-count", "status": "pass" if candidates else "warn", "message": f"{len(candidates)} candidate task(s)"},
        {"name": "one-task-selected", "status": "pass" if selected or active else "warn", "message": str((selected or (active[0] if active else {})).get("task_id", "none"))},
        {"name": "no-concurrent-source-apply", "status": "pass", "message": "selection never authorizes source apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.4", "status": status, "ok": _ok_from(status), "selected_task": selected, "active_tasks": active, "candidate_tasks": candidates[:10], "one_cycle_at_a_time": True, "selection_blocked_by_active_task": bool(active), "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "rows": rows, "message": "Selection policy chooses one queued task by priority/risk and blocks new cycle selection while another task is active."}
    if save: _write_json(MAINTENANCE_TASK_SELECTION_POLICY, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_task_cycle_orchestrator(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal, save=False)
    task = selection.get("selected_task") or (selection.get("active_tasks") or [{}])[0]
    task_goal = str(task.get("goal") or _autonomy_goal(goal))
    plan = build_self_maintenance_plan(project_id=project_id, goal=task_goal, save=False)
    sandbox_cycle = build_self_maintenance_sandbox_cycle(project_id=project_id, goal=task_goal, save=save)
    cycle_id = str(task.get("cycle_id") or sandbox_cycle.get("cycle_id") or _maintenance_cycle_id_for_goal(task_goal))
    proposal_id = str(sandbox_cycle.get("proposal_id") or _proposal_id_for_goal(task_goal))
    rows = [
        {"name": "task-selected", "status": "pass" if task.get("task_id") else "warn", "message": str(task.get("task_id", "generated-from-goal"))},
        {"name": "single-cycle", "status": "pass", "message": "only selected task goal enters the compact maintenance cycle"},
        {"name": "plan-ready", "status": _report_gate_status(plan), "message": plan.get("message", "")},
        {"name": "sandbox-cycle-ready", "status": _report_gate_status(sandbox_cycle), "message": sandbox_cycle.get("message", "")},
        {"name": "checkpoint-required", "status": "pass", "message": "human checkpoint remains required before source apply"},
        {"name": "apply-not-approved", "status": "pass", "message": "orchestrator cannot grant source, publish, or live approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.5", "status": status, "ok": _ok_from(status), "selected_task": task, "cycle_id": cycle_id, "proposal_id": proposal_id, "task_goal": task_goal, "steps": {"selection": _compact_step(selection), "plan": _compact_step(plan), "sandbox_cycle": _compact_step(sandbox_cycle)}, "one_cycle_at_a_time": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "rows": rows, "message": "Task cycle orchestrator runs exactly one selected queue item through compact plan/sandbox-cycle orchestration and leaves source apply to the guarded confirmation path."}
    if save: _write_json(MAINTENANCE_TASK_CYCLE_ORCHESTRATOR, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_task_checkpoint_binding(project_id: str = "eidolon", goal: str | None = None, task_id: str | None = None, save: bool = True) -> dict[str, Any]:
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal, save=False)
    tasks = registry.get("tasks", []) if isinstance(registry, dict) else []
    task = next((item for item in tasks if item.get("task_id") == task_id), None) if task_id else None
    if task is None:
        task, _active, _candidates = _select_next_maintenance_task(tasks)
    task = task or _build_maintenance_task_record(project_id=project_id, goal=goal)
    task_goal = str(task.get("goal") or goal or _autonomy_goal(goal))
    cycle_id = str(task.get("cycle_id") or _maintenance_cycle_id_for_goal(task_goal))
    proposal_id = _proposal_id_for_goal(task_goal)
    proposal = _load_patch_proposal(proposal_id=proposal_id, goal=task_goal)
    task_hash = _canonical_json_hash({k: v for k, v in task.items() if not str(k).startswith("_")})
    cycle_hash = _canonical_json_hash({"cycle_id": cycle_id, "goal": task_goal, "proposal_id": proposal_id, "task_id": task.get("task_id")})
    proposal_hash = _proposal_hash(proposal)
    checkpoint_hash = _canonical_json_hash({"task_hash": task_hash, "cycle_hash": cycle_hash, "proposal_hash": proposal_hash, "review_required": True})
    binding = {"task_id": task.get("task_id"), "task_hash": task_hash, "cycle_id": cycle_id, "cycle_hash": cycle_hash, "proposal_id": proposal_id, "proposal_hash": proposal_hash, "checkpoint_hash": checkpoint_hash, "review_required": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False}
    rows = [
        {"name": "task-bound", "status": "pass" if binding.get("task_id") else "blocked", "message": str(binding.get("task_id"))},
        {"name": "cycle-bound", "status": "pass" if binding.get("cycle_id") else "blocked", "message": str(binding.get("cycle_id"))},
        {"name": "proposal-bound", "status": "pass" if binding.get("proposal_id") and binding.get("proposal_hash") else "blocked", "message": str(binding.get("proposal_id"))},
        {"name": "checkpoint-required", "status": "pass" if binding.get("review_required") else "blocked", "message": "exact task/cycle/proposal binding required"},
        {"name": "approval-boundary", "status": "pass" if not any(binding.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "binding is review evidence only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.6", "status": status, "ok": _ok_from(status), "binding": binding, "task": task, "steps": {"queue_registry": _compact_step(registry)}, "rows": rows, "message": "Task checkpoint binding ties the selected queue task to exact task/cycle/proposal hashes without approving source apply."}
    if save: _write_json(MAINTENANCE_TASK_CHECKPOINT_BINDING, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_task_source_apply_lockout(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal, save=False)
    source_policy = build_source_apply_confirmation_policy(project_id=project_id, goal=goal, save=False)
    rollback_policy = build_source_rollback_confirmation_policy(project_id=project_id, goal=goal, save=False)
    backup_quarantine = build_source_apply_backup_quarantine(project_id=project_id, save=False)
    rows = [
        {"name": "queue-selection-approval", "status": "pass" if not selection.get("source_apply_approved") else "blocked", "message": "selection does not approve source apply"},
        {"name": "source-apply-confirmation", "status": "pass" if source_policy.get("writes_source") is False else "blocked", "message": "confirmation policy is read-only until exact source-apply confirmation is supplied"},
        {"name": "rollback-separate", "status": "pass" if rollback_policy.get("rollback_approved") is False else "blocked", "message": "rollback confirmation policy remains separate and unapproved"},
        {"name": "backup-quarantine", "status": _report_gate_status(backup_quarantine), "message": backup_quarantine.get("message", "")},
        {"name": "no-concurrent-source-apply", "status": "pass", "message": "maintenance queue exposes only one task cycle and no source apply write path"},
        {"name": "publish-not-approved", "status": "pass", "message": "False"},
        {"name": "live-apply-not-approved", "status": "pass", "message": "False"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.7", "status": status, "ok": _ok_from(status), "no_concurrent_source_apply": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "steps": {"selection": _compact_step(selection), "source_apply_confirmation_policy": _compact_step(source_policy), "rollback_confirmation_policy": _compact_step(rollback_policy), "backup_quarantine": _compact_step(backup_quarantine)}, "rows": rows, "message": "Maintenance task source-apply lockout keeps queue work separate from exact-confirmed source apply and rollback systems without rerunning the heavyweight source-apply gate."}
    if save: _write_json(MAINTENANCE_TASK_SOURCE_APPLY_LOCKOUT, report)
    else: report["preview_only"] = True
    return report


