def build_maintenance_task_fixture_drill(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    high = _build_maintenance_task_record(project_id=project_id, goal="tighten source-only package privacy around maintenance queue records")
    medium = _build_maintenance_task_record(project_id=project_id, goal="add dashboard and API queue visibility for self-maintenance tasks")
    active = _build_maintenance_task_record(project_id=project_id, goal="improve release dashboard performance", state="cycle_running")
    selected_without_active, active_without_active, _ = _select_next_maintenance_task([high, medium])
    selected_with_active, active_with_active, _ = _select_next_maintenance_task([high, medium, active])
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    scenarios = [
        {"name": "highest-priority-selected", "status": "pass" if selected_without_active and selected_without_active.get("task_id") == high.get("task_id") else "blocked", "message": str(selected_without_active and selected_without_active.get("task_id"))},
        {"name": "no-active-without-active", "status": "pass" if not active_without_active else "blocked", "message": str(len(active_without_active))},
        {"name": "active-blocks-new-selection", "status": "pass" if selected_with_active is None and len(active_with_active) == 1 else "blocked", "message": str(len(active_with_active))},
        {"name": "task-records-unapproved", "status": "pass" if not any(item.get("source_apply_approved") or item.get("publish_approved") or item.get("live_apply_approved") for item in [high, medium, active]) else "blocked", "message": "tasks grant no approval"},
        {"name": "package-privacy", "status": _report_gate_status(privacy), "message": privacy.get("message", "")},
    ]
    status = _status_from(scenarios)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.9", "status": status, "ok": _ok_from(status), "scenarios": scenarios, "rows": scenarios, "message": "Maintenance task fixture drill covers queue ordering, active-task blocking, approval separation, and source-only package privacy."}
    if save: _write_json(MAINTENANCE_TASK_FIXTURE_DRILL, report)
    else: report["preview_only"] = True
    return report


def build_pre_v46_maintenance_queue_gate(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    checks = {
        "task_schema": build_maintenance_task_record_schema(project_id=project_id, save=False),
        "priority_risk": build_maintenance_task_priority_risk_scoring(project_id=project_id, goal=goal, save=False),
        "queue_registry": build_maintenance_task_queue_registry(project_id=project_id, goal=goal, save=False),
        "selection_policy": build_maintenance_task_selection_policy(project_id=project_id, goal=goal, save=False),
        "cycle_orchestrator": build_maintenance_task_cycle_orchestrator(project_id=project_id, goal=goal, save=False),
        "checkpoint_binding": build_maintenance_task_checkpoint_binding(project_id=project_id, goal=goal, save=False),
        "source_apply_lockout": build_maintenance_task_source_apply_lockout(project_id=project_id, goal=goal, save=False),
        "dashboard_api_views": build_maintenance_task_dashboard_api_views(project_id=project_id, goal=goal, save=False),
        "fixture_drill": build_maintenance_task_fixture_drill(project_id=project_id, save=False),
        "privacy_scan": build_package_privacy_scan(project_id=project_id, save=False),
        "route_safety": build_api_route_safety_audit(project_id=project_id, save=False),
    }
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    hard_failures = [row for row in rows if row["status"] == "blocked" and row["name"] not in {"dashboard-api-views"}]
    status = "blocked" if hard_failures else ("warn" if any(row["status"] in {"warn", "blocked"} for row in rows) else "pass")
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v45.10", "status": status, "ok": status != "blocked", "gate_ready": status != "blocked", "maintenance_queue_ready": status != "blocked", "one_cycle_at_a_time": True, "no_concurrent_source_apply": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "steps": {k: _compact_step(v) for k, v in checks.items()}, "rows": rows, "message": "Pre-v46 gate chains task schema, priority/risk scoring, queue registry, selection policy, one-cycle orchestration, checkpoint binding, source-apply lockout, dashboard/API visibility, fixtures, privacy, and route safety."}
    if save: _write_json(PRE_V46_MAINTENANCE_QUEUE_GATE, report)
    else: report["preview_only"] = True
    return report


def build_controlled_self_maintenance_work_queue(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal, save=save)
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal, save=False)
    orchestrator = build_maintenance_task_cycle_orchestrator(project_id=project_id, goal=goal, save=save)
    checkpoint = build_maintenance_task_checkpoint_binding(project_id=project_id, goal=goal, save=False)
    lockout = build_maintenance_task_source_apply_lockout(project_id=project_id, goal=goal, save=False)
    gate = {"stage": "v45.10", "status": "warn", "ok": True, "message": "Run --pre-v46-maintenance-queue-gate for the full heavy queue gate; this v46 loop uses compact queue orchestration."}
    rows = [
        {"name": "queue-registry", "status": _report_gate_status(registry), "message": registry.get("message", "")},
        {"name": "selection-policy", "status": _report_gate_status(selection), "message": selection.get("message", "")},
        {"name": "one-cycle-orchestrator", "status": _report_gate_status(orchestrator), "message": orchestrator.get("message", "")},
        {"name": "checkpoint-binding", "status": _report_gate_status(checkpoint), "message": checkpoint.get("message", "")},
        {"name": "source-apply-lockout", "status": _report_gate_status(lockout), "message": lockout.get("message", "")},
        {"name": "pre-v46-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "publish-not-approved", "status": "pass", "message": "False"},
        {"name": "live-apply-not-approved", "status": "pass", "message": "False"},
    ]
    hard_failures = [row for row in rows if row["status"] == "blocked"]
    status = "blocked" if hard_failures else ("warn" if any(row["status"] == "warn" for row in rows) else "pass")
    selected = selection.get("selected_task") or orchestrator.get("selected_task")
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.0", "status": status, "ok": status != "blocked", "maintenance_work_queue_ready": status != "blocked", "task_count": registry.get("task_count"), "selected_task_id": selected.get("task_id") if isinstance(selected, dict) else None, "selected_goal": selected.get("goal") if isinstance(selected, dict) else None, "cycle_id": orchestrator.get("cycle_id"), "proposal_id": orchestrator.get("proposal_id"), "one_cycle_at_a_time": True, "no_concurrent_source_apply": True, "requires_human_checkpoint": True, "source_apply_requires_confirmation": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "runtime_records_source_only_excluded": True, "next_actions": ["Review the selected maintenance task and its sandbox diff", "Run --pre-v46-maintenance-queue-gate for the full gate", "Complete the human checkpoint for the exact task/cycle/proposal binding", "Use guarded --apply-reviewed-patch only with exact confirmation if the reviewed artifact set is approved"], "steps": {"registry": _compact_step(registry), "selection": _compact_step(selection), "orchestrator": _compact_step(orchestrator), "checkpoint": _compact_step(checkpoint), "lockout": _compact_step(lockout), "pre_v46_gate": _compact_step(gate)}, "rows": rows, "message": "Controlled self-maintenance work queue can track multiple supervised maintenance tasks, select one cycle at a time, bind checkpoints per task, and keep source apply/publish/live approval separate."}
    if save: _write_json(CONTROLLED_SELF_MAINTENANCE_WORK_QUEUE, report)
    else: report["preview_only"] = True
    return report


