_REPORT_CACHE: dict[str, dict[str, Any]] = {}


def _age_seconds(iso_value: str | None) -> int | None:
    if not iso_value:
        return None
    try:
        return max(0, int((datetime.now() - datetime.fromisoformat(str(iso_value))).total_seconds()))
    except (TypeError, ValueError):
        return None


def _cached_report(cache_key: str, ttl_seconds: int, builder: Any) -> dict[str, Any]:
    now = _now()
    cached = _REPORT_CACHE.get(cache_key)
    if cached:
        age = _age_seconds(str(cached.get("cached_at")))
        if age is not None and age <= ttl_seconds:
            payload = dict(cached.get("payload") or {})
            payload["served_from_cache"] = True
            payload["cache_key"] = cache_key
            payload["cache_age_seconds"] = age
            payload["cache_checked_at"] = now
            return payload
    payload = builder()
    payload["served_from_cache"] = False
    payload["cache_key"] = cache_key
    payload["cache_age_seconds"] = 0
    payload["cache_checked_at"] = now
    _REPORT_CACHE[cache_key] = {"cached_at": now, "payload": payload}
    return dict(payload)


def build_autonomy_queue_report_cache(project_id: str = "eidolon", goal: str | None = None, ttl_seconds: int = 60, save: bool = True) -> dict[str, Any]:
    """v46.2: cache expensive autonomy/queue summaries and expose freshness metadata."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
    summaries = {
        "boundary": _cached_report(f"boundary:{project_id}", ttl_seconds, lambda: summarize_self_maintenance_report(build_autonomy_readiness_boundary_system(project_id=project_id, save=False))),
        "queue_registry": _cached_report(f"queue-registry:{project_id}:{goal_text}", ttl_seconds, lambda: summarize_self_maintenance_report(build_maintenance_task_queue_registry(project_id=project_id, goal=goal_text, save=False))),
        "selection": _cached_report(f"selection:{project_id}:{goal_text}", ttl_seconds, lambda: summarize_self_maintenance_report(build_maintenance_task_selection_policy(project_id=project_id, goal=goal_text, save=False))),
        "controlled_queue": _cached_report(f"controlled-queue:{project_id}:{goal_text}", ttl_seconds, lambda: summarize_self_maintenance_report(build_controlled_self_maintenance_work_queue(project_id=project_id, goal=goal_text, save=False))),
    }
    rows = [
        {"name": name.replace("_", "-"), "status": "pass" if summary.get("ok", summary.get("status") != "blocked") else "blocked", "message": f"cached={summary.get('served_from_cache')} age={summary.get('cache_age_seconds')}s status={summary.get('status')}"}
        for name, summary in summaries.items()
    ]
    rows += [
        {"name": "freshness-timestamps", "status": "pass" if all(summary.get("cache_checked_at") for summary in summaries.values()) else "blocked", "message": "cache_checked_at present for every summary"},
        {"name": "get-safe-cache", "status": "pass", "message": "dashboard/API GET callers use save=False; cache is process-local and does not approve actions"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.2", "status": status, "ok": _ok_from(status), "goal": goal_text, "ttl_seconds": ttl_seconds, "summaries": summaries, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Autonomy and maintenance queue reports can be cached with explicit freshness metadata so the dashboard stays fast without treating stale summaries as approval."}
    if save: _write_json(AUTONOMY_REPORT_CACHE, report)
    else: report["preview_only"] = True
    return report


def _find_maintenance_task(project_id: str = "eidolon", task_id: str | None = None, goal: str | None = None) -> dict[str, Any]:
    tasks = _load_maintenance_tasks(project_id=project_id, goal=goal)
    if task_id:
        for task in tasks:
            if str(task.get("task_id")) == str(task_id):
                return task
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal, save=False)
    selected = selection.get("selected_task") or (selection.get("active_tasks") or [{}])[0]
    if isinstance(selected, dict) and selected.get("task_id"):
        return selected
    return tasks[0] if tasks else _build_maintenance_task_record(project_id=project_id, goal=goal)


def build_maintenance_task_drilldown_view(project_id: str = "eidolon", task_id: str | None = None, goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v46.3: detailed task inspection with hashes and checkpoint binding."""
    task = _find_maintenance_task(project_id=project_id, task_id=task_id, goal=goal)
    task_goal = str(task.get("goal") or _autonomy_goal(goal))
    cycle = build_maintenance_task_cycle_orchestrator(project_id=project_id, goal=task_goal, save=False)
    checkpoint = build_maintenance_task_checkpoint_binding(project_id=project_id, goal=task_goal, task_id=str(task.get("task_id") or ""), save=False)
    receipt = {
        "task_hash": _sha256_text(task),
        "cycle_hash": _sha256_text({"cycle_id": cycle.get("cycle_id"), "proposal_id": cycle.get("proposal_id"), "goal": task_goal}),
        "checkpoint_hash": _sha256_text(checkpoint),
        "proposal_hash": (checkpoint.get("binding") or {}).get("proposal_hash"),
    }
    rows = [
        {"name": "task-found", "status": "pass" if task.get("task_id") else "blocked", "message": str(task.get("task_id", ""))},
        {"name": "cycle-bound", "status": _report_gate_status(cycle), "message": str(cycle.get("cycle_id", ""))},
        {"name": "checkpoint-bound", "status": _report_gate_status(checkpoint), "message": str((checkpoint.get("binding") or {}).get("binding_id", ""))},
        {"name": "hashes-present", "status": "pass" if all(receipt.get(k) for k in ("task_hash", "cycle_hash", "checkpoint_hash", "proposal_hash")) else "warn", "message": "task/cycle/checkpoint/proposal hash view"},
        {"name": "approval-boundaries", "status": "pass" if not any(task.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "drilldown does not approve actions"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.3", "status": status, "ok": _ok_from(status), "task": task, "cycle": summarize_self_maintenance_report(cycle), "checkpoint": summarize_self_maintenance_report(checkpoint), "receipt": receipt, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Maintenance task drill-down exposes the exact task/cycle/checkpoint/proposal binding without mutating source or granting approvals."}
    if save: _write_json(MAINTENANCE_TASK_DRILLDOWN_VIEW, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_queue_stale_state_warnings(project_id: str = "eidolon", goal: str | None = None, task_id: str | None = None, max_cache_age_seconds: int = 300, save: bool = True) -> dict[str, Any]:
    """v46.4: identify stale queue/cache/checkpoint states before they are mistaken for approval."""
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal, save=False)
    drill = build_maintenance_task_drilldown_view(project_id=project_id, task_id=task_id, goal=goal, save=False)
    cache = build_autonomy_queue_report_cache(project_id=project_id, goal=goal, ttl_seconds=60, save=False)
    queue_hash = _sha256_text(registry.get("tasks", []))
    task_hash = (drill.get("receipt") or {}).get("task_hash")
    cache_ages = [int((summary or {}).get("cache_age_seconds") or 0) for summary in (cache.get("summaries") or {}).values()]
    stale_cache = any(age > max_cache_age_seconds for age in cache_ages)
    warnings = []
    if stale_cache:
        warnings.append("cached report older than freshness threshold")
    if registry.get("status") == "warn":
        warnings.append("queue registry returned warning state")
    if not task_hash:
        warnings.append("selected task hash missing")
    rows = [
        {"name": "queue-hash", "status": "pass" if queue_hash else "blocked", "message": queue_hash[:16]},
        {"name": "selected-task-hash", "status": "pass" if task_hash else "warn", "message": str(task_hash or "missing")[:16]},
        {"name": "cache-freshness", "status": "warn" if stale_cache else "pass", "message": f"max_age={max(cache_ages) if cache_ages else 0}s threshold={max_cache_age_seconds}s"},
        {"name": "dry-run-is-not-approval", "status": "pass", "message": "dry-run summaries never authorize apply"},
        {"name": "warning-count", "status": "warn" if warnings else "pass", "message": str(len(warnings))},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.4", "status": status, "ok": status != "blocked", "queue_hash": queue_hash, "selected_task_hash": task_hash, "warnings": warnings, "cache_max_age_seconds": max(cache_ages) if cache_ages else 0, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Stale-state warnings make cache age, queue hash, selected task hash, and dry-run/approval separation visible before an operator acts."}
    if save: _write_json(MAINTENANCE_QUEUE_STALE_STATE_WARNINGS, report)
    else: report["preview_only"] = True
    return report


def build_maintenance_runtime_privacy_audit(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v46.5: explicitly audit runtime autonomy/queue/attention exclusions from source-only packages."""
    inventory = build_package_inventory(project_id=project_id, save=False)
    included = [str(item.get("path") or item) for item in inventory.get("included", [])]
    source_text = (ROOT_DIR / "conscious_agent" / "release_packaging.py").read_text(encoding="utf-8", errors="replace")
    install_text = (ROOT_DIR / "conscious_agent" / "release_installation.py").read_text(encoding="utf-8", errors="replace")
    forbidden_prefixes = ["data/autonomy/", "data/self_maintenance/", "data/release_package/", "data/releases/", "data/patches/", "data/watch_reports/"]
    leaked = [path for path in included if any(path.startswith(prefix) for prefix in forbidden_prefixes)]
    rows = [
        {"name": "no-runtime-leaks", "status": "pass" if not leaked else "blocked", "message": ", ".join(leaked[:6]) or "no runtime/private paths included"},
        {"name": "autonomy-excluded", "status": "pass" if ("data/autonomy" in source_text or '("data", "autonomy")' in source_text) else "warn", "message": "release_packaging mentions data/autonomy exclusion"},
        {"name": "self-maintenance-excluded", "status": "pass" if ("data/self_maintenance" in source_text or '("data", "self_maintenance")' in source_text) else "warn", "message": "release_packaging mentions data/self_maintenance exclusion"},
        {"name": "install-privacy-patterns", "status": "pass" if "data/autonomy/" in install_text and "data/self_maintenance/" in install_text else "warn", "message": "release_installation privacy scan checks autonomy/self-maintenance runtime"},
        {"name": "source-only-profile", "status": "pass" if inventory.get("status") != "blocked" else "blocked", "message": str(inventory.get("message", ""))},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.5", "status": status, "ok": _ok_from(status), "forbidden_prefixes": forbidden_prefixes, "leaked_paths": leaked, "included_count": len(included), "rows": rows, "message": "Runtime privacy audit verifies maintenance queue, self-maintenance, attention, release output, and patch runtime records stay out of source-only packages."}
    if save: _write_json(MAINTENANCE_RUNTIME_PRIVACY_AUDIT, report)
    else: report["preview_only"] = True
    return report


