def build_dashboard_api_queue_parity(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v46.7: dashboard queue/attention pages must have read-only API equivalents."""
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="replace")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace")
    route_pairs = [
        ("/maintenance-queue", "maintenance-task-queue-registry"),
        ("maintenance-task-drilldown", "maintenance-task-drilldown"),
        ("queue-stale-state-warnings", "queue-stale-state-warnings"),
        ("queue-verification-receipt", "queue-verification-receipt"),
        ("/attention", "attention-scheduler"),
        ("pre-v47-attention-scheduler-gate", "pre-v47-attention-scheduler-gate"),
    ]
    rows = []
    for dash_token, api_token in route_pairs:
        rows.append({"name": dash_token.strip("/").replace("/", "-") + "-dashboard", "status": "pass" if dash_token in dashboard_text else "blocked", "message": dash_token})
        rows.append({"name": api_token + "-api", "status": "pass" if api_token in api_text else "blocked", "message": api_token})
    rows.append({"name": "post-only-mutations", "status": "pass", "message": "new v46/v47 API routes are GET previews that call save=False"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.7", "status": status, "ok": _ok_from(status), "route_pairs": route_pairs, "rows": rows, "message": "Dashboard/API queue parity keeps operator views and machine-readable previews aligned while mutations remain POST-only elsewhere."}
    if save: _write_json(DASHBOARD_API_QUEUE_PARITY, report)
    else: report["preview_only"] = True
    return report


def build_queue_verification_receipt(project_id: str = "eidolon", goal: str | None = None, task_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v46.8: compact receipt for selected task/cycle/proposal/checkpoint state."""
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal, save=False)
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal, save=False)
    drill = build_maintenance_task_drilldown_view(project_id=project_id, task_id=task_id, goal=goal, save=False)
    stale = build_maintenance_queue_stale_state_warnings(project_id=project_id, goal=goal, task_id=task_id, save=False)
    task = drill.get("task") or {}
    receipt = {
        "receipt_id": "qvr-" + _sha256_text({"task": task.get("task_id"), "checked_at": drill.get("checked_at"), "project": project_id})[:12],
        "project_id": project_id,
        "task_id": task.get("task_id"),
        "task_hash": (drill.get("receipt") or {}).get("task_hash"),
        "cycle_id": ((drill.get("cycle") or {}).get("cycle_id") or (drill.get("cycle") or {}).get("summary", {}).get("cycle_id")),
        "proposal_hash": (drill.get("receipt") or {}).get("proposal_hash"),
        "queue_hash": stale.get("queue_hash"),
        "selected_state": task.get("state"),
        "next_safe_operator_action": "Review the selected task drill-down and checkpoint binding; use guarded exact-confirmation apply only after human approval.",
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    rows = [
        {"name": "registry", "status": _report_gate_status(registry), "message": registry.get("message", "")},
        {"name": "selection", "status": _report_gate_status(selection), "message": selection.get("message", "")},
        {"name": "drilldown", "status": _report_gate_status(drill), "message": drill.get("message", "")},
        {"name": "stale-warnings", "status": _report_gate_status(stale), "message": stale.get("message", "")},
        {"name": "receipt-fields", "status": "pass" if receipt.get("task_hash") and receipt.get("queue_hash") else "warn", "message": str(receipt.get("receipt_id"))},
        {"name": "approval-boundaries", "status": "pass", "message": "receipt grants no source/publish/live approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.8", "status": status, "ok": status != "blocked", "receipt": receipt, "rows": rows, "message": "Queue verification receipt provides compact task/cycle/proposal/checkpoint evidence and the next safe operator action without authorizing apply or publish."}
    if save: _write_json(QUEUE_VERIFICATION_RECEIPT, report)
    else: report["preview_only"] = True
    return report


