def build_pre_v47_attention_scheduler_gate(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v46.10: final queue/cache/privacy/usability gate before attention scheduling."""
    checks = {
        "report_cache": build_autonomy_queue_report_cache(project_id=project_id, goal=goal, save=False),
        "task_drilldown": build_maintenance_task_drilldown_view(project_id=project_id, goal=goal, save=False),
        "stale_warnings": build_maintenance_queue_stale_state_warnings(project_id=project_id, goal=goal, save=False),
        "runtime_privacy": build_maintenance_runtime_privacy_audit(project_id=project_id, save=False),
        "command_palette": build_operator_command_palette_report(project_id=project_id, save=False),
        "dashboard_api_parity": build_dashboard_api_queue_parity(project_id=project_id, save=False),
        "receipt": build_queue_verification_receipt(project_id=project_id, goal=goal, save=False),
        "compact_layout": build_dashboard_accessibility_compact_layout(project_id=project_id, save=False),
        "pre_v46_gate": build_pre_v46_maintenance_queue_gate(project_id=project_id, goal=goal, save=False),
    }
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    hard = [row for row in rows if row["status"] == "blocked"]
    status = "blocked" if hard else ("warn" if any(row["status"] == "warn" for row in rows) else "pass")
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v46.10", "status": status, "ok": status != "blocked", "gate_ready": status != "blocked", "attention_scheduler_ready": status != "blocked", "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "steps": {k: _compact_step(v) for k, v in checks.items()}, "rows": rows, "message": "Pre-v47 gate verifies caching, task drill-down, stale warnings, runtime privacy, command palette usability, dashboard/API parity, receipts, compact layout, and the v46 queue gate."}
    if save: _write_json(PRE_V47_ATTENTION_SCHEDULER_GATE, report)
    else: report["preview_only"] = True
    return report


def _attention_budget_records(project_id: str = "eidolon") -> list[dict[str, Any]]:
    from self_maintenance_attention_primitives import attention_budget_records
    return attention_budget_records(project_id)


def _attention_score_task(task: dict[str, Any], now_iso: str) -> dict[str, Any]:
    # v1253.4 retains the historical private seam while moving pure scoring out
    # of the authority-owning self-maintenance module.
    from self_maintenance_attention_primitives import attention_score_task
    return attention_score_task(task, now_iso, age_seconds=_age_seconds)

def build_controlled_attention_scheduler(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.0: supervised attention scheduler for maintenance queue focus."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
    gate = {"stage": "v46.10", "status": "pass", "ok": True, "message": "Run --pre-v47-attention-scheduler-gate for the full queue/cache/privacy/usability gate; this v47 scheduler uses a compact focus-selection check."}
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal_text, save=False)
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal_text, save=False)
    tasks = registry.get("tasks") or []
    now_iso = _now()
    scored = sorted([_attention_score_task(task, now_iso) for task in tasks], key=lambda item: (-int(item.get("attention_score") or 0), str(item.get("task_id") or "")))
    active = selection.get("active_tasks") or []
    focus = None
    if active:
        active_id = str(active[0].get("task_id"))
        focus = next((item for item in scored if str(item.get("task_id")) == active_id), None)
    if focus is None:
        focus = next((item for item in scored if item.get("decision") == "candidate_focus"), scored[0] if scored else None)
    deferred = [item for item in scored if item.get("decision") in {"defer_for_human_review", "surface_blocker"}]
    attention_record = {
        "schema_version": "eidolon.attention_scheduler.v1",
        "project_id": project_id,
        "created_at": now_iso,
        "goal": goal_text,
        "budgets": _attention_budget_records(project_id),
        "focus_task": focus,
        "scored_tasks": scored,
        "deferred_tasks": deferred,
        "interruption_policy": {"no_parallel_source_apply": True, "resume_active_task_first": True, "operator_override_required_for_high_risk": True},
        "daily_summary": f"Focus {focus.get('task_id') if focus else '[none]'} because {focus.get('reason') if focus else 'no eligible task'}.",
        "weekly_summary": "Queue attention is budgeted across maintenance, reflection, project work, and reserve capacity; approvals remain external.",
        "runtime_only": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    if save:
        AUTONOMY_ATTENTION_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic((AUTONOMY_ATTENTION_DIR / "latest_attention_schedule.json"), json.dumps(attention_record, indent=2, default=str), encoding="utf-8")
    rows = [
        {"name": "pre-v47-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "budget-records", "status": "pass" if len(attention_record["budgets"]) >= 4 else "blocked", "message": str(len(attention_record["budgets"]))},
        {"name": "task-scoring", "status": "pass" if scored else "warn", "message": f"{len(scored)} task(s) scored"},
        {"name": "focus-selected", "status": "pass" if focus else "warn", "message": str(focus.get("task_id") if focus else "none")},
        {"name": "deferral-rules", "status": "pass", "message": f"{len(deferred)} deferred/blocker task(s) surfaced"},
        {"name": "one-cycle-at-a-time", "status": "pass", "message": "attention selects focus; it does not run concurrent source apply"},
        {"name": "approval-boundaries", "status": "pass", "message": "attention records grant no source/publish/live approval"},
    ]
    hard = [row for row in rows if row["status"] == "blocked"]
    status = "blocked" if hard else ("warn" if any(row["status"] == "warn" for row in rows) else "pass")
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": now_iso, "project_id": project_id, "stage": "v47.0", "status": status, "ok": status != "blocked", "attention_scheduler_ready": status != "blocked", "attention_record": attention_record, "gate": summarize_self_maintenance_report(gate), "rows": rows, "message": "Controlled attention scheduler scores supervised maintenance tasks, applies budgets and deferral rules, preserves one-cycle-at-a-time focus, and never approves source, publish, or live actions."}
    if save: _write_json(CONTROLLED_ATTENTION_SCHEDULER, report)
    else: report["preview_only"] = True
    return report




def _attention_selected_explanation(focus: dict[str, Any] | None) -> str:
    if not focus:
        return "No eligible focus task was selected."
    codes = ", ".join(focus.get("reason_codes") or [])
    return f"Selected {focus.get('task_id')} with attention_score={focus.get('attention_score')} because {focus.get('reason')}. Reason codes: {codes}."


def _attention_receipt_task_row(item: dict[str, Any]) -> dict[str, Any]:
    return {
        "task_id": item.get("task_id"),
        "decision": item.get("decision"),
        "attention_score": item.get("attention_score"),
        "priority_score": item.get("priority_score"),
        "risk_score": item.get("risk_score"),
        "state": item.get("state"),
        "reason": item.get("reason"),
        "reason_codes": item.get("reason_codes") or [],
        "next_safe_action": item.get("next_safe_action"),
    }


def build_attention_selection_receipt(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.1: explain why the attention scheduler selected, deferred, or surfaced tasks."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
    scheduler = build_controlled_attention_scheduler(project_id=project_id, goal=goal_text, save=False)
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal_text, save=False)
    selection = build_maintenance_task_selection_policy(project_id=project_id, goal=goal_text, save=False)
    record = scheduler.get("attention_record") or {}
    focus = record.get("focus_task") or None
    scored = record.get("scored_tasks") or []
    decisions = [_attention_receipt_task_row(item) for item in scored]
    deferred = [row for row in decisions if row.get("decision") == "defer_for_human_review"]
    blocked = [row for row in decisions if row.get("decision") == "surface_blocker" or row.get("state") == "blocked"]
    resurfaced = [row for row in decisions if row.get("decision") == "resume_active_task" or "freshness.aged_queue_item" in (row.get("reason_codes") or [])]
    basis = {
        "scheduler_hash": _sha256_text(record),
        "queue_registry_hash": _sha256_text(registry.get("tasks") or []),
        "selection_hash": _sha256_text(selection.get("selected_task") or selection),
        "focus_hash": _sha256_text(focus or {}),
    }
    receipt = {
        "schema_version": "eidolon.attention_selection_receipt.v1",
        "receipt_id": "attention-receipt-" + _sha256_text({"project_id": project_id, "goal": goal_text, "focus": focus, "basis": basis})[:12],
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "selected_task": _attention_receipt_task_row(focus or {}) if focus else None,
        "why_this_task_now": _attention_selected_explanation(focus),
        "decision_rows": decisions,
        "deferred_tasks": deferred,
        "blocked_tasks": blocked,
        "resurfaced_tasks": resurfaced,
        "basis_hashes": basis,
        "queue_registry_summary": summarize_self_maintenance_report(registry),
        "selection_summary": summarize_self_maintenance_report(selection),
        "next_safe_operator_action": (focus or {}).get("next_safe_action") or "Run the pre-v47.1 attention receipt gate and inspect the queue before applying anything.",
        "approval_boundary_notice": "Attention receipts explain focus only; they do not approve source apply, rollback, publish, or live actions.",
        "runtime_only": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    rows = [
        {"name": "scheduler-ready", "status": _report_gate_status(scheduler), "message": scheduler.get("message", "")},
        {"name": "selected-explanation", "status": "pass" if receipt.get("why_this_task_now") else "warn", "message": str(receipt.get("why_this_task_now", ""))[:160]},
        {"name": "reason-codes", "status": "pass" if all(row.get("reason_codes") for row in decisions) else "warn", "message": f"{sum(1 for row in decisions if row.get('reason_codes'))}/{len(decisions)} decision row(s) explainable"},
        {"name": "deferred-and-blocked", "status": "pass", "message": f"{len(deferred)} deferred, {len(blocked)} blocked, {len(resurfaced)} resurfaced"},
        {"name": "basis-hashes", "status": "pass" if all(basis.values()) else "blocked", "message": ", ".join(sorted(basis))},
        {"name": "approval-boundaries", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "receipt explains focus only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v47.1", "status": status, "ok": _ok_from(status), "attention_receipt_ready": _ok_from(status), "attention_receipt": receipt, "rows": rows, "message": "Attention selection receipt records why a task was selected, deferred, blocked, or resurfaced without granting source, publish, rollback, or live approval."}
    if save:
        _write_json(ATTENTION_SELECTION_RECEIPT, report)
    else:
        report["preview_only"] = True
    return report


def build_pre_v47_1_attention_receipt_gate(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.1 gate: attention explainability surfaces exist and remain read-only/safe."""
