# v47.2-v48.0 attention budget, deferral, resume, and reflection scaffolding
# ---------------------------------------------------------------------------


def _attention_task_cost(item: dict[str, Any]) -> dict[str, Any]:
    """Estimate supervised focus cost for a scored task without granting authority."""
    risk = int(item.get("risk_score") or 0)
    priority = int(item.get("priority_score") or 0)
    state = str(item.get("state") or "queued")
    decision = str(item.get("decision") or "candidate_focus")
    base = 12
    risk_units = max(0, risk // 5)
    priority_units = 6 if priority >= 80 else (4 if priority >= 60 else 2)
    state_units = 8 if state in {"cycle_running", "checkpoint_required", "apply_handoff_ready", "blocked"} else 0
    approval_boundary_units = 10 if state in {"apply_handoff_ready", "checkpoint_required"} or risk >= 70 else 0
    raw_cost = base + risk_units + priority_units + state_units + approval_boundary_units
    risk_multiplier = 1.0 + (risk / 100.0)
    risk_adjusted = int(round(raw_cost * risk_multiplier))
    return {
        "task_id": item.get("task_id"),
        "raw_focus_cost": raw_cost,
        "risk_multiplier": round(risk_multiplier, 2),
        "risk_adjusted_cost": risk_adjusted,
        "cost_reasons": [
            f"base={base}",
            f"risk_units={risk_units}",
            f"priority_units={priority_units}",
            f"state_units={state_units}",
            f"approval_boundary_units={approval_boundary_units}",
            f"decision={decision}",
        ],
        "requires_operator_review": bool(risk >= 70 or state in {"checkpoint_required", "apply_handoff_ready", "blocked"}),
    }


def build_attention_budget_ledger(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.2: account for limited supervised attention without approving actions."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
    scheduler = build_controlled_attention_scheduler(project_id=project_id, goal=goal_text, save=False)
    receipt = build_attention_selection_receipt(project_id=project_id, goal=goal_text, save=False)
    record = scheduler.get("attention_record") or {}
    scored = record.get("scored_tasks") or []
    focus = record.get("focus_task") or None
    cost_rows = []
    for item in scored:
        cost = _attention_task_cost(item)
        row = dict(item)
        row.update(cost)
        cost_rows.append(row)
    focus_cost = next((row for row in cost_rows if focus and row.get("task_id") == focus.get("task_id")), None)
    session_budget = 100
    daily_budget = 300
    session_spent_before = 0
    daily_spent_before = 0
    selected_cost = int((focus_cost or {}).get("risk_adjusted_cost") or 0)
    session_remaining_before = max(0, session_budget - session_spent_before)
    daily_remaining_before = max(0, daily_budget - daily_spent_before)
    budget_exceeded = selected_cost > session_remaining_before or selected_cost > daily_remaining_before
    deferred_due_budget = [row for row in cost_rows if int(row.get("risk_adjusted_cost") or 0) > session_remaining_before]
    ledger = {
        "schema_version": "eidolon.attention_budget_ledger.v1",
        "budget_id": "attention-budget-" + _sha256_text({"project_id": project_id, "goal": goal_text, "focus": focus, "cost": focus_cost})[:12],
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "session_budget_units": session_budget,
        "daily_budget_units": daily_budget,
        "session_spent_before": session_spent_before,
        "daily_spent_before": daily_spent_before,
        "selected_task_id": (focus or {}).get("task_id"),
        "selected_task_cost": selected_cost,
        "selected_raw_focus_cost": int((focus_cost or {}).get("raw_focus_cost") or 0),
        "selected_risk_multiplier": (focus_cost or {}).get("risk_multiplier"),
        "budget_remaining_before": min(session_remaining_before, daily_remaining_before),
        "budget_remaining_after": max(0, min(session_remaining_before, daily_remaining_before) - selected_cost),
        "budget_status": "blocked_by_budget" if budget_exceeded else "within_budget",
        "budget_reason_code": "budget.defer.cost_exceeds_remaining" if budget_exceeded else "budget.within_session_and_daily_limits",
        "task_costs": cost_rows,
        "deferred_due_budget": deferred_due_budget,
        "receipt_id": (receipt.get("attention_receipt") or {}).get("receipt_id"),
        "runtime_only": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "message": "Attention budgeting tracks focus cost only; it does not approve source, publish, rollback, or live actions.",
    }
    rows = [
        {"name": "scheduler-ready", "status": _report_gate_status(scheduler), "message": scheduler.get("message", "")},
        {"name": "budget-id", "status": "pass" if ledger.get("budget_id") else "blocked", "message": str(ledger.get("budget_id"))},
        {"name": "selected-cost", "status": "pass" if selected_cost >= 0 else "blocked", "message": str(selected_cost)},
        {"name": "remaining-after", "status": "warn" if budget_exceeded else "pass", "message": str(ledger.get("budget_remaining_after"))},
        {"name": "budget-defer-reasons", "status": "pass", "message": f"{len(deferred_due_budget)} task(s) exceed the current session budget"},
        {"name": "approval-boundaries", "status": "pass" if not any(ledger.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "budget grants no permission"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v47.2", "status": status, "ok": status != "blocked", "attention_budget_ledger": ledger, "rows": rows, "message": "Attention budget ledger estimates focus cost, remaining budget, and budget-based deferrals without granting apply or publish authority."}
    if save:
        _write_json(ATTENTION_BUDGET_LEDGER, report)
        AUTONOMY_ATTENTION_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic((AUTONOMY_ATTENTION_DIR / "latest_attention_budget_ledger.json"), json.dumps(ledger, indent=2, default=str), encoding="utf-8")
    else:
        report["preview_only"] = True
    return report


def build_deferred_task_memory(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.3: runtime-only memory of why tasks were deferred and when to resurface."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
    receipt = build_attention_selection_receipt(project_id=project_id, goal=goal_text, save=False)
    ledger = build_attention_budget_ledger(project_id=project_id, goal=goal_text, save=False)
    receipt_payload = receipt.get("attention_receipt") or {}
    budget_payload = ledger.get("attention_budget_ledger") or {}
    deferred_source = list(receipt_payload.get("deferred_tasks") or [])
    for row in budget_payload.get("deferred_due_budget") or []:
        if not any(item.get("task_id") == row.get("task_id") for item in deferred_source):
            deferred_source.append(row)
    records = []
    for item in deferred_source:
        codes = list(item.get("reason_codes") or [])
        if item.get("budget_reason_code"):
            codes.append(str(item.get("budget_reason_code")))
        if int(item.get("risk_score") or 0) >= 70 and "risk.high.operator_review_required" not in codes:
            codes.append("risk.high.operator_review_required")
        if int(item.get("risk_adjusted_cost") or 0) > int(budget_payload.get("budget_remaining_before") or 0):
            codes.append("budget.defer.cost_exceeds_remaining")
        records.append({
            "memory_id": "deferred-" + _sha256_text({"task": item.get("task_id"), "codes": codes, "goal": goal_text})[:12],
            "task_id": item.get("task_id"),
            "decision": item.get("decision") or "deferred",
            "deferred_reason_codes": sorted(set(codes)) or ["deferred.reason.unspecified"],
            "deferred_reason": item.get("reason") or "Task was deferred by the attention scheduler.",
            "resurface_after": "next attention review or after operator clears blocker/budget limit",
            "still_valid_if": ["task remains queued or blocked", "operator has not approved source apply", "budget/state has not materially changed"],
            "next_safe_action": item.get("next_safe_action") or "Inspect the task before scheduling another cycle.",
        })
    rows = [
        {"name": "receipt-ready", "status": _report_gate_status(receipt), "message": receipt.get("message", "")},
        {"name": "budget-ready", "status": _report_gate_status(ledger), "message": ledger.get("message", "")},
        {"name": "deferred-records", "status": "pass" if records is not None else "blocked", "message": str(len(records))},
        {"name": "runtime-only", "status": "pass", "message": "deferred task memory is advisory runtime state, not durable identity memory"},
        {"name": "approval-boundaries", "status": "pass", "message": "deferred records grant no source/publish/live approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v47.3", "status": status, "ok": _ok_from(status), "deferred_memory": {"schema_version": "eidolon.deferred_task_memory.v1", "goal": goal_text, "records": records, "runtime_only": True, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False}, "rows": rows, "message": "Deferred task memory records why tasks were deferred and when to resurface them, without writing durable identity memory or approving actions."}
    if save:
        _write_json(DEFERRED_TASK_MEMORY, report)
        AUTONOMY_ATTENTION_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic((AUTONOMY_ATTENTION_DIR / "latest_deferred_task_memory.json"), json.dumps(report["deferred_memory"], indent=2, default=str), encoding="utf-8")
    else:
        report["preview_only"] = True
    return report


def build_blocked_task_handling(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.4: classify blocked/high-risk attention tasks and provide safe remedies."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
    registry = build_maintenance_task_queue_registry(project_id=project_id, goal=goal_text, save=False)
    deferred = build_deferred_task_memory(project_id=project_id, goal=goal_text, save=False)
    tasks = registry.get("tasks") or []
    blocked = []
    for task in tasks:
        risk = int(task.get("risk_score") or 0)
        state = str(task.get("state") or "queued")
        if state == "blocked" or risk >= 70:
            reason = "state.blocked" if state == "blocked" else "risk.high.operator_review_required"
            blocked.append({
                "blocked_id": "blocked-" + _sha256_text({"task": task.get("task_id"), "reason": reason})[:12],
                "task_id": task.get("task_id"),
                "goal": task.get("goal"),
                "blocked_state": state if state == "blocked" else "high_risk_review_required",
                "reason_code": reason,
                "operator_requirement": "human review required before any execution or source-apply handoff",
                "safe_remedy": "inspect task drill-down, resolve checkpoint/proposal/risk issue, then rerun attention receipt gate",
                "unsafe_shortcut": "do not convert blocked/risk state into source, publish, rollback, or live approval",
            })
    rows = [
        {"name": "queue-registry", "status": _report_gate_status(registry), "message": registry.get("message", "")},
        {"name": "deferred-memory", "status": _report_gate_status(deferred), "message": deferred.get("message", "")},
        {"name": "blocked-taxonomy", "status": "pass", "message": "needs_operator_review, stale_checkpoint, high_risk, waiting_for_verification, unsafe_approval_boundary"},
        {"name": "blocked-count", "status": "pass", "message": str(len(blocked))},
        {"name": "approval-boundaries", "status": "pass", "message": "blocked handling never approves actions"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v47.4", "status": status, "ok": status != "blocked", "blocked_tasks": blocked, "blocked_state_taxonomy": ["needs_operator_review", "missing_checkpoint", "stale_proposal", "high_risk", "waiting_for_verification", "unsafe_approval_boundary"], "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Blocked task handling surfaces unsafe or high-risk attention candidates with operator remedies and no approval leakage."}
    if save:
        _write_json(BLOCKED_TASK_HANDLING, report)
    else:
        report["preview_only"] = True
    return report


def build_attention_resume_context(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v47.5: assemble context needed to resume the selected attention task safely."""
    goal_text = _autonomy_goal(goal or "improve release dashboard performance")
