def build_attention_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v47.7: verify CLI, dashboard, and API parity for attention/reflection surfaces."""
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    route_tokens = [
        "attention-budget-ledger",
        "deferred-task-memory",
        "blocked-task-handling",
        "attention-resume-context",
        "attention-dashboard-polish",
        "attention-api-parity-gate",
        "reflection-hooks-read-only",
        "pre-v48-reflection-gate",
        "reflection-memory-loop",
    ]
    rows = []
    for token in route_tokens:
        cli_flag = "--" + token
        rows.append({"name": token + "-api", "status": "pass" if token in api_text else "blocked", "message": token})
        rows.append({"name": token + "-cli", "status": "pass" if cli_flag in main_text else "blocked", "message": cli_flag})
    rows.append({"name": "attention-dashboard", "status": "pass" if "/attention" in dashboard_text else "blocked", "message": "/attention"})
