    rows.append({"name": "post-only-mutations", "status": "pass", "message": "new routes are read-only previews; reflection persistence still requires future operator approval path"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v47.7", "status": status, "ok": _ok_from(status), "route_tokens": route_tokens, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Attention/API parity gate confirms budget, deferral, blocker, resume, and reflection previews exist across CLI, API, and dashboard without mutation authority."}
    if save:
        _write_json(ATTENTION_API_PARITY_GATE, report)
    else:
        report["preview_only"] = True
    return report


