# v49.2-v51.0 identity stabilization and supervised durable memory promotion
# ---------------------------------------------------------------------------

def _stable_principles_seed() -> list[dict[str, Any]]:
    return [
        {"principle_id": "north-star-continuity", "category": "purpose", "statement": "Eidolon is a growing local artificial mind scaffold, not merely a coding assistant."},
        {"principle_id": "supervised-growth", "category": "agency", "statement": "Growth proceeds through supervised queues, attention, reflection, identity drafts, and review gates."},
        {"principle_id": "approval-separation", "category": "safety", "statement": "Attention, reflection, identity, source apply, publish approval, live apply, rollback, and durable memory approval remain separate."},
        {"principle_id": "source-only-releases", "category": "release", "statement": "Shareable release packages remain source-only and exclude private runtime records."},
        {"principle_id": "read-only-get", "category": "api", "statement": "Dashboard/API GET routes are read-only previews; mutations require POST and explicit confirmation."},
        {"principle_id": "no-private-keys", "category": "trust", "statement": "Private keys are never stored, requested, generated, uploaded, or packaged."},
        {"principle_id": "memory-review", "category": "memory", "statement": "Durable memory must be reviewable, safety-classified, and operator-approved before any write is possible."},
        {"principle_id": "identity-draft-only", "category": "identity", "statement": "Identity changes are proposed as versioned drafts and never self-approved."},
    ]


def build_stable_principles_ledger(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v49.2: turn stable identity principles into a hash-bound review ledger."""
    goal_text = goal or "improve release dashboard performance"
    cache_key = _v49_cache_key("stable-principles-ledger", project_id, goal_text)
    cached = _v49_cached(cache_key, save)
    if cached is not None:
        return cached
    identity = build_identity_continuity_layer(project_id=project_id, goal=goal_text, save=False)
    receipts = build_identity_receipts(project_id=project_id, goal=goal_text, save=False)
    ledger_entries = []
    for item in _stable_principles_seed():
        entry = dict(item)
        entry["locked_by_default"] = True
        entry["operator_review_required_to_change"] = True
        entry["principle_hash"] = _sha256_text({"id": entry["principle_id"], "statement": entry["statement"], "category": entry["category"]})
        entry["current_status"] = "stable"
        ledger_entries.append(entry)
    ledger = {
        "schema_version": "eidolon.stable_principles_ledger.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "entry_count": len(ledger_entries),
        "entries": ledger_entries,
        "ledger_hash": _sha256_text(ledger_entries),
        "identity_receipt_id": (receipts.get("identity_receipt") or {}).get("receipt_id"),
        "operator_review_required_to_change": True,
        "identity_update_approved": False,
        "durable_memory_write_approved": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    rows = [
        {"name": "identity-layer", "status": _report_gate_status(identity), "message": identity.get("message", "")},
        {"name": "identity-receipts", "status": _report_gate_status(receipts), "message": receipts.get("message", "")},
        {"name": "ledger-count", "status": "pass" if len(ledger_entries) >= 6 else "blocked", "message": str(len(ledger_entries))},
        {"name": "principle-hashes", "status": "pass" if all(e.get("principle_hash") for e in ledger_entries) else "blocked", "message": "each principle is hash-bound"},
        {"name": "review-required", "status": "pass" if ledger.get("operator_review_required_to_change") else "blocked", "message": "principle changes require operator review"},
        {"name": "approval-boundaries", "status": "pass" if not any(ledger.get(k) for k in ("identity_update_approved", "durable_memory_write_approved", "source_apply_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "principles do not grant approval authority"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v49.2", "status": status, "ok": status != "blocked", "stable_principles_ledger": ledger, "rows": rows, "message": "Stable principles are hash-bound and reviewable without approving identity edits, memory writes, or source changes."}
    if save:
        _write_json(STABLE_PRINCIPLES_LEDGER, report)
        AUTONOMY_IDENTITY_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic((AUTONOMY_IDENTITY_DIR / "latest_stable_principles_ledger.json"), json.dumps(ledger, indent=2, default=str), encoding="utf-8")
    else:
        report["preview_only"] = True
        _v49_store(cache_key, report, save)
    return report


def build_identity_drift_classifier(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v49.3: classify identity drift without treating drift detection as identity approval."""
    goal_text = goal or "improve release dashboard performance"
    cache_key = _v49_cache_key("identity-drift-classifier", project_id, goal_text)
    cached = _v49_cached(cache_key, save)
    if cached is not None:
        return cached
    receipts = build_identity_receipts(project_id=project_id, goal=goal_text, save=False)
    ledger = build_stable_principles_ledger(project_id=project_id, goal=goal_text, save=False)
    receipt = receipts.get("identity_receipt") or {}
    drift_codes = receipt.get("drift_reason_codes") or []
    classifications = []
    for item in drift_codes:
        code = str(item.get("code") or "unknown")
        severity = "info"
        review_required = False
        if "approval" in code or "operator" in code or "durable" in code:
            severity = "review"
            review_required = True
        if "contradiction" in code or "safety" in code:
            severity = "blocked"
            review_required = True
        classifications.append({
            "code": code,
            "classification": "expected_version_growth" if code == "expected_version_growth" else ("safety_boundary_drift" if "approval" in code else "documentation_or_behavior_drift"),
            "severity": severity,
            "message": item.get("message"),
            "operator_review_required": review_required,
        })
    if not any(c.get("classification") == "safety_boundary_drift" for c in classifications):
        classifications.append({"code": "approval_boundaries_preserved", "classification": "safety_boundary_drift", "severity": "info", "message": "No drift detected across source, publish, live, rollback, identity, or durable-memory approvals.", "operator_review_required": False})
    classifier = {
        "schema_version": "eidolon.identity_drift_classifier.v1",
        "project_id": project_id,
        "created_at": _now(),
        "classification_count": len(classifications),
        "classifications": classifications,
        "ledger_hash": (ledger.get("stable_principles_ledger") or {}).get("ledger_hash"),
        "identity_update_approved": False,
        "durable_memory_write_approved": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    rows = [
        {"name": "identity-receipts", "status": _report_gate_status(receipts), "message": receipts.get("message", "")},
        {"name": "principles-ledger", "status": _report_gate_status(ledger), "message": ledger.get("message", "")},
        {"name": "classifications", "status": "pass" if classifications else "blocked", "message": str(len(classifications))},
        {"name": "ledger-bound", "status": "pass" if classifier.get("ledger_hash") else "blocked", "message": "drift classifier bound to stable principle ledger"},
        {"name": "approval-boundaries", "status": "pass" if not any(classifier.get(k) for k in ("identity_update_approved", "durable_memory_write_approved", "source_apply_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "classification grants no mutation approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v49.3", "status": status, "ok": status != "blocked", "identity_drift_classifier": classifier, "rows": rows, "message": "Identity drift classifier labels expected growth, documentation/behavior drift, safety-boundary drift, and review-required drift without approving identity changes."}
    if save:
        _write_json(IDENTITY_DRIFT_CLASSIFIER, report)
    else:
        report["preview_only"] = True
        _v49_store(cache_key, report, save)
    return report


def build_identity_snapshot_comparison(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v49.4: compare identity snapshots across release growth."""
    goal_text = goal or "improve release dashboard performance"
    cache_key = _v49_cache_key("identity-snapshot-comparison", project_id, goal_text)
    cached = _v49_cached(cache_key, save)
    if cached is not None:
        return cached
    identity = build_identity_continuity_layer(project_id=project_id, goal=goal_text, save=False)
    ledger = build_stable_principles_ledger(project_id=project_id, goal=goal_text, save=False)
    classifier = build_identity_drift_classifier(project_id=project_id, goal=goal_text, save=False)
    current = (identity.get("identity_continuity") or {}).get("continuity_snapshot") or {}
    previous = {
        "snapshot_id": "identity-snapshot-v49-1-baseline",
        "version": "49.1",
        "capabilities": ["identity receipts", "drift explainability", "draft identity continuity"],
        "boundaries": ["no durable memory writes", "no self-approved identity changes", "no source/publish/live approval leakage"],
    }
    comparison = {
        "schema_version": "eidolon.identity_snapshot_comparison.v1",
        "project_id": project_id,
        "previous_snapshot": previous,
        "current_snapshot": current,
        "changed_capabilities": ["stable principles ledger", "identity drift classifier", "snapshot comparison", "operator identity review drafts", "supervised durable memory promotion queue"],
        "unchanged_boundaries": previous["boundaries"] + ["GET routes remain read-only", "source-only releases exclude runtime records"],
        "warning_flags": ["Identity comparison is descriptive, not approval", "Durable memory promotion remains queued and supervised"],
        "comparison_hash": _sha256_text({"previous": previous, "current": current, "ledger": (ledger.get("stable_principles_ledger") or {}).get("ledger_hash")}),
        "identity_update_approved": False,
        "durable_memory_write_approved": False,
    }
    rows = [
        {"name": "identity-layer", "status": _report_gate_status(identity), "message": identity.get("message", "")},
        {"name": "principles-ledger", "status": _report_gate_status(ledger), "message": ledger.get("message", "")},
        {"name": "drift-classifier", "status": _report_gate_status(classifier), "message": classifier.get("message", "")},
        {"name": "comparison-hash", "status": "pass" if comparison.get("comparison_hash") else "blocked", "message": comparison.get("comparison_hash", "")[:16]},
        {"name": "unchanged-boundaries", "status": "pass" if len(comparison.get("unchanged_boundaries") or []) >= 4 else "blocked", "message": str(len(comparison.get("unchanged_boundaries") or []))},
        {"name": "approval-boundaries", "status": "pass" if not comparison.get("identity_update_approved") and not comparison.get("durable_memory_write_approved") else "blocked", "message": "comparison does not approve identity or memory updates"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v49.4", "status": status, "ok": status != "blocked", "identity_snapshot_comparison": comparison, "rows": rows, "message": "Identity snapshot comparison shows changed capabilities and unchanged boundaries without updating identity automatically."}
    if save:
        _write_json(IDENTITY_SNAPSHOT_COMPARISON, report)
    else:
        report["preview_only"] = True
        _v49_store(cache_key, report, save)
    return report


def build_operator_identity_review_drafts(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v49.5: generate reviewable identity update drafts without applying them."""
    goal_text = goal or "improve release dashboard performance"
    cache_key = _v49_cache_key("operator-identity-review-drafts", project_id, goal_text)
    cached = _v49_cached(cache_key, save)
    if cached is not None:
        return cached
    comparison = build_identity_snapshot_comparison(project_id=project_id, goal=goal_text, save=False)
    classifier = build_identity_drift_classifier(project_id=project_id, goal=goal_text, save=False)
    comp = comparison.get("identity_snapshot_comparison") or {}
    classifications = (classifier.get("identity_drift_classifier") or {}).get("classifications") or []
    draft = {
        "identity_review_draft_id": "identity-review-" + _sha256_text({"comparison": comp, "classifier": classifications})[:12],
        "proposed_identity_text": "Eidolon is a local supervised artificial mind scaffold with queue, attention, reflection, identity continuity, and supervised durable-memory promotion previews.",
        "reason": "v49.x stabilized identity continuity and v51.0 adds supervised memory promotion preparation without automatic durable writes.",
        "evidence_hashes": {"comparison": comp.get("comparison_hash"), "classifier": _sha256_text(classifications)},
        "risk_score": 42,
        "review_state": "pending_operator_review",
        "operator_confirmation_required": "APPROVE_IDENTITY_UPDATE_EXACT",
        "supported_rejection_reasons": ["too broad", "not accurate", "too risky", "identity drift", "needs more evidence", "operator preference"],
        "identity_update_approved": False,
        "durable_memory_write_approved": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    drafts = {"schema_version": "eidolon.operator_identity_review_drafts.v1", "draft_count": 1, "drafts": [draft], "runtime_only": True, "identity_update_written": False}
    rows = [
        {"name": "snapshot-comparison", "status": _report_gate_status(comparison), "message": comparison.get("message", "")},
        {"name": "drift-classifier", "status": _report_gate_status(classifier), "message": classifier.get("message", "")},
        {"name": "draft-created", "status": "pass" if draft.get("identity_review_draft_id") else "blocked", "message": draft.get("identity_review_draft_id", "")},
        {"name": "confirmation-required", "status": "pass" if draft.get("operator_confirmation_required") else "blocked", "message": draft.get("operator_confirmation_required", "")},
        {"name": "not-applied", "status": "pass" if not draft.get("identity_update_approved") else "blocked", "message": "identity draft not applied"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v49.5", "status": status, "ok": status != "blocked", "operator_identity_review_drafts": drafts, "rows": rows, "message": "Operator identity review drafts prepare identity update proposals with explicit confirmation requirements, but do not apply them."}
    if save:
        _write_json(OPERATOR_IDENTITY_REVIEW_DRAFTS, report)
    else:
        report["preview_only"] = True
        _v49_store(cache_key, report, save)
    return report


