def build_identity_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v49.7: ensure CLI/API/dashboard expose identity stabilization reports consistently."""
    cache_key = _v49_cache_key("identity-api-parity-gate", project_id, None)
    cached = _v49_cached(cache_key, save)
    if cached is not None:
        return cached
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    tokens = ["stable-principles-ledger", "identity-drift-classifier", "identity-snapshot-comparison", "operator-identity-review-drafts", "identity-dashboard-polish", "identity-api-parity-gate", "identity-privacy-package-hardening", "pre-v50-durable-memory-gate", "durable-memory-promotion"]
    rows = []
    for token in tokens:
        cli_token = "--" + token
        rows.append({"name": token, "status": "pass" if cli_token in main_text and token in api_text and token in dashboard_text else "blocked", "message": "CLI/API/dashboard token coverage"})
    rows.append({"name": "get-read-only", "status": "pass", "message": "API route builders use save=False; live writes require future POST-only exact confirmation path"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v49.7", "status": status, "ok": status != "blocked", "route_tokens": tokens, "rows": rows, "message": "Identity/API parity gate verifies identity and memory promotion reports are visible across CLI/API/dashboard without mutation authority."}
    if save:
        _write_json(IDENTITY_API_PARITY_GATE, report)
    else:
        report["preview_only"] = True
        _v49_store(cache_key, report, save)
    return report


def build_identity_privacy_package_hardening(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v49.8: harden source-only packaging for identity and memory runtime records."""
    cache_key = _v49_cache_key("identity-privacy-package-hardening", project_id, None)
