def build_memory_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v50.7: verify CLI/API/dashboard parity for memory promotion and durable write surfaces."""
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="ignore")
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="ignore")
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")
    required = ["memory-promotion-receipts", "memory-promotion-deduplication", "memory-rejection-runtime-ledger", "memory-promotion-confirmation-gate", "memory-removal-drafts", "pre-v51-durable-write-gate", "durable-memory-write"]
    rows = []
    for name in required:
        rows.append({"name": f"api-{name}", "status": "pass" if name in api_text else "blocked", "message": name})
        rows.append({"name": f"cli-{name}", "status": "pass" if f"--{name}" in main_text else "blocked", "message": name})
    rows.append({"name": "dashboard-memory", "status": "pass" if "/memory" in dashboard_text and "memory-promotion-receipts" in dashboard_text else "blocked", "message": "/memory links CLI/API surfaces"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v50.7", "status": status, "ok": status != "blocked", "rows": rows, "message": "Memory API parity gate verifies CLI, API, and dashboard coverage while GET remains read-only and writes remain guarded."}
    if save:
        _write_json(MEMORY_API_PARITY_GATE, report)
    return report


