    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v51.7", "status": status, "ok": status != "blocked", "rows": rows, "message": "Memory dashboard polish verifies compact memory store, correction/removal, and recall previews without heavy render-time gates."}
    if save:
        _write_json(MEMORY_STORE_DASHBOARD_POLISH, report)
