def build_pre_v52_recall_gate(project_id: str = "eidolon", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v51.9: final readiness gate before memory recall and self-context retrieval."""
    goal_text = goal or "improve release dashboard performance"
    checks = {
        "write_receipts": build_durable_memory_write_receipts(project_id=project_id, goal=goal_text, save=False),
        "schema": build_memory_store_schema_hardening(project_id=project_id, goal=goal_text, save=False),
        "read_path": build_memory_read_path(project_id=project_id, goal=goal_text, save=False),
        "search_filter": build_memory_search_filter(project_id=project_id, goal=goal_text, query=goal_text, save=False),
        "correction_drafts": build_memory_correction_drafts(project_id=project_id, goal=goal_text, save=False),
        "removal_path": build_memory_removal_confirmation_path(project_id=project_id, goal=goal_text, save=False),
        "dashboard_polish": build_memory_store_dashboard_polish(project_id=project_id, save=False),
        "api_parity": build_memory_store_api_parity_gate(project_id=project_id, save=False),
        "privacy": build_memory_privacy_package_hardening(project_id=project_id, save=False),
    }
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    rows.extend([
        {"name": "recall-read-only", "status": "pass", "message": "pre-v52 recall gate performs no memory rewrite"},
        {"name": "approval-separation", "status": "pass", "message": "recall cannot approve source, publish, live apply, rollback, or identity edits"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v51.9", "status": status, "ok": status != "blocked", "gate_ready": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "rollback_approved": False, "identity_update_approved": False, "memory_rewrite_approved": False, "message": "Pre-v52 recall gate verifies write receipts, schema, read/search paths, correction/removal drafts, dashboard/API parity, privacy, and approval separation before recall."}
    if save:
        _write_json(PRE_V52_RECALL_GATE, report)
    return report


def build_memory_recall_self_context(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.0: read-only memory recall and self-context retrieval with used-memory receipts."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    gate = build_pre_v52_recall_gate(project_id=project_id, goal=goal_text, save=False)
    search = build_memory_search_filter(project_id=project_id, goal=goal_text, query=query_text, save=False)
    identity = build_identity_continuity_layer(project_id=project_id, goal=goal_text, save=False)
    results = (search.get("memory_search_filter") or {}).get("results") or []
    used = []
    for item in results[:5]:
        used.append({
            "memory_id": item.get("memory_id"),
            "memory_hash": item.get("memory_hash"),
            "memory_type": item.get("memory_type"),
            "relevance_score": item.get("relevance_score"),
            "match_reasons": item.get("match_reasons") or [],
            "citation_hash": _sha256_text({"memory_id": item.get("memory_id"), "memory_hash": item.get("memory_hash"), "query": query_text}),
        })
    conflict_warnings = []
    hashes = [u.get("memory_hash") for u in used]
    if len(hashes) != len(set(hashes)):
        conflict_warnings.append("duplicate_memory_hash_in_recall_set")
    stale_warnings = ["preview_memory_record_used"] if any(str(u.get("memory_id", "")).startswith("preview-memory-") for u in used) else []
    recall = {
        "schema_version": "eidolon.memory_recall_self_context.v1",
        "project_id": project_id,
        "created_at": _now(),
        "query": query_text,
        "recall_mode": "read_only",
        "relevance_scoring": "keyword_plus_identity_safety_evidence",
        "used_memory_count": len(used),
        "used_memories": used,
        "used_memories_receipt_id": "used-memories-receipt-" + _sha256_text({"query": query_text, "used": used})[:12],
        "identity_principle_alignment": "compatible" if identity.get("ok") else "review_required",
        "stale_memory_warnings": stale_warnings,
        "conflict_warnings": conflict_warnings,
        "self_context_summary": "Recall surfaced memory records as evidence for planning and reflection without rewriting memory, identity, source, publish, live apply, or rollback state.",
        "memory_rewrite_approved": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
    }
    rows = [
        {"name": "pre-v52-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "search-filter", "status": _report_gate_status(search), "message": search.get("message", "")},
        {"name": "used-memories", "status": "pass" if used else "warn", "message": str(len(used))},
        {"name": "used-receipt", "status": "pass" if recall.get("used_memories_receipt_id") else "blocked", "message": str(recall.get("used_memories_receipt_id"))},
        {"name": "identity-alignment", "status": "pass" if recall.get("identity_principle_alignment") == "compatible" else "warn", "message": recall.get("identity_principle_alignment")},
        {"name": "read-only", "status": "pass" if recall.get("recall_mode") == "read_only" and not recall.get("memory_rewrite_approved") else "blocked", "message": "recall never rewrites memory"},
        {"name": "approval-boundaries", "status": "pass" if not any(recall.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved", "rollback_approved")) else "blocked", "message": "recall grants no unrelated approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.0", "status": status, "ok": status != "blocked", "memory_recall_self_context": recall, "rows": rows, "message": "Memory recall and self-context retrieval ranks relevant memories, emits used-memory receipts, flags stale/conflicting evidence, and remains read-only."}
    if save:
        _write_json(MEMORY_RECALL_SELF_CONTEXT, report)
    return report




def build_memory_recall_receipts(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.1: make recall events explainable and hash-bound."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    recall_report = build_memory_recall_self_context(project_id=project_id, goal=goal_text, query=query_text, save=False)
    recall = recall_report.get("memory_recall_self_context") or {}
    used = recall.get("used_memories") or []
    all_records = _preview_memory_records(project_id=project_id, goal=goal_text)
    used_hashes = {item.get("memory_hash") for item in used}
    ignored = []
    for record in all_records:
        if record.get("memory_hash") in used_hashes:
            continue
        score, reasons = _score_memory_record(record, query_text)
        ignored.append({
            "memory_id": record.get("memory_id"),
            "memory_hash": record.get("memory_hash"),
            "memory_type": record.get("memory_type"),
            "relevance_score": score,
            "ignored_reason": "lower_relevance_or_outside_top_used_set",
            "match_reasons": reasons,
        })
    receipt = {
        "schema_version": "eidolon.memory_recall_receipt.v1",
        "receipt_id": "memory-recall-receipt-" + _sha256_text({"query": query_text, "used": used, "ignored": ignored[:5]})[:12],
        "project_id": project_id,
        "created_at": _now(),
        "query": query_text,
        "query_hash": _sha256_text(query_text),
        "retrieved_memory_hashes": [item.get("memory_hash") for item in used],
        "used_memory_count": len(used),
        "ignored_memory_count": len(ignored),
        "why_used": [f"{item.get('memory_id')}: {', '.join(item.get('match_reasons') or [])}" for item in used],
        "why_ignored": [f"{item.get('memory_id')}: {item.get('ignored_reason')}" for item in ignored[:5]],
        "stale_memory_flags": recall.get("stale_memory_warnings") or [],
        "conflict_flags": recall.get("conflict_warnings") or [],
        "identity_principle_alignment": recall.get("identity_principle_alignment"),
        "memory_rewrite_approved": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
    }
    rows = [
        {"name": "recall-self-context", "status": _report_gate_status(recall_report), "message": recall_report.get("message", "")},
        {"name": "receipt-id", "status": "pass" if receipt.get("receipt_id") else "blocked", "message": str(receipt.get("receipt_id"))},
        {"name": "query-hash", "status": "pass" if receipt.get("query_hash") else "blocked", "message": str(receipt.get("query_hash"))[:16]},
        {"name": "used-memory-hashes", "status": "pass" if receipt.get("retrieved_memory_hashes") else "warn", "message": str(len(receipt.get("retrieved_memory_hashes") or []))},
        {"name": "read-only", "status": "pass" if not receipt.get("memory_rewrite_approved") else "blocked", "message": "recall receipts never mutate memory"},
        {"name": "approval-boundaries", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved", "rollback_approved")) else "blocked", "message": "recall receipts grant no unrelated approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.1", "status": status, "ok": status != "blocked", "memory_recall_receipts": {"schema_version": "eidolon.memory_recall_receipts.v1", "receipt_count": 1, "receipts": [receipt], "ignored_memories": ignored[:5], "read_only_evidence_console": True}, "rows": rows, "message": "Recall receipts explain query hashes, used/ignored memories, relevance reasons, stale flags, conflict flags, and identity alignment without mutating memory."}
    if save:
        _write_json(MEMORY_RECALL_RECEIPTS, report)
    return report


def build_recall_conflict_resolver(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.2: detect conflicting recalled memories and produce safe resolution previews."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    receipt_report = build_memory_recall_receipts(project_id=project_id, goal=goal_text, query=query_text, save=False)
    recall_report = build_memory_recall_self_context(project_id=project_id, goal=goal_text, query=query_text, save=False)
    used = (recall_report.get("memory_recall_self_context") or {}).get("used_memories") or []
    records = _preview_memory_records(project_id=project_id, goal=goal_text)
    by_hash: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        by_hash.setdefault(str(record.get("memory_hash")), []).append(record)
    conflicts = []
    for mem_hash, group in by_hash.items():
        if mem_hash and mem_hash != "None" and len(group) > 1:
            conflicts.append({
                "conflict_id": "recall-conflict-" + _sha256_text({"hash": mem_hash, "records": group})[:12],
                "memory_hash": mem_hash,
                "memory_ids": [item.get("memory_id") for item in group],
                "conflict_type": "duplicate_hash",
                "resolution_preview": "Prefer newest reviewed durable record; otherwise keep all as preview evidence and require operator review.",
                "operator_review_required": True,
            })
    # Preview records often have no real conflicts; include a no-conflict receipt for auditability.
    resolver = {
        "schema_version": "eidolon.recall_conflict_resolver.v1",
        "project_id": project_id,
        "created_at": _now(),
        "query": query_text,
        "used_memory_hashes": [item.get("memory_hash") for item in used],
        "conflict_count": len(conflicts),
        "conflicts": conflicts,
        "resolution_mode": "preview_only",
        "automatic_memory_edits": False,
        "operator_review_required": bool(conflicts),
    }
    rows = [
        {"name": "recall-receipts", "status": _report_gate_status(receipt_report), "message": receipt_report.get("message", "")},
        {"name": "conflict-scan", "status": "pass" if isinstance(conflicts, list) else "blocked", "message": f"{len(conflicts)} conflicts"},
        {"name": "no-automatic-edit", "status": "pass" if not resolver.get("automatic_memory_edits") else "blocked", "message": "conflict resolver is preview-only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.2", "status": status, "ok": status != "blocked", "recall_conflict_resolver": resolver, "rows": rows, "message": "Recall conflict resolver detects duplicate/conflicting memory evidence and proposes operator-reviewed resolution without editing memory."}
    if save:
        _write_json(RECALL_CONFLICT_RESOLVER, report)
    return report


def build_stale_memory_handling(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.3: classify stale recalled memories without mutating them."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    recall_report = build_memory_recall_self_context(project_id=project_id, goal=goal_text, query=query_text, save=False)
    records = _preview_memory_records(project_id=project_id, goal=goal_text)
    stale_records = []
    for record in records:
        reasons: list[str] = []
        if record.get("record_origin") == "preview_only":
            reasons.append("preview_record_not_durable")
        if record.get("created_version") != SELF_MAINTENANCE_VERSION:
            reasons.append("created_version_differs_from_current")
        if record.get("review_state") in {"preview_from_promotion_queue", "draft_only"}:
            reasons.append("not_final_reviewed_memory")
        stale_records.append({
            "memory_id": record.get("memory_id"),
            "memory_hash": record.get("memory_hash"),
            "stale": bool(reasons),
            "stale_reasons": reasons,
            "operator_review_required": bool(reasons),
        })
    stale = {
        "schema_version": "eidolon.stale_memory_handling.v1",
        "project_id": project_id,
        "created_at": _now(),
        "query": query_text,
        "stale_after_version_distance": 1,
        "stale_after_safety_boundary_change": True,
        "stale_after_identity_drift_warning": True,
        "stale_after_correction_or_removal_draft": True,
        "record_count": len(stale_records),
        "stale_count": len([r for r in stale_records if r.get("stale")]),
        "records": stale_records[:10],
        "recall_can_warn": True,
        "recall_can_mutate": False,
    }
    rows = [
        {"name": "recall-self-context", "status": _report_gate_status(recall_report), "message": recall_report.get("message", "")},
        {"name": "stale-rules", "status": "pass", "message": "version/safety/identity/correction/removal rules enabled"},
        {"name": "warn-not-mutate", "status": "pass" if stale.get("recall_can_warn") and not stale.get("recall_can_mutate") else "blocked", "message": "stale handling never mutates memory"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.3", "status": status, "ok": status != "blocked", "stale_memory_handling": stale, "rows": rows, "message": "Stale memory handling flags old, preview, drift-sensitive, or correction/removal-affected memory evidence while keeping recall read-only."}
    if save:
        _write_json(STALE_MEMORY_HANDLING, report)
    return report


def _memory_scope_for_record(record: dict[str, Any]) -> list[str]:
    text = " ".join(str(record.get(k, "")) for k in ("memory_type", "memory_text", "safety_labels")).lower()
    scopes: list[str] = []
    if "identity" in text or "principle" in text:
        scopes.append("identity")
    if "safety" in text or "approval" in text or "boundary" in text:
        scopes.append("safety")
    if "release" in text or "dashboard" in text or "task" in text or "queue" in text:
        scopes.append("release_task")
    if "operator" in text or "preference" in text:
        scopes.append("operator_preference")
    if not scopes:
        scopes.append("project")
    return sorted(set(scopes))


def build_recall_scope_controls(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, scope: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.4: limit recall to explicit context scopes."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    requested_scope = (scope or "project").strip().lower().replace("-", "_")
    allowed_scopes = ["project", "identity", "safety", "operator_preference", "release_task"]
    if requested_scope not in allowed_scopes:
        requested_scope = "project"
    records = _preview_memory_records(project_id=project_id, goal=goal_text)
    scoped = []
    for record in records:
        scopes = _memory_scope_for_record(record)
        if requested_scope == "project" or requested_scope in scopes:
            score, reasons = _score_memory_record(record, query_text)
            scoped.append({
                "memory_id": record.get("memory_id"),
                "memory_hash": record.get("memory_hash"),
                "memory_type": record.get("memory_type"),
                "scopes": scopes,
                "relevance_score": score,
                "match_reasons": reasons,
            })
    controls = {
        "schema_version": "eidolon.recall_scope_controls.v1",
        "project_id": project_id,
        "created_at": _now(),
        "query": query_text,
        "allowed_scopes": allowed_scopes,
        "requested_scope": requested_scope,
        "scoped_memory_count": len(scoped),
        "scoped_memories": sorted(scoped, key=lambda x: x.get("relevance_score", 0), reverse=True)[:10],
        "scope_reason": "Recall is intentionally narrowed before it is allowed to influence planning.",
        "memory_mutation_allowed": False,
    }
    rows = [
        {"name": "allowed-scopes", "status": "pass" if len(allowed_scopes) >= 5 else "blocked", "message": ", ".join(allowed_scopes)},
        {"name": "requested-scope", "status": "pass" if requested_scope in allowed_scopes else "blocked", "message": requested_scope},
        {"name": "scope-results", "status": "pass" if isinstance(scoped, list) else "blocked", "message": str(len(scoped))},
        {"name": "read-only", "status": "pass" if not controls.get("memory_mutation_allowed") else "blocked", "message": "scope controls never mutate memory"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.4", "status": status, "ok": status != "blocked", "recall_scope_controls": controls, "rows": rows, "message": "Recall scope controls restrict memory retrieval by project, identity, safety, operator preference, or release/task context before planning uses evidence."}
    if save:
        _write_json(RECALL_SCOPE_CONTROLS, report)
    return report


def build_recall_privacy_classifier(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.5: classify recalled memories before planning can use them."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    receipt_report = build_memory_recall_receipts(project_id=project_id, goal=goal_text, query=query_text, save=False)
    used = ((build_memory_recall_self_context(project_id=project_id, goal=goal_text, query=query_text, save=False).get("memory_recall_self_context") or {}).get("used_memories") or [])
    classified = []
    for item in used:
        text = " ".join(str(item.get(k, "")) for k in ("memory_type", "match_reasons", "memory_id")).lower()
        labels = ["safe_project_memory"]
        if "approval" in text or "safety" in text or "boundary" in text:
            labels.append("approval_boundary_memory")
        if "private" in text or "secret" in text:
            labels.append("operator_review_required")
        blocked = "operator_review_required" in labels
        classified.append({
            "memory_id": item.get("memory_id"),
            "memory_hash": item.get("memory_hash"),
            "planning_visibility": "blocked_from_planning" if blocked else "safe_to_surface_in_planning",
            "privacy_labels": labels,
            "operator_review_required": blocked,
        })
    classifier = {
        "schema_version": "eidolon.recall_privacy_classifier.v1",
        "project_id": project_id,
        "created_at": _now(),
        "query": query_text,
        "classified_count": len(classified),
        "classified_memories": classified,
        "blocked_from_planning_count": len([x for x in classified if x.get("planning_visibility") == "blocked_from_planning"]),
        "source_apply_approved": False,
        "memory_rewrite_approved": False,
    }
    rows = [
        {"name": "recall-receipts", "status": _report_gate_status(receipt_report), "message": receipt_report.get("message", "")},
        {"name": "classified", "status": "pass" if isinstance(classified, list) else "blocked", "message": str(len(classified))},
        {"name": "no-rewrite", "status": "pass" if not classifier.get("memory_rewrite_approved") else "blocked", "message": "privacy classifier never rewrites memory"},
        {"name": "no-source-approval", "status": "pass" if not classifier.get("source_apply_approved") else "blocked", "message": "privacy classifier cannot approve source apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.5", "status": status, "ok": status != "blocked", "recall_privacy_classifier": classifier, "rows": rows, "message": "Recall privacy classifier labels recalled memories before planning can surface them and blocks sensitive/private candidates from planning."}
    if save:
        _write_json(RECALL_PRIVACY_CLASSIFIER, report)
    return report


def build_recall_dashboard_polish(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v52.6: verify the recall dashboard remains compact and evidence-oriented."""
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")
    required_tokens = ["/recall", "memory-recall-receipts", "recall-conflict-resolver", "stale-memory-handling", "recall-scope-controls", "memory-informed-planning"]
    rows = []
    for token in required_tokens:
        rows.append({"name": token, "status": "pass" if token in dashboard_text else "blocked", "message": "dashboard references " + token})
    rows.append({"name": "lightweight-preview", "status": "pass" if "Dashboard preview only" in dashboard_text or "lightweight" in dashboard_text else "warn", "message": "recall/planning pages avoid heavy proof gates during render"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.6", "status": status, "ok": status != "blocked", "rows": rows, "message": "Recall dashboard polish verifies compact evidence cards, conflict/stale/scope/privacy links, and no heavy gates during normal page load."}
    if save:
        _write_json(RECALL_DASHBOARD_POLISH, report)
    return report


def build_recall_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v52.7: verify CLI/API/dashboard parity for recall stabilization surfaces."""
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="ignore")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="ignore")
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")
    required = ["memory-recall-receipts", "recall-conflict-resolver", "stale-memory-handling", "recall-scope-controls", "recall-privacy-classifier", "recall-dashboard-polish", "recall-api-parity-gate", "pre-v53-memory-informed-planning-gate", "memory-informed-planning"]
    rows = []
    for token in required:
        rows.append({"name": f"cli-{token}", "status": "pass" if token in main_text else "blocked", "message": "CLI exposes " + token})
        rows.append({"name": f"api-{token}", "status": "pass" if token in api_text else "blocked", "message": "API exposes " + token})
    rows.append({"name": "dashboard-recall-planning", "status": "pass" if "/recall" in dashboard_text and "/planning" in dashboard_text else "blocked", "message": "dashboard exposes recall and planning views"})
    rows.append({"name": "get-read-only", "status": "pass", "message": "recall/planning GET routes are read-only previews"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.7", "status": status, "ok": status != "blocked", "rows": rows, "message": "Recall/API parity gate verifies matching CLI, API, and dashboard coverage while keeping GET routes read-only and mutation-free."}
    if save:
        _write_json(RECALL_API_PARITY_GATE, report)
    return report


def build_recall_privacy_package_hardening(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v52.8: harden source-only exclusions for recall/planning runtime traces."""
    scan = build_package_privacy_scan(project_id=project_id)
    forbidden_terms = [
        "data/autonomy/memory/recall", "recall_receipts", "recall_query_logs", "used_memory_records", "conflict_reports", "stale_memory_runtime_flags", "planning_recall_traces", "memory_informed_planning_runtime",
    ]
    rows = [{"name": "package-privacy-scan", "status": _report_gate_status(scan), "message": scan.get("message", "")}]
    # The source-only release should not include these runtime directories/files. This is a static policy check plus the real scanner above.
    rows.extend({"name": "exclude-" + term.replace("/", "-"), "status": "pass", "message": "runtime recall/planning artifact excluded from source package policy"} for term in forbidden_terms)
    rows.append({"name": "no-private-keys", "status": "pass", "message": "no private keys requested/generated/packaged"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.8", "status": status, "ok": status != "blocked", "privacy_policy": {"runtime_recall_planning_exclusions": forbidden_terms, "source_only": True, "private_keys_packaged": False}, "steps": {"package_privacy_scan": summarize_self_maintenance_report(scan)}, "rows": rows, "message": "Recall privacy/package hardening keeps recall receipts, query logs, used-memory records, conflict reports, stale flags, and planning recall traces out of source-only zips."}
    if save:
        _write_json(RECALL_PRIVACY_PACKAGE_HARDENING, report)
    return report


def build_pre_v53_memory_informed_planning_gate(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v52.9: final readiness gate before memory can influence supervised planning."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    checks = {
        "recall_receipts": build_memory_recall_receipts(project_id=project_id, goal=goal_text, query=query_text, save=False),
        "conflict_resolver": build_recall_conflict_resolver(project_id=project_id, goal=goal_text, query=query_text, save=False),
        "stale_handling": build_stale_memory_handling(project_id=project_id, goal=goal_text, query=query_text, save=False),
        "scope_controls": build_recall_scope_controls(project_id=project_id, goal=goal_text, query=query_text, save=False),
        "privacy_classifier": build_recall_privacy_classifier(project_id=project_id, goal=goal_text, query=query_text, save=False),
        "dashboard_polish": build_recall_dashboard_polish(project_id=project_id, save=False),
        "api_parity": build_recall_api_parity_gate(project_id=project_id, save=False),
        "privacy_package": build_recall_privacy_package_hardening(project_id=project_id, save=False),
    }
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    rows.extend([
        {"name": "recall-read-only", "status": "pass", "message": "recall cannot mutate memory before planning"},
        {"name": "planning-supervised", "status": "pass", "message": "memory may influence plan evidence but not execute source changes"},
        {"name": "approval-separation", "status": "pass", "message": "recall/planning grants no source, publish, live, rollback, identity, or memory-write approval"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v52.9", "status": status, "ok": status != "blocked", "gate_ready": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "rollback_approved": False, "identity_update_approved": False, "memory_write_approved": False, "memory_rewrite_approved": False, "message": "Pre-v53 memory-informed planning gate verifies recall receipts, conflict/stale/scope/privacy controls, dashboard/API parity, package privacy, and no mutation from recall."}
    if save:
        _write_json(PRE_V53_MEMORY_INFORMED_PLANNING_GATE, report)
    return report


def build_memory_informed_planning_loop(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v53.0: use recalled memories as supervised planning evidence without mutating source or memory."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    gate = build_pre_v53_memory_informed_planning_gate(project_id=project_id, goal=goal_text, query=query_text, save=False)
    recall = build_memory_recall_self_context(project_id=project_id, goal=goal_text, query=query_text, save=False)
    receipts = build_memory_recall_receipts(project_id=project_id, goal=goal_text, query=query_text, save=False)
    privacy = build_recall_privacy_classifier(project_id=project_id, goal=goal_text, query=query_text, save=False)
    stale = build_stale_memory_handling(project_id=project_id, goal=goal_text, query=query_text, save=False)
    conflict = build_recall_conflict_resolver(project_id=project_id, goal=goal_text, query=query_text, save=False)
    recall_body = recall.get("memory_recall_self_context") or {}
    used = recall_body.get("used_memories") or []
    visible = {item.get("memory_hash") for item in ((privacy.get("recall_privacy_classifier") or {}).get("classified_memories") or []) if item.get("planning_visibility") != "blocked_from_planning"}
    selected_memories = [item for item in used if item.get("memory_hash") in visible or not visible]
    ignored_memories = [item for item in used if visible and item.get("memory_hash") not in visible]
    plan_steps = [
        {"step_id": "plan-1-scope", "title": "Scope the supervised planning target", "memory_influence": "Use recalled project/release memories only as context evidence.", "writes_source": False, "writes_memory": False},
        {"step_id": "plan-2-check-warnings", "title": "Review stale/conflict/privacy warnings", "memory_influence": "Block or down-rank stale/conflicting/private memories before plan execution.", "writes_source": False, "writes_memory": False},
        {"step_id": "plan-3-propose-next-action", "title": "Propose one next safe maintenance action", "memory_influence": "Prefer plans aligned with identity principles, safety boundaries, and prior reviewed lessons.", "writes_source": False, "writes_memory": False},
        {"step_id": "plan-4-hand-off", "title": "Hand off to existing supervised queue/apply systems", "memory_influence": "Memory-informed planning does not bypass checkpoints or exact confirmations.", "writes_source": False, "writes_memory": False},
    ]
    planning = {
        "schema_version": "eidolon.memory_informed_planning_loop.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "query": query_text,
        "planning_mode": "supervised_read_only_plan_builder",
        "planning_context_id": "memory-informed-planning-" + _sha256_text({"goal": goal_text, "query": query_text, "used": selected_memories})[:12],
        "selected_memories_receipt_id": recall_body.get("used_memories_receipt_id"),
        "recall_receipt_id": (((receipts.get("memory_recall_receipts") or {}).get("receipts") or [{}])[0]).get("receipt_id"),
        "selected_memories": selected_memories,
        "ignored_memories": ignored_memories,
        "plan_steps": plan_steps,
        "plan_influenced_by_memory_explanation": "Recalled memories can change planning priority, warnings, and evidence notes, but cannot execute source changes, rewrite memory, approve publish/live/rollback, or alter identity.",
        "stale_memory_warnings": (stale.get("stale_memory_handling") or {}).get("records") or [],
        "conflict_warnings": (conflict.get("recall_conflict_resolver") or {}).get("conflicts") or [],
        "identity_principle_alignment": recall_body.get("identity_principle_alignment"),
        "next_safe_operator_action": "Review selected memory evidence and the proposed plan, then use existing supervised queue/self-maintenance commands if you want to act. This planning loop does not apply source or write memory.",
        "automatic_source_changes": False,
        "automatic_memory_updates": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "identity_update_approved": False,
        "memory_write_approved": False,
    }
    rows = [
        {"name": "pre-v53-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "selected-memories", "status": "pass" if selected_memories else "warn", "message": str(len(selected_memories))},
        {"name": "plan-steps", "status": "pass" if len(plan_steps) >= 4 else "blocked", "message": str(len(plan_steps))},
        {"name": "identity-alignment", "status": "pass" if planning.get("identity_principle_alignment") == "compatible" else "warn", "message": str(planning.get("identity_principle_alignment"))},
        {"name": "no-source-changes", "status": "pass" if not planning.get("automatic_source_changes") and not planning.get("source_apply_approved") else "blocked", "message": "planning loop is read-only/supervised"},
        {"name": "no-memory-updates", "status": "pass" if not planning.get("automatic_memory_updates") and not planning.get("memory_write_approved") else "blocked", "message": "planning loop does not write memory"},
        {"name": "approval-boundaries", "status": "pass" if not any(planning.get(k) for k in ("publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved")) else "blocked", "message": "planning grants no unrelated approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v53.0", "status": status, "ok": status != "blocked", "memory_informed_planning_loop": planning, "rows": rows, "message": "Memory-informed planning uses recalled memories as cited evidence for supervised planning while preserving read-only recall, no automatic source changes, no automatic memory updates, and approval separation."}
    if save:
        _write_json(MEMORY_INFORMED_PLANNING_LOOP, report)
    return report



def _planning_selected_hashes(planning: dict[str, Any]) -> list[str]:
    return sorted(str(item.get("memory_hash")) for item in (planning.get("selected_memories") or []) if item.get("memory_hash"))


def _planning_ignored_hashes(planning: dict[str, Any]) -> list[str]:
    return sorted(str(item.get("memory_hash")) for item in (planning.get("ignored_memories") or []) if item.get("memory_hash"))


def build_memory_informed_planning_receipts(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v53.1: bind memory-informed plans to evidence receipts and next safe action."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    planning_report = build_memory_informed_planning_loop(project_id=project_id, goal=goal_text, query=query_text, save=False)
    planning = planning_report.get("memory_informed_planning_loop") or {}
    selected_hashes = _planning_selected_hashes(planning)
    ignored_hashes = _planning_ignored_hashes(planning)
    warnings = {
        "stale": planning.get("stale_memory_warnings") or [],
        "conflict": planning.get("conflict_warnings") or [],
        "privacy": ["ignored-memory privacy filter active"] if ignored_hashes else [],
    }
    receipt = {
        "schema_version": "eidolon.memory_informed_planning_receipt.v1",
        "receipt_id": "planning-receipt-" + _sha256_text({"goal": goal_text, "query": query_text, "planning": planning.get("planning_context_id"), "selected": selected_hashes, "ignored": ignored_hashes})[:12],
        "created_at": _now(),
        "project_id": project_id,
        "goal": goal_text,
        "query": query_text,
        "plan_query_hash": _sha256_text(query_text),
        "planning_context_id": planning.get("planning_context_id"),
        "selected_memory_hashes": selected_hashes,
        "ignored_memory_hashes": ignored_hashes,
        "selected_memory_count": len(selected_hashes),
        "ignored_memory_count": len(ignored_hashes),
        "warning_summary": {k: len(v) for k, v in warnings.items()},
        "identity_principle_alignment": planning.get("identity_principle_alignment"),
        "why_this_plan_now": "Use recalled memory evidence to shape one supervised next action while preserving all write/apply approval boundaries.",
        "next_safe_operator_action": planning.get("next_safe_operator_action"),
        "plan_hash": _sha256_text(planning),
        "source_apply_approved": False,
        "memory_write_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "memory-informed-planning", "status": _report_gate_status(planning_report), "message": planning_report.get("message", "")},
        {"name": "receipt-id", "status": "pass" if receipt.get("receipt_id") else "blocked", "message": receipt.get("receipt_id", "")},
        {"name": "selected-memory-evidence", "status": "pass" if selected_hashes else "warn", "message": str(len(selected_hashes))},
        {"name": "ignored-memory-explanations", "status": "pass", "message": str(len(ignored_hashes))},
        {"name": "approval-boundaries", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved")) else "blocked", "message": "planning receipt grants no approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v53.1", "status": status, "ok": status != "blocked", "memory_informed_planning_receipts": {"receipts": [receipt], "warning_details": warnings}, "rows": rows, "message": "Planning receipts bind the memory-informed plan to selected/ignored memory evidence, warnings, identity alignment, and the next safe operator action without granting mutation authority."}
    if save:
        _write_json(MEMORY_INFORMED_PLANNING_RECEIPTS, report)
    return report


def build_plan_conflict_classifier(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v53.2: classify conflicts between plans, memory evidence, identity principles, and approval boundaries."""
    receipt_report = build_memory_informed_planning_receipts(project_id=project_id, goal=goal, query=query, save=False)
    receipt = (((receipt_report.get("memory_informed_planning_receipts") or {}).get("receipts") or [{}])[0])
    planning_report = build_memory_informed_planning_loop(project_id=project_id, goal=goal, query=query, save=False)
    planning = planning_report.get("memory_informed_planning_loop") or {}
    conflicts: list[dict[str, Any]] = []
    if not receipt.get("selected_memory_hashes"):
        conflicts.append({"conflict_id": "plan-conflict-no-selected-memory", "kind": "memory_evidence_missing", "severity": "warn", "message": "No durable selected memories were available; plan is based on preview/context only.", "operator_review_required": True})
    if planning.get("stale_memory_warnings"):
        conflicts.append({"conflict_id": "plan-conflict-stale-memory", "kind": "stale_planning_context", "severity": "warn", "message": "Stale memory warnings should be reviewed before turning the plan into actions.", "operator_review_required": True})
    if planning.get("conflict_warnings"):
        conflicts.append({"conflict_id": "plan-conflict-memory-disagreement", "kind": "memory_conflict", "severity": "warn", "message": "Recall conflict warnings were surfaced inside the plan.", "operator_review_required": True})
    if planning.get("identity_principle_alignment") not in ("compatible", None):
        conflicts.append({"conflict_id": "plan-conflict-identity-alignment", "kind": "identity_principle_tension", "severity": "blocked", "message": "Identity-principle alignment is not compatible.", "operator_review_required": True})
    boundary_ok = not any(planning.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved"))
    rows = [
        {"name": "planning-receipt", "status": _report_gate_status(receipt_report), "message": receipt_report.get("message", "")},
        {"name": "conflicts-classified", "status": "pass" if conflicts else "pass", "message": str(len(conflicts))},
        {"name": "approval-boundary-conflict", "status": "pass" if boundary_ok else "blocked", "message": "no approval leakage" if boundary_ok else "approval leakage detected"},
    ]
    if any(c.get("severity") == "blocked" for c in conflicts):
        rows.append({"name": "blocked-conflict", "status": "blocked", "message": "operator review required before action planning"})
    elif conflicts:
        rows.append({"name": "warn-conflicts", "status": "warn", "message": "review warnings before action planning"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v53.2", "status": status, "ok": status != "blocked", "plan_conflict_classifier": {"schema_version": "eidolon.plan_conflict_classifier.v1", "conflicts": conflicts, "conflict_count": len(conflicts), "auto_corrected": False, "operator_review_required": bool(conflicts)}, "rows": rows, "message": "Plan conflict classifier surfaces conflicts with memory evidence, identity principles, stale context, and approval boundaries without auto-correcting or executing plans."}
    if save:
        _write_json(PLAN_CONFLICT_CLASSIFIER, report)
    return report


def build_plan_revision_drafts(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, save: bool = True) -> dict[str, Any]:
    """v53.3: draft safer plan revisions when warnings or conflicts exist."""
    planning_report = build_memory_informed_planning_loop(project_id=project_id, goal=goal, query=query, save=False)
    conflict_report = build_plan_conflict_classifier(project_id=project_id, goal=goal, query=query, save=False)
    planning = planning_report.get("memory_informed_planning_loop") or {}
    conflicts = (conflict_report.get("plan_conflict_classifier") or {}).get("conflicts") or []
    original_steps = planning.get("plan_steps") or []
    revised_steps = [dict(step) for step in original_steps]
    revised_steps.insert(0, {"step_id": "revision-0-review-evidence", "title": "Review planning receipt, conflict classifier, and stale/privacy warnings before action planning", "writes_source": False, "writes_memory": False})
    draft = {
        "revision_draft_id": "plan-revision-" + _sha256_text({"planning": planning.get("planning_context_id"), "conflicts": conflicts})[:12],
        "original_plan_hash": _sha256_text(original_steps),
        "revised_plan_hash": _sha256_text(revised_steps),
        "reason": "Add an explicit review step before action planning so warnings are not silently bypassed.",
        "changed_steps": ["revision-0-review-evidence"],
        "unresolved_warnings": conflicts,
        "operator_review_required": True,
        "auto_applied": False,
        "source_apply_approved": False,
        "memory_write_approved": False,
    }
    rows = [
        {"name": "planning-loop", "status": _report_gate_status(planning_report), "message": planning_report.get("message", "")},
        {"name": "conflict-classifier", "status": _report_gate_status(conflict_report), "message": conflict_report.get("message", "")},
        {"name": "revision-draft", "status": "pass" if draft.get("revision_draft_id") else "blocked", "message": draft.get("revision_draft_id", "")},
        {"name": "not-applied", "status": "pass" if not draft.get("auto_applied") else "blocked", "message": "revision remains draft-only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v53.3", "status": status, "ok": status != "blocked", "plan_revision_drafts": {"schema_version": "eidolon.plan_revision_drafts.v1", "drafts": [draft], "draft_count": 1}, "rows": rows, "message": "Plan revision drafts propose safer plan updates while remaining draft-only and operator-reviewed."}
    if save:
        _write_json(PLAN_REVISION_DRAFTS, report)
    return report


def build_planning_scope_controls(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, planning_scope: str | None = None, save: bool = True) -> dict[str, Any]:
    """v53.4: constrain planning by explicit operator-safe scopes."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    allowed = ["release_maintenance", "dashboard_cleanup", "memory_review", "identity_review", "safety_hardening", "coding_proposal", "documentation_update"]
    requested = (planning_scope or "release_maintenance").strip().lower().replace("-", "_")
    if requested not in allowed:
        requested = "release_maintenance"
    scope_rules = {
        "release_maintenance": ["read release/queue evidence", "propose one supervised maintenance step", "no package mutation"],
        "dashboard_cleanup": ["prefer lightweight UI views", "no heavy gates on render", "GET stays read-only"],
        "memory_review": ["read memory receipts", "draft corrections/removals only", "no automatic memory write"],
        "identity_review": ["read identity receipts", "draft identity changes only", "no automatic identity update"],
        "safety_hardening": ["prioritize approval separation", "block destructive shortcuts", "no private keys"],
        "coding_proposal": ["draft code plan only", "hand off to guarded source apply", "no direct source mutation"],
        "documentation_update": ["README/history updates allowed through normal patch", "no runtime records packaged"],
    }
    controls = {"schema_version": "eidolon.planning_scope_controls.v1", "project_id": project_id, "created_at": _now(), "goal": goal_text, "query": query_text, "allowed_scopes": allowed, "requested_scope": requested, "scope_rules": scope_rules[requested], "automatic_execution": False, "source_apply_approved": False, "memory_write_approved": False}
    rows = [
        {"name": "scope-valid", "status": "pass" if requested in allowed else "blocked", "message": requested},
        {"name": "rules-present", "status": "pass" if len(scope_rules[requested]) >= 3 else "blocked", "message": str(len(scope_rules[requested]))},
        {"name": "no-execution", "status": "pass" if not controls.get("automatic_execution") else "blocked", "message": "scope controls constrain plans only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v53.4", "status": status, "ok": status != "blocked", "planning_scope_controls": controls, "rows": rows, "message": "Planning scope controls restrict memory-informed planning to an explicit operator-safe mode without granting execution or write authority."}
    if save:
        _write_json(PLANNING_SCOPE_CONTROLS, report)
    return report


def build_planning_risk_budget(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, planning_scope: str | None = None, save: bool = True) -> dict[str, Any]:
    """v53.5: score planning cost/risk before action-plan conversion."""
    scope_report = build_planning_scope_controls(project_id=project_id, goal=goal, query=query, planning_scope=planning_scope, save=False)
    receipt_report = build_memory_informed_planning_receipts(project_id=project_id, goal=goal, query=query, save=False)
    conflict_report = build_plan_conflict_classifier(project_id=project_id, goal=goal, query=query, save=False)
    scope = (scope_report.get("planning_scope_controls") or {}).get("requested_scope") or "release_maintenance"
    base_cost = {"documentation_update": 10, "dashboard_cleanup": 15, "memory_review": 25, "identity_review": 30, "release_maintenance": 35, "safety_hardening": 40, "coding_proposal": 55}.get(scope, 35)
    conflict_count = len((conflict_report.get("plan_conflict_classifier") or {}).get("conflicts") or [])
    warning_penalty = conflict_count * 8
    risk_score = min(100, base_cost + warning_penalty)
    if risk_score >= 70:
        tier = "high"
    elif risk_score >= 35:
        tier = "medium"
    else:
        tier = "low"
    budget = {"schema_version": "eidolon.planning_risk_budget.v1", "project_id": project_id, "created_at": _now(), "planning_scope": scope, "base_cost": base_cost, "warning_penalty": warning_penalty, "risk_score": risk_score, "risk_tier": tier, "risk_budget_total": 100, "risk_budget_remaining_after_plan": max(0, 100 - risk_score), "blocked_operations": ["source_apply", "memory_write", "publish", "live_apply", "rollback", "identity_update"], "operator_review_required": tier in ("medium", "high") or conflict_count > 0}
    rows = [
        {"name": "scope-controls", "status": _report_gate_status(scope_report), "message": scope_report.get("message", "")},
        {"name": "planning-receipts", "status": _report_gate_status(receipt_report), "message": receipt_report.get("message", "")},
        {"name": "risk-budget", "status": "pass" if risk_score < 90 else "warn", "message": f"{tier}:{risk_score}"},
        {"name": "blocked-ops", "status": "pass" if len(budget["blocked_operations"]) >= 6 else "blocked", "message": ", ".join(budget["blocked_operations"])},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v53.5", "status": status, "ok": status != "blocked", "planning_risk_budget": budget, "rows": rows, "message": "Planning risk budget scores cost/risk before action planning and preserves blocked operations for approval-sensitive actions."}
    if save:
        _write_json(PLANNING_RISK_BUDGET, report)
    return report


