def _execution_preview(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, planning_scope: str | None = None) -> dict[str, Any]:
    return build_controlled_action_execution_preview(project_id=project_id, goal=goal, query=query, planning_scope=planning_scope, save=False).get("controlled_action_execution_preview") or {}


def _read_only_command_payload(command_key: str) -> dict[str, Any] | None:
    spec = READ_ONLY_EXECUTION_ALLOWLIST.get(command_key)
    if not spec:
        return None
    if spec.get("command_factory") == "py_compile_core":
        files = [str(p) for p in sorted((ROOT_DIR / "conscious_agent").glob("*.py"))]
        files.append(str(ROOT_DIR / "tools" / "smoke_check.py"))
        command = [sys.executable, "-m", "py_compile", *files]
    else:
        command = list(spec.get("command") or [])
    return {**spec, "command": command, "command_key": command_key, "command_hash": _sha256_text(command)}


def build_execution_preview_receipts(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, planning_scope: str | None = None, save: bool = True) -> dict[str, Any]:
    """v55.1: bind execution preview readiness to reviewable receipts."""
    goal_text = goal or "improve release dashboard performance"
    query_text = query or goal_text
    preview = _execution_preview(project_id=project_id, goal=goal_text, query=query_text, planning_scope=planning_scope)
    step_receipts = []
    for index, step in enumerate(preview.get("step_readiness") or [], start=1):
        step_hash = _sha256_text(step)
        step_receipts.append({
            "execution_step_receipt_id": "execution-step-receipt-" + step_hash[:12],
            "action_step_id": step.get("action_step_id"),
            "step_readiness_hash": step_hash,
            "step_index": index,
            "ready_for_preview": bool(step.get("ready_for_preview")),
            "blocked_reason": step.get("blocked_reason"),
            "why_executable_or_blocked": step.get("blocked_reason") or "readiness preview only; real execution routes remain guarded elsewhere",
        })
    receipt = {
        "schema_version": "eidolon.execution_preview_receipts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "query": query_text,
        "execution_preview_id": preview.get("execution_preview_id"),
        "execution_preview_receipt_id": "execution-preview-receipt-" + _sha256_text({"preview": preview.get("execution_preview_id"), "steps": step_receipts})[:12],
        "bound_action_plan_id": preview.get("action_plan_id"),
        "bound_action_plan_hash": preview.get("action_plan_hash"),
        "step_readiness_receipts": step_receipts,
        "blocked_operations": preview.get("blocked_operations") or [],
        "confirmation_phrase_hash_preview": _sha256_text(preview.get("expected_confirmation_phrase")),
        "audit_receipt_preview": preview.get("audit_receipt_preview"),
        "next_safe_operator_action": "Review execution-preview receipts, then run only an allowlisted read-only command with exact confirmation if evidence is needed.",
        "automatic_execution": False,
        "real_execution_approved": False,
    }
    rows = [
        {"name": "execution-preview-id", "status": "pass" if receipt.get("execution_preview_id") else "blocked", "message": str(receipt.get("execution_preview_id"))},
        {"name": "step-readiness-receipts", "status": "pass" if step_receipts else "blocked", "message": str(len(step_receipts))},
        {"name": "blocked-operations-listed", "status": "pass" if receipt.get("blocked_operations") else "warn", "message": str(receipt.get("blocked_operations"))},
        {"name": "no-real-execution", "status": "pass" if not receipt.get("automatic_execution") and not receipt.get("real_execution_approved") else "blocked", "message": "receipts do not approve execution"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v55.1", "status": status, "ok": status != "blocked", "execution_preview_receipts": receipt, "rows": rows, "message": "Execution preview receipts bind readiness, step hashes, blocked operations, confirmation phrase hashes, and audit previews without executing real operations."}
    if save:
        _write_json(EXECUTION_PREVIEW_RECEIPTS, report)
    return report


def build_execution_step_permission_classifier(project_id: str = "eidolon", goal: str | None = None, query: str | None = None, planning_scope: str | None = None, save: bool = True) -> dict[str, Any]:
    """v55.2: classify preview steps by read-only execution permission."""
    preview = _execution_preview(project_id=project_id, goal=goal, query=query, planning_scope=planning_scope)
    classified = []
    for step in preview.get("step_readiness") or []:
        title = str(step.get("title") or step.get("action_step_id") or "").lower()
        labels = ["read_only_allowed" if step.get("ready_for_preview") else "read_only_blocked"]
        if "compile" in title:
            labels.append("compile_check")
        if "scan" in title or "privacy" in title:
            labels.append("package_privacy_scan")
        if "dashboard" in title or "api" in title:
            labels.append("dashboard_api_get_check")
        if any(word in title for word in ["apply", "write", "remove", "publish", "rollback", "identity"]):
            labels.append("approval_sensitive_blocked")
        classified.append({
            "action_step_id": step.get("action_step_id"),
            "step_hash": _sha256_text(step),
            "permission_labels": sorted(set(labels)),
            "read_only_allowed": "read_only_allowed" in labels and "approval_sensitive_blocked" not in labels,
            "mutation_required": "approval_sensitive_blocked" in labels,
            "destructive_blocked": "approval_sensitive_blocked" in labels,
        })
    classifier = {
        "schema_version": "eidolon.execution_step_permission_classifier.v1",
        "project_id": project_id,
        "created_at": _now(),
        "action_plan_id": preview.get("action_plan_id"),
        "classified_steps": classified,
        "allowed_count": len([s for s in classified if s.get("read_only_allowed")]),
        "blocked_count": len([s for s in classified if s.get("destructive_blocked") or not s.get("read_only_allowed")]),
        "real_execution_approved": False,
    }
    rows = [
        {"name": "classified-steps", "status": "pass" if classified else "blocked", "message": str(len(classified))},
        {"name": "allowed-read-only-steps", "status": "pass" if classifier.get("allowed_count", 0) >= 1 else "warn", "message": str(classifier.get("allowed_count"))},
        {"name": "blocked-sensitive-steps", "status": "pass" if classifier.get("blocked_count", 0) >= 1 else "warn", "message": str(classifier.get("blocked_count"))},
        {"name": "no-approval", "status": "pass" if not classifier.get("real_execution_approved") else "blocked", "message": "permission classification grants no approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v55.2", "status": status, "ok": status != "blocked", "execution_step_permission_classifier": classifier, "rows": rows, "message": "Execution step permission classifier separates read-only diagnostics from mutation-required, destructive, or approval-sensitive steps."}
    if save:
        _write_json(EXECUTION_STEP_PERMISSION_CLASSIFIER, report)
    return report


def build_read_only_command_allowlist(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v55.3: define exact read-only commands allowed for controlled execution."""
    commands = []
    for key in sorted(READ_ONLY_EXECUTION_ALLOWLIST):
        payload = _read_only_command_payload(key) or {}
        commands.append({
            "command_key": key,
            "description": payload.get("description"),
            "category": payload.get("category"),
            "expected_gate": payload.get("expected_gate"),
            "timeout_seconds": payload.get("timeout_seconds"),
            "command_hash": payload.get("command_hash"),
            "confirmation_phrase_preview": f"RUN_READ_ONLY {key}",
        })
    allowlist = {
        "schema_version": "eidolon.read_only_command_allowlist.v1",
        "project_id": project_id,
        "created_at": _now(),
        "allowed_commands": commands,
        "arbitrary_shell_allowed": False,
        "filesystem_write_allowed": False,
        "source_apply_allowed": False,
        "memory_mutation_allowed": False,
        "publish_live_rollback_identity_allowed": False,
    }
    rows = [
        {"name": "allowlist-not-empty", "status": "pass" if commands else "blocked", "message": str(len(commands))},
        {"name": "hashed-commands", "status": "pass" if all(c.get("command_hash") for c in commands) else "blocked", "message": "each command has a hash"},
        {"name": "no-arbitrary-shell", "status": "pass" if not allowlist.get("arbitrary_shell_allowed") else "blocked", "message": "only keyed commands are allowed"},
        {"name": "no-mutation", "status": "pass" if not allowlist.get("filesystem_write_allowed") and not allowlist.get("source_apply_allowed") and not allowlist.get("memory_mutation_allowed") else "blocked", "message": "allowlist is diagnostic-only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v55.3", "status": status, "ok": status != "blocked", "read_only_command_allowlist": allowlist, "rows": rows, "message": "Read-only command allowlist defines exact diagnostic commands and blocks arbitrary shell, source apply, memory mutation, publish, live, rollback, and identity operations."}
    if save:
        _write_json(READ_ONLY_COMMAND_ALLOWLIST, report)
    return report


def build_execution_sandbox_evidence_binder(project_id: str = "eidolon", command_key: str = "version-import", goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v55.4: bind a read-only command to expected evidence before execution."""
    payload = _read_only_command_payload(command_key)
    preview = _execution_preview(project_id=project_id, goal=goal)
    binder = {
        "schema_version": "eidolon.execution_sandbox_evidence_binder.v1",
        "project_id": project_id,
        "created_at": _now(),
        "command_key": command_key,
        "command_known": bool(payload),
        "command_hash": payload.get("command_hash") if payload else None,
        "bound_action_plan_id": preview.get("action_plan_id"),
        "bound_execution_preview_id": preview.get("execution_preview_id"),
        "expected_gate": payload.get("expected_gate") if payload else None,
        "observed_result": None,
        "output_hash": None,
        "next_safe_action": f"Run --controlled-read-only-action-execution --read-only-command-key {command_key} --read-only-confirm-phrase 'RUN_READ_ONLY {command_key}' --execute-read-only-action --readiness-json" if payload else "Choose a known allowlisted command key.",
        "writes_project_files": False,
        "executes_mutation": False,
    }
    rows = [
        {"name": "command-known", "status": "pass" if payload else "blocked", "message": command_key},
        {"name": "command-hash", "status": "pass" if binder.get("command_hash") else "blocked", "message": str(binder.get("command_hash"))},
        {"name": "preview-bound", "status": "pass" if binder.get("bound_execution_preview_id") else "warn", "message": str(binder.get("bound_execution_preview_id"))},
        {"name": "no-mutation", "status": "pass" if not binder.get("writes_project_files") and not binder.get("executes_mutation") else "blocked", "message": "evidence binder is read-only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v55.4", "status": status, "ok": status != "blocked", "execution_sandbox_evidence_binder": binder, "rows": rows, "message": "Execution sandbox evidence binder links an allowlisted command to expected evidence, preview IDs, hashes, and next safe operator action before any controlled read-only execution."}
    if save:
        _write_json(EXECUTION_SANDBOX_EVIDENCE_BINDER, report)
    return report


def build_execution_result_receipts(project_id: str = "eidolon", command_key: str = "version-import", result: dict[str, Any] | None = None, save: bool = True) -> dict[str, Any]:
    """v55.5: create a compact result receipt for read-only execution evidence."""
    payload = _read_only_command_payload(command_key)
    result = result or {"executed": False, "status": "preview", "returncode": None, "stdout": "", "stderr": "", "message": "No read-only command executed yet."}
    output_summary = (str(result.get("stdout") or "") + ("\n" + str(result.get("stderr")) if result.get("stderr") else "")).strip()
    receipt = {
        "schema_version": "eidolon.execution_result_receipts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "command_key": command_key,
        "command_hash": payload.get("command_hash") if payload else None,
        "execution_result_receipt_id": "execution-result-receipt-" + _sha256_text({"key": command_key, "result": result})[:12],
        "executed": bool(result.get("executed")),
        "returncode": result.get("returncode"),
        "result_status": result.get("status"),
        "output_hash": _sha256_text(output_summary),
        "output_summary": output_summary[:1200],
        "privacy_flags": [],
        "operator_review_status": "review_required" if result.get("executed") else "preview_only",
        "source_apply_approved": False,
        "memory_write_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "command-known", "status": "pass" if payload else "blocked", "message": command_key},
        {"name": "receipt-id", "status": "pass" if receipt.get("execution_result_receipt_id") else "blocked", "message": str(receipt.get("execution_result_receipt_id"))},
        {"name": "result-status", "status": "pass" if receipt.get("result_status") in ("pass", "preview") else "warn", "message": str(receipt.get("result_status"))},
        {"name": "no-approval-leakage", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved")) else "blocked", "message": "execution receipt grants no unrelated approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v55.5", "status": status, "ok": status != "blocked", "execution_result_receipts": receipt, "rows": rows, "message": "Execution result receipts hash command output and summarize read-only diagnostic results without granting source, memory, publish, live, rollback, or identity approval."}
    if save:
        _write_json(EXECUTION_RESULT_RECEIPTS, report)
    return report


