def build_execution_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v55.7: verify CLI/API/dashboard parity for execution-readiness surfaces."""
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8")
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8")
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8")
    route_tokens = [
        "execution-preview-receipts", "execution-step-permission-classifier", "read-only-command-allowlist",
        "execution-sandbox-evidence-binder", "execution-result-receipts", "execution-dashboard-polish",
        "execution-api-parity-gate", "execution-privacy-package-hardening", "pre-v56-read-only-execution-gate", "controlled-read-only-action-execution",
    ]
    rows = []
    for token in route_tokens:
        rows.append({"name": f"api-{token}", "status": "pass" if token in api_text else "blocked", "message": token})
    for flag in ["--execution-preview-receipts", "--execution-step-permission-classifier", "--read-only-command-allowlist", "--controlled-read-only-action-execution"]:
        rows.append({"name": f"cli-{flag}", "status": "pass" if flag in main_text else "blocked", "message": flag})
    rows.append({"name": "dashboard-read-only-execution", "status": "pass" if "/read-only-execution" in dashboard_text else "blocked", "message": "/read-only-execution"})
    rows.append({"name": "get-routes-read-only", "status": "pass", "message": "GET routes build save=False previews; controlled execution is POST/CLI confirmed."})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v55.7", "status": status, "ok": status != "blocked", "execution_api_parity_gate": {"routes": route_tokens, "dashboard_page": "/read-only-execution", "post_execution_route": "/api/release/controlled-read-only-action-execution"}, "rows": rows, "message": "Execution/API parity gate verifies CLI, API, and dashboard coverage for execution preview and controlled read-only execution surfaces while keeping GET read-only."}
    if save:
        _write_json(EXECUTION_API_PARITY_GATE, report)
    return report


