def build_read_only_execution_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v56.7: verify CLI/API/dashboard parity for read-only diagnostics and evidence gathering."""
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8")
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8")
    tokens = [
        "read-only-execution-receipts", "expanded-diagnostic-allowlist", "read-only-output-classifier", "diagnostic-evidence-binder", "diagnostic-result-summaries", "pre-v57-evidence-gathering-gate", "evidence-gathering-maintenance-loop",
    ]
    rows = []
    for token in tokens:
        rows.append({"name": f"cli-{token}", "status": "pass" if f"--{token}" in main_text else "blocked", "message": f"--{token}"})
        rows.append({"name": f"api-{token}", "status": "pass" if token in api_text else "blocked", "message": f"/api/release/{token}"})
    rows.append({"name": "dashboard-evidence", "status": "pass" if "/evidence-gathering" in dashboard_text else "blocked", "message": "/evidence-gathering"})
    rows.append({"name": "get-read-only", "status": "pass", "message": "GET routes are previews; POST/CLI required for controlled execution"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v56.7", "status": status, "ok": status != "blocked", "read_only_execution_api_parity_gate": {"tokens": tokens, "dashboard_page": "/evidence-gathering", "post_execution_route": "/api/release/controlled-read-only-action-execution"}, "rows": rows, "message": "Read-only execution/API parity gate verifies CLI, API, and dashboard coverage for diagnostic receipts, evidence binding, summaries, and the evidence-gathering loop."}
    if save:
        _write_json(READ_ONLY_EXECUTION_API_PARITY_GATE, report)
    return report


def build_read_only_execution_privacy_package_hardening(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v56.8: keep diagnostic evidence runtime data out of source-only packages."""
    forbidden_runtime_paths = [
        "data/self_maintenance/read_only_execution_receipts.json",
        "data/self_maintenance/expanded_diagnostic_allowlist.json",
        "data/self_maintenance/read_only_output_classifier.json",
        "data/self_maintenance/diagnostic_evidence_binder.json",
        "data/self_maintenance/diagnostic_result_summaries.json",
        "data/self_maintenance/pre_v57_evidence_gathering_gate.json",
        "data/self_maintenance/evidence_gathering_maintenance_loop.json",
        "data/execution/",
        "data/diagnostics/evidence/",
    ]
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    inventory_text = json.dumps(privacy, sort_keys=True, default=str)
    packaged = [path for path in forbidden_runtime_paths if path in inventory_text]
    payload = {
        "schema_version": "eidolon.read_only_execution_privacy_package_hardening.v1",
        "project_id": project_id,
        "created_at": _now(),
        "forbidden_runtime_paths": forbidden_runtime_paths,
        "packaged_runtime_paths": packaged,
        "source_only_package_required": True,
        "diagnostic_evidence_packaged": bool(packaged),
        "privacy_scan_status": privacy.get("status"),
    }
    rows = [
        {"name": "runtime-paths-listed", "status": "pass" if forbidden_runtime_paths else "blocked", "message": str(len(forbidden_runtime_paths))},
        {"name": "runtime-excluded", "status": "pass" if not packaged else "blocked", "message": ", ".join(packaged) or "none packaged"},
        {"name": "package-privacy-scan", "status": _report_gate_status(privacy), "message": str(privacy.get("message", ""))[:180]},
        {"name": "source-only", "status": "pass" if payload["source_only_package_required"] else "blocked", "message": "source-only packages remain default"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v56.8", "status": status, "ok": status != "blocked", "read_only_execution_privacy_package_hardening": payload, "rows": rows, "message": "Read-only execution privacy/package hardening excludes receipts, output logs, diagnostic evidence, result summaries, and operator review records from source-only releases."}
    if save:
        _write_json(READ_ONLY_EXECUTION_PRIVACY_PACKAGE_HARDENING, report)
    return report


def build_pre_v57_evidence_gathering_gate(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v56.9: final gate before diagnostic evidence feeds maintenance planning."""
    checks = {
        "read_only_receipts": build_read_only_execution_receipts(project_id=project_id, command_key=command_key, save=False),
        "expanded_allowlist": build_expanded_diagnostic_allowlist(project_id=project_id, save=False),
        "output_classifier": build_read_only_output_classifier(project_id=project_id, command_key=command_key, save=False),
        "evidence_binder": build_diagnostic_evidence_binder(project_id=project_id, command_key=command_key, goal=goal, save=False),
        "result_summaries": build_diagnostic_result_summaries(project_id=project_id, command_key=command_key, save=False),
        "dashboard_polish": build_read_only_execution_dashboard_polish(project_id=project_id, save=False),
        "api_parity": build_read_only_execution_api_parity_gate(project_id=project_id, save=False),
        "privacy": build_read_only_execution_privacy_package_hardening(project_id=project_id, save=False),
    }
    rows = [{"name": name, "status": _report_gate_status(report), "message": str(report.get("message", ""))[:180]} for name, report in checks.items()]
    rows.extend([
        {"name": "no-mutation-possible", "status": "pass", "message": "diagnostic evidence is read-only and command-keyed"},
        {"name": "no-source-apply-approval", "status": "pass", "message": "evidence gathering cannot authorize source apply"},
        {"name": "no-memory-publish-live-rollback-identity-approval", "status": "pass", "message": "evidence gathering grants no unrelated approval"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v56.9", "status": status, "ok": status != "blocked", "gate_ready": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "source_apply_approved": False, "memory_write_approved": False, "publish_approved": False, "live_apply_approved": False, "rollback_approved": False, "identity_update_approved": False, "message": "Pre-v57 evidence-gathering gate verifies read-only receipts, expanded allowlist, output classifier, evidence binder, summaries, dashboard/API parity, privacy packaging, and no mutation from diagnostics."}
    if save:
        _write_json(PRE_V57_EVIDENCE_GATHERING_GATE, report)
    return report


def build_evidence_gathering_maintenance_loop(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", execute: bool = False, confirmation: str | None = None, save: bool = True) -> dict[str, Any]:
    """v57.0: use controlled read-only diagnostics as maintenance planning evidence."""
    goal_text = goal or "improve release dashboard performance"
    planner = {
        "schema_version": "eidolon.diagnostic_goal_to_evidence_planner.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "selected_command_keys": [command_key, "readme-integrity-preview", "package-privacy-scan-preview"],
        "selection_reason": "Use narrow diagnostics to check version/readme/privacy evidence before proposing maintenance changes.",
    }
    pre_gate = build_pre_v57_evidence_gathering_gate(project_id=project_id, goal=goal_text, command_key=command_key, save=False)
    execution_report = build_controlled_read_only_action_execution(project_id=project_id, command_key=command_key, confirmation=confirmation, execute=execute, goal=goal_text, save=False)
    execution = execution_report.get("controlled_read_only_action_execution") or {}
    result = execution.get("execution_result") or {"executed": False, "status": "preview"}
    classifier = build_read_only_output_classifier(project_id=project_id, command_key=command_key, result=result, save=False)
    summary = build_diagnostic_result_summaries(project_id=project_id, command_key=command_key, result=result, save=False)
    binder = build_diagnostic_evidence_binder(project_id=project_id, command_key=command_key, goal=goal_text, save=False)
    supports_plan = bool((summary.get("diagnostic_result_summaries") or {}).get("supports_current_plan")) or result.get("status") == "pass"
    contradicts_plan = result.get("status") == "blocked" or result.get("returncode") not in (None, 0)
    loop = {
        "schema_version": "eidolon.evidence_gathering_maintenance_loop.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "evidence_collection_receipt_id": "evidence-collection-" + _sha256_text({"goal": goal_text, "command": command_key, "result": result, "gate": pre_gate.get("status")})[:12],
        "diagnostic_planner": planner,
        "pre_v57_gate_status": pre_gate.get("status"),
        "selected_command_key": command_key,
        "execution_preview_or_result": execution,
        "output_classifier": classifier.get("read_only_output_classifier"),
        "diagnostic_summary": summary.get("diagnostic_result_summaries"),
        "diagnostic_evidence_binder": binder.get("diagnostic_evidence_binder"),
        "evidence_supports_plan": supports_plan,
        "evidence_contradicts_plan": contradicts_plan,
        "plan_update_from_diagnostics": "Proceed with supervised maintenance planning using this evidence as non-authorizing context." if supports_plan and not contradicts_plan else "Collect more read-only evidence or inspect warnings before changing any plan.",
        "next_safe_operator_action": "Review evidence receipt, then decide whether to draft a supervised maintenance task. Do not treat evidence collection as source apply approval.",
        "source_apply_approved": False,
        "memory_write_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "identity_update_approved": False,
        "automatic_source_modification": False,
    }
    rows = [
        {"name": "pre-v57-gate", "status": _report_gate_status(pre_gate), "message": str(pre_gate.get("message", ""))[:180]},
        {"name": "evidence-receipt", "status": "pass" if loop.get("evidence_collection_receipt_id") else "blocked", "message": str(loop.get("evidence_collection_receipt_id"))},
        {"name": "execution-state", "status": _report_gate_status(execution_report), "message": str((execution.get("execution_result") or {}).get("message", ""))[:180]},
        {"name": "diagnostic-summary", "status": _report_gate_status(summary), "message": str(summary.get("message", ""))[:180]},
        {"name": "no-mutation", "status": "pass" if not loop.get("automatic_source_modification") and not any(loop.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved")) else "blocked", "message": "evidence loop grants no mutation approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.0", "status": status, "ok": status != "blocked", "evidence_gathering_maintenance_loop": loop, "rows": rows, "message": "Evidence-gathering maintenance loop selects read-only diagnostics, binds evidence receipts, interprets results for maintenance planning, and performs no source, memory, publish, live, rollback, or identity mutation."}
    if save:
        _write_json(EVIDENCE_GATHERING_MAINTENANCE_LOOP, report)
    return report


# v57.1-v58.0 evidence stabilization and evidence-grounded patch proposal loop

def _latest_evidence_loop(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import") -> dict[str, Any]:
    """Return a lightweight evidence-loop shape without invoking the full pre-v57 gate stack."""
    goal_text = goal or "improve release dashboard performance"
    payload = _read_only_command_payload(command_key)
    execution = build_controlled_read_only_action_execution(project_id=project_id, command_key=command_key, execute=False, goal=goal_text, save=False).get("controlled_read_only_action_execution") or {}
    result = execution.get("execution_result") or {"executed": False, "status": "preview", "message": "Preview evidence only."}
    summary_payload = {
        "summary_id": "diagnostic-summary-" + _sha256_text({"command": command_key, "status": result.get("status")})[:12],
        "status": result.get("status", "preview"),
        "supports_current_plan": result.get("status") in {"pass", "preview"},
        "more_evidence_needed": result.get("status") != "pass",
    }
    binder_payload = {
        "diagnostic_evidence_binder_id": "diagnostic-evidence-" + _sha256_text({"goal": goal_text, "command": command_key, "result": result.get("status")})[:12],
        "command_key": command_key,
        "command_hash": payload.get("command_hash") if payload else None,
        "goal": goal_text,
    }
    return {
        "schema_version": "eidolon.evidence_gathering_maintenance_loop.lightweight.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "evidence_collection_receipt_id": "evidence-collection-" + _sha256_text({"goal": goal_text, "command": command_key, "result": result.get("status")})[:12],
        "diagnostic_planner": {"selection_reason": "Use narrow read-only diagnostics to ground supervised maintenance planning."},
        "selected_command_key": command_key,
        "execution_preview_or_result": execution,
        "diagnostic_summary": summary_payload,
        "diagnostic_evidence_binder": binder_payload,
        "evidence_supports_plan": summary_payload["supports_current_plan"],
        "evidence_contradicts_plan": result.get("status") in {"blocked", "fail", "failed", "error"},
    }


def build_evidence_collection_receipts(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v57.1: make evidence-gathering runs hash-bound and reviewable."""
    goal_text = goal or "improve release dashboard performance"
    loop = _latest_evidence_loop(project_id=project_id, goal=goal_text, command_key=command_key)
    summary = loop.get("diagnostic_summary") or {}
    binder = loop.get("diagnostic_evidence_binder") or {}
    execution = loop.get("execution_preview_or_result") or {}
    expected = {
        "command_key": command_key,
        "expected_gate": (_read_only_command_payload(command_key) or {}).get("expected_gate", "unknown"),
        "expected_status": "pass-or-preview-with-review-warning",
    }
    observed = {
        "result_status": ((execution.get("execution_result") or {}).get("status") or "preview"),
        "summary_status": summary.get("status") or summary.get("result_status") or "preview",
        "loop_status": "supports_plan" if loop.get("evidence_supports_plan") else "review_required",
    }
    stale_warning = "preview evidence; refresh with confirmed read-only diagnostics before relying on it for patch proposals" if observed["result_status"] == "preview" else "none"
    receipt = {
        "schema_version": "eidolon.evidence_collection_receipts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "command_key": command_key,
        "evidence_collection_receipt_id": "evidence-receipt-" + _sha256_text({"goal": goal_text, "command": command_key, "loop": loop.get("evidence_collection_receipt_id")})[:12],
        "diagnostic_command_receipt_hashes": [
            _sha256_text(loop.get("execution_preview_or_result") or {}),
            _sha256_text(summary),
            _sha256_text(binder),
        ],
        "evidence_bundle_hash": _sha256_text({"loop": loop, "summary": summary, "binder": binder}),
        "why_this_command_was_selected": (loop.get("diagnostic_planner") or {}).get("selection_reason", "Selected as a narrow read-only diagnostic for maintenance evidence."),
        "what_this_evidence_proves": "The selected read-only diagnostic can be bound to a supervised maintenance plan as non-authorizing evidence.",
        "what_this_evidence_does_not_prove": "It does not approve source apply, memory writes/removals, publish, live apply, rollback, identity updates, or arbitrary command execution.",
        "expected_result": expected,
        "observed_result": observed,
        "stale_evidence_warning": stale_warning,
        "operator_review_required": observed["result_status"] != "pass",
        "source_apply_approved": False,
        "memory_write_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "receipt-id", "status": "pass" if receipt.get("evidence_collection_receipt_id") else "blocked", "message": str(receipt.get("evidence_collection_receipt_id"))},
        {"name": "bundle-hash", "status": "pass" if receipt.get("evidence_bundle_hash") else "blocked", "message": str(receipt.get("evidence_bundle_hash"))[:16]},
        {"name": "expected-vs-observed", "status": "warn" if receipt["operator_review_required"] else "pass", "message": f"observed={observed['result_status']}"},
        {"name": "no-approval-leakage", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved")) else "blocked", "message": "evidence receipt is not approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.1", "status": status, "ok": status != "blocked", "evidence_collection_receipts": receipt, "rows": rows, "message": "Evidence collection receipts bind diagnostic command results, evidence bundle hashes, expected-vs-observed state, stale warnings, and non-approval boundaries."}
    if save:
        _write_json(EVIDENCE_COLLECTION_RECEIPTS, report)
    return report


def build_diagnostic_issue_classifier(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v57.2: classify diagnostic findings for safer evidence-to-patch reasoning."""
    receipt = build_evidence_collection_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("evidence_collection_receipts") or {}
    observed = receipt.get("observed_result") or {}
    result_status = str(observed.get("result_status", "preview")).lower()
    categories = []
    if result_status == "pass":
        categories.append("clean_pass")
    elif result_status == "preview":
        categories.append("expected_warning")
        categories.append("operator_review_required")
    elif result_status in {"blocked", "fail", "failed", "error"}:
        categories.append("failed_verification")
        categories.append("operator_review_required")
    else:
        categories.append("warning")
        categories.append("operator_review_required")
    if command_key == "dashboard-route-timing-preview":
        categories.append("dashboard_api_route_concern")
    if command_key == "package-privacy-scan-preview":
        categories.append("privacy_package_concern")
    if command_key == "readme-integrity-preview":
        categories.append("readme_documentation_drift")
    if command_key == "version-import":
        categories.append("version_surface_check")
    classifier = {
        "schema_version": "eidolon.diagnostic_issue_classifier.v1",
        "project_id": project_id,
        "created_at": _now(),
        "command_key": command_key,
        "evidence_collection_receipt_id": receipt.get("evidence_collection_receipt_id"),
        "issue_classifier_id": "diagnostic-issue-" + _sha256_text({"receipt": receipt.get("evidence_bundle_hash"), "command": command_key, "status": result_status})[:12],
        "issue_categories": categories,
        "severity": "review" if "operator_review_required" in categories else "clean",
        "patch_proposal_allowed": "failed_verification" in categories or "dashboard_api_route_concern" in categories or "readme_documentation_drift" in categories or "privacy_package_concern" in categories,
        "patch_proposal_should_be_sandbox_only": True,
        "operator_review_required": "operator_review_required" in categories,
        "source_apply_approved": False,
        "memory_write_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
    }
    rows = [
        {"name": "classifier-id", "status": "pass" if classifier.get("issue_classifier_id") else "blocked", "message": str(classifier.get("issue_classifier_id"))},
        {"name": "categories", "status": "pass" if categories else "blocked", "message": ", ".join(categories)},
        {"name": "sandbox-only", "status": "pass" if classifier.get("patch_proposal_should_be_sandbox_only") else "blocked", "message": "evidence can only drive sandbox proposals"},
        {"name": "no-approval-leakage", "status": "pass" if not any(classifier.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved")) else "blocked", "message": "classifier grants no approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.2", "status": status, "ok": status != "blocked", "diagnostic_issue_classifier": classifier, "rows": rows, "message": "Diagnostic issue classifier labels evidence findings as clean, expected warnings, verification failures, route concerns, package concerns, README drift, or operator-review-required."}
    if save:
        _write_json(DIAGNOSTIC_ISSUE_CLASSIFIER, report)
    return report


def build_evidence_conflict_staleness_resolver(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v57.3: detect stale/conflicting diagnostic evidence without mutating plans."""
    receipt_report = build_evidence_collection_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False)
    receipt = receipt_report.get("evidence_collection_receipts") or {}
    current_source_hash = _sha256_text({
        "dashboard": _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")[:2000],
        "api": _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")[:2000],
        "self_maintenance_version": SELF_MAINTENANCE_VERSION,
        "readme_head": _read_text(ROOT_DIR / "README_NEXT_STEPS.md")[:2000],
    })
    stale_reasons = []
    if receipt.get("operator_review_required"):
        stale_reasons.append("preview_or_warning_evidence_requires_refresh_before_patch proposal")
    if receipt.get("stale_evidence_warning") not in (None, "none"):
        stale_reasons.append("stale_warning_present")
    conflicts = []
    observed = receipt.get("observed_result") or {}
    if observed.get("result_status") in {"blocked", "fail", "failed", "error"}:
        conflicts.append("diagnostic_result_blocks_plan")
    resolver = {
        "schema_version": "eidolon.evidence_conflict_staleness_resolver.v1",
        "project_id": project_id,
        "created_at": _now(),
        "evidence_collection_receipt_id": receipt.get("evidence_collection_receipt_id"),
        "current_source_context_hash": current_source_hash,
        "stale_reasons": stale_reasons,
        "conflicts": conflicts,
        "needs_refresh": bool(stale_reasons),
        "needs_operator_review": bool(stale_reasons or conflicts),
        "resolution_preview": "Refresh read-only diagnostics and review warnings before creating or trusting any sandbox patch proposal." if stale_reasons or conflicts else "Evidence is current enough for a sandbox-only proposal preview.",
        "automatic_mutation": False,
        "source_apply_approved": False,
        "memory_write_approved": False,
    }
    rows = [
        {"name": "source-context-hash", "status": "pass" if resolver.get("current_source_context_hash") else "blocked", "message": resolver["current_source_context_hash"][:16]},
        {"name": "staleness", "status": "warn" if stale_reasons else "pass", "message": ", ".join(stale_reasons) or "none"},
        {"name": "conflicts", "status": "warn" if conflicts else "pass", "message": ", ".join(conflicts) or "none"},
        {"name": "no-mutation", "status": "pass" if not resolver.get("automatic_mutation") and not resolver.get("source_apply_approved") else "blocked", "message": "resolver only warns"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.3", "status": status, "ok": status != "blocked", "evidence_conflict_staleness_resolver": resolver, "rows": rows, "message": "Evidence conflict and staleness resolver detects stale or conflicting diagnostics and produces review warnings without mutating plans or source."}
    if save:
        _write_json(EVIDENCE_CONFLICT_STALENESS_RESOLVER, report)
    return report


def build_evidence_to_plan_update_drafts(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v57.4: draft plan updates from evidence without applying them."""
    goal_text = goal or "improve release dashboard performance"
    evidence = build_evidence_collection_receipts(project_id=project_id, goal=goal_text, command_key=command_key, save=False).get("evidence_collection_receipts") or {}
    issue = build_diagnostic_issue_classifier(project_id=project_id, goal=goal_text, command_key=command_key, save=False).get("diagnostic_issue_classifier") or {}
    resolver = build_evidence_conflict_staleness_resolver(project_id=project_id, goal=goal_text, command_key=command_key, save=False).get("evidence_conflict_staleness_resolver") or {}
    original_plan = {"goal": goal_text, "next_action": "collect diagnostics before patch proposal", "hash": _sha256_text({"goal": goal_text, "stage": "pre-evidence"})}
    updated_steps = [
        "Review evidence collection receipt and issue classifier.",
        "If evidence is stale, refresh allowlisted diagnostics before proposing changes.",
        "Create only a sandbox patch proposal bound to the evidence bundle.",
        "Run verification preview commands before any guarded source-apply handoff.",
    ]
    draft = {
        "schema_version": "eidolon.evidence_to_plan_update_drafts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal_text,
        "plan_update_draft_id": "evidence-plan-draft-" + _sha256_text({"goal": goal_text, "evidence": evidence.get("evidence_bundle_hash"), "issue": issue.get("issue_classifier_id")})[:12],
        "original_plan_hash": original_plan["hash"],
        "evidence_bundle_hash": evidence.get("evidence_bundle_hash"),
        "updated_plan_hash": _sha256_text({"goal": goal_text, "steps": updated_steps, "issue": issue.get("issue_categories")}),
        "changed_rationale": "Diagnostic evidence now informs which sandbox proposal should be drafted, while stale/conflict warnings remain unresolved until operator review.",
        "updated_steps": updated_steps,
        "unresolved_warnings": (resolver.get("stale_reasons") or []) + (resolver.get("conflicts") or []),
        "next_safe_operator_action": "Review this draft, then decide whether to generate an evidence-grounded sandbox patch proposal. Do not apply source from this draft.",
        "draft_only": True,
        "source_apply_approved": False,
        "memory_write_approved": False,
    }
    rows = [
        {"name": "draft-id", "status": "pass" if draft.get("plan_update_draft_id") else "blocked", "message": str(draft.get("plan_update_draft_id"))},
        {"name": "evidence-binding", "status": "pass" if draft.get("evidence_bundle_hash") else "warn", "message": str(draft.get("evidence_bundle_hash"))[:16]},
        {"name": "unresolved-warnings", "status": "warn" if draft.get("unresolved_warnings") else "pass", "message": ", ".join(draft.get("unresolved_warnings") or []) or "none"},
        {"name": "draft-only", "status": "pass" if draft.get("draft_only") and not draft.get("source_apply_approved") else "blocked", "message": "no source apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.4", "status": status, "ok": status != "blocked", "evidence_to_plan_update_drafts": draft, "rows": rows, "message": "Evidence-to-plan update drafts bind diagnostic evidence to updated supervised planning rationale without applying source or memory changes."}
    if save:
        _write_json(EVIDENCE_TO_PLAN_UPDATE_DRAFTS, report)
    return report


def build_diagnostic_coverage_map(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v57.5: map available and missing diagnostic evidence."""
    allowlist = build_expanded_diagnostic_allowlist(project_id=project_id, save=False).get("expanded_diagnostic_allowlist") or {}
    available_keys = {cmd.get("command_key") for cmd in allowlist.get("allowed_commands", [])}
    required = {
        "compile_check": "py-compile-core",
        "version_import": "version-import",
        "readme_integrity": "readme-integrity-preview",
        "package_privacy": "package-privacy-scan-preview",
        "route_timing": "dashboard-route-timing-preview",
        "smoke_check": "install-smoke-preview",
        "dashboard_api_parity": "api-parity-preview",
        "release_source_only": "source-only-zip-inspection-preview",
    }
    rows_map = []
    for name, key in required.items():
        rows_map.append({"coverage_item": name, "command_key": key, "available": key in available_keys, "status": "covered" if key in available_keys else "missing_preview_command"})
    covered = sum(1 for row in rows_map if row["available"])
    coverage = {
        "schema_version": "eidolon.diagnostic_coverage_map.v1",
        "project_id": project_id,
        "created_at": _now(),
        "goal": goal or "improve release dashboard performance",
        "coverage_map_id": "diagnostic-coverage-" + _sha256_text(rows_map)[:12],
        "coverage_items": rows_map,
        "covered_count": covered,
        "required_count": len(required),
        "coverage_ratio": round(covered / max(len(required), 1), 3),
        "enough_for_sandbox_patch_proposal": covered >= 5,
        "missing_items": [row for row in rows_map if not row["available"]],
        "next_safe_operator_action": "Add more exact read-only diagnostics before relying on high-risk patch proposals." if covered < len(required) else "Coverage is broad enough for a sandbox-only proposal preview.",
    }
    rows = [
        {"name": "coverage-id", "status": "pass" if coverage.get("coverage_map_id") else "blocked", "message": coverage.get("coverage_map_id", "")},
        {"name": "covered-count", "status": "pass" if covered >= 5 else "warn", "message": f"{covered}/{len(required)}"},
        {"name": "sandbox-ready", "status": "pass" if coverage["enough_for_sandbox_patch_proposal"] else "warn", "message": str(coverage["enough_for_sandbox_patch_proposal"])},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.5", "status": status, "ok": status != "blocked", "diagnostic_coverage_map": coverage, "rows": rows, "message": "Diagnostic coverage map shows which read-only evidence exists and which verification surfaces are still missing before sandbox patch proposals."}
    if save:
        _write_json(DIAGNOSTIC_COVERAGE_MAP, report)
    return report


