def build_evidence_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v57.7: verify CLI/API/dashboard coverage for v57.x-v58 evidence proposal surfaces."""
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    tokens = [
        "evidence-collection-receipts", "diagnostic-issue-classifier", "evidence-conflict-staleness-resolver", "evidence-to-plan-update-drafts", "diagnostic-coverage-map", "evidence-dashboard-polish", "evidence-api-parity-gate", "evidence-privacy-package-hardening", "pre-v58-patch-proposal-gate", "evidence-grounded-patch-proposal",
    ]
    rows = []
    for token in tokens:
        rows.append({"name": f"cli-{token}", "status": "pass" if token.replace('-', '_') in main_text or token in main_text else "blocked", "message": token})
        rows.append({"name": f"api-{token}", "status": "pass" if token in api_text else "blocked", "message": token})
    rows.append({"name": "dashboard-patch-proposals", "status": "pass" if "/patch-proposals" in dashboard_text else "blocked", "message": "/patch-proposals"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v57.7", "status": status, "ok": status != "blocked", "evidence_api_parity_gate": {"tokens": tokens, "dashboard_page": "/patch-proposals", "get_routes_read_only": True}, "rows": rows, "message": "Evidence/API parity gate verifies CLI, API, and dashboard coverage for evidence receipts, coverage maps, plan update drafts, and sandbox patch proposal previews."}
    if save:
        _write_json(EVIDENCE_API_PARITY_GATE, report)
    return report


def build_evidence_privacy_package_hardening(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v57.8: keep evidence and proposal runtime records out of source packages."""
    packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py") + "\n" + _read_text(ROOT_DIR / "conscious_agent" / "release_installation.py")
