def _sandbox_execution_preview(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import") -> dict[str, Any]:
    """Return the v59 sandbox execution payload in preview mode without writing runtime state."""
    return build_controlled_sandbox_patch_execution(project_id=project_id, goal=goal, command_key=command_key, confirmation=None, execute=False, save=False).get("controlled_sandbox_patch_execution") or {}


def _sandbox_baseline_hash() -> str:
    pieces: dict[str, str] = {}
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/self_maintenance.py", "conscious_agent/dashboard.py", "conscious_agent/api_server.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            pieces[rel] = hashlib.sha256(path.read_bytes()).hexdigest()
    return _sha256_text(pieces)


def build_sandbox_execution_receipts(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v59.1: make sandbox patch execution hash-bound and reviewable."""
    sandbox = _sandbox_execution_preview(project_id=project_id, goal=goal, command_key=command_key)
    proposal = build_patch_proposal_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_proposal_receipts") or {}
    receipt = {
        "schema_version": "eidolon.sandbox_execution_receipts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "sandbox_execution_receipt_id": "sandbox-execution-receipt-" + _sha256_text({"sandbox": sandbox.get("sandbox_patch_execution_id"), "proposal": proposal.get("patch_proposal_receipt_id")})[:12],
        "bound_sandbox_patch_execution_id": sandbox.get("sandbox_patch_execution_id"),
        "bound_proposal_receipt_id": proposal.get("patch_proposal_receipt_id"),
        "bound_proposal_hash": sandbox.get("bound_proposal_hash") or (proposal.get("hashes") or {}).get("proposal_hash"),
        "sandbox_workspace_hash": _sha256_text({"sandbox_path": sandbox.get("sandbox_path"), "baseline": _sandbox_baseline_hash()}),
        "predicted_touched_files_hash": _sha256_text(sandbox.get("predicted_touched_files") or []),
        "actual_touched_files_hash": _sha256_text(sandbox.get("actual_touched_files") or []),
        "predicted_vs_actual": sandbox.get("predicted_vs_actual") or "preview-only",
        "verification_result_hash": _sha256_text(sandbox.get("verification_results") or []),
        "rollback_expectation_hash": _sha256_text(sandbox.get("rollback_expectation_check") or ""),
        "what_this_sandbox_run_proves": "A reviewed proposal can be bound to a sandbox execution preview or confirmed temp-sandbox rehearsal without touching live source.",
        "what_this_sandbox_run_does_not_prove": "It does not approve live source apply, publish, live apply, rollback, memory writes, or identity updates.",
        "operator_review_required": True,
        "source_apply_approved": False,
        "memory_write_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "receipt-id", "status": "pass" if receipt.get("sandbox_execution_receipt_id") else "blocked", "message": str(receipt.get("sandbox_execution_receipt_id"))},
        {"name": "proposal-binding", "status": "pass" if receipt.get("bound_proposal_receipt_id") else "blocked", "message": str(receipt.get("bound_proposal_receipt_id"))},
        {"name": "workspace-hash", "status": "pass" if receipt.get("sandbox_workspace_hash") else "blocked", "message": str(receipt.get("sandbox_workspace_hash"))[:16]},
        {"name": "review-required", "status": "pass", "message": "sandbox receipts are evidence, not approval"},
        {"name": "no-approval-leakage", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "memory_write_approved", "publish_approved", "live_apply_approved", "rollback_approved", "identity_update_approved")) else "blocked", "message": "sandbox receipt grants no guarded approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.1", "status": status, "ok": status != "blocked", "sandbox_execution_receipts": receipt, "rows": rows, "message": "Sandbox execution receipts bind proposal receipts, workspace hashes, predicted/actual touched-file hashes, verification results, rollback expectations, and non-approval boundaries."}
    if save:
        _write_json(SANDBOX_EXECUTION_RECEIPTS, report)
    return report


def build_sandbox_verification_matrix(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v59.2: track sandbox verification coverage and results."""
    receipts = build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_execution_receipts") or {}
    plan = build_patch_verification_plan(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_verification_plan") or {}
    command_names = list(plan.get("commands") or [])
    matrix_rows = [
        {"check": "compile", "required": True, "observed": "preview", "status": "warn", "command_hint": "python -m py_compile conscious_agent/*.py tools/smoke_check.py"},
        {"check": "version-import", "required": True, "observed": "preview", "status": "warn", "command_hint": "PYTHONPATH=conscious_agent python -c ..."},
        {"check": "feature-gate", "required": True, "observed": "preview", "status": "warn", "command_hint": "python conscious_agent/main.py --pre-v60-source-apply-handoff-gate --readiness-json"},
        {"check": "package-privacy-scan", "required": True, "observed": "preview", "status": "warn", "command_hint": "python conscious_agent/main.py --package-privacy-scan --readiness-json"},
        {"check": "readme-history-consistency", "required": True, "observed": "preview", "status": "warn", "command_hint": "README_NEXT_STEPS.md and README_RELEASE_HISTORY.md updated"},
    ]
    matrix = {
        "schema_version": "eidolon.sandbox_verification_matrix.v1",
        "project_id": project_id,
        "created_at": _now(),
        "sandbox_execution_receipt_id": receipts.get("sandbox_execution_receipt_id"),
        "verification_plan_id": plan.get("verification_plan_id"),
        "required_commands": command_names,
        "matrix_rows": matrix_rows,
        "all_required_passed": False,
        "preview_only": True,
        "source_apply_approved": False,
    }
    rows = [
        {"name": "receipt-bound", "status": "pass" if matrix.get("sandbox_execution_receipt_id") else "blocked", "message": str(matrix.get("sandbox_execution_receipt_id"))},
        {"name": "verification-plan-bound", "status": "pass" if matrix.get("verification_plan_id") else "warn", "message": str(matrix.get("verification_plan_id"))},
        {"name": "matrix-row-count", "status": "pass" if len(matrix_rows) >= 5 else "blocked", "message": str(len(matrix_rows))},
        {"name": "preview-not-approval", "status": "pass" if not matrix.get("source_apply_approved") else "blocked", "message": "verification matrix does not approve source apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.2", "status": status, "ok": status != "blocked", "sandbox_verification_matrix": matrix, "rows": rows, "message": "Sandbox verification matrix tracks compile, version import, feature gate, privacy scan, dashboard/API timing, smoke, and README/history checks as review evidence only."}
    if save:
        _write_json(SANDBOX_VERIFICATION_MATRIX, report)
    return report


def build_sandbox_drift_detector(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v59.3: detect sandbox proposal/live-source drift before any handoff."""
    receipts = build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_execution_receipts") or {}
    patch_receipt = build_patch_proposal_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_proposal_receipts") or {}
    current_baseline = _sandbox_baseline_hash()
    predicted_hash = receipts.get("predicted_touched_files_hash")
    actual_hash = receipts.get("actual_touched_files_hash")
    drift_flags = []
    if actual_hash == _sha256_text([]):
        drift_flags.append("actual-touched-files-preview-only")
    if predicted_hash and actual_hash and predicted_hash != actual_hash:
        drift_flags.append("predicted-vs-actual-differs-or-preview")
    detector = {
        "schema_version": "eidolon.sandbox_drift_detector.v1",
        "project_id": project_id,
        "created_at": _now(),
        "sandbox_execution_receipt_id": receipts.get("sandbox_execution_receipt_id"),
        "proposal_receipt_hash": _sha256_text(patch_receipt),
        "source_baseline_hash": current_baseline,
        "readme_version_notes_hash": _sha256_text({"next": (ROOT_DIR / "README_NEXT_STEPS.md").read_text(encoding="utf-8") if (ROOT_DIR / "README_NEXT_STEPS.md").exists() else "", "history": (ROOT_DIR / "README_RELEASE_HISTORY.md").read_text(encoding="utf-8") if (ROOT_DIR / "README_RELEASE_HISTORY.md").exists() else ""}),
        "predicted_touched_files_hash": predicted_hash,
        "actual_touched_files_hash": actual_hash,
        "drift_flags": drift_flags,
        "operator_review_required": bool(drift_flags),
        "source_apply_approved": False,
    }
    rows = [
        {"name": "baseline-hash", "status": "pass" if detector.get("source_baseline_hash") else "blocked", "message": str(detector.get("source_baseline_hash"))[:16]},
        {"name": "receipt-bound", "status": "pass" if detector.get("sandbox_execution_receipt_id") else "blocked", "message": str(detector.get("sandbox_execution_receipt_id"))},
        {"name": "drift-flags", "status": "warn" if drift_flags else "pass", "message": ", ".join(drift_flags) if drift_flags else "no drift flags in preview metadata"},
        {"name": "no-live-mutation", "status": "pass", "message": "drift detector is read-only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.3", "status": status, "ok": status != "blocked", "sandbox_drift_detector": detector, "rows": rows, "message": "Sandbox drift detector compares proposal prediction, sandbox actuals, live source baseline, README/history notes, and verification expectations without mutating source."}
    if save:
        _write_json(SANDBOX_DRIFT_DETECTOR, report)
    return report


def build_sandbox_rollback_rehearsal(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v59.4: rehearse rollback expectations inside sandbox evidence only."""
    receipts = build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_execution_receipts") or {}
    diff = build_patch_diff_preview_drafts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_diff_preview_drafts") or {}
    changed_files = list(diff.get("proposed_files") or [])
    rehearsal = {
        "schema_version": "eidolon.sandbox_rollback_rehearsal.v1",
        "project_id": project_id,
        "created_at": _now(),
        "sandbox_execution_receipt_id": receipts.get("sandbox_execution_receipt_id"),
        "rollback_rehearsal_id": "sandbox-rollback-rehearsal-" + _sha256_text({"receipt": receipts.get("sandbox_execution_receipt_id"), "files": changed_files})[:12],
        "changed_file_list": changed_files,
        "backup_expectation": "Live source apply handoff must create source-apply backups before touching real files.",
        "sandbox_disposal": "Temporary sandbox rollback is deletion of the sandbox workspace only.",
        "rollback_route_availability": "Use existing v44 controlled rollback only after a real guarded source apply creates backups.",
        "what_rollback_would_restore": "Sandbox rehearsal only restores/discards temp sandbox files; it would not restore live source because live source is untouched.",
        "what_rollback_would_not_restore": "It does not revoke publish approval, live apply approval, durable memory, or identity records.",
        "rollback_approved": False,
        "source_apply_approved": False,
    }
    rows = [
        {"name": "rehearsal-id", "status": "pass" if rehearsal.get("rollback_rehearsal_id") else "blocked", "message": str(rehearsal.get("rollback_rehearsal_id"))},
        {"name": "changed-files", "status": "pass" if changed_files else "warn", "message": f"{len(changed_files)} predicted file(s)"},
        {"name": "rollback-separated", "status": "pass" if not rehearsal.get("rollback_approved") else "blocked", "message": "sandbox rollback rehearsal does not approve live rollback"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.4", "status": status, "ok": status != "blocked", "sandbox_rollback_rehearsal": rehearsal, "rows": rows, "message": "Sandbox rollback rehearsal previews temp sandbox disposal, source backup expectations, and rollback boundaries without approving rollback or source apply."}
    if save:
        _write_json(SANDBOX_ROLLBACK_REHEARSAL, report)
    return report


def build_sandbox_apply_candidate_drafts(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v59.5: draft source-apply candidates from sandbox evidence without applying source."""
    receipts = build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_execution_receipts") or {}
    matrix = build_sandbox_verification_matrix(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_verification_matrix") or {}
    drift = build_sandbox_drift_detector(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_drift_detector") or {}
    rollback = build_sandbox_rollback_rehearsal(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_rollback_rehearsal") or {}
    patch = build_patch_proposal_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_proposal_receipts") or {}
    candidate = {
        "schema_version": "eidolon.sandbox_apply_candidate_drafts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "apply_candidate_id": "sandbox-apply-candidate-" + _sha256_text({"sandbox": receipts.get("sandbox_execution_receipt_id"), "proposal": patch.get("patch_proposal_receipt_id")})[:12],
        "sandbox_execution_receipt_id": receipts.get("sandbox_execution_receipt_id"),
        "proposal_receipt_id": patch.get("patch_proposal_receipt_id"),
        "patch_diff_hash": (patch.get("hashes") or {}).get("patch_rationale_hash"),
        "touched_files_hash": receipts.get("predicted_touched_files_hash"),
        "verification_summary_hash": _sha256_text(matrix),
        "drift_summary_hash": _sha256_text(drift),
        "rollback_rehearsal_hash": _sha256_text(rollback),
        "required_confirmation_phrase_preview": "HANDOFF_SANDBOX_TO_SOURCE_APPLY " + str(receipts.get("sandbox_execution_receipt_id")),
        "review_required_before_source_apply": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "candidate-id", "status": "pass" if candidate.get("apply_candidate_id") else "blocked", "message": str(candidate.get("apply_candidate_id"))},
        {"name": "sandbox-receipt-bound", "status": "pass" if candidate.get("sandbox_execution_receipt_id") else "blocked", "message": str(candidate.get("sandbox_execution_receipt_id"))},
        {"name": "review-required", "status": "pass" if candidate.get("review_required_before_source_apply") else "blocked", "message": "candidate is draft-only"},
        {"name": "no-source-apply", "status": "pass" if not candidate.get("source_apply_approved") else "blocked", "message": "draft does not apply source"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.5", "status": status, "ok": status != "blocked", "sandbox_apply_candidate_drafts": candidate, "rows": rows, "message": "Sandbox apply candidate drafts package sandbox receipts, proposal hashes, verification summaries, drift checks, rollback rehearsal, and exact handoff phrase previews without applying source."}
    if save:
        _write_json(SANDBOX_APPLY_CANDIDATE_DRAFTS, report)
    return report


