def build_sandbox_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v59.7: verify CLI/API/dashboard parity for sandbox and handoff state."""
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8")
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8")
    tokens = [
        "sandbox-execution-receipts", "sandbox-verification-matrix", "sandbox-drift-detector", "sandbox-rollback-rehearsal", "sandbox-apply-candidate-drafts", "sandbox-dashboard-polish", "sandbox-api-parity-gate", "sandbox-privacy-package-hardening", "pre-v60-source-apply-handoff-gate", "controlled-sandbox-source-apply-handoff",
    ]
    missing_cli = [t for t in tokens if "--" + t not in main_text]
    missing_api = [t for t in tokens if t not in api_text]
    missing_dashboard = [p for p in ["/sandbox-patch-execution", "/source-apply-handoff"] if p not in dashboard_text]
    rows = [
        {"name": "cli-tokens", "status": "pass" if not missing_cli else "blocked", "message": f"missing={missing_cli}"},
        {"name": "api-tokens", "status": "pass" if not missing_api else "blocked", "message": f"missing={missing_api}"},
        {"name": "dashboard-pages", "status": "pass" if not missing_dashboard else "blocked", "message": f"missing={missing_dashboard}"},
        {"name": "get-read-only", "status": "pass", "message": "GET/API/dashboard views are read-only previews"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.7", "status": status, "ok": status != "blocked", "sandbox_api_parity_gate": {"tokens": tokens, "missing_cli": missing_cli, "missing_api": missing_api, "missing_dashboard": missing_dashboard, "get_routes_read_only": True}, "rows": rows, "message": "Sandbox/API parity gate verifies CLI, API, and dashboard coverage for sandbox receipts, verification matrix, drift detector, rollback rehearsal, apply candidates, privacy hardening, and controlled source-apply handoff previews."}
    if save:
        _write_json(SANDBOX_API_PARITY_GATE, report)
    return report


def build_sandbox_privacy_package_hardening(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v59.8: ensure sandbox runtime records and handoff drafts stay out of source packages."""
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    forbidden_fragments = [
        "data/self_maintenance/sandbox_execution_receipts.json", "data/self_maintenance/sandbox_verification_matrix.json", "data/self_maintenance/sandbox_drift_detector.json", "data/self_maintenance/sandbox_rollback_rehearsal.json", "data/self_maintenance/sandbox_apply_candidate_drafts.json", "data/self_maintenance/controlled_sandbox_source_apply_handoff.json", "data/self_maintenance/sandbox", "operator review record", "source apply handoff runtime",
    ]
    hardening = {"privacy_scan_status": privacy.get("status"), "forbidden_fragments": forbidden_fragments, "violations": privacy.get("violations") or [], "runtime_sandbox_records_packaged": False, "source_only_release": True}
    rows = [
        {"name": "package-privacy-scan", "status": _report_gate_status(privacy), "message": str(privacy.get("message", ""))[:180]},
        {"name": "runtime-sandbox-records", "status": "pass" if not hardening["runtime_sandbox_records_packaged"] else "blocked", "message": "runtime sandbox/handoff records excluded"},
        {"name": "source-only", "status": "pass" if hardening["source_only_release"] else "blocked", "message": "release package remains source-only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.8", "status": status, "ok": status != "blocked", "sandbox_privacy_package_hardening": hardening, "rows": rows, "message": "Sandbox privacy/package hardening verifies sandbox workspaces, execution receipts, verification logs, rollback rehearsal records, apply-candidate drafts, and handoff records remain outside source-only releases."}
    if save:
        _write_json(SANDBOX_PRIVACY_PACKAGE_HARDENING, report)
    return report


def build_pre_v60_source_apply_handoff_gate(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v59.9: final gate before controlled sandbox-to-source apply handoff."""
    checks = {
        "sandbox_receipts": build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "verification_matrix": build_sandbox_verification_matrix(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "drift_detector": build_sandbox_drift_detector(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "rollback_rehearsal": build_sandbox_rollback_rehearsal(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "apply_candidate": build_sandbox_apply_candidate_drafts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "dashboard": build_sandbox_dashboard_polish(project_id=project_id, save=False),
        "api_parity": build_sandbox_api_parity_gate(project_id=project_id, save=False),
        "privacy": build_sandbox_privacy_package_hardening(project_id=project_id, save=False),
    }
    rows = [{"name": name, "status": _report_gate_status(report), "message": str(report.get("message", ""))[:180]} for name, report in checks.items()]
    rows.append({"name": "no-live-source-mutation", "status": "pass", "message": "pre-v60 gate prepares handoff evidence and cannot apply source"})
    rows.append({"name": "handoff-not-approval", "status": "pass", "message": "handoff must use existing guarded source-apply exact confirmation"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v59.9", "status": status, "ok": status != "blocked", "gate_ready": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "source_apply_approved": False, "memory_write_approved": False, "publish_approved": False, "live_apply_approved": False, "rollback_approved": False, "identity_update_approved": False, "message": "Pre-v60 source-apply handoff gate verifies sandbox receipts, verification matrix, drift detection, rollback rehearsal, apply candidates, dashboard/API parity, privacy packaging, and no live source mutation from sandbox paths."}
    if save:
        _write_json(PRE_V60_SOURCE_APPLY_HANDOFF_GATE, report)
    return report


def build_controlled_sandbox_source_apply_handoff(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", confirmation: str | None = None, execute: bool = False, save: bool = True) -> dict[str, Any]:
    """v60.0: prepare a hash-bound handoff packet for the existing guarded source-apply path without applying source."""
    gate = build_pre_v60_source_apply_handoff_gate(project_id=project_id, goal=goal, command_key=command_key, save=False)
    candidate = build_sandbox_apply_candidate_drafts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_apply_candidate_drafts") or {}
    sandbox_receipt = build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_execution_receipts") or {}
    patch_receipt = build_patch_proposal_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_proposal_receipts") or {}
    required_confirmation = str(candidate.get("required_confirmation_phrase_preview") or ("HANDOFF_SANDBOX_TO_SOURCE_APPLY " + str(candidate.get("apply_candidate_id"))))
    confirmation_matched = bool(confirmation and confirmation.strip() == required_confirmation)
    handoff_packet = {
        "schema_version": "eidolon.controlled_sandbox_source_apply_handoff.v1",
        "project_id": project_id,
        "created_at": _now(),
        "stage": "v60.0",
        "apply_handoff_candidate_id": "source-apply-handoff-" + _sha256_text({"candidate": candidate.get("apply_candidate_id"), "sandbox": sandbox_receipt.get("sandbox_execution_receipt_id")})[:12],
        "sandbox_execution_receipt_id": sandbox_receipt.get("sandbox_execution_receipt_id"),
        "proposal_receipt_id": patch_receipt.get("patch_proposal_receipt_id"),
        "apply_candidate_id": candidate.get("apply_candidate_id"),
        "reviewed_artifact_set_hash": _sha256_text({"candidate": candidate, "sandbox_receipt": sandbox_receipt, "patch_receipt": patch_receipt}),
        "source_baseline_drift_check_hash": _sandbox_baseline_hash(),
        "rollback_backup_expectation": "Existing guarded source apply must create backups before writing real source; v44 rollback remains separate.",
        "pre_apply_verification_checklist": ["pre-v60 gate", "compile", "version import", "package privacy scan", "reviewed artifact hash match", "exact guarded source-apply confirmation"],
        "post_apply_verification_checklist": ["compile", "version import", "targeted feature gate", "package privacy scan", "install smoke when required", "rollback backup receipt check"],
        "required_confirmation_phrase": required_confirmation,
        "confirmation_phrase_hash": _sha256_text(required_confirmation),
        "confirmation_matched": confirmation_matched,
        "execute_requested": bool(execute),
        "handoff_record_written": False,
        "would_call_existing_guarded_source_apply": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
        "message": "Controlled handoff packet is ready for operator review. Use the existing guarded source-apply path separately with exact reviewed-artifact confirmation; this route does not apply source.",
    }
    if execute and confirmation_matched and gate.get("ok"):
        # Still do not apply source: v60 prepares the handoff packet only.
        handoff_packet["handoff_record_written"] = True
        handoff_packet["message"] = "Confirmed handoff packet recorded for review only. Live source was not modified and guarded source apply remains separate."
    elif execute and not confirmation_matched:
        handoff_packet["message"] = "Handoff refused because the exact confirmation phrase did not match. No source was touched."
    rows = [
        {"name": "pre-v60-gate", "status": _report_gate_status(gate), "message": str(gate.get("message", ""))[:180]},
        {"name": "candidate-bound", "status": "pass" if handoff_packet.get("apply_candidate_id") else "blocked", "message": str(handoff_packet.get("apply_candidate_id"))},
        {"name": "sandbox-receipt-bound", "status": "pass" if handoff_packet.get("sandbox_execution_receipt_id") else "blocked", "message": str(handoff_packet.get("sandbox_execution_receipt_id"))},
        {"name": "reviewed-artifact-hash", "status": "pass" if handoff_packet.get("reviewed_artifact_set_hash") else "blocked", "message": str(handoff_packet.get("reviewed_artifact_set_hash"))[:16]},
        {"name": "exact-confirmation", "status": "pass" if confirmation_matched else "warn", "message": "matched" if confirmation_matched else "exact handoff phrase required to record handoff packet"},
        {"name": "source-apply-separated", "status": "pass" if not handoff_packet.get("source_apply_approved") and not handoff_packet.get("would_call_existing_guarded_source_apply") else "blocked", "message": "handoff does not call source apply"},
        {"name": "no-approval-leakage", "status": "pass" if not any(handoff_packet.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved", "rollback_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "handoff grants no guarded approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.0", "status": status if confirmation_matched else "warn", "ok": status != "blocked", "controlled_sandbox_source_apply_handoff": handoff_packet, "rows": rows, "message": "Controlled sandbox-to-source apply handoff binds sandbox receipts, proposal receipts, reviewed artifact hashes, source baseline drift checks, rollback backup expectations, and verification checklists while leaving live source apply to the existing guarded exact-confirmation source-apply system."}
    if save:
        _write_json(CONTROLLED_SANDBOX_SOURCE_APPLY_HANDOFF, report)
    return report


