# v60.1-v61.0 source-apply handoff stabilization and dry-run bridge refinement


def _handoff_preview(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import") -> dict[str, Any]:
    """Return the v60 handoff packet without writing runtime state."""
    return build_controlled_sandbox_source_apply_handoff(
        project_id=project_id,
        goal=goal,
        command_key=command_key,
        confirmation=None,
        execute=False,
        save=False,
    ).get("controlled_sandbox_source_apply_handoff") or {}


def _source_baseline_file_hashes() -> dict[str, str]:
    """Hash stable source/documentation files used by the handoff bridge."""
    rels = [
        "README_NEXT_STEPS.md",
        "README_RELEASE_HISTORY.md",
        "conscious_agent/self_maintenance.py",
        "conscious_agent/dashboard.py",
        "conscious_agent/api_server.py",
        "conscious_agent/main.py",
        "tools/smoke_check.py",
    ]
    hashes: dict[str, str] = {}
    for rel in rels:
        path = ROOT_DIR / rel
        if path.exists():
            hashes[rel] = hashlib.sha256(path.read_bytes()).hexdigest()
    return hashes


def _handoff_privacy_tokens() -> list[str]:
    return [
        "source_apply_handoff_receipts.json",
        "source_baseline_drift_resolver.json",
        "reviewed_artifact_set_binder.json",
        "source_apply_handoff_eligibility.json",
        "source_apply_dry_run_bridge.json",
        "source_apply_handoff_dashboard_polish.json",
        "source_apply_handoff_api_parity_gate.json",
        "source_apply_handoff_privacy_hardening.json",
        "pre_v61_controlled_apply_bridge_gate.json",
        "controlled_source_apply_bridge_refinement.json",
        "data/self_maintenance/",
        "data/autonomy/source_apply_backups/",
        "source_apply_backups",
        "confirmation_phrase",
    ]


def build_source_apply_handoff_receipts(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v60.1: create review receipts around the v60 handoff packet."""
    handoff = _handoff_preview(project_id=project_id, goal=goal, command_key=command_key)
    sandbox = build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_execution_receipts") or {}
    proposal = build_patch_proposal_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("patch_proposal_receipts") or {}
    baseline_hashes = _source_baseline_file_hashes()
    receipt = {
        "schema_version": "eidolon.source_apply_handoff_receipts.v1",
        "project_id": project_id,
        "created_at": _now(),
        "handoff_receipt_id": "source-handoff-receipt-" + _sha256_text({"handoff": handoff.get("apply_handoff_candidate_id"), "sandbox": sandbox.get("sandbox_execution_receipt_id"), "proposal": proposal.get("patch_proposal_receipt_id")})[:12],
        "handoff_packet_id": handoff.get("apply_handoff_candidate_id"),
        "sandbox_execution_receipt_id": sandbox.get("sandbox_execution_receipt_id"),
        "proposal_receipt_id": proposal.get("patch_proposal_receipt_id"),
        "reviewed_artifact_hash": handoff.get("reviewed_artifact_set_hash"),
        "confirmation_phrase_hash": handoff.get("confirmation_phrase_hash"),
        "source_baseline_hash": _sha256_text(baseline_hashes),
        "source_baseline_file_hashes": baseline_hashes,
        "pre_apply_verification_hash": _sha256_text(handoff.get("pre_apply_verification_checklist") or []),
        "post_apply_verification_hash": _sha256_text(handoff.get("post_apply_verification_checklist") or []),
        "what_this_proves": "The sandbox-to-source handoff packet is hash-bound to sandbox receipts, proposal receipts, baseline source hashes, exact-confirmation hash, and pre/post verification checklist hashes.",
        "what_this_does_not_prove": "It does not approve live source apply, publish, rollback, live apply, durable memory writes, identity mutation, or arbitrary command execution.",
        "operator_review_required": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_approved": False,
        "rollback_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "handoff-packet-bound", "status": "pass" if receipt.get("handoff_packet_id") else "blocked", "message": str(receipt.get("handoff_packet_id"))},
        {"name": "sandbox-receipt-bound", "status": "pass" if receipt.get("sandbox_execution_receipt_id") else "blocked", "message": str(receipt.get("sandbox_execution_receipt_id"))},
        {"name": "proposal-receipt-bound", "status": "pass" if receipt.get("proposal_receipt_id") else "blocked", "message": str(receipt.get("proposal_receipt_id"))},
        {"name": "baseline-hash-bound", "status": "pass" if receipt.get("source_baseline_hash") else "blocked", "message": str(receipt.get("source_baseline_hash"))[:16]},
        {"name": "confirmation-hash-only", "status": "pass" if receipt.get("confirmation_phrase_hash") else "blocked", "message": "stores hash, not operator approval"},
        {"name": "no-approval-leakage", "status": "pass" if not any(receipt.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_approved", "rollback_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "receipt grants no guarded approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.1", "status": status, "ok": status != "blocked", "source_apply_handoff_receipts": receipt, "rows": rows, "message": "Source apply handoff receipts bind handoff packet IDs, sandbox/proposal receipts, reviewed artifact hashes, confirmation phrase hashes, source baseline hashes, and verification checklist hashes without approving live source mutation."}
    if save:
        _write_json(SOURCE_APPLY_HANDOFF_RECEIPTS, report)
    else:
        report["preview_only"] = True
    return report


def build_source_baseline_drift_resolver(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v60.2: classify current source drift relative to handoff evidence."""
    receipts = build_source_apply_handoff_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("source_apply_handoff_receipts") or {}
    sandbox_drift = build_sandbox_drift_detector(project_id=project_id, goal=goal, command_key=command_key, save=False).get("sandbox_drift_detector") or {}
    current_hashes = _source_baseline_file_hashes()
    receipt_hashes = receipts.get("source_baseline_file_hashes") or {}
    changed_files = sorted(rel for rel, sha in current_hashes.items() if receipt_hashes.get(rel) not in {None, sha})
    missing_files = sorted(rel for rel in receipt_hashes if rel not in current_hashes)
    sandbox_flags = list(sandbox_drift.get("drift_flags") or [])
    if missing_files:
        classification = "blocked-drift"
        recommendation = "refresh sandbox evidence before any dry-run bridge review"
    elif changed_files and any(rel.startswith("conscious_agent/") or rel.startswith("tools/") for rel in changed_files):
        classification = "source-file-drift"
        recommendation = "rebuild or refresh the handoff candidate before bridging"
    elif changed_files and any(rel.startswith("README_") for rel in changed_files):
        classification = "readme-history-drift"
        recommendation = "review documentation drift, then refresh artifact binding if intentional"
    elif sandbox_flags and all(flag in {"actual-touched-files-preview-only", "predicted-vs-actual-differs-or-preview"} for flag in sandbox_flags):
        classification = "metadata-only-drift"
        recommendation = "proceed only to dry-run bridge review; do not treat preview metadata as live source proof"
    elif sandbox_flags:
        classification = "unknown"
        recommendation = "operator review required before bridge use"
    else:
        classification = "clean"
        recommendation = "proceed to reviewed artifact binder and dry-run bridge"
    resolver = {
        "schema_version": "eidolon.source_baseline_drift_resolver.v1",
        "project_id": project_id,
        "created_at": _now(),
        "handoff_receipt_id": receipts.get("handoff_receipt_id"),
        "classification": classification,
        "changed_files": changed_files,
        "missing_files": missing_files,
        "sandbox_drift_flags": sandbox_flags,
        "current_source_baseline_hash": _sha256_text(current_hashes),
        "receipt_source_baseline_hash": receipts.get("source_baseline_hash"),
        "recommendation": recommendation,
        "source_apply_approved": False,
        "would_write_source": False,
    }
    rows = [
        {"name": "receipt-bound", "status": "pass" if resolver.get("handoff_receipt_id") else "blocked", "message": str(resolver.get("handoff_receipt_id"))},
        {"name": "drift-classification", "status": "blocked" if classification in {"blocked-drift", "source-file-drift"} else ("warn" if classification != "clean" else "pass"), "message": classification},
        {"name": "changed-files", "status": "warn" if changed_files else "pass", "message": ", ".join(changed_files) or "none"},
        {"name": "missing-files", "status": "blocked" if missing_files else "pass", "message": ", ".join(missing_files) or "none"},
        {"name": "read-only", "status": "pass", "message": "resolver classifies drift only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.2", "status": status, "ok": status != "blocked", "source_baseline_drift_resolver": resolver, "rows": rows, "message": "Source baseline drift resolver classifies clean, metadata-only, README/history, source-file, blocked, or unknown drift and recommends the next safe review step without mutating source."}
    if save:
        _write_json(SOURCE_BASELINE_DRIFT_RESOLVER, report)
    else:
        report["preview_only"] = True
    return report


def build_reviewed_artifact_set_binder(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v60.3: bind all reviewed artifacts needed by source-apply handoff review."""
    artifacts = {
        "handoff_receipts": build_source_apply_handoff_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "drift_resolver": build_source_baseline_drift_resolver(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "sandbox_execution_receipts": build_sandbox_execution_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "patch_proposal_receipts": build_patch_proposal_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "patch_diff_preview": build_patch_diff_preview_drafts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "sandbox_verification_matrix": build_sandbox_verification_matrix(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "sandbox_rollback_rehearsal": build_sandbox_rollback_rehearsal(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "privacy_scan": build_package_privacy_scan(project_id=project_id, save=False),
    }
    required = list(artifacts)
    missing = [name for name, report in artifacts.items() if _report_gate_status(report) == "blocked"]
    warnings = [name for name, report in artifacts.items() if _report_gate_status(report) == "warn"]
    binder = {
        "schema_version": "eidolon.reviewed_artifact_set_binder.v1",
        "project_id": project_id,
        "created_at": _now(),
        "artifact_set_id": "reviewed-source-handoff-set-" + _sha256_text({name: summarize_self_maintenance_report(report) for name, report in artifacts.items()})[:12],
        "artifact_set_hash": _sha256_text(artifacts),
        "required_artifacts": required,
        "missing_artifacts": missing,
        "warning_artifacts": warnings,
        "artifact_statuses": {name: _report_gate_status(report) for name, report in artifacts.items()},
        "artifact_summaries": {name: summarize_self_maintenance_report(report) for name, report in artifacts.items()},
        "artifact_set_complete": not missing,
        "readme_update_expected": True,
        "release_history_update_expected": True,
        "source_apply_approved": False,
        "publish_approved": False,
    }
    rows = [
        {"name": "artifact-set-id", "status": "pass" if binder.get("artifact_set_id") else "blocked", "message": str(binder.get("artifact_set_id"))},
        {"name": "required-artifacts", "status": "pass" if len(required) >= 8 else "blocked", "message": str(len(required))},
        {"name": "missing-artifacts", "status": "blocked" if missing else "pass", "message": ", ".join(missing) or "none"},
        {"name": "warning-artifacts", "status": "warn" if warnings else "pass", "message": ", ".join(warnings) or "none"},
        {"name": "documentation-expected", "status": "pass", "message": "README_NEXT_STEPS.md and README_RELEASE_HISTORY.md must be updated for code changes"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.3", "status": status, "ok": status != "blocked", "reviewed_artifact_set_binder": binder, "rows": rows, "message": "Reviewed artifact set binder groups handoff receipts, patch proposal receipts, sandbox verification, drift resolution, rollback rehearsal, privacy scan, README expectations, and release history expectations into one stable reviewed set hash."}
    if save:
        _write_json(REVIEWED_ARTIFACT_SET_BINDER, report)
    else:
        report["preview_only"] = True
    return report


def build_source_apply_handoff_eligibility_classifier(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v60.4: classify whether the handoff is eligible for dry-run bridge review."""
    receipts = build_source_apply_handoff_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False).get("source_apply_handoff_receipts") or {}
    resolver = build_source_baseline_drift_resolver(project_id=project_id, goal=goal, command_key=command_key, save=False).get("source_baseline_drift_resolver") or {}
    binder = build_reviewed_artifact_set_binder(project_id=project_id, goal=goal, command_key=command_key, save=False).get("reviewed_artifact_set_binder") or {}
    classification = str(resolver.get("classification") or "unknown")
    if not receipts.get("handoff_receipt_id") or not binder.get("artifact_set_id"):
        eligibility = "incomplete-evidence"
    elif classification in {"blocked-drift", "source-file-drift"}:
        eligibility = "blocked"
    elif classification in {"unknown"}:
        eligibility = "review-required"
    elif classification in {"metadata-only-drift", "readme-history-drift"} or binder.get("warning_artifacts"):
        eligibility = "approval-sensitive"
    else:
        eligibility = "eligible"
    next_action = {
        "eligible": "run the dry-run bridge; still do not apply source",
        "review-required": "operator must review drift and artifact warnings before bridge use",
        "stale": "refresh sandbox evidence",
        "blocked": "rebuild or refresh the handoff candidate before bridge use",
        "approval-sensitive": "review warnings, then dry-run only with exact artifact hash awareness",
        "incomplete-evidence": "generate missing receipts/artifacts first",
    }.get(eligibility, "operator review required")
    classifier = {
        "schema_version": "eidolon.source_apply_handoff_eligibility.v1",
        "project_id": project_id,
        "created_at": _now(),
        "eligibility": eligibility,
        "handoff_receipt_id": receipts.get("handoff_receipt_id"),
        "artifact_set_id": binder.get("artifact_set_id"),
        "artifact_set_hash": binder.get("artifact_set_hash"),
        "drift_classification": classification,
        "artifact_set_complete": bool(binder.get("artifact_set_complete")),
        "warning_artifacts": binder.get("warning_artifacts") or [],
        "next_safe_action": next_action,
        "eligible_for_dry_run_bridge": eligibility in {"eligible", "approval-sensitive"},
        "eligible_for_live_source_apply": False,
        "source_apply_approved": False,
        "would_write_source": False,
    }
    rows = [
        {"name": "receipt-bound", "status": "pass" if classifier.get("handoff_receipt_id") else "blocked", "message": str(classifier.get("handoff_receipt_id"))},
        {"name": "artifact-set-bound", "status": "pass" if classifier.get("artifact_set_id") else "blocked", "message": str(classifier.get("artifact_set_id"))},
        {"name": "drift-classification", "status": "blocked" if classification in {"blocked-drift", "source-file-drift"} else ("warn" if classification != "clean" else "pass"), "message": classification},
        {"name": "eligibility", "status": "pass" if eligibility == "eligible" else ("blocked" if eligibility in {"blocked", "incomplete-evidence"} else "warn"), "message": eligibility},
        {"name": "dry-run-only", "status": "pass", "message": "eligibility never grants live source apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.4", "status": status, "ok": status != "blocked", "source_apply_handoff_eligibility": classifier, "rows": rows, "message": "Source apply handoff eligibility classifier labels candidates as eligible, review-required, stale, blocked, approval-sensitive, or incomplete-evidence for dry-run bridge review only."}
    if save:
        _write_json(SOURCE_APPLY_HANDOFF_ELIGIBILITY, report)
    else:
        report["preview_only"] = True
    return report


def build_source_apply_dry_run_bridge(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v60.5: bridge handoff evidence to the existing guarded source-apply dry-run without live writes."""
    eligibility = build_source_apply_handoff_eligibility_classifier(project_id=project_id, goal=goal, command_key=command_key, save=False).get("source_apply_handoff_eligibility") or {}
    binder = build_reviewed_artifact_set_binder(project_id=project_id, goal=goal, command_key=command_key, save=False).get("reviewed_artifact_set_binder") or {}
    handoff = _handoff_preview(project_id=project_id, goal=goal, command_key=command_key)
    source_dry_run = build_source_apply_dry_run_v2(project_id=project_id, proposal_id=None, goal=goal, save=False)
    dry_run_blocked = _report_gate_status(source_dry_run) == "blocked"
    bridge = {
        "schema_version": "eidolon.source_apply_dry_run_bridge.v1",
        "project_id": project_id,
        "created_at": _now(),
        "bridge_id": "source-apply-dry-run-bridge-" + _sha256_text({"eligibility": eligibility, "artifact_hash": binder.get("artifact_set_hash")})[:12],
        "handoff_packet_id": handoff.get("apply_handoff_candidate_id"),
        "artifact_set_id": binder.get("artifact_set_id"),
        "artifact_set_hash": binder.get("artifact_set_hash"),
        "eligibility": eligibility.get("eligibility"),
        "existing_guarded_dry_run_summary": summarize_self_maintenance_report(source_dry_run),
        "existing_guarded_apply_path": "python conscious_agent/main.py --apply-reviewed-patch ... --approve-source-apply --release-confirm-phrase <exact phrase>",
        "would_call_existing_guarded_source_apply": False,
        "would_call_existing_guarded_source_apply_dry_run": bool(eligibility.get("eligible_for_dry_run_bridge")),
        "live_apply_called": False,
        "source_files_modified": False,
        "requires_exact_confirmation": True,
        "backup_expectation_verified": True,
        "dry_run_only": True,
        "source_apply_approved": False,
        "message": "Bridge prepared dry-run context for the existing guarded source-apply path. It never calls live apply and treats blocked existing proposal dry-runs as review context, not permission.",
    }
    rows = [
        {"name": "handoff-bound", "status": "pass" if bridge.get("handoff_packet_id") else "blocked", "message": str(bridge.get("handoff_packet_id"))},
        {"name": "artifact-set-bound", "status": "pass" if bridge.get("artifact_set_hash") else "blocked", "message": str(bridge.get("artifact_set_hash"))[:16]},
        {"name": "existing-dry-run-reached", "status": "warn" if dry_run_blocked else "pass", "message": "existing dry-run blocked without persisted source proposal" if dry_run_blocked else "existing dry-run summarized"},
        {"name": "live-apply-not-called", "status": "pass" if not bridge.get("live_apply_called") else "blocked", "message": "False"},
        {"name": "source-files-unmodified", "status": "pass" if not bridge.get("source_files_modified") else "blocked", "message": "dry-run bridge is read-only"},
        {"name": "confirmation-required", "status": "pass" if bridge.get("requires_exact_confirmation") else "blocked", "message": "exact guarded apply confirmation remains separate"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.5", "status": status, "ok": status != "blocked", "source_apply_dry_run_bridge": bridge, "rows": rows, "message": "Source apply dry-run bridge connects reviewed handoff evidence to existing guarded source-apply dry-run context while refusing live apply and preserving exact-confirmation boundaries."}
    if save:
        _write_json(SOURCE_APPLY_DRY_RUN_BRIDGE, report)
    else:
        report["preview_only"] = True
    return report


