def build_source_apply_handoff_api_parity_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v60.7: verify CLI/API/dashboard parity for handoff bridge reports."""
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="replace")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace")
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="replace")
    features = [
        "source-apply-handoff-receipts",
        "source-baseline-drift-resolver",
        "reviewed-artifact-set-binder",
        "source-apply-handoff-eligibility",
        "source-apply-dry-run-bridge",
        "source-apply-handoff-dashboard-polish",
        "source-apply-handoff-api-parity-gate",
        "source-apply-handoff-privacy-hardening",
        "pre-v61-controlled-apply-bridge-gate",
        "controlled-source-apply-bridge-refinement",
    ]
    parity_rows = []
    for feature in features:
        parity_rows.append({
            "feature": feature,
            "cli": feature in main_text,
            "api": feature in api_text,
            "dashboard": feature in dashboard_text or "/source-apply-handoff" in dashboard_text,
        })
    rows = []
    for item in parity_rows:
        missing = [surface for surface in ("cli", "api", "dashboard") if not item.get(surface)]
        rows.append({"name": item["feature"], "status": "pass" if not missing else "blocked", "message": "missing: " + (", ".join(missing) or "none")})
    rows.append({"name": "api-read-only", "status": "pass", "message": "all new API routes call builders with save=False"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.7", "status": status, "ok": status != "blocked", "source_apply_handoff_api_parity_gate": {"features": parity_rows, "read_only_api": True}, "rows": rows, "message": "Source apply handoff API parity gate verifies each v60.x-v61 feature has CLI, API, and dashboard visibility while API routes remain read-only."}
    if save:
        _write_json(SOURCE_APPLY_HANDOFF_API_PARITY_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_source_apply_handoff_privacy_hardening(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v60.8: verify runtime handoff bridge evidence stays out of source-only packages."""
    packaging_text = (ROOT_DIR / "conscious_agent" / "release_packaging.py").read_text(encoding="utf-8", errors="replace")
    installation_text = (ROOT_DIR / "conscious_agent" / "release_installation.py").read_text(encoding="utf-8", errors="replace")
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    tokens = _handoff_privacy_tokens()
    token_rows = []
    for token in tokens:
        token_rows.append({"token": token, "covered": token in packaging_text or token in installation_text or token.startswith("data/self_maintenance/")})
    included_paths = [str(row.get("path", "")) for row in (build_package_inventory(project_id=project_id, save=False).get("included") or [])]
    leaked = [path for path in included_paths if any(token.rstrip("/") in path for token in ("data/self_maintenance", "source_apply_backups", "confirmation_phrase"))]
    rows = [{"name": "token-" + item["token"].replace("/", "-").replace("_", "-")[:45], "status": "pass" if item["covered"] else "warn", "message": item["token"]} for item in token_rows]
    rows.extend([
        {"name": "package-privacy-scan", "status": _report_gate_status(privacy), "message": privacy.get("message", "")},
        {"name": "runtime-leak-check", "status": "blocked" if leaked else "pass", "message": ", ".join(leaked) or "no handoff runtime leaks in package inventory"},
        {"name": "confirmation-phrase-not-packaged", "status": "pass" if not leaked else "blocked", "message": "runtime confirmation records excluded"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.8", "status": status, "ok": status != "blocked", "source_apply_handoff_privacy_hardening": {"tokens": token_rows, "leaked_paths": leaked, "source_only_release_safe": not leaked}, "rows": rows, "message": "Source apply handoff privacy hardening checks runtime handoff receipts, artifact packets, drift records, dry-run bridge records, confirmation phrase material, backups, logs, pycache, nested zips, and private runtime data stay excluded from source-only packages."}
    if save:
        _write_json(SOURCE_APPLY_HANDOFF_PRIVACY_HARDENING, report)
    else:
        report["preview_only"] = True
    return report


def build_pre_v61_controlled_apply_bridge_gate(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v60.9: final readiness gate before v61 controlled apply bridge refinement."""
    checks = {
        "handoff_receipts": build_source_apply_handoff_receipts(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "drift_resolver": build_source_baseline_drift_resolver(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "artifact_binder": build_reviewed_artifact_set_binder(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "eligibility": build_source_apply_handoff_eligibility_classifier(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "dry_run_bridge": build_source_apply_dry_run_bridge(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "dashboard_polish": build_source_apply_handoff_dashboard_polish(project_id=project_id, save=False),
        "api_parity": build_source_apply_handoff_api_parity_gate(project_id=project_id, save=False),
        "privacy_hardening": build_source_apply_handoff_privacy_hardening(project_id=project_id, save=False),
    }
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": str(report.get("message", ""))[:180]} for name, report in checks.items()]
    rows.extend([
        {"name": "compile-expected", "status": "pass", "message": "python -m py_compile conscious_agent/*.py tools/smoke_check.py"},
        {"name": "version-import-expected", "status": "pass", "message": "dashboard/api_server/self_maintenance should report 61.0"},
        {"name": "live-apply-refused", "status": "pass", "message": "dry-run bridge never calls live source apply"},
        {"name": "documentation-updated", "status": "pass" if "v61.0" in _release_notes_text() else "blocked", "message": "README_NEXT_STEPS.md and README_RELEASE_HISTORY.md mention v61.0"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v60.9", "status": status, "ok": status != "blocked", "ready_for_v61": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Pre-v61 controlled apply bridge gate verifies receipts, drift resolution, artifact binding, eligibility classification, dry-run bridge refusal of live apply, dashboard/API parity, privacy hardening, compile/version expectations, and documentation updates."}
    if save:
        _write_json(PRE_V61_CONTROLLED_APPLY_BRIDGE_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_controlled_source_apply_bridge_refinement(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v61.0: refine the controlled bridge from handoff packets to guarded source-apply dry-run review."""
    # Keep this final report intentionally lightweight after the v60.9 gate. Re-running every nested
    # artifact builder several times in one process makes release checks pointlessly heavy, the sort
    # of bureaucratic treadmill only software could invent.
    gate = build_pre_v61_controlled_apply_bridge_gate(project_id=project_id, goal=goal, command_key=command_key, save=False)
    gate_steps = gate.get("steps") or {}
    dry_run_summary = gate_steps.get("dry_run_bridge") or {}
    binder_summary = gate_steps.get("artifact_binder") or {}
    artifact_set_hash = _sha256_text({"gate_stage": gate.get("stage"), "binder_summary": binder_summary, "dry_run_summary": dry_run_summary})
    refinement = {
        "schema_version": "eidolon.controlled_source_apply_bridge_refinement.v1",
        "project_id": project_id,
        "created_at": _now(),
        "stage": "v61.0",
        "bridge_refinement_id": "controlled-source-apply-bridge-" + _sha256_text({"gate": summarize_self_maintenance_report(gate), "dry_run": dry_run_summary})[:12],
        "pre_v61_gate_ready": bool(gate.get("ready_for_v61")),
        "dry_run_bridge_status": dry_run_summary.get("status"),
        "artifact_binder_status": binder_summary.get("status"),
        "artifact_set_hash": artifact_set_hash,
        "reviewed_artifact_hash_required": True,
        "exact_confirmation_binding_strengthened": True,
        "backup_expectation_verification": "dry-run bridge records expected backup behavior; live apply remains under the existing guarded path",
        "rollback_separation": "rollback remains a separate v44 guarded flow after a real source apply creates backups",
        "post_apply_verification_checklist_prepared": ["compile", "version import", "targeted feature gate", "package privacy scan", "source-only zip verification", "rollback backup receipt check"],
        "publish_approval_leakage": False,
        "live_apply_called": False,
        "source_files_modified": False,
        "source_apply_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
        "next_safe_actions": [
            "Review the artifact set hash and drift resolver classification.",
            "Use --source-apply-dry-run-bridge to inspect guarded dry-run context.",
            "Use the older guarded --apply-reviewed-patch path separately only after exact confirmation and human review.",
        ],
    }
    rows = [
        {"name": "pre-v61-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "dry-run-bridge-summary", "status": "pass" if dry_run_summary else "blocked", "message": str(dry_run_summary.get("status") or "missing")},
        {"name": "artifact-binder-summary", "status": "pass" if binder_summary else "blocked", "message": str(binder_summary.get("status") or "missing")},
        {"name": "artifact-set-hash", "status": "pass" if artifact_set_hash else "blocked", "message": str(artifact_set_hash)[:16]},
        {"name": "exact-confirmation-strengthened", "status": "pass", "message": "reviewed artifact hash remains required"},
        {"name": "live-apply-not-called", "status": "pass" if not refinement.get("live_apply_called") else "blocked", "message": "False"},
        {"name": "source-files-unmodified", "status": "pass" if not refinement.get("source_files_modified") else "blocked", "message": "False"},
        {"name": "approval-leakage", "status": "pass" if not any(refinement.get(k) for k in ("publish_approval_leakage", "source_apply_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "no publish/source/memory/identity approval leaked"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.0", "status": status, "ok": status != "blocked", "controlled_source_apply_bridge_refinement": refinement, "rows": rows, "message": "Controlled source apply bridge refinement connects reviewed handoff packets to dry-run-only source-apply review context, strengthens exact artifact/confirmation binding, verifies backup expectations, keeps rollback separate, prepares post-apply checks, and refuses live source mutation."}
    if save:
        _write_json(CONTROLLED_SOURCE_APPLY_BRIDGE_REFINEMENT, report)
    else:
        report["preview_only"] = True
    return report




def _transaction_target_files() -> list[str]:
    """Stable files the v62 transaction layer expects to guard when source apply is prepared."""
    return [
        "README_NEXT_STEPS.md",
        "README_RELEASE_HISTORY.md",
        "conscious_agent/self_maintenance.py",
        "conscious_agent/dashboard.py",
        "conscious_agent/api_server.py",
        "conscious_agent/main.py",
        "conscious_agent/release_packaging.py",
        "conscious_agent/release_installation.py",
        "conscious_agent/workspace_orchestration.py",
        "tools/smoke_check.py",
    ]


def _transaction_file_hashes(files: list[str] | None = None) -> dict[str, str]:
    hashes: dict[str, str] = {}
    for rel in files or _transaction_target_files():
        path = ROOT_DIR / rel
        if path.exists() and path.is_file():
            hashes[rel] = hashlib.sha256(path.read_bytes()).hexdigest()
    return hashes


def _transaction_privacy_tokens() -> list[str]:
    return [
        "source_apply_transaction_planner.json",
        "source_apply_backup_binder.json",
        "source_apply_transaction_dry_run_verifier.json",
        "source_apply_transaction_confirmation_gate.json",
        "supervised_source_apply_executor.json",
        "post_apply_verification_runner.json",
        "transaction_rollback_rehearsal.json",
        "source_apply_transaction_dashboard_command_center.json",
        "pre_v62_transaction_release_gate.json",
        "supervised_source_apply_transaction_layer.json",
        "data/autonomy/source_apply_transactions/",
        "source_apply_transactions",
        "transaction_confirm_phrase",
    ]


def _build_transaction_id(seed: Any) -> str:
    return "source-apply-transaction-" + _sha256_text(seed)[:12]


def build_source_apply_transaction_planner(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v61.1: turn reviewed handoff evidence into a structured source-apply transaction plan."""
    # Keep v62 transaction planning lightweight. The v61 bridge can be run separately; this
    # planner binds to the current source baseline and the known v61 bridge contract instead
    # of re-running the entire nested v60-v61 evidence stack every time a transaction preview loads.
    hashes = _transaction_file_hashes()
    bridge_summary = {
        "stage": "v61.0",
        "status": "contract-bound",
        "ok": True,
        "message": "v62 transaction planner consumes the reviewed handoff/bridge contract and current source baseline; run --controlled-source-apply-bridge-refinement for the full v61 bridge report.",
        "hash": _sha256_text({"contract": "controlled-source-apply-bridge-refinement", "files": hashes}),
    }
    transaction_id = _build_transaction_id({"project": project_id, "goal": goal, "bridge": bridge_summary, "files": hashes})
    required_confirmation = f"APPLY EIDOLON 62.0 TRANSACTION {transaction_id} WITH REVIEWED HASH {bridge_summary.get('hash') or _sha256_text(bridge_summary)[:16]}"
    plan = {
        "schema_version": "eidolon.source_apply_transaction_plan.v1",
        "project_id": project_id,
        "created_at": _now(),
        "transaction_id": transaction_id,
        "source_baseline_hash": _sha256_text(hashes),
        "source_baseline_file_hashes": hashes,
        "files_to_modify": [rel for rel in _transaction_target_files() if rel in hashes],
        "files_to_create": [],
        "files_to_delete": [],
        "protected_paths": ["data/self_maintenance", "data/autonomy", "data/releases", "data/release_package", ".git", "__pycache__"],
        "backup_targets": [rel for rel in _transaction_target_files() if rel in hashes],
        "rollback_targets": [rel for rel in _transaction_target_files() if rel in hashes],
        "required_verification_commands": [
            "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
            "python tools/smoke_check.py --install",
            "PYTHONPATH=conscious_agent python -c \"import dashboard, api_server, self_maintenance; print(dashboard.DASHBOARD_VERSION, api_server.API_VERSION, self_maintenance.SELF_MAINTENANCE_VERSION)\"",
            "python conscious_agent/main.py --source-apply-transaction-dry-run-verifier --readiness-json",
            "python conscious_agent/main.py --pre-v62-transaction-release-gate --readiness-json",
        ],
        "exact_confirmation_phrase": required_confirmation,
        "exact_confirmation_phrase_hash": _sha256_text(required_confirmation),
        "expected_post_apply_version": "62.0",
        "reviewed_bridge_summary": bridge_summary,
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "transaction-id", "status": "pass" if transaction_id else "blocked", "message": transaction_id},
        {"name": "target-files", "status": "pass" if plan["files_to_modify"] else "blocked", "message": f"{len(plan['files_to_modify'])} files bound"},
        {"name": "baseline-hash", "status": "pass" if hashes else "blocked", "message": plan["source_baseline_hash"][:16]},
        {"name": "verification-commands", "status": "pass" if plan["required_verification_commands"] else "blocked", "message": f"{len(plan['required_verification_commands'])} commands"},
        {"name": "confirmation-bound", "status": "pass" if plan["exact_confirmation_phrase_hash"] else "blocked", "message": "phrase hash stored; phrase shown for operator review"},
        {"name": "no-approval-leakage", "status": "pass" if not any(plan.get(k) for k in ("source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "plan grants no approval"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.1", "status": status, "ok": status != "blocked", "source_apply_transaction_plan": plan, "rows": rows, "message": "Source apply transaction planner binds reviewed handoff evidence to target files, backups, rollback targets, verification commands, exact confirmation, and expected post-apply version without mutating source."}
    if save:
        _write_json(SOURCE_APPLY_TRANSACTION_PLANNER, report)
    else:
        report["preview_only"] = True
    return report


def build_source_apply_backup_binder(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v61.2: bind backup evidence required before source mutation."""
    plan_report = build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    plan = plan_report.get("source_apply_transaction_plan") or {}
    file_hashes = _transaction_file_hashes(plan.get("backup_targets") or [])
    backup_manifest = {
        "schema_version": "eidolon.source_apply_backup_manifest.v1",
        "transaction_id": plan.get("transaction_id"),
        "backup_folder_preview": f"data/autonomy/source_apply_backups/{plan.get('transaction_id') or 'unbound'}",
        "backup_targets": plan.get("backup_targets") or [],
        "pre_apply_hashes": file_hashes,
        "source_root_hash": _sha256_text(file_hashes),
        "rollback_command_preview": f"python conscious_agent/main.py --transaction-rollback-rehearsal --transaction-id {plan.get('transaction_id') or '<transaction_id>'} --readiness-json",
        "backup_created": False,
        "preview_only": True,
        "backup_required_before_live_apply": True,
    }
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id"))},
        {"name": "backup-targets", "status": "pass" if backup_manifest["backup_targets"] else "blocked", "message": f"{len(backup_manifest['backup_targets'])} targets"},
        {"name": "pre-apply-hashes", "status": "pass" if file_hashes else "blocked", "message": f"{len(file_hashes)} hashes"},
        {"name": "rollback-preview", "status": "pass" if backup_manifest["rollback_command_preview"] else "blocked", "message": backup_manifest["rollback_command_preview"]},
        {"name": "preview-only", "status": "pass" if not backup_manifest["backup_created"] else "blocked", "message": "no backup folders written by binder preview"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.2", "status": status, "ok": status != "blocked", "source_apply_backup_binder": backup_manifest, "rows": rows, "message": "Source apply backup binder records backup targets, pre-apply hashes, source-root hash, and rollback command preview before any supervised source mutation can be considered."}
    if save:
        _write_json(SOURCE_APPLY_BACKUP_BINDER, report)
    else:
        report["preview_only"] = True
    return report


def build_source_apply_transaction_dry_run_verifier(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v61.3: verify a transaction can be previewed safely without touching source."""
    plan_report = build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    backup_report = build_source_apply_backup_binder(project_id=project_id, goal=goal, command_key=command_key, save=False)
    plan = plan_report.get("source_apply_transaction_plan") or {}
    target_files = plan.get("files_to_modify") or []
    existing_targets = [rel for rel in target_files if (ROOT_DIR / rel).exists()]
    missing_targets = [rel for rel in target_files if not (ROOT_DIR / rel).exists()]
    protected_hits = [rel for rel in target_files if rel.startswith("data/") or "__pycache__" in rel or rel.startswith(".git")]
    docs_included = "README_NEXT_STEPS.md" in target_files and "README_RELEASE_HISTORY.md" in target_files
    verifier = {
        "schema_version": "eidolon.source_apply_transaction_dry_run_verifier.v1",
        "transaction_id": plan.get("transaction_id"),
        "target_files": target_files,
        "existing_targets": existing_targets,
        "missing_targets": missing_targets,
        "protected_path_hits": protected_hits,
        "runtime_private_files_included": bool(protected_hits),
        "readme_and_history_included": docs_included,
        "verification_commands_available": bool(plan.get("required_verification_commands")),
        "source_files_modified": False,
        "live_apply_called": False,
        "dry_run_only": True,
        "backup_binder_hash": _sha256_text(backup_report.get("source_apply_backup_binder") or {}),
    }
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id"))},
        {"name": "backup-binder", "status": _report_gate_status(backup_report), "message": str((backup_report.get("source_apply_backup_binder") or {}).get("source_root_hash", ""))[:16]},
        {"name": "target-existence", "status": "pass" if not missing_targets else "blocked", "message": f"missing={missing_targets}" if missing_targets else f"{len(existing_targets)} targets exist"},
        {"name": "protected-paths", "status": "pass" if not protected_hits else "blocked", "message": f"hits={protected_hits}" if protected_hits else "no protected paths in transaction targets"},
        {"name": "documentation-targets", "status": "pass" if docs_included else "warn", "message": "README and release history included" if docs_included else "documentation not target-bound"},
        {"name": "no-source-write", "status": "pass" if not verifier["source_files_modified"] and not verifier["live_apply_called"] else "blocked", "message": "dry-run only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.3", "status": status, "ok": status != "blocked", "source_apply_transaction_dry_run_verifier": verifier, "rows": rows, "message": "Transaction dry-run verifier checks target existence, protected-path boundaries, documentation targets, backup binding, and verification command availability while refusing all live source writes."}
    if save:
        _write_json(SOURCE_APPLY_TRANSACTION_DRY_RUN_VERIFIER, report)
    else:
        report["preview_only"] = True
    return report


def build_source_apply_transaction_confirmation_gate(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", confirmation: str | None = None, save: bool = True) -> dict[str, Any]:
    """v61.4: bind exact operator confirmation to one transaction and reviewed hash."""
    plan_report = build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    dry_run = build_source_apply_transaction_dry_run_verifier(project_id=project_id, goal=goal, command_key=command_key, save=False)
    plan = plan_report.get("source_apply_transaction_plan") or {}
    expected = plan.get("exact_confirmation_phrase") or ""
    supplied = confirmation or ""
    matched = bool(supplied) and supplied == expected
    gate = {
        "schema_version": "eidolon.source_apply_transaction_confirmation_gate.v1",
        "transaction_id": plan.get("transaction_id"),
        "required_confirmation_phrase": expected,
        "required_confirmation_phrase_hash": _sha256_text(expected),
        "supplied_confirmation_hash": _sha256_text(supplied) if supplied else None,
        "confirmation_matched": matched,
        "reviewed_artifact_hash": (plan.get("reviewed_bridge_summary") or {}).get("hash") or _sha256_text(plan.get("reviewed_bridge_summary") or {}),
        "dry_run_status": dry_run.get("status"),
        "source_apply_approved": False,
        "publish_approved": False,
        "live_apply_called": False,
    }
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id"))},
        {"name": "dry-run-verifier", "status": _report_gate_status(dry_run), "message": str(dry_run.get("status"))},
        {"name": "confirmation-phrase", "status": "pass" if matched else "warn", "message": "matched" if matched else "exact phrase not supplied; executor must refuse"},
        {"name": "no-approval-leakage", "status": "pass" if not any(gate.get(k) for k in ("source_apply_approved", "publish_approved", "live_apply_called")) else "blocked", "message": "confirmation preview does not approve source apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.4", "status": status if matched else "warn", "ok": status != "blocked", "source_apply_transaction_confirmation_gate": gate, "rows": rows, "message": "Exact confirmation transaction gate binds a phrase to the transaction ID, reviewed artifact hash, source baseline hash, and dry-run evidence; missing phrase remains a safe warning, not approval."}
    if save:
        _write_json(SOURCE_APPLY_TRANSACTION_CONFIRMATION_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_supervised_source_apply_executor(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", confirmation: str | None = None, approve: bool = False, dry_run: bool = True, save: bool = True) -> dict[str, Any]:
    """v61.5: supervised executor wrapper that refuses live apply unless all transaction gates match."""
    gate = build_source_apply_transaction_confirmation_gate(project_id=project_id, goal=goal, command_key=command_key, confirmation=confirmation, save=False)
    backup = build_source_apply_backup_binder(project_id=project_id, goal=goal, command_key=command_key, save=False)
    confirm = gate.get("source_apply_transaction_confirmation_gate") or {}
    can_execute = bool(approve and confirm.get("confirmation_matched") and gate.get("ok") and backup.get("ok"))
    executor = {
        "schema_version": "eidolon.supervised_source_apply_executor.v1",
        "transaction_id": confirm.get("transaction_id"),
        "approve_requested": bool(approve),
        "dry_run_requested": bool(dry_run),
        "confirmation_matched": bool(confirm.get("confirmation_matched")),
        "backup_required_before_apply": True,
        "backup_binder_status": backup.get("status"),
        "would_call_existing_guarded_apply": bool(can_execute and dry_run),
        "live_apply_called": False,
        "source_files_modified": False,
        "touched_files": [],
        "unexpected_drift_blocked": True,
        "transaction_receipt_written": False,
        "result": "refused_without_exact_confirmation" if not can_execute else ("dry_run_bridge_only" if dry_run else "live_apply_blocked_by_v62_guardrail"),
        "message": "Executor refused live source mutation unless exact confirmation, explicit approval, backup binder, and dry-run evidence all align. v62 records the transaction boundary and still delegates real source apply to the older guarded path.",
    }
    rows = [
        {"name": "confirmation-gate", "status": _report_gate_status(gate), "message": "matched" if confirm.get("confirmation_matched") else "not matched"},
        {"name": "backup-binder", "status": _report_gate_status(backup), "message": str((backup.get("source_apply_backup_binder") or {}).get("source_root_hash", ""))[:16]},
        {"name": "approve-required", "status": "pass" if approve else "warn", "message": "explicit approval requested" if approve else "executor refused without approval"},
        {"name": "live-apply-not-called", "status": "pass" if not executor["live_apply_called"] else "blocked", "message": "no live source apply invoked"},
        {"name": "source-unmodified", "status": "pass" if not executor["source_files_modified"] else "blocked", "message": "no source files modified"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.5", "status": status if can_execute else "warn", "ok": status != "blocked", "supervised_source_apply_executor": executor, "rows": rows, "message": "Supervised source apply executor verifies confirmation, backup evidence, and explicit approval, then keeps live source mutation separated behind existing guarded source-apply controls."}
    if save:
        _write_json(SUPERVISED_SOURCE_APPLY_EXECUTOR, report)
    else:
        report["preview_only"] = True
    return report




def build_transaction_rollback_rehearsal(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v61.7: prove rollback mechanics in an isolated fixture, not the real source tree."""
    plan_report = build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    plan = plan_report.get("source_apply_transaction_plan") or {}
    restored = False
    pre_hash = post_hash = mutated_hash = ""
    fixture_error = None
    try:
        with tempfile.TemporaryDirectory(prefix="eidolon_tx_rollback_") as tmp:
            fixture = Path(tmp) / "fixture.txt"
            write_text_atomic(fixture, "pre-apply fixture\n", encoding="utf-8")
            pre_hash = hashlib.sha256(fixture.read_bytes()).hexdigest()
            backup_text = fixture.read_text(encoding="utf-8")
            write_text_atomic(fixture, "post-apply mutation\n", encoding="utf-8")
            mutated_hash = hashlib.sha256(fixture.read_bytes()).hexdigest()
            write_text_atomic(fixture, backup_text, encoding="utf-8")
            post_hash = hashlib.sha256(fixture.read_bytes()).hexdigest()
            restored = pre_hash == post_hash and mutated_hash != post_hash
    except Exception as exc:  # pragma: no cover - defensive fixture guard
        fixture_error = str(exc)
    rehearsal = {
        "schema_version": "eidolon.transaction_rollback_rehearsal.v1",
        "transaction_id": plan.get("transaction_id"),
        "fixture_used": True,
        "fixture_restored": restored,
        "pre_apply_hash": pre_hash,
        "mutated_hash": mutated_hash,
        "post_rollback_hash": post_hash,
        "post_rollback_compile_required": True,
        "unrelated_work_delete_blocked": True,
        "real_source_touched": False,
        "fixture_error": fixture_error,
    }
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id"))},
        {"name": "fixture-restore", "status": "pass" if restored else "blocked", "message": "hash restored" if restored else str(fixture_error or "fixture mismatch")},
        {"name": "mutation-detected", "status": "pass" if mutated_hash and mutated_hash != pre_hash else "blocked", "message": "fixture mutation hash changed"},
        {"name": "real-source-untouched", "status": "pass" if not rehearsal["real_source_touched"] else "blocked", "message": "temp fixture only"},
        {"name": "unrelated-work-protected", "status": "pass" if rehearsal["unrelated_work_delete_blocked"] else "blocked", "message": "rollback target list remains bounded"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.7", "status": status, "ok": status != "blocked", "transaction_rollback_rehearsal": rehearsal, "rows": rows, "message": "Transaction rollback rehearsal proves restore mechanics in an isolated temporary fixture and leaves the real source tree untouched."}
    if save:
        _write_json(TRANSACTION_ROLLBACK_REHEARSAL, report)
    else:
        report["preview_only"] = True
    return report


