def build_pre_v62_transaction_release_gate(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v61.9: final gate for the supervised transaction layer."""
    checks = {
        "transaction_planner": build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "backup_binder": build_source_apply_backup_binder(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "dry_run_verifier": build_source_apply_transaction_dry_run_verifier(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "confirmation_gate": build_source_apply_transaction_confirmation_gate(project_id=project_id, goal=goal, command_key=command_key, confirmation=None, save=False),
        "executor_refusal": build_supervised_source_apply_executor(project_id=project_id, goal=goal, command_key=command_key, confirmation=None, approve=False, dry_run=True, save=False),
        "post_apply_verification": build_post_apply_verification_runner(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "rollback_rehearsal": build_transaction_rollback_rehearsal(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "dashboard_command_center": build_source_apply_transaction_dashboard_command_center(project_id=project_id, save=False),
    }
    routes = [
        "source-apply-transaction-planner",
        "source-apply-backup-binder",
        "source-apply-transaction-dry-run-verifier",
        "source-apply-transaction-confirmation-gate",
        "supervised-source-apply-executor",
        "post-apply-verification-runner",
        "transaction-rollback-rehearsal",
        "source-apply-transaction-dashboard-command-center",
        "pre-v62-transaction-release-gate",
        "supervised-source-apply-transaction-layer",
    ]
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8") if (ROOT_DIR / "conscious_agent" / "api_server.py").exists() else ""
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8") if (ROOT_DIR / "conscious_agent" / "main.py").exists() else ""
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": str(report.get("message", ""))[:180]} for name, report in checks.items()]
    rows.extend([
        {"name": "executor-refuses-without-phrase", "status": "pass" if (checks["executor_refusal"].get("supervised_source_apply_executor") or {}).get("result") == "refused_without_exact_confirmation" else "blocked", "message": "executor refusal confirmed"},
        {"name": "cli-parity", "status": "pass" if all("--" + route in main_text for route in routes) else "blocked", "message": "all v62 CLI flags present"},
        {"name": "api-parity", "status": "pass" if all(route in api_text for route in routes) else "blocked", "message": "all v62 API routes present"},
        {"name": "compile-expected", "status": "pass", "message": "python -m py_compile conscious_agent/*.py tools/smoke_check.py"},
        {"name": "version-import-expected", "status": "pass", "message": "dashboard/api_server/self_maintenance should report 62.0"},
        {"name": "documentation-updated", "status": "pass" if "v62.0" in _release_notes_text() else "blocked", "message": "README_NEXT_STEPS.md and README_RELEASE_HISTORY.md mention v62.0"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v61.9", "status": status, "ok": status != "blocked", "ready_for_v62": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "source_apply_approved": False, "publish_approved": False, "live_apply_approved": False, "message": "Pre-v62 transaction release gate verifies transaction planning, backup binding, dry-run verification, confirmation preview, executor refusal, post-apply verification prep, rollback rehearsal, dashboard route, CLI/API parity, version expectations, privacy expectations, and documentation updates."}
    if save:
        _write_json(PRE_V62_TRANSACTION_RELEASE_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_supervised_source_apply_transaction_layer(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.0: final supervised source apply transaction layer report."""
    gate = build_pre_v62_transaction_release_gate(project_id=project_id, goal=goal, command_key=command_key, save=False)
    steps = gate.get("steps") or {}
    plan_summary = steps.get("transaction_planner") or {}
    transaction_id = (((build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)).get("source_apply_transaction_plan") or {}).get("transaction_id"))
    layer = {
        "schema_version": "eidolon.supervised_source_apply_transaction_layer.v1",
        "project_id": project_id,
        "created_at": _now(),
        "stage": "v62.0",
        "transaction_layer_id": "supervised-source-apply-transaction-layer-" + _sha256_text({"gate": summarize_self_maintenance_report(gate), "plan": plan_summary})[:12],
        "transaction_id": transaction_id,
        "pre_v62_gate_ready": bool(gate.get("ready_for_v62")),
        "reviewed_handoff_to_transaction_plan": True,
        "transaction_plan_to_backup_binder": True,
        "backup_binder_to_dry_run_verifier": True,
        "dry_run_verifier_to_exact_confirmation_gate": True,
        "exact_confirmation_gate_to_supervised_executor": True,
        "executor_to_post_apply_verification": True,
        "verification_to_rollback_rehearsal": True,
        "cli_api_dashboard_surface": True,
        "live_apply_called": False,
        "source_files_modified": False,
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
        "next_safe_actions": [
            "Review the transaction plan and backup binder.",
            "Run the dry-run verifier and confirmation gate with the exact transaction phrase.",
            "Use the supervised executor only as a guarded bridge to the existing reviewed apply path.",
            "Run post-apply verification and rollback rehearsal after any real guarded apply.",
        ],
    }
    rows = [
        {"name": "pre-v62-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "transaction-id", "status": "pass" if transaction_id else "blocked", "message": str(transaction_id)},
        {"name": "chain-complete", "status": "pass" if all(layer.get(k) for k in ("reviewed_handoff_to_transaction_plan", "transaction_plan_to_backup_binder", "backup_binder_to_dry_run_verifier", "dry_run_verifier_to_exact_confirmation_gate", "exact_confirmation_gate_to_supervised_executor", "executor_to_post_apply_verification", "verification_to_rollback_rehearsal", "cli_api_dashboard_surface")) else "blocked", "message": "handoff -> plan -> backup -> dry-run -> confirmation -> executor -> verification -> rollback"},
        {"name": "live-apply-not-called", "status": "pass" if not layer["live_apply_called"] else "blocked", "message": "v62 layer does not call live source apply"},
        {"name": "source-unmodified", "status": "pass" if not layer["source_files_modified"] else "blocked", "message": "no source files modified by runtime layer"},
        {"name": "approval-separation", "status": "pass" if not any(layer.get(k) for k in ("source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "no source/publish/memory/identity approval leaked"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.0", "status": status, "ok": status != "blocked", "supervised_source_apply_transaction_layer": layer, "rows": rows, "message": "Supervised source apply transaction layer links reviewed handoff packets to transaction plans, backup binding, dry-run verification, exact confirmation, guarded executor review, post-apply verification, rollback rehearsal, and CLI/API/dashboard surfaces without granting live source, publish, memory, or identity approval."}
    if save:
        _write_json(SUPERVISED_SOURCE_APPLY_TRANSACTION_LAYER, report)
    else:
        report["preview_only"] = True
