def _transaction_evidence_privacy_tokens() -> list[str]:
    return _transaction_privacy_tokens() + [
        "transaction_receipt_ledger.json",
        "transaction_diff_viewer.json",
        "transaction_conflict_detector.json",
        "transaction_approval_record_binder.json",
        "transaction_package_evidence_exporter.json",
        "transaction_replay_audit.json",
        "transaction_dashboard_receipt_timeline.json",
        "transaction_api_search_filtering.json",
        "pre_v63_transaction_evidence_gate.json",
        "durable_transaction_evidence_system.json",
        "data/autonomy/transaction_evidence/",
        "transaction_evidence_export",
        "exact_confirmation_phrase",
        "transaction_confirm_phrase",
    ]


def _read_transaction_receipt_entries() -> list[dict[str, Any]]:
    candidates = [TRANSACTION_EVIDENCE_LEDGER_FILE, TRANSACTION_RECEIPT_LEDGER]
    for path in candidates:
        try:
            if path.exists():
                payload = json.loads(path.read_text(encoding="utf-8"))
                entries = payload.get("receipts") if isinstance(payload, dict) else payload
                if isinstance(entries, list):
                    return [entry for entry in entries if isinstance(entry, dict)]
        except (OSError, json.JSONDecodeError):
            continue
    return []


def _write_transaction_receipt_entries(entries: list[dict[str, Any]]) -> None:
    TRANSACTION_EVIDENCE_DIR.mkdir(parents=True, exist_ok=True)
    payload = {
        "schema_version": "eidolon.transaction_receipt_ledger.v1",
        "updated_at": _now(),
        "receipt_count": len(entries),
        "receipts": entries[-50:],
    }
    write_text_atomic(TRANSACTION_EVIDENCE_LEDGER_FILE, json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")


def _current_transaction_receipt(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", stage: str = "v62.1") -> dict[str, Any]:
    plan_report = build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    backup_report = build_source_apply_backup_binder(project_id=project_id, goal=goal, command_key=command_key, save=False)
    dry_run_report = build_source_apply_transaction_dry_run_verifier(project_id=project_id, goal=goal, command_key=command_key, save=False)
    rollback_report = build_transaction_rollback_rehearsal(project_id=project_id, goal=goal, command_key=command_key, save=False)
    post_apply_report = build_post_apply_verification_runner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    plan = plan_report.get("source_apply_transaction_plan") or {}
    backup = backup_report.get("source_apply_backup_binder") or {}
    dry = dry_run_report.get("source_apply_transaction_dry_run_verifier") or {}
    rollback = rollback_report.get("transaction_rollback_rehearsal") or {}
    post_apply = post_apply_report.get("post_apply_verification_runner") or {}
    receipt_seed = {
        "transaction_id": plan.get("transaction_id"),
        "stage": stage,
        "source_baseline_hash": plan.get("source_baseline_hash"),
        "reviewed_artifact_hash": (plan.get("reviewed_bridge_summary") or {}).get("hash"),
        "backup_hash": backup.get("source_root_hash"),
        "rollback_hash": rollback.get("rollback_rehearsal_hash"),
        "verification_hash": _sha256_text(post_apply.get("verification_commands") or post_apply.get("prepared_checks") or []),
    }
    return {
        "schema_version": "eidolon.transaction_receipt.v1",
        "receipt_id": "transaction-receipt-" + _sha256_text(receipt_seed)[:12],
        "transaction_id": plan.get("transaction_id"),
        "stage": stage,
        "status": _status_from([
            {"status": _report_gate_status(plan_report)},
            {"status": _report_gate_status(backup_report)},
            {"status": _report_gate_status(dry_run_report)},
            {"status": _report_gate_status(rollback_report)},
            {"status": _report_gate_status(post_apply_report)},
        ]),
        "created_at": _now(),
        "project_id": project_id,
        "source_baseline_hash": plan.get("source_baseline_hash"),
        "reviewed_artifact_hash": (plan.get("reviewed_bridge_summary") or {}).get("hash"),
        "backup_hash": backup.get("source_root_hash"),
        "rollback_hash": rollback.get("rollback_rehearsal_hash") or _sha256_text(rollback),
        "verification_result": _report_gate_status(post_apply_report),
        "dry_run_result": _report_gate_status(dry_run_report),
        "source_apply_approval_state": "not-approved",
        "publish_approval_state": "separate-not-approved",
        "memory_approval_state": "separate-not-approved",
        "identity_approval_state": "separate-not-approved",
        "files_touched_preview": list(plan.get("files_to_modify") or []),
        "current_file_hashes": _transaction_file_hashes(plan.get("files_to_modify") or []),
        "safety_flags": {
            "live_apply_called": bool(dry.get("live_apply_called")),
            "source_files_modified": bool(dry.get("source_files_modified")),
            "publish_approved": False,
            "memory_write_approved": False,
            "identity_update_approved": False,
        },
        "receipt_hash": _sha256_text(receipt_seed),
    }


def build_transaction_receipt_ledger(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.1: persist a durable local ledger of source-apply transaction receipts."""
    receipt = _current_transaction_receipt(project_id=project_id, goal=goal, command_key=command_key, stage="v62.1")
    entries = _read_transaction_receipt_entries()
    by_id = {str(entry.get("receipt_id")): entry for entry in entries if entry.get("receipt_id")}
    by_id[receipt["receipt_id"]] = receipt
    ordered = sorted(by_id.values(), key=lambda item: str(item.get("created_at") or ""))[-50:]
    ledger = {
        "schema_version": "eidolon.transaction_receipt_ledger.v1",
        "project_id": project_id,
        "checked_at": _now(),
        "ledger_path": str(TRANSACTION_EVIDENCE_LEDGER_FILE.relative_to(ROOT_DIR)) if str(TRANSACTION_EVIDENCE_LEDGER_FILE).startswith(str(ROOT_DIR)) else str(TRANSACTION_EVIDENCE_LEDGER_FILE),
        "receipt_count": len(ordered),
        "latest_receipt": receipt,
        "receipts": ordered,
        "retention_limit": 50,
        "private_runtime_evidence": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "latest-receipt", "status": "pass" if receipt.get("receipt_id") else "blocked", "message": str(receipt.get("receipt_id"))},
        {"name": "transaction-id", "status": "pass" if receipt.get("transaction_id") else "blocked", "message": str(receipt.get("transaction_id"))},
        {"name": "source-baseline", "status": "pass" if receipt.get("source_baseline_hash") else "blocked", "message": str(receipt.get("source_baseline_hash", ""))[:16]},
        {"name": "approval-separation", "status": "pass" if not any(ledger.get(k) for k in ("source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "source/publish/memory/identity remain separate"},
        {"name": "ledger-write", "status": "pass", "message": "persistent ledger updated" if save else "preview only; ledger write path is available"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.1", "status": status, "ok": status != "blocked", "transaction_receipt_ledger": ledger, "rows": rows, "message": "Transaction receipt ledger records durable local evidence for transaction attempts while keeping approvals separate and private runtime data out of source packages."}
    if save:
        _write_transaction_receipt_entries(ordered)
        _write_json(TRANSACTION_RECEIPT_LEDGER, report)
    else:
        report["preview_only"] = True
    return report


def _receipt_pair(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import") -> tuple[dict[str, Any], dict[str, Any]]:
    entries = _read_transaction_receipt_entries()
    current = _current_transaction_receipt(project_id=project_id, goal=goal, command_key=command_key, stage="v62.2")
    previous = entries[-1] if entries else {
        "receipt_id": "synthetic-v62-baseline",
        "transaction_id": current.get("transaction_id"),
        "stage": "v62.0",
        "status": "baseline-preview",
        "source_baseline_hash": current.get("source_baseline_hash"),
        "reviewed_artifact_hash": current.get("reviewed_artifact_hash"),
        "backup_hash": current.get("backup_hash"),
        "rollback_hash": current.get("rollback_hash"),
        "verification_result": current.get("verification_result"),
        "files_touched_preview": current.get("files_touched_preview", []),
        "current_file_hashes": current.get("current_file_hashes", {}),
        "safety_flags": current.get("safety_flags", {}),
    }
    return previous, current


def build_transaction_diff_viewer(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.2: compare transaction receipts/plans so changes are obvious before review."""
    previous, current = _receipt_pair(project_id=project_id, goal=goal, command_key=command_key)
    prev_files = set(previous.get("files_touched_preview") or [])
    cur_files = set(current.get("files_touched_preview") or [])
    prev_hashes = previous.get("current_file_hashes") or {}
    cur_hashes = current.get("current_file_hashes") or {}
    common = sorted(prev_files & cur_files)
    modified = [rel for rel in common if prev_hashes.get(rel) != cur_hashes.get(rel)]
    diff = {
        "schema_version": "eidolon.transaction_diff_viewer.v1",
        "previous_receipt_id": previous.get("receipt_id"),
        "current_receipt_id": current.get("receipt_id"),
        "previous_transaction_id": previous.get("transaction_id"),
        "current_transaction_id": current.get("transaction_id"),
        "files_added": sorted(cur_files - prev_files),
        "files_removed": sorted(prev_files - cur_files),
        "files_modified": modified,
        "source_baseline_changed": previous.get("source_baseline_hash") != current.get("source_baseline_hash"),
        "reviewed_artifact_changed": previous.get("reviewed_artifact_hash") != current.get("reviewed_artifact_hash"),
        "backup_hash_changed": previous.get("backup_hash") != current.get("backup_hash"),
        "rollback_hash_changed": previous.get("rollback_hash") != current.get("rollback_hash"),
        "verification_result_changed": previous.get("verification_result") != current.get("verification_result"),
        "safety_flag_changes": {k: [previous.get("safety_flags", {}).get(k), current.get("safety_flags", {}).get(k)] for k in sorted(set((previous.get("safety_flags") or {}).keys()) | set((current.get("safety_flags") or {}).keys())) if (previous.get("safety_flags") or {}).get(k) != (current.get("safety_flags") or {}).get(k)},
    }
    rows = [
        {"name": "receipt-pair", "status": "pass" if diff["current_receipt_id"] else "blocked", "message": f"{diff['previous_receipt_id']} -> {diff['current_receipt_id']}"},
        {"name": "file-additions", "status": "pass", "message": str(len(diff["files_added"]))},
        {"name": "file-removals", "status": "pass", "message": str(len(diff["files_removed"]))},
        {"name": "file-modifications", "status": "warn" if modified else "pass", "message": str(len(modified))},
        {"name": "safety-flag-changes", "status": "blocked" if diff["safety_flag_changes"] else "pass", "message": str(diff["safety_flag_changes"] or "none")},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.2", "status": status, "ok": status != "blocked", "transaction_diff_viewer": diff, "rows": rows, "message": "Transaction diff viewer compares durable transaction evidence for changed files, hashes, verification state, rollback state, and safety flags."}
    if save:
        _write_json(TRANSACTION_DIFF_VIEWER, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_conflict_detector(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.3: detect stale or unsafe transaction evidence against the current source tree."""
    previous, current = _receipt_pair(project_id=project_id, goal=goal, command_key=command_key)
    current_hashes = _transaction_file_hashes(current.get("files_touched_preview") or [])
    receipt_hashes = previous.get("current_file_hashes") or {}
    changed_targets = [rel for rel, digest in receipt_hashes.items() if current_hashes.get(rel) and current_hashes.get(rel) != digest]
    protected_conflicts = [rel for rel in current.get("files_touched_preview") or [] if rel.startswith("data/") or rel.startswith(".git") or "__pycache__" in rel]
    conflicts: list[str] = []
    if previous.get("source_baseline_hash") != current.get("source_baseline_hash"):
        conflicts.append("baseline hash mismatch")
    if changed_targets:
        conflicts.append("target file changed")
    if previous.get("rollback_hash") and previous.get("rollback_hash") != current.get("rollback_hash"):
        conflicts.append("rollback evidence stale")
    if previous.get("backup_hash") and previous.get("backup_hash") != current.get("backup_hash"):
        conflicts.append("backup evidence stale")
    if previous.get("reviewed_artifact_hash") != current.get("reviewed_artifact_hash"):
        conflicts.append("reviewed artifact mismatch")
    if protected_conflicts:
        conflicts.append("protected file conflict")
    classification = "no conflict" if not conflicts else ("protected file conflict" if protected_conflicts else conflicts[0])
    detector = {
        "schema_version": "eidolon.transaction_conflict_detector.v1",
        "reference_receipt_id": previous.get("receipt_id"),
        "current_receipt_id": current.get("receipt_id"),
        "classification": classification,
        "conflicts": conflicts,
        "changed_target_files": changed_targets,
        "protected_conflicts": protected_conflicts,
        "current_source_hash": current.get("source_baseline_hash"),
        "reference_source_hash": previous.get("source_baseline_hash"),
        "recommendation": "refresh sandbox/transaction evidence before apply" if conflicts else "receipt evidence is compatible with current source preview",
    }
    rows = [
        {"name": "reference-receipt", "status": "pass" if previous.get("receipt_id") else "warn", "message": str(previous.get("receipt_id") or "none")},
        {"name": "classification", "status": "pass" if classification == "no conflict" else "warn", "message": classification},
        {"name": "changed-targets", "status": "warn" if changed_targets else "pass", "message": str(len(changed_targets))},
        {"name": "protected-conflicts", "status": "blocked" if protected_conflicts else "pass", "message": str(protected_conflicts or "none")},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.3", "status": status, "ok": status != "blocked", "transaction_conflict_detector": detector, "rows": rows, "message": "Transaction conflict detector checks whether durable receipts are stale against the current source baseline, target hashes, backup evidence, rollback evidence, reviewed artifacts, and protected paths."}
    if save:
        _write_json(TRANSACTION_CONFLICT_DETECTOR, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_approval_record_binder(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.4: bind approval metadata to one exact transaction without granting it."""
    plan_report = build_source_apply_transaction_planner(project_id=project_id, goal=goal, command_key=command_key, save=False)
    plan = plan_report.get("source_apply_transaction_plan") or {}
    record = {
        "schema_version": "eidolon.transaction_approval_record.v1",
        "transaction_id": plan.get("transaction_id"),
        "approval_record_id": "transaction-approval-record-" + _sha256_text({"transaction_id": plan.get("transaction_id"), "phrase_hash": plan.get("exact_confirmation_phrase_hash")})[:12],
        "exact_confirmation_phrase_hash": plan.get("exact_confirmation_phrase_hash"),
        "operator_approval_mode": "explicit-exact-phrase-required",
        "dry_run_vs_real_apply": "dry-run preview only until existing guarded source-apply path receives exact confirmation",
        "source_apply_approval_flag": False,
        "publish_approval_flag": False,
        "memory_approval_flag": False,
        "identity_approval_flag": False,
        "approval_scope": ["source-apply-transaction-review"],
        "approval_leakage_blocked": True,
    }
    rows = [
        {"name": "transaction-bound", "status": "pass" if record["transaction_id"] else "blocked", "message": str(record["transaction_id"])},
        {"name": "confirmation-hash", "status": "pass" if record["exact_confirmation_phrase_hash"] else "blocked", "message": str(record["exact_confirmation_phrase_hash"] or "")[:16]},
        {"name": "source-approval", "status": "pass" if not record["source_apply_approval_flag"] else "blocked", "message": "not approved"},
        {"name": "publish-memory-identity-separate", "status": "pass" if not any(record[k] for k in ("publish_approval_flag", "memory_approval_flag", "identity_approval_flag")) else "blocked", "message": "separate and not approved"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.4", "status": status, "ok": status != "blocked", "transaction_approval_record_binder": record, "rows": rows, "message": "Transaction approval record binder binds approval metadata to the exact transaction/confirmation hash while refusing generic source, publish, memory, or identity approval."}
    if save:
        _write_json(TRANSACTION_APPROVAL_RECORD_BINDER, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_package_evidence_exporter(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.5: export safe transaction evidence without leaking private runtime state or phrases."""
    ledger_report = build_transaction_receipt_ledger(project_id=project_id, goal=goal, command_key=command_key, save=False)
    diff_report = build_transaction_diff_viewer(project_id=project_id, goal=goal, command_key=command_key, save=False)
    conflict_report = build_transaction_conflict_detector(project_id=project_id, goal=goal, command_key=command_key, save=False)
    approval_report = build_transaction_approval_record_binder(project_id=project_id, goal=goal, command_key=command_key, save=False)
    latest = (ledger_report.get("transaction_receipt_ledger") or {}).get("latest_receipt") or {}
    safe_export = {
        "schema_version": "eidolon.transaction_package_evidence_export.v1",
        "project_id": project_id,
        "created_at": _now(),
        "transaction_id": latest.get("transaction_id"),
        "receipt_id": latest.get("receipt_id"),
        "receipt_hash": latest.get("receipt_hash"),
        "source_baseline_hash": latest.get("source_baseline_hash"),
        "reviewed_artifact_hash": latest.get("reviewed_artifact_hash"),
        "backup_hash": latest.get("backup_hash"),
        "rollback_hash": latest.get("rollback_hash"),
        "dry_run_result": latest.get("dry_run_result"),
        "verification_result": latest.get("verification_result"),
        "conflict_classification": (conflict_report.get("transaction_conflict_detector") or {}).get("classification"),
        "diff_summary": {k: (diff_report.get("transaction_diff_viewer") or {}).get(k) for k in ("files_added", "files_removed", "files_modified", "source_baseline_changed", "reviewed_artifact_changed")},
        "approval_record_id": (approval_report.get("transaction_approval_record_binder") or {}).get("approval_record_id"),
        "excluded_private_tokens": _transaction_evidence_privacy_tokens(),
        "contains_confirmation_phrase": False,
        "contains_memory_files": False,
        "contains_identity_files": False,
        "contains_backups": False,
        "contains_logs": False,
        "contains_nested_zips": False,
    }
    export_id = "transaction-evidence-export-" + _sha256_text(safe_export)[:12]
    safe_export["export_id"] = export_id
    safe_export["export_hash"] = _sha256_text(safe_export)
    rows = [
        {"name": "safe-export-id", "status": "pass" if export_id else "blocked", "message": export_id},
        {"name": "no-confirmation-phrase", "status": "pass" if not safe_export["contains_confirmation_phrase"] else "blocked", "message": "phrase excluded"},
        {"name": "no-memory-identity", "status": "pass" if not safe_export["contains_memory_files"] and not safe_export["contains_identity_files"] else "blocked", "message": "memory/identity excluded"},
        {"name": "no-backups-logs-zips", "status": "pass" if not any(safe_export[k] for k in ("contains_backups", "contains_logs", "contains_nested_zips")) else "blocked", "message": "backups/logs/zips excluded"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.5", "status": status, "ok": status != "blocked", "transaction_package_evidence_exporter": safe_export, "rows": rows, "message": "Transaction package evidence exporter prepares a safe shareable evidence summary while excluding confirmation phrases, private runtime state, memories, identities, backups, logs, and nested packages."}
    if save:
        TRANSACTION_EVIDENCE_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic((TRANSACTION_EVIDENCE_EXPORT_DIR / f"{export_id}.json"), json.dumps(safe_export, indent=2, sort_keys=True), encoding="utf-8")
        _write_json(TRANSACTION_PACKAGE_EVIDENCE_EXPORTER, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_replay_audit(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.6: audit whether a past transaction receipt is still understandable and replay-safe."""
    ledger_report = build_transaction_receipt_ledger(project_id=project_id, goal=goal, command_key=command_key, save=False)
    conflict_report = build_transaction_conflict_detector(project_id=project_id, goal=goal, command_key=command_key, save=False)
    latest = (ledger_report.get("transaction_receipt_ledger") or {}).get("latest_receipt") or {}
    required_keys = ["schema_version", "receipt_id", "transaction_id", "source_baseline_hash", "reviewed_artifact_hash", "backup_hash", "rollback_hash", "verification_result", "receipt_hash"]
    missing = [key for key in required_keys if not latest.get(key)]
    conflict = conflict_report.get("transaction_conflict_detector") or {}
    audit = {
        "schema_version": "eidolon.transaction_replay_audit.v1",
        "receipt_id": latest.get("receipt_id"),
        "transaction_id": latest.get("transaction_id"),
        "required_keys_present": not missing,
        "missing_keys": missing,
        "hash_consistency_checked": bool(latest.get("receipt_hash")),
        "source_baseline_comparison": conflict.get("classification"),
        "artifact_references_present": bool(latest.get("reviewed_artifact_hash") and latest.get("backup_hash") and latest.get("rollback_hash")),
        "command_availability": "prepared-by-v62-post-apply-runner",
        "rollback_evidence_present": bool(latest.get("rollback_hash")),
        "privacy_boundaries_present": True,
        "replay_safe": not missing and conflict.get("classification") in ("no conflict", None),
    }
    rows = [
        {"name": "receipt-schema", "status": "pass" if latest.get("schema_version") == "eidolon.transaction_receipt.v1" else "blocked", "message": str(latest.get("schema_version"))},
        {"name": "required-keys", "status": "pass" if not missing else "blocked", "message": str(missing or "all present")},
        {"name": "source-conflict", "status": "pass" if conflict.get("classification") == "no conflict" else "warn", "message": str(conflict.get("classification"))},
        {"name": "rollback-evidence", "status": "pass" if audit["rollback_evidence_present"] else "blocked", "message": "present" if audit["rollback_evidence_present"] else "missing"},
        {"name": "replay-safe", "status": "pass" if audit["replay_safe"] else "warn", "message": str(audit["replay_safe"])},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.6", "status": status, "ok": status != "blocked", "transaction_replay_audit": audit, "rows": rows, "message": "Transaction replay audit checks receipt schema, required keys, hash consistency evidence, source conflict state, artifact references, rollback evidence, privacy boundaries, and replay safety without applying anything."}
    if save:
        _write_json(TRANSACTION_REPLAY_AUDIT, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_dashboard_receipt_timeline(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v62.7: summarize transaction receipts for the dashboard timeline."""
    entries = _read_transaction_receipt_entries()
    if not entries:
        entries = [_current_transaction_receipt(project_id=project_id, stage="v62.7")]
    timeline_entries = [
        {
            "receipt_id": entry.get("receipt_id"),
            "transaction_id": entry.get("transaction_id"),
            "stage": entry.get("stage"),
            "status": entry.get("status"),
            "created_at": entry.get("created_at"),
            "source_baseline_hash": str(entry.get("source_baseline_hash") or "")[:16],
            "approval_state": entry.get("source_apply_approval_state", "not-approved"),
            "verification_result": entry.get("verification_result"),
            "rollback_hash": str(entry.get("rollback_hash") or "")[:16],
        }
        for entry in entries[-12:]
    ]
    timeline = {
        "schema_version": "eidolon.transaction_dashboard_receipt_timeline.v1",
        "route": "/transaction-evidence",
        "entry_count": len(timeline_entries),
        "entries": timeline_entries,
        "status_badges": [entry.get("status") for entry in timeline_entries],
        "api_links": ["/api/self-maintenance/transaction-receipt-ledger", "/api/self-maintenance/transaction-api-search-filtering"],
        "dashboard_read_only": True,
    }
    rows = [
        {"name": "timeline-route", "status": "pass", "message": timeline["route"]},
        {"name": "timeline-entries", "status": "pass" if timeline_entries else "warn", "message": str(len(timeline_entries))},
        {"name": "read-only", "status": "pass" if timeline["dashboard_read_only"] else "blocked", "message": "dashboard does not approve/apply"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.7", "status": status, "ok": status != "blocked", "transaction_dashboard_receipt_timeline": timeline, "rows": rows, "message": "Dashboard receipt timeline exposes recent transaction receipts, statuses, hashes, approval state, verification state, rollback state, and API links in a read-only view."}
    if save:
        _write_json(TRANSACTION_DASHBOARD_RECEIPT_TIMELINE, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_api_search_filtering(project_id: str = "eidolon", transaction_id: str | None = None, status_filter: str | None = None, stage_filter: str | None = None, file_touched: str | None = None, save: bool = True) -> dict[str, Any]:
    """v62.8: expose read-only transaction receipt search/filtering evidence."""
    entries = _read_transaction_receipt_entries()
    if not entries:
        entries = [_current_transaction_receipt(project_id=project_id, stage="v62.8")]
    def match(entry: dict[str, Any]) -> bool:
        if transaction_id and transaction_id not in str(entry.get("transaction_id") or ""):
            return False
        if status_filter and status_filter != str(entry.get("status") or ""):
            return False
        if stage_filter and stage_filter != str(entry.get("stage") or ""):
            return False
        if file_touched and file_touched not in (entry.get("files_touched_preview") or []):
            return False
        return True
    matches = [entry for entry in entries if match(entry)]
    search = {
        "schema_version": "eidolon.transaction_api_search_filtering.v1",
        "route": "/api/self-maintenance/transaction-api-search-filtering",
        "filters": {"transaction_id": transaction_id, "status": status_filter, "stage": stage_filter, "file_touched": file_touched},
        "match_count": len(matches),
        "matches": [
            {
                "receipt_id": entry.get("receipt_id"),
                "transaction_id": entry.get("transaction_id"),
                "stage": entry.get("stage"),
                "status": entry.get("status"),
                "created_at": entry.get("created_at"),
                "source_baseline_hash": entry.get("source_baseline_hash"),
                "files_touched_preview": entry.get("files_touched_preview", []),
            }
            for entry in matches[:25]
        ],
        "read_only": True,
        "does_not_expose_confirmation_phrase": True,
    }
    rows = [
        {"name": "api-route", "status": "pass", "message": search["route"]},
        {"name": "filter-results", "status": "pass", "message": str(len(matches))},
        {"name": "read-only", "status": "pass" if search["read_only"] else "blocked", "message": "no mutation"},
        {"name": "phrase-excluded", "status": "pass" if search["does_not_expose_confirmation_phrase"] else "blocked", "message": "confirmation phrase not exposed"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.8", "status": status, "ok": status != "blocked", "transaction_api_search_filtering": search, "rows": rows, "message": "Transaction API search/filtering provides read-only receipt lookup by transaction, status, stage, and touched file while excluding confirmation phrases."}
    if save:
        _write_json(TRANSACTION_API_SEARCH_FILTERING, report)
    else:
        report["preview_only"] = True
    return report


def build_pre_v63_transaction_evidence_gate(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v62.9: final gate for durable transaction evidence before v63.0."""
    checks = {
        "receipt_ledger": build_transaction_receipt_ledger(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "diff_viewer": build_transaction_diff_viewer(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "conflict_detector": build_transaction_conflict_detector(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "approval_binder": build_transaction_approval_record_binder(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "evidence_exporter": build_transaction_package_evidence_exporter(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "replay_audit": build_transaction_replay_audit(project_id=project_id, goal=goal, command_key=command_key, save=False),
        "dashboard_timeline": build_transaction_dashboard_receipt_timeline(project_id=project_id, save=False),
        "api_search": build_transaction_api_search_filtering(project_id=project_id, save=False),
    }
    rows = [{"name": name.replace("_", "-"), "status": _report_gate_status(report), "message": str(report.get("message", ""))[:180]} for name, report in checks.items()]
    rows.extend([
        {"name": "compile-expected", "status": "pass", "message": "python -m py_compile conscious_agent/*.py tools/smoke_check.py"},
        {"name": "install-smoke-expected", "status": "pass", "message": "python tools/smoke_check.py --install"},
        {"name": "version-import-expected", "status": "pass", "message": "dashboard/api_server/self_maintenance should report 63.0"},
        {"name": "documentation-updated", "status": "pass" if "v63.0" in _release_notes_text() else "blocked", "message": "README_NEXT_STEPS.md and README_RELEASE_HISTORY.md mention v63.0"},
        {"name": "privacy-tokens", "status": "pass" if _transaction_evidence_privacy_tokens() else "blocked", "message": f"{len(_transaction_evidence_privacy_tokens())} tokens"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v62.9", "status": status, "ok": status != "blocked", "ready_for_v63": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "message": "Pre-v63 transaction evidence gate verifies ledger, diff viewer, conflict detector, approval binder, safe exporter, replay audit, dashboard timeline, API search/filtering, privacy tokens, version expectations, and documentation updates."}
    if save:
        _write_json(PRE_V63_TRANSACTION_EVIDENCE_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_durable_transaction_evidence_system(project_id: str = "eidolon", goal: str | None = None, command_key: str = "version-import", save: bool = True) -> dict[str, Any]:
    """v63.0: durable, searchable, comparable, exportable, replay-auditable transaction evidence."""
    gate = build_pre_v63_transaction_evidence_gate(project_id=project_id, goal=goal, command_key=command_key, save=False)
    ledger = build_transaction_receipt_ledger(project_id=project_id, goal=goal, command_key=command_key, save=False)
    latest = (ledger.get("transaction_receipt_ledger") or {}).get("latest_receipt") or {}
    system = {
        "schema_version": "eidolon.durable_transaction_evidence_system.v1",
        "project_id": project_id,
        "created_at": _now(),
        "stage": "v63.0",
        "system_id": "durable-transaction-evidence-" + _sha256_text({"gate": summarize_self_maintenance_report(gate), "latest": latest})[:12],
        "ledger_enabled": True,
        "diff_viewer_enabled": True,
        "conflict_detector_enabled": True,
        "approval_record_binding_enabled": True,
        "safe_export_enabled": True,
        "replay_audit_enabled": True,
        "dashboard_timeline_route": "/transaction-evidence",
        "api_search_route": "/api/self-maintenance/transaction-api-search-filtering",
        "latest_transaction_id": latest.get("transaction_id"),
        "latest_receipt_id": latest.get("receipt_id"),
        "private_runtime_ledger_path": str(TRANSACTION_EVIDENCE_LEDGER_FILE),
        "package_privacy_enforced": True,
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
        "live_apply_called": False,
        "source_files_modified": False,
        "next_safe_arc": "v63.x can use receipt history to score supervised improvement candidates without granting autonomous apply.",
    }
    rows = [
        {"name": "pre-v63-gate", "status": _report_gate_status(gate), "message": str(gate.get("message", ""))[:180]},
        {"name": "latest-receipt", "status": "pass" if system["latest_receipt_id"] else "blocked", "message": str(system["latest_receipt_id"])},
        {"name": "dashboard-route", "status": "pass", "message": system["dashboard_timeline_route"]},
        {"name": "api-route", "status": "pass", "message": system["api_search_route"]},
        {"name": "approval-separation", "status": "pass" if not any(system[k] for k in ("source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "no approval granted"},
        {"name": "no-live-apply", "status": "pass" if not system["live_apply_called"] and not system["source_files_modified"] else "blocked", "message": "durable evidence only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v63.0", "status": status, "ok": status != "blocked", "durable_transaction_evidence_system": system, "rows": rows, "message": "Durable transaction evidence system makes transaction receipts persistent, diffable, conflict-aware, transaction-bound, safely exportable, replay-auditable, dashboard-visible, and API-searchable without granting live source, publish, memory, or identity approval."}
    if save:
        # Saving the final system also writes one durable ledger receipt so the timeline is not empty.
        build_transaction_receipt_ledger(project_id=project_id, goal=goal, command_key=command_key, save=True)
        _write_json(DURABLE_TRANSACTION_EVIDENCE_SYSTEM, report)
    else:
        report["preview_only"] = True
    return report


