def _latest_transaction_entries_for_intelligence(project_id: str = "eidolon") -> list[dict[str, Any]]:
    entries = _read_transaction_receipt_entries()
    if not entries:
        try:
            ledger = build_transaction_receipt_ledger(project_id=project_id, save=True)
            receipt = ledger.get("latest_receipt")
            if isinstance(receipt, dict):
                entries = [receipt]
        except Exception:
            entries = []
    return [entry for entry in entries if isinstance(entry, dict)]


