def _proposal_drafting_tokens() -> list[str]:
    return [
        "accepted-recommendation-intake",
        "proposal-draft-skeleton",
        "evidence-requirement-mapper",
        "proposal-risk-contract",
        "sandbox-patch-request-compiler",
        "proposal-review-packet-binder",
        "proposal-dashboard-review-console",
        "proposal-api-cli-access",
        "pre-v65-proposal-drafting-gate",
        "recommendation-to-proposal-drafting-layer",
    ]


def _selected_recommendation_for_drafting(project_id: str = "eidolon", recommendation_id: str | None = None) -> dict[str, Any]:
    queue = build_supervised_recommendation_queue(project_id=project_id, save=False)
    items = queue.get("recommendation_queue") or []
    if recommendation_id:
        selected = next((item for item in items if str(item.get("candidate_id")) == str(recommendation_id) or str(item.get("recommendation_id")) == str(recommendation_id)), None)
        if selected:
            return selected
    selected = queue.get("highest_value_candidate") or (items[0] if items else {})
    if selected:
        return dict(selected)
    return {
        "candidate_id": "candidate-proposal-drafting-baseline",
        "title": "Create supervised proposal drafting baseline",
        "score": 70,
        "recommendation": "recommended",
        "risk_level": "low",
        "next_safe_action": "prepare supervised patch proposal",
        "blocked_by_missing_evidence": False,
    }


def _proposal_id_from_intake(intake: dict[str, Any]) -> str:
    return "proposal-" + _sha256_text({"recommendation": intake.get("recommendation_id"), "accepted_at": intake.get("accepted_at"), "project": intake.get("project_id")})[:12]


def build_accepted_recommendation_intake(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v64.1: accept one supervised recommendation into proposal drafting without creating a patch."""
    selected = _selected_recommendation_for_drafting(project_id=project_id, recommendation_id=recommendation_id)
    registry = build_improvement_candidate_registry(project_id=project_id, save=False).get("improvement_candidate_registry", {})
    candidate = next((item for item in registry.get("candidates", []) if str(item.get("candidate_id")) == str(selected.get("candidate_id"))), {})
    accepted_at = _now()
    intake = {
        "schema_version": "eidolon.accepted_recommendation_intake.v1",
        "project_id": project_id,
        "accepted_at": accepted_at,
        "intake_id": "intake-" + _sha256_text({"selected": selected, "accepted_at": accepted_at})[:12],
        "recommendation_id": selected.get("candidate_id") or selected.get("recommendation_id"),
        "title": selected.get("title") or candidate.get("title") or "Untitled supervised recommendation",
        "operator_acceptance_state": "accepted-for-proposal-drafting",
        "source_evidence_summary": candidate.get("reason") or "Selected from supervised recommendation queue and durable transaction evidence.",
        "expected_affected_files": candidate.get("affected_files") or ["conscious_agent/self_maintenance.py", "conscious_agent/main.py", "conscious_agent/api_server.py", "conscious_agent/dashboard.py", "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "expected_risk_level": selected.get("risk_level") or candidate.get("risk_level") or "medium",
        "linked_transaction_receipts": candidate.get("related_transaction_receipts") or [],
        "safety_boundaries": {
            "proposal_drafting_only": True,
            "sandbox_request_allowed": True,
            "patch_created": False,
            "source_apply_approved": False,
            "publish_approved": False,
            "memory_write_approved": False,
            "identity_update_approved": False,
            "live_apply_called": False,
        },
    }
    rows = [
        {"name": "recommendation-selected", "status": "pass" if intake.get("recommendation_id") else "blocked", "message": str(intake.get("recommendation_id"))},
        {"name": "operator-acceptance-state", "status": "pass" if intake["operator_acceptance_state"] == "accepted-for-proposal-drafting" else "blocked", "message": intake["operator_acceptance_state"]},
        {"name": "affected-files", "status": "pass" if intake["expected_affected_files"] else "blocked", "message": f"{len(intake['expected_affected_files'])} expected file(s)"},
        {"name": "approval-boundaries", "status": "pass" if not any(intake["safety_boundaries"][key] for key in ("patch_created", "source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved", "live_apply_called")) else "blocked", "message": "acceptance does not grant mutation authority"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.1", "status": status, "ok": status != "blocked", "accepted_recommendation_intake": intake, "rows": rows, "message": "Accepted recommendation intake separates queue selection from supervised proposal drafting and grants no source, publish, memory, or identity approval."}
    if save:
        PROPOSAL_DRAFTING_DIR.mkdir(parents=True, exist_ok=True)
        _write_json(ACCEPTED_RECOMMENDATION_INTAKE, report)
    else:
        report["preview_only"] = True
    return report


def build_proposal_draft_skeleton(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v64.2: build a structured proposal draft skeleton from accepted recommendation intake."""
    intake_report = build_accepted_recommendation_intake(project_id=project_id, recommendation_id=recommendation_id, save=False)
    intake = intake_report.get("accepted_recommendation_intake") or {}
    proposal_id = _proposal_id_from_intake(intake)
    files = list(intake.get("expected_affected_files") or [])
    draft = {
        "schema_version": "eidolon.proposal_draft_skeleton.v1",
        "project_id": project_id,
        "proposal_id": proposal_id,
        "created_at": _now(),
        "title": f"Proposal draft: {intake.get('title', 'supervised improvement')}",
        "reason": intake.get("source_evidence_summary"),
        "target_files": files,
        "intended_behavior_change": "Convert an accepted supervised recommendation into a reviewable sandbox patch request with explicit safety boundaries.",
        "non_goals": ["do not apply source", "do not publish", "do not write memory", "do not alter identity", "do not bypass exact confirmation gates"],
        "safety_constraints": intake.get("safety_boundaries", {}),
        "verification_commands": [
            "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
            "python tools/smoke_check.py --tier install",
            "python conscious_agent/main.py --recommendation-to-proposal-drafting-layer --readiness-json",
        ],
        "rollback_expectations": ["all source edits remain outside this drafting layer", "future sandbox requests must bind rollback expectations before source apply"],
        "documentation_requirements": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "proposal-id", "status": "pass" if proposal_id else "blocked", "message": proposal_id},
        {"name": "target-files", "status": "pass" if files else "blocked", "message": f"{len(files)} target file(s)"},
        {"name": "verification-plan", "status": "pass" if len(draft["verification_commands"]) >= 3 else "blocked", "message": f"{len(draft['verification_commands'])} command(s)"},
        {"name": "non-goals", "status": "pass" if "do not apply source" in draft["non_goals"] else "blocked", "message": "mutation boundaries explicit"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.2", "status": status, "ok": status != "blocked", "proposal_draft_skeleton": draft, "rows": rows, "message": "Proposal draft skeleton turns accepted recommendations into structured review drafts with non-goals, verification, rollback, and documentation requirements."}
    if save: _write_json(PROPOSAL_DRAFT_SKELETON, report)
    else: report["preview_only"] = True
    return report


def build_evidence_requirement_mapper(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v64.3: map durable evidence and intelligence outputs into proposal requirements."""
    draft = build_proposal_draft_skeleton(project_id=project_id, recommendation_id=recommendation_id, save=False).get("proposal_draft_skeleton") or {}
    summary = build_transaction_evidence_summarizer(project_id=project_id, save=False).get("transaction_evidence_summary", {})
    regression = build_improvement_regression_pattern_detector(project_id=project_id, save=False).get("regression_patterns", [])
    scoring = build_evidence_based_candidate_scoring(project_id=project_id, save=False).get("candidate_scores", [])
    mapper = {
        "schema_version": "eidolon.evidence_requirement_mapper.v1",
        "proposal_id": draft.get("proposal_id"),
        "project_id": project_id,
        "mapped_at": _now(),
        "source_evidence": {
            "transaction_summary_hash": _sha256_text(summary),
            "regression_pattern_count": len(regression),
            "candidate_score_count": len(scoring),
            "most_common_touched_files": summary.get("most_common_touched_files", []),
        },
        "required_behavior_changes": [
            "represent accepted recommendation as explicit proposal draft",
            "bind proposal draft to evidence-derived requirements",
            "compile sandbox-only patch request without source apply authority",
        ],
        "required_tests_checks": draft.get("verification_commands", []),
        "required_docs_updates": draft.get("documentation_requirements", []),
        "protected_boundaries": ["source apply", "publish approval", "memory writes", "identity updates", "private runtime ledgers", "confirmation phrases"],
        "open_risks": [pattern.get("pattern_id") for pattern in regression if pattern.get("status") in {"warn", "blocked"}],
        "source_apply_approved": False,
        "publish_approved": False,
    }
    rows = [
        {"name": "proposal-bound", "status": "pass" if mapper.get("proposal_id") else "blocked", "message": str(mapper.get("proposal_id"))},
        {"name": "behavior-requirements", "status": "pass" if mapper["required_behavior_changes"] else "blocked", "message": f"{len(mapper['required_behavior_changes'])} requirement(s)"},
        {"name": "docs-requirements", "status": "pass" if mapper["required_docs_updates"] else "blocked", "message": ", ".join(mapper["required_docs_updates"])},
        {"name": "protected-boundaries", "status": "pass" if "source apply" in mapper["protected_boundaries"] else "blocked", "message": "mutation boundaries mapped"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.3", "status": status, "ok": status != "blocked", "evidence_requirement_mapping": mapper, "rows": rows, "message": "Evidence-to-requirement mapper converts receipts, regression patterns, candidate scores, and risk signals into concrete proposal requirements."}
    if save: _write_json(EVIDENCE_REQUIREMENT_MAPPER, report)
    else: report["preview_only"] = True
    return report


def build_proposal_risk_contract(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v64.4: attach an explicit risk contract to a proposal draft."""
    draft = build_proposal_draft_skeleton(project_id=project_id, recommendation_id=recommendation_id, save=False).get("proposal_draft_skeleton") or {}
    forecast_report = build_improvement_risk_blast_radius_forecaster(project_id=project_id, save=False)
    forecasts = forecast_report.get("risk_forecasts", [])
    intake = build_accepted_recommendation_intake(project_id=project_id, recommendation_id=recommendation_id, save=False).get("accepted_recommendation_intake", {})
    rid = intake.get("recommendation_id")
    forecast = next((item for item in forecasts if str(item.get("candidate_id")) == str(rid)), forecasts[0] if forecasts else {})
    contract = {
        "schema_version": "eidolon.proposal_risk_contract.v1",
        "project_id": project_id,
        "proposal_id": draft.get("proposal_id"),
        "risk_contract_id": "risk-" + _sha256_text({"proposal": draft.get("proposal_id"), "forecast": forecast})[:12],
        "risk_level": forecast.get("risk_level") or intake.get("expected_risk_level") or "medium",
        "blast_radius": forecast.get("blast_radius") or ["CLI/API/dashboard/docs"],
        "protected_files": ["data/", "data/autonomy/", "data/self_maintenance/", ".env", "*.key", "*.pem"],
        "allowed_file_classes": ["Python source", "README documentation", "release history", "smoke checks"],
        "disallowed_file_classes": ["runtime memory", "identity state", "approval secrets", "confirmation phrases", "backups", "logs", "nested release zips"],
        "runtime_private_data_boundaries": ["data/autonomy/proposal_drafting", "data/autonomy/improvement_intelligence", "data/autonomy/transaction_evidence"],
        "apply_restrictions": ["sandbox request only", "no source apply approval", "no publish approval", "exact confirmation remains external"],
        "rollback_expectations": draft.get("rollback_expectations", []),
        "verification_minimums": draft.get("verification_commands", []),
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "risk-contract-id", "status": "pass" if contract["risk_contract_id"] else "blocked", "message": contract["risk_contract_id"]},
        {"name": "protected-files", "status": "pass" if contract["protected_files"] else "blocked", "message": f"{len(contract['protected_files'])} protected pattern(s)"},
        {"name": "disallowed-files", "status": "pass" if "approval secrets" in contract["disallowed_file_classes"] else "blocked", "message": "private/runtime/secret classes disallowed"},
        {"name": "apply-restrictions", "status": "pass" if "no source apply approval" in contract["apply_restrictions"] else "blocked", "message": "sandbox-only restrictions explicit"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.4", "status": status, "ok": status != "blocked", "proposal_risk_contract": contract, "rows": rows, "message": "Proposal risk contract makes blast radius, allowed/disallowed file classes, runtime privacy, apply restrictions, rollback, and verification minimums explicit before any sandbox work request."}
    if save: _write_json(PROPOSAL_RISK_CONTRACT, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_patch_request_compiler(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v64.5: compile a proposal draft into a sandbox-only patch request."""
    draft = build_proposal_draft_skeleton(project_id=project_id, recommendation_id=recommendation_id, save=False).get("proposal_draft_skeleton") or {}
    mapping = build_evidence_requirement_mapper(project_id=project_id, recommendation_id=recommendation_id, save=False).get("evidence_requirement_mapping", {})
    risk = build_proposal_risk_contract(project_id=project_id, recommendation_id=recommendation_id, save=False).get("proposal_risk_contract", {})
    request = {
        "schema_version": "eidolon.sandbox_patch_request.v1",
        "project_id": project_id,
        "patch_request_id": "sandbox-request-" + _sha256_text({"proposal": draft.get("proposal_id"), "risk": risk.get("risk_contract_id")})[:12],
        "proposal_id": draft.get("proposal_id"),
        "compiled_at": _now(),
        "implementation_summary": draft.get("intended_behavior_change"),
        "expected_file_operations": [{"operation": "review-or-edit", "path": path} for path in draft.get("target_files", [])],
        "verification_checklist": mapping.get("required_tests_checks", []),
        "dry_run_requirements": ["run in temporary sandbox", "record diff preview", "record verification receipt", "do not write live source"],
        "privacy_exclusions": risk.get("disallowed_file_classes", []),
        "exact_review_instructions": ["operator reviews proposal packet", "sandbox result must bind to proposal hash", "source apply remains a separate guarded transaction"],
        "source_apply_permission": False,
        "publish_permission": False,
        "memory_write_permission": False,
        "identity_update_permission": False,
    }
    rows = [
        {"name": "patch-request-id", "status": "pass" if request["patch_request_id"] else "blocked", "message": request["patch_request_id"]},
        {"name": "expected-operations", "status": "pass" if request["expected_file_operations"] else "blocked", "message": f"{len(request['expected_file_operations'])} operation(s)"},
        {"name": "dry-run-only", "status": "pass" if "do not write live source" in request["dry_run_requirements"] else "blocked", "message": "sandbox-only request"},
        {"name": "no-source-permission", "status": "pass" if not request["source_apply_permission"] and not request["publish_permission"] else "blocked", "message": "no live permission granted"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.5", "status": status, "ok": status != "blocked", "sandbox_patch_request": request, "rows": rows, "message": "Sandbox patch request compiler turns proposal drafts into sandbox-ready requests with verification, dry-run, privacy, and review instructions while withholding source apply permission."}
    if save: _write_json(SANDBOX_PATCH_REQUEST_COMPILER, report)
    else: report["preview_only"] = True
    return report


def build_proposal_review_packet_binder(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v64.6: bind accepted intake, proposal, evidence mapping, risk contract, and sandbox request into one packet."""
    intake = build_accepted_recommendation_intake(project_id=project_id, recommendation_id=recommendation_id, save=False)
    draft = build_proposal_draft_skeleton(project_id=project_id, recommendation_id=recommendation_id, save=False)
    mapping = build_evidence_requirement_mapper(project_id=project_id, recommendation_id=recommendation_id, save=False)
    risk = build_proposal_risk_contract(project_id=project_id, recommendation_id=recommendation_id, save=False)
    request = build_sandbox_patch_request_compiler(project_id=project_id, recommendation_id=recommendation_id, save=False)
    packet = {
        "schema_version": "eidolon.proposal_review_packet.v1",
        "project_id": project_id,
        "created_at": _now(),
        "packet_id": "proposal-packet-" + _sha256_text({"intake": intake.get("accepted_recommendation_intake"), "draft": draft.get("proposal_draft_skeleton"), "request": request.get("sandbox_patch_request")})[:12],
        "accepted_recommendation_hash": _sha256_text(intake.get("accepted_recommendation_intake", {})),
        "proposal_draft_hash": _sha256_text(draft.get("proposal_draft_skeleton", {})),
        "evidence_mapping_hash": _sha256_text(mapping.get("evidence_requirement_mapping", {})),
        "risk_contract_hash": _sha256_text(risk.get("proposal_risk_contract", {})),
        "sandbox_patch_request_hash": _sha256_text(request.get("sandbox_patch_request", {})),
        "verification_plan": (request.get("sandbox_patch_request") or {}).get("verification_checklist", []),
        "rollback_plan": (risk.get("proposal_risk_contract") or {}).get("rollback_expectations", []),
        "dashboard_api_cli_parity_expectations": _proposal_drafting_tokens(),
        "complete": all(_report_gate_status(report) != "blocked" for report in (intake, draft, mapping, risk, request)),
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
    }
    rows = [
        {"name": "packet-id", "status": "pass" if packet["packet_id"] else "blocked", "message": packet["packet_id"]},
        {"name": "component-hashes", "status": "pass" if all(packet.get(k) for k in ("accepted_recommendation_hash", "proposal_draft_hash", "evidence_mapping_hash", "risk_contract_hash", "sandbox_patch_request_hash")) else "blocked", "message": "all core hashes present"},
        {"name": "packet-complete", "status": "pass" if packet["complete"] else "blocked", "message": str(packet["complete"])},
        {"name": "approval-separation", "status": "pass" if not any(packet[k] for k in ("source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "packet is review evidence only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.6", "status": status, "ok": status != "blocked", "proposal_review_packet": packet, "steps": {"intake": summarize_self_maintenance_report(intake), "draft": summarize_self_maintenance_report(draft), "mapping": summarize_self_maintenance_report(mapping), "risk": summarize_self_maintenance_report(risk), "request": summarize_self_maintenance_report(request)}, "rows": rows, "message": "Proposal review packet binder collects the accepted recommendation, proposal draft, evidence mapping, risk contract, sandbox patch request, verification plan, and rollback plan into one operator-review packet."}
    if save:
        PROPOSAL_DRAFTING_DIR.mkdir(parents=True, exist_ok=True)
        write_text_atomic(PROPOSAL_DRAFTING_REGISTRY_FILE, json.dumps(packet, indent=2, sort_keys=True), encoding="utf-8")
        _write_json(PROPOSAL_REVIEW_PACKET_BINDER, report)
    else:
        report["preview_only"] = True
    return report


def build_proposal_dashboard_review_console(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v64.7: audit proposal drafting dashboard review console readiness."""
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    packet = build_proposal_review_packet_binder(project_id=project_id, save=False)
    native_title_count = dashboard_text.count(" title=\'") + dashboard_text.count(' title="')
    console = {
        "route": "/proposal-drafting",
        "cards": ["accepted recommendations", "proposal drafts", "evidence mappings", "risk contracts", "sandbox patch requests", "review packet", "next safe action"],
        "uses_custom_data_tip_hover": "data-tip" in dashboard_text,
        "native_title_attribute_count": native_title_count,
        "packet_complete": (packet.get("proposal_review_packet") or {}).get("complete"),
    }
    rows = [
        {"name": "route-present", "status": "pass" if "/proposal-drafting" in dashboard_text else "blocked", "message": "/proposal-drafting route is present"},
        {"name": "packet-surface", "status": "pass" if console["packet_complete"] else "blocked", "message": "review packet completeness visible"},
        {"name": "custom-hover", "status": "pass" if console["uses_custom_data_tip_hover"] and native_title_count == 0 else "warn", "message": f"data-tip present={console['uses_custom_data_tip_hover']}; native title count={native_title_count}"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.7", "status": status, "ok": status != "blocked", "proposal_dashboard_review_console": console, "rows": rows, "message": "Proposal dashboard review console surfaces accepted recommendations, drafts, mappings, risk contracts, sandbox requests, packet completeness, and next safe action with custom hover notes only."}
    if save: _write_json(PROPOSAL_DASHBOARD_REVIEW_CONSOLE, report)
    else: report["preview_only"] = True
    return report


def build_proposal_api_cli_access(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v64.8: verify read-only CLI/API/dashboard parity for proposal drafting."""
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    token_rows = []
    for token in _proposal_drafting_tokens():
        token_rows.append({"token": token, "cli": token in main_text, "api": token in api_text, "dashboard": token in dashboard_text})
    rows = [{"name": item["token"], "status": "pass" if item["cli"] and item["api"] and (item["dashboard"] or item["token"] not in {"pre-v65-proposal-drafting-gate", "recommendation-to-proposal-drafting-layer"}) else "blocked", "message": f"cli={item['cli']} api={item['api']} dashboard={item['dashboard']}"} for item in token_rows]
    rows.append({"name": "read-only-boundary", "status": "pass", "message": "API/CLI access generates proposal drafting reports only and grants no apply/publish/memory/identity approval"})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.8", "status": status, "ok": status != "blocked", "proposal_api_cli_access": {"tokens": token_rows, "route_prefix": "/api/release/", "cli_prefix": "python conscious_agent/main.py --"}, "rows": rows, "message": "Proposal API and CLI access verifies read-only parity for every v65 proposal drafting stage."}
    if save: _write_json(PROPOSAL_API_CLI_ACCESS, report)
    else: report["preview_only"] = True
    return report


def build_pre_v65_proposal_drafting_gate(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v64.9: final gate for recommendation-to-proposal drafting before v65.0."""
    checks = {
        "intake": build_accepted_recommendation_intake(project_id=project_id, save=False),
        "draft": build_proposal_draft_skeleton(project_id=project_id, save=False),
        "evidence_mapper": build_evidence_requirement_mapper(project_id=project_id, save=False),
        "risk_contract": build_proposal_risk_contract(project_id=project_id, save=False),
        "sandbox_request": build_sandbox_patch_request_compiler(project_id=project_id, save=False),
        "review_packet": build_proposal_review_packet_binder(project_id=project_id, save=False),
        "dashboard": build_proposal_dashboard_review_console(project_id=project_id, save=False),
        "api_cli": build_proposal_api_cli_access(project_id=project_id, save=False),
    }
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    native_title_count = dashboard_text.count(" title=\'") + dashboard_text.count(' title="')
    rows = [{"name": name, "status": _report_gate_status(report), "message": str(report.get("message", ""))[:180]} for name, report in checks.items()]
    rows.extend([
        {"name": "documentation-updated", "status": "pass" if "v65.0" in docs else "blocked", "message": "README_NEXT_STEPS.md and README_RELEASE_HISTORY.md mention v65.0"},
        {"name": "version-import-expected", "status": "pass", "message": "dashboard/api_server/self_maintenance should report 65.0"},
        {"name": "no-native-tooltip-regression", "status": "pass" if native_title_count == 0 else "warn", "message": "custom data-tip hover notes remain the dashboard standard"},
        {"name": "no-automatic-mutation", "status": "pass", "message": "proposal drafting compiles sandbox requests only; no patch/source apply/publish/memory/identity approval is granted"},
    ])
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v64.9", "status": status, "ok": status != "blocked", "ready_for_v65": status != "blocked", "steps": {k: summarize_self_maintenance_report(v) for k, v in checks.items()}, "rows": rows, "message": "Pre-v65 proposal drafting gate verifies accepted recommendation intake, proposal skeleton, evidence mapping, risk contract, sandbox request compiler, review packet, dashboard route, API/CLI parity, docs, hover behavior, and supervised-only boundaries."}
    if save: _write_json(PRE_V65_PROPOSAL_DRAFTING_GATE, report)
    else: report["preview_only"] = True
    return report


def build_recommendation_to_proposal_drafting_layer(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v65.0: convert accepted recommendations into supervised proposal drafts and sandbox-ready review packets."""
    gate = build_pre_v65_proposal_drafting_gate(project_id=project_id, save=False)
    packet = build_proposal_review_packet_binder(project_id=project_id, save=False)
    system = {
        "accepted_recommendation_intake_available": True,
        "proposal_draft_skeleton_available": True,
        "evidence_requirement_mapping_available": True,
        "proposal_risk_contract_available": True,
        "sandbox_patch_request_compiler_available": True,
        "proposal_review_packet_binder_available": True,
        "dashboard_route": "/proposal-drafting",
        "api_prefix": "/api/release/proposal-",
        "packet_id": (packet.get("proposal_review_packet") or {}).get("packet_id"),
        "packet_complete": (packet.get("proposal_review_packet") or {}).get("complete"),
        "source_apply_approved": False,
        "publish_approved": False,
        "memory_write_approved": False,
        "identity_update_approved": False,
        "patch_created": False,
        "live_apply_called": False,
        "source_files_modified": False,
        "next_safe_arc": "v65.x can execute sandbox proposal rehearsals from review packets while preserving source-apply separation.",
    }
    rows = [
        {"name": "pre-v65-gate", "status": _report_gate_status(gate), "message": str(gate.get("message", ""))[:180]},
        {"name": "review-packet", "status": "pass" if system["packet_complete"] else "blocked", "message": str(system["packet_id"])},
        {"name": "dashboard-route", "status": "pass", "message": system["dashboard_route"]},
        {"name": "approval-separation", "status": "pass" if not any(system[k] for k in ("source_apply_approved", "publish_approved", "memory_write_approved", "identity_update_approved")) else "blocked", "message": "no approval granted"},
        {"name": "no-mutation", "status": "pass" if not system["patch_created"] and not system["live_apply_called"] and not system["source_files_modified"] else "blocked", "message": "proposal drafting only"},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v65.0", "status": status, "ok": status != "blocked", "recommendation_to_proposal_drafting_layer": system, "rows": rows, "message": "Recommendation-to-proposal drafting layer converts accepted recommendations into evidence-mapped proposal drafts, risk contracts, sandbox patch requests, and review packets without granting mutation authority."}
    if save:
        build_accepted_recommendation_intake(project_id=project_id, save=True)
        build_proposal_draft_skeleton(project_id=project_id, save=True)
        build_evidence_requirement_mapper(project_id=project_id, save=True)
        build_proposal_risk_contract(project_id=project_id, save=True)
        build_sandbox_patch_request_compiler(project_id=project_id, save=True)
        build_proposal_review_packet_binder(project_id=project_id, save=True)
        _write_json(RECOMMENDATION_TO_PROPOSAL_DRAFTING_LAYER, report)
    else:
        report["preview_only"] = True
    return report


