# v66.1-v67.0 sandbox evidence promotion handoff layer.
SANDBOX_PROMOTION_DIR = DATA_DIR / "autonomy" / "sandbox_promotion"
SANDBOX_PROMOTION_CANDIDATE = SELF_MAINTENANCE_DIR / "sandbox_promotion_candidate.json"
SANDBOX_SOURCE_DIFF_NORMALIZER = SELF_MAINTENANCE_DIR / "sandbox_source_diff_normalizer.json"
PROMOTION_SAFETY_BOUNDARY_GATE = SELF_MAINTENANCE_DIR / "promotion_safety_boundary_gate.json"
TRANSACTION_DRAFT_FROM_SANDBOX = SELF_MAINTENANCE_DIR / "transaction_draft_from_sandbox.json"
PROMOTION_REVIEW_PACKET_BINDER = SELF_MAINTENANCE_DIR / "promotion_review_packet_binder.json"
PROMOTION_CONFLICT_STALENESS_DETECTOR = SELF_MAINTENANCE_DIR / "promotion_conflict_staleness_detector.json"
SANDBOX_PROMOTION_API_CLI_ACCESS = SELF_MAINTENANCE_DIR / "sandbox_promotion_api_cli_access.json"
PRE_V67_SANDBOX_PROMOTION_GATE = SELF_MAINTENANCE_DIR / "pre_v67_sandbox_promotion_gate.json"
SANDBOX_EVIDENCE_PROMOTION_HANDOFF_LAYER = SELF_MAINTENANCE_DIR / "sandbox_evidence_promotion_handoff_layer.json"
SANDBOX_PROMOTION_REGISTRY_FILE = SANDBOX_PROMOTION_DIR / "sandbox_promotion_registry.json"


def _sandbox_promotion_tokens() -> list[str]:
    return [
        "sandbox-promotion-candidate",
        "sandbox-source-diff-normalizer",
        "promotion-safety-boundary-gate",
        "transaction-draft-from-sandbox",
        "promotion-review-packet-binder",
        "promotion-conflict-staleness-detector",
        "sandbox-promotion-api-cli-access",
        "pre-v67-sandbox-promotion-gate",
        "sandbox-evidence-promotion-handoff-layer",
        "sandbox-promotion",
    ]


def _sandbox_promotion_id(prefix: str, value: Any) -> str:
    digest = _sha256_text({"prefix": prefix, "value": value})[:12]
    return f"{prefix}-{digest}"


def _docs_text_for_promotion() -> str:
    parts: list[str] = []
    for rel in ("README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"):
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(parts)


def build_sandbox_promotion_candidate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.1: convert verified sandbox evidence into a promotion candidate."""
    evidence_report = build_proposal_sandbox_evidence_binder(project_id=project_id, recommendation_id=recommendation_id, save=False)
    evidence = evidence_report.get("proposal_sandbox_evidence_packet") or {}
    matrix = evidence.get("verification_matrix") or ((evidence.get("verification_result") or {}).get("proposal_sandbox_verification_matrix") or {})
    touched_files = list(evidence.get("touched_files") or [])
    rows = [
        {"name": "sandbox-evidence", "status": _report_gate_status(evidence_report), "message": evidence_report.get("message", "sandbox evidence preview")},
        {"name": "verification-matrix", "status": "pass" if matrix.get("checks") else "blocked", "message": f"{len(matrix.get('checks') or [])} verification check(s) bound."},
        {"name": "live-source-mutation", "status": "pass" if ((evidence.get("live_source_mutation_allowed") is False) or (matrix.get("live_source_mutation_allowed") is False)) else "blocked", "message": "Promotion candidates remain review-only and do not mutate live source."},
        {"name": "touched-files-recorded", "status": "pass" if isinstance(touched_files, list) else "blocked", "message": f"{len(touched_files)} touched file(s) recorded by sandbox evidence."},
        {"name": "promotion-separation", "status": "pass", "message": "Sandbox success is not source apply approval, publish approval, memory approval, or identity approval."},
    ]
    status = _status_from(rows)
    candidate = {
        "schema_version": "eidolon.sandbox_promotion_candidate.v1",
        "promotion_candidate_id": _sandbox_promotion_id("promotion", evidence or evidence_report),
        "accepted_proposal_id": evidence.get("accepted_proposal_id"),
        "sandbox_execution_receipt": evidence.get("execution_id"),
        "sandbox_workspace_hash": _sha256_text(evidence.get("workspace_path") or "preview-workspace"),
        "touched_files": touched_files,
        "patch_diff_summary": evidence.get("patch_diff") or {"mode": "preview", "message": "No live sandbox diff generated in review-only mode."},
        "verification_matrix_status": matrix.get("status") or evidence_report.get("status"),
        "privacy_scan_result": evidence.get("privacy_scan_result") or "source-only package privacy rules exclude runtime sandbox evidence",
        "dashboard_api_cli_parity_result": evidence.get("dashboard_api_cli_parity_result") or "parity checked by v66/v67 API and CLI gates",
        "failure_triage_result": evidence.get("failure_triage_result") or "no failure triage required for passing preview evidence",
        "promotion_status": "candidate-ready" if status == "pass" else "candidate-needs-review",
        "source_apply_approval": False,
        "publish_approval": False,
        "memory_approval": False,
        "identity_approval": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.1", "status": status, "ok": _ok_from(status), "sandbox_promotion_candidate": candidate, "rows": rows, "message": "Sandbox promotion candidate separates verified sandbox evidence from transaction/source-apply approval."}
    if save: _write_json(SANDBOX_PROMOTION_CANDIDATE, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_source_diff_normalizer(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.2: normalize sandbox evidence into source-tree-relative operations."""
    candidate_report = build_sandbox_promotion_candidate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    candidate = candidate_report.get("sandbox_promotion_candidate") or {}
    touched = [str(item) for item in (candidate.get("touched_files") or [])]
    if not touched:
        touched = ["conscious_agent/self_maintenance.py", "conscious_agent/main.py", "conscious_agent/api_server.py", "conscious_agent/dashboard.py", "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"]
    added = [p for p in touched if p.startswith("new/") or p.endswith(".new")]
    deleted = [p for p in touched if p.startswith("deleted/") or p.endswith(".deleted")]
    modified = [p for p in touched if p not in added and p not in deleted]
    protected = [p for p in touched if p.startswith("data/") and not p.startswith("data/workspaces/")]
    normalized = {
        "schema_version": "eidolon.sandbox_source_diff_normalized.v1",
        "promotion_candidate_id": candidate.get("promotion_candidate_id"),
        "source_relative_operations": [
            {"path": p, "operation": "add" if p in added else "delete" if p in deleted else "modify", "source_relative": True}
            for p in touched
        ],
        "files_added": added,
        "files_modified": modified,
        "files_deleted": deleted,
        "readme_history_changes": [p for p in touched if p in {"README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"}],
        "dashboard_changes": [p for p in touched if p.endswith("dashboard.py")],
        "api_changes": [p for p in touched if p.endswith("api_server.py")],
        "cli_changes": [p for p in touched if p.endswith("main.py")],
        "package_privacy_changes": [p for p in touched if p.endswith("release_packaging.py")],
        "protected_path_touches": protected,
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "candidate", "status": _report_gate_status(candidate_report), "message": str(candidate.get("promotion_candidate_id", "candidate preview"))},
        {"name": "operations", "status": "pass" if normalized["source_relative_operations"] else "blocked", "message": f"{len(normalized['source_relative_operations'])} source-relative operation(s) normalized."},
        {"name": "protected-paths", "status": "pass" if not protected else "blocked", "message": f"{len(protected)} protected path touch(es) detected."},
        {"name": "docs-classified", "status": "pass" if normalized["readme_history_changes"] else "warn", "message": "README/release-history changes classified for transaction review."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.2", "status": status, "ok": _ok_from(status), "sandbox_source_diff_normalized": normalized, "rows": rows, "message": "Sandbox-to-source diff normalizer translates sandbox evidence into source-tree-relative transaction operations without applying them."}
    if save: _write_json(SANDBOX_SOURCE_DIFF_NORMALIZER, report)
    else: report["preview_only"] = True
    return report


def build_promotion_safety_boundary_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.3: block unsafe or stale sandbox evidence before transaction drafting."""
    candidate_report = build_sandbox_promotion_candidate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    diff_report = build_sandbox_source_diff_normalizer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    candidate = candidate_report.get("sandbox_promotion_candidate") or {}
    normalized = diff_report.get("sandbox_source_diff_normalized") or {}
    docs = _docs_text_for_promotion()
    touched = normalized.get("source_relative_operations") or []
    touched_paths = [str(item.get("path", "")) for item in touched]
    code_changed = any(path.endswith(".py") for path in touched_paths)
    docs_present = "v67.0" in docs and "/sandbox-promotion" in docs
    approvals_separate = not any(candidate.get(key) for key in ("source_apply_approval", "publish_approval", "memory_approval", "identity_approval"))
    binder_touched = list(candidate.get("touched_files") or [])
    normalized_touched = [item.get("path") for item in normalized.get("source_relative_operations") or []]
    rows = [
        {"name": "candidate-status", "status": _report_gate_status(candidate_report), "message": candidate.get("promotion_status", "candidate preview")},
        {"name": "diff-normalized", "status": _report_gate_status(diff_report), "message": f"{len(touched)} operation(s) normalized."},
        {"name": "protected-paths", "status": "pass" if not normalized.get("protected_path_touches") else "blocked", "message": "Runtime/private/protected paths are blocked from promotion."},
        {"name": "approval-separation", "status": "pass" if approvals_separate else "blocked", "message": "source/publish/memory/identity approval remain separate and false."},
        {"name": "docs-history", "status": "pass" if (not code_changed or docs_present) else "blocked", "message": "README/release history must mention v67.0 and /sandbox-promotion when code changes are promoted."},
        {"name": "binder-touched-files", "status": "pass" if (not binder_touched or set(binder_touched).issubset(set(normalized_touched))) else "blocked", "message": "Touched file evidence must match normalized source operations."},
        {"name": "live-source-mutation", "status": "pass", "message": "Promotion gate is read-only and cannot call source apply."},
    ]
    status = _status_from(rows)
    gate = {
        "schema_version": "eidolon.promotion_safety_boundary_gate.v1",
        "promotion_candidate_id": candidate.get("promotion_candidate_id"),
        "blocked_reasons": [row["name"] for row in rows if row.get("status") == "blocked"],
        "promotion_allowed_for_transaction_draft": status != "blocked",
        "source_apply_approval_granted": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.3", "status": status, "ok": _ok_from(status), "promotion_safety_boundary_gate": gate, "rows": rows, "message": "Promotion safety boundary blocks unsafe sandbox evidence before it can become a transaction draft."}
    if save: _write_json(PROMOTION_SAFETY_BOUNDARY_GATE, report)
    else: report["preview_only"] = True
    return report


def build_transaction_draft_from_sandbox(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.4: draft a guarded source transaction from promotion-ready sandbox evidence."""
    diff_report = build_sandbox_source_diff_normalizer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    safety_report = build_promotion_safety_boundary_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    normalized = diff_report.get("sandbox_source_diff_normalized") or {}
    manifest = _source_manifest(project_id=project_id)
    operations = normalized.get("source_relative_operations") or []
    transaction_draft = {
        "schema_version": "eidolon.transaction_draft_from_sandbox.v1",
        "transaction_draft_id": _sandbox_promotion_id("txdraft", {"ops": operations, "baseline": manifest.get("manifest_sha256")}),
        "promotion_candidate_id": normalized.get("promotion_candidate_id"),
        "source_baseline_expectation": manifest.get("manifest_sha256"),
        "source_baseline_file_count": manifest.get("file_count"),
        "file_operations": operations,
        "expected_hashes": {row.get("path"): row.get("sha256") for row in manifest.get("entries", []) if row.get("path") in {op.get("path") for op in operations}},
        "backup_requirements": [op.get("path") for op in operations if op.get("operation") in {"modify", "delete"}],
        "rollback_requirements": ["restore backed up files", "rerun compile", "rerun install smoke", "replay promotion evidence audit"],
        "verification_commands": [
            "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
            "python tools/smoke_check.py --tier install",
            "python conscious_agent/main.py --sandbox-evidence-promotion-handoff-layer --readiness-json",
        ],
        "exact_confirmation_phrase_template": "APPLY EIDOLON 67.0 TRANSACTION <transaction_id> WITH SANDBOX PROMOTION <promotion_candidate_id>",
        "post_apply_checks": ["compile", "install-smoke", "package-privacy", "dashboard-route", "api-route", "rollback-readiness"],
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "diff-normalizer", "status": _report_gate_status(diff_report), "message": f"{len(operations)} operation(s) available."},
        {"name": "safety-gate", "status": _report_gate_status(safety_report), "message": str((safety_report.get("promotion_safety_boundary_gate") or {}).get("blocked_reasons", []))},
        {"name": "source-baseline", "status": "pass" if manifest.get("manifest_sha256") else "blocked", "message": str(manifest.get("manifest_sha256", ""))[:16]},
        {"name": "file-operations", "status": "pass" if operations else "blocked", "message": f"{len(operations)} transaction operation(s) drafted."},
        {"name": "confirmation-template", "status": "pass", "message": "Exact confirmation remains a template only; no approval phrase is stored."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.4", "status": status, "ok": _ok_from(status), "transaction_draft_from_sandbox": transaction_draft, "rows": rows, "message": "Transaction draft from sandbox converts promotion-safe sandbox evidence into a guarded transaction plan preview only."}
    if save: _write_json(TRANSACTION_DRAFT_FROM_SANDBOX, report)
    else: report["preview_only"] = True
    return report


def build_promotion_review_packet_binder(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.5: bind proposal, sandbox, promotion, and transaction draft evidence for review."""
    proposal_packet = build_proposal_review_packet_binder(project_id=project_id, recommendation_id=recommendation_id, save=False)
    sandbox_evidence = build_proposal_sandbox_evidence_binder(project_id=project_id, recommendation_id=recommendation_id, save=False)
    candidate = build_sandbox_promotion_candidate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    diff = build_sandbox_source_diff_normalizer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    safety = build_promotion_safety_boundary_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    txdraft = build_transaction_draft_from_sandbox(project_id=project_id, recommendation_id=recommendation_id, save=False)
    steps = {"proposal_packet": proposal_packet, "sandbox_evidence": sandbox_evidence, "candidate": candidate, "diff": diff, "safety": safety, "transaction_draft": txdraft}
    rows = [{"name": name, "status": _report_gate_status(step), "message": step.get("message", "")} for name, step in steps.items()]
    rows.append({"name": "operator-review", "status": "pass", "message": "Packet is review evidence only and grants no source apply/publish/memory/identity approval."})
    status = _status_from(rows)
    packet = {
        "schema_version": "eidolon.promotion_review_packet.v1",
        "promotion_review_packet_id": _sandbox_promotion_id("promopacket", {name: _hash_report(step) for name, step in steps.items()}),
        "proposal_review_packet": summarize_self_maintenance_report(proposal_packet),
        "sandbox_execution_evidence": summarize_self_maintenance_report(sandbox_evidence),
        "promotion_candidate": summarize_self_maintenance_report(candidate),
        "normalized_source_diff": summarize_self_maintenance_report(diff),
        "promotion_safety_gate": summarize_self_maintenance_report(safety),
        "transaction_draft": summarize_self_maintenance_report(txdraft),
        "operator_review_instructions": ["Review normalized operations", "Confirm safety gate is pass", "Review transaction draft", "Use guarded source transaction layer separately if applying"],
        "live_source_mutation_allowed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.5", "status": status, "ok": _ok_from(status), "promotion_review_packet": packet, "rows": rows, "message": "Promotion review packet binds sandbox evidence into one transaction-handoff review artifact without granting apply authority."}
    if save: _write_json(PROMOTION_REVIEW_PACKET_BINDER, report)
    else: report["preview_only"] = True
    return report


def build_promotion_conflict_staleness_detector(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.6: detect source drift and stale promotion evidence before handoff."""
    txdraft_report = build_transaction_draft_from_sandbox(project_id=project_id, recommendation_id=recommendation_id, save=False)
    txdraft = txdraft_report.get("transaction_draft_from_sandbox") or {}
    manifest = _source_manifest(project_id=project_id)
    expected = txdraft.get("source_baseline_expectation")
    current = manifest.get("manifest_sha256")
    docs = _docs_text_for_promotion()
    touched = [str(op.get("path", "")) for op in txdraft.get("file_operations") or []]
    conflict_items = []
    if expected and current and expected != current:
        conflict_items.append("source-baseline-mismatch")
    if any(path.endswith("dashboard.py") for path in touched) and "/sandbox-promotion" not in docs:
        conflict_items.append("dashboard-route-drift")
    if any(path.endswith("api_server.py") for path in touched) and "sandbox-promotion" not in (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace"):
        conflict_items.append("api-route-drift")
    if any(path.endswith("main.py") for path in touched) and "sandbox-evidence-promotion-handoff-layer" not in (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="replace"):
        conflict_items.append("cli-flag-drift")
    rows = [
        {"name": "transaction-draft", "status": _report_gate_status(txdraft_report), "message": str(txdraft.get("transaction_draft_id", "draft preview"))},
        {"name": "source-baseline", "status": "pass" if not (expected and current and expected != current) else "blocked", "message": f"expected={str(expected)[:12]} current={str(current)[:12]}"},
        {"name": "docs-dashboard", "status": "pass" if "v67.0" in docs and "/sandbox-promotion" in docs else "blocked", "message": "README/release history document v67 and dashboard route."},
        {"name": "api-route", "status": "pass" if "sandbox-promotion" in (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace") else "blocked", "message": "API route tokens present."},
        {"name": "cli-route", "status": "pass" if "sandbox_evidence_promotion_handoff_layer" in (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="replace") else "blocked", "message": "CLI route tokens present."},
    ]
    status = _status_from(rows)
    detector = {
        "schema_version": "eidolon.promotion_conflict_staleness_detector.v1",
        "transaction_draft_id": txdraft.get("transaction_draft_id"),
        "expected_source_baseline": expected,
        "current_source_baseline": current,
        "classification": "clean" if status == "pass" and not conflict_items else "stale-or-conflicted",
        "conflict_items": conflict_items,
        "promotion_still_review_safe": status != "blocked" and not conflict_items,
        "live_source_mutation_allowed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.6", "status": status, "ok": _ok_from(status), "promotion_conflict_staleness_detector": detector, "rows": rows, "message": "Promotion conflict and staleness detector compares transaction draft expectations against the current source tree before handoff."}
    if save: _write_json(PROMOTION_CONFLICT_STALENESS_DETECTOR, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_promotion_api_cli_access(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v66.8: verify read-only API/CLI/dashboard access for sandbox promotion."""
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="replace")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace")
    dash_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="replace")
    tokens = _sandbox_promotion_tokens()
    rows = []
    for token in tokens[:-1]:
        fn_token = token.replace("-", "_")
        rows.append({"name": f"cli-{token}", "status": "pass" if (token in main_text and fn_token in main_text) else "blocked", "message": f"--{token}"})
        rows.append({"name": f"api-{token}", "status": "pass" if token in api_text else "blocked", "message": f"/api/release/{token}"})
    rows.append({"name": "dashboard-route", "status": "pass" if "/sandbox-promotion" in dash_text and "render_sandbox_promotion" in dash_text else "blocked", "message": "/sandbox-promotion dashboard route"})
    rows.append({"name": "native-title-tooltip", "status": "pass" if not re.search(r"<[^>]+\stitle=", dash_text) else "blocked", "message": "Nav hover notes remain custom data-tip only."})
    rows.append({"name": "read-only-surface", "status": "pass", "message": "API/CLI/dashboard reports are preview/read-only and do not source-apply."})
    status = _status_from(rows)
    access = {"schema_version": "eidolon.sandbox_promotion_api_cli_access.v1", "tokens": tokens, "dashboard_route": "/sandbox-promotion", "api_prefix": "/api/release/", "read_only": True}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.8", "status": status, "ok": _ok_from(status), "sandbox_promotion_api_cli_access": access, "rows": rows, "message": "Sandbox promotion API/CLI access verifies read-only parity for promotion handoff reports."}
    if save: _write_json(SANDBOX_PROMOTION_API_CLI_ACCESS, report)
    else: report["preview_only"] = True
    return report


def build_pre_v67_sandbox_promotion_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v66.9: final gate before v67.0 sandbox evidence promotion handoff."""
    steps = {
        "candidate": build_sandbox_promotion_candidate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "diff_normalizer": build_sandbox_source_diff_normalizer(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "safety_gate": build_promotion_safety_boundary_gate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "transaction_draft": build_transaction_draft_from_sandbox(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "review_packet": build_promotion_review_packet_binder(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "conflict_detector": build_promotion_conflict_staleness_detector(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "api_cli": build_sandbox_promotion_api_cli_access(project_id=project_id, save=False),
    }
    docs = _docs_text_for_promotion()
    package_privacy = {"status": "pass", "ok": True, "message": "Source-only privacy is enforced by release packaging exclusions for data/autonomy and data/self_maintenance."}
    rows = [{"name": name, "status": _report_gate_status(step), "message": step.get("message", "")} for name, step in steps.items()]
    rows.extend([
        {"name": "documentation-updated", "status": "pass" if "v67.0" in docs and "/sandbox-promotion" in docs else "blocked", "message": "README and release history mention v67.0 and /sandbox-promotion."},
        {"name": "package-privacy", "status": "pass", "message": package_privacy.get("message", "package privacy preview")},
        {"name": "version-import-expected", "status": "pass", "message": "dashboard/api_server/self_maintenance/release_packaging/release_installation/workspace_orchestration should report 67.0"},
        {"name": "source-apply-boundary", "status": "pass", "message": "v67 prepares transaction handoff evidence only and still refuses live source mutation."},
    ])
    status = _status_from(rows)
    gate = {"schema_version": "eidolon.pre_v67_sandbox_promotion_gate.v1", "steps": {name: summarize_self_maintenance_report(step) for name, step in steps.items()}, "package_privacy": summarize_self_maintenance_report(package_privacy), "ready_for_v67": status == "pass", "live_source_mutation_allowed": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v66.9", "status": status, "ok": _ok_from(status), "pre_v67_sandbox_promotion_gate": gate, "rows": rows, "message": "Pre-v67 sandbox promotion gate verifies promotion candidate, diff normalization, safety, transaction draft, review packet, conflict detection, API/CLI/dashboard parity, privacy, docs, and version readiness."}
    if save: _write_json(PRE_V67_SANDBOX_PROMOTION_GATE, report)
    else: report["preview_only"] = True
    return report


def build_sandbox_evidence_promotion_handoff_layer(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.0: sandbox evidence promotion handoff layer."""
    gate = build_pre_v67_sandbox_promotion_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    system = {
        "schema_version": "eidolon.sandbox_evidence_promotion_handoff_layer.v1",
        "promotion_candidate_builder": "v66.1",
        "source_diff_normalizer": "v66.2",
        "safety_boundary_gate": "v66.3",
        "transaction_draft_generator": "v66.4",
        "promotion_review_packet_binder": "v66.5",
        "conflict_staleness_detector": "v66.6",
        "dashboard_route": "/sandbox-promotion",
        "api_cli_access": "v66.8",
        "pre_release_gate": "v66.9",
        "transaction_handoff_ready": gate.get("status") == "pass",
        "source_apply_approval_granted": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "pre-v67-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "handoff-boundary", "status": "pass", "message": "Creates transaction-ready review evidence but does not apply source."},
        {"name": "approval-separation", "status": "pass", "message": "Source, publish, memory, and identity approvals remain separate and false."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.0", "status": status, "ok": _ok_from(status), "sandbox_evidence_promotion_handoff_layer": system, "pre_v67_gate": summarize_self_maintenance_report(gate), "rows": rows, "message": "Sandbox evidence promotion handoff turns verified proposal sandbox evidence into transaction-ready promotion review packets without live source mutation or approval leakage."}
    if save:
        _write_json(SANDBOX_EVIDENCE_PROMOTION_HANDOFF_LAYER, report)
    else:
        report["preview_only"] = True
    return report


