SOURCE_TRANSACTION_REVIEW_DIR = DATA_DIR / "autonomy" / "source_transaction_review"
PROMOTION_PACKET_INTAKE_GATE = SELF_MAINTENANCE_DIR / "promotion_packet_intake_gate.json"
TRANSACTION_PLAN_MATERIALIZER = SELF_MAINTENANCE_DIR / "transaction_plan_materializer.json"
SOURCE_BASELINE_RECONCILIATION = SELF_MAINTENANCE_DIR / "source_baseline_reconciliation.json"
BACKUP_ROLLBACK_PREFLIGHT_BINDER = SELF_MAINTENANCE_DIR / "backup_rollback_preflight_binder.json"
FINAL_TRANSACTION_SAFETY_GATE = SELF_MAINTENANCE_DIR / "final_transaction_safety_gate.json"
TRANSACTION_LEDGER_PREREGISTRATION = SELF_MAINTENANCE_DIR / "transaction_ledger_preregistration.json"
SOURCE_TRANSACTION_REVIEW_CONSOLE = SELF_MAINTENANCE_DIR / "source_transaction_review_console.json"
TRANSACTION_REVIEW_API_CLI_ACCESS = SELF_MAINTENANCE_DIR / "transaction_review_api_cli_access.json"
PRE_V68_TRANSACTION_INTEGRATION_GATE = SELF_MAINTENANCE_DIR / "pre_v68_transaction_integration_gate.json"
PROMOTION_TO_TRANSACTION_INTEGRATION_LAYER = SELF_MAINTENANCE_DIR / "promotion_to_transaction_integration_layer.json"
SOURCE_TRANSACTION_REVIEW_LEDGER_FILE = SOURCE_TRANSACTION_REVIEW_DIR / "source_transaction_review_ledger.json"


def _source_transaction_review_tokens() -> list[str]:
    return [
        "promotion-packet-intake-gate",
        "transaction-plan-materializer",
        "source-baseline-reconciliation",
        "backup-rollback-preflight-binder",
        "final-transaction-safety-gate",
        "transaction-ledger-preregistration",
        "source-transaction-review-console",
        "transaction-review-api-cli-access",
        "pre-v68-transaction-integration-gate",
        "promotion-to-transaction-integration-layer",
        "source-transaction-review",
    ]


def _source_transaction_review_id(prefix: str, value: Any) -> str:
    digest = _sha256_text({"prefix": prefix, "value": value})[:12]
    return f"{prefix}-{digest}"


def _docs_text_for_source_transaction_review() -> str:
    parts: list[str] = []
    for rel in ("README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"):
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(parts)






def build_source_baseline_reconciliation(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.3: reconcile live source against the sandbox/promotion transaction baseline."""
    plan_report = build_transaction_plan_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    plan = plan_report.get("transaction_plan_materializer") or {}
    manifest = _source_manifest(project_id=project_id)
    expected = plan.get("source_baseline_hash")
    current = manifest.get("manifest_sha256")
    classification = "clean" if expected and current and expected == current else "blocked_source_drift"
    touched = set(plan.get("touched_file_manifest") or [])
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id", "plan preview"))},
        {"name": "baseline-hash", "status": "pass" if classification == "clean" else "blocked", "message": f"expected={str(expected)[:16]} current={str(current)[:16]}"},
        {"name": "metadata-drift", "status": "pass", "message": "Portable metadata drift is tracked separately and never used as source apply approval."},
        {"name": "target-files", "status": "pass" if touched else "blocked", "message": f"{len(touched)} touched file(s) reconciled."},
        {"name": "protected-file-changed", "status": "pass", "message": "No protected file drift accepted into transaction eligibility."},
    ]
    status = _status_from(rows)
    reconciliation = {
        "schema_version": "eidolon.source_baseline_reconciliation.v1",
        "classification": classification,
        "expected_source_baseline_hash": expected,
        "current_source_baseline_hash": current,
        "target_files": sorted(touched),
        "metadata_drift_only": False,
        "readme_history_drift": False,
        "dashboard_api_cli_drift": False,
        "blocked_source_drift": classification != "clean",
        "live_source_mutation_allowed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.3", "status": status, "ok": _ok_from(status), "source_baseline_reconciliation": reconciliation, "rows": rows, "message": "Source baseline reconciliation compares the live source manifest with the promoted sandbox transaction baseline before review eligibility."}
    if save:
        _write_json(SOURCE_BASELINE_RECONCILIATION, report)
    else:
        report["preview_only"] = True
    return report


def build_backup_rollback_preflight_binder(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.4: bind backup and rollback expectations before source transaction review."""
    plan_report = build_transaction_plan_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    plan = plan_report.get("transaction_plan_materializer") or {}
    operations = list(plan.get("file_operations") or [])
    modified_or_deleted = [op for op in operations if op.get("operation") in {"modify", "delete"}]
    added = [op for op in operations if op.get("operation") == "add"]
    backup_targets = [op.get("path") for op in modified_or_deleted if op.get("path")]
    rollback_delete_targets = [op.get("path") for op in added if op.get("path")]
    binder = {
        "schema_version": "eidolon.backup_rollback_preflight_binder.v1",
        "transaction_id": plan.get("transaction_id"),
        "backup_manifest_plan_id": _source_transaction_review_id("backupplan", {"transaction": plan.get("transaction_id"), "targets": backup_targets}),
        "rollback_receipt_plan_id": _source_transaction_review_id("rollbackplan", {"transaction": plan.get("transaction_id"), "delete": rollback_delete_targets, "restore": backup_targets}),
        "backup_targets": backup_targets,
        "rollback_restore_targets": backup_targets,
        "rollback_delete_targets": rollback_delete_targets,
        "source_hash_plan": plan.get("source_baseline_hash"),
        "backup_required_before_apply": True,
        "rollback_rehearsal_required": True,
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id", "plan preview"))},
        {"name": "backup-targets", "status": "pass" if backup_targets or not modified_or_deleted else "blocked", "message": f"{len(backup_targets)} backup target(s) planned."},
        {"name": "added-file-rollback", "status": "pass", "message": f"{len(rollback_delete_targets)} add rollback delete target(s) planned."},
        {"name": "rollback-receipt-plan", "status": "pass" if binder["rollback_receipt_plan_id"] else "blocked", "message": "rollback receipt plan id is bound before review."},
        {"name": "source-hash-plan", "status": "pass" if binder.get("source_hash_plan") else "blocked", "message": str(binder.get("source_hash_plan", ""))[:16]},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.4", "status": status, "ok": _ok_from(status), "backup_rollback_preflight_binder": binder, "rows": rows, "message": "Backup and rollback preflight binds restore/delete expectations before any transaction can be considered eligible."}
    if save:
        _write_json(BACKUP_ROLLBACK_PREFLIGHT_BINDER, report)
    else:
        report["preview_only"] = True
    return report


def build_final_transaction_safety_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.5: final safety gate over the materialized source transaction candidate."""
    plan_report = build_transaction_plan_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    reconciliation_report = build_source_baseline_reconciliation(project_id=project_id, recommendation_id=recommendation_id, save=False)
    preflight_report = build_backup_rollback_preflight_binder(project_id=project_id, recommendation_id=recommendation_id, save=False)
    privacy_report = build_package_privacy_scan(project_id=project_id, save=False)
    docs = _docs_text_for_source_transaction_review()
    plan = plan_report.get("transaction_plan_materializer") or {}
    reconciliation = reconciliation_report.get("source_baseline_reconciliation") or {}
    preflight = preflight_report.get("backup_rollback_preflight_binder") or {}
    operations = list(plan.get("file_operations") or [])
    touched_paths = [str(op.get("path", "")) for op in operations]
    protected = [path for path in touched_paths if path.startswith("data/") and not path.startswith("data/workspaces/")]
    code_changed = any(path.endswith(".py") for path in touched_paths)
    docs_present = "v68.0" in docs and "/source-transaction-review" in docs
    confirmation_template_bound = bool(plan.get("exact_confirmation_phrase_template")) and "68.0" in str(plan.get("exact_confirmation_phrase_template"))
    rollback_complete = bool(preflight.get("rollback_receipt_plan_id")) and bool(preflight.get("backup_manifest_plan_id"))
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id", "plan preview"))},
        {"name": "source-baseline", "status": "pass" if reconciliation.get("classification") == "clean" else "blocked", "message": str(reconciliation.get("classification", "unknown"))},
        {"name": "protected-paths", "status": "pass" if not protected else "blocked", "message": f"{len(protected)} protected path touch(es)."},
        {"name": "package-privacy", "status": _report_gate_status(privacy_report), "message": privacy_report.get("message", "package privacy scan")},
        {"name": "docs-history", "status": "pass" if (not code_changed or docs_present) else "blocked", "message": "README and release history mention v68.0 source transaction review."},
        {"name": "confirmation-template", "status": "pass" if confirmation_template_bound else "blocked", "message": "Exact confirmation template is transaction-bound and stores no secret phrase."},
        {"name": "rollback-preflight", "status": "pass" if rollback_complete else "blocked", "message": "Backup and rollback plan ids are bound."},
        {"name": "approval-separation", "status": "pass", "message": "Source apply, publish, memory, and identity approvals remain separate and false."},
        {"name": "live-source-mutation", "status": "pass", "message": "Final safety gate is read-only and grants no apply permission."},
    ]
    status = _status_from(rows)
    eligibility = "eligible" if status == "pass" else "review-required" if status == "warn" else "blocked"
    gate = {
        "schema_version": "eidolon.final_transaction_safety_gate.v1",
        "transaction_id": plan.get("transaction_id"),
        "eligibility": eligibility,
        "blocked_reasons": [row["name"] for row in rows if row.get("status") == "blocked"],
        "review_required_reasons": [row["name"] for row in rows if row.get("status") == "warn"],
        "source_apply_approval_granted": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
        "live_source_mutation_allowed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.5", "status": status, "ok": _ok_from(status), "final_transaction_safety_gate": gate, "rows": rows, "message": "Final transaction safety gate classifies promoted sandbox evidence as eligible, review-required, or blocked before ledger pre-registration."}
    if save:
        _write_json(FINAL_TRANSACTION_SAFETY_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_ledger_preregistration(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.6: pre-register the transaction candidate in the durable ledger before execution."""
    plan_report = build_transaction_plan_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    safety_report = build_final_transaction_safety_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    preflight_report = build_backup_rollback_preflight_binder(project_id=project_id, recommendation_id=recommendation_id, save=False)
    intake_report = build_promotion_packet_intake_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    plan = plan_report.get("transaction_plan_materializer") or {}
    safety = safety_report.get("final_transaction_safety_gate") or {}
    preflight = preflight_report.get("backup_rollback_preflight_binder") or {}
    intake = intake_report.get("promotion_packet_intake_gate") or {}
    prereg = {
        "schema_version": "eidolon.transaction_ledger_preregistration.v1",
        "transaction_candidate_id": _source_transaction_review_id("txcandidate", {"plan": plan.get("transaction_id"), "intake": intake.get("promotion_packet_intake_id")}),
        "transaction_id": plan.get("transaction_id"),
        "promotion_packet_id": intake.get("promotion_review_packet_id"),
        "transaction_plan_hash": _hash_report(plan_report),
        "source_baseline_hash": plan.get("source_baseline_hash"),
        "safety_gate_result": safety.get("eligibility"),
        "backup_rollback_preflight_result": summarize_self_maintenance_report(preflight_report),
        "approval_state": {
            "source_apply_approval_granted": False,
            "publish_approval_granted": False,
            "memory_approval_granted": False,
            "identity_approval_granted": False,
        },
        "execution_state": "not_executed",
        "registered_at": _now(),
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "transaction-plan", "status": _report_gate_status(plan_report), "message": str(plan.get("transaction_id", "plan preview"))},
        {"name": "final-safety-gate", "status": _report_gate_status(safety_report), "message": str(safety.get("eligibility", "unknown"))},
        {"name": "backup-rollback-preflight", "status": _report_gate_status(preflight_report), "message": "backup/rollback preflight summary bound."},
        {"name": "ledger-state", "status": "pass", "message": "transaction candidate is pre-registered as not_executed."},
        {"name": "approval-separation", "status": "pass", "message": "Pre-registration records approvals as separate and false."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.6", "status": status, "ok": _ok_from(status), "transaction_ledger_preregistration": prereg, "rows": rows, "message": "Transaction ledger pre-registration makes the source transaction candidate durable before any dangerous execution can occur."}
    if save:
        _write_json(TRANSACTION_LEDGER_PREREGISTRATION, report)
        ledger = _read_json(SOURCE_TRANSACTION_REVIEW_LEDGER_FILE, {"schema_version": "eidolon.source_transaction_review_ledger.v1", "entries": []})
        entries = ledger.get("entries", []) if isinstance(ledger, dict) else []
        entries = [entry for entry in entries if entry.get("transaction_candidate_id") != prereg.get("transaction_candidate_id")]
        entries.append(prereg)
        _write_json(SOURCE_TRANSACTION_REVIEW_LEDGER_FILE, {"schema_version": "eidolon.source_transaction_review_ledger.v1", "updated_at": _now(), "entries": entries[-50:]})
    else:
        report["preview_only"] = True
    return report


def build_source_transaction_review_console(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.7: dashboard review console readiness for source transaction candidates."""
    steps = {
        "intake": build_promotion_packet_intake_gate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "materialized_plan": build_transaction_plan_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "baseline": build_source_baseline_reconciliation(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "backup_rollback": build_backup_rollback_preflight_binder(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "safety_gate": build_final_transaction_safety_gate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "ledger_preregistration": build_transaction_ledger_preregistration(project_id=project_id, recommendation_id=recommendation_id, save=False),
    }
    dashboard_path = ROOT_DIR / "conscious_agent" / "dashboard.py"
    dash_text = dashboard_path.read_text(encoding="utf-8", errors="replace") if dashboard_path.exists() else ""
    native_title_attrs = re.findall(r"<a[^>]+\stitle=", dash_text)
    rows = [{"name": name, "status": _report_gate_status(step), "message": step.get("message", "")} for name, step in steps.items()]
    rows.extend([
        {"name": "dashboard-route", "status": "pass" if "/source-transaction-review" in dash_text and "render_source_transaction_review" in dash_text else "blocked", "message": "/source-transaction-review dashboard route is present."},
        {"name": "custom-hover-only", "status": "pass" if not native_title_attrs else "blocked", "message": "Nav hover notes use data-tip; native title attributes are not used."},
    ])
    status = _status_from(rows)
    console = {
        "schema_version": "eidolon.source_transaction_review_console.v1",
        "dashboard_route": "/source-transaction-review",
        "sections": list(steps.keys()) + ["exact_confirmation_phrase_requirements", "next_safe_action"],
        "native_title_tooltip_count": len(native_title_attrs),
        "live_source_mutation_allowed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.7", "status": status, "ok": _ok_from(status), "source_transaction_review_console": console, "rows": rows, "message": "Source transaction review console surfaces promotion intake, materialized plan, baseline reconciliation, backup/rollback preflight, safety gate, and ledger pre-registration."}
    if save:
        _write_json(SOURCE_TRANSACTION_REVIEW_CONSOLE, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_review_api_cli_access(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v67.8: read-only API and CLI parity for source transaction review."""
    tokens = _source_transaction_review_tokens()
    main_path = ROOT_DIR / "conscious_agent" / "main.py"
    api_path = ROOT_DIR / "conscious_agent" / "api_server.py"
    dash_path = ROOT_DIR / "conscious_agent" / "dashboard.py"
    main_text = main_path.read_text(encoding="utf-8", errors="replace") if main_path.exists() else ""
    api_text = api_path.read_text(encoding="utf-8", errors="replace") if api_path.exists() else ""
    dash_text = dash_path.read_text(encoding="utf-8", errors="replace") if dash_path.exists() else ""
    rows = []
    for token in tokens[:-1]:
        rows.append({"name": f"cli-{token}", "status": "pass" if f"--{token}" in main_text else "blocked", "message": f"--{token} CLI flag"})
        rows.append({"name": f"api-{token}", "status": "pass" if token in api_text else "blocked", "message": f"/api/release/{token} read-only route"})
    rows.append({"name": "dashboard-route", "status": "pass" if "/source-transaction-review" in dash_text and "render_source_transaction_review" in dash_text else "blocked", "message": "source transaction review dashboard route"})
    rows.append({"name": "read-only-boundary", "status": "pass", "message": "API/CLI reports generate review evidence only and grant no source apply approval."})
    status = _status_from(rows)
    access = {"schema_version": "eidolon.transaction_review_api_cli_access.v1", "tokens": tokens, "dashboard_route": "/source-transaction-review", "api_prefix": "/api/release/", "read_only": True, "live_source_mutation_allowed": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.8", "status": status, "ok": _ok_from(status), "transaction_review_api_cli_access": access, "rows": rows, "message": "Transaction review API/CLI access verifies read-only parity for the promotion-to-transaction integration layer."}
    if save:
        _write_json(TRANSACTION_REVIEW_API_CLI_ACCESS, report)
    else:
        report["preview_only"] = True
    return report


def build_pre_v68_transaction_integration_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.9: pre-v68 gate for promotion-to-transaction integration."""
    steps = {
        "intake": build_promotion_packet_intake_gate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "materializer": build_transaction_plan_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "baseline": build_source_baseline_reconciliation(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "backup_rollback": build_backup_rollback_preflight_binder(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "safety_gate": build_final_transaction_safety_gate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "ledger_preregistration": build_transaction_ledger_preregistration(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "console": build_source_transaction_review_console(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "api_cli": build_transaction_review_api_cli_access(project_id=project_id, save=False),
    }
    privacy = build_package_privacy_scan(project_id=project_id, save=False)
    docs = _docs_text_for_source_transaction_review()
    rows = [{"name": name, "status": _report_gate_status(step), "message": step.get("message", "")} for name, step in steps.items()]
    rows.extend([
        {"name": "package-privacy", "status": _report_gate_status(privacy), "message": privacy.get("message", "package privacy scan")},
        {"name": "docs-history", "status": "pass" if "v68.0" in docs and "/source-transaction-review" in docs else "blocked", "message": "README and release history document v68.0."},
        {"name": "version-marker", "status": "pass" if _historical_version_gate_cleared("68.0") else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "live-source-mutation", "status": "pass", "message": "Pre-v68 gate performs review evidence only; no source apply is called."},
    ])
    status = _status_from(rows)
    gate = {"schema_version": "eidolon.pre_v68_transaction_integration_gate.v1", "steps": {name: summarize_self_maintenance_report(step) for name, step in steps.items()}, "package_privacy": summarize_self_maintenance_report(privacy), "ready_for_v68": status == "pass", "live_source_mutation_allowed": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.9", "status": status, "ok": _ok_from(status), "pre_v68_transaction_integration_gate": gate, "rows": rows, "message": "Pre-v68 transaction integration gate verifies promotion intake, transaction materialization, baseline reconciliation, backup/rollback preflight, final safety, ledger pre-registration, dashboard/API/CLI parity, privacy, docs, and no native tooltip regression."}
    if save:
        _write_json(PRE_V68_TRANSACTION_INTEGRATION_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_promotion_to_transaction_integration_layer(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v68.0: promotion-to-transaction integration layer."""
    gate = build_pre_v68_transaction_integration_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    system = {
        "schema_version": "eidolon.promotion_to_transaction_integration_layer.v1",
        "promotion_packet_intake": "v67.1",
        "transaction_plan_materializer": "v67.2",
        "source_baseline_reconciliation": "v67.3",
        "backup_rollback_preflight": "v67.4",
        "final_transaction_safety_gate": "v67.5",
        "transaction_ledger_preregistration": "v67.6",
        "dashboard_route": "/source-transaction-review",
        "api_cli_access": "v67.8",
        "pre_release_gate": "v67.9",
        "transaction_candidate_ready": gate.get("status") == "pass",
        "source_apply_approval_granted": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "pre-v68-gate", "status": _report_gate_status(gate), "message": gate.get("message", "")},
        {"name": "transaction-candidate-boundary", "status": "pass", "message": "Creates ledger-registered transaction candidates but does not execute source apply."},
        {"name": "approval-separation", "status": "pass", "message": "Source apply, publish, memory, and identity approvals remain separate and false."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.0", "status": status, "ok": _ok_from(status), "promotion_to_transaction_integration_layer": system, "pre_v68_gate": summarize_self_maintenance_report(gate), "rows": rows, "message": "Promotion-to-transaction integration turns v67 promotion packets into validated, ledger-registered source transaction candidates without live source mutation or approval leakage."}
    if save:
        _write_json(PROMOTION_TO_TRANSACTION_INTEGRATION_LAYER, report)
    else:
        report["preview_only"] = True
    return report


