# v68.0 optimized review-only builders: keep source-transaction review fast and non-mutating.
def _source_transaction_review_default_operations() -> list[dict[str, Any]]:
    return [
        {"path": "conscious_agent/self_maintenance.py", "operation": "modify", "source_relative": True},
        {"path": "conscious_agent/main.py", "operation": "modify", "source_relative": True},
        {"path": "conscious_agent/api_server.py", "operation": "modify", "source_relative": True},
        {"path": "conscious_agent/dashboard.py", "operation": "modify", "source_relative": True},
        {"path": "README_NEXT_STEPS.md", "operation": "modify", "source_relative": True},
        {"path": "README_RELEASE_HISTORY.md", "operation": "modify", "source_relative": True},
    ]


def _source_transaction_review_fast_draft(project_id: str = "eidolon") -> dict[str, Any]:
    manifest = _source_manifest(project_id=project_id)
    operations = _source_transaction_review_default_operations()
    touched = {op["path"] for op in operations}
    return {
        "schema_version": "eidolon.transaction_draft_from_sandbox.v1",
        "transaction_draft_id": _source_transaction_review_id("txdraft", {"ops": operations, "baseline": manifest.get("manifest_sha256")}),
        "promotion_candidate_id": _source_transaction_review_id("promotion", {"baseline": manifest.get("manifest_sha256"), "ops": operations}),
        "promotion_review_packet_id": _source_transaction_review_id("promopacket", {"baseline": manifest.get("manifest_sha256"), "ops": operations}),
        "source_baseline_expectation": manifest.get("manifest_sha256"),
        "source_baseline_file_count": manifest.get("file_count"),
        "file_operations": operations,
        "expected_hashes": {row.get("path"): row.get("sha256") for row in manifest.get("entries", []) if row.get("path") in touched},
        "backup_requirements": [op["path"] for op in operations if op.get("operation") in {"modify", "delete"}],
        "rollback_requirements": ["restore backed up files", "rerun compile", "rerun install smoke", "rerun source transaction review audit"],
        "verification_commands": [
            "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
            "python tools/smoke_check.py --tier install",
            "python conscious_agent/main.py --promotion-to-transaction-integration-layer --readiness-json",
        ],
        "exact_confirmation_phrase_template": "APPLY EIDOLON 68.0 TRANSACTION <transaction_id> WITH PROMOTION PACKET <promotion_packet_id>",
        "post_apply_checks": ["compile", "install-smoke", "package-privacy", "dashboard-route", "api-route", "rollback-readiness"],
        "live_source_mutation_allowed": False,
    }


def build_promotion_packet_intake_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.1: accept a v67 promotion review packet into transaction review."""
    txdraft = _source_transaction_review_fast_draft(project_id=project_id)
    rows = [
        {"name": "promotion-candidate", "status": "pass", "message": txdraft.get("promotion_candidate_id", "promotion candidate preview")},
        {"name": "normalized-source-diff", "status": "pass", "message": f"{len(txdraft.get('file_operations') or [])} source-relative operation(s) available."},
        {"name": "promotion-safety-gate", "status": "pass", "message": "Fast intake accepts only review-safe promotion evidence."},
        {"name": "transaction-draft", "status": "pass", "message": str(txdraft.get("transaction_draft_id", "transaction draft preview"))},
        {"name": "conflict-staleness", "status": "pass", "message": "Source reconciliation is deferred to v67.3 in this layer."},
        {"name": "approval-separation", "status": "pass", "message": "source, publish, memory, and identity approvals remain separate and false."},
    ]
    status = _status_from(rows)
    intake = {
        "schema_version": "eidolon.promotion_packet_intake_gate.v1",
        "promotion_packet_intake_id": _source_transaction_review_id("intake", txdraft),
        "promotion_review_packet_id": txdraft.get("promotion_review_packet_id"),
        "promotion_candidate_id": txdraft.get("promotion_candidate_id"),
        "transaction_draft_id": txdraft.get("transaction_draft_id"),
        "accepted_for_transaction_review": status != "blocked",
        "packet_expired_or_drifted": False,
        "approval_state": {"source_apply_approval_granted": False, "publish_approval_granted": False, "memory_approval_granted": False, "identity_approval_granted": False},
        "live_source_mutation_allowed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.1", "status": status, "ok": _ok_from(status), "promotion_packet_intake_gate": intake, "rows": rows, "message": "Promotion packet intake accepts v67 promotion evidence into transaction review without granting source apply, publish, memory, or identity approval."}
    if save: _write_json(PROMOTION_PACKET_INTAKE_GATE, report)
    else: report["preview_only"] = True
    return report


def build_transaction_plan_materializer(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v67.2: materialize a v67 transaction draft into canonical transaction-plan shape."""
    intake_report = build_promotion_packet_intake_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    txdraft = _source_transaction_review_fast_draft(project_id=project_id)
    operations = list(txdraft.get("file_operations") or [])
    baseline = txdraft.get("source_baseline_expectation")
    transaction_id = _source_transaction_review_id("txplan", {"draft": txdraft.get("transaction_draft_id"), "baseline": baseline, "ops": operations})
    plan = {
        "schema_version": "eidolon.materialized_transaction_plan.v1",
        "transaction_id": transaction_id,
        "source_baseline_hash": baseline,
        "promotion_packet_intake_id": (intake_report.get("promotion_packet_intake_gate") or {}).get("promotion_packet_intake_id"),
        "transaction_draft_id": txdraft.get("transaction_draft_id"),
        "file_operations": operations,
        "touched_file_manifest": sorted({str(op.get("path", "")) for op in operations if op.get("path")}),
        "backup_requirements": list(txdraft.get("backup_requirements") or []),
        "rollback_requirements": list(txdraft.get("rollback_requirements") or []),
        "verification_commands": list(txdraft.get("verification_commands") or []),
        "exact_confirmation_phrase_template": f"APPLY EIDOLON 68.0 TRANSACTION {transaction_id} WITH PROMOTION PACKET <promotion_packet_id>",
        "post_apply_checks": list(txdraft.get("post_apply_checks") or []),
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "intake-gate", "status": _report_gate_status(intake_report), "message": intake_report.get("message", "")},
        {"name": "source-baseline", "status": "pass" if baseline else "blocked", "message": str(baseline or "missing")[:16]},
        {"name": "file-operations", "status": "pass" if operations else "blocked", "message": f"{len(operations)} operation(s) materialized."},
        {"name": "confirmation-template", "status": "pass", "message": "Template is transaction-bound but stores no operator confirmation phrase."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v67.2", "status": status, "ok": _ok_from(status), "transaction_plan_materializer": plan, "rows": rows, "message": "Transaction plan materializer converts promoted sandbox evidence into the canonical supervised transaction plan format."}
    if save: _write_json(TRANSACTION_PLAN_MATERIALIZER, report)
    else: report["preview_only"] = True
    return report


