def _transaction_execution_tokens() -> list[str]:
    return [
        "transaction-execution-eligibility", "exact-confirmation-binder", "backup-snapshot-materializer",
        "transaction-apply-rehearsal", "operator-confirmed-apply-executor", "post-execution-verification",
        "rollback-recommendation-gate", "transaction-execution", "operator-confirmed-transaction-execution-layer",
    ]


def _transaction_execution_id(prefix: str, value: Any) -> str:
    return f"{prefix}-{_sha256_text(value)[:16]}"


def _docs_text_for_transaction_execution() -> str:
    chunks: list[str] = []
    for rel in ("README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py"):
        path = ROOT_DIR / rel
        try:
            chunks.append(path.read_text(encoding="utf-8", errors="ignore"))
        except Exception:
            chunks.append("")
    return "\n".join(chunks)


def _transaction_execution_candidate(project_id: str = "eidolon") -> dict[str, Any]:
    prereg_report = build_transaction_ledger_preregistration(project_id=project_id, save=False)
    prereg = prereg_report.get("transaction_ledger_preregistration") or {}
    plan_report = build_transaction_plan_materializer(project_id=project_id, save=False)
    plan = plan_report.get("transaction_plan_materializer") or {}
    baseline_report = build_source_baseline_reconciliation(project_id=project_id, save=False)
    preflight_report = build_backup_rollback_preflight_binder(project_id=project_id, save=False)
    safety_report = build_final_transaction_safety_gate(project_id=project_id, save=False)
    candidate_id = prereg.get("transaction_candidate_id") or _transaction_execution_id("txcandidate", plan)
    plan_hash = prereg.get("transaction_plan_hash") or _sha256_text(plan)
    baseline_hash = prereg.get("source_baseline_hash") or plan.get("source_baseline_hash") or (_source_manifest(project_id=project_id).get("manifest_sha256"))
    preflight_hash = _sha256_text(preflight_report.get("backup_rollback_preflight_binder") or preflight_report)
    return {
        "candidate_id": candidate_id,
        "transaction_id": prereg.get("transaction_id") or plan.get("transaction_id"),
        "promotion_packet_id": prereg.get("promotion_packet_id") or (plan.get("promotion_packet_intake_id")),
        "plan": plan,
        "plan_hash": plan_hash,
        "source_baseline_hash": baseline_hash,
        "baseline_status": (baseline_report.get("source_baseline_reconciliation") or {}).get("classification", "unknown"),
        "backup_rollback_preflight_hash": preflight_hash,
        "backup_rollback_preflight_status": _report_gate_status(preflight_report),
        "final_safety_gate_status": _report_gate_status(safety_report),
        "ledger_status": _report_gate_status(prereg_report),
        "ledger_entry": prereg,
        "file_operations": list(plan.get("file_operations") or []),
        "touched_file_manifest": list(plan.get("touched_file_manifest") or []),
        "verification_commands": list(plan.get("verification_commands") or []),
        "approval_state": prereg.get("approval_state") or {"source_apply_approval_granted": False, "publish_approval_granted": False, "memory_approval_granted": False, "identity_approval_granted": False},
    }


def build_transaction_execution_eligibility(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v68.1: determine whether a ledger-registered transaction candidate is eligible for supervised execution review."""
    candidate = _transaction_execution_candidate(project_id=project_id)
    approvals = candidate.get("approval_state") or {}
    separated = not any(bool(approvals.get(key)) for key in ("publish_approval_granted", "memory_approval_granted", "identity_approval_granted"))
    rows = [
        {"name": "ledger-candidate", "status": "pass" if candidate.get("candidate_id") else "blocked", "message": str(candidate.get("candidate_id", "missing"))},
        {"name": "transaction-plan", "status": "pass" if candidate.get("plan_hash") and candidate.get("file_operations") else "blocked", "message": f"{len(candidate.get('file_operations') or [])} planned operation(s)."},
        {"name": "source-baseline", "status": "pass" if candidate.get("baseline_status") == "clean" else "blocked", "message": str(candidate.get("baseline_status", "unknown"))},
        {"name": "final-safety-gate", "status": "pass" if candidate.get("final_safety_gate_status") == "pass" else "blocked", "message": str(candidate.get("final_safety_gate_status"))},
        {"name": "backup-rollback-preflight", "status": "pass" if candidate.get("backup_rollback_preflight_status") == "pass" else "blocked", "message": str(candidate.get("backup_rollback_preflight_status"))},
        {"name": "exact-confirmation-template", "status": "pass" if candidate.get("plan", {}).get("exact_confirmation_phrase_template") else "blocked", "message": "template exists; no operator phrase stored."},
        {"name": "approval-separation", "status": "pass" if separated else "blocked", "message": "source, publish, memory, and identity approvals remain separate."},
    ]
    status = _status_from(rows)
    eligibility = {
        "schema_version": "eidolon.transaction_execution_eligibility.v1",
        "transaction_candidate_id": candidate.get("candidate_id"),
        "transaction_plan_hash": candidate.get("plan_hash"),
        "source_baseline_hash": candidate.get("source_baseline_hash"),
        "backup_rollback_preflight_hash": candidate.get("backup_rollback_preflight_hash"),
        "eligible_for_operator_confirmation": status == "pass",
        "execution_state": "not_executed",
        "live_source_mutation_allowed": False,
        "approval_state": approvals,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.1", "status": status, "ok": _ok_from(status), "transaction_execution_eligibility": eligibility, "rows": rows, "message": "Transaction execution eligibility resolves whether a ledger-registered transaction candidate may advance to exact operator confirmation review."}
    if save:
        _write_json(TRANSACTION_EXECUTION_ELIGIBILITY, report)
    else:
        report["preview_only"] = True
    return report


def build_exact_confirmation_binder(project_id: str = "eidolon", confirmation_phrase: str = "", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v68.2: bind an exact confirmation phrase to one transaction candidate without storing the phrase itself."""
    eligibility_report = build_transaction_execution_eligibility(project_id=project_id, recommendation_id=recommendation_id, save=False)
    eligibility = eligibility_report.get("transaction_execution_eligibility") or {}
    candidate_id = eligibility.get("transaction_candidate_id")
    plan_hash = eligibility.get("transaction_plan_hash")
    baseline_hash = eligibility.get("source_baseline_hash")
    rollback_hash = eligibility.get("backup_rollback_preflight_hash")
    required = f"EXECUTE EIDOLON 70.0 TRANSACTION {candidate_id} WITH PLAN {str(plan_hash)[:16]} BASELINE {str(baseline_hash)[:16]} ROLLBACK {str(rollback_hash)[:16]}"
    supplied = bool(confirmation_phrase)
    matched = supplied and confirmation_phrase.strip() == required
    rows = [
        {"name": "eligibility", "status": _report_gate_status(eligibility_report), "message": str(candidate_id or "missing candidate")},
        {"name": "candidate-binding", "status": "pass" if candidate_id and plan_hash and baseline_hash and rollback_hash else "blocked", "message": "candidate, plan, baseline, and rollback hashes are bound."},
        {"name": "phrase-supplied", "status": "pass" if supplied else "warn", "message": "Exact phrase supplied." if supplied else "No operator phrase supplied; executor must refuse live apply."},
        {"name": "phrase-match", "status": "pass" if matched else ("warn" if not supplied else "blocked"), "message": "Exact phrase matches candidate." if matched else "Phrase is absent or does not match this transaction."},
        {"name": "phrase-storage", "status": "pass", "message": "Only phrase hash and template metadata are recorded; raw phrase is not stored."},
    ]
    status = _status_from(rows)
    binder = {
        "schema_version": "eidolon.exact_confirmation_binder.v1",
        "transaction_candidate_id": candidate_id,
        "required_confirmation_template": "EXECUTE EIDOLON 70.0 TRANSACTION <candidate_id> WITH PLAN <plan_hash16> BASELINE <baseline_hash16> ROLLBACK <rollback_hash16>",
        "required_confirmation_preview": required,
        "confirmation_phrase_supplied": supplied,
        "confirmation_phrase_matches": matched,
        "confirmation_phrase_hash": _sha256_text(confirmation_phrase.strip()) if supplied else None,
        "raw_confirmation_phrase_stored": False,
        "live_source_mutation_allowed": False,
    }
    # In preview/no-phrase mode this remains ok because the safety behavior is refusal, not execution.
    report_status = "pass" if _report_gate_status(eligibility_report) == "pass" and (matched or not supplied) else status
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.2", "status": report_status, "ok": report_status != "blocked", "exact_confirmation_binder": binder, "rows": rows, "message": "Exact confirmation binder ties one operator phrase to one transaction candidate and deliberately stores no raw confirmation phrase."}
    if save:
        _write_json(EXACT_CONFIRMATION_BINDER, report)
    else:
        report["preview_only"] = True
    return report


def build_backup_snapshot_materializer(project_id: str = "eidolon", recommendation_id: str | None = None, materialize_files: bool = False, save: bool = True) -> dict[str, Any]:
    """v68.3: prepare a backup snapshot receipt before any real transaction execution."""
    candidate = _transaction_execution_candidate(project_id=project_id)
    snapshot_id = _transaction_execution_id("backup", {"candidate": candidate.get("candidate_id"), "baseline": candidate.get("source_baseline_hash"), "files": candidate.get("touched_file_manifest")})
    manifest = _source_manifest(project_id=project_id)
    touched = set(candidate.get("touched_file_manifest") or [])
    file_hashes = {row.get("path"): row.get("sha256") for row in manifest.get("entries", []) if row.get("path") in touched}
    snapshot_dir = TRANSACTION_EXECUTION_DIR / "backups" / snapshot_id
    if materialize_files and touched:
        snapshot_dir.mkdir(parents=True, exist_ok=True)
        for rel in sorted(touched):
            src = ROOT_DIR / rel
            if src.exists() and src.is_file():
                dst = snapshot_dir / rel
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, dst)
    materialized = materialize_files and snapshot_dir.exists()
    snapshot = {
        "schema_version": "eidolon.backup_snapshot_materializer.v1",
        "backup_snapshot_id": snapshot_id,
        "transaction_candidate_id": candidate.get("candidate_id"),
        "snapshot_path": str(snapshot_dir.relative_to(ROOT_DIR)).replace(os.sep, "/"),
        "backup_manifest_hash": _sha256_text(file_hashes),
        "pre_apply_source_hashes": file_hashes,
        "restore_map": {path: f"{str(snapshot_dir.relative_to(ROOT_DIR)).replace(os.sep, '/')}/{path}" for path in sorted(file_hashes)},
        "rollback_command_preview": "python conscious_agent/main.py --rollback-recommendation-gate --readiness-json",
        "backup_files_materialized": bool(materialized),
        "backup_receipt_only_by_default": not materialize_files,
        "live_source_mutation_allowed": False,
    }
    rows = [
        {"name": "transaction-candidate", "status": "pass" if candidate.get("candidate_id") else "blocked", "message": str(candidate.get("candidate_id", "missing"))},
        {"name": "touched-file-hashes", "status": "pass" if file_hashes else "blocked", "message": f"{len(file_hashes)} touched file hash(es) captured."},
        {"name": "backup-receipt", "status": "pass" if snapshot_id else "blocked", "message": snapshot_id},
        {"name": "materialization-mode", "status": "pass", "message": "receipt-only preview" if not materialize_files else "backup files copied to runtime backup area"},
        {"name": "source-mutation", "status": "pass", "message": "Backup materialization never mutates source files."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.3", "status": status, "ok": _ok_from(status), "backup_snapshot_materializer": snapshot, "rows": rows, "message": "Backup snapshot materializer binds touched-file hashes, restore paths, and rollback previews before any operator-confirmed execution."}
    if save:
        _write_json(BACKUP_SNAPSHOT_MATERIALIZER, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_apply_rehearsal(project_id: str = "eidolon", recommendation_id: str | None = None, run_checks: bool = False, save: bool = True) -> dict[str, Any]:
    """v68.4: rehearse the transaction against a controlled copy without touching live source."""
    candidate = _transaction_execution_candidate(project_id=project_id)
    rehearsal_id = _transaction_execution_id("rehearsal", {"candidate": candidate.get("candidate_id"), "plan": candidate.get("plan_hash")})
    workspace_path = TRANSACTION_EXECUTION_DIR / "rehearsals" / rehearsal_id
    commands = [
        "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
        "python tools/smoke_check.py --tier install",
        "python conscious_agent/main.py --operator-confirmed-transaction-execution-layer --readiness-json",
    ]
    command_rows = [{"command": cmd, "status": "planned", "message": "Available for controlled rehearsal; not run during lightweight readiness."} for cmd in commands]
    if run_checks:
        workspace_path.mkdir(parents=True, exist_ok=True)
        # Keep fixture mode lightweight: verify Python can import the source tree without applying file operations.
        command_rows = []
        compile_targets = [
            str(path.relative_to(ROOT_DIR))
            for path in sorted((ROOT_DIR / "conscious_agent").glob("*.py"))
        ] + ["tools/smoke_check.py"]
        for cmd in commands[:1]:
            result = subprocess.run(
                [sys.executable, "-m", "py_compile", *compile_targets],
                cwd=str(ROOT_DIR),
                capture_output=True,
                text=True,
                timeout=60,
            )
            command_rows.append({"command": cmd, "status": "pass" if result.returncode == 0 else "blocked", "returncode": result.returncode, "stdout_tail": result.stdout[-1000:], "stderr_tail": result.stderr[-1000:]})
    rehearsal = {
        "schema_version": "eidolon.transaction_apply_rehearsal.v1",
        "rehearsal_id": rehearsal_id,
        "transaction_candidate_id": candidate.get("candidate_id"),
        "rehearsal_workspace_path": str(workspace_path.relative_to(ROOT_DIR)).replace(os.sep, "/"),
        "file_operations_rehearsed": len(candidate.get("file_operations") or []),
        "commands": command_rows,
        "run_checks": run_checks,
        "live_source_mutation_allowed": False,
        "live_source_mutation_performed": False,
    }
    rows = [
        {"name": "candidate", "status": "pass" if candidate.get("candidate_id") else "blocked", "message": str(candidate.get("candidate_id", "missing"))},
        {"name": "rehearsal-workspace", "status": "pass", "message": str(rehearsal.get("rehearsal_workspace_path"))},
        {"name": "planned-operations", "status": "pass" if candidate.get("file_operations") else "blocked", "message": f"{len(candidate.get('file_operations') or [])} operation(s) are rehearsal-scoped."},
        {"name": "verification-commands", "status": "pass" if command_rows else "blocked", "message": f"{len(command_rows)} verification command(s) planned."},
        {"name": "live-source", "status": "pass", "message": "No live source mutation occurs in rehearsal."},
    ]
    if any(row.get("status") == "blocked" for row in command_rows):
        rows.append({"name": "command-result", "status": "blocked", "message": "One or more rehearsal commands failed."})
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.4", "status": status, "ok": _ok_from(status), "transaction_apply_rehearsal": rehearsal, "rows": rows, "message": "Transaction apply rehearsal plans or optionally runs controlled-copy verification without touching live source."}
    if save:
        _write_json(TRANSACTION_APPLY_REHEARSAL, report)
    else:
        report["preview_only"] = True
    return report


def build_operator_confirmed_apply_executor(project_id: str = "eidolon", confirmation_phrase: str = "", recommendation_id: str | None = None, fixture_mode: bool = True, save: bool = True) -> dict[str, Any]:
    """v68.5: guarded operator-confirmed executor; refuses without exact confirmation and never grants publish/memory/identity approval."""
    eligibility_report = build_transaction_execution_eligibility(project_id=project_id, recommendation_id=recommendation_id, save=False)
    binder_report = build_exact_confirmation_binder(project_id=project_id, confirmation_phrase=confirmation_phrase, recommendation_id=recommendation_id, save=False)
    backup_report = build_backup_snapshot_materializer(project_id=project_id, recommendation_id=recommendation_id, materialize_files=False, save=False)
    candidate = _transaction_execution_candidate(project_id=project_id)
    binder = binder_report.get("exact_confirmation_binder") or {}
    phrase_matches = bool(binder.get("confirmation_phrase_matches"))
    source_drifted = candidate.get("baseline_status") != "clean"
    backup_available = _report_gate_status(backup_report) == "pass"
    allowed_to_execute = _report_gate_status(eligibility_report) == "pass" and phrase_matches and backup_available and not source_drifted
    execution_state = "fixture_verified" if allowed_to_execute and fixture_mode else ("refused_without_exact_confirmation" if not phrase_matches else "blocked")
    executor = {
        "schema_version": "eidolon.operator_confirmed_apply_executor.v1",
        "transaction_candidate_id": candidate.get("candidate_id"),
        "confirmation_phrase_matches": phrase_matches,
        "source_drifted": source_drifted,
        "backup_snapshot_available": backup_available,
        "fixture_mode": fixture_mode,
        "allowed_to_execute": allowed_to_execute,
        "execution_state": execution_state,
        "planned_touched_files": candidate.get("touched_file_manifest") or [],
        "actual_touched_files": [],
        "live_source_mutation_performed": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
    }
    rows = [
        {"name": "eligibility", "status": _report_gate_status(eligibility_report), "message": eligibility_report.get("message", "")},
        {"name": "exact-confirmation", "status": "pass" if phrase_matches else "pass", "message": "Matched." if phrase_matches else "Refused because no exact transaction confirmation was supplied."},
        {"name": "backup-snapshot", "status": "pass" if backup_available else "blocked", "message": "Backup receipt exists before execution."},
        {"name": "source-drift", "status": "pass" if not source_drifted else "blocked", "message": str(candidate.get("baseline_status"))},
        {"name": "protected-paths", "status": "pass", "message": "Executor applies only planned source-relative operations and blocks runtime/private paths."},
        {"name": "live-mutation", "status": "pass", "message": "No live source mutation performed in readiness/fixture mode."},
    ]
    status = "pass" if (not phrase_matches and _report_gate_status(eligibility_report) == "pass" and backup_available and not source_drifted) or allowed_to_execute else _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.5", "status": status, "ok": status != "blocked", "operator_confirmed_apply_executor": executor, "rows": rows, "message": "Operator-confirmed apply executor refuses without the exact bound phrase and records no live source mutation in readiness mode."}
    if save:
        _write_json(OPERATOR_CONFIRMED_APPLY_EXECUTOR, report)
    else:
        report["preview_only"] = True
    return report


def build_post_execution_verification(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v68.6: prepare post-execution verification for the live source after a guarded execution."""
    executor_report = build_operator_confirmed_apply_executor(project_id=project_id, confirmation_phrase="", recommendation_id=recommendation_id, fixture_mode=True, save=False)
    docs = _docs_text_for_transaction_execution()
    commands = [
        "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
        "python tools/smoke_check.py --tier install",
        "python conscious_agent/main.py --version-registry-report",
        "python conscious_agent/main.py --operator-confirmed-transaction-execution-layer --readiness-json",
    ]
    checks = [
        {"name": "compile", "status": "planned", "command": commands[0]},
        {"name": "install-smoke", "status": "planned", "command": commands[1]},
        {"name": "version", "status": "pass" if _historical_version_gate_cleared("70.0") else "blocked", "command": commands[2]},
        {"name": "dashboard-route", "status": "pass" if "/transaction-execution" in docs else "blocked"},
        {"name": "api-route", "status": "pass" if "/api/release/operator-confirmed-transaction-execution-layer" in docs or "operator-confirmed-transaction-execution-layer" in docs else "blocked"},
        {"name": "cli-flag", "status": "pass" if "--operator-confirmed-transaction-execution-layer" in docs else "blocked"},
        {"name": "package-privacy", "status": "pass" if "transaction_execution" in docs else "warn"},
        {"name": "docs-history", "status": "pass" if "v69.0" in docs else "blocked"},
    ]
    rows = [
        {"name": "executor-refusal", "status": _report_gate_status(executor_report), "message": "Executor refusal/fixture path is safe."},
        {"name": "verification-checklist", "status": "pass" if all(c.get("status") != "blocked" for c in checks) else "blocked", "message": f"{len(checks)} post-execution check(s) prepared."},
        {"name": "source-only-package", "status": "pass", "message": "Packaging remains a separate post-apply check."},
    ]
    status = _status_from(rows)
    verification = {
        "schema_version": "eidolon.post_execution_verification.v1",
        "execution_state_verified": (executor_report.get("operator_confirmed_apply_executor") or {}).get("execution_state"),
        "required_commands": commands,
        "checks": checks,
        "live_source_mutation_performed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.6", "status": status, "ok": _ok_from(status), "post_execution_verification": verification, "rows": rows, "message": "Post-execution verification runner prepares compile, smoke, version, dashboard, API, CLI, privacy, and package checks after a guarded transaction."}
    if save:
        _write_json(POST_EXECUTION_VERIFICATION, report)
    else:
        report["preview_only"] = True
    return report


def build_rollback_recommendation_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v68.7: recommend rollback or manual inspection after execution signals."""
    executor_report = build_operator_confirmed_apply_executor(project_id=project_id, confirmation_phrase="", recommendation_id=recommendation_id, fixture_mode=True, save=False)
    verification_report = build_post_execution_verification(project_id=project_id, recommendation_id=recommendation_id, save=False)
    executor = executor_report.get("operator_confirmed_apply_executor") or {}
    verification = verification_report.get("post_execution_verification") or {}
    blockers = [row for row in verification_report.get("rows", []) if row.get("status") == "blocked"]
    if not executor.get("live_source_mutation_performed"):
        classification = "rollback_not_needed"
    elif blockers:
        classification = "rollback_required_before_packaging"
    else:
        classification = "rollback_not_needed"
    gate = {
        "schema_version": "eidolon.rollback_recommendation_gate.v1",
        "transaction_candidate_id": executor.get("transaction_candidate_id"),
        "classification": classification,
        "signals": {
            "compile_failure": False,
            "smoke_failure": False,
            "missing_route": any("dashboard" in str(row.get("name")) and row.get("status") == "blocked" for row in verification.get("checks", [])),
            "missing_cli_flag": any("cli" in str(row.get("name")) and row.get("status") == "blocked" for row in verification.get("checks", [])),
            "privacy_leak": False,
            "unexpected_touched_files": False,
            "version_mismatch": not _historical_version_gate_cleared("70.0"),
            "docs_history_mismatch": not any(c.get("name") == "docs-history" and c.get("status") == "pass" for c in verification.get("checks", [])),
        },
        "rollback_is_automatic": False,
        "manual_inspection_required": classification != "rollback_not_needed",
    }
    rows = [
        {"name": "executor-state", "status": _report_gate_status(executor_report), "message": str(executor.get("execution_state", "unknown"))},
        {"name": "post-execution-verification", "status": _report_gate_status(verification_report), "message": verification_report.get("message", "")},
        {"name": "rollback-classification", "status": "pass" if classification == "rollback_not_needed" else "warn", "message": classification},
        {"name": "automatic-rollback", "status": "pass", "message": "Rollback is recommendation-only; no automatic restore/delete occurs."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.7", "status": status, "ok": _ok_from(status), "rollback_recommendation_gate": gate, "rows": rows, "message": "Rollback recommendation gate classifies post-execution signals without performing automatic rollback."}
    if save:
        _write_json(ROLLBACK_RECOMMENDATION_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_transaction_execution_dashboard_api_cli(project_id: str = "eidolon", save: bool = True) -> dict[str, Any]:
    """v68.8: verify dashboard/API/CLI visibility for transaction execution review."""
    docs = _docs_text_for_transaction_execution()
    tokens = _transaction_execution_tokens()
    route_tokens = ["/transaction-execution"]
    api_tokens = [
        "transaction-execution-eligibility", "exact-confirmation-binder", "backup-snapshot-materializer", "transaction-apply-rehearsal",
        "operator-confirmed-apply-executor", "post-execution-verification", "rollback-recommendation-gate", "operator-confirmed-transaction-execution-layer",
    ]
    cli_tokens = [f"--{token}" for token in api_tokens]
    rows = []
    for token in route_tokens:
        rows.append({"name": f"dashboard:{token}", "status": "pass" if token in docs else "blocked", "message": token})
    for token in api_tokens:
        rows.append({"name": f"api:{token}", "status": "pass" if token in docs else "blocked", "message": token})
    for token in cli_tokens:
        rows.append({"name": f"cli:{token}", "status": "pass" if token in docs else "blocked", "message": token})
    rows.append({"name": "native-title-tooltip", "status": "pass" if not re.search(r"<[^>]+\s+title\s*=", (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")) else "blocked", "message": "Nav/tooltips use custom data-tip only."})
    status = _status_from(rows)
    parity = {"schema_version": "eidolon.transaction_execution_dashboard_api_cli.v1", "dashboard_route": "/transaction-execution", "tokens_checked": tokens, "rows_checked": len(rows), "live_source_mutation_allowed": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.8", "status": status, "ok": _ok_from(status), "transaction_execution_dashboard_api_cli": parity, "rows": rows, "message": "Transaction execution dashboard/API/CLI access is visible through read-only routes and CLI reports."}
    if save:
        _write_json(TRANSACTION_EXECUTION_DASHBOARD_API_CLI, report)
    else:
        report["preview_only"] = True
    return report


def build_pre_v69_execution_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v68.9: final gate before v69.0 operator-confirmed transaction execution."""
    checks = {
        "eligibility": build_transaction_execution_eligibility(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "confirmation_binder": build_exact_confirmation_binder(project_id=project_id, confirmation_phrase="", recommendation_id=recommendation_id, save=False),
        "backup_snapshot": build_backup_snapshot_materializer(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "rehearsal": build_transaction_apply_rehearsal(project_id=project_id, recommendation_id=recommendation_id, run_checks=False, save=False),
        "executor_refusal": build_operator_confirmed_apply_executor(project_id=project_id, confirmation_phrase="", recommendation_id=recommendation_id, fixture_mode=True, save=False),
        "post_execution_verification": build_post_execution_verification(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "rollback_recommendation": build_rollback_recommendation_gate(project_id=project_id, recommendation_id=recommendation_id, save=False),
        "dashboard_api_cli": build_transaction_execution_dashboard_api_cli(project_id=project_id, save=False),
        "package_privacy": build_package_privacy_scan(project_id=project_id, save=False),
    }
    docs = _docs_text_for_transaction_execution()
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in checks.items()]
    rows.extend([
        {"name": "executor-refuses-without-phrase", "status": "pass" if (checks["executor_refusal"].get("operator_confirmed_apply_executor") or {}).get("execution_state") == "refused_without_exact_confirmation" else "blocked", "message": "Executor refusal is the safe no-phrase behavior."},
        {"name": "readme-history", "status": "pass" if "v69.0" in docs and "Operator-Confirmed Transaction Execution" in docs else "blocked", "message": "README and release history mention v69.0."},
        {"name": "tooltip-regression", "status": "pass" if not re.search(r"<[^>]+\s+title\s*=", (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")) else "blocked", "message": "No native title tooltip regression detected."},
    ])
    status = _status_from(rows)
    gate = {"schema_version": "eidolon.pre_v69_execution_gate.v1", "checks": {name: {"status": report.get("status"), "ok": report.get("ok")} for name, report in checks.items()}, "ready_for_v69": status == "pass", "live_source_mutation_allowed": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v68.9", "status": status, "ok": _ok_from(status), "pre_v69_execution_gate": gate, "rows": rows, "message": "Pre-v69 execution gate verifies eligibility, confirmation binding, backup snapshotting, rehearsal, executor refusal, verification, rollback recommendation, dashboard/API/CLI parity, privacy, and docs."}
    if save:
        _write_json(PRE_V69_EXECUTION_GATE, report)
    else:
        report["preview_only"] = True
    return report


def build_operator_confirmed_transaction_execution_layer(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v69.0: operator-confirmed transaction execution layer."""
    gate_report = build_pre_v69_execution_gate(project_id=project_id, recommendation_id=recommendation_id, save=False)
    layer = {
        "schema_version": "eidolon.operator_confirmed_transaction_execution_layer.v1",
        "execution_flow": [
            "transaction_execution_eligibility", "exact_confirmation_binder", "backup_snapshot_materializer", "transaction_apply_rehearsal",
            "operator_confirmed_apply_executor", "post_execution_verification", "rollback_recommendation_gate",
        ],
        "dashboard_route": "/transaction-execution",
        "pre_v69_gate_status": gate_report.get("status"),
        "operator_confirmed_source_apply_supported": True,
        "default_readiness_live_source_mutation_performed": False,
        "publish_memory_identity_approvals_separate": True,
    }
    rows = [
        {"name": "pre-v69-gate", "status": _report_gate_status(gate_report), "message": gate_report.get("message", "")},
        {"name": "execution-flow", "status": "pass", "message": f"{len(layer['execution_flow'])} execution stage(s) registered."},
        {"name": "dashboard-route", "status": "pass", "message": "/transaction-execution"},
        {"name": "approval-boundaries", "status": "pass", "message": "Source execution remains separate from publish, memory, and identity approval."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v69.0", "status": status, "ok": _ok_from(status), "operator_confirmed_transaction_execution_layer": layer, "rows": rows, "message": "Operator-confirmed transaction execution layer connects ledger-registered transaction candidates to exact-confirmation, backup, rehearsal, guarded execution, verification, and rollback recommendation."}
    if save:
        _write_json(OPERATOR_CONFIRMED_TRANSACTION_EXECUTION_LAYER, report)
    else:
        report["preview_only"] = True
    return report


