# v69.1-v70.0 verified execution recovery and release finalization runtime paths.
RELEASE_FINALIZATION_DIR = DATA_DIR / "autonomy" / "release_finalization"
EXECUTION_RESULT_LEDGER_FINALIZER = SELF_MAINTENANCE_DIR / "execution_result_ledger_finalizer.json"
ROLLBACK_DECISION_RESOLVER = SELF_MAINTENANCE_DIR / "rollback_decision_resolver.json"
OPERATOR_CONFIRMED_ROLLBACK_EXECUTOR = SELF_MAINTENANCE_DIR / "operator_confirmed_rollback_executor.json"
POST_ROLLBACK_VERIFICATION = SELF_MAINTENANCE_DIR / "post_rollback_verification.json"
RELEASE_CANDIDATE_FINALIZATION_GATE = SELF_MAINTENANCE_DIR / "release_candidate_finalization_gate.json"
SOURCE_ONLY_PACKAGE_CERTIFIER = SELF_MAINTENANCE_DIR / "source_only_package_certifier.json"
RELEASE_FINALIZATION_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "release_finalization_dashboard_api_cli.json"
RECOVERY_SIMULATION_HARNESS = SELF_MAINTENANCE_DIR / "recovery_simulation_harness.json"
PRE_V70_RECOVERY_FINALIZATION_GATE = SELF_MAINTENANCE_DIR / "pre_v70_recovery_finalization_gate.json"
VERIFIED_EXECUTION_RECOVERY_RELEASE_LAYER = SELF_MAINTENANCE_DIR / "verified_execution_recovery_release_layer.json"


def _release_finalization_tokens() -> list[str]:
    return [
        "execution-result-ledger-finalizer", "rollback-decision-resolver", "operator-confirmed-rollback-executor",
        "post-rollback-verification", "release-candidate-finalization-gate", "source-only-package-certifier",
        "release-finalization-dashboard-api-cli", "recovery-simulation-harness", "release-finalization",
        "verified-execution-recovery-release-layer",
    ]


def _release_finalization_id(prefix: str, value: Any) -> str:
    return f"{prefix}-{_sha256_text(value)[:16]}"


def _docs_text_for_release_finalization() -> str:
    chunks: list[str] = []
    for rel in ("README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "conscious_agent/release_installation.py"):
        path = ROOT_DIR / rel
        try:
            chunks.append(path.read_text(encoding="utf-8", errors="ignore"))
        except Exception:
            chunks.append("")
    return "\n".join(chunks)




def build_execution_result_ledger_finalizer(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v69.1: finalize the transaction ledger record after an execution attempt."""
    ctx = _latest_execution_context(project_id=project_id, recommendation_id=recommendation_id)
    candidate = ctx["candidate"]
    executor = ctx["executor"]
    verification_report = ctx["verification_report"]
    rollback_report = ctx["rollback_report"]
    expected = set(ctx["expected_touched_files"])
    actual = set(ctx["actual_touched_files"])
    unexpected = sorted(actual - expected)
    missing = sorted(expected - actual) if executor.get("live_source_mutation_performed") else []
    finalizer_id = _release_finalization_id("execfinal", {"candidate": candidate.get("candidate_id"), "execution": executor, "verification": verification_report})
    package_scan = build_package_privacy_scan(project_id=project_id, save=False)
    final_state = "finalization_eligible" if _report_gate_status(verification_report) == "pass" and not unexpected else "manual_review_required"
    ledger = {
        "schema_version": "eidolon.execution_result_ledger_finalizer.v1",
        "execution_finalizer_id": finalizer_id,
        "transaction_candidate_id": candidate.get("candidate_id"),
        "transaction_plan_hash": candidate.get("plan_hash"),
        "execution_status": ctx["execution_status"],
        "touched_files_expected": sorted(expected),
        "touched_files_actual": sorted(actual),
        "unexpected_touched_files": unexpected,
        "missing_expected_touched_files": missing,
        "verification_status": ctx["verification_status"],
        "rollback_recommendation": ctx["rollback_recommendation"],
        "package_readiness": "pass" if package_scan.get("ok") else "blocked",
        "operator_confirmation_hash": executor.get("confirmation_phrase_hash"),
        "execution_receipt_hash": _sha256_text(executor),
        "final_ledger_state": final_state,
        "execution_result_is_durable": True,
        "live_source_mutation_performed": bool(executor.get("live_source_mutation_performed")),
    }
    rows = [
        {"name": "transaction-candidate", "status": "pass" if candidate.get("candidate_id") else "blocked", "message": str(candidate.get("candidate_id", "missing"))},
        {"name": "execution-status", "status": "pass", "message": str(ctx["execution_status"])},
        {"name": "touched-file-reconciliation", "status": "pass" if not unexpected and not missing else "blocked", "message": f"unexpected={len(unexpected)} missing={len(missing)}"},
        {"name": "post-execution-verification", "status": ctx["verification_status"], "message": verification_report.get("message", "")},
        {"name": "rollback-recommendation", "status": _report_gate_status(rollback_report), "message": str(ctx["rollback_recommendation"])},
        {"name": "package-readiness", "status": "pass" if package_scan.get("ok") else "blocked", "message": package_scan.get("message", "")},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v69.1", "status": status, "ok": _ok_from(status), "execution_result_ledger_finalizer": ledger, "rows": rows, "message": "Execution result ledger finalizer completes durable post-execution records with touched-file reconciliation, verification, rollback, package readiness, and receipt hashes."}
    if save: _write_json(EXECUTION_RESULT_LEDGER_FINALIZER, report)
    else: report["preview_only"] = True
    return report


def build_rollback_decision_resolver(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v69.2: turn rollback recommendations and verification signals into a structured decision."""
    finalizer_report = build_execution_result_ledger_finalizer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    ctx = _latest_execution_context(project_id=project_id, recommendation_id=recommendation_id)
    ledger = finalizer_report.get("execution_result_ledger_finalizer") or {}
    verification_blocked = ctx.get("verification_status") == "blocked"
    unexpected = bool(ledger.get("unexpected_touched_files"))
    package_blocked = ledger.get("package_readiness") == "blocked"
    if not (ctx.get("executor") or {}).get("live_source_mutation_performed"):
        decision = "finalization-eligible"
    elif verification_blocked or unexpected or package_blocked:
        decision = "rollback-required"
    elif ctx.get("rollback_recommendation") not in {"rollback_not_needed", "rollback-not-needed"}:
        decision = "rollback-recommended"
    else:
        decision = "rollback-not-needed"
    signals = {
        "compile_failure": verification_blocked,
        "smoke_failure": verification_blocked,
        "route_check_failure": verification_blocked,
        "privacy_failure": package_blocked,
        "unexpected_touched_files": unexpected,
        "version_mismatch": not _historical_version_gate_cleared("70.0"),
        "readme_history_mismatch": "v70.0" not in _docs_text_for_release_finalization(),
        "package_scan_blocked": package_blocked,
    }
    resolver = {
        "schema_version": "eidolon.rollback_decision_resolver.v1",
        "transaction_candidate_id": ledger.get("transaction_candidate_id"),
        "decision": decision,
        "signals": signals,
        "rollback_is_automatic": False,
        "operator_confirmation_required_for_rollback": True,
        "finalization_eligible": decision in {"rollback-not-needed", "finalization-eligible"},
    }
    rows = [
        {"name": "ledger-finalizer", "status": _report_gate_status(finalizer_report), "message": finalizer_report.get("message", "")},
        {"name": "decision", "status": "pass" if decision in {"rollback-not-needed", "finalization-eligible"} else "warn", "message": decision},
        {"name": "automatic-rollback", "status": "pass", "message": "No automatic rollback occurs; exact rollback confirmation is required."},
        {"name": "signal-count", "status": "pass" if not any(signals.values()) or decision == "finalization-eligible" else "warn", "message": f"{sum(1 for v in signals.values() if v)} active signal(s)."},
    ]
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v69.2", "status": status, "ok": _ok_from(status), "rollback_decision_resolver": resolver, "rows": rows, "message": "Rollback decision resolver converts post-execution signals into rollback-not-needed, rollback-recommended, rollback-required, manual-review, blocked, or finalization-eligible states."}
    if save: _write_json(ROLLBACK_DECISION_RESOLVER, report)
    else: report["preview_only"] = True
    return report


def build_operator_confirmed_rollback_executor(project_id: str = "eidolon", rollback_confirmation_phrase: str = "", recommendation_id: str | None = None, fixture_mode: bool = True, save: bool = True) -> dict[str, Any]:
    """v69.3: guarded rollback executor; refuses without exact rollback confirmation."""
    decision_report = build_rollback_decision_resolver(project_id=project_id, recommendation_id=recommendation_id, save=False)
    ctx = _latest_execution_context(project_id=project_id, recommendation_id=recommendation_id)
    candidate = ctx["candidate"]
    snapshot = ctx["snapshot"]
    candidate_id = candidate.get("candidate_id") or "unknown"
    backup_hash = _sha256_text(snapshot)
    required_phrase = f"ROLLBACK EIDOLON 70.0 TRANSACTION {candidate_id} WITH BACKUP {backup_hash[:16]}"
    phrase_matches = bool(rollback_confirmation_phrase) and rollback_confirmation_phrase == required_phrase
    decision = (decision_report.get("rollback_decision_resolver") or {}).get("decision")
    rollback_needed = decision in {"rollback-recommended", "rollback-required", "manual-review-required"}
    allowed = phrase_matches and rollback_needed and _report_gate_status(decision_report) != "blocked"
    executor = {
        "schema_version": "eidolon.operator_confirmed_rollback_executor.v1",
        "transaction_candidate_id": candidate_id,
        "required_confirmation_template": "ROLLBACK EIDOLON 70.0 TRANSACTION <candidate_id> WITH BACKUP <backup_hash16>",
        "required_confirmation_phrase_hash": _sha256_text(required_phrase),
        "provided_confirmation_phrase_hash": _sha256_text(rollback_confirmation_phrase) if rollback_confirmation_phrase else None,
        "confirmation_phrase_matches": phrase_matches,
        "rollback_decision": decision,
        "rollback_needed": rollback_needed,
        "fixture_mode": fixture_mode,
        "allowed_to_rollback": allowed,
        "rollback_state": "fixture_verified" if allowed and fixture_mode else ("refused_without_exact_confirmation" if not phrase_matches else "not_needed_or_blocked"),
        "restore_map": snapshot.get("backup_entries") or [],
        "rollback_touched_files": [] if not allowed else list(candidate.get("touched_file_manifest") or []),
        "live_source_mutation_performed": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
    }
    rows = [
        {"name": "rollback-decision", "status": _report_gate_status(decision_report), "message": str(decision)},
        {"name": "exact-rollback-confirmation", "status": "pass", "message": "Matched." if phrase_matches else "Refused because exact rollback confirmation was not supplied."},
        {"name": "backup-snapshot", "status": "pass" if snapshot else "blocked", "message": f"{len(snapshot.get('backup_entries') or [])} backup entrie(s) planned."},
        {"name": "fixture-mode", "status": "pass", "message": "Readiness path never mutates live source."},
        {"name": "approval-boundaries", "status": "pass", "message": "Rollback remains separate from publish, memory, and identity approvals."},
    ]
    status = _status_from(rows)
    if not phrase_matches and _report_gate_status(decision_report) != "blocked":
        status = "pass"
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v69.3", "status": status, "ok": _ok_from(status), "operator_confirmed_rollback_executor": executor, "rows": rows, "message": "Operator-confirmed rollback executor refuses without the exact rollback phrase and performs no live restore/delete in readiness mode."}
    if save: _write_json(OPERATOR_CONFIRMED_ROLLBACK_EXECUTOR, report)
    else: report["preview_only"] = True
    return report


def build_post_rollback_verification(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v69.4: verify the source tree after a rollback attempt or rollback refusal."""
    rollback_report = build_operator_confirmed_rollback_executor(project_id=project_id, rollback_confirmation_phrase="", recommendation_id=recommendation_id, fixture_mode=True, save=False)
    docs = _docs_text_for_release_finalization()
    commands = [
        "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
        "python tools/smoke_check.py --tier install",
        "python conscious_agent/main.py --version-registry-report",
        "python conscious_agent/main.py --verified-execution-recovery-release-layer --readiness-json",
    ]
    checks = [
        {"name": "compile", "status": "planned", "command": commands[0]},
        {"name": "install-smoke", "status": "planned", "command": commands[1]},
        {"name": "version", "status": "pass" if _historical_version_gate_cleared("70.0") else "blocked", "command": commands[2]},
        {"name": "restored-hashes", "status": "planned", "message": "Compared against backup snapshot after real rollback."},
        {"name": "unexpected-files", "status": "planned", "message": "Checked after real rollback."},
        {"name": "runtime-private-boundary", "status": "pass", "message": "Rollback verification never touches runtime/private data in readiness mode."},
        {"name": "package-privacy", "status": "pass" if build_package_privacy_scan(project_id=project_id, save=False).get("ok") else "blocked"},
        {"name": "dashboard-route", "status": "pass" if "/release-finalization" in docs else "blocked"},
        {"name": "api-route", "status": "pass" if "verified-execution-recovery-release-layer" in docs else "blocked"},
        {"name": "cli-flag", "status": "pass" if "--verified-execution-recovery-release-layer" in docs else "blocked"},
    ]
    rows = [
        {"name": "rollback-executor", "status": _report_gate_status(rollback_report), "message": rollback_report.get("message", "")},
        {"name": "verification-checklist", "status": "pass" if all(c.get("status") != "blocked" for c in checks) else "blocked", "message": f"{len(checks)} post-rollback check(s) prepared."},
        {"name": "live-source", "status": "pass", "message": "No live rollback occurred in readiness mode."},
    ]
    status = _status_from(rows)
    verification = {"schema_version": "eidolon.post_rollback_verification.v1", "checks": checks, "required_commands": commands, "rollback_state": (rollback_report.get("operator_confirmed_rollback_executor") or {}).get("rollback_state"), "live_source_mutation_performed": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v69.4", "status": status, "ok": _ok_from(status), "post_rollback_verification": verification, "rows": rows, "message": "Post-rollback verification prepares compile, smoke, version, hash restoration, unexpected-file, privacy, dashboard, API, and CLI checks."}
    if save: _write_json(POST_ROLLBACK_VERIFICATION, report)
    else: report["preview_only"] = True
    return report


def build_release_candidate_finalization_gate(project_id: str = "eidolon", recommendation_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v69.5: certify the source tree as a release candidate after successful execution or safe readiness."""
    finalizer_report = build_execution_result_ledger_finalizer(project_id=project_id, recommendation_id=recommendation_id, save=False)
    decision_report = build_rollback_decision_resolver(project_id=project_id, recommendation_id=recommendation_id, save=False)
