    gate = {"schema_version": "eidolon.pre_v70_recovery_finalization_gate.v1", "checks": {name: {"status": report.get("status"), "ok": report.get("ok")} for name, report in checks.items()}, "ready_for_v70": status == "pass", "live_source_mutation_allowed": False, "publish_approval_granted": False}
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v69.9", "status": status, "ok": _ok_from(status), "pre_v70_recovery_finalization_gate": gate, "rows": rows, "message": "Pre-v70 recovery/finalization gate verifies ledger finalization, rollback decision/executor/verification, release candidate certification, package certification, simulations, dashboard/API/CLI parity, privacy, install smoke planning, docs, and tooltip stability."}
    if save: _write_json(PRE_V70_RECOVERY_FINALIZATION_GATE, report)
    else: report["preview_only"] = True
    return report


