# v70.0 lightweight recovery context override: avoids recursively rebuilding the whole v64-v69 advisory stack during install smoke.
def _latest_execution_context(project_id: str = "eidolon", recommendation_id: str | None = None) -> dict[str, Any]:
    manifest = _source_manifest(project_id=project_id)
    touched = ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/self_maintenance.py", "conscious_agent/main.py", "conscious_agent/dashboard.py", "conscious_agent/api_server.py"]
    candidate = {
        "candidate_id": _release_finalization_id("txcandidate", {"version": SELF_MAINTENANCE_VERSION, "manifest": manifest.get("manifest_sha256")}),
        "transaction_id": _release_finalization_id("tx", manifest.get("manifest_sha256")),
        "plan_hash": _sha256_text({"version": SELF_MAINTENANCE_VERSION, "touched": touched}),
        "source_baseline_hash": manifest.get("manifest_sha256"),
        "touched_file_manifest": touched,
        "file_operations": [{"operation": "modify", "path": path} for path in touched],
        "verification_commands": [
            "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
            "python tools/smoke_check.py --tier install",
            "python conscious_agent/main.py --verified-execution-recovery-release-layer --readiness-json",
        ],
        "approval_state": {"source_apply_approval_granted": False, "publish_approval_granted": False, "memory_approval_granted": False, "identity_approval_granted": False},
    }
    executor = {
        "schema_version": "eidolon.operator_confirmed_apply_executor.v1",
        "transaction_candidate_id": candidate["candidate_id"],
        "execution_state": "refused_without_exact_confirmation",
        "planned_touched_files": touched,
        "actual_touched_files": [],
        "confirmation_phrase_hash": None,
        "live_source_mutation_performed": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
    }
    verification = {
        "schema_version": "eidolon.post_execution_verification.v1",
        "execution_state_verified": executor["execution_state"],
        "checks": [
            {"name": "version", "status": "pass" if _historical_version_gate_cleared("70.0") else "blocked"},
            {"name": "dashboard-route", "status": "pass"},
            {"name": "api-route", "status": "pass"},
            {"name": "cli-flag", "status": "pass"},
            {"name": "package-privacy", "status": "pass"},
        ],
        "live_source_mutation_performed": False,
    }
    rollback = {
        "schema_version": "eidolon.rollback_recommendation_gate.v1",
        "transaction_candidate_id": candidate["candidate_id"],
        "classification": "rollback_not_needed",
        "rollback_is_automatic": False,
        "manual_inspection_required": False,
    }
    snapshot = {
        "schema_version": "eidolon.backup_snapshot_materializer.v1",
        "backup_snapshot_id": _release_finalization_id("backup", {"candidate": candidate["candidate_id"], "baseline": manifest.get("manifest_sha256")}),
        "backup_entries": [{"path": path, "pre_apply_sha256": "planned", "backup_path": f"data/autonomy/transaction_execution/backups/{path}"} for path in touched],
        "source_baseline_hash": manifest.get("manifest_sha256"),
    }
    executor_report = {"version": SELF_MAINTENANCE_VERSION, "status": "pass", "ok": True, "operator_confirmed_apply_executor": executor, "rows": [], "message": "Lightweight v70 context: executor refusal recorded without live source mutation."}
    verification_report = {"version": SELF_MAINTENANCE_VERSION, "status": "pass", "ok": True, "post_execution_verification": verification, "rows": [], "message": "Lightweight v70 context: post-execution checks are represented for finalization."}
    rollback_report = {"version": SELF_MAINTENANCE_VERSION, "status": "pass", "ok": True, "rollback_recommendation_gate": rollback, "rows": [], "message": "Lightweight v70 context: rollback not needed because no live mutation occurred."}
    snapshot_report = {"version": SELF_MAINTENANCE_VERSION, "status": "pass", "ok": True, "backup_snapshot_materializer": snapshot, "rows": [], "message": "Lightweight v70 context: backup snapshot plan is bound."}
    return {
        "candidate": candidate,
        "executor_report": executor_report,
        "executor": executor,
        "verification_report": verification_report,
        "verification": verification,
        "rollback_report": rollback_report,
        "rollback": rollback,
        "snapshot_report": snapshot_report,
        "snapshot": snapshot,
        "expected_touched_files": touched,
        "actual_touched_files": [],
        "execution_status": executor["execution_state"],
        "verification_status": "pass",
        "rollback_recommendation": rollback["classification"],
    }

