PATCH_CONTEXT_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "patch_context_dashboard_api_cli.json"
PRE_V72_PATCH_CONTEXT_GATE = SELF_MAINTENANCE_DIR / "pre_v72_patch_context_gate.json"
PATCH_GENERATION_CONTEXT_BUILDER = SELF_MAINTENANCE_DIR / "patch_generation_context_builder.json"
DEFAULT_PATCH_CONTEXT_GOAL = "Prepare a supervised patch-generation context packet for the next reviewed Eidolon change without generating, applying, publishing, writing memory, altering identity, or bypassing approvals."


def _patch_context_tokens() -> list[str]:
    return [
        "patch-goal-intake-classifier", "relevant-file-context-selector", "historical-failure-context-binder",
        "risk-aware-context-budgeter", "verification-requirement-compiler", "patch-prompt-context-packet-builder",
        "context-completeness-reviewer", "patch-context-dashboard-api-cli", "pre-v72-patch-context-gate",
        "patch-generation-context-builder", "patch-context", "data/autonomy/patch_context/",
    ]


def _patch_context_id(prefix: str, value: Any) -> str:
    return f"{prefix}-{_sha256_text(value)[:16]}"


def _normalize_patch_goal(patch_goal: str | None = None) -> str:
    goal = (patch_goal or "").strip()
    return goal or DEFAULT_PATCH_CONTEXT_GOAL


def _patch_context_terms(goal: str) -> list[str]:
    terms = []
    for term in re.findall(r"[A-Za-z0-9_./-]+", goal.lower()):
        clean = term.strip("._-/")
        if len(clean) >= 3 and clean not in {"the", "and", "for", "with", "into", "from", "that", "this", "without", "before"}:
            terms.append(clean)
    # Preserve order while removing duplicates, because apparently even words deserve paperwork.
    seen: set[str] = set()
    unique: list[str] = []
    for term in terms:
        if term not in seen:
            unique.append(term)
            seen.add(term)
    return unique[:40]


def _patch_goal_hints(goal: str) -> dict[str, Any]:
    lowered = goal.lower()
    categories: set[str] = set()
    files: set[str] = set()
    reasons: list[str] = []
    mappings = [
        (("dashboard", "nav", "hover", "tooltip", "ui", "page", "route page"), "dashboard", "conscious_agent/dashboard.py", "dashboard/UI terms"),
        (("api", "endpoint", "json", "route", "server"), "api", "conscious_agent/api_server.py", "API/route terms"),
        (("cli", "flag", "command", "main.py", "readiness-json"), "cli", "conscious_agent/main.py", "CLI terms"),
        (("self_maintenance", "self maintenance", "gate", "context", "builder", "classifier", "risk", "verification"), "self_maintenance", "conscious_agent/self_maintenance.py", "self-maintenance/context terms"),
        (("smoke", "test", "verify", "verification", "compile"), "verification", "tools/smoke_check.py", "verification terms"),
        (("readme", "docs", "documentation", "release history"), "documentation", "README_NEXT_STEPS.md", "documentation terms"),
        (("release", "package", "zip", "privacy", "source-only"), "release_packaging", "conscious_agent/release_packaging.py", "release/package terms"),
        (("install", "portable", "clean room", "privacy scan"), "release_installation", "conscious_agent/release_installation.py", "install/privacy terms"),
        (("workspace", "project registry", "metadata"), "workspace_metadata", "conscious_agent/workspace_orchestration.py", "workspace metadata terms"),
    ]
    for needles, category, file_name, reason in mappings:
        if any(needle in lowered for needle in needles):
            categories.add(category)
            files.add(file_name)
            reasons.append(reason)
    if "release history" in lowered or "history" in lowered:
        files.add("README_RELEASE_HISTORY.md")
        categories.add("documentation")
    for rel in re.findall(r"(?:conscious_agent|tools|data)/[A-Za-z0-9_./-]+|README_[A-Z_]+\.md", goal):
        files.add(rel.strip())
    mutation_terms: list[str] = []
    for term in ("apply", "execute", "publish", "write memory", "mutate memory", "identity", "autonomous", "bypass approval", "delete", "rollback"):
        index = lowered.find(term)
        if index < 0:
            continue
        negation_window = lowered[max(0, index - 90):index]
        if "without" in negation_window or " no " in f" {negation_window} " or " not " in f" {negation_window} ":
            continue
        mutation_terms.append(term)
    safety_class = "context_only_safe" if not mutation_terms else "context_only_with_mutation_language"
    return {
        "target_categories": sorted(categories) or ["self_maintenance", "cli", "api", "dashboard", "verification", "documentation"],
        "likely_files": sorted(files) or [
            "conscious_agent/self_maintenance.py",
            "conscious_agent/main.py",
            "conscious_agent/api_server.py",
            "conscious_agent/dashboard.py",
            "tools/smoke_check.py",
            "README_NEXT_STEPS.md",
            "README_RELEASE_HISTORY.md",
        ],
        "reasons": reasons or ["default v72 context-builder surface"],
        "mutation_terms_detected": mutation_terms,
        "safety_class": safety_class,
    }


def _read_source_text(rel: str, max_bytes: int = 2_000_000) -> str:
    path = ROOT_DIR / rel
    if not path.exists() or not path.is_file():
        return ""
    try:
        data = path.read_bytes()[:max_bytes]
        return data.decode("utf-8", errors="replace")
    except OSError:
        return ""


def _outline_source_file(rel: str, terms: list[str], max_lines: int = 80) -> dict[str, Any]:
    text = _read_source_text(rel)
    if not text:
        return {"file": rel, "outline": [], "matching_lines": [], "sha256": None}
    path = ROOT_DIR / rel
    outline: list[dict[str, Any]] = []
    matching_lines: list[dict[str, Any]] = []
    interesting_prefixes = ("def ", "class ", "async def ", "from ", "import ", "if parts", "elif path", "parser.add_argument", "DASHBOARD_VERSION", "API_VERSION", "SELF_MAINTENANCE_VERSION", "RELEASE_PACKAGING_VERSION", "RELEASE_INSTALLATION_VERSION")
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if stripped.startswith(interesting_prefixes):
            outline.append({"line": lineno, "text": stripped[:220]})
        lowered = stripped.lower()
        if terms and any(term in lowered for term in terms):
            matching_lines.append({"line": lineno, "text": stripped[:220]})
        if len(outline) >= max_lines and len(matching_lines) >= max_lines // 2:
            break
    return {
        "file": rel,
        "sha256": _sha256_file(path) if path.stat().st_size <= 2_000_000 else "large-file-skipped",
        "outline": outline[:max_lines],
        "matching_lines": matching_lines[: max_lines // 2],
    }


def _risk_by_file() -> dict[str, dict[str, Any]]:
    report = build_module_risk_profile(save=False)
    return {item.get("file", ""): item for item in report.get("module_risk_profile", {}).get("profiles", [])}


def _responsibility_by_file() -> dict[str, dict[str, Any]]:
    report = build_module_responsibility_map(save=False)
    return {item.get("file", ""): item for item in report.get("module_responsibility_map", {}).get("modules", [])}


def _dependency_neighbors_for(rel: str, dependency_map: dict[str, Any]) -> dict[str, list[str]]:
    imports = dependency_map.get("python_imports", {}) if isinstance(dependency_map, dict) else {}
    reverse = dependency_map.get("reverse_imports", {}) if isinstance(dependency_map, dict) else {}
    direct = imports.get(rel, []) if isinstance(imports, dict) else []
    inbound = reverse.get(rel, []) if isinstance(reverse, dict) else []
    return {"imports": list(direct)[:20], "imported_by": list(inbound)[:20]}


def build_patch_goal_intake_classifier(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.1: classify a requested patch goal into read-only context-building hints."""
    goal = _normalize_patch_goal(patch_goal)
    terms = _patch_context_terms(goal)
    hints = _patch_goal_hints(goal)
    classifier = {
        "schema_version": "eidolon.patch_context.goal_intake.v1",
        "classification_id": _patch_context_id("goal", {"goal": goal, "terms": terms, "hints": hints}),
        "normalized_goal": goal,
        "goal_terms": terms,
        "target_categories": hints["target_categories"],
        "likely_files": hints["likely_files"],
        "selection_reasons": hints["reasons"],
        "safety_class": hints["safety_class"],
        "mutation_terms_detected": hints["mutation_terms_detected"],
        "context_only": True,
        "patch_generation_performed": False,
        "source_mutation_performed": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
    }
    rows = [
        {"name": "goal-present", "status": "pass" if goal else "blocked", "message": "Patch goal normalized for context selection."},
        {"name": "target-hints", "status": "pass" if classifier["likely_files"] else "blocked", "message": f"{len(classifier['likely_files'])} likely files and {len(classifier['target_categories'])} categories identified."},
        {"name": "context-only-boundary", "status": "pass" if classifier["context_only"] and not classifier["patch_generation_performed"] and not classifier["source_mutation_performed"] else "blocked", "message": "Classifier prepares context only; it does not generate or apply patches."},
    ]
    if classifier["mutation_terms_detected"]:
        rows.append({"name": "mutation-language-detected", "status": "warn", "message": f"Goal contains mutation/autonomy terms that are carried as warnings only: {', '.join(classifier['mutation_terms_detected'])}."})
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.1", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "patch_goal_intake_classifier": classifier, "rows": rows, "message": "Patch goal intake classifier turns a requested change into safe, read-only context-selection hints."}
    if save: _write_json(PATCH_GOAL_INTAKE_CLASSIFIER, report)
    else: report["preview_only"] = True
    return report


def build_relevant_file_context_selector(project_id: str = "eidolon", patch_goal: str | None = None, max_files: int = 18, save: bool = True) -> dict[str, Any]:
    """v71.2: select source files relevant to a patch goal from the v71 codebase map."""
    intake = build_patch_goal_intake_classifier(project_id=project_id, patch_goal=patch_goal, save=False)
    classifier = intake.get("patch_goal_intake_classifier", {})
    terms = list(classifier.get("goal_terms", []))
    likely_files = set(classifier.get("likely_files", []))
    categories = set(classifier.get("target_categories", []))
    inventory = build_source_tree_inventory(project_id=project_id, save=False)
    responsibilities = _responsibility_by_file()
    risks = _risk_by_file()
    deps_report = build_dependency_call_surface_map(project_id=project_id, save=False).get("dependency_call_surface_map", {})
    baseline_files = {
        "conscious_agent/self_maintenance.py", "conscious_agent/main.py", "conscious_agent/api_server.py", "conscious_agent/dashboard.py",
        "tools/smoke_check.py", "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md",
    }
    scored: list[tuple[int, dict[str, Any]]] = []
    for item in inventory.get("source_tree_inventory", {}).get("files", []):
        rel = item.get("file", "")
        if not rel or item.get("runtime_private") or not item.get("included_in_source_package"):
            continue
        resp = responsibilities.get(rel, {})
        risk = risks.get(rel, {})
        haystack = " ".join([
            rel.lower(), str(item.get("category", "")).lower(), str(item.get("role_hint", "")).lower(),
            " ".join(resp.get("responsibilities", [])).lower(), " ".join(resp.get("risk_notes", [])).lower(),
        ])
        score = 0
        reasons: list[str] = []
        if rel in likely_files:
            score += 40
            reasons.append("explicit goal hint")
        if rel in baseline_files:
            score += 20
            reasons.append("baseline patch-context surface")
        if item.get("category") in categories:
            score += 18
            reasons.append(f"category match: {item.get('category')}")
        matched_terms = [term for term in terms if term and term in haystack]
        if matched_terms:
            score += min(24, len(matched_terms) * 4)
            reasons.append("term match: " + ", ".join(matched_terms[:6]))
        if rel.endswith(".py") and any(term in rel for term in ("patch", "context", "maintenance", "release")):
            score += 4
        if score <= 0:
            continue
        selected = {
            "file": rel,
            "category": item.get("category"),
            "role_hint": item.get("role_hint"),
            "size_bytes": item.get("size_bytes"),
            "risk_level": risk.get("risk_level", "unknown"),
            "risk_score": risk.get("risk_score", 0),
            "risk_categories": risk.get("risk_categories", []),
            "responsibilities": resp.get("responsibilities", [item.get("role_hint", "")]),
            "common_failure_modes": resp.get("common_failure_modes", []),
            "dependency_neighbors": _dependency_neighbors_for(rel, deps_report),
            "selection_score": score,
            "why_selected": reasons,
        }
        scored.append((score, selected))
    scored.sort(key=lambda pair: (-pair[0], pair[1]["file"]))
    selected_files = [item for _, item in scored[:max(1, max_files)]]
    selector = {
        "schema_version": "eidolon.patch_context.relevant_files.v1",
        "selector_id": _patch_context_id("files", {"goal": classifier.get("normalized_goal"), "files": [f["file"] for f in selected_files]}),
        "goal_classification": classifier,
        "selected_file_count": len(selected_files),
        "selected_files": selected_files,
        "excluded_runtime_private": True,
        "source_mutation_performed": False,
        "patch_generation_performed": False,
    }
    rows = [
        {"name": "intake", "status": _report_gate_status(intake), "message": intake.get("message", "")},
        {"name": "selected-files", "status": "pass" if selected_files else "blocked", "message": f"{len(selected_files)} relevant source files selected."},
        {"name": "runtime-private-excluded", "status": "pass" if selector["excluded_runtime_private"] else "blocked", "message": "Runtime/private/generated files are not selected for source context."},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.2", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "relevant_file_context_selector": selector, "rows": rows, "message": "Relevant file context selector chooses source files, responsibilities, dependencies, and risks from the v71 codebase map."}
    if save: _write_json(RELEVANT_FILE_CONTEXT_SELECTOR, report)
    else: report["preview_only"] = True
    return report


def build_historical_failure_context_binder(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.3: bind historical failure lessons to the selected patch context."""
    selector_report = build_relevant_file_context_selector(project_id=project_id, patch_goal=patch_goal, save=False)
    selector = selector_report.get("relevant_file_context_selector", {})
    selected_files = {item.get("file") for item in selector.get("selected_files", [])}
    terms = set(selector.get("goal_classification", {}).get("goal_terms", []))
    failure_report = build_historical_failure_memory(project_id=project_id, save=False)
    failures = failure_report.get("historical_failure_memory", {}).get("failures", [])
    bound: list[dict[str, Any]] = []
    for failure in failures:
        files = set(failure.get("files", []))
        lesson_text = " ".join([failure.get("id", ""), failure.get("area", ""), failure.get("lesson", ""), " ".join(failure.get("watch_for", []))]).lower()
        matches_file = bool(files & selected_files)
        matched_terms = sorted([term for term in terms if term in lesson_text])
        if matches_file or matched_terms:
            bound.append({
                "id": failure.get("id"),
                "area": failure.get("area"),
                "files": failure.get("files", []),
                "lesson": failure.get("lesson"),
                "watch_for": failure.get("watch_for", []),
                "binding_reason": "file match" if matches_file else "goal term match",
                "matched_terms": matched_terms,
            })
    binder = {
        "schema_version": "eidolon.patch_context.historical_failure_binding.v1",
        "binding_id": _patch_context_id("failctx", {"files": sorted(selected_files), "failures": [f.get("id") for f in bound]}),
        "selected_files": sorted(file for file in selected_files if file),
        "bound_failure_count": len(bound),
        "bound_failures": bound,
        "source_mutation_performed": False,
        "patch_generation_performed": False,
    }
    rows = [
        {"name": "selector", "status": _report_gate_status(selector_report), "message": selector_report.get("message", "")},
        {"name": "failure-memory", "status": _report_gate_status(failure_report), "message": failure_report.get("message", "")},
        {"name": "bound-failures", "status": "pass" if bound else "warn", "message": f"{len(bound)} historical failure lessons bound to the selected context."},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.3", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "historical_failure_context_binder": binder, "rows": rows, "message": "Historical failure context binder attaches prior regressions and operator lessons to the patch context."}
    if save: _write_json(HISTORICAL_FAILURE_CONTEXT_BINDER, report)
    else: report["preview_only"] = True
    return report


def build_risk_aware_context_budgeter(project_id: str = "eidolon", patch_goal: str | None = None, max_total_lines: int = 1800, max_total_chars: int = 160_000, save: bool = True) -> dict[str, Any]:
    """v71.4: assign a bounded, risk-aware context budget to selected files."""
    selector_report = build_relevant_file_context_selector(project_id=project_id, patch_goal=patch_goal, save=False)
    selected = selector_report.get("relevant_file_context_selector", {}).get("selected_files", [])
    per_risk_lines = {"critical": 140, "high": 120, "medium": 90, "low": 60, "unknown": 60}
    budgeted_files: list[dict[str, Any]] = []
    total_lines = 0
    total_chars = 0
    for item in selected:
        risk = str(item.get("risk_level", "unknown"))
        allowed = per_risk_lines.get(risk, 60)
        size = int(item.get("size_bytes") or 0)
        est_chars = min(size, allowed * 110)
        total_lines += allowed
        total_chars += est_chars
        budgeted_files.append({
            "file": item.get("file"),
            "risk_level": risk,
            "risk_score": item.get("risk_score", 0),
            "max_context_lines": allowed,
            "estimated_context_chars": est_chars,
            "budget_reason": "larger slice for high-risk operator surfaces" if risk in {"critical", "high"} else "compact slice for localized/static files",
            "requires_summary_before_full_file": bool(size > est_chars),
        })
    over_lines = total_lines > max_total_lines
    over_chars = total_chars > max_total_chars
    budgeter = {
        "schema_version": "eidolon.patch_context.risk_aware_budget.v1",
        "budget_id": _patch_context_id("budget", {"files": budgeted_files, "limits": [max_total_lines, max_total_chars]}),
        "limits": {"max_total_lines": max_total_lines, "max_total_chars": max_total_chars},
        "estimated_total_lines": total_lines,
        "estimated_total_chars": total_chars,
        "budgeted_files": budgeted_files,
        "over_budget": over_lines or over_chars,
        "source_mutation_performed": False,
        "patch_generation_performed": False,
    }
    rows = [
        {"name": "selector", "status": _report_gate_status(selector_report), "message": selector_report.get("message", "")},
        {"name": "line-budget", "status": "pass" if not over_lines else "warn", "message": f"Estimated {total_lines} context lines against limit {max_total_lines}."},
        {"name": "char-budget", "status": "pass" if not over_chars else "warn", "message": f"Estimated {total_chars} context chars against limit {max_total_chars}."},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.4", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "risk_aware_context_budgeter": budgeter, "rows": rows, "message": "Risk-aware context budgeter limits file context while preserving more room for high-risk operator surfaces."}
    if save: _write_json(RISK_AWARE_CONTEXT_BUDGETER, report)
    else: report["preview_only"] = True
    return report


def build_verification_requirement_compiler(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.5: compile verification commands and manual checks from selected files and categories."""
    selector_report = build_relevant_file_context_selector(project_id=project_id, patch_goal=patch_goal, save=False)
    selector = selector_report.get("relevant_file_context_selector", {})
    verification_report = build_verification_command_map(project_id=project_id, save=False)
    verification_map = verification_report.get("verification_command_map", {})
    category_map = verification_map.get("category_command_map", {})
    file_examples = verification_map.get("file_examples", {})
    commands: list[str] = []
    manual_checks: list[str] = []
    for file_item in selector.get("selected_files", []):
        rel = file_item.get("file")
        category = file_item.get("category") or "default"
        for command in file_examples.get(rel, []) or category_map.get(category, []) or category_map.get("default", []):
            if "check" in command and not command.startswith("python"):
                manual_checks.append(command)
            else:
                commands.append(command)
    required_baseline = [
        "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
        "python tools/smoke_check.py --tier install",
        "python conscious_agent/main.py --patch-generation-context-builder --readiness-json",
    ]
    required_manual = [
        "README/release history consistency check",
        "package privacy scan",
        "custom data-tip hover regression check; no native title tooltips on nav tabs",
        "confirm context packet generated no patch and made no source/memory/publish/identity mutation",
    ]
    def dedupe(values: list[str]) -> list[str]:
        seen: set[str] = set()
        output: list[str] = []
        for value in values:
            if value and value not in seen:
                output.append(value)
                seen.add(value)
        return output
    compiled = {
        "schema_version": "eidolon.patch_context.verification_requirements.v1",
        "compiler_id": _patch_context_id("verifyctx", {"files": [f.get("file") for f in selector.get("selected_files", [])], "commands": commands}),
        "selected_files": [f.get("file") for f in selector.get("selected_files", [])],
        "required_commands": dedupe(required_baseline + commands),
        "required_manual_checks": dedupe(required_manual + manual_checks),
        "targeted_cli_gates": [
            "--patch-goal-intake-classifier", "--relevant-file-context-selector", "--historical-failure-context-binder",
            "--risk-aware-context-budgeter", "--verification-requirement-compiler", "--patch-prompt-context-packet-builder",
            "--context-completeness-reviewer", "--patch-context-dashboard-api-cli", "--pre-v72-patch-context-gate",
            "--patch-generation-context-builder",
        ],
        "source_mutation_performed": False,
        "patch_generation_performed": False,
    }
    rows = [
        {"name": "selector", "status": _report_gate_status(selector_report), "message": selector_report.get("message", "")},
        {"name": "verification-map", "status": _report_gate_status(verification_report), "message": verification_report.get("message", "")},
        {"name": "required-commands", "status": "pass" if compiled["required_commands"] else "blocked", "message": f"{len(compiled['required_commands'])} commands compiled."},
        {"name": "manual-checks", "status": "pass" if compiled["required_manual_checks"] else "blocked", "message": f"{len(compiled['required_manual_checks'])} manual checks compiled."},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.5", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "verification_requirement_compiler": compiled, "rows": rows, "message": "Verification requirement compiler binds selected files to commands, manual checks, and targeted context-builder gates."}
    if save: _write_json(VERIFICATION_REQUIREMENT_COMPILER, report)
    else: report["preview_only"] = True
    return report


def build_patch_prompt_context_packet_builder(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.6: assemble a reviewable prompt context packet for a future patch generator."""
    intake = build_patch_goal_intake_classifier(project_id=project_id, patch_goal=patch_goal, save=False)
    selector = build_relevant_file_context_selector(project_id=project_id, patch_goal=patch_goal, save=False)
    failures = build_historical_failure_context_binder(project_id=project_id, patch_goal=patch_goal, save=False)
    budget = build_risk_aware_context_budgeter(project_id=project_id, patch_goal=patch_goal, save=False)
    verification = build_verification_requirement_compiler(project_id=project_id, patch_goal=patch_goal, save=False)
    terms = intake.get("patch_goal_intake_classifier", {}).get("goal_terms", [])
    outlines = []
    budget_by_file = {item.get("file"): item for item in budget.get("risk_aware_context_budgeter", {}).get("budgeted_files", [])}
    for file_item in selector.get("relevant_file_context_selector", {}).get("selected_files", []):
        rel = file_item.get("file")
        if not rel:
            continue
        max_lines = int(budget_by_file.get(rel, {}).get("max_context_lines", 60))
        outlines.append(_outline_source_file(rel, terms, max_lines=min(max_lines, 100)))
    packet = {
        "schema_version": "eidolon.patch_context.prompt_packet.v1",
        "packet_id": _patch_context_id("packet", {"goal": intake.get("patch_goal_intake_classifier", {}).get("normalized_goal"), "files": [o.get("file") for o in outlines]}),
        "packet_type": "patch_generation_context_only",
        "goal": intake.get("patch_goal_intake_classifier", {}).get("normalized_goal"),
        "context_instructions": [
            "Use this packet only to understand the requested change before drafting a reviewed patch.",
            "Do not apply changes to live source from this packet.",
            "Do not publish releases, write memory, alter identity, run autonomous loops, or bypass approval gates.",
            "Respect historical failure lessons, especially dashboard route ordering, data-tip-only hover notes, version marker consistency, and package privacy.",
        ],
        "selected_files": selector.get("relevant_file_context_selector", {}).get("selected_files", []),
        "source_outlines": outlines,
        "historical_failures": failures.get("historical_failure_context_binder", {}).get("bound_failures", []),
        "risk_budget": budget.get("risk_aware_context_budgeter", {}),
        "verification_requirements": verification.get("verification_requirement_compiler", {}),
        "improvement_opportunities": build_improvement_opportunity_detector(project_id=project_id, save=False).get("improvement_opportunity_detector", {}).get("opportunities", []),
        "patch_generation_performed": False,
        "source_mutation_performed": False,
        "publish_approval_granted": False,
        "memory_approval_granted": False,
        "identity_approval_granted": False,
    }
    rows = [
        {"name": "intake", "status": _report_gate_status(intake), "message": intake.get("message", "")},
        {"name": "selector", "status": _report_gate_status(selector), "message": selector.get("message", "")},
        {"name": "failures", "status": _report_gate_status(failures), "message": failures.get("message", "")},
        {"name": "budget", "status": _report_gate_status(budget), "message": budget.get("message", "")},
        {"name": "verification", "status": _report_gate_status(verification), "message": verification.get("message", "")},
        {"name": "context-only", "status": "pass" if not packet["patch_generation_performed"] and not packet["source_mutation_performed"] else "blocked", "message": "Packet contains context and instructions only; no patch was generated or applied."},
    ]
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.6", "status": _status_from(rows), "ok": _ok_from(_status_from(rows)), "patch_prompt_context_packet_builder": packet, "rows": rows, "message": "Patch prompt context packet builder assembles the files, risks, historical failures, and verification requirements a future patch generator needs."}
    if save: _write_json(PATCH_PROMPT_CONTEXT_PACKET_BUILDER, report)
    else: report["preview_only"] = True
    return report


def build_context_completeness_reviewer(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.7: review whether a context packet is complete enough for patch drafting."""
    packet_report = build_patch_prompt_context_packet_builder(project_id=project_id, patch_goal=patch_goal, save=False)
    packet = packet_report.get("patch_prompt_context_packet_builder", {})
    selected = packet.get("selected_files", [])
    requirements = packet.get("verification_requirements", {})
    filenames = {item.get("file") for item in selected}
    rows = [
        {"name": "packet", "status": _report_gate_status(packet_report), "message": packet_report.get("message", "")},
        {"name": "goal", "status": "pass" if packet.get("goal") else "blocked", "message": "Context packet includes a normalized patch goal."},
        {"name": "files", "status": "pass" if len(selected) >= 3 else "blocked", "message": f"{len(selected)} selected files included."},
        {"name": "operator-surfaces", "status": "pass" if {"conscious_agent/main.py", "conscious_agent/api_server.py", "conscious_agent/dashboard.py"} & filenames else "warn", "message": "Operator-facing files are included when relevant."},
        {"name": "documentation", "status": "pass" if {"README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"} <= filenames else "warn", "message": "README and release history are included in the update context."},
        {"name": "historical-failures", "status": "pass" if packet.get("historical_failures") else "warn", "message": f"{len(packet.get('historical_failures') or [])} historical failure lessons included."},
        {"name": "verification", "status": "pass" if requirements.get("required_commands") and requirements.get("required_manual_checks") else "blocked", "message": "Verification commands and manual checks are present."},
        {"name": "safety-boundary", "status": "pass" if not packet.get("patch_generation_performed") and not packet.get("source_mutation_performed") and not packet.get("publish_approval_granted") and not packet.get("memory_approval_granted") and not packet.get("identity_approval_granted") else "blocked", "message": "No patch generation, source mutation, publish, memory, or identity authority is granted."},
    ]
    status = _status_from(rows)
    reviewer = {
        "schema_version": "eidolon.patch_context.completeness_review.v1",
        "review_id": _patch_context_id("review", {"packet": packet.get("packet_id"), "rows": rows}),
        "packet_id": packet.get("packet_id"),
        "ready_for_reviewed_patch_generation_prompt": status != "blocked",
        "blocking_gaps": [row for row in rows if row.get("status") == "blocked"],
        "warnings": [row for row in rows if row.get("status") == "warn"],
        "source_mutation_performed": False,
        "patch_generation_performed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.7", "status": status, "ok": _ok_from(status), "context_completeness_reviewer": reviewer, "rows": rows, "message": "Context completeness reviewer checks whether the patch context has goal, files, risks, history, verification, docs, and safety boundaries."}
    if save: _write_json(CONTEXT_COMPLETENESS_REVIEWER, report)
    else: report["preview_only"] = True
    return report


def build_patch_context_dashboard_api_cli(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.8: verify dashboard, API, and CLI exposure for the patch context builder."""
    dashboard_text = _read_source_text("conscious_agent/dashboard.py")
    api_text = _read_source_text("conscious_agent/api_server.py")
    cli_text = _read_source_text("conscious_agent/main.py")
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    required_cli = [
        "--patch-goal-intake-classifier", "--relevant-file-context-selector", "--historical-failure-context-binder",
        "--risk-aware-context-budgeter", "--verification-requirement-compiler", "--patch-prompt-context-packet-builder",
        "--context-completeness-reviewer", "--patch-context-dashboard-api-cli", "--pre-v72-patch-context-gate",
        "--patch-generation-context-builder",
    ]
    api_routes = [
        "/api/patch-context/goal", "/api/patch-context/files", "/api/patch-context/failures",
        "/api/patch-context/budget", "/api/patch-context/verification", "/api/patch-context/packet",
        "/api/patch-context/review", "/api/patch-context/gate", "/api/patch-context/layer",
    ]
    rows = [
        {"name": "dashboard-route", "status": "pass" if "/patch-context" in dashboard_text and "render_patch_context" in dashboard_text else "blocked", "message": "/patch-context route and renderer are present."},
        {"name": "api-routes", "status": "pass" if all(route in api_text or route.split("/api/")[-1].replace("/", "\", \"") in api_text for route in api_routes) else "blocked", "message": "Patch context API routes are exposed read-only."},
        {"name": "cli-flags", "status": "pass" if all(flag in cli_text for flag in required_cli) else "blocked", "message": "Patch context CLI flags are available."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard nav keeps custom data-tip hover notes only."},
        {"name": "docs", "status": "pass" if "v72.0 - Patch Generation Context Builder" in docs else "blocked", "message": "README/release history mention v72.0."},
    ]
    status = _status_from(rows)
    parity = {
        "schema_version": "eidolon.patch_context.dashboard_api_cli.v1",
        "parity_id": _patch_context_id("patchctxparity", rows),
        "dashboard_path": "/patch-context",
        "api_routes": api_routes,
        "cli_flags": required_cli,
        "custom_data_tip_only": not _dashboard_nav_title_regression_present(),
        "source_mutation_performed": False,
        "patch_generation_performed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.8", "status": status, "ok": _ok_from(status), "patch_context_dashboard_api_cli": parity, "rows": rows, "message": "Patch context dashboard/API/CLI exposes read-only context packets while preserving custom data-tip hover behavior."}
    if save: _write_json(PATCH_CONTEXT_DASHBOARD_API_CLI, report)
    else: report["preview_only"] = True
    return report


def build_pre_v72_patch_context_gate(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v71.9: final gate before declaring the v72 patch context builder complete."""
    parts = {
        "goal_intake": build_patch_goal_intake_classifier(project_id=project_id, patch_goal=patch_goal, save=False),
        "file_selector": build_relevant_file_context_selector(project_id=project_id, patch_goal=patch_goal, save=False),
        "failure_binder": build_historical_failure_context_binder(project_id=project_id, patch_goal=patch_goal, save=False),
        "budgeter": build_risk_aware_context_budgeter(project_id=project_id, patch_goal=patch_goal, save=False),
        "verification": build_verification_requirement_compiler(project_id=project_id, patch_goal=patch_goal, save=False),
        "packet": build_patch_prompt_context_packet_builder(project_id=project_id, patch_goal=patch_goal, save=False),
        "reviewer": build_context_completeness_reviewer(project_id=project_id, patch_goal=patch_goal, save=False),
        "dashboard_api_cli": build_patch_context_dashboard_api_cli(project_id=project_id, patch_goal=patch_goal, save=False),
        "privacy": build_package_privacy_scan(project_id=project_id, save=False),
    }
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in parts.items()]
    rows.extend([
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v72.0 - Patch Generation Context Builder" in docs else "blocked", "message": "README and release history mention v72.0."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs."},
    ])
    status = _status_from(rows)
    gate = {
        "schema_version": "eidolon.patch_context.pre_v72_gate.v1",
        "gate_id": _patch_context_id("prev72", {k: v.get("status") for k, v in parts.items()}),
        "steps": {k: _compact_step(v) for k, v in parts.items()},
        "source_mutation_performed": False,
        "patch_generation_performed": False,
        "approval_bypass_performed": False,
    }
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": "v71.9", "status": status, "ok": _ok_from(status), "pre_v72_patch_context_gate": gate, "rows": rows, "message": "Pre-v72 patch context gate verifies goal intake, file selection, failure binding, risk budgeting, verification, packet completeness, UI/API/CLI parity, privacy, docs, and tooltip safety."}
    if save: _write_json(PRE_V72_PATCH_CONTEXT_GATE, report)
    else: report["preview_only"] = True
    return report


def build_patch_generation_context_builder(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v72.0: complete read-only patch generation context builder."""
    packet_report = build_patch_prompt_context_packet_builder(project_id=project_id, patch_goal=patch_goal, save=False)
