# v72.1-v73.0 supervised patch draft composer runtime paths.
PATCH_DRAFT_DIR = DATA_DIR / "autonomy" / "patch_drafts"
PATCH_INTENT_NORMALIZER = SELF_MAINTENANCE_DIR / "patch_intent_normalizer.json"
PATCH_SCOPE_CONTRACT_BUILDER = SELF_MAINTENANCE_DIR / "patch_scope_contract_builder.json"
PATCH_PROMPT_COMPOSER = SELF_MAINTENANCE_DIR / "patch_prompt_composer.json"
PATCH_DRAFT_OUTPUT_SCHEMA = SELF_MAINTENANCE_DIR / "patch_draft_output_schema.json"
PATCH_DRAFT_SAFETY_REVIEWER = SELF_MAINTENANCE_DIR / "patch_draft_safety_reviewer.json"
PATCH_DRAFT_EVIDENCE_BINDER = SELF_MAINTENANCE_DIR / "patch_draft_evidence_binder.json"
PATCH_DRAFT_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "patch_draft_dashboard_api_cli.json"
LOCAL_MODEL_HANDOFF_STUB = SELF_MAINTENANCE_DIR / "local_model_handoff_stub.json"
PRE_V73_PATCH_DRAFT_GATE = SELF_MAINTENANCE_DIR / "pre_v73_patch_draft_gate.json"
SUPERVISED_PATCH_DRAFT_COMPOSER = SELF_MAINTENANCE_DIR / "supervised_patch_draft_composer.json"
DEFAULT_PATCH_DRAFT_GOAL = "Compose a supervised patch draft request for the next Eidolon improvement using v72 context, without applying source changes, publishing, mutating memory, altering identity, or bypassing approval gates."


def _patch_draft_tokens() -> list[str]:
    return [
        "patch-intent-normalizer", "patch-scope-contract-builder", "patch-prompt-composer",
        "patch-draft-output-schema", "patch-draft-safety-reviewer", "patch-draft-evidence-binder",
        "patch-draft-dashboard-api-cli", "local-model-handoff-stub", "pre-v73-patch-draft-gate",
        "supervised-patch-draft-composer", "patch-drafts", "data/autonomy/patch_drafts/",
    ]


def _normalize_patch_draft_goal(patch_goal: str | None = None) -> str:
    return _normalize_patch_goal(patch_goal or DEFAULT_PATCH_DRAFT_GOAL)


def _default_patch_draft_forbidden_behaviors() -> list[str]:
    return [
        "Do not apply source changes.",
        "Do not run generated code as an execution transaction.",
        "Do not publish release artifacts.",
        "Do not mutate durable memory or identity records.",
        "Do not bypass approval gates or consume approval records.",
        "Do not alter trust roots, signing keys, or private runtime data.",
        "Do not convert a prompt packet into an autonomous loop.",
    ]






def _compose_patch_prompt(intent: dict[str, Any], contract: dict[str, Any], packet: dict[str, Any], schema: dict[str, Any]) -> str:
    selected = packet.get("selected_files", [])[:10]
    source_notes = []
    for item in selected:
        source_notes.append(f"- {item.get('file')}: risk={item.get('risk_level', 'unknown')}; why={', '.join(item.get('why_selected', [])[:3])}")
    commands = packet.get("verification_requirements", {}).get("required_commands", [])
    failures = packet.get("historical_failures", [])[:6]
    failure_lines = [f"- {f.get('id')}: {f.get('lesson')}" for f in failures]
    return "\n".join([
        "You are drafting a supervised Eidolon patch proposal. Produce a reviewable draft only.",
        "Do not apply files, run transactions, publish releases, mutate memory, alter identity, or bypass approvals.",
        "",
        "PATCH GOAL:",
        str(intent.get("normalized_goal", "")),
        "",
        "SCOPE CONTRACT:",
        f"Allowed files: {', '.join(contract.get('allowed_files', []))}",
        f"Blocked patterns: {', '.join(contract.get('blocked_file_patterns', []))}",
        f"Max file count: {contract.get('max_file_count')} | Max diff lines: {contract.get('max_diff_lines')}",
        f"Required docs: {', '.join(contract.get('required_documentation_updates', []))}",
        "",
        "RELEVANT FILE CONTEXT:",
        "\n".join(source_notes) or "- No files selected. Stop and report missing context.",
        "",
        "HISTORICAL FAILURE WARNINGS:",
        "\n".join(failure_lines) or "- No bound historical failures; still avoid route shadowing, double tooltips, version drift, package leaks, and smoke bloat.",
        "",
        "VERIFICATION COMMANDS REQUIRED:",
        "\n".join([f"- {cmd}" for cmd in commands]) or "- python -m py_compile conscious_agent/*.py tools/smoke_check.py",
        "",
        "OUTPUT FORMAT:",
        json.dumps(schema.get("expected_output", {}), indent=2),
        "",
        "Return only a draft packet: summary, file-by-file plan, proposed unified diff or explicit no-diff explanation, risk notes, verification plan, rollback notes, and documentation update plan.",
    ])


















