# v71.1-v72.0 patch context tokens: patch-goal-intake-classifier relevant-file-context-selector historical-failure-context-binder risk-aware-context-budgeter verification-requirement-compiler patch-prompt-context-packet-builder context-completeness-reviewer patch-context-dashboard-api-cli pre-v72-patch-context-gate patch-generation-context-builder /patch-context /api/patch-context data/autonomy/patch_context/ source_mutation_performed=False patch_generation_performed=False no_native_title_tooltip


# v73 optimized build overrides: each public build uses one v72 packet instead of recursively rebuilding every substage.
def _build_patch_draft_core(project_id: str = "eidolon", patch_goal: str | None = None) -> dict[str, Any]:
    goal = _normalize_patch_draft_goal(patch_goal)
    intake_report = build_patch_goal_intake_classifier(project_id=project_id, patch_goal=goal, save=False)
    packet_report = build_patch_prompt_context_packet_builder(project_id=project_id, patch_goal=goal, save=False)
    packet = packet_report.get("patch_prompt_context_packet_builder", {})
    classifier = intake_report.get("patch_goal_intake_classifier", {})
    selected = packet.get("selected_files", [])
    context_summary = {
        "context_packet_id": packet.get("packet_id"),
        "selected_files": [item.get("file") for item in selected if item.get("file")],
        "required_commands": packet.get("verification_requirements", {}).get("required_commands", []),
        "required_manual_checks": packet.get("verification_requirements", {}).get("required_manual_checks", []),
    }
    intent = {
        "schema_version": "eidolon.patch_draft.intent.v1",
        "intent_id": _patch_context_id("intent", {"goal": goal, "context": context_summary.get("context_packet_id")}),
        "normalized_goal": goal,
        "requested_change": goal,
        "affected_capabilities": classifier.get("target_categories", []),
        "likely_files": classifier.get("likely_files", []),
        "expected_behavior": [
            "Produce a structured, reviewable patch draft prompt and packet.",
            "Use v72 codebase context, selected files, risk notes, history, and verification requirements.",
            "Keep every generated artifact advisory until a separate human-approved apply path exists.",
        ],
        "forbidden_behaviors": _default_patch_draft_forbidden_behaviors(),
        "safety_boundaries": {"draft_only": True, "context_packet_id": context_summary.get("context_packet_id"), "local_model_invoked": False, "patch_generated_by_eidolon": False, "source_mutation_performed": False, "publish_approval_granted": False, "memory_approval_granted": False, "identity_approval_granted": False, "approval_bypass_performed": False},
        "verification_expectations": context_summary.get("required_commands", []),
        "manual_review_expectations": context_summary.get("required_manual_checks", []),
    }
    allowed = []
    for item in selected:
        rel = item.get("file")
        if rel and rel not in allowed and (rel.endswith(".py") or rel.startswith("README_") or rel.startswith("tools/")):
            allowed.append(rel)
    for rel in intent.get("likely_files", []) + ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "tools/smoke_check.py"]:
        if rel and rel not in allowed and (rel.endswith(".py") or rel.startswith("README_") or rel.startswith("tools/")):
            allowed.append(rel)
    contract = {
        "schema_version": "eidolon.patch_draft.scope_contract.v1",
        "contract_id": _patch_context_id("scope", {"intent": intent.get("intent_id"), "allowed": allowed}),
        "intent_id": intent.get("intent_id"),
        "allowed_files": allowed[:24],
        "blocked_file_patterns": ["data/**", "*.zip", "*.log", "**/__pycache__/**", "data/signing/**", "data/memory/**", "data/identity/**", "release_packages/**", "backups/**", "dist/**", "build/**", ".git/**"],
        "max_file_count": min(max(len(allowed), 3), 12),
        "max_diff_lines": 900,
        "max_prompt_chars": 32000,
        "allowed_operation_types": ["explain", "propose", "draft_unified_diff", "draft_file_plan", "draft_verification_plan"],
        "blocked_operation_types": ["apply_diff", "write_source", "delete_source", "publish_release", "mutate_memory", "mutate_identity", "consume_approval", "run_autonomous_loop"],
        "required_documentation_updates": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "required_verification_commands": context_summary.get("required_commands", []),
        "manual_review_required": True,
        "high_risk_files": [item.get("file") for item in selected if str(item.get("risk_level", "")).lower() in {"high", "critical"}],
        "source_mutation_performed": False,
        "local_model_invoked": False,
    }
    expected_output = {
        "schema_version": "eidolon.patch_draft.model_output.v1",
        "summary": "string",
        "status": "draft|blocked|needs_more_context",
        "files": [{"path": "string", "operation": "modify|add|docs|test", "reason": "string", "risk": "low|medium|high"}],
        "unified_diff": "string or empty when no diff is proposed",
        "file_by_file_plan": ["string"],
        "risk_assessment": {"overall": "low|medium|high|blocked", "warnings": ["string"]},
        "verification_plan": {"commands": ["string"], "manual_checks": ["string"]},
        "rollback_notes": ["string"],
        "documentation_updates": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "safety_attestation": {"source_applied": False, "publish_attempted": False, "memory_mutated": False, "identity_mutated": False, "approval_bypassed": False},
    }
    schema = {"schema_version": "eidolon.patch_draft.output_schema.v1", "schema_id": _patch_context_id("schema", expected_output), "expected_output": expected_output, "required_top_level_fields": list(expected_output.keys()), "blocked_content": ["claims that files were applied", "approval consumption", "publish completion", "memory/identity mutation", "unbounded autonomous loop"], "source_mutation_performed": False, "local_model_invoked": False}
    prompt_text = _compose_patch_prompt(intent, contract, packet, schema)
    prompt = {"schema_version": "eidolon.patch_draft.prompt_composer.v1", "prompt_id": _patch_context_id("prompt", {"intent": intent.get("intent_id"), "contract": contract.get("contract_id"), "packet": packet.get("packet_id")}), "intent_id": intent.get("intent_id"), "contract_id": contract.get("contract_id"), "context_packet_id": packet.get("packet_id"), "output_schema_id": schema.get("schema_id"), "prompt": prompt_text[: int(contract.get("max_prompt_chars", 32000))], "prompt_char_count": min(len(prompt_text), int(contract.get("max_prompt_chars", 32000))), "truncated": len(prompt_text) > int(contract.get("max_prompt_chars", 32000)), "local_model_invoked": False, "source_mutation_performed": False}
    return {"goal": goal, "intake_report": intake_report, "packet_report": packet_report, "packet": packet, "context_summary": context_summary, "intent": intent, "contract": contract, "schema": schema, "prompt": prompt}


def _report_from_rows(stage: str, key: str, payload: dict[str, Any], rows: list[dict[str, Any]], project_id: str, message: str, save_path: Path | None, save: bool) -> dict[str, Any]:
    status = _status_from(rows)
    report = {"version": SELF_MAINTENANCE_VERSION, "checked_at": _now(), "project_id": project_id, "stage": stage, "status": status, "ok": _ok_from(status), key: payload, "rows": rows, "message": message}
    if save and save_path is not None:
        _write_json(save_path, report)
    elif not save:
        report["preview_only"] = True
    return report


def build_patch_intent_normalizer(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    core = _build_patch_draft_core(project_id, patch_goal)
    intent = core["intent"]
    rows = [
        {"name": "goal", "status": "pass" if intent.get("normalized_goal") else "blocked", "message": "Patch draft goal normalized."},
        {"name": "v72-packet", "status": _report_gate_status(core["packet_report"]), "message": core["packet_report"].get("message", "")},
        {"name": "draft-only", "status": "pass" if intent.get("safety_boundaries", {}).get("draft_only") and not intent.get("safety_boundaries", {}).get("source_mutation_performed") else "blocked", "message": "Intent grants draft/prompt authority only."},
        {"name": "forbidden-behaviors", "status": "pass" if len(intent.get("forbidden_behaviors", [])) >= 6 else "blocked", "message": f"{len(intent.get('forbidden_behaviors', []))} forbidden behavior rules attached."},
    ]
    return _report_from_rows("v72.1", "patch_intent_normalizer", intent, rows, project_id, "Patch intent normalizer converts an operator goal into a strict draft-only patch intent.", PATCH_INTENT_NORMALIZER, save)


def build_patch_scope_contract_builder(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    core = _build_patch_draft_core(project_id, patch_goal)
    contract = core["contract"]
    rows = [
        {"name": "allowed-files", "status": "pass" if contract.get("allowed_files") else "blocked", "message": f"{len(contract.get('allowed_files', []))} files allowed in draft scope."},
        {"name": "documentation-required", "status": "pass" if set(contract.get("required_documentation_updates", [])) <= set(contract.get("allowed_files", [])) else "blocked", "message": "README and release history are mandatory draft targets."},
        {"name": "mutation-operations-blocked", "status": "pass" if "apply_diff" in contract.get("blocked_operation_types", []) and "write_source" in contract.get("blocked_operation_types", []) else "blocked", "message": "Apply/write operations are explicitly blocked."},
    ]
    return _report_from_rows("v72.2", "patch_scope_contract_builder", contract, rows, project_id, "Patch scope contract builder limits which files and operations a future draft may discuss.", PATCH_SCOPE_CONTRACT_BUILDER, save)




def build_patch_prompt_composer(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    core = _build_patch_draft_core(project_id, patch_goal)
    prompt = core["prompt"]
    rows = [
        {"name": "v72-packet", "status": _report_gate_status(core["packet_report"]), "message": core["packet_report"].get("message", "")},
        {"name": "prompt", "status": "pass" if "Do not apply" in prompt.get("prompt", "") and prompt.get("prompt_char_count", 0) > 500 else "blocked", "message": f"Prompt composed with {prompt.get('prompt_char_count', 0)} characters."},
        {"name": "model-not-invoked", "status": "pass" if not prompt.get("local_model_invoked") else "blocked", "message": "Composer exports prompt text only."},
    ]
    return _report_from_rows("v72.3", "patch_prompt_composer", prompt, rows, project_id, "Patch prompt composer creates a structured prompt for a local coding model without invoking it.", PATCH_PROMPT_COMPOSER, save)


def build_patch_draft_safety_reviewer(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, save: bool = True) -> dict[str, Any]:
    core = _build_patch_draft_core(project_id, patch_goal)
    text = draft_text if draft_text is not None else core["prompt"].get("prompt", "")
    lowered = str(text).lower()
    checks = {"source_apply_claim": any(term in lowered for term in ["applied the patch", "source_applied: true", "files were written", "wrote source"]), "publish_claim": any(term in lowered for term in ["published release", "publish_attempted: true", "release uploaded"]), "memory_identity_claim": any(term in lowered for term in ["memory_mutated: true", "identity_mutated: true", "updated identity", "wrote memory"]), "approval_bypass_claim": any(term in lowered for term in ["approval_bypassed: true", "bypassed approval", "consumed approval"]), "autonomous_loop_claim": any(term in lowered for term in ["run autonomously", "continuous self-modification", "without operator review"])}
    blocked = [name for name, value in checks.items() if value]
    mentioned_paths = set(re.findall(r"(?:conscious_agent|tools|data)/[A-Za-z0-9_./-]+|README_[A-Z_]+\.md", str(text)))
    allowed_files = set(core["contract"].get("allowed_files", []))
    out_of_scope = sorted([path for path in mentioned_paths if path not in allowed_files and not path.startswith("data/autonomy/patch_drafts")])
    rows = [{"name": "forbidden-claims", "status": "blocked" if blocked else "pass", "message": ", ".join(blocked) if blocked else "No forbidden apply/publish/memory/identity/approval/autonomy claims found."}, {"name": "scope", "status": "warn" if out_of_scope else "pass", "message": f"Out-of-scope path mentions: {', '.join(out_of_scope[:8])}" if out_of_scope else "Path mentions stay within the draft scope contract."}, {"name": "documentation", "status": "pass" if "README_NEXT_STEPS.md" in str(text) and "README_RELEASE_HISTORY.md" in str(text) else "warn", "message": "Draft prompt includes documentation update reminders."}]
    status = _status_from(rows)
