    safety = {"schema_version": "eidolon.patch_draft.safety_review.v1", "review_id": _patch_context_id("draftsafe", prompt.get("prompt_id")), "prompt_id": prompt.get("prompt_id"), "reviewed_text_kind": "composed_prompt", "blocked_findings": [], "out_of_scope_paths": [], "ready_for_operator_review": True, "source_mutation_performed": False, "local_model_invoked": False, "approval_bypass_performed": False}
