def _patch_draft_schema_payload() -> dict[str, Any]:
    expected_output = {
        "schema_version": "eidolon.patch_draft.model_output.v1",
        "summary": "string",
        "status": "draft|blocked|needs_more_context",
        "files": [{"path": "string", "operation": "modify|add|docs|test", "reason": "string", "risk": "low|medium|high"}],
        "unified_diff": "string or empty when no diff is proposed",
        "file_by_file_plan": ["string"],
        "risk_assessment": {"overall": "low|medium|high|blocked", "warnings": ["string"]},
        "verification_plan": {"commands": ["string"], "manual_checks": ["string"]},
        "rollback_notes": ["string"],
        "documentation_updates": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "safety_attestation": {"source_applied": False, "publish_attempted": False, "memory_mutated": False, "identity_mutated": False, "approval_bypassed": False},
    }
    return {"schema_version": "eidolon.patch_draft.output_schema.v1", "schema_id": _patch_context_id("schema", expected_output), "expected_output": expected_output, "required_top_level_fields": list(expected_output.keys()), "blocked_content": ["claims that files were applied", "approval consumption", "publish completion", "memory/identity mutation", "unbounded autonomous loop"], "source_mutation_performed": False, "local_model_invoked": False}


