# v74.1-v75.0 sandbox patch trial runner layer.
PATCH_TRIAL_DIR = DATA_DIR / "autonomy" / "patch_trials"
PATCH_TRIAL_INTAKE_BINDER = SELF_MAINTENANCE_DIR / "patch_trial_intake_binder.json"
PATCH_TRIAL_WORKSPACE_BUILDER = SELF_MAINTENANCE_DIR / "patch_trial_workspace_builder.json"
PATCH_TRIAL_MATERIALIZER = SELF_MAINTENANCE_DIR / "patch_trial_materializer.json"
PATCH_TRIAL_VERIFICATION_RUNNER = SELF_MAINTENANCE_DIR / "patch_trial_verification_runner.json"
PATCH_TRIAL_EVIDENCE_COLLECTOR = SELF_MAINTENANCE_DIR / "patch_trial_evidence_collector.json"
PATCH_TRIAL_ESCAPE_MUTATION_GUARD = SELF_MAINTENANCE_DIR / "patch_trial_escape_mutation_guard.json"
PATCH_TRIAL_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "patch_trial_dashboard_api_cli.json"
PATCH_TRIAL_CLEANUP_RETENTION = SELF_MAINTENANCE_DIR / "patch_trial_cleanup_retention.json"
PRE_V75_SANDBOX_TRIAL_GATE = SELF_MAINTENANCE_DIR / "pre_v75_sandbox_trial_gate.json"
SANDBOX_PATCH_TRIAL_RUNNER = SELF_MAINTENANCE_DIR / "sandbox_patch_trial_runner.json"
_PATCH_TRIAL_CORE_CACHE: dict[str, dict[str, Any]] = {}


def _normalize_patch_trial_goal(patch_goal: str | None = None) -> str:
    goal = (patch_goal or "Trial a reviewed patch proposal in a disposable sandbox workspace without touching the live Eidolon source tree.").strip()
    return re.sub(r"\s+", " ", goal)[:800]


def _patch_trial_id(goal: str, draft_hash: str, trial_id: str | None = None) -> str:
    if trial_id:
        cleaned = re.sub(r"[^a-zA-Z0-9_.-]+", "-", str(trial_id)).strip(".-_")[:80]
        return cleaned or _patch_context_id("trial", {"goal": goal, "draft": draft_hash})[:24]
    return _patch_context_id("trial", {"goal": goal, "draft": draft_hash})[:24]


def _patch_trial_path(trial_id: str) -> Path:
    root = PATCH_TRIAL_DIR.resolve()
    path = (PATCH_TRIAL_DIR / trial_id).resolve()
    if root != path and root not in path.parents:
        raise ValueError("unsafe patch trial id resolved outside patch trial root")
    return path


def _patch_trial_workspace_path(trial_id: str) -> Path:
    return _patch_trial_path(trial_id) / "workspace" / "Eidolon"


def _patch_trial_safe_rel(rel: str) -> bool:
    rel = str(rel).replace("\\", "/").strip("/")
    if not rel or rel.startswith("/") or ".." in Path(rel).parts:
        return False
    blocked_prefixes = ("data/autonomy/", "data/self_maintenance/", "data/backups/", ".git/", "__pycache__/")
    return not rel.startswith(blocked_prefixes)


def _patch_trial_manifest() -> dict[str, Any]:
    manifest = _source_manifest(project_id="eidolon")
    return {
        "manifest_sha256": manifest.get("manifest_sha256"),
        "file_count": manifest.get("file_count"),
        "entries": manifest.get("entries", []),
        "drift_tolerant_count": manifest.get("drift_tolerant_count", 0),
    }


def _patch_trial_review_report(project_id: str, patch_goal: str | None, draft_text: str | None, draft_file: str | None) -> dict[str, Any]:
    return build_patch_review_report_builder(project_id=project_id, patch_goal=patch_goal, draft_text=draft_text, draft_file=draft_file, save=False)


def _build_patch_trial_core(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None) -> dict[str, Any]:
    goal = _normalize_patch_trial_goal(patch_goal)
    text, source = _read_patch_review_draft_text(draft_text=draft_text, draft_file=draft_file, patch_goal=goal)
    draft_hash = hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest()
    tid = _patch_trial_id(goal, draft_hash, trial_id)
    cache_key = _patch_context_id("trialcore", {"project": project_id, "goal": goal, "draft": draft_hash, "trial": tid})
    cached = _PATCH_TRIAL_CORE_CACHE.get(cache_key)
    if cached is not None:
        return cached
    review = _patch_trial_review_report(project_id, goal, text, None)
    review_payload = review.get("patch_review_report_builder", {})
    decision = str(review_payload.get("decision") or review.get("status") or "unknown").lower()
    risk_level = str(review_payload.get("risk_level") or "unknown").lower()
    files = review_payload.get("touched_files") or [item.get("path") for item in _patch_review_diff_files(text) if item.get("path")]
    eligible = decision != "blocked" and review.get("status") != "blocked" and review.get("ok") is not False
    core = {
        "project_id": project_id,
        "goal": goal,
        "draft_text": text,
        "draft_source": source,
        "draft_hash": draft_hash,
        "trial_id": tid,
        "trial_path": str(_patch_trial_path(tid)),
        "workspace_path": str(_patch_trial_workspace_path(tid)),
        "review_report": review,
        "review_decision": decision,
        "risk_level": risk_level,
        "eligible": eligible,
        "touched_files": sorted(set(str(f) for f in files if f)),
        "pre_manifest": _patch_trial_manifest(),
    }
    _PATCH_TRIAL_CORE_CACHE[cache_key] = core
    if len(_PATCH_TRIAL_CORE_CACHE) > 6:
        try:
            _PATCH_TRIAL_CORE_CACHE.pop(next(iter(_PATCH_TRIAL_CORE_CACHE)))
        except StopIteration:
            pass
    return core


def _patch_trial_write_metadata(trial_path: Path, name: str, payload: dict[str, Any]) -> None:
    trial_path.mkdir(parents=True, exist_ok=True)
    write_text_atomic((trial_path / name), json.dumps(payload, indent=2, default=str), encoding="utf-8")


def _patch_trial_copy_workspace(workspace: Path) -> tuple[bool, str]:
    trial_root = workspace.parents[1]
    try:
        root_resolved = PATCH_TRIAL_DIR.resolve()
        if root_resolved not in trial_root.resolve().parents and trial_root.resolve() != root_resolved:
            return False, "workspace is outside data/autonomy/patch_trials"
        if workspace.exists():
            shutil.rmtree(workspace.parents[1])
        def ignore(dirpath: str, names: list[str]) -> set[str]:
            ignored = {".git", ".venv", "venv", "__pycache__", ".pytest_cache", ".mypy_cache"}.intersection(names)
            if Path(dirpath).resolve() == ROOT_DIR.resolve() and "data" in names:
                # Runtime state is not needed for sandbox code verification; copy the minimal public data below.
                ignored.add("data")
            return ignored
        shutil.copytree(ROOT_DIR, workspace, ignore=ignore)
        (workspace / "data" / "workspaces").mkdir(parents=True, exist_ok=True)
        for rel in ("data/projects.json", "data/settings.json", "data/signing/trusted_public_keys.json", "data/workspaces/projects.json", "data/workspaces/active_project.json"):
            src = ROOT_DIR / rel
            dst = workspace / rel
            if src.exists():
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, dst)
        return True, "workspace copied into disposable patch-trial directory"
    except Exception as error:
        return False, str(error)


def _patch_trial_additions_by_file(text: str) -> dict[str, list[str]]:
    additions: dict[str, list[str]] = {}
    current: str | None = None
    for raw in text.splitlines():
        line = raw.rstrip("\n")
        git_match = re.match(r"diff --git a/(.+?) b/(.+)$", line.strip())
        if git_match:
            current = git_match.group(2)
            additions.setdefault(current, [])
            continue
        if line.startswith("+++ b/"):
            current = line[6:].strip()
            additions.setdefault(current, [])
            continue
        if current and line.startswith("+") and not line.startswith("+++"):
            additions.setdefault(current, []).append(line[1:])
    return additions


def _patch_trial_materialize_into_workspace(core: dict[str, Any], workspace: Path) -> dict[str, Any]:
    trial_path = _patch_trial_path(core["trial_id"])
    text = core["draft_text"]
    write_text_atomic((trial_path / "patch_input.txt"), text, encoding="utf-8")
    additions = _patch_trial_additions_by_file(text)
    materialized: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    unsafe: list[str] = []
    for rel, lines in sorted(additions.items()):
        rel = rel.replace("\\", "/").strip("/")
        if not _patch_trial_safe_rel(rel):
            unsafe.append(rel)
            continue
        target = (workspace / rel).resolve()
        if workspace.resolve() not in target.parents and target != workspace.resolve():
            unsafe.append(rel)
            continue
        if not lines:
            continue
        if rel.endswith(".md"):
            target.parent.mkdir(parents=True, exist_ok=True)
            old = target.read_text(encoding="utf-8", errors="replace") if target.exists() else ""
            block = "\n".join(lines).strip()
            if block and block not in old:
                write_text_atomic(target, block + "\n\n" + old, encoding="utf-8")
            materialized.append({"path": rel, "mode": "sandbox_docs_additions", "line_count": len(lines)})
        else:
            skipped.append({"path": rel, "mode": "source_preview_only", "reason": "v75 keeps non-document source edits as patch_input evidence unless a later sandbox applier validates structured diffs"})
    payload = {
        "schema_version": "eidolon.patch_trial.materialization_result.v1",
        "trial_id": core["trial_id"],
        "workspace_path": str(workspace),
        "patch_input_path": str(trial_path / "patch_input.txt"),
        "materialized_files": materialized,
        "preview_only_files": skipped,
        "unsafe_paths": unsafe,
        "source_mutation_performed": False,
        "live_source_mutation_performed": False,
    }
    _patch_trial_write_metadata(trial_path, "materialization.json", payload)
    return payload


def _patch_trial_run_command(workspace: Path, cmd: list[str], timeout: int = 60) -> dict[str, Any]:
    started = datetime.now()
    try:
        proc = subprocess.run(cmd, cwd=workspace, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
        status = "pass" if proc.returncode == 0 else "blocked"
        return {
            "command": " ".join(cmd),
            "exit_code": proc.returncode,
            "status": status,
            "ok": proc.returncode == 0,
            "duration_seconds": round((datetime.now() - started).total_seconds(), 3),
            "stdout_excerpt": proc.stdout[-4000:],
            "stderr_excerpt": proc.stderr[-4000:],
        }
    except subprocess.TimeoutExpired as error:
        return {"command": " ".join(cmd), "exit_code": None, "status": "blocked", "ok": False, "duration_seconds": timeout, "stdout_excerpt": (error.stdout or "")[-1000:] if isinstance(error.stdout, str) else "", "stderr_excerpt": "timeout"}
    except Exception as error:
        return {"command": " ".join(cmd), "exit_code": None, "status": "blocked", "ok": False, "duration_seconds": round((datetime.now() - started).total_seconds(), 3), "stdout_excerpt": "", "stderr_excerpt": str(error)}


def build_patch_trial_intake_binder(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v74.1: bind v74 review eligibility before a sandbox trial can begin."""
    core = _build_patch_trial_core(project_id, patch_goal, draft_text, draft_file, trial_id)
    payload = {
        "schema_version": "eidolon.patch_trial.intake_binder.v1",
        "trial_id": core["trial_id"],
        "normalized_goal": core["goal"],
        "draft_hash": core["draft_hash"],
        "draft_source": core["draft_source"],
        "review_decision": core["review_decision"],
        "risk_level": core["risk_level"],
        "eligible_for_sandbox_trial": core["eligible"],
        "touched_files": core["touched_files"],
        "source_mutation_performed": False,
        "live_source_mutation_performed": False,
    }
    rows = [
        {"name": "review-bound", "status": "pass" if core["review_report"].get("status") != "blocked" else "blocked", "message": f"v74 review decision={core['review_decision']} risk={core['risk_level']}"},
        {"name": "eligible", "status": "pass" if core["eligible"] else "blocked", "message": "Reviewed patch may enter sandbox trial." if core["eligible"] else "Blocked v74 reviews cannot enter sandbox trial."},
        {"name": "draft-loaded", "status": "pass" if core["draft_text"].strip() else "blocked", "message": f"draft hash={core['draft_hash'][:12]}"},
        {"name": "review-only-boundary", "status": "pass", "message": "Intake only binds evidence; no workspace or source mutation occurs."},
    ]
    return _report_from_rows("v74.1", "patch_trial_intake_binder", payload, rows, project_id, "Sandbox trial intake binder requires a non-blocked v74 review before any disposable workspace trial can start.", PATCH_TRIAL_INTAKE_BINDER, save)


def build_disposable_workspace_builder(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v74.2: create a disposable workspace under data/autonomy/patch_trials."""
    core = _build_patch_trial_core(project_id, patch_goal, draft_text, draft_file, trial_id)
    trial_path = _patch_trial_path(core["trial_id"])
    workspace = _patch_trial_workspace_path(core["trial_id"])
    copied, message = (False, "v74 review blocked; workspace creation refused")
    if core["eligible"]:
        PATCH_TRIAL_DIR.mkdir(parents=True, exist_ok=True)
        copied, message = _patch_trial_copy_workspace(workspace)
    metadata = {
        "schema_version": "eidolon.patch_trial.workspace.v1",
        "trial_id": core["trial_id"],
        "trial_path": str(trial_path),
        "workspace_path": str(workspace),
        "created": bool(copied),
        "pre_manifest_sha256": core["pre_manifest"].get("manifest_sha256"),
        "package_exclusion_root": "data/autonomy/patch_trials/",
        "live_source_mutation_performed": False,
    }
    if copied:
        _patch_trial_write_metadata(trial_path, "trial_metadata.json", metadata | {"patch_goal": core["goal"], "draft_hash": core["draft_hash"], "created_at": _now()})
    rows = [
        {"name": "eligible", "status": "pass" if core["eligible"] else "blocked", "message": "v74 review permits disposable trial." if core["eligible"] else "v74 review blocked trial."},
        {"name": "workspace-created", "status": "pass" if copied and workspace.exists() else "blocked", "message": message},
        {"name": "inside-trial-root", "status": "pass" if str(workspace).replace("\\", "/").find("data/autonomy/patch_trials/") >= 0 else "blocked", "message": str(workspace)},
        {"name": "live-source-unchanged", "status": "pass", "message": "Workspace builder copies to sandbox only."},
    ]
    return _report_from_rows("v74.2", "disposable_workspace_builder", metadata, rows, project_id, "Disposable workspace builder copies Eidolon into data/autonomy/patch_trials without touching the live source tree.", PATCH_TRIAL_WORKSPACE_BUILDER, save)


def build_patch_draft_materializer(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v74.3: materialize a reviewed patch proposal inside the sandbox only."""
    core = _build_patch_trial_core(project_id, patch_goal, draft_text, draft_file, trial_id)
    workspace = _patch_trial_workspace_path(core["trial_id"])
    if not workspace.exists():
        build_disposable_workspace_builder(project_id, patch_goal, draft_text, draft_file, core["trial_id"], save=True)
    materialized = _patch_trial_materialize_into_workspace(core, workspace) if core["eligible"] and workspace.exists() else {"materialized_files": [], "preview_only_files": [], "unsafe_paths": [], "live_source_mutation_performed": False}
    rows = [
        {"name": "workspace", "status": "pass" if workspace.exists() else "blocked", "message": str(workspace)},
        {"name": "unsafe-paths", "status": "blocked" if materialized.get("unsafe_paths") else "pass", "message": ", ".join(materialized.get("unsafe_paths", [])) or "No unsafe paths."},
        {"name": "materialized", "status": "pass" if materialized.get("materialized_files") or materialized.get("preview_only_files") else "warn", "message": f"docs={len(materialized.get('materialized_files', []))}, preview_only={len(materialized.get('preview_only_files', []))}"},
        {"name": "sandbox-only", "status": "pass", "message": "Materialization writes only under the disposable trial workspace and trial metadata directory."},
    ]
    return _report_from_rows("v74.3", "patch_draft_materializer", materialized, rows, project_id, "Patch draft materializer stages reviewed patch content inside the sandbox only and refuses unsafe paths.", PATCH_TRIAL_MATERIALIZER, save)


def build_sandbox_verification_runner(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v74.4: run verification commands in the sandbox workspace only."""
    core = _build_patch_trial_core(project_id, patch_goal, draft_text, draft_file, trial_id)
    workspace = _patch_trial_workspace_path(core["trial_id"])
    if not workspace.exists():
        build_patch_draft_materializer(project_id, patch_goal, draft_text, draft_file, core["trial_id"], save=True)
    commands = [
        [sys.executable, "-m", "compileall", "-q", "conscious_agent", "tools"],
        [sys.executable, "conscious_agent/main.py", "--status"],
    ]
    results = [_patch_trial_run_command(workspace, cmd, timeout=90) for cmd in commands] if workspace.exists() else []
    trial_path = _patch_trial_path(core["trial_id"])
    payload = {
        "schema_version": "eidolon.patch_trial.verification.v1",
        "trial_id": core["trial_id"],
        "workspace_path": str(workspace),
        "commands": results,
        "failed_commands": [item for item in results if item.get("status") == "blocked"],
        "all_passed": bool(results) and all(item.get("ok") for item in results),
        "live_source_mutation_performed": False,
    }
    if workspace.exists():
        _patch_trial_write_metadata(trial_path, "verification.json", payload)
    rows = [
        {"name": "workspace", "status": "pass" if workspace.exists() else "blocked", "message": str(workspace)},
        {"name": "compile", "status": results[0].get("status", "blocked") if results else "blocked", "message": results[0].get("stderr_excerpt", "")[:200] if results else "not run"},
        {"name": "status-command", "status": results[1].get("status", "blocked") if len(results) > 1 else "blocked", "message": "main status ran inside sandbox" if len(results) > 1 and results[1].get("ok") else "not run"},
        {"name": "sandbox-cwd", "status": "pass" if str(workspace).replace("\\", "/").find("data/autonomy/patch_trials/") >= 0 else "blocked", "message": "verification cwd is the disposable workspace"},
    ]
    return _report_from_rows("v74.4", "sandbox_verification_runner", payload, rows, project_id, "Sandbox verification runner executes compile/status checks inside the disposable workspace only.", PATCH_TRIAL_VERIFICATION_RUNNER, save)


def build_sandbox_evidence_collector(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v74.5: collect sandbox trial evidence."""
    core = _build_patch_trial_core(project_id, patch_goal, draft_text, draft_file, trial_id)
    materializer = build_patch_draft_materializer(project_id, patch_goal, draft_text, draft_file, core["trial_id"], save=False)
    verification = build_sandbox_verification_runner(project_id, patch_goal, draft_text, draft_file, core["trial_id"], save=False)
    payload = {
        "schema_version": "eidolon.patch_trial.evidence.v1",
        "evidence_id": _patch_context_id("trialevidence", {"trial": core["trial_id"], "verify": verification.get("status")}),
        "trial_id": core["trial_id"],
        "patch_goal": core["goal"],
        "draft_hash": core["draft_hash"],
        "review_decision": core["review_decision"],
        "risk_level": core["risk_level"],
        "touched_files": core["touched_files"],
        "materializer_status": materializer.get("status"),
        "verification_status": verification.get("status"),
        "verification_commands": verification.get("sandbox_verification_runner", {}).get("commands", []),
        "recommendation": "operator_review" if verification.get("status") != "blocked" else "fix_before_retry",
        "live_source_mutation_performed": False,
        "promotion_performed": False,
    }
    _patch_trial_write_metadata(_patch_trial_path(core["trial_id"]), "evidence.json", payload)
    rows = [
        {"name": "review", "status": "pass" if core["eligible"] else "blocked", "message": f"decision={core['review_decision']} risk={core['risk_level']}"},
        {"name": "materializer", "status": _report_gate_status(materializer), "message": materializer.get("message", "")},
        {"name": "verification", "status": _report_gate_status(verification), "message": verification.get("message", "")},
        {"name": "promotion", "status": "pass", "message": "Evidence is collected only; no promotion to live source exists in v75."},
    ]
    return _report_from_rows("v74.5", "sandbox_evidence_collector", payload, rows, project_id, "Sandbox evidence collector binds review, materialization, verification, and operator recommendation without promotion.", PATCH_TRIAL_EVIDENCE_COLLECTOR, save)


def build_sandbox_escape_mutation_guard(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v74.6: prove the live source manifest did not change during sandbox trial."""
    core = _build_patch_trial_core(project_id, patch_goal, draft_text, draft_file, trial_id)
    pre = core["pre_manifest"]
    post = _patch_trial_manifest()
    workspace = _patch_trial_workspace_path(core["trial_id"])
    same = pre.get("manifest_sha256") == post.get("manifest_sha256")
    payload = {
        "schema_version": "eidolon.patch_trial.escape_guard.v1",
        "trial_id": core["trial_id"],
        "pre_manifest_sha256": pre.get("manifest_sha256"),
        "post_manifest_sha256": post.get("manifest_sha256"),
        "live_source_unchanged": same,
        "workspace_path": str(workspace),
        "workspace_inside_sandbox": str(workspace).replace("\\", "/").find("data/autonomy/patch_trials/") >= 0,
        "package_exclusion_root": "data/autonomy/patch_trials/",
        "live_source_mutation_performed": not same,
    }
    _patch_trial_write_metadata(_patch_trial_path(core["trial_id"]), "escape_guard.json", payload)
    rows = [
        {"name": "manifest-unchanged", "status": "pass" if same else "blocked", "message": f"pre={pre.get('manifest_sha256')} post={post.get('manifest_sha256')}"},
        {"name": "sandbox-location", "status": "pass" if payload["workspace_inside_sandbox"] else "blocked", "message": str(workspace)},
        {"name": "package-privacy-root", "status": "pass", "message": "data/autonomy/patch_trials/ is under source-only package exclusion rules."},
    ]
    return _report_from_rows("v74.6", "sandbox_escape_mutation_guard", payload, rows, project_id, "Sandbox escape/mutation guard compares source manifests and verifies the workspace stayed inside the excluded sandbox root.", PATCH_TRIAL_ESCAPE_MUTATION_GUARD, save)


