# v76.1-v77.0 operator-approved patch application layer.
PATCH_APPLICATION_DIR = DATA_DIR / "autonomy" / "patch_applications"
PATCH_APPROVAL_INTAKE_CONTRACT = SELF_MAINTENANCE_DIR / "patch_approval_intake_contract.json"
RECOMMENDATION_APPROVAL_BINDER = SELF_MAINTENANCE_DIR / "recommendation_approval_binder.json"
LIVE_SOURCE_SNAPSHOT_BUILDER = SELF_MAINTENANCE_DIR / "live_source_snapshot_builder.json"
APPROVED_PATCH_MATERIALIZER = SELF_MAINTENANCE_DIR / "approved_patch_materializer.json"
POST_APPLY_VERIFICATION_RUNNER = SELF_MAINTENANCE_DIR / "post_apply_verification_runner.json"
AUTOMATIC_ROLLBACK_EXECUTOR = SELF_MAINTENANCE_DIR / "automatic_rollback_executor.json"
APPLICATION_EVIDENCE_RECORDER = SELF_MAINTENANCE_DIR / "application_evidence_recorder.json"
PATCH_APPLICATION_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "patch_application_dashboard_api_cli.json"
PRE_V77_APPLICATION_GATE = SELF_MAINTENANCE_DIR / "pre_v77_application_gate.json"
OPERATOR_APPROVED_PATCH_APPLICATION_LAYER = SELF_MAINTENANCE_DIR / "operator_approved_patch_application_layer.json"
PATCH_APPLICATION_APPROVAL_PHRASE = "APPROVE PATCH APPLICATION"
_PATCH_APPLICATION_CORE_CACHE: dict[str, dict[str, Any]] = {}


def _normalize_patch_application_goal(patch_goal: str | None = None) -> str:
    goal = (patch_goal or "Apply an already reviewed, sandbox-tested, and recommendation-bound patch only after explicit operator approval, with rollback snapshot and post-apply verification.").strip()
    return re.sub(r"\s+", " ", goal)[:800]


def _patch_application_id(goal: str, recommendation_id: str, application_id: str | None = None) -> str:
    if application_id:
        cleaned = re.sub(r"[^a-zA-Z0-9_.-]+", "-", str(application_id)).strip(".-_")[:80]
        if cleaned:
            return cleaned
    return _patch_context_id("application", {"goal": goal, "recommendation": recommendation_id})[:28]


def _patch_application_path(application_id: str) -> Path:
    root = PATCH_APPLICATION_DIR.resolve()
    path = (PATCH_APPLICATION_DIR / application_id).resolve()
    if root != path and root not in path.parents:
        raise ValueError("unsafe patch application id resolved outside application root")
    return path


def _patch_application_safe_rel(rel: str) -> bool:
    rel = str(rel).replace("\\", "/").strip("/")
    if not rel or rel.startswith("/") or ".." in Path(rel).parts:
        return False
    blocked_prefixes = ("data/autonomy/", "data/self_maintenance/", "data/backups/", ".git/", "__pycache__/")
    blocked_exact = {"data/projects.json", "data/settings.json"}
    if rel in blocked_exact:
        return False
    return not rel.startswith(blocked_prefixes)


def _patch_application_load_approval_file(approval_file: str | None) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    if not approval_file:
        return None, {"source": "inline", "path": None, "fallback_used": False}
    path = Path(str(approval_file))
    if not path.is_absolute():
        path = ROOT_DIR / path
    try:
        resolved = path.resolve()
        root = ROOT_DIR.resolve()
        if root not in resolved.parents and resolved != root:
            return None, {"source": "inline", "path": str(path), "fallback_used": True, "warning": "approval_file outside project root ignored"}
        payload = json.loads(resolved.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            return None, {"source": "inline", "path": str(resolved.relative_to(root)), "fallback_used": True, "warning": "approval file did not contain an object"}
        return payload, {"source": "file", "path": str(resolved.relative_to(root)), "fallback_used": False}
    except (OSError, json.JSONDecodeError) as error:
        return None, {"source": "inline", "path": str(path), "fallback_used": True, "warning": str(error)}


def _patch_application_write_metadata(application_path: Path, name: str, payload: dict[str, Any]) -> str:
    application_path.mkdir(parents=True, exist_ok=True)
    out = application_path / name
    write_text_atomic(out, json.dumps(payload, indent=2, default=str), encoding="utf-8")
    return str(out)


def _approved_file_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        raw = re.split(r"[,\n]+", value)
    elif isinstance(value, (list, tuple, set)):
        raw = list(value)
    else:
        raw = []
    result: list[str] = []
    for item in raw:
        rel = str(item).strip().strip("`'\"").replace("\\", "/")
        if rel and rel not in result:
            result.append(rel)
    return result


def _patch_application_core(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False) -> dict[str, Any]:
    goal = _normalize_patch_application_goal(patch_goal)
    phrase_hash = hashlib.sha256(str(approval_phrase or "").encode("utf-8", errors="replace")).hexdigest()[:16]
    cache_key = _patch_context_id("applicationcore", {"project": project_id, "goal": goal, "draft_file": draft_file, "trial": trial_id, "evidence": evidence_file, "approval": approval_file, "phrase": phrase_hash, "approved": apply_approved, "application": application_id})
    cached = _PATCH_APPLICATION_CORE_CACHE.get(cache_key)
    if cached is not None:
        return cached
    recommendation = build_promotion_readiness_packet_builder(project_id=project_id, patch_goal=goal, draft_text=draft_text, draft_file=draft_file, trial_id=trial_id, evidence_file=evidence_file, save=False)
    readiness = recommendation.get("promotion_readiness_packet_builder", {})
    evidence_core = _build_patch_evidence_core(project_id, goal, draft_text, draft_file, trial_id, evidence_file)
    approval_payload, approval_source = _patch_application_load_approval_file(approval_file)
    file_approved_phrase = str((approval_payload or {}).get("approval_phrase") or (approval_payload or {}).get("phrase") or "")
    phrase = str(approval_phrase or file_approved_phrase or "")
    approval_requested = bool(apply_approved or approval_payload)
    touched = sorted(set(str(f) for f in (readiness.get("touched_files") or evidence_core.get("touched_files") or []) if f))
    explicit_files = _approved_file_list(approved_files) or _approved_file_list((approval_payload or {}).get("approved_files"))
    approved_scope = sorted(set(explicit_files or touched))
    app_id = _patch_application_id(goal, str(readiness.get("readiness_packet_id") or evidence_core.get("review_id") or "recommendation"), application_id)
    exact_phrase = phrase == PATCH_APPLICATION_APPROVAL_PHRASE
    approval = {
        "schema_version": "eidolon.patch_application.operator_approval.v1",
        "approval_id": _patch_context_id("approval", {"application": app_id, "phrase_ok": exact_phrase, "files": approved_scope})[:32],
        "application_id": app_id,
        "operator_label": str((approval_payload or {}).get("operator_label") or operator_label or "local-operator"),
        "approval_source": approval_source,
        "approval_requested": approval_requested,
        "approval_phrase_required": PATCH_APPLICATION_APPROVAL_PHRASE,
        "approval_phrase_exact": exact_phrase,
        "approval_timestamp": str((approval_payload or {}).get("approval_timestamp") or (approval_payload or {}).get("approved_at") or (_now() if approval_requested else "")),
        "approved_files": approved_scope,
        "operator_approval_granted": bool(approval_requested and exact_phrase),
        "source_mutation_authorized": bool(approval_requested and exact_phrase),
        "publish_authorized": False,
        "memory_mutation_authorized": False,
        "identity_mutation_authorized": False,
        "approval_bypass_performed": False,
    }
    core = {
        "project_id": project_id,
        "goal": goal,
        "draft_text": draft_text,
        "draft_file": draft_file,
        "trial_id": str(readiness.get("trial_id") or evidence_core.get("trial_id") or trial_id or "generated-trial"),
        "review_id": str(readiness.get("review_id") or evidence_core.get("review_id") or "generated-review"),
        "recommendation_report": recommendation,
        "readiness": readiness,
        "evidence_core": evidence_core,
        "recommendation_id": str(readiness.get("readiness_packet_id") or evidence_core.get("review_id") or "generated-recommendation"),
        "recommendation_status": str(recommendation.get("status") or readiness.get("evidence_status") or "warn").lower(),
        "operator_recommendation": str(readiness.get("operator_recommendation") or "recommend_manual_review"),
        "risk_classification": str(readiness.get("risk_classification") or "moderate"),
        "touched_files": touched,
        "approval": approval,
        "application_id": app_id,
        "application_path": str(_patch_application_path(app_id)),
        "pre_manifest": _source_manifest(project_id=project_id),
    }
    _PATCH_APPLICATION_CORE_CACHE[cache_key] = core
    if len(_PATCH_APPLICATION_CORE_CACHE) > 6:
        try:
            _PATCH_APPLICATION_CORE_CACHE.pop(next(iter(_PATCH_APPLICATION_CORE_CACHE)))
        except StopIteration:
            pass
    return core


def _patch_application_extract_doc_additions(text: str) -> dict[str, list[str]]:
    additions: dict[str, list[str]] = {}
    current: str | None = None
    for raw in str(text or "").splitlines():
        line = raw.rstrip("\n")
        git_match = re.match(r"diff --git a/(.+?) b/(.+)$", line.strip())
        if git_match:
            current = git_match.group(2).strip()
            additions.setdefault(current, [])
            continue
        if line.strip().startswith("+++ b/"):
            current = line.strip()[6:].strip()
            additions.setdefault(current, [])
            continue
        if current and line.startswith("+") and not line.startswith("+++"):
            additions.setdefault(current, []).append(line[1:])
    return {rel: lines for rel, lines in additions.items() if rel.endswith(".md") and lines}


def _patch_application_snapshot_payload(core: dict[str, Any]) -> dict[str, Any]:
    approved = [rel for rel in core.get("approval", {}).get("approved_files", []) if _patch_application_safe_rel(rel)]
    files: list[dict[str, Any]] = []
    for rel in approved:
        path = ROOT_DIR / rel
        if path.exists() and path.is_file():
            try:
                files.append({"path": rel, "sha256": _sha256_file(path), "size": path.stat().st_size, "text": path.read_text(encoding="utf-8", errors="replace") if path.stat().st_size <= 1_000_000 else ""})
            except OSError:
                files.append({"path": rel, "error": "unreadable"})
        else:
            files.append({"path": rel, "missing": True, "text": ""})
    return {
        "schema_version": "eidolon.patch_application.snapshot.v1",
        "application_id": core["application_id"],
        "approval_id": core["approval"].get("approval_id"),
        "patch_goal": core["goal"],
        "recommendation_id": core["recommendation_id"],
        "trial_id": core["trial_id"],
        "manifest_before": core["pre_manifest"],
        "files": files,
        "snapshot_created_at": _now(),
        "rollback_scope": approved,
        "package_private_root": "data/autonomy/patch_applications/",
        "source_mutation_performed": False,
    }


def build_patch_approval_intake_contract(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, save: bool = True) -> dict[str, Any]:
    """v76.1: require an explicit operator approval contract before live patch application."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    approval = core["approval"]
    approved_file_count = len(approval.get("approved_files", []))
    rows = [
        {"name": "approval-requested", "status": "pass" if approval.get("approval_requested") else "blocked", "message": "explicit approval flag or file present" if approval.get("approval_requested") else "missing --patch-apply-approved or approval file"},
        {"name": "approval-phrase", "status": "pass" if approval.get("approval_phrase_exact") else "blocked", "message": "exact approval phrase matched" if approval.get("approval_phrase_exact") else f"approval phrase must equal {PATCH_APPLICATION_APPROVAL_PHRASE!r}"},
        {"name": "approved-files", "status": "pass" if approved_file_count else "blocked", "message": f"{approved_file_count} approved file(s) bound."},
        {"name": "forbidden-authority", "status": "pass" if not approval.get("publish_authorized") and not approval.get("memory_mutation_authorized") and not approval.get("identity_mutation_authorized") else "blocked", "message": "Approval contract only authorizes scoped source application, never publish/memory/identity mutation."},
    ]
    payload = dict(approval)
    payload.update({"patch_goal": core["goal"], "recommendation_id": core["recommendation_id"], "trial_id": core["trial_id"], "touched_files": core["touched_files"]})
    return _report_from_rows("v76.1", "patch_approval_intake_contract", payload, rows, project_id, "Approval intake contract requires an exact operator phrase, scope-bound file list, and no publish/memory/identity authority before v77 can apply anything.", PATCH_APPROVAL_INTAKE_CONTRACT, save)


def build_recommendation_approval_binder(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, save: bool = True) -> dict[str, Any]:
    """v76.2: bind explicit approval to the exact v76 recommendation packet."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    approval = core["approval"]
    recommendation_blocked = core["recommendation_status"] == "blocked" or "blocked" in core["operator_recommendation"]
    approved_set = set(approval.get("approved_files", []))
    touched_set = set(core.get("touched_files", []))
    broadening = sorted([rel for rel in approved_set if rel not in touched_set]) if touched_set else []
    missing_from_approval = sorted([rel for rel in touched_set if rel not in approved_set]) if touched_set else []
    payload = {
        "schema_version": "eidolon.patch_application.recommendation_approval_binder.v1",
        "binding_id": _patch_context_id("approvalbinding", {"app": core["application_id"], "recommendation": core["recommendation_id"], "approval": approval.get("approval_id")}),
        "application_id": core["application_id"],
        "recommendation_id": core["recommendation_id"],
        "trial_id": core["trial_id"],
        "approval_id": approval.get("approval_id"),
        "recommendation_status": core["recommendation_status"],
        "operator_recommendation": core["operator_recommendation"],
        "risk_classification": core["risk_classification"],
        "approval_valid": bool(approval.get("operator_approval_granted") and not recommendation_blocked and not broadening),
        "scope_broadening_files": broadening,
        "recommended_files_missing_from_approval": missing_from_approval,
        "source_mutation_performed": False,
        "approval_bypass_performed": False,
    }
    rows = [
        {"name": "recommendation-not-blocked", "status": "blocked" if recommendation_blocked else "pass", "message": f"recommendation={core['operator_recommendation']} status={core['recommendation_status']}"},
        {"name": "approval-exact", "status": "pass" if approval.get("operator_approval_granted") else "blocked", "message": "approval phrase and flag/file are exact" if approval.get("operator_approval_granted") else "operator approval not granted"},
        {"name": "scope-not-broadened", "status": "blocked" if broadening else "pass", "message": "approval broadens scope: " + ", ".join(broadening[:8]) if broadening else "approved files do not exceed recommendation scope"},
        {"name": "manual-review-risk", "status": "warn" if "manual_review" in core["operator_recommendation"] or core["risk_classification"] in {"moderate", "high"} else "pass", "message": f"risk={core['risk_classification']} recommendation={core['operator_recommendation']}"},
    ]
    return _report_from_rows("v76.2", "recommendation_approval_binder", payload, rows, project_id, "Recommendation-to-approval binder prevents recommendations from being treated as approval and blocks stale or broadened scope.", RECOMMENDATION_APPROVAL_BINDER, save)


def build_live_source_snapshot_builder(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, save: bool = True) -> dict[str, Any]:
    """v76.3: capture a rollback snapshot before any approved live source mutation."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    snapshot = _patch_application_snapshot_payload(core)
    archived_path = ""
    if save:
        archived_path = _patch_application_write_metadata(_patch_application_path(core["application_id"]), "snapshot.json", snapshot)
    snapshot["archived_path"] = archived_path
    rows = [
        {"name": "manifest", "status": "pass" if snapshot.get("manifest_before", {}).get("manifest_sha256") else "blocked", "message": str(snapshot.get("manifest_before", {}).get("manifest_sha256"))},
        {"name": "rollback-files", "status": "pass" if snapshot.get("files") else "blocked", "message": f"{len(snapshot.get('files', []))} file snapshot record(s)."},
        {"name": "runtime-only", "status": "pass", "message": "snapshot stored under data/autonomy/patch_applications and excluded from source packages"},
        {"name": "no-mutation", "status": "pass", "message": "snapshot capture reads source only."},
    ]
    return _report_from_rows("v76.3", "live_source_snapshot_builder", snapshot, rows, project_id, "Live source snapshot builder captures rollback contents and manifests before approved source application.", LIVE_SOURCE_SNAPSHOT_BUILDER, save)


def build_approved_patch_materializer(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, dry_run: bool = True, save: bool = True) -> dict[str, Any]:
    """v76.4: apply only explicitly approved, bounded, structured changes to the live tree."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    binder = build_recommendation_approval_binder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved, save=False)
    allowed = set(core["approval"].get("approved_files", []))
    draft = core.get("draft_text")
    if not draft and draft_file:
        draft, _src = _read_patch_review_draft_text(draft_file=draft_file, patch_goal=core["goal"])
    elif not draft:
        draft = core["evidence_core"].get("draft_text") or _sample_patch_review_draft(core["goal"])
    doc_additions = _patch_application_extract_doc_additions(str(draft))
    materialized: list[dict[str, Any]] = []
    preview_only: list[dict[str, Any]] = []
    unsafe: list[str] = []
    blocked_reason = "" if binder.get("recommendation_approval_binder", {}).get("approval_valid") else "approval_binding_invalid"
    if not blocked_reason:
        for rel, lines in doc_additions.items():
            if rel not in allowed:
                preview_only.append({"path": rel, "reason": "not in approved file scope"})
                continue
            if not _patch_application_safe_rel(rel):
                unsafe.append(rel)
                continue
            if dry_run:
                materialized.append({"path": rel, "mode": "dry_run_doc_append", "line_count": len(lines)})
                continue
            target = ROOT_DIR / rel
            root = ROOT_DIR.resolve()
            resolved = target.resolve()
            if root not in resolved.parents and resolved != root:
                unsafe.append(rel)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            old = target.read_text(encoding="utf-8", errors="replace") if target.exists() else ""
            block = "\n".join(lines).strip()
            if block and block not in old:
                write_text_atomic(target, block + "\n\n" + old, encoding="utf-8")
                materialized.append({"path": rel, "mode": "live_doc_append", "line_count": len(lines)})
            else:
                materialized.append({"path": rel, "mode": "already_present", "line_count": len(lines)})
        for rel in sorted(allowed):
            if rel not in doc_additions and not rel.endswith(".md"):
                preview_only.append({"path": rel, "reason": "v77 materializer starts conservative: non-document source patches require a structured applier in a later hardening arc"})
    payload = {
        "schema_version": "eidolon.patch_application.materializer.v1",
        "application_id": core["application_id"],
        "approval_id": core["approval"].get("approval_id"),
        "dry_run": dry_run,
        "blocked_reason": blocked_reason,
        "materialized_files": materialized,
        "preview_only_files": preview_only,
        "unsafe_paths": unsafe,
        "source_mutation_performed": bool(materialized and not dry_run and not blocked_reason and not unsafe),
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "approval_bypass_performed": False,
    }
    if save:
        _patch_application_write_metadata(_patch_application_path(core["application_id"]), "materialization.json", payload)
    rows = [
        {"name": "approval-binding", "status": _report_gate_status(binder), "message": binder.get("message", "")},
        {"name": "blocked-reason", "status": "blocked" if blocked_reason else "pass", "message": blocked_reason or "approval binding valid"},
        {"name": "unsafe-paths", "status": "blocked" if unsafe else "pass", "message": ", ".join(unsafe[:8]) if unsafe else "no unsafe paths"},
        {"name": "materialized", "status": "pass" if materialized or dry_run else "warn", "message": f"{len(materialized)} file operation(s); dry_run={dry_run}"},
        {"name": "source-scope", "status": "warn" if preview_only else "pass", "message": f"{len(preview_only)} approved source file(s) left preview-only."},
    ]
    return _report_from_rows("v76.4", "approved_patch_materializer", payload, rows, project_id, "Approved patch materializer applies only exact-approval, approved-scope, safe-path changes; API and gates use dry-run by default.", APPROVED_PATCH_MATERIALIZER, save)


def build_post_apply_verification_runner(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, dry_run: bool = True, save: bool = True) -> dict[str, Any]:
    """v76.5: run verification after an approved application or dry-run application preview."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    commands = [
        [sys.executable, "-m", "py_compile", str(ROOT_DIR / "conscious_agent" / "self_maintenance.py"), str(ROOT_DIR / "conscious_agent" / "main.py"), str(ROOT_DIR / "conscious_agent" / "api_server.py"), str(ROOT_DIR / "conscious_agent" / "dashboard.py"), str(ROOT_DIR / "tools" / "smoke_check.py")],
        [sys.executable, "conscious_agent/main.py", "--status"],
    ]
    results = [_patch_trial_run_command(ROOT_DIR, cmd, timeout=60) for cmd in commands]
    failures = [r for r in results if not r.get("ok")]
    payload = {
        "schema_version": "eidolon.patch_application.post_apply_verification.v1",
        "application_id": core["application_id"],
        "dry_run": dry_run,
        "verification_commands": results,
        "failed_commands": failures,
        "verification_passed": not failures,
        "source_mutation_performed": False,
        "publish_performed": False,
    }
    if save:
        _patch_application_write_metadata(_patch_application_path(core["application_id"]), "post_apply_verification.json", payload)
    rows = [
        {"name": "commands", "status": "pass" if results else "blocked", "message": f"{len(results)} verification command(s) run."},
        {"name": "failures", "status": "blocked" if failures else "pass", "message": f"{len(failures)} failed command(s)."},
        {"name": "publish-boundary", "status": "pass", "message": "post-apply verification does not publish releases."},
    ]
    return _report_from_rows("v76.5", "post_apply_verification_runner", payload, rows, project_id, "Post-apply verification runner checks compile/status evidence after materialization and never publishes a release.", POST_APPLY_VERIFICATION_RUNNER, save)


def build_automatic_rollback_executor(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, dry_run: bool = True, verification_failed: bool = False, save: bool = True) -> dict[str, Any]:
    """v76.6: restore snapshotted files when post-apply verification fails."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    snapshot = _patch_application_snapshot_payload(core)
    restored: list[str] = []
    skipped_reason = "dry_run" if dry_run else "verification_passed"
    if verification_failed and not dry_run:
        skipped_reason = ""
        for item in snapshot.get("files", []):
            rel = str(item.get("path") or "")
            if not _patch_application_safe_rel(rel):
                continue
            target = ROOT_DIR / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            if item.get("missing"):
                if target.exists() and target.is_file():
                    target.unlink()
                restored.append(rel)
            else:
                write_text_atomic(target, str(item.get("text") or ""), encoding="utf-8")
                restored.append(rel)
    payload = {
        "schema_version": "eidolon.patch_application.rollback_executor.v1",
        "application_id": core["application_id"],
        "dry_run": dry_run,
        "verification_failed": verification_failed,
        "rollback_performed": bool(restored),
        "restored_files": restored,
        "skipped_reason": skipped_reason,
        "manifest_after_rollback": _source_manifest(project_id=project_id) if restored else None,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
    }
    if save:
        _patch_application_write_metadata(_patch_application_path(core["application_id"]), "rollback.json", payload)
    rows = [
        {"name": "rollback-trigger", "status": "pass" if verification_failed or dry_run else "pass", "message": "rollback required" if verification_failed else "no rollback required"},
        {"name": "restored-files", "status": "pass", "message": f"{len(restored)} file(s) restored; dry_run={dry_run}."},
        {"name": "retry-boundary", "status": "pass", "message": "rollback does not retry or generate a fix automatically."},
    ]
    return _report_from_rows("v76.6", "automatic_rollback_executor", payload, rows, project_id, "Automatic rollback executor restores approved files from snapshot on failed verification and never retries autonomously.", AUTOMATIC_ROLLBACK_EXECUTOR, save)


def build_application_evidence_recorder(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, dry_run: bool = True, save: bool = True) -> dict[str, Any]:
    """v76.7: record final application evidence for operator audit."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    approval = build_patch_approval_intake_contract(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved, save=False)
    binder = build_recommendation_approval_binder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved, save=False)
    materializer = build_approved_patch_materializer(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved, dry_run=dry_run, save=False)
    verification = build_post_apply_verification_runner(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved, dry_run=dry_run, save=False)
    verification_failed = verification.get("post_apply_verification_runner", {}).get("verification_passed") is False and materializer.get("approved_patch_materializer", {}).get("source_mutation_performed") is True
    rollback = build_automatic_rollback_executor(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved, dry_run=dry_run, verification_failed=verification_failed, save=False)
    final_status = "blocked"
    if _report_gate_status(approval) != "blocked" and _report_gate_status(binder) != "blocked" and _report_gate_status(materializer) != "blocked" and _report_gate_status(verification) != "blocked":
        final_status = "dry_run_verified" if dry_run else "applied_verified"
    if rollback.get("automatic_rollback_executor", {}).get("rollback_performed"):
        final_status = "rolled_back"
    payload = {
        "schema_version": "eidolon.patch_application.evidence.v1",
        "application_id": core["application_id"],
        "approval_id": core["approval"].get("approval_id"),
        "recommendation_id": core["recommendation_id"],
        "trial_id": core["trial_id"],
        "patch_goal": core["goal"],
        "final_status": final_status,
        "dry_run": dry_run,
        "files_changed": materializer.get("approved_patch_materializer", {}).get("materialized_files", []),
        "pre_apply_manifest": core["pre_manifest"].get("manifest_sha256"),
        "post_apply_manifest": _source_manifest(project_id=project_id).get("manifest_sha256"),
        "steps": {"approval": _compact_step(approval), "binder": _compact_step(binder), "materializer": _compact_step(materializer), "verification": _compact_step(verification), "rollback": _compact_step(rollback)},
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "approval_bypass_performed": False,
    }
    if save:
        _patch_application_write_metadata(_patch_application_path(core["application_id"]), "application_evidence.json", payload)
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in {"approval": approval, "binder": binder, "materializer": materializer, "verification": verification, "rollback": rollback}.items()]
    rows.append({"name": "evidence-status", "status": "pass" if final_status in {"dry_run_verified", "applied_verified"} else "warn" if final_status == "rolled_back" else "blocked", "message": final_status})
    return _report_from_rows("v76.7", "application_evidence_recorder", payload, rows, project_id, "Application evidence recorder binds approval, snapshot, materialization, verification, rollback, and final state for operator audit.", APPLICATION_EVIDENCE_RECORDER, save)


def build_patch_application_dashboard_api_cli(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v76.8: verify patch application dashboard/API/CLI surfaces."""
    dashboard_text = _read_source_text("conscious_agent/dashboard.py")
    api_text = _read_source_text("conscious_agent/api_server.py")
    cli_text = _read_source_text("conscious_agent/main.py")
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    cli_flags = ["--patch-apply-approval", "--patch-apply-bind", "--patch-apply-snapshot", "--patch-apply-materialize", "--patch-apply-verify", "--patch-apply-rollback", "--patch-apply-evidence", "--patch-application-dashboard-api-cli", "--pre-v77-application-gate", "--operator-approved-patch-application-layer", "--patch-approval-file", "--patch-application-id", "--patch-apply-approved", "--approval-phrase"]
    api_routes = ["/api/patch-apply/approval", "/api/patch-apply/bind", "/api/patch-apply/snapshot", "/api/patch-apply/apply", "/api/patch-apply/verify", "/api/patch-apply/rollback", "/api/patch-apply/evidence", "/api/patch-apply/parity", "/api/patch-apply/gate", "/api/patch-apply/layer"]
    rows = [
        {"name": "dashboard-route", "status": "pass" if "/patch-apply" in dashboard_text and "Operator-Approved Patch Application" in dashboard_text else "blocked", "message": "/patch-apply exposes v77 application status."},
        {"name": "api-routes", "status": "pass" if all(route in api_text for route in api_routes) else "blocked", "message": "Patch apply API routes are exposed in dry-run/read-only mode."},
        {"name": "cli-flags", "status": "pass" if all(flag in cli_text for flag in cli_flags) else "blocked", "message": "Patch application CLI flags are available."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard nav keeps custom data-tip hover notes only."},
        {"name": "docs", "status": "pass" if "v77.0 - Operator-Approved Patch Application Layer" in docs else "blocked", "message": "README/release history mention v77.0."},
    ]
    payload = {"schema_version": "eidolon.patch_application.dashboard_api_cli.v1", "parity_id": _patch_context_id("applicationparity", rows), "dashboard_path": "/patch-apply", "api_routes": api_routes, "cli_flags": cli_flags, "custom_data_tip_only": not _dashboard_nav_title_regression_present(), "api_live_apply_enabled": False, "source_mutation_performed": False}
    return _report_from_rows("v76.8", "patch_application_dashboard_api_cli", payload, rows, project_id, "Patch application dashboard/API/CLI exposes explicit-approval source-apply controls while API surfaces stay dry-run/read-only.", PATCH_APPLICATION_DASHBOARD_API_CLI, save)


def build_pre_v77_application_gate(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = PATCH_APPLICATION_APPROVAL_PHRASE, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = True, save: bool = True) -> dict[str, Any]:
    """v76.9: verify the pre-v77 application gate in dry-run mode."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    parts = {
        "approval": build_patch_approval_intake_contract(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, save=False),
        "binder": build_recommendation_approval_binder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, save=False),
        "snapshot": build_live_source_snapshot_builder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, save=False),
        "materializer": build_approved_patch_materializer(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=True, save=False),
        "verification": build_post_apply_verification_runner(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=True, save=False),
        "rollback": build_automatic_rollback_executor(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=True, verification_failed=True, save=False),
        "evidence": build_application_evidence_recorder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=True, save=False),
        "parity": build_patch_application_dashboard_api_cli(project_id, patch_goal, save=False),
        "privacy": build_package_privacy_scan(project_id=project_id, save=False),
    }
    docs_text = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in parts.items()]
    rows.extend([
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v77.0 - Operator-Approved Patch Application Layer" in docs_text else "blocked", "message": "README and release history mention v77.0."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs."},
        {"name": "application-boundary", "status": "pass", "message": "pre-v77 gate uses dry-run materialization and cannot publish or mutate memory/identity."},
    ])
    payload = {"schema_version": "eidolon.patch_application.pre_v77_gate.v1", "gate_id": _patch_context_id("prev77", {k: v.get("status") for k, v in parts.items()}), "application_id": core["application_id"], "recommendation_id": core["recommendation_id"], "steps": {k: _compact_step(v) for k, v in parts.items()}, "ready_for_operator_approved_application": _status_from(rows) != "blocked", "dry_run": True, "publish_performed": False, "memory_mutation_performed": False, "identity_mutation_performed": False, "approval_bypass_performed": False}
    return _report_from_rows("v76.9", "pre_v77_application_gate", payload, rows, project_id, "Pre-v77 application gate verifies exact approval binding, source snapshotting, dry-run materialization, verification, rollback evidence, dashboard/API/CLI, privacy, docs, version markers, and safety boundaries.", PRE_V77_APPLICATION_GATE, save)


def build_operator_approved_patch_application_layer(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator", apply_approved: bool = False, dry_run: bool = True, save: bool = True) -> dict[str, Any]:
    """v77.0: integrated Operator-Approved Patch Application Layer."""
    core = _patch_application_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved)
    parts = {
        "approval": build_patch_approval_intake_contract(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, save=False),
        "binder": build_recommendation_approval_binder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, save=False),
        "snapshot": build_live_source_snapshot_builder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, save=save),
        "materializer": build_approved_patch_materializer(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=dry_run, save=save),
        "verification": build_post_apply_verification_runner(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=dry_run, save=save),
    }
    verification_failed = parts["verification"].get("post_apply_verification_runner", {}).get("verification_passed") is False and parts["materializer"].get("approved_patch_materializer", {}).get("source_mutation_performed") is True
    parts["rollback"] = build_automatic_rollback_executor(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=dry_run, verification_failed=verification_failed, save=save)
    parts["evidence"] = build_application_evidence_recorder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, core["application_id"], operator_label, apply_approved, dry_run=dry_run, save=save)
    rows = [{"name": name, "status": _report_gate_status(value), "message": value.get("message", "")} for name, value in parts.items()]
    status = _status_from(rows)
    final = parts["evidence"].get("application_evidence_recorder", {}).get("final_status")
    payload = {
        "schema_version": "eidolon.patch_application.layer.v1",
        "layer_id": _patch_context_id("applicationlayer", {"application": core["application_id"], "status": status, "dry_run": dry_run}),
        "version": SELF_MAINTENANCE_VERSION,
        "application_id": core["application_id"],
        "approval_id": core["approval"].get("approval_id"),
        "recommendation_id": core["recommendation_id"],
        "trial_id": core["trial_id"],
        "decision": final or ("application_blocked" if status == "blocked" else "application_ready"),
        "dry_run": dry_run,
        "source_mutation_performed": parts["materializer"].get("approved_patch_materializer", {}).get("source_mutation_performed") is True,
        "rollback_performed": parts["rollback"].get("automatic_rollback_executor", {}).get("rollback_performed") is True,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "approval_bypass_performed": False,
        "summary": "Operator-approved patch application requires exact approval, binds to v76 recommendation evidence, snapshots live source, materializes scoped changes, verifies results, and rolls back on failed verification. It never publishes or mutates memory/identity.",
        "recommended_next_arc": "v78.0 Verified Application Recovery and Rollback Hardening",
    }
    return _report_from_rows("v77.0", "operator_approved_patch_application_layer", payload, rows, project_id, "Operator-Approved Patch Application Layer applies only exact-approval, recommendation-bound patches with rollback snapshot and verification; no publish, memory/identity mutation, or approval bypass.", OPERATOR_APPROVED_PATCH_APPLICATION_LAYER, save)


