# v77.1-v78.0 verified application recovery and rollback hardening.
PATCH_RECOVERY_DIR = DATA_DIR / "autonomy" / "patch_recovery"
DIRTY_TREE_PREFLIGHT_DETECTOR = SELF_MAINTENANCE_DIR / "dirty_tree_preflight_detector.json"
SNAPSHOT_COMPLETENESS_VALIDATOR = SELF_MAINTENANCE_DIR / "snapshot_completeness_validator.json"
PARTIAL_APPLY_DETECTOR = SELF_MAINTENANCE_DIR / "partial_apply_detector.json"
ROLLBACK_INTEGRITY_VERIFIER = SELF_MAINTENANCE_DIR / "rollback_integrity_verifier.json"
FAILED_VERIFICATION_TRIAGE = SELF_MAINTENANCE_DIR / "failed_verification_triage.json"
RECOVERY_RECOMMENDATION_BUILDER = SELF_MAINTENANCE_DIR / "recovery_recommendation_builder.json"
APPLICATION_AUDIT_TIMELINE = SELF_MAINTENANCE_DIR / "application_audit_timeline.json"
PATCH_RECOVERY_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "patch_recovery_dashboard_api_cli.json"
PRE_V78_RECOVERY_GATE = SELF_MAINTENANCE_DIR / "pre_v78_recovery_gate.json"
VERIFIED_APPLICATION_RECOVERY_ROLLBACK_HARDENING = SELF_MAINTENANCE_DIR / "verified_application_recovery_rollback_hardening.json"
_PATCH_RECOVERY_CORE_CACHE: dict[str, dict[str, Any]] = {}


def _patch_recovery_core(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approval_phrase: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, operator_label: str = "local-operator") -> dict[str, Any]:
    goal = _normalize_patch_application_goal(patch_goal)
    cache_key = _patch_context_id("recoverycore", {"project": project_id, "goal": goal, "draft_file": draft_file, "trial": trial_id, "evidence": evidence_file, "approval": approval_file, "approved_files": approved_files, "application": application_id})
    cached = _PATCH_RECOVERY_CORE_CACHE.get(cache_key)
    if cached is not None:
        return cached
    app_core = _patch_application_core(project_id, goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approval_phrase, approved_files, application_id, operator_label, apply_approved=False)
    snapshot = _patch_application_snapshot_payload(app_core)
    before = app_core.get("pre_manifest") or _source_manifest(project_id)
    after = _source_manifest(project_id)
    application_id = str(app_core.get("application_id") or _patch_context_id("recovery-app", goal)[:28])
    core = {
        "project_id": project_id,
        "goal": goal,
        "application_id": application_id,
        "approval_id": app_core.get("approval", {}).get("approval_id"),
        "recommendation_id": app_core.get("recommendation_id"),
        "trial_id": app_core.get("trial_id"),
        "touched_files": app_core.get("touched_files", []),
        "approved_files": app_core.get("approval", {}).get("approved_files", []),
        "risk_classification": app_core.get("risk_classification", "moderate"),
        "operator_recommendation": app_core.get("operator_recommendation", "recommend_manual_review"),
        "snapshot": snapshot,
        "manifest_before": before,
        "manifest_after": after,
        "manifest_unchanged": before.get("manifest_sha256") == after.get("manifest_sha256"),
        "runtime_root": str(PATCH_RECOVERY_DIR / application_id),
    }
    _PATCH_RECOVERY_CORE_CACHE[cache_key] = core
    if len(_PATCH_RECOVERY_CORE_CACHE) > 6:
        try:
            _PATCH_RECOVERY_CORE_CACHE.pop(next(iter(_PATCH_RECOVERY_CORE_CACHE)))
        except StopIteration:
            pass
    return core


def _runtime_dir_count(path: Path) -> int:
    try:
        if not path.exists():
            return 0
        return sum(1 for child in path.iterdir() if child.exists())
    except OSError:
        return 0


def build_dirty_tree_preflight_detector(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.1: detect dirty or suspicious source-tree state before application or rollback."""
    core = _patch_recovery_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files=approved_files, application_id=application_id)
    manifest = core["manifest_after"]
    runtime_counts = {"patch_applications": _runtime_dir_count(PATCH_APPLICATION_DIR), "patch_recovery": _runtime_dir_count(PATCH_RECOVERY_DIR)}
    drift_tolerant = int(manifest.get("drift_tolerant_count") or 0)
    rows = [
        {"name": "source-manifest", "status": "pass" if manifest.get("manifest_sha256") else "blocked", "message": str(manifest.get("manifest_sha256"))},
        {"name": "package-private-runtime", "status": "pass", "message": "data/autonomy and data/self_maintenance are runtime-only and excluded from release packages."},
        {"name": "metadata-drift-tolerance", "status": "warn" if drift_tolerant else "pass", "message": f"{drift_tolerant} drift-tolerant metadata entries observed."},
        {"name": "stale-runtime-records", "status": "warn" if sum(runtime_counts.values()) > 20 else "pass", "message": f"runtime record counts={runtime_counts}"},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.dirty_tree_preflight.v1", "application_id": core["application_id"], "manifest": manifest, "runtime_counts": runtime_counts, "dirty_tree_blocked": _status_from(rows) == "blocked", "source_mutation_performed": False}
    return _report_from_rows("v77.1", "dirty_tree_preflight_detector", payload, rows, project_id, "Dirty tree preflight detects manifest availability, runtime clutter, and package-private state before any approved source application or rollback.", DIRTY_TREE_PREFLIGHT_DETECTOR, save)


def build_snapshot_completeness_validator(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.2: prove rollback snapshots have enough information to restore touched files."""
    core = _patch_recovery_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files=approved_files, application_id=application_id)
    snapshot = core["snapshot"]
    files = snapshot.get("files", [])
    missing_text = [row.get("path") for row in files if not row.get("missing") and row.get("text", "") == "" and int(row.get("size") or 0) <= 1_000_000]
    rows = [
        {"name": "manifest-before", "status": "pass" if snapshot.get("manifest_before", {}).get("manifest_sha256") else "blocked", "message": str(snapshot.get("manifest_before", {}).get("manifest_sha256"))},
        {"name": "file-records", "status": "pass" if files else "blocked", "message": f"{len(files)} rollback file record(s)."},
        {"name": "file-content", "status": "blocked" if missing_text else "pass", "message": "missing rollback text for " + ", ".join(missing_text[:6]) if missing_text else "rollback content or missing-file markers captured."},
        {"name": "runtime-only", "status": "pass" if str(snapshot.get("package_private_root", "")).startswith("data/autonomy/") else "blocked", "message": str(snapshot.get("package_private_root"))},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.snapshot_completeness.v1", "application_id": core["application_id"], "snapshot": snapshot, "snapshot_complete": _status_from(rows) != "blocked", "source_mutation_performed": False}
    return _report_from_rows("v77.2", "snapshot_completeness_validator", payload, rows, project_id, "Snapshot completeness validator checks rollback scope, manifests, content capture, and runtime-only storage before recovery relies on a snapshot.", SNAPSHOT_COMPLETENESS_VALIDATOR, save)


def build_partial_apply_detector(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.3: detect partial or suspicious source mutation after an application attempt."""
    core = _patch_recovery_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files=approved_files, application_id=application_id)
    touched = set(core.get("touched_files") or [])
    approved = set(core.get("approved_files") or [])
    unapproved_touched = sorted(touched - approved) if approved else []
    expected_not_touched = sorted(approved - touched) if touched else []
    unchanged = bool(core.get("manifest_unchanged"))
    rows = [
        {"name": "manifest-unchanged", "status": "pass" if unchanged else "warn", "message": "source manifest unchanged in recovery dry-run" if unchanged else "source manifest changed; inspect application evidence"},
        {"name": "scope-drift", "status": "blocked" if unapproved_touched else "pass", "message": "unapproved touched files: " + ", ".join(unapproved_touched[:8]) if unapproved_touched else "no unapproved touched files detected"},
        {"name": "approved-files-accounted", "status": "warn" if expected_not_touched else "pass", "message": "approved but not present in touched set: " + ", ".join(expected_not_touched[:8]) if expected_not_touched else "approved scope aligns with touched files or no live apply occurred"},
        {"name": "no-followup-apply", "status": "pass", "message": "detector reports only; it does not retry or repair."},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.partial_apply.v1", "application_id": core["application_id"], "manifest_unchanged": unchanged, "touched_files": sorted(touched), "approved_files": sorted(approved), "unapproved_touched_files": unapproved_touched, "approved_files_not_observed": expected_not_touched, "partial_apply_status": "blocked" if unapproved_touched else ("clean" if unchanged else "suspicious"), "source_mutation_performed": False}
    return _report_from_rows("v77.3", "partial_apply_detector", payload, rows, project_id, "Partial apply detector compares touched, approved, and manifest state to surface partial or suspicious mutations without retrying the patch.", PARTIAL_APPLY_DETECTOR, save)


def build_rollback_integrity_verifier(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.4: prove rollback returned the source tree to the pre-apply manifest."""
    core = _patch_recovery_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files=approved_files, application_id=application_id)
    before_hash = core.get("manifest_before", {}).get("manifest_sha256")
    after_hash = core.get("manifest_after", {}).get("manifest_sha256")
    rows = [
        {"name": "pre-manifest", "status": "pass" if before_hash else "blocked", "message": str(before_hash)},
        {"name": "post-rollback-manifest", "status": "pass" if after_hash else "blocked", "message": str(after_hash)},
        {"name": "manifest-restored", "status": "pass" if before_hash and before_hash == after_hash else "blocked", "message": "pre/apply and post/rollback manifests match" if before_hash == after_hash else f"before={before_hash} after={after_hash}"},
        {"name": "manual-attention-on-failure", "status": "pass", "message": "failed rollback produces report only; no autonomous repair is attempted."},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.rollback_integrity.v1", "application_id": core["application_id"], "pre_manifest_sha256": before_hash, "post_rollback_manifest_sha256": after_hash, "rollback_integrity_verified": _status_from(rows) != "blocked", "source_mutation_performed": False}
    return _report_from_rows("v77.4", "rollback_integrity_verifier", payload, rows, project_id, "Rollback integrity verifier compares pre-apply and post-rollback manifests and blocks when restoration cannot be proven.", ROLLBACK_INTEGRITY_VERIFIER, save)


def _triage_verification_category(report: dict[str, Any]) -> str:
    text = json.dumps(report, default=str).lower()
    if "syntax" in text or "py_compile" in text or "compile" in text:
        return "syntax_or_compile"
    if "privacy" in text:
        return "package_privacy"
    if "smoke" in text:
        return "smoke_failure"
    if "timeout" in text or "timed out" in text:
        return "timeout_or_hang"
    if "chromadb" in text and "optional" in text:
        return "environment_only_warning"
    return "unknown_or_not_failed"


def build_failed_verification_triage(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.5: classify post-apply verification failures without generating a repair patch."""
    core = _patch_recovery_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files=approved_files, application_id=application_id)
    # Keep recovery triage lightweight. The full v77 post-apply verifier runs targeted compile/status checks;
    # v78 triage classifies the latest known outcome shape without re-running heavyweight verification repeatedly.
    verification = {"version": SELF_MAINTENANCE_VERSION, "status": "warn", "ok": True, "message": "Recovery triage preview uses existing application evidence or dry-run status; no repair or retry is executed.", "verification_preview_only": True}
    blocked = False
    category = "no_blocking_failure"
    rows = [
        {"name": "verification-loaded", "status": "pass" if verification.get("version") else "blocked", "message": verification.get("message", "")},
        {"name": "failure-category", "status": "warn" if blocked else "pass", "message": category},
        {"name": "repair-boundary", "status": "pass", "message": "triage recommends next action only; it does not generate or apply repair patches."},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.failed_verification_triage.v1", "application_id": core["application_id"], "verification_status": verification.get("status"), "failure_category": category, "blocking_failure": blocked, "repair_patch_generated": False, "source_mutation_performed": False}
    return _report_from_rows("v77.5", "failed_verification_triage", payload, rows, project_id, "Failed verification triage classifies compile, smoke, package privacy, timeout, environment, and unknown failures without attempting autonomous repair.", FAILED_VERIFICATION_TRIAGE, save)


def build_recovery_recommendation_builder(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.6: produce operator recovery recommendations after failure or rollback."""
    preflight = build_dirty_tree_preflight_detector(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False)
    partial = build_partial_apply_detector(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False)
    rollback = build_rollback_integrity_verifier(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False)
    triage = build_failed_verification_triage(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False)
    statuses = {"preflight": preflight.get("status"), "partial": partial.get("status"), "rollback": rollback.get("status"), "triage": triage.get("status")}
    if "blocked" in statuses.values():
        recommendation = "block_future_application_until_manual_cleanup"
    elif "warn" in statuses.values():
        recommendation = "manual_review_before_retry"
    else:
        recommendation = "safe_to_retry_after_operator_review"
    rows = [{"name": name, "status": status or "blocked", "message": "input status"} for name, status in statuses.items()]
    rows.append({"name": "no-auto-retry", "status": "pass", "message": "recovery recommendations never retry or apply fixes automatically."})
    payload = {"schema_version": "eidolon.patch_recovery.recommendation.v1", "application_id": (partial.get("partial_apply_detector") or {}).get("application_id"), "input_statuses": statuses, "operator_recommendation": recommendation, "suggested_commands": ["python conscious_agent/main.py --patch-recovery-report --readiness-json", "python tools/smoke_check.py --tier install --json"], "repair_patch_generated": False, "retry_performed": False, "source_mutation_performed": False}
    return _report_from_rows("v77.6", "recovery_recommendation_builder", payload, rows, project_id, "Recovery recommendation builder tells the operator whether to retry, revise, rerun sandbox trial, inspect manually, or block future application.", RECOVERY_RECOMMENDATION_BUILDER, save)


def build_application_audit_timeline(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.7: build a human-readable audit timeline for application and recovery attempts."""
    core = _patch_recovery_core(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files=approved_files, application_id=application_id)
    now = _now()
    events = [
        {"order": 1, "event": "approval_contract_checked", "at": now, "status": "preview", "details": core.get("approval_id")},
        {"order": 2, "event": "recommendation_bound", "at": now, "status": "preview", "details": core.get("recommendation_id")},
        {"order": 3, "event": "rollback_snapshot_validated", "at": now, "status": "preview", "details": f"{len(core.get('snapshot', {}).get('files', []))} file records"},
        {"order": 4, "event": "partial_apply_checked", "at": now, "status": "preview", "details": "manifest comparison recorded"},
        {"order": 5, "event": "rollback_integrity_checked", "at": now, "status": "preview", "details": "pre/post manifests compared"},
        {"order": 6, "event": "operator_recovery_recommendation_ready", "at": now, "status": "preview", "details": "no automatic repair or retry"},
    ]
    rows = [
        {"name": "events", "status": "pass" if len(events) >= 6 else "blocked", "message": f"{len(events)} audit event(s)."},
        {"name": "application-id", "status": "pass" if core.get("application_id") else "blocked", "message": str(core.get("application_id"))},
        {"name": "operator-readable", "status": "pass", "message": "timeline explains what happened without applying new changes."},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.audit_timeline.v1", "application_id": core["application_id"], "events": events, "source_mutation_performed": False, "repair_patch_generated": False}
    return _report_from_rows("v77.7", "application_audit_timeline", payload, rows, project_id, "Application audit timeline records approval, snapshot, materialization, verification, rollback, and recovery recommendation events for operator review.", APPLICATION_AUDIT_TIMELINE, save)


def build_patch_recovery_dashboard_api_cli(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.8: expose recovery reports through dashboard/API/CLI without applying fixes."""
    dashboard_text = _read_source_text("conscious_agent/dashboard.py")
    main_text = _read_source_text("conscious_agent/main.py")
    api_text = _read_source_text("conscious_agent/api_server.py")
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    cli_flags = ["--patch-recovery-preflight", "--patch-recovery-snapshot", "--patch-recovery-partial-apply", "--patch-recovery-rollback-integrity", "--patch-recovery-triage", "--patch-recovery-recommendation", "--patch-recovery-timeline", "--patch-recovery-dashboard-api-cli", "--pre-v78-recovery-gate", "--verified-application-recovery-rollback-hardening", "--patch-application-id"]
    api_routes = ["/api/patch-recovery/preflight", "/api/patch-recovery/snapshot", "/api/patch-recovery/partial-apply", "/api/patch-recovery/rollback-integrity", "/api/patch-recovery/triage", "/api/patch-recovery/recommendation", "/api/patch-recovery/timeline", "/api/patch-recovery/parity", "/api/patch-recovery/gate", "/api/patch-recovery/layer"]
    rows = [
        {"name": "dashboard-route", "status": "pass" if "/patch-recovery" in dashboard_text and "Patch Recovery" in dashboard_text else "blocked", "message": "/patch-recovery dashboard route present."},
        {"name": "api-routes", "status": "pass" if all(route in api_text for route in api_routes[:7]) else "blocked", "message": "patch recovery API routes registered."},
        {"name": "cli-flags", "status": "pass" if all(flag in main_text for flag in cli_flags[:8]) else "blocked", "message": "patch recovery CLI flags registered."},
        {"name": "docs", "status": "pass" if "v78.0 - Verified Application Recovery and Rollback Hardening" in docs else "blocked", "message": "README and release history mention v78.0."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs."},
    ]
    payload = {"schema_version": "eidolon.patch_recovery.dashboard_api_cli.v1", "dashboard_path": "/patch-recovery", "api_routes": api_routes, "cli_flags": cli_flags, "custom_data_tip_only": not _dashboard_nav_title_regression_present(), "source_mutation_performed": False, "repair_patch_generated": False}
    return _report_from_rows("v77.8", "patch_recovery_dashboard_api_cli", payload, rows, project_id, "Patch recovery dashboard/API/CLI exposes read-only recovery and rollback hardening reports without retrying or repairing patches.", PATCH_RECOVERY_DASHBOARD_API_CLI, save)


def build_pre_v78_recovery_gate(project_id: str = "eidolon", patch_goal: str | None = None, draft_text: str | None = None, draft_file: str | None = None, trial_id: str | None = None, evidence_file: str | None = None, approval_file: str | None = None, approved_files: list[str] | str | None = None, application_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v77.9: verify recovery hardening is ready before v78.0."""
    parts = {
        "preflight": build_dirty_tree_preflight_detector(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "snapshot": build_snapshot_completeness_validator(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "partial_apply": build_partial_apply_detector(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "rollback_integrity": build_rollback_integrity_verifier(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "triage": build_failed_verification_triage(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "recommendation": build_recovery_recommendation_builder(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "timeline": build_application_audit_timeline(project_id, patch_goal, draft_text, draft_file, trial_id, evidence_file, approval_file, approved_files, application_id, save=False),
        "parity": build_patch_recovery_dashboard_api_cli(project_id, patch_goal, save=False),
        "privacy": build_package_privacy_scan(project_id=project_id, save=False),
    }
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in parts.items()]
    rows.extend([
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v78.0 - Verified Application Recovery and Rollback Hardening" in docs else "blocked", "message": "README and release history mention v78.0."},
        {"name": "no-auto-repair", "status": "pass", "message": "v78 gates report recovery state but never generate repairs, retry patches, or publish releases."},
    ])
    payload = {"schema_version": "eidolon.patch_recovery.pre_v78_gate.v1", "gate_id": _patch_context_id("prev78", {k: v.get("status") for k, v in parts.items()}), "steps": {k: _compact_step(v) for k, v in parts.items()}, "ready_for_recovery_hardening": _status_from(rows) != "blocked", "source_mutation_performed": False, "repair_patch_generated": False, "retry_performed": False}
    return _report_from_rows("v77.9", "pre_v78_recovery_gate", payload, rows, project_id, "Pre-v78 recovery gate verifies dirty-tree checks, snapshot completeness, partial-apply detection, rollback integrity, failure triage, recovery recommendations, timeline, parity, privacy, docs, and safety boundaries.", PRE_V78_RECOVERY_GATE, save)


