    payload = {"schema_version": "eidolon.patch_recovery.layer.v1", "layer_id": _patch_context_id("recoverylayer", {k: v.get("status") for k, v in parts.items()}), "version": SELF_MAINTENANCE_VERSION, "decision": "manual_review" if _status_from(rows) == "warn" else ("blocked" if _status_from(rows) == "blocked" else "recovery_ready"), "steps": {k: _compact_step(v) for k, v in parts.items()}, "source_mutation_performed": False, "repair_patch_generated": False, "retry_performed": False, "publish_performed": False, "memory_mutation_performed": False, "identity_mutation_performed": False, "recommended_next_arc": "v79.0 Multi-Patch Queue Planning Layer"}
    return _report_from_rows("v78.0", "verified_application_recovery_rollback_hardening", payload, rows, project_id, "Verified Application Recovery and Rollback Hardening detects dirty trees, validates snapshots, detects partial applies, verifies rollback integrity, triages failures, and recommends recovery without auto-repair.", VERIFIED_APPLICATION_RECOVERY_ROLLBACK_HARDENING, save)


