# v78.1-v79.0 multi-patch queue planning layer.
PATCH_QUEUE_DIR = DATA_DIR / "autonomy" / "patch_queue"
PATCH_QUEUE_RECORD_SCHEMA = SELF_MAINTENANCE_DIR / "patch_queue_record_schema.json"
PATCH_QUEUE_INTAKE_ORGANIZER = SELF_MAINTENANCE_DIR / "patch_queue_intake_organizer.json"
PATCH_QUEUE_CONFLICT_DETECTOR = SELF_MAINTENANCE_DIR / "patch_queue_conflict_detector.json"
PATCH_QUEUE_RISK_PRIORITY_SCHEDULER = SELF_MAINTENANCE_DIR / "patch_queue_risk_priority_scheduler.json"
PATCH_QUEUE_STALE_EVIDENCE_DETECTOR = SELF_MAINTENANCE_DIR / "patch_queue_stale_evidence_detector.json"
PATCH_QUEUE_SERIAL_TRIAL_PLAN_BUILDER = SELF_MAINTENANCE_DIR / "patch_queue_serial_trial_plan_builder.json"
PATCH_QUEUE_OPERATOR_REVIEW_PACKET = SELF_MAINTENANCE_DIR / "patch_queue_operator_review_packet.json"
PATCH_QUEUE_DASHBOARD_API_CLI = SELF_MAINTENANCE_DIR / "patch_queue_dashboard_api_cli.json"
PRE_V79_QUEUE_GATE = SELF_MAINTENANCE_DIR / "pre_v79_queue_gate.json"
MULTI_PATCH_QUEUE_PLANNING_LAYER = SELF_MAINTENANCE_DIR / "multi_patch_queue_planning_layer.json"
_PATCH_QUEUE_CORE_CACHE: dict[str, dict[str, Any]] = {}


def _patch_queue_id(goal: str | None = None, queue_id: str | None = None) -> str:
    if queue_id:
        cleaned = re.sub(r"[^a-zA-Z0-9_.-]+", "-", str(queue_id)).strip(".-_")[:80]
        if cleaned:
            return cleaned
    return _patch_context_id("queue", goal or "multi-patch queue")[:28]


def _load_patch_queue_items(queue_file: str | None, patch_goal: str | None) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    source = {"source": "generated", "path": None, "warning": "using generated sample queue"}
    items: list[dict[str, Any]] = []
    if queue_file:
        path = Path(str(queue_file))
        if not path.is_absolute():
            path = ROOT_DIR / path
        try:
            resolved = path.resolve()
            root = ROOT_DIR.resolve()
            if root in resolved.parents or resolved == root:
                raw = json.loads(resolved.read_text(encoding="utf-8"))
                if isinstance(raw, dict):
                    maybe = raw.get("items") or raw.get("patches") or raw.get("queue") or []
                else:
                    maybe = raw
                if isinstance(maybe, list):
                    for idx, item in enumerate(maybe):
                        if isinstance(item, dict):
                            items.append(dict(item))
                        else:
                            items.append({"goal": str(item)})
                    source = {"source": "file", "path": str(resolved.relative_to(root)), "warning": None}
        except (OSError, json.JSONDecodeError) as error:
            source = {"source": "generated", "path": str(queue_file), "warning": str(error)}
    if not items:
        items = [
            {"id": "queue-docs-context", "goal": patch_goal or "Document and verify the next supervised patch-planning arc.", "files": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"], "risk": "low", "evidence_status": "ready"},
            {"id": "queue-dashboard-parity", "goal": "Expose queue planning safely through dashboard/API/CLI without applying patches.", "files": ["conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py"], "risk": "moderate", "evidence_status": "needs_review"},
        ]
    normalized: list[dict[str, Any]] = []
    for idx, item in enumerate(items, start=1):
        files = item.get("files") or item.get("touched_files") or item.get("approved_files") or []
        if isinstance(files, str):
            files = [part.strip() for part in re.split(r"[,\n]+", files) if part.strip()]
        patch_id = str(item.get("id") or item.get("patch_id") or _patch_context_id("queueitem", {"idx": idx, "goal": item.get("goal")})[:16])
        normalized.append({
            "id": patch_id,
            "goal": str(item.get("goal") or item.get("patch_goal") or f"Patch queue item {idx}"),
            "files": [str(f).replace("\\", "/") for f in files if str(f).strip()],
            "risk": str(item.get("risk") or item.get("risk_classification") or "moderate"),
            "evidence_status": str(item.get("evidence_status") or item.get("recommendation_status") or "needs_review"),
            "depends_on": item.get("depends_on") or item.get("dependencies") or [],
            "recommendation_id": item.get("recommendation_id"),
            "trial_id": item.get("trial_id"),
        })
    return normalized, source


def _patch_queue_core(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None) -> dict[str, Any]:
    qid = _patch_queue_id(patch_goal, queue_id)
    cache_key = _patch_context_id("queuecore", {"project": project_id, "goal": patch_goal, "file": queue_file, "queue": qid})
    cached = _PATCH_QUEUE_CORE_CACHE.get(cache_key)
    if cached is not None:
        return cached
    items, source = _load_patch_queue_items(queue_file, patch_goal)
    core = {"project_id": project_id, "queue_id": qid, "goal": patch_goal or "Plan a supervised queue of multiple patch candidates without applying them.", "items": items, "source": source, "queue_path": str((PATCH_QUEUE_DIR / qid).resolve())}
    _PATCH_QUEUE_CORE_CACHE[cache_key] = core
    if len(_PATCH_QUEUE_CORE_CACHE) > 6:
        try:
            _PATCH_QUEUE_CORE_CACHE.pop(next(iter(_PATCH_QUEUE_CORE_CACHE)))
        except StopIteration:
            pass
    return core


def build_patch_queue_record_schema(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.1: define a strict record schema for multi-patch planning queues."""
    core = _patch_queue_core(project_id, patch_goal, queue_file, queue_id)
    required = ["id", "goal", "files", "risk", "evidence_status", "depends_on", "recommendation_id", "trial_id"]
    rows = [
        {"name": "required-fields", "status": "pass" if len(required) >= 7 else "blocked", "message": ", ".join(required)},
        {"name": "item-count", "status": "pass" if core.get("items") else "blocked", "message": f"{len(core.get('items', []))} queue item(s)."},
        {"name": "planning-only", "status": "pass", "message": "queue records cannot apply, approve, publish, or mutate memory/identity."},
    ]
    payload = {"schema_version": "eidolon.patch_queue.record_schema.v1", "queue_id": core["queue_id"], "required_fields": required, "optional_fields": ["priority", "blocked_reason", "operator_notes", "verification_commands"], "items_preview": core["items"], "source_mutation_performed": False}
    return _report_from_rows("v78.1", "patch_queue_record_schema", payload, rows, project_id, "Patch queue record schema defines the fields required to plan multiple patch candidates without applying them.", PATCH_QUEUE_RECORD_SCHEMA, save)


def build_patch_queue_intake_organizer(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.2: load and normalize multi-patch queue intake."""
    core = _patch_queue_core(project_id, patch_goal, queue_file, queue_id)
    items = core["items"]
    duplicate_ids = sorted({item["id"] for item in items if [i["id"] for i in items].count(item["id"]) > 1})
    rows = [
        {"name": "queue-source", "status": "warn" if core["source"].get("warning") else "pass", "message": core["source"].get("warning") or str(core["source"].get("path"))},
        {"name": "items-normalized", "status": "pass" if items else "blocked", "message": f"{len(items)} normalized queue item(s)."},
        {"name": "unique-ids", "status": "blocked" if duplicate_ids else "pass", "message": "duplicate ids: " + ", ".join(duplicate_ids) if duplicate_ids else "queue ids are unique"},
    ]
    payload = {"schema_version": "eidolon.patch_queue.intake.v1", "queue_id": core["queue_id"], "items": items, "source": core["source"], "source_mutation_performed": False, "patches_applied": False}
    return _report_from_rows("v78.2", "patch_queue_intake_organizer", payload, rows, project_id, "Patch queue intake organizer loads, normalizes, and deduplicates proposed patch candidates for planning only.", PATCH_QUEUE_INTAKE_ORGANIZER, save)


def _queue_conflicts(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    conflicts: list[dict[str, Any]] = []
    for i, left in enumerate(items):
        left_files = set(left.get("files") or [])
        for right in items[i + 1:]:
            overlap = sorted(left_files & set(right.get("files") or []))
            if overlap:
                conflicts.append({"left": left.get("id"), "right": right.get("id"), "overlap_files": overlap})
    return conflicts


def build_patch_queue_conflict_detector(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.3: detect file and dependency conflicts between queued patches."""
    core = _patch_queue_core(project_id, patch_goal, queue_file, queue_id)
    conflicts = _queue_conflicts(core["items"])
    dependency_edges = [{"patch": item["id"], "depends_on": item.get("depends_on") or []} for item in core["items"] if item.get("depends_on")]
    rows = [
        {"name": "file-conflicts", "status": "warn" if conflicts else "pass", "message": f"{len(conflicts)} file overlap conflict(s)."},
        {"name": "dependency-edges", "status": "pass", "message": f"{len(dependency_edges)} dependency edge set(s)."},
        {"name": "serial-required-on-conflict", "status": "pass", "message": "conflicts force serial planning; no patch is applied."},
    ]
    payload = {"schema_version": "eidolon.patch_queue.conflicts.v1", "queue_id": core["queue_id"], "conflicts": conflicts, "dependency_edges": dependency_edges, "requires_serial_order": bool(conflicts or dependency_edges), "source_mutation_performed": False}
    return _report_from_rows("v78.3", "patch_queue_conflict_detector", payload, rows, project_id, "Patch queue conflict detector finds overlapping files and dependency edges so queued patches can be ordered safely.", PATCH_QUEUE_CONFLICT_DETECTOR, save)


def build_patch_queue_risk_priority_scheduler(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.4: plan a risk-aware review order for queued patches."""
    core = _patch_queue_core(project_id, patch_goal, queue_file, queue_id)
    risk_rank = {"blocked": 99, "high": 30, "moderate": 20, "medium": 20, "low": 10}
    ordered = sorted(core["items"], key=lambda item: (risk_rank.get(str(item.get("risk", "moderate")).lower(), 20), item.get("id")))
    schedule = [{"order": idx, "id": item["id"], "risk": item.get("risk"), "operator_action": "manual_review" if item.get("risk") in {"high", "blocked"} else "review_then_trial"} for idx, item in enumerate(ordered, start=1)]
    rows = [
        {"name": "schedule", "status": "pass" if schedule else "blocked", "message": f"{len(schedule)} queue item(s) scheduled."},
        {"name": "high-risk-manual", "status": "pass", "message": "high/blocked risk items are held for manual review, not auto-applied."},
        {"name": "planning-only", "status": "pass", "message": "scheduler outputs review order only."},
    ]
    payload = {"schema_version": "eidolon.patch_queue.risk_scheduler.v1", "queue_id": core["queue_id"], "schedule": schedule, "source_mutation_performed": False, "patches_applied": False}
    return _report_from_rows("v78.4", "patch_queue_risk_priority_scheduler", payload, rows, project_id, "Patch queue risk priority scheduler orders queued patches by risk and review needs without executing them.", PATCH_QUEUE_RISK_PRIORITY_SCHEDULER, save)


def build_patch_queue_stale_evidence_detector(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.5: detect stale or missing sandbox/recommendation evidence in the queue."""
    core = _patch_queue_core(project_id, patch_goal, queue_file, queue_id)
    stale = []
    for item in core["items"]:
        if str(item.get("evidence_status", "")).lower() not in {"ready", "passed", "recommend_approval", "manual_review"} or not (item.get("recommendation_id") or item.get("trial_id")):
            stale.append({"id": item["id"], "evidence_status": item.get("evidence_status"), "recommendation_id": item.get("recommendation_id"), "trial_id": item.get("trial_id")})
    rows = [
        {"name": "stale-or-missing-evidence", "status": "warn" if stale else "pass", "message": f"{len(stale)} item(s) need refreshed evidence."},
        {"name": "stale-blocks-application", "status": "pass", "message": "stale items may be planned but not applied without fresh review/trial/recommendation evidence."},
    ]
    payload = {"schema_version": "eidolon.patch_queue.stale_evidence.v1", "queue_id": core["queue_id"], "stale_items": stale, "fresh_item_count": len(core["items"]) - len(stale), "source_mutation_performed": False}
    return _report_from_rows("v78.5", "patch_queue_stale_evidence_detector", payload, rows, project_id, "Patch queue stale evidence detector flags queued patches that need fresh review, sandbox trial, or recommendation packets before application.", PATCH_QUEUE_STALE_EVIDENCE_DETECTOR, save)


def build_patch_queue_serial_trial_plan_builder(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.6: build a serial sandbox trial plan for queued patches."""
    scheduler = build_patch_queue_risk_priority_scheduler(project_id, patch_goal, queue_file, queue_id, save=False)
    conflicts = build_patch_queue_conflict_detector(project_id, patch_goal, queue_file, queue_id, save=False)
    schedule = scheduler.get("patch_queue_risk_priority_scheduler", {}).get("schedule", [])
    plan = []
    for item in schedule:
        plan.append({"order": item["order"], "id": item["id"], "trial_mode": "serial", "required_before_trial": ["v74 review", "v75 sandbox", "v76 recommendation"], "parallel_allowed": False})
    rows = [
        {"name": "serial-plan", "status": "pass" if plan else "blocked", "message": f"{len(plan)} serial trial step(s)."},
        {"name": "conflict-aware", "status": "warn" if conflicts.get("status") == "warn" else "pass", "message": f"conflict status={conflicts.get('status')}"},
        {"name": "no-parallel-apply", "status": "pass", "message": "v79 plans trials only; it never batch-applies patches."},
    ]
    payload = {"schema_version": "eidolon.patch_queue.serial_trial_plan.v1", "queue_id": scheduler.get("patch_queue_risk_priority_scheduler", {}).get("queue_id"), "plan": plan, "source_mutation_performed": False, "patches_applied": False}
    return _report_from_rows("v78.6", "patch_queue_serial_trial_plan_builder", payload, rows, project_id, "Patch queue serial trial plan builder turns the queue schedule into an ordered sandbox-trial plan without parallel application.", PATCH_QUEUE_SERIAL_TRIAL_PLAN_BUILDER, save)


def build_patch_queue_operator_review_packet(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.7: build an operator review packet for the queued patch plan."""
    intake = build_patch_queue_intake_organizer(project_id, patch_goal, queue_file, queue_id, save=False)
    conflicts = build_patch_queue_conflict_detector(project_id, patch_goal, queue_file, queue_id, save=False)
    stale = build_patch_queue_stale_evidence_detector(project_id, patch_goal, queue_file, queue_id, save=False)
    serial = build_patch_queue_serial_trial_plan_builder(project_id, patch_goal, queue_file, queue_id, save=False)
    statuses = {"intake": intake.get("status"), "conflicts": conflicts.get("status"), "stale": stale.get("status"), "serial": serial.get("status")}
    recommendation = "operator_review_required" if "warn" in statuses.values() else "queue_ready_for_serial_review"
    rows = [{"name": k, "status": v or "blocked", "message": "queue review input"} for k, v in statuses.items()]
    rows.append({"name": "approval-boundary", "status": "pass", "message": "operator packet cannot approve or apply queued patches."})
    payload = {"schema_version": "eidolon.patch_queue.operator_review_packet.v1", "queue_id": (intake.get("patch_queue_intake_organizer") or {}).get("queue_id"), "statuses": statuses, "operator_recommendation": recommendation, "review_summary": {"item_count": len((intake.get("patch_queue_intake_organizer") or {}).get("items", [])), "conflict_count": len((conflicts.get("patch_queue_conflict_detector") or {}).get("conflicts", [])), "stale_count": len((stale.get("patch_queue_stale_evidence_detector") or {}).get("stale_items", []))}, "source_mutation_performed": False, "patches_applied": False}
    return _report_from_rows("v78.7", "patch_queue_operator_review_packet", payload, rows, project_id, "Patch queue operator review packet summarizes queue order, conflicts, stale evidence, and required human review before any later application layer.", PATCH_QUEUE_OPERATOR_REVIEW_PACKET, save)


def build_patch_queue_dashboard_api_cli(project_id: str = "eidolon", patch_goal: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.8: expose multi-patch queue planning through dashboard/API/CLI."""
    dashboard_text = _read_source_text("conscious_agent/dashboard.py")
    main_text = _read_source_text("conscious_agent/main.py")
    api_text = _read_source_text("conscious_agent/api_server.py")
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    cli_flags = ["--patch-queue-schema", "--patch-queue-intake", "--patch-queue-conflicts", "--patch-queue-priority", "--patch-queue-stale-evidence", "--patch-queue-serial-plan", "--patch-queue-review-packet", "--patch-queue-dashboard-api-cli", "--pre-v79-queue-gate", "--multi-patch-queue-planning-layer", "--patch-queue-file", "--patch-queue-id"]
    api_routes = ["/api/patch-queue/schema", "/api/patch-queue/intake", "/api/patch-queue/conflicts", "/api/patch-queue/priority", "/api/patch-queue/stale-evidence", "/api/patch-queue/serial-plan", "/api/patch-queue/review-packet", "/api/patch-queue/parity", "/api/patch-queue/gate", "/api/patch-queue/layer"]
    rows = [
        {"name": "dashboard-route", "status": "pass" if "/patch-queue" in dashboard_text and "Multi-Patch Queue" in dashboard_text else "blocked", "message": "/patch-queue dashboard route present."},
        {"name": "api-routes", "status": "pass" if all(route in api_text for route in api_routes[:7]) else "blocked", "message": "patch queue API routes registered."},
        {"name": "cli-flags", "status": "pass" if all(flag in main_text for flag in cli_flags[:10]) else "blocked", "message": "patch queue CLI flags registered."},
        {"name": "docs", "status": "pass" if "v79.0 - Multi-Patch Queue Planning Layer" in docs else "blocked", "message": "README and release history mention v79.0."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs."},
    ]
    payload = {"schema_version": "eidolon.patch_queue.dashboard_api_cli.v1", "dashboard_path": "/patch-queue", "api_routes": api_routes, "cli_flags": cli_flags, "custom_data_tip_only": not _dashboard_nav_title_regression_present(), "source_mutation_performed": False, "patches_applied": False}
    return _report_from_rows("v78.8", "patch_queue_dashboard_api_cli", payload, rows, project_id, "Patch queue dashboard/API/CLI exposes multi-patch planning surfaces without batch apply or approval bypass.", PATCH_QUEUE_DASHBOARD_API_CLI, save)


def build_pre_v79_queue_gate(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v78.9: verify the queue planning layer before v79.0."""
    parts = {
        "schema": build_patch_queue_record_schema(project_id, patch_goal, queue_file, queue_id, save=False),
        "intake": build_patch_queue_intake_organizer(project_id, patch_goal, queue_file, queue_id, save=False),
        "conflicts": build_patch_queue_conflict_detector(project_id, patch_goal, queue_file, queue_id, save=False),
        "priority": build_patch_queue_risk_priority_scheduler(project_id, patch_goal, queue_file, queue_id, save=False),
        "stale": build_patch_queue_stale_evidence_detector(project_id, patch_goal, queue_file, queue_id, save=False),
        "serial": build_patch_queue_serial_trial_plan_builder(project_id, patch_goal, queue_file, queue_id, save=False),
        "review": build_patch_queue_operator_review_packet(project_id, patch_goal, queue_file, queue_id, save=False),
        "parity": build_patch_queue_dashboard_api_cli(project_id, patch_goal, save=False),
        "privacy": build_package_privacy_scan(project_id=project_id, save=False),
    }
    docs = _read_source_text("README_NEXT_STEPS.md") + "\n" + _read_source_text("README_RELEASE_HISTORY.md")
    rows = [{"name": name, "status": _report_gate_status(report), "message": report.get("message", "")} for name, report in parts.items()]
    rows.extend([
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v79.0 - Multi-Patch Queue Planning Layer" in docs else "blocked", "message": "README and release history mention v79.0."},
        {"name": "planning-only", "status": "pass", "message": "pre-v79 gate never applies queued patches, grants approval, or runs autonomous loops."},
    ])
    payload = {"schema_version": "eidolon.patch_queue.pre_v79_gate.v1", "gate_id": _patch_context_id("prev79", {k: v.get("status") for k, v in parts.items()}), "steps": {k: _compact_step(v) for k, v in parts.items()}, "ready_for_multi_patch_queue_planning": _status_from(rows) != "blocked", "source_mutation_performed": False, "patches_applied": False, "approval_bypass_performed": False}
    return _report_from_rows("v78.9", "pre_v79_queue_gate", payload, rows, project_id, "Pre-v79 queue gate verifies schema, intake, conflict detection, risk scheduling, stale evidence detection, serial trial planning, operator packet, parity, privacy, docs, version markers, and safety boundaries.", PRE_V79_QUEUE_GATE, save)


def build_multi_patch_queue_planning_layer(project_id: str = "eidolon", patch_goal: str | None = None, queue_file: str | None = None, queue_id: str | None = None, save: bool = True) -> dict[str, Any]:
    """v79.0: integrated Multi-Patch Queue Planning Layer."""
    parts = {
        "schema": build_patch_queue_record_schema(project_id, patch_goal, queue_file, queue_id, save=False),
        "intake": build_patch_queue_intake_organizer(project_id, patch_goal, queue_file, queue_id, save=False),
        "conflicts": build_patch_queue_conflict_detector(project_id, patch_goal, queue_file, queue_id, save=False),
        "priority": build_patch_queue_risk_priority_scheduler(project_id, patch_goal, queue_file, queue_id, save=False),
        "stale": build_patch_queue_stale_evidence_detector(project_id, patch_goal, queue_file, queue_id, save=False),
        "serial": build_patch_queue_serial_trial_plan_builder(project_id, patch_goal, queue_file, queue_id, save=False),
        "review": build_patch_queue_operator_review_packet(project_id, patch_goal, queue_file, queue_id, save=False),
        "gate": build_pre_v79_queue_gate(project_id, patch_goal, queue_file, queue_id, save=False),
    }
    rows = [{"name": name, "status": _report_gate_status(value), "message": value.get("message", "")} for name, value in parts.items()]
    core = _patch_queue_core(project_id, patch_goal, queue_file, queue_id)
    if save:
        try:
            qpath = PATCH_QUEUE_DIR / core["queue_id"]
            qpath.mkdir(parents=True, exist_ok=True)
            write_text_atomic((qpath / "queue_plan.json"), json.dumps({"queue_id": core["queue_id"], "items": core["items"], "parts": {k: _compact_step(v) for k, v in parts.items()}, "created_at": _now()}, indent=2, default=str), encoding="utf-8")
        except OSError:
            rows.append({"name": "runtime-archive", "status": "warn", "message": "could not archive queue plan runtime artifact"})
    payload = {"schema_version": "eidolon.patch_queue.layer.v1", "layer_id": _patch_context_id("queuelayer", {k: v.get("status") for k, v in parts.items()}), "version": SELF_MAINTENANCE_VERSION, "queue_id": core["queue_id"], "decision": "operator_review_required" if _status_from(rows) == "warn" else ("blocked" if _status_from(rows) == "blocked" else "queue_plan_ready"), "item_count": len(core["items"]), "steps": {k: _compact_step(v) for k, v in parts.items()}, "source_mutation_performed": False, "patches_applied": False, "approval_bypass_performed": False, "publish_performed": False, "memory_mutation_performed": False, "identity_mutation_performed": False, "recommended_next_arc": "v80.0 Supervised Local Improvement Loop Planning"}
    return _report_from_rows("v79.0", "multi_patch_queue_planning_layer", payload, rows, project_id, "Multi-Patch Queue Planning Layer records, organizes, deconflicts, schedules, checks stale evidence, and prepares operator review for multiple patch candidates without applying them.", MULTI_PATCH_QUEUE_PLANNING_LAYER, save)


