V80_85_STAGE_BY_SLUG: dict[str, dict[str, Any]] = {item["slug"]: item for item in V80_85_STAGE_DEFS}
V80_85_RUNTIME_DIR = DATA_DIR / "autonomy" / "supervised_improvement_loop"


def _v80_85_id(kind: str, payload: Any) -> str:
    return _patch_context_id(kind, payload)[:28]


def _v80_85_cli_flag(slug: str) -> str:
    return "--" + slug.replace("_", "-")


def _v80_85_arc_steps(version: str) -> list[dict[str, Any]]:
    return [item for item in V80_85_STAGE_DEFS if item.get("version") == version and not item.get("is_final")]


def _v80_85_sample_candidates(improvement_goal: str | None = None) -> list[dict[str, Any]]:
    goal = improvement_goal or "Coordinate the next supervised Eidolon improvement without autonomous application."
    return [
        {"id": "candidate-context-docs", "goal": goal, "files": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"], "risk": "low", "evidence_status": "ready"},
        {"id": "candidate-dashboard-cli", "goal": "Expose supervised loop status through dashboard/API/CLI without source apply.", "files": ["conscious_agent/self_maintenance.py", "conscious_agent/main.py", "conscious_agent/dashboard.py"], "risk": "moderate", "evidence_status": "manual_review"},
    ]


def _build_v80_85_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, save: bool = True) -> dict[str, Any]:
    definition = V80_85_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Coordinate supervised local improvement safely."
    arc_steps = _v80_85_arc_steps(definition["version"])
    cli_flags = [_v80_85_cli_flag(item["slug"]) for item in arc_steps] + [_v80_85_cli_flag(definition["final_slug"]), "--improvement-goal", "--local-model-name", "--improvement-cycle-id", "--candidate-file"]
    api_routes = [f"/api/{definition['api']}/{item['route']}" for item in arc_steps] + [f"/api/{definition['api']}/layer"]
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    docs = _release_notes_text()
    rows: list[dict[str, Any]] = [
        {"name": "goal-bound", "status": "pass" if goal.strip() else "blocked", "message": goal},
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if f"{definition['version']} - {definition['final_label']}" in docs else "blocked", "message": f"README and release history mention {definition['version']}."},
        {"name": "safety-boundary", "status": "pass", "message": "No self-approval, autonomous source apply, publish, memory mutation, identity mutation, or approval bypass is performed."},
    ]
    if definition.get("is_final"):
        rows.extend([
            {"name": "substage-count", "status": "pass" if len(arc_steps) == 9 else "blocked", "message": f"{len(arc_steps)} substages defined before {definition['version']}."},
            {"name": "operator-stop", "status": "pass", "message": "Integrated flow ends at operator review or suggestion packet; it does not apply patches."},
        ])
    if "dashboard_api_cli" in slug or "dashboard" in definition["label"].lower() or definition.get("is_final"):
        missing_cli = [flag for flag in cli_flags if flag not in main_text]
        missing_api = [route for route in api_routes if route not in api_text]
        rows.extend([
            {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
            {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": "missing: " + ", ".join(missing_api) if missing_api else f"{len(api_routes)} API route(s) present."},
            {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": "missing: " + ", ".join(missing_cli) if missing_cli else f"{len(cli_flags)} CLI flag(s) present."},
            {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard nav keeps custom data-tip hover system without native title tooltips."},
        ])
    if "model" in slug or "invocation" in slug or definition["version"] == "v81.0":
        rows.append({"name": "local-model-default", "status": "pass", "message": f"Local model invocation remains disabled by default; model={model_name or 'manual-handoff'}."})
    if "suggestion" in slug or definition["version"] == "v85.0":
        rows.append({"name": "suggestion-only", "status": "pass", "message": "Suggestion loop organizes operator attention only; no automatic apply or queue execution."})
    payload = {
        "schema_version": f"eidolon.v80_85.{slug}.v1",
        "artifact_id": _v80_85_id(slug, {"project": project_id, "goal": goal, "cycle": cycle_id, "model": model_name}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "improvement_goal": goal,
        "cycle_id": cycle_id or _v80_85_id("cycle", goal),
        "model_name": model_name or "manual/local-disabled",
        "candidate_file": candidate_file,
        "sample_candidates": _v80_85_sample_candidates(goal),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": _v80_85_cli_flag(item["slug"]), "api_route": f"/api/{definition['api']}/{item['route']}"} for item in arc_steps],
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "operator_review_required": True,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} prepares supervised improvement work while preserving operator gates and preventing autonomous live mutation.", save_path, save)


def _make_v80_85_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, save: bool = True) -> dict[str, Any]:
        return _build_v80_85_stage(slug, project_id=project_id, improvement_goal=improvement_goal, model_name=model_name, cycle_id=cycle_id, candidate_file=candidate_file, save=save)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_v80_85_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = V80_85_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_v80_85_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_v80_85_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False) -> None:
        report = _build_v80_85_stage(slug, project_id=project_id, improvement_goal=improvement_goal, model_name=model_name, cycle_id=cycle_id, candidate_file=candidate_file, save=True)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _v80_85_def in V80_85_STAGE_DEFS:
    _slug = _v80_85_def["slug"]
    globals()[f"build_{_slug}"] = _make_v80_85_build(_slug)
    globals()[f"{_slug}_text"] = _make_v80_85_text(_slug)
    globals()[f"print_{_slug}"] = _make_v80_85_print(_slug)

