SUGGESTION_INBOX_STAGE_BY_SLUG = {item["slug"]: item for item in SUGGESTION_INBOX_STAGE_DEFS}


def _suggestion_inbox_slug_to_flag(slug: str) -> str:
    return "--" + slug.replace("_", "-")


def _suggestion_inbox_id(kind: str, seed: Any) -> str:
    raw = json.dumps(seed, sort_keys=True, default=str) if not isinstance(seed, str) else seed
    return f"{kind}-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]


def _suggestion_inbox_default_records(goal: str) -> list[dict[str, Any]]:
    base = [
        {
            "source": "safe_autonomous_suggestion_loop",
            "title": "Review recurring safe improvement suggestions",
            "category": "supervised_improvement",
            "priority": "medium",
            "risk": "low",
            "affected_files": ["conscious_agent/self_maintenance.py", "README_NEXT_STEPS.md"],
            "evidence": ["v85 safe suggestion loop output", goal],
        },
        {
            "source": "smoke_check",
            "title": "Keep suggestion inbox parity under smoke coverage",
            "category": "verification",
            "priority": "medium",
            "risk": "low",
            "affected_files": ["tools/smoke_check.py", "conscious_agent/main.py"],
            "evidence": ["dashboard/api/cli parity must remain testable"],
        },
        {
            "source": "operator_rule",
            "title": "Preserve custom data-tip dashboard hover system",
            "category": "dashboard_safety",
            "priority": "high",
            "risk": "low",
            "affected_files": ["conscious_agent/dashboard.py"],
            "evidence": ["native title tooltips previously caused double hover behavior"],
        },
    ]
    records: list[dict[str, Any]] = []
    for item in base:
        duplicate_hash = hashlib.sha256((item["title"] + "|" + ",".join(item["affected_files"])).encode("utf-8")).hexdigest()[:16]
        records.append({
            "suggestion_id": _suggestion_inbox_id("sug", item),
            "schema_version": "eidolon.suggestion_inbox.record.v1",
            "state": "new",
            "duplicate_hash": duplicate_hash,
            "operator_decision": None,
            "created_at": "preview",
            "updated_at": "preview",
            **item,
        })
    return records


def _suggestion_inbox_work_order(goal: str, suggestion: dict[str, Any]) -> dict[str, Any]:
    safe_title = suggestion.get("title") or "Supervised improvement work order"
    return {
        "work_order_id": _suggestion_inbox_id("wo", {"goal": goal, "suggestion": suggestion.get("suggestion_id")}),
        "schema_version": "eidolon.suggestion_inbox.work_order.v1",
        "source_suggestion_id": suggestion.get("suggestion_id"),
        "goal": safe_title,
        "reason": "; ".join(str(x) for x in suggestion.get("evidence", [])[:3]) or goal,
        "expected_files": suggestion.get("affected_files", []),
        "forbidden_files": ["data/autonomy/**", "data/self_maintenance/**", "identity/**", "memory/**"],
        "required_docs_updates": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "required_verification_commands": [
            "python -m py_compile conscious_agent/*.py tools/smoke_check.py",
            "python conscious_agent/main.py --supervised-suggestion-inbox-work-order-planner --readiness-json",
            "python tools/smoke_check.py --tier install --json",
        ],
        "risk_estimate": suggestion.get("risk", "low"),
        "rollback_expectations": "No live source apply occurs in this planner; any future patch must use existing operator-approved rollback gates.",
        "operator_approval_required": True,
        "patches_applied": False,
        "source_mutation_performed": False,
    }


def _suggestion_inbox_handoff_plan(suggestion: dict[str, Any]) -> dict[str, Any]:
    category = str(suggestion.get("category", "")).lower()
    files = " ".join(str(f).lower() for f in suggestion.get("affected_files", []))
    if "smoke" in category or "verification" in category or "tools/smoke_check.py" in files:
        destination = "v72 Patch Generation Context Builder -> v73 Patch Draft Composer -> v75 Sandbox Patch Trial Runner"
    elif "dashboard" in category or "dashboard.py" in files:
        destination = "v72 Patch Generation Context Builder -> v74 Patch Review -> dashboard/API/CLI parity checks"
    elif "model" in category:
        destination = "v81 Local Model Patch Proposal Integration, disabled by default"
    else:
        destination = "v72 Patch Generation Context Builder"
    return {
        "suggestion_id": suggestion.get("suggestion_id"),
        "recommended_destination": destination,
        "execute_now": False,
        "operator_approval_required": True,
    }


def _build_suggestion_inbox_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True) -> dict[str, Any]:
    definition = SUGGESTION_INBOX_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Convert safe improvement suggestions into supervised operator-reviewed work orders."
    arc_steps = [item for item in SUGGESTION_INBOX_STAGE_DEFS if item.get("stage", "") != "v86.0"]
    cli_flags = [_suggestion_inbox_slug_to_flag(item["slug"]) for item in SUGGESTION_INBOX_STAGE_DEFS] + ["--improvement-goal", "--candidate-file"]
    api_routes = [f"/api/suggestion-inbox/{item['route']}" for item in SUGGESTION_INBOX_STAGE_DEFS]
    records = _suggestion_inbox_default_records(goal)
    selected = records[0]
    work_order = _suggestion_inbox_work_order(goal, selected)
    handoff_plan = [_suggestion_inbox_handoff_plan(item) for item in records]
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_cli = [flag for flag in cli_flags if flag not in main_text]
    missing_api = [route for route in api_routes if route not in api_text]
    rows: list[dict[str, Any]] = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v86.0 - Supervised Suggestion Inbox and Work Order Planner" in docs else "blocked", "message": "README and release history mention v86.0."},
        {"name": "runtime-privacy", "status": "pass" if "data/autonomy/suggestion_inbox/" in release_packaging_text else "blocked", "message": "Suggestion inbox runtime records stay outside source-only packages."},
        {"name": "record-schema", "status": "pass" if all(k in selected for k in ["suggestion_id", "source", "title", "category", "priority", "risk", "affected_files", "evidence", "duplicate_hash", "state"]) else "blocked", "message": "Suggestion records include id, source, triage, evidence, duplicate hash, and lifecycle state."},
        {"name": "operator-triage", "status": "pass" if "accepted_for_planning" in SUGGESTION_INBOX_STATES and selected.get("state") != "accepted_for_planning" else "blocked", "message": "Only an operator can move a suggestion into accepted_for_planning."},
        {"name": "work-order-draft", "status": "pass" if work_order.get("operator_approval_required") and not work_order.get("patches_applied") else "blocked", "message": "Work order drafts are review packets, not patch execution."},
        {"name": "safety-contract", "status": "pass" if all(action in SUGGESTION_INBOX_FORBIDDEN_ACTIONS for action in ["self_approval", "live_source_apply", "release_publish", "memory_mutation", "identity_mutation", "approval_bypass"]) else "blocked", "message": "No self-approval, source apply, publish, memory mutation, identity mutation, or approval bypass."},
        {"name": "handoff-planner", "status": "pass" if handoff_plan and not any(item.get("execute_now") for item in handoff_plan) else "blocked", "message": "Pipeline handoff recommendations do not execute."},
        {"name": "dashboard-route", "status": "pass" if "/suggestion-inbox" in dashboard_text else "blocked", "message": "/suggestion-inbox dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": "missing: " + ", ".join(missing_api) if missing_api else f"{len(api_routes)} API route(s) present."},
        {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": "missing: " + ", ".join(missing_cli) if missing_cli else f"{len(cli_flags)} CLI flag(s) present."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard nav keeps custom data-tip hover system without native title tooltips."},
        {"name": "no-autonomy", "status": "pass", "message": "Planner prepares, reviews, dedupes, drafts, and routes suggestions but does not apply, publish, self-approve, or mutate memory/identity."},
    ]
    if definition.get("is_final"):
        rows.append({"name": "substage-count", "status": "pass" if len(arc_steps) == 9 else "blocked", "message": f"{len(arc_steps)} substages defined before v86.0."})
    payload = {
        "schema_version": f"eidolon.v86.{slug}.v1",
        "artifact_id": _suggestion_inbox_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": "v86.0",
        "theme": "Supervised suggestion inbox and work order planning without autonomous mutation.",
        "dashboard_path": "/suggestion-inbox",
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": str(SUGGESTION_INBOX_RUNTIME_DIR.relative_to(ROOT_DIR) if SUGGESTION_INBOX_RUNTIME_DIR.is_relative_to(ROOT_DIR) else SUGGESTION_INBOX_RUNTIME_DIR),
        "suggestion_states": SUGGESTION_INBOX_STATES,
        "forbidden_actions": SUGGESTION_INBOX_FORBIDDEN_ACTIONS,
        "suggestion_records_preview": records,
        "duplicate_groups_preview": [{"duplicate_hash": records[0]["duplicate_hash"], "suggestion_ids": [records[0]["suggestion_id"]], "auto_dismissed": False}],
        "work_order_preview": work_order,
        "handoff_plan_preview": handoff_plan,
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": _suggestion_inbox_slug_to_flag(item["slug"]), "api_route": f"/api/suggestion-inbox/{item['route']}"} for item in arc_steps],
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "operator_review_required": True,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} keeps suggestions in supervised operator-review flow and only drafts non-executing work orders.", save_path, save)


def _make_suggestion_inbox_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
        return _build_suggestion_inbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_suggestion_inbox_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = SUGGESTION_INBOX_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_suggestion_inbox_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_suggestion_inbox_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **_: Any) -> None:
        report = _build_suggestion_inbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _suggestion_inbox_def in SUGGESTION_INBOX_STAGE_DEFS:
    _slug = _suggestion_inbox_def["slug"]
    globals()[f"build_{_slug}"] = _make_suggestion_inbox_build(_slug)
    globals()[f"{_slug}_text"] = _make_suggestion_inbox_text(_slug)
    globals()[f"print_{_slug}"] = _make_suggestion_inbox_print(_slug)

