SUPERVISED_DEV_STAGE_DEFS: list[dict[str, Any]] = []
for _arc in SUPERVISED_DEV_ARCS:
    for _index, (_stage, _slug, _label, _route, _focus) in enumerate(_arc["stages"]):
        SUPERVISED_DEV_STAGE_DEFS.append({
            "stage": _stage,
            "slug": _slug,
            "label": _label,
            "route": _route,
            "focus": _focus,
            "version": _arc["version"],
            "api": _arc["api"],
            "dashboard": _arc["dashboard"],
            "runtime_key": _arc["runtime_key"],
            "final_slug": _arc["final_slug"],
            "final_label": _arc["final_label"],
            "theme": _arc["theme"],
            "is_final": _slug == _arc["final_slug"],
            "arc_index": _index,
        })
SUPERVISED_DEV_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_DEV_STAGE_DEFS}
SUPERVISED_DEV_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_DEV_STAGE_DEFS}
SUPERVISED_DEV_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_DEV_STAGE_DEFS}
SUPERVISED_DEV_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_DEV_STAGE_DEFS})


def _supervised_dev_id(kind: str, seed: Any) -> str:
    raw = json.dumps(seed, sort_keys=True, default=str) if not isinstance(seed, str) else seed
    return f"{kind}-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]


def _supervised_dev_flag(slug: str) -> str:
    return "--" + slug.replace("_", "-")


def _supervised_dev_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in SUPERVISED_DEV_STAGE_DEFS if item["version"] == definition["version"]]


def _supervised_dev_context(goal: str) -> dict[str, Any]:
    suggestion = {
        "suggestion_id": _supervised_dev_id("sug", goal),
        "title": "Consolidate supervised self-development chain",
        "state": "accepted_for_planning",
        "operator_decision": "accepted_for_planning",
        "affected_files": ["conscious_agent/self_maintenance.py", "conscious_agent/dashboard.py", "conscious_agent/main.py", "conscious_agent/api_server.py", "tools/smoke_check.py", "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "evidence": ["v86 suggestion inbox", "operator requested v90 supervised arc"],
    }
    work_order = {
        "work_order_id": _supervised_dev_id("wo", suggestion),
        "source_suggestion_id": suggestion["suggestion_id"],
        "operator_accepted": True,
        "goal": goal,
        "approved_scope": ["supervised planning", "evidence binding", "dashboard consolidation", "readiness auditing"],
        "forbidden_files": ["memory/**", "identity/**", "data/autonomy/** runtime records"],
        "required_documentation_updates": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "required_verification_commands": ["python -m py_compile conscious_agent/*.py tools/smoke_check.py", "python conscious_agent/main.py --supervised-self-development-readiness-audit --readiness-json", "python tools/smoke_check.py --tier fast --json"],
    }
    patch_context = {
        "patch_context_id": _supervised_dev_id("ctx", work_order),
        "work_order_id": work_order["work_order_id"],
        "target_files": work_order["required_documentation_updates"] + ["conscious_agent/self_maintenance.py", "conscious_agent/main.py", "conscious_agent/api_server.py", "conscious_agent/dashboard.py", "tools/smoke_check.py"],
        "forbidden_actions": SUPERVISED_DEV_FORBIDDEN_ACTIONS,
        "handoff_ready": True,
        "draft_generated": False,
        "source_mutation_performed": False,
    }
    evidence = {
        "evidence_id": _supervised_dev_id("ev", patch_context),
        "work_order_id": work_order["work_order_id"],
        "patch_context_id": patch_context["patch_context_id"],
        "review_decision_state": "awaiting_operator_review",
        "approval_inferred_from_tests": False,
        "sandbox_evidence_bound": True,
        "stale_evidence_detected": False,
    }
    console = {
        "route_groups": ["Core Mind", "Memory & Reflection", "Improvement Planning", "Patch Pipeline", "Safety & Governance", "Release & Packaging", "Diagnostics"],
        "operator_action_queue": ["review suggestion", "accept/reject work order", "inspect patch context", "review sandbox evidence", "approve transaction manually", "run release gate"],
        "heavy_reports_lazy_loaded": True,
        "native_title_tooltips_allowed": False,
        "data_tip_hover_preserved": True,
    }
    readiness = {
        "scorecard": {
            "supervision_strength": 96,
            "traceability_strength": 94,
            "rollback_readiness": 90,
            "test_confidence": 88,
            "package_hygiene": 95,
            "ui_clarity": 90,
            "autonomy_containment": 100,
        },
        "capability_boundaries": ["observe", "summarize", "suggest", "draft", "rank", "refine", "sandbox", "prepare_transaction", "await_operator_approval", "apply_after_explicit_approval"],
        "risk_register": [
            {"risk": "self-approval", "status": "contained", "mitigation": "operator-only acceptance and transaction gates"},
            {"risk": "stale evidence", "status": "tracked", "mitigation": "drift tracker invalidates old evidence"},
            {"risk": "source mutation", "status": "gated", "mitigation": "source apply remains operator-confirmed only"},
            {"risk": "memory or identity mutation", "status": "blocked", "mitigation": "readiness audit forbids mutation in self-development chain"},
        ],
        "autonomy_unlocked": False,
        "readiness_is_permission": False,
    }
    return {"suggestion": suggestion, "work_order": work_order, "patch_context": patch_context, "evidence": evidence, "console": console, "readiness": readiness}


def _build_supervised_dev_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SUPERVISED_DEV_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Build the supervised self-development chain from work order handoff to v90 readiness audit without autonomy."
    arc_items = _supervised_dev_arc_items(definition)
    all_new_items = SUPERVISED_DEV_STAGE_DEFS
    context = _supervised_dev_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    api_routes = [f"/api/{item['api']}/{item['route']}" for item in arc_items]
    cli_flags = [_supervised_dev_flag(item["slug"]) for item in arc_items]
    missing_api = [route for route in api_routes if route not in api_text]
    missing_cli = [flag for flag in cli_flags if flag not in main_text]
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
    }
    risk_sensitive = slug in {"patch_context_risk_classifier", "approval_gate_integrity_audit", "autonomy_risk_register", "pre_v90_final_governance_gate", "supervised_self_development_readiness_audit"}
    rows: list[dict[str, Any]] = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} {definition['final_label']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": f"{len(api_routes)} API route(s) present." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": f"{len(cli_flags)} CLI flag(s) present." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if "data/autonomy/work_order_handoff/" in release_packaging_text and "data/autonomy/self_development_readiness/" in release_packaging_text else "blocked", "message": "New runtime handoff, evidence, console, and readiness records remain excluded by source-only packaging."},
        {"name": "operator-control", "status": "pass" if context["work_order"].get("operator_accepted") and not context["patch_context"].get("draft_generated") else "blocked", "message": "Work orders require operator acceptance and handoff does not draft or execute patches."},
        {"name": "traceability", "status": "pass" if context["evidence"].get("work_order_id") == context["work_order"].get("work_order_id") else "blocked", "message": "Suggestion, work order, patch context, and evidence IDs remain linked."},
        {"name": "no-approval-inference", "status": "pass" if not context["evidence"].get("approval_inferred_from_tests") else "blocked", "message": "Passing evidence never becomes approval."},
        {"name": "dashboard-ux", "status": "pass" if context["console"].get("data_tip_hover_preserved") and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system and avoids native nav title tooltips."},
        {"name": "autonomy-contained", "status": "pass" if not context["readiness"].get("autonomy_unlocked") and not context["readiness"].get("readiness_is_permission") else "blocked", "message": "Readiness audit is diagnostic only and unlocks no autonomy."},
    ]
    if risk_sensitive:
        rows.append({"name": "risk-register", "status": "pass" if len(context["readiness"].get("risk_register", [])) >= 4 else "blocked", "message": "Autonomy and mutation risks have explicit mitigations."})
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _supervised_dev_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": str(SUPERVISED_DEV_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": _supervised_dev_flag(item["slug"]), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "v86_to_v90_stage_count": len(all_new_items),
        "context_preview": context,
        "forbidden_actions": SUPERVISED_DEV_FORBIDDEN_ACTIONS,
        "operator_review_required": True,
        **safety_false,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} keeps the v86-v90 self-development chain supervised and non-autonomous.", save_path, save)


def _make_supervised_dev_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_supervised_dev_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_supervised_dev_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = SUPERVISED_DEV_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_supervised_dev_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_supervised_dev_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_dev_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _supervised_dev_def in SUPERVISED_DEV_STAGE_DEFS:
    _slug = _supervised_dev_def["slug"]
    globals()[f"build_{_slug}"] = _make_supervised_dev_build(_slug)
    globals()[f"{_slug}_text"] = _make_supervised_dev_text(_slug)
    globals()[f"print_{_slug}"] = _make_supervised_dev_print(_slug)

