SUPERVISED_RUNTIME_STAGE_DEFS: list[dict[str, Any]] = []
for _arc in SUPERVISED_RUNTIME_ARCS:
    for _index, (_stage, _slug, _label, _route, _focus) in enumerate(_arc["stages"]):
        SUPERVISED_RUNTIME_STAGE_DEFS.append({
            "stage": _stage,
            "slug": _slug,
            "label": _label,
            "route": _route,
            "focus": _focus,
            "version": _arc["version"],
            "api": _arc["api"],
            "dashboard": _arc["dashboard"],
            "runtime_key": _arc["runtime_key"],
            "final_slug": _arc["final_slug"],
            "final_label": _arc["final_label"],
            "theme": _arc["theme"],
            "is_final": _slug == _arc["final_slug"],
            "arc_index": _index,
        })
SUPERVISED_RUNTIME_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_RUNTIME_STAGE_DEFS}
SUPERVISED_RUNTIME_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_RUNTIME_STAGE_DEFS}
SUPERVISED_RUNTIME_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_RUNTIME_STAGE_DEFS}
SUPERVISED_RUNTIME_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_RUNTIME_STAGE_DEFS})


def _supervised_runtime_id(kind: str, seed: Any) -> str:
    raw = json.dumps(seed, sort_keys=True, default=str) if not isinstance(seed, str) else seed
    return f"{kind}-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]


def _supervised_runtime_flag(slug: str) -> str:
    return "--" + slug.replace("_", "-")


def _supervised_runtime_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in SUPERVISED_RUNTIME_STAGE_DEFS if item["version"] == definition["version"]]


def _supervised_runtime_context(goal: str) -> dict[str, Any]:
    suggestion = {"suggestion_id": _supervised_runtime_id("sug", goal), "state": "accepted_for_planning", "title": "Govern the supervised improvement runtime"}
    work_order = {"work_order_id": _supervised_runtime_id("wo", suggestion), "source_suggestion_id": suggestion["suggestion_id"], "operator_accepted": True, "goal": goal}
    session = {
        "session_id": _supervised_runtime_id("session", work_order),
        "title": "v91-v95 supervised runtime session",
        "linked_suggestions": [suggestion["suggestion_id"]],
        "linked_work_orders": [work_order["work_order_id"]],
        "state": "awaiting_operator_review",
        "operator_opened": False,
        "approval_state_entered_by_operator_only": True,
        "allowed_files": ["conscious_agent/self_maintenance.py", "conscious_agent/dashboard.py", "conscious_agent/main.py", "conscious_agent/api_server.py", "tools/smoke_check.py", "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
        "forbidden_files": ["data/autonomy/** runtime records", "memory/**", "identity/**"],
    }
    approval = {
        "approval_id": _supervised_runtime_id("approval", session),
        "linked_session_id": session["session_id"],
        "requested_action": "operator_review",
        "decision": "pending",
        "approval_inferred_from_tests": False,
        "approval_inferred_from_ranking": False,
        "approval_inferred_from_readiness_score": False,
        "operator_explicit_confirmation_required": True,
        "dependencies_clear": False,
        "decision_history_preserved": True,
    }
    experiment = {
        "experiment_id": _supervised_runtime_id("experiment", approval),
        "linked_session_id": session["session_id"],
        "sandbox_path_planned": "data/experiments/preview-only",
        "live_source_mutation_performed": False,
        "promotion_requires_operator_transaction": True,
        "evidence_contract": ["command output", "diff summary", "smoke result", "dashboard route status", "API route status", "package privacy status", "operator notes"],
    }
    reflection = {
        "reflection_id": _supervised_runtime_id("reflection", experiment),
        "linked_session_id": session["session_id"],
        "outcome": "advisory_pending_operator_review",
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "direct_patch_created": False,
        "safe_suggestion_handoff_only": True,
        "recurring_issue_categories": ["README update", "release history drift", "package privacy", "dashboard tooltip regression", "CLI/API parity", "slow smoke checks"],
    }
    cycle = {
        "cycle_id": _supervised_runtime_id("cycle", reflection),
        "chain": ["suggestion", "work_order", "development_session", "approval_request", "experiment_plan", "patch_context", "evidence", "operator_decision", "outcome_reflection", "next_suggestion"],
        "current_stage": "operator_action_needed",
        "blockers": ["explicit operator decision missing", "sandbox evidence not yet bound", "transaction not approved"],
        "next_step_recommendation": "operator reviews the generated session, approval, experiment, and cycle packets",
        "timeline_built": True,
        "governance_passed": True,
    }
    return {"suggestion": suggestion, "work_order": work_order, "session": session, "approval": approval, "experiment": experiment, "reflection": reflection, "cycle": cycle}


def _build_supervised_runtime_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SUPERVISED_RUNTIME_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Operate the v91-v95 supervised improvement runtime without autonomy."
    arc_items = _supervised_runtime_arc_items(definition)
    context = _supervised_runtime_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    api_routes = [f"/api/{item['api']}/{item['route']}" for item in arc_items]
    cli_flags = [_supervised_runtime_flag(item["slug"]) for item in arc_items]
    missing_api = [route for route in api_routes if route not in api_text]
    missing_cli = [flag for flag in cli_flags if flag not in main_text]
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    runtime_tokens = ["data/autonomy/development_sessions/", "data/autonomy/approval_console/", "data/autonomy/experiment_planner/", "data/autonomy/outcome_reflections/", "data/autonomy/improvement_cycles/"]
    runtime_privacy_ok = all(token in release_packaging_text for token in runtime_tokens)
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "experiment_promoted_without_transaction": False,
    }
    rows: list[dict[str, Any]] = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} {definition['final_label']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": f"{len(api_routes)} API route(s) present." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": f"{len(cli_flags)} CLI flag(s) present." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_privacy_ok else "blocked", "message": "Session, approval, experiment, reflection, and cycle runtime records remain excluded by source-only packaging."},
        {"name": "session-supervision", "status": "pass" if context["session"].get("approval_state_entered_by_operator_only") else "blocked", "message": "Development sessions are traceable containers and cannot self-enter approval states."},
        {"name": "approval-integrity", "status": "pass" if not context["approval"].get("approval_inferred_from_tests") and not context["approval"].get("approval_inferred_from_ranking") and not context["approval"].get("approval_inferred_from_readiness_score") else "blocked", "message": "Approvals require explicit operator confirmation and are never inferred."},
        {"name": "experiment-containment", "status": "pass" if not context["experiment"].get("live_source_mutation_performed") and context["experiment"].get("promotion_requires_operator_transaction") else "blocked", "message": "Experiments plan sandbox metadata only and promotion remains transaction-gated."},
        {"name": "reflection-containment", "status": "pass" if not context["reflection"].get("memory_mutation_performed") and not context["reflection"].get("identity_mutation_performed") and context["reflection"].get("safe_suggestion_handoff_only") else "blocked", "message": "Outcome reflections are advisory and may only hand safe suggestions to triage."},
        {"name": "cycle-governance", "status": "pass" if context["cycle"].get("governance_passed") and not any(safety_false.values()) else "blocked", "message": "Improvement cycles recommend next steps without execution, mutation, or autonomy unlock."},
        {"name": "dashboard-ux", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _supervised_runtime_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": str(SUPERVISED_RUNTIME_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": _supervised_runtime_flag(item["slug"]), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "v90_to_v95_stage_count": len(SUPERVISED_RUNTIME_STAGE_DEFS),
        "context_preview": context,
        "forbidden_actions": SUPERVISED_RUNTIME_FORBIDDEN_ACTIONS,
        "operator_review_required": True,
        **safety_false,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} keeps the v90-v95 runtime supervised, traceable, and non-autonomous.", save_path, save)


def _make_supervised_runtime_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_supervised_runtime_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_supervised_runtime_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = SUPERVISED_RUNTIME_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_supervised_runtime_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_supervised_runtime_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_runtime_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _supervised_runtime_def in SUPERVISED_RUNTIME_STAGE_DEFS:
    _slug = _supervised_runtime_def["slug"]
    globals()[f"build_{_slug}"] = _make_supervised_runtime_build(_slug)
    globals()[f"{_slug}_text"] = _make_supervised_runtime_text(_slug)
    globals()[f"print_{_slug}"] = _make_supervised_runtime_print(_slug)

