GOVERNED_SIMULATION_STAGE_DEFS: list[dict[str, Any]] = []
for _arc in GOVERNED_SIMULATION_ARCS:
    for _index, (_stage, _slug, _label, _route, _focus) in enumerate(_arc["stages"]):
        GOVERNED_SIMULATION_STAGE_DEFS.append({
            "stage": _stage,
            "slug": _slug,
            "label": _label,
            "route": _route,
            "focus": _focus,
            "version": _arc["version"],
            "api": _arc["api"],
            "dashboard": _arc["dashboard"],
            "runtime_key": _arc["runtime_key"],
            "final_slug": _arc["final_slug"],
            "final_label": _arc["final_label"],
            "theme": _arc["theme"],
            "is_final": _slug == _arc["final_slug"],
            "arc_index": _index,
        })
GOVERNED_SIMULATION_STAGE_BY_SLUG = {item["slug"]: item for item in GOVERNED_SIMULATION_STAGE_DEFS}
GOVERNED_SIMULATION_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in GOVERNED_SIMULATION_STAGE_DEFS}
GOVERNED_SIMULATION_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in GOVERNED_SIMULATION_STAGE_DEFS}
GOVERNED_SIMULATION_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in GOVERNED_SIMULATION_STAGE_DEFS})


def _governed_simulation_id(kind: str, seed: Any) -> str:
    raw = json.dumps(seed, sort_keys=True, default=str) if not isinstance(seed, str) else seed
    return f"{kind}-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]


def _governed_simulation_flag(slug: str) -> str:
    return "--" + slug.replace("_", "-")


def _governed_simulation_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in GOVERNED_SIMULATION_STAGE_DEFS if item["version"] == definition["version"]]


def _governed_simulation_context(goal: str) -> dict[str, Any]:
    replay = {
        "replay_id": _governed_simulation_id("replay", goal),
        "fixtures": ["docs_only", "dashboard_route", "cli_api_parity", "package_privacy", "smoke_failure", "stale_evidence", "autonomy_sensitive_block", "release_history_missing", "tooltip_regression"],
        "live_source_mutation_performed": False,
        "transaction_executed": False,
        "approval_created_as_decision": False,
        "benchmark_unlocks_capability": False,
        "expected_safe_outputs_present": True,
    }
    capability = {
        "ledger_id": _governed_simulation_id("capability", replay),
        "allowed": ["observe", "summarize", "suggest", "draft", "rank", "refine", "simulate", "prepare_review_packet", "request_operator_approval"],
        "gated": ["sandbox_with_permission", "apply_after_operator_approval", "publish_after_operator_approval"],
        "blocked": ["self_approve", "mutate_memory", "mutate_identity", "approval_bypass", "autonomy_unlock", "simulation_to_execution"],
        "budget_limits": {"suggestions_per_cycle": 10, "patch_candidates": 5, "replay_attempts": 20, "experiment_plans": 5, "local_model_calls_default": 0, "heavy_dashboard_reports": 3},
        "budget_exhaustion_blocks_planning": True,
    }
    shadow = {
        "simulation_id": _governed_simulation_id("shadow", capability),
        "simulated_intention": "draft approval request for operator review",
        "execution_performed": False,
        "approval_performed": False,
        "file_mutation_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "actions_map_to_approval_or_block": True,
        "unsafe_execution_wording_flagged": True,
    }
    failure = {
        "scenario_id": _governed_simulation_id("failure", shadow),
        "scenarios": ["failed_smoke", "package_privacy_leak", "dashboard_crash", "native_tooltip_regression", "stale_evidence", "bad_patch", "missing_readme", "missing_release_history", "unsafe_approval", "local_model_hallucination", "experiment_self_promotion"],
        "automatic_rollback_performed": False,
        "source_mutation_performed": False,
        "publish_performed": False,
        "operator_action_required": True,
        "recovery_evidence_required": True,
    }
    milestone = {
        "audit_id": _governed_simulation_id("milestone", failure),
        "areas": ["memory_architecture", "reflection_architecture", "identity_boundaries", "goals", "supervised_self_development", "safety_gates", "local_model_usage", "dashboard_usability", "release_discipline", "operator_control"],
        "architecture_chain": ["memory", "reflection", "goals", "suggestions", "work_orders", "sessions", "approvals", "experiments", "evidence", "reflection", "future_suggestions"],
        "hidden_identity_mutation": False,
        "unsupervised_memory_write": False,
        "reflection_to_memory_bypass": False,
        "local_model_memory_overwrite": False,
        "autonomy_unlock": False,
        "scorecard_unlocks_capability": False,
        "operator_burden_review_included": True,
    }
    return {"replay": replay, "capability": capability, "shadow": shadow, "failure": failure, "milestone": milestone}


def _build_governed_simulation_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = GOVERNED_SIMULATION_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Rehearse, limit, stress-test, and audit supervised self-development without autonomy."
    arc_items = _governed_simulation_arc_items(definition)
    context = _governed_simulation_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    api_routes = [f"/api/{item['api']}/{item['route']}" for item in arc_items]
    cli_flags = [_governed_simulation_flag(item["slug"]) for item in arc_items]
    missing_api = [route for route in api_routes if route not in api_text]
    missing_cli = [flag for flag in cli_flags if flag not in main_text]
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    runtime_tokens = ["data/autonomy/cycle_replay/", "data/autonomy/capability_ledger/", "data/autonomy/shadow_autonomy/", "data/autonomy/failure_war_games/", "data/autonomy/mind_milestone_audit/"]
    runtime_privacy_ok = all(token in release_packaging_text for token in runtime_tokens)
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "experiment_promoted_without_transaction": False,
        "simulation_executed": False,
        "automatic_rollback_performed": False,
        "scorecard_unlocks_capability": False,
    }
    rows: list[dict[str, Any]] = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} {definition['final_label']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": f"{len(api_routes)} API route(s) present." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": f"{len(cli_flags)} CLI flag(s) present." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_privacy_ok else "blocked", "message": "Replay, capability ledger, shadow autonomy, failure war game, and milestone audit runtime records remain excluded by source-only packaging."},
        {"name": "replay-containment", "status": "pass" if not context["replay"].get("live_source_mutation_performed") and not context["replay"].get("transaction_executed") and not context["replay"].get("benchmark_unlocks_capability") else "blocked", "message": "Cycle replay remains simulation-only and benchmarks do not unlock capability."},
        {"name": "capability-boundary", "status": "pass" if all(item in context["capability"].get("blocked", []) for item in ["self_approve", "mutate_memory", "mutate_identity", "approval_bypass", "autonomy_unlock", "simulation_to_execution"]) else "blocked", "message": "Capability ledger blocks self-approval, memory/identity mutation, bypass, autonomy unlock, and simulation-to-execution."},
        {"name": "shadow-containment", "status": "pass" if not context["shadow"].get("execution_performed") and not context["shadow"].get("approval_performed") and context["shadow"].get("actions_map_to_approval_or_block") else "blocked", "message": "Shadow autonomy maps simulated intentions to approval requests or block states only."},
        {"name": "failure-war-game-containment", "status": "pass" if not context["failure"].get("automatic_rollback_performed") and not context["failure"].get("source_mutation_performed") and context["failure"].get("operator_action_required") else "blocked", "message": "Failure war games rehearse recovery and rollback without executing recovery automatically."},
        {"name": "mind-boundary", "status": "pass" if not context["milestone"].get("hidden_identity_mutation") and not context["milestone"].get("unsupervised_memory_write") and not context["milestone"].get("autonomy_unlock") and not context["milestone"].get("scorecard_unlocks_capability") else "blocked", "message": "Milestone audit checks mind architecture without memory, identity, or autonomy mutation."},
        {"name": "dashboard-ux", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _governed_simulation_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": str(GOVERNED_SIMULATION_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": _governed_simulation_flag(item["slug"]), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "v95_to_v100_stage_count": len(GOVERNED_SIMULATION_STAGE_DEFS),
        "context_preview": context,
        "forbidden_actions": GOVERNED_SIMULATION_FORBIDDEN_ACTIONS,
        "operator_review_required": True,
        "simulation_only": True,
        "scorecard_diagnostic_only": True,
        **safety_false,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} keeps the v95-v100 stretch simulated, bounded, stress-tested, audited, and non-autonomous.", save_path, save)


def _make_governed_simulation_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_governed_simulation_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_governed_simulation_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = GOVERNED_SIMULATION_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_governed_simulation_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_governed_simulation_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_governed_simulation_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _governed_simulation_def in GOVERNED_SIMULATION_STAGE_DEFS:
    _slug = _governed_simulation_def["slug"]
    globals()[f"build_{_slug}"] = _make_governed_simulation_build(_slug)
    globals()[f"{_slug}_text"] = _make_governed_simulation_text(_slug)
    globals()[f"print_{_slug}"] = _make_governed_simulation_print(_slug)

