COHERENT_RUNTIME_STAGE_DEFS: list[dict[str, Any]] = []
for _coherent_arc in COHERENT_RUNTIME_ARCS:
    for _stage, _slug, _label, _route, _description in _coherent_arc["stages"]:
        COHERENT_RUNTIME_STAGE_DEFS.append({
            "stage": _stage,
            "slug": _slug,
            "label": _label,
            "route": _route,
            "api": _coherent_arc["api"],
            "version": _coherent_arc["version"],
            "dashboard": _coherent_arc["dashboard"],
            "runtime_key": _coherent_arc["runtime_key"],
            "final_slug": _coherent_arc["final_slug"],
            "final_label": _coherent_arc["final_label"],
            "theme": _coherent_arc["theme"],
            "description": _description,
        })
COHERENT_RUNTIME_STAGE_BY_SLUG = {item["slug"]: item for item in COHERENT_RUNTIME_STAGE_DEFS}
COHERENT_RUNTIME_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in COHERENT_RUNTIME_STAGE_DEFS}
COHERENT_RUNTIME_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in COHERENT_RUNTIME_STAGE_DEFS}


def _coherent_runtime_flag(slug: str) -> str:
    return slug.replace("_", "-")


def _coherent_runtime_id(slug: str, seed: dict[str, Any]) -> str:
    raw = json.dumps({"slug": slug, "seed": seed}, sort_keys=True, default=str)
    return "coherent-runtime-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]


def _coherent_runtime_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in COHERENT_RUNTIME_STAGE_DEFS if item["api"] == definition["api"]]


def _coherent_runtime_context(goal: str) -> dict[str, Any]:
    inventory = {
        "dashboard_routes_reviewed": True,
        "api_routes_reviewed": True,
        "cli_flags_reviewed": True,
        "smoke_checks_reviewed": True,
        "duplicates_are_advisory": True,
        "operator_friction_reported": True,
    }
    map_state = {
        "core_mind_components": ["memory", "reflection", "goals", "identity_boundaries", "suggestions", "local_model_interfaces", "self_development_loops"],
        "development_pipeline_mapped": True,
        "governance_boundaries_mapped": True,
        "operator_home_read_only": True,
        "cross_links_advisory": True,
    }
    coherence = {
        "memory_referenced_only": True,
        "reflection_goal_links_advisory": True,
        "goal_suggestion_trace_required": True,
        "conflicts_are_advisory": True,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
    }
    daily = {
        "callable_report_only": True,
        "schedules_itself": False,
        "automatic_action_performed": False,
        "source_mutation_performed": False,
        "memory_write_performed": False,
        "identity_write_performed": False,
    }
    runtime = {
        "read_only_snapshot": True,
        "continuity_report_generated": True,
        "next_step_recommendation_only": True,
        "scorecard_unlocks_capability": False,
        "contradictions_flagged": True,
        "autonomy_unlocked": False,
    }
    return {"goal": goal, "inventory": inventory, "map": map_state, "coherence": coherence, "daily": daily, "runtime": runtime}


def _build_coherent_runtime_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = COHERENT_RUNTIME_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Stabilize the v100 milestone, unify the system map, bind memory/reflection/goals, and expose a coherent read-only local mind runtime."
    arc_items = _coherent_runtime_arc_items(definition)
    context = _coherent_runtime_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    api_routes = [f"/api/{item['api']}/{item['route']}" for item in arc_items]
    cli_flags = [_coherent_runtime_flag(item["slug"]) for item in arc_items]
    missing_api = [route for route in api_routes if route not in api_text]
    missing_cli = [flag for flag in cli_flags if flag not in main_text]
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    runtime_tokens = ["data/autonomy/v100_stabilization/", "data/autonomy/system_map/", "data/autonomy/coherence_binder/", "data/autonomy/daily_loop/", "data/autonomy/local_mind_runtime/"]
    runtime_privacy_ok = all(token in release_packaging_text for token in runtime_tokens)
    dashboard_routes = ["/v100-stabilization", "/operator-home", "/system-map", "/coherence-binder", "/daily-loop", "/local-mind-runtime"]
    dashboard_routes_ok = all(route in dashboard_text for route in dashboard_routes)
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "experiment_promoted_without_transaction": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "scorecard_unlocks_capability": False,
    }
    rows: list[dict[str, Any]] = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} {definition['final_label']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text and dashboard_routes_ok else "blocked", "message": f"{definition['dashboard']} dashboard route present and v101-v105 routes are mapped."},
        {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": f"{len(api_routes)} API route(s) present." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": f"{len(cli_flags)} CLI flag(s) present." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_privacy_ok else "blocked", "message": "Stabilization, system-map, coherence, daily-loop, and local-mind-runtime records remain excluded by source-only packaging."},
        {"name": "stabilization-review", "status": "pass" if context["inventory"].get("duplicates_are_advisory") and context["inventory"].get("operator_friction_reported") else "blocked", "message": "Inventory and friction findings are advisory review outputs only."},
        {"name": "system-map", "status": "pass" if context["map"].get("operator_home_read_only") and context["map"].get("governance_boundaries_mapped") else "blocked", "message": "Operator home and system map remain read-only with governance boundaries visible."},
        {"name": "coherence-boundary", "status": "pass" if context["coherence"].get("memory_referenced_only") and not context["coherence"].get("memory_mutation_performed") and not context["coherence"].get("identity_mutation_performed") else "blocked", "message": "Coherence binder references memory and goals without memory or identity mutation."},
        {"name": "daily-loop-containment", "status": "pass" if context["daily"].get("callable_report_only") and not context["daily"].get("schedules_itself") and not context["daily"].get("automatic_action_performed") else "blocked", "message": "Daily loop is callable, advisory, and not scheduled or automatic."},
        {"name": "runtime-read-only", "status": "pass" if context["runtime"].get("read_only_snapshot") and context["runtime"].get("next_step_recommendation_only") and not context["runtime"].get("autonomy_unlocked") and not context["runtime"].get("scorecard_unlocks_capability") else "blocked", "message": "Local mind runtime is read-only and recommends only supervised next steps."},
        {"name": "dashboard-ux", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _coherent_runtime_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": str(COHERENT_RUNTIME_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": _coherent_runtime_flag(item["slug"]), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "v100_to_v105_stage_count": len(COHERENT_RUNTIME_STAGE_DEFS),
        "context_preview": context,
        "forbidden_actions": COHERENT_RUNTIME_FORBIDDEN_ACTIONS,
        "operator_review_required": True,
        "read_only_runtime": True,
        "advisory_only": True,
        "no_automatic_daily_execution": True,
        **safety_false,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} makes Eidolon more coherent and usable while staying read-only, advisory, supervised, and non-autonomous.", save_path, save)


def _make_coherent_runtime_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_coherent_runtime_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_coherent_runtime_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = COHERENT_RUNTIME_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_coherent_runtime_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_coherent_runtime_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_coherent_runtime_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _coherent_runtime_def in COHERENT_RUNTIME_STAGE_DEFS:
    _slug = _coherent_runtime_def["slug"]
    globals()[f"build_{_slug}"] = _make_coherent_runtime_build(_slug)
    globals()[f"{_slug}_text"] = _make_coherent_runtime_text(_slug)
    globals()[f"print_{_slug}"] = _make_coherent_runtime_print(_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(COHERENT_RUNTIME_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(COHERENT_RUNTIME_STAGE_BY_SLUG)
SUPERVISED_RUNTIME_CLI_MAP.update(COHERENT_RUNTIME_CLI_MAP)
