PRACTICAL_COHERENCE_STAGE_BY_SLUG = {item["slug"]: item for item in PRACTICAL_COHERENCE_STAGE_DEFS}
PRACTICAL_COHERENCE_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in PRACTICAL_COHERENCE_STAGE_DEFS}
PRACTICAL_COHERENCE_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in PRACTICAL_COHERENCE_STAGE_DEFS}


def _practical_coherence_id(slug: str, payload: dict[str, Any]) -> str:
    return f"{slug}-" + _sha256_text(payload)[:12]


def _practical_coherence_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in PRACTICAL_COHERENCE_STAGE_DEFS if item["version"] == definition["version"]]


def _practical_coherence_context(goal: str) -> dict[str, Any]:
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    legacy_version_flag_fixed = "python conscious_agent/main.py --version-registry-report" in _read_text(ROOT_DIR / "conscious_agent" / "self_maintenance.py") and "python conscious_agent/main.py --version\"" not in _read_text(ROOT_DIR / "conscious_agent" / "self_maintenance.py")
    return {
        "goal": goal,
        "v100_findings_review": {
            "smoke_exact_version_findings": "fixed_by_current_version_marker_update",
            "v96_v100_routes": "mapped_in_v105_and_retained",
            "v100_milestone_depth": "classified_as_safety_first_scaffold_not_self_operation",
            "legacy_version_checklist_flag_fixed": legacy_version_flag_fixed,
        },
        "memory_quality": {
            "sources_inventory": ["durable_memory", "reflections", "goals", "lessons", "settings", "project_rules", "release_history"],
            "freshness_classes": ["current", "stale", "uncertain", "contradicted", "operator_review"],
            "correction_drafts_only": True,
            "memory_mutation_performed": False,
            "identity_mutation_performed": False,
        },
        "goal_continuity": {
            "states": ["active", "deferred", "blocked", "completed", "recurring"],
            "priority_stability_scored": True,
            "blocked_goal_unblockers_are_operator_decisions": True,
            "approval_inferred": False,
        },
        "reasoning_workbench": {
            "safe_tasks": ["critique", "compare", "explain", "summarize", "rank", "inspect", "propose"],
            "manual_output_capture_only": True,
            "local_model_invoked_by_default": False,
            "source_mutation_performed": False,
        },
        "workflow_console": {
            "commands_are_copy_only": True,
            "approvals_inferred_from_queue": False,
            "hidden_scheduling_performed": False,
            "data_tip_preserved": "data-tip" in dashboard_text and " title=" not in dashboard_text,
        },
        "practical_audit": {
            "walkthrough_path": ["operator_home", "daily_loop", "memory_quality", "goal_continuity", "reasoning_workbench", "workflow_console"],
            "usefulness_reviewed": True,
            "sprawl_reviewed": True,
            "safety_boundary_regression_audited": True,
            "v100_scaffold_is_not_self_operation": True,
        },
        "source_surface": {
            "docs_mentions_v110": "v110.0 - Practical Supervised Mind Usefulness Audit" in docs,
            "dashboard_routes_present": all(route in dashboard_text for route in ["/memory-quality", "/goal-continuity", "/reasoning-workbench", "/workflow-console", "/practical-mind-audit"]),
            "api_dynamic_map_present": "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text,
            "cli_dynamic_map_present": "SUPERVISED_RUNTIME_CLI_MAP" in main_text,
            "privacy_tokens_present": all(token in release_packaging_text for token in ["data/autonomy/memory_quality/", "data/autonomy/goal_continuity/", "data/autonomy/reasoning_workbench/", "data/autonomy/workflow_console/", "data/autonomy/practical_mind_audit/"]),
        },
    }


def _build_practical_coherence_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = PRACTICAL_COHERENCE_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Improve memory quality, goal continuity, contained reasoning, operator workflow compression, and practical usefulness while preserving strict supervision."
    arc_items = _practical_coherence_arc_items(definition)
    context = _practical_coherence_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    api_routes = [f"/api/{item['api']}/{item['route']}" for item in arc_items]
    cli_flags = ["--" + item["slug"].replace("_", "-") for item in arc_items]
    missing_api = [route for route in api_routes if route not in api_text and f"{item['api']}/{item['route']}" not in PRACTICAL_COHERENCE_ROUTE_MAP for item in []]
    missing_cli = [flag for flag in cli_flags if flag[2:] not in main_text and flag[2:] not in PRACTICAL_COHERENCE_CLI_MAP]
    runtime_token = str(PRACTICAL_COHERENCE_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep, "/") + "/"
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    stage_docs_ok = f"- {definition['stage']} {definition['label']}" in docs
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "scorecard_unlocks_capability": False,
        "approvals_inferred_from_queue": False,
        "commands_executed_from_console": False,
    }
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok and stage_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} and {definition['stage']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api else "blocked", "message": f"{len(api_routes)} API route(s) present dynamically or explicitly." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli else "blocked", "message": f"{len(cli_flags)} CLI flag(s) present dynamically or explicitly." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked", "message": f"{runtime_token} remains excluded by source-only packaging."},
        {"name": "v100-findings", "status": "pass" if context["v100_findings_review"]["legacy_version_checklist_flag_fixed"] else "warn", "message": "Old v100 findings are fixed or explicitly classified, including the synthetic milestone scaffold limitation."},
        {"name": "memory-boundary", "status": "pass" if not context["memory_quality"]["memory_mutation_performed"] and not context["memory_quality"]["identity_mutation_performed"] else "blocked", "message": "Memory quality drafts corrections only and performs no memory/identity writes."},
        {"name": "reasoning-containment", "status": "pass" if not context["reasoning_workbench"]["local_model_invoked_by_default"] and context["reasoning_workbench"]["manual_output_capture_only"] else "blocked", "message": "Reasoning workbench captures manual output and keeps local model invocation disabled by default."},
        {"name": "workflow-containment", "status": "pass" if context["workflow_console"]["commands_are_copy_only"] and not context["workflow_console"]["approvals_inferred_from_queue"] and not context["workflow_console"]["hidden_scheduling_performed"] else "blocked", "message": "Workflow console is copy-only, explicit-approval-only, and not scheduled."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name": "advisory-only", "status": "pass" if all(value is False for value in safety_false.values()) else "blocked", "message": "No autonomy, source mutation, publish, memory, identity, hidden scheduling, queue approval, command execution, or approval bypass occurred."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _practical_coherence_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "focus": definition["focus"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": str(PRACTICAL_COHERENCE_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": "--" + item["slug"].replace("_", "-"), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "v105_to_v110_stage_count": len(PRACTICAL_COHERENCE_STAGE_DEFS),
        "context_preview": context,
        "forbidden_actions": PRACTICAL_COHERENCE_FORBIDDEN_ACTIONS,
        "operator_review_required": True,
        "read_only_runtime": True,
        "advisory_only": True,
        "no_automatic_daily_execution": True,
        "copy_only_commands": True,
        "manual_local_model_output_only": True,
        **safety_false,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} advances practical supervised coherence while keeping Eidolon advisory-only and non-autonomous.", save_path, save)


def _make_practical_coherence_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_practical_coherence_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_practical_coherence_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = PRACTICAL_COHERENCE_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_practical_coherence_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_practical_coherence_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_practical_coherence_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _practical_coherence_def in PRACTICAL_COHERENCE_STAGE_DEFS:
    _slug = _practical_coherence_def["slug"]
    globals()[f"build_{_slug}"] = _make_practical_coherence_build(_slug)
    globals()[f"{_slug}_text"] = _make_practical_coherence_text(_slug)
    globals()[f"print_{_slug}"] = _make_practical_coherence_print(_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(PRACTICAL_COHERENCE_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(PRACTICAL_COHERENCE_STAGE_BY_SLUG)
SUPERVISED_RUNTIME_CLI_MAP.update(PRACTICAL_COHERENCE_CLI_MAP)
SUPERVISED_RUNTIME_ROUTE_MAP.update(PRACTICAL_COHERENCE_ROUTE_MAP)

