SUPERVISED_SELF_DEVELOPMENT_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS}
SUPERVISED_SELF_DEVELOPMENT_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS}
SUPERVISED_SELF_DEVELOPMENT_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS}
SUPERVISED_SELF_DEVELOPMENT_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS})


def _supervised_self_development_id(slug: str, seed: dict[str, Any]) -> str:
    return "ssd-" + slug.replace("_", "-") + "-" + _sha256_text(seed)[:12]


def _supervised_self_development_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS if item["version"] == definition["version"]]


def _supervised_self_development_context(goal: str) -> dict[str, Any]:
    return {
        "improvement_intent": {
            "goal": goal,
            "candidate_sources": ["goals", "audits", "workflow_friction", "memory_quality", "reasoning_workbench", "operator_notes"],
            "problem_statement_required": True,
            "evidence_required_before_patch": True,
            "operator_value_scored": True,
            "safety_sensitive_domains": ["autonomy", "memory", "identity", "local_models", "release_packaging", "source_mutation", "scheduling"],
            "actions_performed": [],
        },
        "work_package": {
            "required_sections": ["intent", "scope", "affected_files", "acceptance_criteria", "test_plan", "documentation_obligations", "regression_risks"],
            "documentation_obligation": ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
            "copy_only": True,
            "source_mutation_performed": False,
            "approval_inferred": False,
        },
        "patch_readiness": {
            "review_dimensions": ["expected_diff", "completeness", "claim_vs_change", "safety_regression", "dashboard_regression", "tooltip_regression"],
            "blocked_patterns": SUPERVISED_SELF_DEVELOPMENT_FORBIDDEN_ACTIONS,
            "apply_supported": False,
            "operator_approval_required": True,
        },
        "release_candidate_judgment": {
            "required_checks": ["version_consistency", "route_api_cli_parity", "documentation", "package_privacy", "install_layer_verification"],
            "publish_supported": False,
            "release_recommendation_only": True,
        },
        "supervised_development_readiness": {
            "dashboard_route": "/supervised-development-readiness",
            "v90_route_preserved": "/self-development-readiness",
            "operator_burden_audited": True,
            "decision_trace_required": True,
            "readiness_unlocks_capability": False,
        },
    }


def _build_supervised_self_development_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SUPERVISED_SELF_DEVELOPMENT_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Prepare increasingly complete supervised self-development work packages without enabling autonomy, hidden execution, or inferred approval."
    arc_items = _supervised_self_development_arc_items(definition)
    context = _supervised_self_development_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    api_routes = [f"/api/{item['api']}/{item['route']}" for item in arc_items]
    cli_flags = ["--" + item["slug"].replace("_", "-") for item in arc_items]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    runtime_token = path_reference(SUPERVISED_SELF_DEVELOPMENT_RUNTIME_DIRS[definition["runtime_key"]]) + "/"
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    stage_docs_ok = f"- {definition['stage']} {definition['label']}" in docs or f"{definition['stage']} {definition['label']}" in docs
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "readiness_unlocks_capability": False,
    }
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok and stage_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} and {definition['stage']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "v90-route-preserved", "status": "pass" if "/self-development-readiness" in dashboard_text and "/supervised-development-readiness" in dashboard_text else "blocked", "message": "v90 readiness route is preserved and v115 uses a distinct dashboard route."},
        {"name": "api-routes", "status": "pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message": f"{len(api_routes)} API route(s) present dynamically." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message": f"{len(cli_flags)} CLI flag(s) present dynamically." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if "data/autonomy" in release_packaging_text and runtime_token in release_packaging_text else "blocked", "message": f"{runtime_token} remains excluded by source-only packaging."},
        {"name": "work-package-advisory", "status": "pass" if context["work_package"]["copy_only"] and not context["work_package"]["source_mutation_performed"] else "blocked", "message": "Work packages are copy-only advisory review packets."},
        {"name": "patch-readiness-containment", "status": "pass" if not context["patch_readiness"]["apply_supported"] and context["patch_readiness"]["operator_approval_required"] else "blocked", "message": "Patch readiness reviews cannot apply patches or infer approval."},
        {"name": "release-judgment-containment", "status": "pass" if not context["release_candidate_judgment"]["publish_supported"] and context["release_candidate_judgment"]["release_recommendation_only"] else "blocked", "message": "Release judgment cannot publish; it recommends only."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name": "advisory-only", "status": "pass" if all(value is False for value in safety_false.values()) else "blocked", "message": "No autonomy, source mutation, publish, memory, identity, hidden scheduling, command execution, readiness unlock, or approval bypass occurred."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _supervised_self_development_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "focus": definition["focus"],
        "dashboard_path": definition["dashboard"],
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_dir": path_reference(SUPERVISED_SELF_DEVELOPMENT_RUNTIME_DIRS[definition["runtime_key"]]),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": "--" + item["slug"].replace("_", "-"), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "v110_to_v115_stage_count": len(SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS),
        "context_preview": context,
        "forbidden_actions": SUPERVISED_SELF_DEVELOPMENT_FORBIDDEN_ACTIONS,
        "operator_review_required": True,
        "read_only_runtime": True,
        "advisory_only": True,
        "no_automatic_daily_execution": True,
        "copy_only_commands": True,
        "manual_local_model_output_only": True,
        **safety_false,
    }
    save_path = SELF_MAINTENANCE_DIR / f"{slug}.json"
    return _report_from_rows(definition["stage"], slug, payload, rows, project_id, f"{definition['label']} improves supervised self-development readiness while keeping Eidolon advisory-only and non-autonomous.", save_path, save)


def _make_supervised_self_development_build(slug: str):
    def _builder(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_supervised_self_development_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_supervised_self_development_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        definition = SUPERVISED_SELF_DEVELOPMENT_STAGE_BY_SLUG[slug]
        return _generic_text(f"{definition['stage']} {definition['label']}", report or _build_supervised_self_development_stage(slug, save=False), full)
    _text.__name__ = f"{slug}_text"
    return _text


def _make_supervised_self_development_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_self_development_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        text_func = globals()[f"{slug}_text"]
        _json_print(report) if json_output else print(text_func(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _supervised_self_development_def in SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS:
    _slug = _supervised_self_development_def["slug"]
    globals()[f"build_{_slug}"] = _make_supervised_self_development_build(_slug)
    globals()[f"{_slug}_text"] = _make_supervised_self_development_text(_slug)
    globals()[f"print_{_slug}"] = _make_supervised_self_development_print(_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_SELF_DEVELOPMENT_STAGE_DEFS)
