SUPERVISED_EXECUTION_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_EXECUTION_STAGE_DEFS}
SUPERVISED_EXECUTION_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_EXECUTION_STAGE_DEFS}
SUPERVISED_EXECUTION_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_EXECUTION_STAGE_DEFS}
SUPERVISED_EXECUTION_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_EXECUTION_STAGE_DEFS})


def _supervised_execution_id(slug: str, values: dict[str, Any]) -> str:
    return "sde-" + slug.replace("_", "-") + "-" + _sha256_text(values)[:12]


def _supervised_execution_arc_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in SUPERVISED_EXECUTION_STAGE_DEFS if item["version"] == definition["version"]]


def _supervised_execution_context(goal: str) -> dict[str, Any]:
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    smoke_text = _read_text(ROOT_DIR / "tools" / "smoke_check.py")
    return {
        "goal": goal,
        "session_planner": {
            "inputs": ["improvement_intent", "work_packages", "patch_readiness", "audits", "operator_notes"],
            "scope_is_bounded": True,
            "operator_decisions_required": True,
            "session_work_executed": False,
        },
        "source_cartography": {
            "surfaces": ["dashboard_routes", "api_routes", "cli_flags", "builder_functions", "smoke_checks", "docs", "packaging", "install_checks"],
            "fragile_surfaces": ["dashboard_dispatch_order", "data_tip_hover", "package_privacy", "version_markers", "install_smoke", "stale_commands"],
            "source_mutation_performed": False,
        },
        "patch_simulation": {
            "expected_diff_planned": True,
            "missing_change_detector": True,
            "overreach_detector": True,
            "patch_applied": False,
            "source_mutation_performed": False,
        },
        "verification_matrix": {
            "feature_area_mappings": ["dashboard", "api_cli", "packaging", "safety", "documentation"],
            "durable_memory_mutated": False,
            "hidden_scheduling_performed": False,
        },
        "execution_audit": {
            "walkthrough_path": ["development_session_planner", "source_change_cartographer", "patch_simulation", "verification_matrix"],
            "operator_burden_reviewed": True,
            "verification_coverage_reviewed": True,
            "dashboard_sprawl_reviewed": True,
            "documentation_continuity_reviewed": True,
        },
        "source_surface": {
            "docs_mentions_v120": "v120.0 - Supervised Development Execution Audit" in docs,
            "dashboard_routes_present": all(route in dashboard_text for route in ["/development-session-planner", "/source-change-cartographer", "/patch-simulation", "/verification-matrix", "/development-execution-audit"]),
            "api_dynamic_map_present": "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text,
            "cli_dynamic_map_present": "SUPERVISED_RUNTIME_CLI_MAP" in main_text,
            "smoke_final_checks_present": all(token in smoke_text for token in ["development_session_planner", "source_change_cartographer", "patch_simulation_dry_run_review_layer", "verification_matrix_regression_memory_layer", "supervised_development_execution_audit"]),
            "privacy_tokens_present": all(token in release_packaging_text for token in ["data/autonomy/development_session_planner/", "data/autonomy/source_change_cartographer/", "data/autonomy/patch_simulation/", "data/autonomy/verification_matrix/", "data/autonomy/development_execution_audit/"]),
        },
    }


def _build_supervised_execution_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SUPERVISED_EXECUTION_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Improve supervised development execution by planning sessions, mapping source changes, simulating patches, recommending verification, and auditing execution readiness while preserving strict supervision."
    arc_items = _supervised_execution_arc_items(definition)
    context = _supervised_execution_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    runtime_token = str(SUPERVISED_EXECUTION_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep, "/") + "/"
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    stage_docs_ok = f"- {definition['stage']} {definition['label']}" in docs
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "session_work_executed": False,
        "patch_simulation_applied_patch": False,
    }
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok and stage_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} and {definition['stage']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message": f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message": f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked", "message": f"{runtime_token} remains excluded by source-only packaging."},
        {"name": "session-planner-boundary", "status": "pass" if context["session_planner"]["operator_decisions_required"] and not context["session_planner"]["session_work_executed"] else "blocked", "message": "Session planning requires operator decisions and executes no work."},
        {"name": "source-cartography-boundary", "status": "pass" if not context["source_cartography"]["source_mutation_performed"] else "blocked", "message": "Source cartography maps surfaces without mutating source."},
        {"name": "patch-simulation-boundary", "status": "pass" if not context["patch_simulation"]["patch_applied"] and not context["patch_simulation"]["source_mutation_performed"] else "blocked", "message": "Patch simulation predicts and reviews without applying patches."},
        {"name": "verification-matrix-boundary", "status": "pass" if not context["verification_matrix"]["durable_memory_mutated"] and not context["verification_matrix"]["hidden_scheduling_performed"] else "blocked", "message": "Verification matrix recommends checks without memory writes or scheduling."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name": "advisory-only", "status": "pass" if all(value is False for value in safety_false.values()) else "blocked", "message": "No autonomy, source mutation, patch application, publish, memory, identity, hidden scheduling, command execution, or approval bypass occurred."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _supervised_execution_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "focus": definition["focus"],
        "dashboard_path": definition["dashboard"],
        "api_routes": [f"/api/{key}" for key in route_keys],
        "cli_flags": ["--" + key for key in flag_keys],
        "runtime_dir": str(SUPERVISED_EXECUTION_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": "--" + item["slug"].replace("_", "-"), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "context": context,
        "rows": rows,
        "advisory_only": True,
        "operator_review_required": True,
        "read_only_runtime": True,
        "autonomy_unlocked": False,
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "session_work_executed": False,
        "recommended_next_operator_action": "Review the generated supervised execution packet and explicitly approve any real source work before it occurs.",
    }
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains supervised-only."
    if save:
        SUPERVISED_EXECUTION_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_EXECUTION_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version": definition["version"], "status": payload["status"], "ok": payload["ok"], "checked_at": _now(), "message": payload["message"], "rows": rows, slug: payload}


def _supervised_execution_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_EXECUTION_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage', 'v115.1-v120.0')} {payload.get('name', 'Supervised Development Execution')}", "", report.get("message", "Supervised execution report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status', 'unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Advisory only. No self-approval, patch application, source mutation, memory mutation, identity mutation, local model default invocation, hidden scheduling, command execution, or release publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)


def _make_supervised_execution_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_execution_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_execution_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _supervised_execution_def in SUPERVISED_EXECUTION_STAGE_DEFS:
    _supervised_execution_slug = _supervised_execution_def["slug"]
    globals()[f"build_{_supervised_execution_slug}"] = (lambda slug: (lambda *args, **kwargs: _build_supervised_execution_stage(slug, *args, **kwargs)))(_supervised_execution_slug)
    globals()[f"{_supervised_execution_slug}_text"] = _supervised_execution_text
    globals()[f"print_{_supervised_execution_slug}"] = _make_supervised_execution_print(_supervised_execution_slug)

