def _build_supervised_learning_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SUPERVISED_LEARNING_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "Improve supervised learning from completed development sessions by comparing outcomes, extracting proposed lessons, refining recommendations, integrating operator feedback, and auditing learning without memory mutation or autonomy."
    arc_items = _supervised_learning_arc_items(definition)
    context = _supervised_learning_context(goal)
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    runtime_token = str(SUPERVISED_LEARNING_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep, "/") + "/"
    final_docs_ok = f"{definition['version']} - {definition['final_label']}" in docs
    stage_docs_ok = f"- {definition['stage']} {definition['label']}" in docs
    safety_false = {
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "autonomy_unlocked": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "lessons_auto_persisted": False,
        "feedback_auto_persisted": False,
        "recommendations_auto_applied": False,
    }
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if final_docs_ok and stage_docs_ok else "blocked", "message": f"README and release history mention {definition['version']} and {definition['stage']}."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message": f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message": f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked", "message": f"{runtime_token} remains excluded by source-only packaging."},
        {"name": "outcome-review-boundary", "status": "pass" if not context["outcome_review"]["actual_source_mutation_performed"] else "blocked", "message": "Outcome review compares plans and outcomes without mutating source."},
        {"name": "lesson-memory-boundary", "status": "pass" if context["lesson_extraction"]["lesson_candidates_only"] and not context["lesson_extraction"]["durable_memory_mutated"] else "blocked", "message": "Lessons are proposed candidates only and are not written to durable memory."},
        {"name": "recommendation-boundary", "status": "pass" if context["recommendation_refinement"]["recommendations_remain_advisory"] and not context["recommendation_refinement"]["patches_applied"] else "blocked", "message": "Recommendation refinement remains advisory and applies no patches."},
        {"name": "feedback-boundary", "status": "pass" if context["feedback_integration"]["standing_rule_review_packet"] and not context["feedback_integration"]["memory_write_performed"] else "blocked", "message": "Feedback integration builds review packets without memory writes."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name": "advisory-only", "status": "pass" if all(value is False for value in safety_false.values()) else "blocked", "message": "No autonomy, source mutation, patch application, publish, memory, identity, hidden scheduling, command execution, lesson persistence, recommendation apply, or approval bypass occurred."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _supervised_learning_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "focus": definition["focus"],
        "dashboard_path": definition["dashboard"],
        "api_routes": [f"/api/{key}" for key in route_keys],
        "cli_flags": ["--" + key for key in flag_keys],
        "runtime_dir": str(SUPERVISED_LEARNING_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": "--" + item["slug"].replace("_", "-"), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "context": context,
        "rows": rows,
        "advisory_only": True,
        "operator_review_required": True,
        "read_only_runtime": True,
        "autonomy_unlocked": False,
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "lessons_auto_persisted": False,
        "feedback_auto_persisted": False,
        "recommendations_auto_applied": False,
        "recommended_next_operator_action": "Review the supervised learning packet and explicitly approve any durable memory or project rule changes before they are recorded.",
    }
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains supervised-only."
    if save:
        SUPERVISED_LEARNING_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_LEARNING_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version": definition["version"], "status": payload["status"], "ok": payload["ok"], "checked_at": _now(), "message": payload["message"], "rows": rows, slug: payload}


def _supervised_learning_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_LEARNING_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage', 'v120.1-v125.0')} {payload.get('name', 'Supervised Development Learning')}", "", report.get("message", "Supervised development learning report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status', 'unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Advisory only. No self-approval, patch application, source mutation, memory mutation, identity mutation, local model default invocation, hidden scheduling, command execution, lesson persistence, recommendation application, or release publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)


def _make_supervised_learning_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_learning_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_learning_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _supervised_learning_def in SUPERVISED_LEARNING_STAGE_DEFS:
    _supervised_learning_slug = _supervised_learning_def["slug"]
    globals()[f"build_{_supervised_learning_slug}"] = (lambda slug: (lambda *args, **kwargs: _build_supervised_learning_stage(slug, *args, **kwargs)))(_supervised_learning_slug)
    globals()[f"{_supervised_learning_slug}_text"] = _supervised_learning_text
    globals()[f"print_{_supervised_learning_slug}"] = _make_supervised_learning_print(_supervised_learning_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_LEARNING_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(SUPERVISED_LEARNING_STAGE_BY_SLUG)
SUPERVISED_RUNTIME_CLI_MAP.update(SUPERVISED_LEARNING_CLI_MAP)
SUPERVISED_RUNTIME_ROUTE_MAP.update(SUPERVISED_LEARNING_ROUTE_MAP)

