SUPERVISED_STRATEGIC_GROWTH_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS}
SUPERVISED_STRATEGIC_GROWTH_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS}
SUPERVISED_STRATEGIC_GROWTH_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS}
SUPERVISED_STRATEGIC_GROWTH_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS})


def _supervised_strategic_growth_id(slug: str, parts: dict[str, Any]) -> str:
    raw = "|".join(str(parts.get(key, "")) for key in sorted(parts))
    return f"{slug}-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]


def _supervised_strategic_growth_context() -> dict[str, Any]:
    return {
        "strategic_intake": {"signals_collected": ["lessons", "feedback", "goals", "audits", "failed_checks", "operator_direction"], "signals_are_read_only": True, "durable_memory_mutated": False},
        "roadmap_synthesis": {"roadmap_options": ["short_term", "medium_term", "long_term"], "recommendations_are_advisory": True, "work_scheduled": False, "approval_inferred": False},
        "risk_ledger": {"technical_debt_tracked": True, "safety_debt_tracked": True, "usability_debt_tracked": True, "mitigation_is_advisory": True},
        "capability_maturity": {"maturity_levels": ["scaffolded", "integrated", "tested", "useful", "reliable", "operator_trusted"], "scaffold_detection_enabled": True, "self_upgrade_performed": False},
        "strategic_audit": {"end_to_end_walkthrough": True, "roadmap_quality_checked": True, "operator_burden_checked": True, "next_arc_is_recommended_only": True},
        "safety": {action: False for action in SUPERVISED_STRATEGIC_GROWTH_FORBIDDEN_ACTIONS},
    }


def _strategic_growth_stage_items(definition: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS if item["version"] == definition["version"]]


def _build_supervised_strategic_growth_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
    definition = SUPERVISED_STRATEGIC_GROWTH_STAGE_BY_SLUG[slug]
    goal = improvement_goal or "supervised strategic growth planning"
    docs = _release_notes_text()
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    context = _supervised_strategic_growth_context()
    arc_items = _strategic_growth_stage_items(definition)
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    runtime_token = f"data/autonomy/{definition['runtime_key']}/"
    safety_false = {
        "autonomy_unlocked": False,
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "roadmap_auto_selected": False,
        "capability_self_upgrade_performed": False,
    }
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v130.0 - Supervised Strategic Growth Audit" in docs and "v125.1-v126.0 - Strategic Growth Intake Layer" in docs else "blocked", "message": "README and release history document v126-v130 strategic growth."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message": f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message": f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked", "message": f"{runtime_token} remains excluded by source-only packaging."},
        {"name": "strategic-intake-boundary", "status": "pass" if context["strategic_intake"]["signals_are_read_only"] and not context["strategic_intake"]["durable_memory_mutated"] else "blocked", "message": "Strategic signals are read-only inputs and do not mutate durable memory."},
        {"name": "roadmap-boundary", "status": "pass" if context["roadmap_synthesis"]["recommendations_are_advisory"] and not context["roadmap_synthesis"]["work_scheduled"] and not context["roadmap_synthesis"]["approval_inferred"] else "blocked", "message": "Roadmaps remain advisory and schedule no hidden work."},
        {"name": "risk-ledger-boundary", "status": "pass" if context["risk_ledger"]["mitigation_is_advisory"] else "blocked", "message": "Risk and debt mitigations are recommendations only."},
        {"name": "capability-maturity-boundary", "status": "pass" if context["capability_maturity"]["scaffold_detection_enabled"] and not context["capability_maturity"]["self_upgrade_performed"] else "blocked", "message": "Capability maturity scoring cannot self-upgrade capabilities."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name": "advisory-only", "status": "pass" if all(value is False for value in safety_false.values()) else "blocked", "message": "No autonomy, source mutation, patch application, publish, memory, identity, hidden scheduling, command execution, roadmap auto-selection, capability self-upgrade, or approval bypass occurred."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _supervised_strategic_growth_id(slug, {"project": project_id, "goal": goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "focus": definition["focus"],
        "dashboard_path": definition["dashboard"],
        "api_routes": [f"/api/{key}" for key in route_keys],
        "cli_flags": ["--" + key for key in flag_keys],
        "runtime_dir": str(SUPERVISED_STRATEGIC_GROWTH_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)),
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": "--" + item["slug"].replace("_", "-"), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "context": context,
        "rows": rows,
        "advisory_only": True,
        "operator_review_required": True,
        "read_only_runtime": True,
        "autonomy_unlocked": False,
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "roadmap_auto_selected": False,
        "capability_self_upgrade_performed": False,
        "recommended_next_operator_action": "Review the supervised strategic growth packet and explicitly choose any roadmap, debt mitigation, or capability maturity upgrade before work is planned.",
    }
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains supervised-only."
    if save:
        SUPERVISED_STRATEGIC_GROWTH_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_STRATEGIC_GROWTH_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version": definition["version"], "status": payload["status"], "ok": payload["ok"], "checked_at": _now(), "message": payload["message"], "rows": rows, slug: payload}


def _supervised_strategic_growth_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_STRATEGIC_GROWTH_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage', 'v125.1-v130.0')} {payload.get('name', 'Supervised Strategic Growth')}", "", report.get("message", "Supervised strategic growth report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status', 'unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Advisory only. No self-approval, patch application, source mutation, memory mutation, identity mutation, local model default invocation, hidden scheduling, command execution, roadmap auto-selection, capability self-upgrade, or release publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)


def _make_supervised_strategic_growth_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_strategic_growth_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_strategic_growth_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _supervised_strategic_growth_def in SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS:
    _supervised_strategic_growth_slug = _supervised_strategic_growth_def["slug"]
    globals()[f"build_{_supervised_strategic_growth_slug}"] = (lambda slug: (lambda *args, **kwargs: _build_supervised_strategic_growth_stage(slug, *args, **kwargs)))(_supervised_strategic_growth_slug)
    globals()[f"{_supervised_strategic_growth_slug}_text"] = _supervised_strategic_growth_text
    globals()[f"print_{_supervised_strategic_growth_slug}"] = _make_supervised_strategic_growth_print(_supervised_strategic_growth_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_STRATEGIC_GROWTH_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(SUPERVISED_STRATEGIC_GROWTH_STAGE_BY_SLUG)
