def _operator_planning_id(slug: str, payload: dict[str, Any]) -> str:
    return f"opplan-{slug}-" + _sha256_text(json.dumps(payload, sort_keys=True, default=str))[:12]


def _build_supervised_operator_planning_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
    definition = SUPERVISED_OPERATOR_PLANNING_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": SELF_MAINTENANCE_VERSION, "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown supervised operator planning stage: {slug}", "rows": []}
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    arc_items = [item for item in SUPERVISED_OPERATOR_PLANNING_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    context = {
        "planning_signals": {"consolidated": True, "read_only": True, "durable_memory_mutated": False},
        "work_package_recommendations": {"ranked": True, "work_created": False, "approval_inferred": False, "patch_applied": False},
        "decision_brief": {"top_three_presented": True, "roadmap_auto_selected": False, "hidden_scheduling_performed": False},
        "planning_console": {"dashboard_sprawl_reduced": True, "existing_routes_preserved": True, "data_tip_preserved": not _dashboard_nav_title_regression_present()},
        "planning_readiness_audit": {"operator_review_required": True, "autonomy_unlocked": False},
    }
    safety_false = {
        "autonomy_unlocked": False,
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "roadmap_auto_selected": False,
        "work_package_auto_launched": False,
        "capability_self_upgrade_performed": False,
    }
    runtime_token = str(SUPERVISED_OPERATOR_PLANNING_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep, "/")
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs", "status": "pass" if "v135.0 - Supervised Operator Planning Console" in docs and "v130.1-v131.0 - Planning Signal Consolidation Layer" in docs else "blocked", "message": "README and release history document v131-v135 operator planning."},
        {"name": "substage-count", "status": "pass" if len(arc_items) == 10 else "blocked", "message": f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name": "dashboard-route", "status": "pass" if definition["dashboard"] in dashboard_text else "blocked", "message": f"{definition['dashboard']} dashboard route present."},
        {"name": "api-routes", "status": "pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message": f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: " + ", ".join(missing_api)},
        {"name": "cli-flags", "status": "pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message": f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: " + ", ".join(missing_cli)},
        {"name": "runtime-privacy", "status": "pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked", "message": f"{runtime_token} remains excluded by source-only packaging."},
        {"name": "planning-signal-boundary", "status": "pass" if context["planning_signals"]["read_only"] and not context["planning_signals"]["durable_memory_mutated"] else "blocked", "message": "Planning signals are consolidated without durable memory mutation."},
        {"name": "work-package-boundary", "status": "pass" if not context["work_package_recommendations"]["work_created"] and not context["work_package_recommendations"]["patch_applied"] else "blocked", "message": "Work packages remain recommendations and create no work automatically."},
        {"name": "decision-brief-boundary", "status": "pass" if not context["decision_brief"]["roadmap_auto_selected"] and not context["decision_brief"]["hidden_scheduling_performed"] else "blocked", "message": "Decision briefs cannot auto-select roadmaps or schedule hidden work."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name": "advisory-only", "status": "pass" if all(value is False for value in safety_false.values()) else "blocked", "message": "No autonomy, source mutation, patch application, publish, memory, identity, hidden scheduling, command execution, roadmap auto-selection, work package auto-launch, capability self-upgrade, or approval bypass occurred."},
    ]
    payload = {
        "schema_version": f"eidolon.{definition['version'].lower().replace('.', '_')}.{slug}.v1",
        "artifact_id": _operator_planning_id(slug, {"project": project_id, "goal": improvement_goal, "candidate_file": candidate_file}),
        "stage": definition["stage"],
        "name": definition["label"],
        "arc_version": definition["version"],
        "theme": definition["theme"],
        "focus": definition["focus"],
        "dashboard_path": definition["dashboard"],
        "api_routes": [f"/api/{key}" for key in route_keys],
        "cli_flags": ["--" + key for key in flag_keys],
        "runtime_dir": runtime_token,
        "substage_plan": [{"stage": item["stage"], "slug": item["slug"], "label": item["label"], "cli_flag": "--" + item["slug"].replace("_", "-"), "api_route": f"/api/{item['api']}/{item['route']}"} for item in arc_items],
        "context": context,
        "rows": rows,
        "advisory_only": True,
        "operator_review_required": True,
        "read_only_runtime": True,
        "autonomy_unlocked": False,
        "source_mutation_performed": False,
        "patches_applied": False,
        "approval_bypass_performed": False,
        "publish_performed": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "local_model_invoked_by_default": False,
        "automatic_action_performed": False,
        "hidden_scheduling_performed": False,
        "commands_executed_from_console": False,
        "approvals_inferred_from_readiness": False,
        "roadmap_auto_selected": False,
        "work_package_auto_launched": False,
        "capability_self_upgrade_performed": False,
        "recommended_next_operator_action": "Review the planning packet and explicitly choose any work package before a session or patch plan is prepared.",
    }
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains supervised-only."
    if save:
        SUPERVISED_OPERATOR_PLANNING_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_OPERATOR_PLANNING_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version": definition["version"], "status": payload["status"], "ok": payload["ok"], "checked_at": _now(), "message": payload["message"], "rows": rows, slug: payload}


def _supervised_operator_planning_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_OPERATOR_PLANNING_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage', 'v130.1-v135.0')} {payload.get('name', 'Supervised Operator Planning')}", "", report.get("message", "Supervised operator planning report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status', 'unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Advisory only. No self-approval, patch application, source mutation, memory mutation, identity mutation, local model default invocation, hidden scheduling, command execution, roadmap auto-selection, work package auto-launch, capability self-upgrade, or release publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)


def _make_supervised_operator_planning_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_operator_planning_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_operator_planning_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _operator_planning_def in SUPERVISED_OPERATOR_PLANNING_STAGE_DEFS:
    _operator_planning_slug = _operator_planning_def["slug"]
    globals()[f"build_{_operator_planning_slug}"] = (lambda slug: (lambda *args, **kwargs: _build_supervised_operator_planning_stage(slug, *args, **kwargs)))(_operator_planning_slug)
    globals()[f"{_operator_planning_slug}_text"] = _supervised_operator_planning_text
    globals()[f"print_{_operator_planning_slug}"] = _make_supervised_operator_planning_print(_operator_planning_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_OPERATOR_PLANNING_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(SUPERVISED_OPERATOR_PLANNING_STAGE_BY_SLUG)
