SUPERVISED_SESSION_LAUNCH_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_SESSION_LAUNCH_STAGE_DEFS}
SUPERVISED_SESSION_LAUNCH_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_SESSION_LAUNCH_STAGE_DEFS}
SUPERVISED_SESSION_LAUNCH_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_SESSION_LAUNCH_STAGE_DEFS}

def _session_launch_id(slug: str, parts: dict[str, Any]) -> str:
    return "session_launch_" + slug + "_" + _sha256_text(json.dumps(parts, sort_keys=True))[:12]

def _build_supervised_session_launch_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = False, **kwargs: Any) -> dict[str, Any]:
    if slug not in SUPERVISED_SESSION_LAUNCH_STAGE_BY_SLUG:
        return {"version":"140.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown supervised session launch stage: {slug}","rows":[]}
    definition = SUPERVISED_SESSION_LAUNCH_STAGE_BY_SLUG[slug]
    arc_items = [item for item in SUPERVISED_SESSION_LAUNCH_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_","-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    safety_false = {"autonomy_unlocked":False,"source_mutation_performed":False,"patches_applied":False,"approval_bypass_performed":False,"publish_performed":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"commands_executed_from_console":False,"approvals_inferred_from_readiness":False,"roadmap_auto_selected":False,"work_package_auto_launched":False,"verification_commands_executed":False}
    runtime_token = str(SUPERVISED_SESSION_LAUNCH_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v140.0 - Supervised Work Package Selection and Session Launch" in docs and "v135.1-v136.0 - Work Package Selection Layer" in docs else "blocked","message":"README and release history document v136-v140 supervised session launch."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"operator-selection-required","status":"pass","message":"Work package selection requires explicit operator action and does not auto-select."},
        {"name":"launch-readiness-not-permission","status":"pass","message":"Session briefs, approval checklists, and verification plans are readiness artifacts, not permission."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"advisory-only","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, source mutation, patch application, publish, memory, identity, hidden scheduling, command execution, auto-launch, verification command execution, or approval bypass occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_session_launch_id(slug,{"project":project_id,"goal":improvement_goal,"candidate_file":candidate_file}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"operator_selected": False, "launch_packet_prepared": True, "approval_required": True, "verification_plan_advisory": True, "rollback_plan_advisory": True},"rows":rows,"advisory_only":True,"operator_review_required":True,"read_only_runtime":True,**safety_false,"recommended_next_operator_action":"Review the launch packet and explicitly approve any future patch work before source changes are prepared or applied."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains supervised-only."
    if save:
        SUPERVISED_SESSION_LAUNCH_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_SESSION_LAUNCH_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _supervised_session_launch_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_SESSION_LAUNCH_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v135.1-v140.0')} {payload.get('name','Supervised Session Launch')}", "", report.get("message","Supervised session launch report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Advisory only. Operator selection and approval are required. No auto-selection, self-approval, source mutation, patch application, memory mutation, identity mutation, local model default invocation, hidden scheduling, verification command execution, approval bypass, or publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_supervised_session_launch_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, model_name: str | None = None, cycle_id: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_session_launch_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_session_launch_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _session_launch_def in SUPERVISED_SESSION_LAUNCH_STAGE_DEFS:
    _session_launch_slug = _session_launch_def["slug"]
    globals()[f"build_{_session_launch_slug}"] = (lambda slug: (lambda *args, **kwargs: _build_supervised_session_launch_stage(slug, *args, **kwargs)))(_session_launch_slug)
    globals()[f"{_session_launch_slug}_text"] = _supervised_session_launch_text
    globals()[f"print_{_session_launch_slug}"] = _make_supervised_session_launch_print(_session_launch_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_SESSION_LAUNCH_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(SUPERVISED_SESSION_LAUNCH_STAGE_BY_SLUG)
SUPERVISED_RUNTIME_CLI_MAP.update(SUPERVISED_SESSION_LAUNCH_CLI_MAP)
SUPERVISED_RUNTIME_ROUTE_MAP.update(SUPERVISED_SESSION_LAUNCH_ROUTE_MAP)

