SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_DEFS}
SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_DEFS}
SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_DEFS}

def _implementation_handoff_id(slug: str, parts: dict[str, Any]) -> str:
    return "ih-" + slug.replace("_", "-") + "-" + hashlib.sha256(json.dumps(parts, sort_keys=True).encode("utf-8")).hexdigest()[:12]

def _build_supervised_patch_implementation_handoff_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = False, **kwargs: Any) -> dict[str, Any]:
    if slug not in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_BY_SLUG:
        return {"version":"v155.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown supervised patch implementation handoff stage: {slug}","rows":[]}
    definition = SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_BY_SLUG[slug]
    arc_items = [item for item in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    safety_false = {"autonomy_unlocked":False,"source_mutation_performed":False,"patches_applied":False,"approval_bypass_performed":False,"publish_performed":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"commands_executed_from_console":False,"approvals_inferred_from_readiness":False,"drafts_written_to_live_source":False,"generated_draft_approved":False,"verification_commands_executed":False,"scope_expanded_without_operator":False,"implementation_started":False,"live_files_modified":False,"implementation_plan_auto_selected":False,"work_package_auto_launched":False}
    runtime_token = str(SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v155.0 - Supervised Patch Implementation Handoff" in docs and "v150.1-v151.0 - Implementation Handoff Intake Layer" in docs else "blocked","message":"README and release history document v151-v155 supervised patch implementation handoff."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"operator-approval-required","status":"pass","message":"Implementation handoff remains reviewable and requires explicit operator approval before source changes."},
        {"name":"implementation-not-started","status":"pass","message":"Handoff, application plan, verification worksheet, and rollback packet are artifacts only; no live source is mutated."},
        {"name":"verification-not-executed","status":"pass","message":"Verification commands are listed for the operator and are not executed automatically."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"advisory-only","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, source mutation, implementation, patch application, draft approval, verification command execution, publishing, memory, identity, hidden scheduling, scope expansion, command execution, approval inference, approval bypass, auto roadmap selection, or auto work launch occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_implementation_handoff_id(slug,{"project":project_id,"goal":improvement_goal,"candidate_file":candidate_file}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"draft_qa_imported": True, "approved_file_scope_bound": True, "manual_application_plan_prepared": True, "verification_worksheet_prepared": True, "rollback_packet_prepared": True, "implementation_allowed": False},"rows":rows,"advisory_only":True,"operator_review_required":True,"operator_approval_required_before_implementation":True,"read_only_runtime":True,**safety_false,"recommended_next_operator_action":"Review the handoff packet and approve any future implementation path explicitly before live source is changed."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains implementation-handoff-only."
    if save:
        SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _supervised_patch_implementation_handoff_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v150.1-v155.0')} {payload.get('name','Supervised Patch Implementation Handoff')}", "", report.get("message","Supervised patch implementation handoff report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Implementation-handoff-only and advisory. Operator approval is required before source changes. No live file writes, patch application, self-approval, memory mutation, identity mutation, local model default invocation, hidden scheduling, verification command execution, approval inference, approval bypass, roadmap auto-selection, work-package auto-launch, or publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_supervised_patch_implementation_handoff_build(slug: str):
    return lambda *args, **kwargs: _build_supervised_patch_implementation_handoff_stage(slug, *args, **kwargs)

def _make_supervised_patch_implementation_handoff_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_patch_implementation_handoff_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_patch_implementation_handoff_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _implementation_handoff_def in SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_DEFS:
    _implementation_handoff_slug = _implementation_handoff_def["slug"]
    globals()[f"build_{_implementation_handoff_slug}"] = _make_supervised_patch_implementation_handoff_build(_implementation_handoff_slug)
    globals()[f"{_implementation_handoff_slug}_text"] = _supervised_patch_implementation_handoff_text
    globals()[f"print_{_implementation_handoff_slug}"] = _make_supervised_patch_implementation_handoff_print(_implementation_handoff_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(SUPERVISED_PATCH_IMPLEMENTATION_HANDOFF_STAGE_BY_SLUG)
