SUPERVISED_PATCH_APPLICATION_READINESS_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_PATCH_APPLICATION_READINESS_STAGE_DEFS}

def _patch_application_readiness_id(slug: str, parts: dict[str, Any]) -> str:
    return "par-" + slug.replace("_", "-") + "-" + hashlib.sha256(json.dumps(parts, sort_keys=True).encode("utf-8")).hexdigest()[:12]

def _build_supervised_patch_application_readiness_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = False, **kwargs: Any) -> dict[str, Any]:
    if slug not in SUPERVISED_PATCH_APPLICATION_READINESS_STAGE_BY_SLUG:
        return {"version":"v165.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown supervised patch application readiness stage: {slug}","rows":[]}
    definition = SUPERVISED_PATCH_APPLICATION_READINESS_STAGE_BY_SLUG[slug]
    arc_items = [item for item in SUPERVISED_PATCH_APPLICATION_READINESS_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    safety_false = {"autonomy_unlocked":False,"source_mutation_performed":False,"patches_applied":False,"approval_bypass_performed":False,"publish_performed":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"commands_executed_from_console":False,"approvals_inferred_from_readiness":False,"drafts_written_to_live_source":False,"generated_draft_approved":False,"verification_commands_executed":False,"scope_expanded_without_operator":False,"implementation_started":False,"live_files_modified":False,"readiness_go_auto_selected":False,"work_package_auto_launched":False,"patch_application_performed":False}
    runtime_token = str(SUPERVISED_PATCH_APPLICATION_READINESS_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v165.0 - Supervised Patch Application Readiness" in docs and "v155.1-v156.0 - Patch Readiness Intake Layer" in docs else "blocked","message":"README and release history document v156-v160 supervised patch application readiness."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"operator-approval-required","status":"pass","message":"Readiness can recommend go/no-go but cannot infer approval or apply changes."},
        {"name":"application-not-performed","status":"pass","message":"Patch readiness packets are advisory only; no source files are modified."},
        {"name":"verification-not-executed","status":"pass","message":"Verification commands remain worksheet instructions and are not executed automatically."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"advisory-only","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, source mutation, patch application, draft approval, verification command execution, publishing, memory, identity, hidden scheduling, scope expansion, command execution, approval inference, approval bypass, readiness go auto-selection, or work launch occurred."},
    ]
    readiness_status = "ready" if definition["version"] == "v165.0" else "review"
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_patch_application_readiness_id(slug,{"project":project_id,"goal":improvement_goal,"candidate_file":candidate_file}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"draft_qa_bound": True, "implementation_handoff_bound": True, "manual_application_plan_bound": True, "verification_worksheet_bound": True, "rollback_packet_bound": True, "operator_approval_present": False, "readiness_status": readiness_status},"rows":rows,"advisory_only":True,"operator_review_required":True,"operator_approval_required_before_application":True,"readiness_recommendation":"operator-go-no-go-review-required","read_only_runtime":True,**safety_false,"recommended_next_operator_action":"Review blockers and go/no-go packet, then explicitly approve any future sandbox or live application step before changes are made."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains readiness-only."
    if save:
        SUPERVISED_PATCH_APPLICATION_READINESS_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_PATCH_APPLICATION_READINESS_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _supervised_patch_application_readiness_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_PATCH_APPLICATION_READINESS_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v155.1-v165.0')} {payload.get('name','Supervised Patch Application Readiness')}", "", report.get("message","Supervised patch application readiness report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Readiness-only and advisory. It may recommend ready, blocked, risky, incomplete, unsafe, go, no-go, or conditional-go states, but operator approval is required before any application. No live file writes, patch application, self-approval, memory mutation, identity mutation, local model default invocation, hidden scheduling, verification command execution, approval inference, approval bypass, readiness auto-go, work-package auto-launch, or publishing."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_supervised_patch_application_readiness_build(slug: str):
    return lambda *args, **kwargs: _build_supervised_patch_application_readiness_stage(slug, *args, **kwargs)

def _make_supervised_patch_application_readiness_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_patch_application_readiness_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_patch_application_readiness_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _patch_application_readiness_def in SUPERVISED_PATCH_APPLICATION_READINESS_STAGE_DEFS:
    _patch_application_readiness_slug = _patch_application_readiness_def["slug"]
    globals()[f"build_{_patch_application_readiness_slug}"] = _make_supervised_patch_application_readiness_build(_patch_application_readiness_slug)
    globals()[f"{_patch_application_readiness_slug}_text"] = _supervised_patch_application_readiness_text
    globals()[f"print_{_patch_application_readiness_slug}"] = _make_supervised_patch_application_readiness_print(_patch_application_readiness_slug)

