SUPERVISED_PATCH_APPLICATION_SANDBOX_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_PATCH_APPLICATION_SANDBOX_STAGE_DEFS}

def _sandbox_patch_application_id(slug: str, parts: dict[str, Any]) -> str:
    return "spa-" + slug.replace("_", "-") + "-" + hashlib.sha256(json.dumps(parts, sort_keys=True).encode("utf-8")).hexdigest()[:12]

def _build_supervised_patch_application_sandbox_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, sandbox_id: str | None = None, save: bool = False, **kwargs: Any) -> dict[str, Any]:
    if slug not in SUPERVISED_PATCH_APPLICATION_SANDBOX_STAGE_BY_SLUG:
        return {"version":"v165.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown supervised patch application sandbox stage: {slug}","rows":[]}
    definition = SUPERVISED_PATCH_APPLICATION_SANDBOX_STAGE_BY_SLUG[slug]
    arc_items = [item for item in SUPERVISED_PATCH_APPLICATION_SANDBOX_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    safety_false = {"autonomy_unlocked":False,"source_mutation_performed":False,"live_source_mutation_performed":False,"patches_applied_to_live_source":False,"sandbox_promoted_to_source":False,"approval_bypass_performed":False,"publish_performed":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"commands_executed_from_console":False,"approvals_inferred_from_readiness":False,"readiness_go_auto_selected":False,"work_package_auto_launched":False,"patch_application_performed_without_approval":False,"sandbox_application_performed_without_approval":False,"verification_commands_executed_without_approval":False,"sandbox_output_written_to_live_source":False,"promotion_auto_selected":False}
    runtime_token = str(SUPERVISED_PATCH_APPLICATION_SANDBOX_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v165.0 - Operator-Approved Patch Application Sandbox" in docs and "v160.1-v161.0 - Patch Sandbox Intake Layer" in docs else "blocked","message":"README and release history document v161-v165 supervised sandbox patch application."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"explicit-approval-required","status":"pass","message":"Sandbox application planning requires explicit operator approval before actionable sandbox steps."},
        {"name":"sandbox-only","status":"pass","message":"The arc prepares sandbox/staging copies and evidence packets only; live source targets are forbidden."},
        {"name":"no-promotion","status":"pass","message":"Sandbox result review may classify promotion eligibility but cannot promote sandbox output to live source."},
        {"name":"verification-gated","status":"pass","message":"Sandbox verification commands are prepared as packets and are not run without explicit approval."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"advisory-supervised-boundary","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, live source mutation, self-approval, publishing, memory/identity mutation, hidden scheduling, approval inference, auto-promotion, unapproved verification, or source write occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_sandbox_patch_application_id(slug,{"project":project_id,"goal":improvement_goal,"candidate_file":candidate_file,"sandbox_id":sandbox_id}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"readiness_decision_imported": True, "explicit_operator_approval_required": True, "sandbox_target_resolved": True, "sandbox_only": True, "live_source_targets_allowed": False, "promotion_allowed": False, "verification_requires_approval": True},"rows":rows,"advisory_only":True,"operator_review_required":True,"operator_approval_required_before_sandbox_application":True,"operator_approval_required_before_verification_execution":True,"operator_approval_required_before_any_future_promotion":True,"sandbox_only":True,"read_only_runtime":True,**safety_false,"recommended_next_operator_action":"Review the sandbox packet and provide explicit approval only when ready to prepare or run sandbox-only application steps."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains sandbox-only, gated, and non-promoting."
    if save:
        SUPERVISED_PATCH_APPLICATION_SANDBOX_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_PATCH_APPLICATION_SANDBOX_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _supervised_patch_application_sandbox_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_PATCH_APPLICATION_SANDBOX_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v160.1-v165.0')} {payload.get('name','Operator-Approved Patch Application Sandbox')}", "", report.get("message","Supervised patch application sandbox report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Sandbox-only and supervised. It may prepare sandbox intake, sandbox application plans, verification packets, result reviews, and audit packets, but explicit operator approval is required before any sandbox action. No live source mutation, sandbox-to-source promotion, self-approval, publishing, memory mutation, identity mutation, hidden scheduling, local model default invocation, approval inference, unapproved command execution, or source write."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_supervised_patch_application_sandbox_build(slug: str):
    return lambda *args, **kwargs: _build_supervised_patch_application_sandbox_stage(slug, *args, **kwargs)

def _make_supervised_patch_application_sandbox_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, sandbox_id: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_patch_application_sandbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, sandbox_id=sandbox_id, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_patch_application_sandbox_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _sandbox_def in SUPERVISED_PATCH_APPLICATION_SANDBOX_STAGE_DEFS:
    _sandbox_slug = _sandbox_def["slug"]
    globals()[f"build_{_sandbox_slug}"] = _make_supervised_patch_application_sandbox_build(_sandbox_slug)
    globals()[f"{_sandbox_slug}_text"] = _supervised_patch_application_sandbox_text
    globals()[f"print_{_sandbox_slug}"] = _make_supervised_patch_application_sandbox_print(_sandbox_slug)

