SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_DEFS}

def _sandbox_to_source_promotion_id(slug: str, context: dict[str, Any]) -> str:
    raw = "|".join([slug, context.get("project") or "eidolon", context.get("goal") or "sandbox-to-source-promotion", context.get("sandbox_id") or "sandbox", context.get("promotion_id") or "promotion"])
    return "promotion-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]

def _build_supervised_sandbox_to_source_promotion_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, sandbox_id: str | None = None, promotion_id: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
    if slug not in SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_BY_SLUG:
        return {"version":"v170.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown supervised sandbox-to-source promotion stage: {slug}","rows":[]}
    definition = SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_BY_SLUG[slug]
    arc_items = [item for item in SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_", "-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    safety_false = {"autonomy_unlocked":False,"live_source_mutation_performed_without_approval":False,"source_promotion_performed":False,"source_promotion_performed_without_approval":False,"patches_applied_to_live_source_without_approval":False,"sandbox_promoted_to_source_without_approval":False,"approval_bypass_performed":False,"publish_performed":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"commands_executed_from_console":False,"approvals_inferred_from_readiness":False,"operator_approval_inferred":False,"promotion_auto_selected":False,"post_promotion_verification_auto_executed":False,"work_package_auto_launched":False}
    runtime_token = str(SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v170.0 - Operator-Approved Sandbox-to-Source Promotion" in docs and "v165.1-v166.0 - Sandbox Promotion Intake Layer" in docs else "blocked","message":"README and release history document v166-v170 supervised sandbox-to-source promotion."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"explicit-promotion-approval","status":"pass","message":"Live source promotion requires a fresh explicit operator approval and cannot be inferred from sandbox success."},
        {"name":"advisory-source-plan","status":"pass","message":"Source promotion plans remain advisory until operator approval; this arc prepares packets, not live writes."},
        {"name":"post-promotion-verification-gated","status":"pass","message":"Post-promotion verification and rollback procedures are prepared but not automatically executed by default."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"supervised-boundary","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, self-approval, approval inference, source promotion without approval, publishing, memory/identity mutation, hidden scheduling, default model invocation, auto-verification, or auto-promotion occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_sandbox_to_source_promotion_id(slug,{"project":project_id,"goal":improvement_goal,"candidate_file":candidate_file,"sandbox_id":sandbox_id,"promotion_id":promotion_id}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"sandbox_result_imported": True, "explicit_operator_promotion_approval_required": True, "source_target_scope_bound": True, "source_plan_advisory_until_approval": True, "post_promotion_verification_requires_operator_control": True, "automatic_promotion_allowed": False},"rows":rows,"advisory_only_until_approval":True,"operator_review_required":True,"operator_approval_required_before_source_promotion":True,"operator_approval_required_before_post_promotion_verification_execution":True,"read_only_runtime":True,**safety_false,"recommended_next_operator_action":"Review the promotion packet and provide explicit approval only when sandbox evidence is fresh, complete, and acceptable."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains supervised, approval-gated, and non-autonomous."
    if save:
        SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _supervised_sandbox_to_source_promotion_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v165.1-v170.0')} {payload.get('name','Operator-Approved Sandbox-to-Source Promotion')}", "", report.get("message","Supervised sandbox-to-source promotion report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Supervised and approval-gated. It may prepare promotion intake, source promotion plans, approval packets, post-promotion verification/rollback procedures, and audits, but it must not infer approval, self-approve, promote sandbox output to live source, publish, mutate memory or identity, schedule hidden work, invoke local models by default, auto-run verification, or bypass approval gates."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_supervised_sandbox_to_source_promotion_build(slug: str):
    return lambda *args, **kwargs: _build_supervised_sandbox_to_source_promotion_stage(slug, *args, **kwargs)

def _make_supervised_sandbox_to_source_promotion_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, sandbox_id: str | None = None, promotion_id: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_sandbox_to_source_promotion_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, sandbox_id=sandbox_id, promotion_id=promotion_id, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_sandbox_to_source_promotion_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _promotion_def in SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_DEFS:
    _promotion_slug = _promotion_def["slug"]
    globals()[f"build_{_promotion_slug}"] = _make_supervised_sandbox_to_source_promotion_build(_promotion_slug)
    globals()[f"{_promotion_slug}_text"] = _supervised_sandbox_to_source_promotion_text
    globals()[f"print_{_promotion_slug}"] = _make_supervised_sandbox_to_source_promotion_print(_promotion_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_STAGE_BY_SLUG)
SUPERVISED_RUNTIME_CLI_MAP.update(SUPERVISED_SANDBOX_TO_SOURCE_PROMOTION_CLI_MAP)
