SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_BY_SLUG = {item["slug"]: item for item in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_DEFS}
SUPERVISED_SOURCE_PATCH_APPLICATION_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_DEFS}
SUPERVISED_SOURCE_PATCH_APPLICATION_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_DEFS}

def _source_patch_application_id(slug: str, context: dict[str, Any]) -> str:
    raw = "|".join([slug, context.get("project") or "eidolon", context.get("goal") or "source-patch-application", context.get("promotion_id") or "promotion", context.get("approval_id") or "approval"])
    return "source-apply-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]

def _build_supervised_source_patch_application_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, sandbox_id: str | None = None, promotion_id: str | None = None, approval_id: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
    if slug not in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_BY_SLUG:
        return {"version":"v175.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown supervised source patch application stage: {slug}","rows":[]}
    definition = SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_BY_SLUG[slug]
    arc_items = [item for item in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_","-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    safety_false = {"autonomy_unlocked":False,"self_approval_performed":False,"operator_approval_inferred":False,"source_mutation_performed_without_approval":False,"live_source_mutation_performed_without_approval":False,"patches_applied_to_live_source_without_approval":False,"unapproved_file_write_performed":False,"publish_performed":False,"release_candidate_auto_created":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"commands_executed_from_console_without_approval":False,"verification_auto_executed_without_approval":False,"cascade_work_started":False,"approval_bypass_performed":False}
    runtime_token = str(SUPERVISED_SOURCE_PATCH_APPLICATION_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v175.0 - Operator-Approved Source Patch Application" in docs and "v170.1-v171.0 - Source Application Approval Intake Layer" in docs else "blocked","message":"README and release history document v171-v175 operator-approved source patch application."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"explicit-approval-required","status":"pass","message":"Live source application eligibility requires an explicit operator approval phrase and cannot be inferred from readiness, sandbox success, or promotion packets."},
        {"name":"snapshot-rollback-required","status":"pass","message":"Source application planning requires preflight snapshot/backup evidence and rollback readiness before mutation is considered."},
        {"name":"no-cascade-work","status":"pass","message":"The execution packet cannot continue into additional patches after the approved application scope."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"approval-bound-supervised-boundary","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, self-approval, inferred approval, unapproved source mutation, publishing, memory/identity mutation, hidden scheduling, default model invocation, unapproved verification, or cascade work occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_source_patch_application_id(slug,{"project":project_id,"goal":improvement_goal,"promotion_id":promotion_id,"approval_id":approval_id}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"promotion_packet_imported": True, "explicit_operator_source_application_approval_required": True, "approval_expiration_guard_enabled": True, "source_scope_bound": True, "snapshot_required_before_mutation": True, "rollback_required": True, "automatic_source_mutation_allowed": False},"rows":rows,"operator_review_required":True,"operator_approval_required_before_live_source_application":True,"operator_approval_required_before_verification_execution":True,"snapshot_required_before_source_mutation":True,"rollback_required":True,"approval_bound_only":True,**safety_false,"recommended_next_operator_action":"Review the source application approval packet and provide an exact approval only for the approved scope after snapshot and rollback readiness are acceptable."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains operator-approved, scope-bound, reversible, and non-autonomous."
    if save:
        SUPERVISED_SOURCE_PATCH_APPLICATION_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(SUPERVISED_SOURCE_PATCH_APPLICATION_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _supervised_source_patch_application_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v170.1-v175.0')} {payload.get('name','Operator-Approved Source Patch Application')}", "", report.get("message","Supervised source patch application report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Operator-approved and reversible. It may prepare approval intake, live source application plans, approved execution packets, post-application verification and rollback controls, and audits. It must not self-approve, infer approval, mutate live source outside explicit approval, publish, mutate memory or identity, schedule hidden work, invoke local models by default, auto-run verification without approval, or continue into new patches."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_supervised_source_patch_application_build(slug: str):
    return lambda *args, **kwargs: _build_supervised_source_patch_application_stage(slug, *args, **kwargs)

def _make_supervised_source_patch_application_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, sandbox_id: str | None = None, promotion_id: str | None = None, approval_id: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_supervised_source_patch_application_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, sandbox_id=sandbox_id, promotion_id=promotion_id, approval_id=approval_id, save=True, **kwargs)
        _json_print(report) if json_output else print(_supervised_source_patch_application_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _source_apply_def in SUPERVISED_SOURCE_PATCH_APPLICATION_STAGE_DEFS:
    _source_apply_slug = _source_apply_def["slug"]
    globals()[f"build_{_source_apply_slug}"] = _make_supervised_source_patch_application_build(_source_apply_slug)
    globals()[f"{_source_apply_slug}_text"] = _supervised_source_patch_application_text
    globals()[f"print_{_source_apply_slug}"] = _make_supervised_source_patch_application_print(_source_apply_slug)

