POST_APPLICATION_LEARNING_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in POST_APPLICATION_LEARNING_STAGE_DEFS}

def _post_application_learning_id(slug: str, data: dict[str, Any]) -> str:
    raw = "|".join([slug, data.get("project") or "eidolon", data.get("goal") or "post-application-learning", data.get("application_id") or "application", data.get("approval_id") or "approval", data.get("verification_id") or "verification"])
    return "post-app-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]

def _build_post_application_learning_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, application_id: str | None = None, approval_id: str | None = None, verification_id: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    if slug not in POST_APPLICATION_LEARNING_STAGE_BY_SLUG:
        return {"version":"v180.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown post-application learning stage: {slug}","rows":[]}
    definition = POST_APPLICATION_LEARNING_STAGE_BY_SLUG[slug]
    arc_items = [item for item in POST_APPLICATION_LEARNING_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_","-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    smoke_text = _read_text(ROOT_DIR / "tools" / "smoke_check.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    runtime_token = path_reference(POST_APPLICATION_LEARNING_RUNTIME_DIRS[definition["runtime_key"]])
    safety_false = {"autonomy_unlocked":False,"self_approval_performed":False,"operator_approval_inferred":False,"source_mutation_performed_without_approval":False,"publish_performed":False,"release_candidate_auto_created":False,"release_candidate_auto_packaged":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"verification_auto_executed_without_approval":False,"cascade_work_started":False,"next_patch_auto_started":False,"next_improvement_auto_selected":False,"work_order_auto_created":False}
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v180.0 - Operator-Governed Post-Application Learning and Release Readiness" in docs and "v175.1-v176.0 - Post-Application Outcome Intake Layer" in docs else "blocked","message":"README and release history document v176-v180 post-application learning and release readiness."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"smoke-coverage","status":"pass" if "operator-governed-post-application-learning-and-release-readiness" in smoke_text else "blocked","message":"Install smoke includes the v180 final closure audit."},
        {"name":"read-only-outcome-learning","status":"pass","message":"Outcome intake, lesson extraction, candidate building, and release readiness are advisory/read-only packets."},
        {"name":"no-release-candidate-auto-creation","status":"pass","message":"Release readiness may recommend ready/revise/blocked but cannot create, freeze, sign, package, or publish a release candidate."},
        {"name":"no-cascade-work","status":"pass","message":"The closure audit cannot continue into the next patch or work order automatically."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"operator-governed-boundary","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, self-approval, inferred approval, unapproved source mutation, publishing, release-candidate auto-creation, memory/identity mutation, hidden scheduling, default model invocation, unapproved verification, auto-selection, work-order creation, or cascade work occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_post_application_learning_id(slug,{"project":project_id,"goal":improvement_goal,"application_id":application_id,"approval_id":approval_id,"verification_id":verification_id}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"approved_source_application_imported": bool(application_id), "operator_notes_supported": True, "verification_evidence_import_only": True, "lessons_reviewable_only": True, "memory_write_allowed": False, "candidate_auto_selection_allowed": False, "release_candidate_auto_creation_allowed": False},"rows":rows,"operator_review_required":True,"advisory_only":True,"read_only_runtime":True,"operator_approval_required_before_any_future_source_mutation":True,"operator_approval_required_before_any_future_release_action":True,**safety_false,"recommended_next_operator_action":"Review the post-application packets, then explicitly choose whether to revise, prepare a supervised next patch, or begin a separate release-candidate workflow."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains operator-governed, advisory, read-only, and non-autonomous."
    if save:
        POST_APPLICATION_LEARNING_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(POST_APPLICATION_LEARNING_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _post_application_learning_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in POST_APPLICATION_LEARNING_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v175.1-v180.0')} {payload.get('name','Operator-Governed Post-Application Learning and Release Readiness')}", "", report.get("message","Post-application learning and release readiness report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Operator-governed and advisory. It may intake outcomes, extract reviewable lessons, rank supervised next-improvement candidates, judge release readiness, and audit the closure loop. It must not mutate memory, alter identity, infer approval, create or publish release candidates, auto-run verification, auto-select work, or continue into new patches."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_post_application_learning_build(slug: str):
    return lambda *args, **kwargs: _build_post_application_learning_stage(slug, *args, **kwargs)

def _make_post_application_learning_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, application_id: str | None = None, approval_id: str | None = None, verification_id: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_post_application_learning_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, application_id=application_id, approval_id=approval_id, verification_id=verification_id, save=True, **kwargs)
        _json_print(report) if json_output else print(_post_application_learning_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _post_app_def in POST_APPLICATION_LEARNING_STAGE_DEFS:
    _post_app_slug = _post_app_def["slug"]
    globals()[f"build_{_post_app_slug}"] = _make_post_application_learning_build(_post_app_slug)
    globals()[f"{_post_app_slug}_text"] = _post_application_learning_text
    globals()[f"print_{_post_app_slug}"] = _make_post_application_learning_print(_post_app_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(POST_APPLICATION_LEARNING_STAGE_DEFS)
