MULTI_CYCLE_ROADMAP_STAGE_BY_SLUG = {item["slug"]: item for item in MULTI_CYCLE_ROADMAP_STAGE_DEFS}
MULTI_CYCLE_ROADMAP_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in MULTI_CYCLE_ROADMAP_STAGE_DEFS}
MULTI_CYCLE_ROADMAP_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in MULTI_CYCLE_ROADMAP_STAGE_DEFS}

def _multi_cycle_roadmap_id(slug: str, data: dict[str, Any]) -> str:
    raw = "|".join([slug, data.get("project") or "eidolon", data.get("goal") or "multi-cycle-roadmap", data.get("roadmap_id") or "roadmap", data.get("operator_note_id") or "operator-note"])
    return "roadmap-intel-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]

def _build_multi_cycle_roadmap_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, roadmap_id: str | None = None, operator_note_id: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    if slug not in MULTI_CYCLE_ROADMAP_STAGE_BY_SLUG:
        return {"version":"v190.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown multi-cycle roadmap stage: {slug}","rows":[]}
    definition = MULTI_CYCLE_ROADMAP_STAGE_BY_SLUG[slug]
    arc_items = [item for item in MULTI_CYCLE_ROADMAP_STAGE_DEFS if item["version"] == definition["version"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in arc_items]
    flag_keys = [item["slug"].replace("_","-") for item in arc_items]
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    main_text = _read_text(ROOT_DIR / "conscious_agent" / "main.py")
    release_packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    smoke_text = _read_text(ROOT_DIR / "tools" / "smoke_check.py")
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    missing_cli = [key for key in flag_keys if key not in SUPERVISED_RUNTIME_CLI_MAP]
    runtime_token = str(MULTI_CYCLE_ROADMAP_RUNTIME_DIRS[definition["runtime_key"]].relative_to(ROOT_DIR)).replace(os.sep,"/")
    safety_false = {"autonomy_unlocked":False,"self_approval_performed":False,"operator_approval_inferred":False,"source_mutation_performed_without_approval":False,"publish_performed":False,"release_candidate_auto_created":False,"release_candidate_auto_packaged":False,"memory_mutation_performed":False,"identity_mutation_performed":False,"local_model_invoked_by_default":False,"automatic_action_performed":False,"hidden_scheduling_performed":False,"verification_auto_executed_without_approval":False,"cascade_work_started":False,"next_patch_auto_started":False,"roadmap_auto_selected":False,"roadmap_work_auto_launched":False,"work_package_auto_created":False,"implementation_auto_started":False,"proposal_auto_approved":False,"roadmap_score_treated_as_approval":False,"v200_readiness_treated_as_approval":False}
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v190.0 - Operator-Governed Multi-Cycle Roadmap Intelligence" in docs and "v185.1-v186.0 - Multi-Cycle Roadmap Intake Layer" in docs else "blocked","message":"README and release history document v186-v190 multi-cycle roadmap intelligence."},
        {"name":"substage-count","status":"pass" if len(arc_items) == 10 else "blocked","message":f"{len(arc_items)} stage(s) defined for {definition['version']}."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"{definition['dashboard']} dashboard route present."},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if not missing_cli and "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked","message":f"{len(flag_keys)} CLI flag(s) present dynamically." if not missing_cli else "missing: "+", ".join(missing_cli)},
        {"name":"runtime-privacy","status":"pass" if runtime_token in release_packaging_text and "data/autonomy" in release_packaging_text else "blocked","message":f"{runtime_token} remains excluded by source-only packaging."},
        {"name":"smoke-coverage","status":"pass" if "operator-governed-multi-cycle-roadmap-intelligence" in smoke_text else "blocked","message":"Install smoke includes the v190 final roadmap governance audit."},
        {"name":"roadmap-advisory-boundary","status":"pass","message":"Roadmap intake, options, dependencies, and v200 readiness remain advisory only."},
        {"name":"no-auto-roadmap-selection","status":"pass","message":"Roadmap scores and v200 readiness cannot select, approve, or launch work."},
        {"name":"no-cascade-work","status":"pass","message":"The roadmap governance audit cannot continue into implementation or new roadmap work automatically."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"Dashboard keeps custom data-tip hover system without native nav title tooltips."},
        {"name":"operator-governed-boundary","status":"pass" if all(value is False for value in safety_false.values()) else "blocked","message":"No autonomy, inferred approval, roadmap auto-selection, work launch, source mutation, release action, memory/identity mutation, hidden scheduling, default model invocation, auto verification, or cascade work occurred."},
    ]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_multi_cycle_roadmap_id(slug,{"project":project_id,"goal":improvement_goal,"roadmap_id":roadmap_id,"operator_note_id":operator_note_id}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in arc_items],"context":{"completed_arc_indexing_supported": True, "capability_inventory_supported": True, "roadmap_options_reviewable_only": True, "dependency_graph_advisory_only": True, "v200_readiness_not_approval": True, "source_write_allowed": False, "implementation_start_allowed": False, "roadmap_auto_selection_allowed": False, "release_candidate_auto_creation_allowed": False},"rows":rows,"operator_review_required":True,"advisory_only":True,"read_only_runtime":True,"operator_approval_required_before_any_future_source_mutation":True,"operator_approval_required_before_any_future_implementation":True,"operator_approval_required_before_any_future_release_action":True,**safety_false,"recommended_next_operator_action":"Review roadmap options, dependencies, and v200 readiness, then explicitly approve, revise, reject, or defer any future roadmap or patch proposal in a separate supervised step."}
    payload["status"] = "pass" if all(row["status"] == "pass" for row in rows) else "blocked"
    payload["ok"] = payload["status"] == "pass"
    payload["message"] = f"{definition['stage']} {definition['label']} is {payload['status']} and remains operator-governed, advisory, evidence-bound, read-only, and non-autonomous."
    if save:
        MULTI_CYCLE_ROADMAP_RUNTIME_DIRS[definition["runtime_key"]].mkdir(parents=True, exist_ok=True)
        _write_json(MULTI_CYCLE_ROADMAP_RUNTIME_DIRS[definition["runtime_key"]] / f"{slug}.json", payload)
    return {"version":definition["version"],"status":payload["status"],"ok":payload["ok"],"checked_at":_now(),"message":payload["message"],"rows":rows,slug:payload}

def _multi_cycle_roadmap_text(report: dict[str, Any], full: bool = False) -> str:
    payload = next((value for key, value in report.items() if isinstance(value, dict) and key in MULTI_CYCLE_ROADMAP_STAGE_BY_SLUG), {})
    lines = [f"# {payload.get('stage','v185.1-v190.0')} {payload.get('name','Operator-Governed Multi-Cycle Roadmap Intelligence')}", "", report.get("message","Multi-cycle roadmap intelligence report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()}: {row.get('name')} - {row.get('message')}")
    lines.extend(["", "## Boundary", "Operator-governed and roadmap-only. It may intake roadmap evidence, generate options, map dependencies, score v200 readiness, and audit governance. It must not auto-select roadmaps, launch work, mutate source, infer approval, run commands, create releases, mutate memory or identity, or continue into new work."])
    if full and payload:
        lines.extend(["", "## Substages"])
        for item in payload.get("substage_plan", []):
            lines.append(f"- {item['stage']} {item['label']} ({item['cli_flag']}, {item['api_route']})")
    return "\n".join(lines)

def _make_multi_cycle_roadmap_build(slug: str):
    return lambda *args, **kwargs: _build_multi_cycle_roadmap_stage(slug, *args, **kwargs)

def _make_multi_cycle_roadmap_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, roadmap_id: str | None = None, operator_note_id: str | None = None, full: bool = False, json_output: bool = False, **kwargs: Any) -> None:
        report = _build_multi_cycle_roadmap_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, roadmap_id=roadmap_id, operator_note_id=operator_note_id, save=True, **kwargs)
        _json_print(report) if json_output else print(_multi_cycle_roadmap_text(report, full))
    _printer.__name__ = f"print_{slug}"
    return _printer

for _roadmap_def in MULTI_CYCLE_ROADMAP_STAGE_DEFS:
    _roadmap_slug = _roadmap_def["slug"]
    globals()[f"build_{_roadmap_slug}"] = _make_multi_cycle_roadmap_build(_roadmap_slug)
    globals()[f"{_roadmap_slug}_text"] = _multi_cycle_roadmap_text
    globals()[f"print_{_roadmap_slug}"] = _make_multi_cycle_roadmap_print(_roadmap_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(MULTI_CYCLE_ROADMAP_STAGE_DEFS)
