CAPABILITY_MATURITY_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in CAPABILITY_MATURITY_STAGE_DEFS}

def _capability_maturity_id(slug: str, data: dict[str, Any]) -> str:
    raw = "|".join([slug, data.get("project") or "eidolon", data.get("goal") or "capability-maturity", data.get("capability_id") or "capability", data.get("operator_note_id") or "operator-note"])
    return "capmat-" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]

def _build_capability_maturity_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, roadmap_id: str | None = None, capability_id: str | None = None, operator_note_id: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = next((item for item in CAPABILITY_MATURITY_STAGE_DEFS if item["slug"] == slug), None)
    if not definition:
        return {"version":"v195.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown capability maturity stage: {slug}","rows":[]}
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    api_text = _read_text(ROOT_DIR / "conscious_agent" / "api_server.py")
    smoke_text = _read_text(ROOT_DIR / "tools" / "smoke_check.py")
    packaging_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    stage_items = [item for item in CAPABILITY_MATURITY_STAGE_DEFS if item["api"] == definition["api"]]
    route_keys = [f"{item['api']}/{item['route']}" for item in stage_items]
    flag_keys = [item["slug"].replace("_","-") for item in stage_items]
    missing_api = [key for key in route_keys if key not in SUPERVISED_RUNTIME_ROUTE_MAP]
    runtime_token = f"data/autonomy/{definition['runtime_key']}/"
    safety_false = {
        "autonomy_unlocked": False,
        "self_approval_performed": False,
        "operator_approval_inferred": False,
        "source_mutation_performed_without_approval": False,
        "publish_performed": False,
        "release_candidate_auto_created": False,
        "memory_mutation_performed": False,
        "identity_mutation_performed": False,
        "hidden_scheduling_performed": False,
        "verification_auto_executed_without_approval": False,
        "cascade_work_started": False,
        "capability_auto_expanded": False,
        "improvement_auto_started": False,
        "maturity_score_treated_as_approval": False,
    }
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v195.0 - Supervised Capability Maturity Modeling" in docs and "v190.1-v191.0 - Capability Inventory and Maturity Schema" in docs else "blocked","message":"README and release history document v191-v195 capability maturity modeling."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text and definition["api"] in dashboard_text else "blocked","message":definition["dashboard"]},
        {"name":"api-routes","status":"pass" if not missing_api and "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked","message":f"{len(route_keys)} API route(s) present dynamically." if not missing_api else "missing: "+", ".join(missing_api)},
        {"name":"cli-flags","status":"pass" if all(flag in smoke_text or flag in dashboard_text or flag in docs for flag in flag_keys) else "blocked","message":"CLI flag tokens are present for parity/smoke coverage."},
        {"name":"privacy-token","status":"pass" if runtime_token in packaging_text else "blocked","message":runtime_token},
        {"name":"approval-boundary","status":"pass" if not any(safety_false.values()) else "blocked","message":"Maturity scoring, gaps, and plans remain advisory only."},
        {"name":"dashboard-tooltip-regression","status":"pass" if " title=" not in dashboard_text[dashboard_text.find("NAV_ITEMS"):dashboard_text.find("def render", dashboard_text.find("NAV_ITEMS")) if dashboard_text.find("def render", dashboard_text.find("NAV_ITEMS")) != -1 else len(dashboard_text)] else "blocked","message":"No native title tooltips in nav tab region."},
        {"name":"smoke-coverage","status":"pass" if "supervised-capability-maturity-modeling" in smoke_text else "blocked","message":"Install smoke includes v195 final maturity governance audit."},
    ]
    ok = all(row["status"] == "pass" for row in rows)
    status = "pass" if ok else "blocked"
    key = definition["runtime_key"]
    payload = {"schema_version":f"eidolon.{definition['version'].lower().replace('.','_')}.{slug}.v1","artifact_id":_capability_maturity_id(slug,{"project":project_id,"goal":improvement_goal,"capability_id":capability_id,"operator_note_id":operator_note_id}),"stage":definition["stage"],"name":definition["label"],"arc_version":definition["version"],"theme":definition["theme"],"focus":definition["focus"],"dashboard_path":definition["dashboard"],"api_routes":[f"/api/{key}" for key in route_keys],"cli_flags":["--"+key for key in flag_keys],"runtime_dir":runtime_token,"substage_plan":[{"stage":item["stage"],"slug":item["slug"],"label":item["label"],"cli_flag":"--"+item["slug"].replace("_","-"),"api_route":f"/api/{item['api']}/{item['route']}"} for item in stage_items],"context":{"maturity_scores_advisory_only": True, "gap_reports_reviewable_only": True, "improvement_plans_not_execution_packets": True, "v200_ready_not_approval": True, "source_write_allowed": False, "implementation_start_allowed": False, "capability_auto_expansion_allowed": False, "release_candidate_auto_creation_allowed": False},"rows":rows,"operator_review_required":True,"advisory_only":True,"read_only_runtime":True,"operator_approval_required_before_any_future_source_mutation":True,"operator_approval_required_before_any_future_implementation":True,"operator_approval_required_before_any_future_release_action":True,**safety_false,"recommended_next_operator_action":"Review maturity scores, gaps, overreach warnings, and improvement plans, then explicitly approve, revise, reject, or defer any future capability hardening in a separate supervised step."}
    report = {"version":"v195.0","status":status,"ok":ok,"checked_at":_now(),"project_id":project_id,"message":f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}","payload":payload,"rows":rows}
    if save:
        outdir = CAPABILITY_MATURITY_RUNTIME_DIRS[key]
        _ensure_dir(outdir)
        _write_json(outdir / f"{slug}.json", report)
    return report

def _capability_maturity_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    lines = [f"# {payload.get('stage','v190.1-v195.0')} {payload.get('name','Supervised Capability Maturity Modeling')}", "", report.get("message","Capability maturity modeling report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','?').upper()}: {row.get('name','check')} - {row.get('message','')}")
    lines.extend(["", "## Operator Boundary", "- Advisory only: maturity scores, gaps, and improvement plans do not grant approval.", "- No source writes, memory mutation, identity mutation, release action, hidden scheduling, or capability expansion is performed."])
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2, sort_keys=True)])
    return "\n".join(lines)

def _make_capability_maturity_build(slug: str):
    return lambda *args, **kwargs: _build_capability_maturity_stage(slug, *args, **kwargs)

def _make_capability_maturity_print(slug: str):
    def _printer(project_id: str = "eidolon", improvement_goal: str | None = None, candidate_file: str | None = None, roadmap_id: str | None = None, capability_id: str | None = None, operator_note_id: str | None = None, json_output: bool = False, full: bool = False, **kwargs: Any) -> None:
        report = _build_capability_maturity_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, roadmap_id=roadmap_id, capability_id=capability_id, operator_note_id=operator_note_id, save=True, **kwargs)
        _json_print(report) if json_output else print(_capability_maturity_text(report, full))
    return _printer

for _maturity_def in CAPABILITY_MATURITY_STAGE_DEFS:
    _maturity_slug = _maturity_def["slug"]
    globals()[f"build_{_maturity_slug}"] = _make_capability_maturity_build(_maturity_slug)
    globals()[f"{_maturity_slug}_text"] = _capability_maturity_text
    globals()[f"print_{_maturity_slug}"] = _make_capability_maturity_print(_maturity_slug)

SUPERVISED_RUNTIME_ROUTE_MAP.update(CAPABILITY_MATURITY_ROUTE_MAP)
