GOVERNANCE_KERNEL_STAGE_BY_SLUG = {item["slug"]: item for item in GOVERNANCE_KERNEL_STAGE_DEFS}
GOVERNANCE_KERNEL_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in GOVERNANCE_KERNEL_STAGE_DEFS}
GOVERNANCE_KERNEL_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in GOVERNANCE_KERNEL_STAGE_DEFS}
GOVERNANCE_KERNEL_CAPABILITY_DOMAINS = [
    "governance state", "rule evaluation", "operator consent", "enforcement simulation",
    "approval boundaries", "source mutation control", "release controls", "memory and identity boundaries",
    "dashboard/API/CLI parity", "documentation and evidence traceability",
]

def _governance_kernel_status_rows(definition, docs):
    route_map = globals().get("SUPERVISED_RUNTIME_ROUTE_MAP", {})
    cli_map = globals().get("SUPERVISED_RUNTIME_CLI_MAP", {})
    dashboard_text = _read_text(ROOT_DIR / "conscious_agent" / "dashboard.py")
    package_text = _read_text(ROOT_DIR / "conscious_agent" / "release_packaging.py")
    rows = [
        {"name":"version-markers","status":"pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked","message":f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name":"docs","status":"pass" if "v200.0 - Local Artificial Mind Governance Kernel v1" in docs and "v195.1-v196.0 - Governance Kernel State Model" in docs else "blocked","message":"README and release history document v196-v200 governance kernel work."},
        {"name":"dashboard-route","status":"pass" if definition["dashboard"] in dashboard_text else "blocked","message":f"Dashboard route {definition['dashboard']} is documented."},
        {"name":"dynamic-api-route","status":"pass" if f"{definition['api']}/{definition['route']}" in route_map else "blocked","message":f"Dynamic API route /api/{definition['api']}/{definition['route']} is registered."},
        {"name":"dynamic-cli-flag","status":"pass" if definition["slug"].replace("_", "-") in cli_map else "blocked","message":f"CLI flag --{definition['slug'].replace('_','-')} is registered."},
        {"name":"privacy-token","status":"pass" if f"data/autonomy/{definition['runtime_key']}/" in package_text else "blocked","message":f"Source-only privacy token for {definition['runtime_key']} is present."},
        {"name":"approval-boundary","status":"pass","message":"Governance output remains descriptive, review-only, and cannot grant approval."},
        {"name":"non-autonomy-boundary","status":"pass","message":"No self-approval, hidden scheduling, memory mutation, identity mutation, auto-release, default local-model invocation, or autonomous continuation is authorized."},
        {"name":"tooltip-regression","status":"pass" if not _dashboard_nav_title_regression_present() else "blocked","message":"No native title tooltips on nav tabs; custom data-tip hover remains the dashboard hover path."},
    ]
    return rows

def _build_governance_kernel_stage(slug, project_id="default", improvement_goal=None, candidate_file=None, save=True):
    definition = GOVERNANCE_KERNEL_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version":"v200.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown governance kernel stage: {slug}","rows":[]}
    docs = _read_text(ROOT_DIR / "README_NEXT_STEPS.md") + "\n" + _read_text(ROOT_DIR / "README_RELEASE_HISTORY.md")
    rows = _governance_kernel_status_rows(definition, docs)
    ok = all(row.get("status") == "pass" for row in rows)
    status = "pass" if ok else "blocked"
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v195.1-v200.0 Local Artificial Mind Governance Kernel v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "capability_domains": GOVERNANCE_KERNEL_CAPABILITY_DOMAINS,
        "forbidden_actions": GOVERNANCE_KERNEL_FORBIDDEN_ACTIONS,
        "governance_decisions": ["allowed_for_review", "requires_operator_approval", "blocked", "insufficient_evidence"],
        "approval_model": {"explicit_operator_approval_required": True, "approval_inferred_from_readiness": False, "approval_reusable_outside_scope": False},
        "safety": {
            "descriptive_only": True,
            "can_authorize_actions": False,
            "can_execute_workflows": False,
            "can_publish_release": False,
            "can_mutate_memory_or_identity": False,
            "can_invoke_local_models_by_default": False,
            "can_continue_autonomously": False,
        },
        "evidence": [row["name"] for row in rows if row.get("status") == "pass"],
    }
    report = {"version":"v200.0","status":status,"ok":ok,"checked_at":_now(),"project_id":project_id,"message":f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}","payload":payload,"rows":rows}
    if save:
        outdir = GOVERNANCE_KERNEL_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report

def _governance_kernel_text(report, full=False):
    payload = report.get("payload", {})
    lines = [f"# {payload.get('stage','v195.1-v200.0')} {payload.get('name','Local Artificial Mind Governance Kernel v1')}", "", report.get("message","Governance kernel report."), "", "## Checks"]
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Governance boundaries"])
    safety = payload.get("safety", {})
    lines.append(f"- Descriptive only: {safety.get('descriptive_only', True)}")
    lines.append(f"- Can authorize actions: {safety.get('can_authorize_actions', False)}")
    lines.append(f"- Can execute workflows: {safety.get('can_execute_workflows', False)}")
    lines.append(f"- Explicit operator approval required: {payload.get('approval_model', {}).get('explicit_operator_approval_required', True)}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)

def _make_governance_kernel_build(slug):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, save=True):
        return _build_governance_kernel_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save)
    return _builder

def _make_governance_kernel_print(slug):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, full=False, json_output=False):
        report = _build_governance_kernel_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=False)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_governance_kernel_text(report, full=full))
    return _printer

for _governance_slug in GOVERNANCE_KERNEL_STAGE_BY_SLUG:
    globals()[f"build_{_governance_slug}"] = _make_governance_kernel_build(_governance_slug)
    globals()[f"{_governance_slug}_text"] = _governance_kernel_text
    globals()[f"print_{_governance_slug}"] = _make_governance_kernel_print(_governance_slug)

