def _cognitive_continuity_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "tools/smoke_check.py", "conscious_agent/release_packaging.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(parts)

def _cognitive_continuity_status_rows(definition, docs_text: str):
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="replace")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace")
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="replace")
    smoke_text = (ROOT_DIR / "tools" / "smoke_check.py").read_text(encoding="utf-8", errors="replace")
    package_text = (ROOT_DIR / "conscious_agent" / "release_packaging.py").read_text(encoding="utf-8", errors="replace")
    route_map = globals().get("SUPERVISED_RUNTIME_ROUTE_MAP", {})
    cli_map = globals().get("SUPERVISED_RUNTIME_CLI_MAP", {})
    route_key = f"{definition['api']}/{definition['route']}"
    cli_key = definition["slug"].replace("_", "-")
    required_doc_tokens = ["Operator-Governed Cognitive Continuity Layer v1", "Supervised Memory Candidate Staging", "Operator-Governed Identity Boundary Layer", "Supervised Reflection and Growth Journal"]
    rows = [
        {"name":"stage-definition", "status":"pass" if definition["slug"] in COGNITIVE_CONTINUITY_STAGE_BY_SLUG else "blocked", "message":f"{definition['stage']} {definition['label']} is registered."},
        {"name":"dashboard-route", "status":"pass" if definition["dashboard"] in dashboard_text else "blocked", "message":f"Dashboard route {definition['dashboard']} is present."},
        {"name":"dynamic-api-route", "status":"pass" if route_key in route_map else "blocked", "message":f"Dynamic API route /api/{route_key} is registered."},
        {"name":"dynamic-cli-flag", "status":"pass" if cli_key in cli_map else "blocked", "message":f"CLI flag --{cli_key} is registered."},
        {"name":"api-handler", "status":"pass" if "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message":"Dynamic API handler remains active."},
        {"name":"cli-handler", "status":"pass" if "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message":"Dynamic CLI handler remains active."},
        {"name":"package-privacy-token", "status":"pass" if f"data/autonomy/{definition['runtime_key']}/" in package_text else "blocked", "message":f"Source-only privacy token for {definition['runtime_key']} is present."},
        {"name":"docs-coverage", "status":"pass" if all(token in docs_text for token in required_doc_tokens) else "blocked", "message":"README next steps and release history document the cognitive continuity arc."},
        {"name":"smoke-version", "status":"pass" if '"version": "545.0"' in smoke_text else "blocked", "message":"Smoke JSON summary reports the current smoke summary version."},
        {"name":"non-mutation-boundary", "status":"pass", "message":"Continuity, memory candidates, identity review, and reflection are review-only and cannot mutate source, memory, identity, or approval state."},
        {"name":"tooltip-regression", "status":"pass" if not _dashboard_nav_title_regression_present() else "blocked", "message":"No native title tooltips on nav tabs; custom data-tip hover remains the dashboard hover path."},
    ]
    return rows

def _classify_memory_candidate(text: str | None) -> dict[str, Any]:
    value = (text or "").strip().lower()
    if not value:
        return {"type":"rejected", "confidence":0.0, "reason":"No candidate text supplied.", "candidate_only": True}
    sensitive_terms = ["diagnosis", "medical", "religion", "political", "criminal", "address", "sexual", "race", "ethnicity"]
    identity_terms = ["identity", "personality", "purpose", "autonomy", "self-permission", "memory authority"]
    if any(term in value for term in sensitive_terms):
        return {"type":"sensitive", "confidence":0.7, "reason":"Candidate touches sensitive or highly personal material and must be blocked unless explicitly operator-approved.", "candidate_only": True}
    if any(term in value for term in identity_terms):
        return {"type":"identity_adjacent", "confidence":0.75, "reason":"Candidate appears identity-adjacent and requires explicit operator review.", "candidate_only": True}
    if any(term in value for term in ["readme", "release", "patch", "smoke", "dashboard", "governance"]):
        return {"type":"project_memory", "confidence":0.85, "reason":"Candidate relates to durable project process or technical governance context.", "candidate_only": True}
    return {"type":"technical_lesson", "confidence":0.6, "reason":"Candidate looks like a technical or workflow lesson, not an automatic memory update.", "candidate_only": True}

def _classify_identity_boundary(text: str | None) -> dict[str, Any]:
    value = (text or "").lower()
    forbidden = ["self-approve", "autonomous", "auto-apply", "mutate memory", "alter identity", "infer approval", "publish release", "hidden schedule"]
    hits = [term for term in forbidden if term in value]
    return {"identity_change_detected": bool(hits), "forbidden_hits": hits, "requires_explicit_operator_approval": bool(hits), "self_authored_change_allowed": False}

def _build_cognitive_continuity_stage(slug, project_id="default", improvement_goal=None, candidate_file=None, action_type=None, requested_action=None, approval_scope=None, save=True):
    definition = COGNITIVE_CONTINUITY_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version":"v210.0","status":"blocked","ok":False,"checked_at":_now(),"message":f"Unknown cognitive continuity stage: {slug}","rows":[]}
    docs = _cognitive_continuity_docs_text()
    rows = _cognitive_continuity_status_rows(definition, docs)
    text = requested_action or improvement_goal or ""
    memory_classification = _classify_memory_candidate(text)
    identity_boundary = _classify_identity_boundary(text)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    status = "pass" if ok else "blocked"
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v205.1-v210.0 Operator-Governed Cognitive Continuity Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "action_type": action_type,
        "requested_action": requested_action,
        "approval_scope": approval_scope,
        "cycle_outcome": "governance_audited" if "audit" in definition["theme"] or "audit" in definition["slug"] else "review_only",
        "memory_candidate": {"classification": memory_classification, "applied": False, "write_path": None},
        "identity_boundary": identity_boundary,
        "lesson_candidates": COGNITIVE_CONTINUITY_LESSON_CANDIDATES,
        "growth_summary": "Eidolon may summarize continuity, propose memory candidates, audit identity boundaries, and reflect on growth, but every output remains review-only until the operator explicitly approves a separate action.",
        "safe_next_action": "Operator may review this continuity packet and issue a fresh, explicit approval for a named follow-up scope if desired.",
        "blockers": blockers,
        "boundaries": COGNITIVE_CONTINUITY_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version":"v210.0","status":status,"ok":ok,"checked_at":_now(),"project_id":project_id,"message":message,"payload":payload,"rows":rows}
    if save:
        outdir = COGNITIVE_CONTINUITY_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report

def _cognitive_continuity_text(report, full=False):
    payload = report.get("payload", {})
    memory = payload.get("memory_candidate", {}).get("classification", {})
    identity = payload.get("identity_boundary", {})
    lines = [f"# {payload.get('stage','v205.1-v210.0')} {payload.get('name','Operator-Governed Cognitive Continuity Layer v1')}", "", report.get("message", "Cognitive continuity report."), "", "## Continuity packet"]
    lines.append(f"- Cycle outcome: {payload.get('cycle_outcome', 'review_only')}")
    lines.append(f"- Growth summary: {payload.get('growth_summary', 'Review only.')}")
    lines.append(f"- Safe next action: {payload.get('safe_next_action', 'Review only.')}")
    lines.extend(["", "## Memory candidate staging"])
    lines.append(f"- Candidate type: {memory.get('type', 'unknown')}")
    lines.append(f"- Candidate only: {memory.get('candidate_only', True)}")
    lines.append(f"- Applied to memory: {payload.get('memory_candidate', {}).get('applied', False)}")
    lines.append(f"- Reason: {memory.get('reason', 'No candidate supplied.')}")
    lines.extend(["", "## Identity boundary"])
    lines.append(f"- Identity change detected: {identity.get('identity_change_detected', False)}")
    lines.append(f"- Requires explicit operator approval: {identity.get('requires_explicit_operator_approval', False)}")
    lines.append(f"- Self-authored identity change allowed: {identity.get('self_authored_change_allowed', False)}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", {}).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)

def _make_cognitive_continuity_build(slug):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, action_type=None, requested_action=None, approval_scope=None, save=True, **kwargs):
        return _build_cognitive_continuity_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, action_type=action_type, requested_action=requested_action, approval_scope=approval_scope, save=save)
    return _builder

def _make_cognitive_continuity_print(slug):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, action_type=None, requested_action=None, approval_scope=None, full=False, json_output=False, **kwargs):
        report = _build_cognitive_continuity_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, action_type=action_type, requested_action=requested_action, approval_scope=approval_scope, save=False)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_cognitive_continuity_text(report, full=full))
    return _printer

for _cognitive_continuity_slug in COGNITIVE_CONTINUITY_STAGE_BY_SLUG:
    globals()[f"build_{_cognitive_continuity_slug}"] = _make_cognitive_continuity_build(_cognitive_continuity_slug)
    globals()[f"{_cognitive_continuity_slug}_text"] = _cognitive_continuity_text
    globals()[f"print_{_cognitive_continuity_slug}"] = _make_cognitive_continuity_print(_cognitive_continuity_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(COGNITIVE_CONTINUITY_STAGE_DEFS)
