SIMULATION_FORESIGHT_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in SIMULATION_FORESIGHT_STAGE_DEFS}
SIMULATION_FORESIGHT_RUNTIME_DIRS = {
    "internal_simulation_packet": DATA_DIR / "autonomy" / "internal_simulation_packet",
    "foresight_branch_comparison": DATA_DIR / "autonomy" / "foresight_branch_comparison",
    "pre_change_consequence_modeling": DATA_DIR / "autonomy" / "pre_change_consequence_modeling",
    "expectation_reality_check": DATA_DIR / "autonomy" / "expectation_reality_check",
    "simulation_foresight_audit": DATA_DIR / "autonomy" / "simulation_foresight_audit",
}
SIMULATION_FORESIGHT_BOUNDARIES = {
    "descriptive_only": True,
    "simulation_packets_execute_commands": False,
    "simulation_success_grants_approval": False,
    "branch_comparison_selects_roadmap": False,
    "consequence_model_mutates_source": False,
    "expectation_reality_launches_followup": False,
    "simulation_promotes_release": False,
    "memory_or_identity_mutation_performed": False,
    "hidden_scheduling_performed": False,
    "local_model_invoked_by_default": False,
    "autonomous_continuation_performed": False,
}
SIMULATION_FAILURE_MODES = [
    {"mode":"route/API/CLI parity drift", "likelihood":"medium", "mitigation":"bind each dashboard route to dynamic runtime maps and smoke coverage"},
    {"mode":"stale version metadata", "likelihood":"medium", "mitigation":"check code markers, smoke JSON version, docs, source data, and package metadata"},
    {"mode":"dashboard tooltip regression", "likelihood":"low", "mitigation":"preserve data-tip and reject native title tooltips on nav tabs"},
    {"mode":"package privacy leak", "likelihood":"low", "mitigation":"keep runtime data paths excluded and source-only tokens explicit"},
    {"mode":"simulated success mistaken for approval", "likelihood":"high", "mitigation":"render explicit non-execution and non-authorization boundaries"},
]
FORESIGHT_BRANCHES = [
    {"branch":"verification hardening", "benefit":"reduce repeated version and smoke drift", "risk":"low", "governance_cost":"low", "evidence_ready": True, "selected_as_approved": False},
    {"branch":"dashboard console compression", "benefit":"reduce operator navigation burden", "risk":"medium", "governance_cost":"medium", "evidence_ready": True, "selected_as_approved": False},
    {"branch":"deeper cognitive continuity", "benefit":"improve self-understanding under supervision", "risk":"medium", "governance_cost":"high", "evidence_ready": False, "selected_as_approved": False},
]

def _simulation_foresight_docs_text() -> str:
    parts = []
    for rel in ("README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"):
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(parts)

def _simulation_foresight_status_rows(definition: dict[str, Any], docs_text: str) -> list[dict[str, Any]]:
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="replace")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="replace")
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="replace")
    smoke_text = (ROOT_DIR / "tools" / "smoke_check.py").read_text(encoding="utf-8", errors="replace")
    package_text = (ROOT_DIR / "conscious_agent" / "release_packaging.py").read_text(encoding="utf-8", errors="replace")
    route_map = globals().get("SUPERVISED_RUNTIME_ROUTE_MAP", {})
    cli_map = globals().get("SUPERVISED_RUNTIME_CLI_MAP", {})
    route_key = f"{definition['api']}/{definition['route']}"
    cli_key = definition["slug"].replace("_", "-")
    required_doc_tokens = [
        "Operator-Governed Internal Simulation and Foresight Layer v1",
        "Supervised Internal Simulation Packet Layer",
        "Operator-Governed Foresight Branch Comparison",
        "Supervised Pre-Change Consequence Modeling",
        "Supervised Expectation-Reality Check Layer",
    ]
    rows = [
        {"name":"stage-definition", "status":"pass" if definition["slug"] in SIMULATION_FORESIGHT_STAGE_BY_SLUG else "blocked", "message":f"{definition['stage']} {definition['label']} is registered."},
        {"name":"dashboard-route", "status":"pass" if definition["dashboard"] in dashboard_text else "blocked", "message":f"Dashboard route {definition['dashboard']} is present."},
        {"name":"dynamic-api-route", "status":"pass" if route_key in route_map else "blocked", "message":f"Dynamic API route /api/{route_key} is registered."},
        {"name":"dynamic-cli-flag", "status":"pass" if cli_key in cli_map else "blocked", "message":f"CLI flag --{cli_key} is registered."},
        {"name":"api-handler", "status":"pass" if "SUPERVISED_RUNTIME_ROUTE_MAP" in api_text else "blocked", "message":"Dynamic API handler remains active."},
        {"name":"cli-handler", "status":"pass" if "SUPERVISED_RUNTIME_CLI_MAP" in main_text else "blocked", "message":"Dynamic CLI handler remains active."},
        {"name":"package-privacy-token", "status":"pass" if f"data/autonomy/{definition['runtime_key']}/" in package_text else "blocked", "message":f"Source-only privacy token for {definition['runtime_key']} is present."},
        {"name":"docs-coverage", "status":"pass" if all(token in docs_text for token in required_doc_tokens) else "blocked", "message":"README next steps and release history document the v220 simulation/foresight arc."},
        {"name":"smoke-version", "status":"pass" if '"version": "545.0"' in smoke_text else "blocked", "message":"Smoke JSON summary reports the current smoke summary version."},
        {"name":"simulation-non-execution", "status":"pass" if SIMULATION_FORESIGHT_BOUNDARIES.get("simulation_packets_execute_commands") is False and SIMULATION_FORESIGHT_BOUNDARIES.get("simulation_success_grants_approval") is False else "blocked", "message":"Simulations cannot execute commands or grant approval."},
        {"name":"no-autonomy-boundary", "status":"pass" if all(value is False for key, value in SIMULATION_FORESIGHT_BOUNDARIES.items() if key != "descriptive_only") else "blocked", "message":"No self-approval, mutation, scheduling, default model invocation, release promotion, roadmap selection, or autonomous continuation is allowed."},
        {"name":"tooltip-regression", "status":"pass" if not _dashboard_nav_title_regression_present() else "blocked", "message":"No native title tooltips on nav tabs; custom data-tip hover remains the dashboard hover path."},
    ]
    return rows

def _classify_simulation_type(text: str | None) -> str:
    value = (text or "").lower()
    for key in ("memory", "identity", "roadmap", "dashboard", "smoke", "package", "release", "governance"):
        if key in value:
            return key
    return "patch" if value else "general"

def _build_simulation_foresight_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, action_type: str | None = None, requested_action: str | None = None, approval_scope: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SIMULATION_FORESIGHT_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version":"v220.0", "status":"blocked", "ok":False, "checked_at":_now(), "message":f"Unknown simulation/foresight stage: {slug}", "rows":[]}
    docs = _simulation_foresight_docs_text()
    rows = _simulation_foresight_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    text = requested_action or improvement_goal or ""
    expected_checklist = [
        "dashboard route added and dispatch checked",
        "dynamic API and CLI route-map coverage present",
        "README_NEXT_STEPS and README_RELEASE_HISTORY updated",
        "source-only privacy tokens present and runtime data excluded",
        "fast/install and extracted ZIP smoke planned or run by operator",
        "simulation remains non-executing and non-authorizing",
    ]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v215.1-v220.0 Operator-Governed Internal Simulation and Foresight Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "action_type": action_type or _classify_simulation_type(text),
        "requested_action": requested_action,
        "approval_scope": approval_scope,
        "simulation_packet": {
            "simulation_type": _classify_simulation_type(text),
            "assumptions": ["operator approval remains explicit and scoped", "simulation does not execute commands", "post-change reality requires external evidence"],
            "expected_outcome": "A reviewable forecast and checklist for operator consideration only.",
            "failure_modes": SIMULATION_FAILURE_MODES,
            "executed_commands": False,
            "mutated_files": False,
            "approval_granted": False,
        },
        "foresight_branch_comparison": {
            "branches": FORESIGHT_BRANCHES,
            "roadmap_selected_as_approved": False,
            "recommendation_only": True,
        },
        "pre_change_consequence_model": {
            "source_impact_forecast": ["self_maintenance.py", "dashboard.py", "tools/smoke_check.py", "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md"],
            "runtime_surface_impact": ["dashboard route", "dynamic API route", "dynamic CLI flag", "source-only package privacy token"],
            "mutates_source": False,
        },
        "expectation_reality_check": {
            "expected_checklist": expected_checklist,
            "followup_launched": False,
            "simulation_accuracy_authorizes_action": False,
        },
        "safe_next_action": "Operator may review this simulation/foresight packet and issue a fresh explicit approval for a named follow-up scope if desired.",
        "blockers": blockers,
        "boundaries": SIMULATION_FORESIGHT_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version":"v220.0", "status":"pass" if ok else "blocked", "ok":ok, "checked_at":_now(), "project_id":project_id, "message":message, "payload":payload, "rows":rows}
    if save:
        outdir = SIMULATION_FORESIGHT_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report

def _simulation_foresight_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    sim = payload.get("simulation_packet", {})
    branches = payload.get("foresight_branch_comparison", {}).get("branches", FORESIGHT_BRANCHES)
    consequence = payload.get("pre_change_consequence_model", {})
    reality = payload.get("expectation_reality_check", {})
    lines = [f"# {payload.get('stage', report.get('stage', 'v215.1-v220.0'))} {payload.get('name', 'Operator-Governed Internal Simulation and Foresight Layer v1')}", "", report.get("message", "Simulation and foresight report."), "", "## Simulation packet"]
    lines.append(f"- Type: {sim.get('simulation_type', 'general')}")
    lines.append(f"- Executed commands: {sim.get('executed_commands', False)}")
    lines.append(f"- Mutated files: {sim.get('mutated_files', False)}")
    lines.append(f"- Approval granted: {sim.get('approval_granted', False)}")
    for failure in sim.get("failure_modes", SIMULATION_FAILURE_MODES)[:4]:
        lines.append(f"- Failure mode: {failure.get('mode')} | mitigation: {failure.get('mitigation')}")
    lines.extend(["", "## Foresight branches"])
    for branch in branches[:4]:
        lines.append(f"- {branch.get('branch')} | risk: {branch.get('risk')} | benefit: {branch.get('benefit')} | selected-as-approved: {branch.get('selected_as_approved', False)}")
    lines.extend(["", "## Consequence model"])
    lines.append(f"- Mutates source: {consequence.get('mutates_source', False)}")
    for item in consequence.get("runtime_surface_impact", [])[:5]:
        lines.append(f"- Runtime impact forecast: {item}")
    lines.extend(["", "## Expectation/reality check"])
    lines.append(f"- Follow-up launched: {reality.get('followup_launched', False)}")
    lines.append(f"- Accuracy authorizes action: {reality.get('simulation_accuracy_authorizes_action', False)}")
    for item in reality.get("expected_checklist", [])[:6]:
        lines.append(f"- Expected: {item}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", SIMULATION_FORESIGHT_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)

def _make_simulation_foresight_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, action_type=None, requested_action=None, approval_scope=None, save=True, **kwargs):
        return _build_simulation_foresight_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, action_type=action_type, requested_action=requested_action, approval_scope=approval_scope, save=save, **kwargs)
    return _builder

def _make_simulation_foresight_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, action_type=None, requested_action=None, approval_scope=None, full=False, json_output=False, **kwargs):
        report = _build_simulation_foresight_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, action_type=action_type, requested_action=requested_action, approval_scope=approval_scope, save=False, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_simulation_foresight_text(report, full=full))
    return _printer

for _simulation_foresight_slug in SIMULATION_FORESIGHT_STAGE_BY_SLUG:
    globals()[f"build_{_simulation_foresight_slug}"] = _make_simulation_foresight_build(_simulation_foresight_slug)
    globals()[f"{_simulation_foresight_slug}_text"] = _simulation_foresight_text
    globals()[f"print_{_simulation_foresight_slug}"] = _make_simulation_foresight_print(_simulation_foresight_slug)

