def _learning_curriculum_docs_text() -> str:
    chunks: list[str] = []
    for path in (ROOT_DIR / "README_NEXT_STEPS.md", ROOT_DIR / "README_RELEASE_HISTORY.md", ROOT_DIR / "conscious_agent" / "dashboard.py", ROOT_DIR / "conscious_agent" / "release_packaging.py"):
        try:
            chunks.append(path.read_text(encoding="utf-8"))
        except Exception:
            pass
    return "\n".join(chunks)


def _learning_curriculum_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["learning-objective-map", "practice-task-design", "capability-calibration", "skill-gap-remediation-planner", "learning-curriculum-audit", "operator-governed-learning-curriculum-and-capability-calibration-layer-v1"]
    runtime_tokens = ["data/autonomy/learning_objective_map/", "data/autonomy/practice_task_design/", "data/autonomy/capability_calibration/", "data/autonomy/skill_gap_remediation_planner/", "data/autonomy/learning_curriculum_audit/"]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "route-tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Learning curriculum dashboard/API/CLI/docs tokens are present."},
        {"name": "runtime-privacy-tokens", "status": "pass" if all(token in docs for token in runtime_tokens) else "blocked", "message": "Runtime learning curriculum data remains source-only excluded."},
        {"name": "learning-non-autonomy", "status": "pass" if LEARNING_CURRICULUM_BOUNDARIES.get("learning_objectives_start_work") is False and LEARNING_CURRICULUM_BOUNDARIES.get("autonomous_learning_loop_started") is False else "blocked", "message": "Learning objectives cannot start autonomous work or learning loops."},
        {"name": "practice-non-execution", "status": "pass" if LEARNING_CURRICULUM_BOUNDARIES.get("practice_tasks_execute_work") is False else "blocked", "message": "Practice tasks are designs only and cannot execute."},
        {"name": "calibration-non-promotion", "status": "pass" if LEARNING_CURRICULUM_BOUNDARIES.get("calibration_promotes_capability") is False and LEARNING_CURRICULUM_BOUNDARIES.get("high_scores_expand_authority") is False else "blocked", "message": "Calibration scores cannot promote capability authority."},
        {"name": "remediation-no-continuation", "status": "pass" if LEARNING_CURRICULUM_BOUNDARIES.get("remediation_continues_work") is False else "blocked", "message": "Remediation plans cannot continue into implementation."},
        {"name": "memory-identity-locked", "status": "pass" if LEARNING_CURRICULUM_BOUNDARIES.get("memory_mutation_performed") is False and LEARNING_CURRICULUM_BOUNDARIES.get("identity_mutation_performed") is False else "blocked", "message": "Curriculum surfaces cannot mutate memory or identity."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_learning_curriculum_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, learning_domain: str | None = None, capability_claim: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = LEARNING_CURRICULUM_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v225.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown learning curriculum stage: {slug}", "rows": []}
    docs = _learning_curriculum_docs_text()
    rows = _learning_curriculum_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    objective_domain = learning_domain or (improvement_goal or "supervised growth discipline")
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v220.1-v225.0 Operator-Governed Learning Curriculum and Capability Calibration Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "learning_domain": objective_domain,
        "capability_claim": capability_claim,
        "learning_objective_map": {
            "objectives": LEARNING_OBJECTIVE_SEEDS,
            "starts_work": False,
            "autonomous_loop_started": False,
            "success_requires_operator_review": True,
        },
        "practice_task_design": {
            "practice_tasks": PRACTICE_TASK_SEEDS,
            "executes_tasks": False,
            "operator_review_required_before_use": True,
        },
        "capability_calibration": {
            "claims": CAPABILITY_CALIBRATION_CLAIMS,
            "promotion_authorized": False,
            "self_declared_mastery_allowed": False,
        },
        "skill_gap_remediation": {
            "gaps": SKILL_GAP_REMEDIATION_SEEDS,
            "continues_into_implementation": False,
            "requires_fresh_approval_for_action": True,
        },
        "safe_next_action": "Operator may review the curriculum/calibration packet and explicitly approve a named practice or remediation exercise if desired.",
        "blockers": blockers,
        "boundaries": LEARNING_CURRICULUM_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v225.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = LEARNING_CURRICULUM_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _learning_curriculum_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    objective_map = payload.get("learning_objective_map", {})
    practice = payload.get("practice_task_design", {})
    calibration = payload.get("capability_calibration", {})
    remediation = payload.get("skill_gap_remediation", {})
    lines = [f"# {payload.get('stage', 'v220.1-v225.0')} {payload.get('name', 'Operator-Governed Learning Curriculum and Capability Calibration Layer v1')}", "", report.get("message", "Learning curriculum report."), "", "## Learning objectives"]
    lines.append(f"- Starts work: {objective_map.get('starts_work', False)}")
    lines.append(f"- Autonomous loop started: {objective_map.get('autonomous_loop_started', False)}")
    for item in objective_map.get("objectives", LEARNING_OBJECTIVE_SEEDS)[:4]:
        lines.append(f"- {item.get('domain')}: {item.get('objective')} | evidence: {item.get('evidence_required')}")
    lines.extend(["", "## Practice task designs"])
    lines.append(f"- Executes tasks: {practice.get('executes_tasks', False)}")
    for item in practice.get("practice_tasks", PRACTICE_TASK_SEEDS)[:4]:
        lines.append(f"- {item.get('task')}: {item.get('target_skill')} | runs commands: {item.get('runs_commands', False)}")
    lines.extend(["", "## Capability calibration"])
    lines.append(f"- Promotion authorized: {calibration.get('promotion_authorized', False)}")
    for item in calibration.get("claims", CAPABILITY_CALIBRATION_CLAIMS)[:4]:
        lines.append(f"- {item.get('capability')}: claim={item.get('claim')} evidence={item.get('evidence_strength')} promoted={item.get('promotion_authorized', False)}")
    lines.extend(["", "## Skill gap remediation"])
    lines.append(f"- Continues into implementation: {remediation.get('continues_into_implementation', False)}")
    for item in remediation.get("gaps", SKILL_GAP_REMEDIATION_SEEDS)[:4]:
        lines.append(f"- {item.get('gap')}: {item.get('strategy')} | continues work: {item.get('continues_work', False)}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", LEARNING_CURRICULUM_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_learning_curriculum_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, learning_domain=None, capability_claim=None, save=True, **kwargs):
        return _build_learning_curriculum_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, learning_domain=learning_domain, capability_claim=capability_claim, save=save, **kwargs)
    return _builder


def _make_learning_curriculum_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, learning_domain=None, capability_claim=None, full=False, json_output=False, **kwargs):
        report = _build_learning_curriculum_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, learning_domain=learning_domain, capability_claim=capability_claim, save=False, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_learning_curriculum_text(report, full=full))
    return _printer


for _learning_curriculum_slug in LEARNING_CURRICULUM_STAGE_BY_SLUG:
    globals()[f"build_{_learning_curriculum_slug}"] = _make_learning_curriculum_build(_learning_curriculum_slug)
    globals()[f"{_learning_curriculum_slug}_text"] = _learning_curriculum_text
    globals()[f"print_{_learning_curriculum_slug}"] = _make_learning_curriculum_print(_learning_curriculum_slug)

