def _knowledge_organization_docs_text() -> str:
    chunks: list[str] = []
    for path in (ROOT_DIR / "README_NEXT_STEPS.md", ROOT_DIR / "README_RELEASE_HISTORY.md", ROOT_DIR / "conscious_agent" / "dashboard.py", ROOT_DIR / "conscious_agent" / "release_packaging.py"):
        try:
            chunks.append(path.read_text(encoding="utf-8"))
        except Exception:
            pass
    return "\n".join(chunks)


def _knowledge_organization_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["knowledge-claim-ledger", "belief-candidate-review", "contradiction-staleness-intelligence", "project-knowledge-map", "knowledge-organization-audit", "operator-governed-knowledge-and-belief-organization-layer-v1"]
    runtime_tokens = ["data/autonomy/knowledge_claim_ledger/", "data/autonomy/belief_candidate_review/", "data/autonomy/contradiction_staleness_intelligence/", "data/autonomy/project_knowledge_map/", "data/autonomy/knowledge_organization_audit/"]
    route_map = globals().get("SUPERVISED_RUNTIME_ROUTE_MAP", {})
    cli_map = globals().get("SUPERVISED_RUNTIME_CLI_MAP", {})
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "route-tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Knowledge/belief dashboard/API/CLI/docs tokens are present."},
        {"name": "runtime-privacy-tokens", "status": "pass" if all(token in docs for token in runtime_tokens) else "blocked", "message": "Runtime knowledge organization data remains source-only excluded."},
        {"name": "api-route-map", "status": "pass" if all(f"{item['api']}/{item['route']}" in route_map for item in KNOWLEDGE_ORGANIZATION_STAGE_DEFS) else "blocked", "message": "Dynamic API route map covers v230 stages."},
        {"name": "cli-map", "status": "pass" if all(item["slug"].replace("_", "-") in cli_map for item in KNOWLEDGE_ORGANIZATION_STAGE_DEFS) else "blocked", "message": "Dynamic CLI map covers v230 stages."},
        {"name": "claim-non-mutation", "status": "pass" if KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("claim_entries_mutate_memory") is False and KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("knowledge_map_mutates_source") is False else "blocked", "message": "Claim ledgers and maps cannot mutate memory or source."},
        {"name": "belief-non-authority", "status": "pass" if KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("belief_candidates_promote_truth") is False and KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("belief_state_authorizes_action") is False and KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("confidence_equals_truth") is False else "blocked", "message": "Belief candidates and confidence cannot become truth or authorization."},
        {"name": "contradiction-non-execution", "status": "pass" if KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("contradiction_reports_execute_work") is False else "blocked", "message": "Contradiction reports cannot execute fixes."},
        {"name": "no-hidden-research", "status": "pass" if KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("autonomous_research_loop_started") is False and KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("hidden_source_fetching_started") is False and KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("local_model_invoked_by_default") is False else "blocked", "message": "No autonomous research loop, hidden fetching, or default local model invocation."},
        {"name": "memory-identity-locked", "status": "pass" if KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("memory_mutation_performed") is False and KNOWLEDGE_ORGANIZATION_BOUNDARIES.get("identity_mutation_performed") is False else "blocked", "message": "Knowledge organization cannot mutate memory or identity."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_knowledge_organization_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, claim_text: str | None = None, belief_text: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = KNOWLEDGE_ORGANIZATION_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v230.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown knowledge organization stage: {slug}", "rows": []}
    docs = _knowledge_organization_docs_text()
    rows = _knowledge_organization_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v225.1-v230.0 Operator-Governed Knowledge and Belief Organization Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "claim_text": claim_text,
        "belief_text": belief_text,
        "knowledge_claim_ledger": {
            "claims": KNOWLEDGE_CLAIM_SEEDS,
            "entries_mutate_memory": False,
            "entries_mutate_source": False,
            "operator_review_required_for_promotion": True,
        },
        "belief_candidate_review": {
            "beliefs": BELIEF_CANDIDATE_SEEDS,
            "promotes_truth": False,
            "authorizes_action": False,
            "operator_review_required": True,
        },
        "contradiction_staleness_intelligence": {
            "events": CONTRADICTION_STALENESS_SEEDS,
            "executes_fixes": False,
            "starts_research_loop": False,
        },
        "project_knowledge_map": {
            "nodes": PROJECT_KNOWLEDGE_MAP_SEEDS,
            "mutates_source": False,
            "grants_authority": False,
        },
        "safe_next_action": "Operator may review knowledge claims, belief candidates, contradiction warnings, or map nodes and explicitly approve a separate follow-up packet if desired.",
        "blockers": blockers,
        "boundaries": KNOWLEDGE_ORGANIZATION_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v230.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = KNOWLEDGE_ORGANIZATION_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _knowledge_organization_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    ledger = payload.get("knowledge_claim_ledger", {})
    beliefs = payload.get("belief_candidate_review", {})
    contradictions = payload.get("contradiction_staleness_intelligence", {})
    project_map = payload.get("project_knowledge_map", {})
    lines = [f"# {payload.get('stage', 'v225.1-v230.0')} {payload.get('name', 'Operator-Governed Knowledge and Belief Organization Layer v1')}", "", report.get("message", "Knowledge organization report."), "", "## Knowledge claim ledger"]
    lines.append(f"- Entries mutate memory: {ledger.get('entries_mutate_memory', False)}")
    lines.append(f"- Entries mutate source: {ledger.get('entries_mutate_source', False)}")
    for item in ledger.get("claims", KNOWLEDGE_CLAIM_SEEDS)[:4]:
        lines.append(f"- {item.get('domain')}: {item.get('claim')} | confidence: {item.get('confidence')} | promoted: {item.get('promoted', False)}")
    lines.extend(["", "## Belief candidates"])
    lines.append(f"- Promotes truth: {beliefs.get('promotes_truth', False)}")
    lines.append(f"- Authorizes action: {beliefs.get('authorizes_action', False)}")
    for item in beliefs.get("beliefs", BELIEF_CANDIDATE_SEEDS)[:3]:
        lines.append(f"- {item.get('belief')} | confidence: {item.get('confidence')} | action authority: {item.get('authorizes_action', False)}")
    lines.extend(["", "## Contradiction and staleness intelligence"])
    lines.append(f"- Executes fixes: {contradictions.get('executes_fixes', False)}")
    for item in contradictions.get("events", CONTRADICTION_STALENESS_SEEDS)[:4]:
        lines.append(f"- {item.get('event')}: detector={item.get('detector')} severity={item.get('severity')} executes_fix={item.get('executes_fix', False)}")
    lines.extend(["", "## Project knowledge map"])
    lines.append(f"- Mutates source: {project_map.get('mutates_source', False)}")
    lines.append(f"- Grants authority: {project_map.get('grants_authority', False)}")
    for item in project_map.get("nodes", PROJECT_KNOWLEDGE_MAP_SEEDS)[:5]:
        lines.append(f"- {item.get('node')}: {item.get('authority')} | surfaces: {', '.join(item.get('surfaces', []))}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", KNOWLEDGE_ORGANIZATION_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_knowledge_organization_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, claim_text=None, belief_text=None, save=True, **kwargs):
        return _build_knowledge_organization_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, claim_text=claim_text, belief_text=belief_text, save=save, **kwargs)
    return _builder


def _make_knowledge_organization_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, claim_text=None, belief_text=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_knowledge_organization_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, claim_text=claim_text, belief_text=belief_text, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_knowledge_organization_text(report, full=full))
    return _printer


for _knowledge_slug in KNOWLEDGE_ORGANIZATION_STAGE_BY_SLUG:
    globals()[f"build_{_knowledge_slug}"] = _make_knowledge_organization_build(_knowledge_slug)
    globals()[f"print_{_knowledge_slug}"] = _make_knowledge_organization_print(_knowledge_slug)

