def _local_model_workbench_docs_text() -> str:
    chunks: list[str] = []
    for path in (ROOT_DIR / "README_NEXT_STEPS.md", ROOT_DIR / "README_RELEASE_HISTORY.md", ROOT_DIR / "conscious_agent" / "dashboard.py", ROOT_DIR / "conscious_agent" / "release_packaging.py", ROOT_DIR / "conscious_agent" / "api_server.py", ROOT_DIR / "conscious_agent" / "main.py"):
        try:
            chunks.append(path.read_text(encoding="utf-8"))
        except Exception:
            pass
    return "\n".join(chunks)


def _local_model_workbench_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["local-model-inventory", "model-evaluation-plan", "model-output-comparison", "cognitive-workbench-routing", "local-model-workbench-audit", "operator-governed-local-model-evaluation-and-cognitive-workbench-layer-v1"]
    runtime_tokens = ["data/autonomy/local_model_inventory/", "data/autonomy/model_evaluation_plan/", "data/autonomy/model_output_comparison/", "data/autonomy/cognitive_workbench_routing/", "data/autonomy/local_model_workbench_audit/"]
    route_map = globals().get("SUPERVISED_RUNTIME_ROUTE_MAP", {})
    cli_map = globals().get("SUPERVISED_RUNTIME_CLI_MAP", {})
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "route-tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Local model workbench dashboard/API/CLI/docs tokens are present."},
        {"name": "runtime-privacy-tokens", "status": "pass" if all(token in docs for token in runtime_tokens) else "blocked", "message": "Runtime model workbench data remains source-only excluded."},
        {"name": "api-route-map", "status": "pass" if all(f"{item['api']}/{item['route']}" in route_map for item in LOCAL_MODEL_WORKBENCH_STAGE_DEFS) else "blocked", "message": "Dynamic API route map covers v235 stages."},
        {"name": "cli-map", "status": "pass" if all(item["slug"].replace("_", "-") in cli_map for item in LOCAL_MODEL_WORKBENCH_STAGE_DEFS) else "blocked", "message": "Dynamic CLI map covers v235 stages."},
        {"name": "no-default-invocation", "status": "pass" if LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("local_model_invoked_by_default") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("hidden_model_calls_started") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("autonomous_evaluation_loop_started") is False else "blocked", "message": "No default local model invocation, hidden calls, or autonomous evaluation loops."},
        {"name": "evaluation-non-execution", "status": "pass" if LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("evaluation_plans_execute_models") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("inventory_profiles_invoke_models") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("workbench_routing_executes_models") is False else "blocked", "message": "Inventory, evaluation plans, and routing recommendations cannot execute model calls."},
        {"name": "model-output-non-authority", "status": "pass" if LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("model_output_promotes_truth") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("model_output_authorizes_action") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("model_recommendation_grants_approval") is False else "blocked", "message": "Model outputs and recommendations cannot become truth, action authority, or approval."},
        {"name": "no-self-upgrade-memory-identity", "status": "pass" if LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("self_upgrade_from_model_output") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("memory_mutation_from_model_output") is False and LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("identity_mutation_from_model_output") is False else "blocked", "message": "Model output cannot trigger self-upgrades, memory mutation, or identity mutation."},
        {"name": "no-roadmap-selection", "status": "pass" if LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("roadmap_selected_from_model_ranking") is False else "blocked", "message": "Model ranking cannot select roadmaps."},
        {"name": "operator-approval-required", "status": "pass" if LOCAL_MODEL_WORKBENCH_BOUNDARIES.get("operator_approval_required_for_invocation") is True else "blocked", "message": "Any model invocation requires explicit operator approval in a separate workflow."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_local_model_workbench_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, model_name: str | None = None, task_type: str | None = None, prompt_suite: list[str] | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = LOCAL_MODEL_WORKBENCH_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v235.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown local model workbench stage: {slug}", "rows": []}
    docs = _local_model_workbench_docs_text()
    rows = _local_model_workbench_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v230.1-v235.0 Operator-Governed Local Model Evaluation and Cognitive Workbench Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "model_name": model_name,
        "task_type": task_type,
        "prompt_suite": prompt_suite or [],
        "local_model_inventory": {"models": LOCAL_MODEL_INVENTORY_SEEDS, "invoked_by_default": False, "profiles_invoke_models": False},
        "model_evaluation_plan": {"plans": MODEL_EVALUATION_PLAN_SEEDS, "executes_models": False, "requires_operator_approval_before_run": True},
        "model_output_comparison": {"scoring_dimensions": MODEL_OUTPUT_COMPARISON_SEEDS, "promotes_truth": False, "authorizes_action": False, "mutates_memory": False},
        "cognitive_workbench_routing": {"routes": COGNITIVE_WORKBENCH_ROUTING_SEEDS, "executes_models": False, "human_review_required": True, "recommendation_grants_approval": False},
        "safe_next_action": "Operator may review local model inventory, evaluation plans, output comparison rules, or routing recommendations and separately approve an exact model invocation workflow if desired.",
        "blockers": blockers,
        "boundaries": LOCAL_MODEL_WORKBENCH_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v235.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = LOCAL_MODEL_WORKBENCH_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _local_model_workbench_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    inventory = payload.get("local_model_inventory", {})
    evaluation = payload.get("model_evaluation_plan", {})
    comparison = payload.get("model_output_comparison", {})
    routing = payload.get("cognitive_workbench_routing", {})
    lines = [f"# {payload.get('stage', 'v230.1-v235.0')} {payload.get('name', 'Operator-Governed Local Model Evaluation and Cognitive Workbench Layer v1')}", "", report.get("message", "Local model workbench report."), "", "## Local model inventory"]
    lines.append(f"- Invoked by default: {inventory.get('invoked_by_default', False)}")
    lines.append(f"- Profiles invoke models: {inventory.get('profiles_invoke_models', False)}")
    for item in inventory.get("models", LOCAL_MODEL_INVENTORY_SEEDS)[:4]:
        lines.append(f"- {item.get('model')}: runtime={item.get('runtime')} use={item.get('intended_use')} invoked={item.get('invoked', False)}")
    lines.extend(["", "## Evaluation plans"])
    lines.append(f"- Executes models: {evaluation.get('executes_models', False)}")
    lines.append(f"- Requires operator approval before run: {evaluation.get('requires_operator_approval_before_run', True)}")
    for item in evaluation.get("plans", MODEL_EVALUATION_PLAN_SEEDS)[:4]:
        lines.append(f"- {item.get('task')}: prompts={len(item.get('prompt_suite', []))} executes_model={item.get('executes_model', False)}")
    lines.extend(["", "## Output comparison and trust scoring"])
    lines.append(f"- Promotes truth: {comparison.get('promotes_truth', False)}")
    lines.append(f"- Authorizes action: {comparison.get('authorizes_action', False)}")
    for item in comparison.get("scoring_dimensions", MODEL_OUTPUT_COMPARISON_SEEDS)[:4]:
        lines.append(f"- {item.get('dimension')}: truth_authority={item.get('truth_authority', False)}")
    lines.extend(["", "## Cognitive workbench routing"])
    lines.append(f"- Executes models: {routing.get('executes_models', False)}")
    lines.append(f"- Recommendation grants approval: {routing.get('recommendation_grants_approval', False)}")
    for item in routing.get("routes", COGNITIVE_WORKBENCH_ROUTING_SEEDS)[:4]:
        lines.append(f"- {item.get('workflow')}: role={item.get('useful_model_role')} human_review_required={item.get('human_review_required', True)}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", LOCAL_MODEL_WORKBENCH_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_local_model_workbench_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, prompt_suite=None, save=True, **kwargs):
        return _build_local_model_workbench_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, prompt_suite=prompt_suite, save=save, **kwargs)
    return _builder


def _make_local_model_workbench_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, prompt_suite=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_local_model_workbench_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, prompt_suite=prompt_suite, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_local_model_workbench_text(report, full=full))
    return _printer


for _local_model_workbench_slug in LOCAL_MODEL_WORKBENCH_STAGE_BY_SLUG:
    globals()[f"build_{_local_model_workbench_slug}"] = _make_local_model_workbench_build(_local_model_workbench_slug)
    globals()[f"print_{_local_model_workbench_slug}"] = _make_local_model_workbench_print(_local_model_workbench_slug)

