def _local_model_invocation_sandbox_docs_text() -> str:
    chunks: list[str] = []
    for path in (ROOT_DIR / "README_NEXT_STEPS.md", ROOT_DIR / "README_RELEASE_HISTORY.md", ROOT_DIR / "conscious_agent" / "dashboard.py", ROOT_DIR / "conscious_agent" / "release_packaging.py", ROOT_DIR / "conscious_agent" / "api_server.py", ROOT_DIR / "conscious_agent" / "main.py"):
        try:
            chunks.append(path.read_text(encoding="utf-8"))
        except Exception:
            pass
    return "\n".join(chunks)


def _local_model_invocation_sandbox_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["local-model-invocation-consent", "model-evaluation-run-ledger", "multi-model-output-triage", "model-reliability-profile-candidates", "local-model-invocation-sandbox-audit", "operator-approved-local-model-invocation-sandbox-v1"]
    runtime_tokens = ["data/autonomy/local_model_invocation_consent/", "data/autonomy/model_evaluation_run_ledger/", "data/autonomy/multi_model_output_triage/", "data/autonomy/model_reliability_profile_candidates/", "data/autonomy/local_model_invocation_sandbox_audit/"]
    route_map = globals().get("SUPERVISED_RUNTIME_ROUTE_MAP", {})
    cli_map = globals().get("SUPERVISED_RUNTIME_CLI_MAP", {})
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "route-tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Local model invocation sandbox dashboard/API/CLI/docs tokens are present."},
        {"name": "runtime-privacy-tokens", "status": "pass" if all(token in docs for token in runtime_tokens) else "blocked", "message": "Runtime model invocation sandbox data remains source-only excluded."},
        {"name": "api-route-map", "status": "pass" if all(f"{item['api']}/{item['route']}" in route_map for item in LOCAL_MODEL_INVOCATION_SANDBOX_STAGE_DEFS) else "blocked", "message": "Dynamic API route map covers v240 stages."},
        {"name": "cli-map", "status": "pass" if all(item["slug"].replace("_", "-") in cli_map for item in LOCAL_MODEL_INVOCATION_SANDBOX_STAGE_DEFS) else "blocked", "message": "Dynamic CLI map covers v240 stages."},
        {"name": "no-default-invocation", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("model_invocation_by_default") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("hidden_model_calls_started") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("autonomous_evaluation_loop_started") is False else "blocked", "message": "No default local model invocation, hidden model calls, or autonomous evaluation loops."},
        {"name": "consent-gate", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("invocation_requires_scoped_operator_approval") is True and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("expired_consent_reusable") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("context_boundary_required") is True else "blocked", "message": "Scoped, non-reusable operator consent and context boundary are required before invocation."},
        {"name": "ledger-non-mutation", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("run_ledgers_mutate_source") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("run_ledgers_mutate_memory") is False else "blocked", "message": "Run ledgers record outputs without mutating source or memory."},
        {"name": "output-non-authority", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("run_outputs_promote_truth") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("run_outputs_authorize_action") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("triage_grants_approval") is False else "blocked", "message": "Model outputs and triage cannot become truth, action authority, or approval."},
        {"name": "no-source-release-mutation", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("run_outputs_apply_patches") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("run_outputs_publish_releases") is False else "blocked", "message": "Model outputs cannot apply patches or publish releases."},
        {"name": "no-self-promotion-memory-identity", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("reliability_candidates_self_promote") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("capability_promotion_from_model_output") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("memory_mutation_from_model_output") is False and LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("identity_mutation_from_model_output") is False else "blocked", "message": "Reliability candidates and model outputs cannot self-promote capabilities, mutate memory, or alter identity."},
        {"name": "no-roadmap-selection", "status": "pass" if LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES.get("roadmap_selected_from_model_ranking") is False else "blocked", "message": "Model rankings cannot select roadmaps."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_local_model_invocation_sandbox_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, model_name: str | None = None, task_type: str | None = None, prompt_suite: list[str] | None = None, consent_id: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = LOCAL_MODEL_INVOCATION_SANDBOX_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v240.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown local model invocation sandbox stage: {slug}", "rows": []}
    docs = _local_model_invocation_sandbox_docs_text()
    rows = _local_model_invocation_sandbox_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v235.1-v240.0 Operator-Approved Local Model Invocation Sandbox v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "model_name": model_name,
        "task_type": task_type,
        "prompt_suite": prompt_suite or [],
        "consent_id": consent_id,
        "invocation_consent": {"fields": INVOCATION_CONSENT_SEEDS, "requires_scoped_operator_approval": True, "expired_consent_reusable": False, "invokes_model_now": False},
        "evaluation_run_ledger": {"records": EVALUATION_RUN_LEDGER_SEEDS, "records_outputs_only": True, "mutates_source": False, "mutates_memory": False},
        "multi_model_output_triage": {"dimensions": MULTI_MODEL_TRIAGE_SEEDS, "grants_approval": False, "promotes_truth": False},
        "model_reliability_profile_candidates": {"candidates": MODEL_RELIABILITY_CANDIDATE_SEEDS, "self_promotes": False, "requires_operator_promotion": True},
        "safe_next_action": "Operator may review the invocation sandbox packet and separately approve an exact scoped local model run. This packet itself invokes no model and grants no authority.",
        "blockers": blockers,
        "boundaries": LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v240.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = LOCAL_MODEL_INVOCATION_SANDBOX_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _local_model_invocation_sandbox_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    consent = payload.get("invocation_consent", {})
    ledger = payload.get("evaluation_run_ledger", {})
    triage = payload.get("multi_model_output_triage", {})
    reliability = payload.get("model_reliability_profile_candidates", {})
    lines = [f"# {payload.get('stage', 'v235.1-v240.0')} {payload.get('name', 'Operator-Approved Local Model Invocation Sandbox v1')}", "", report.get("message", "Local model invocation sandbox report."), "", "## Invocation consent gate"]
    lines.append(f"- Requires scoped operator approval: {consent.get('requires_scoped_operator_approval', True)}")
    lines.append(f"- Expired consent reusable: {consent.get('expired_consent_reusable', False)}")
    lines.append(f"- Invokes model now: {consent.get('invokes_model_now', False)}")
    for item in consent.get("fields", INVOCATION_CONSENT_SEEDS)[:5]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')} reusable={item.get('reusable', False)}")
    lines.extend(["", "## Evaluation run ledger"])
    lines.append(f"- Records outputs only: {ledger.get('records_outputs_only', True)}")
    lines.append(f"- Mutates source: {ledger.get('mutates_source', False)}")
    lines.append(f"- Mutates memory: {ledger.get('mutates_memory', False)}")
    for item in ledger.get("records", EVALUATION_RUN_LEDGER_SEEDS)[:4]:
        lines.append(f"- {item.get('record')}: captures={', '.join(item.get('captures', []))}")
    lines.extend(["", "## Multi-model output triage"])
    lines.append(f"- Grants approval: {triage.get('grants_approval', False)}")
    lines.append(f"- Promotes truth: {triage.get('promotes_truth', False)}")
    for item in triage.get("dimensions", MULTI_MODEL_TRIAGE_SEEDS)[:4]:
        lines.append(f"- {item.get('dimension')}: {item.get('rule')} grants_approval={item.get('grants_approval', False)}")
    lines.extend(["", "## Reliability profile candidates"])
    lines.append(f"- Self-promotes: {reliability.get('self_promotes', False)}")
    lines.append(f"- Requires operator promotion: {reliability.get('requires_operator_promotion', True)}")
    for item in reliability.get("candidates", MODEL_RELIABILITY_CANDIDATE_SEEDS)[:4]:
        lines.append(f"- {item.get('candidate')}: evidence={item.get('evidence_required')} self_promotes={item.get('self_promotes', False)}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", LOCAL_MODEL_INVOCATION_SANDBOX_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_local_model_invocation_sandbox_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, prompt_suite=None, consent_id=None, save=True, **kwargs):
        return _build_local_model_invocation_sandbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, prompt_suite=prompt_suite, consent_id=consent_id, save=save, **kwargs)
    return _builder


def _make_local_model_invocation_sandbox_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, prompt_suite=None, consent_id=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_local_model_invocation_sandbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, prompt_suite=prompt_suite, consent_id=consent_id, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_local_model_invocation_sandbox_text(report, full=full))
    return _printer


for _local_model_invocation_sandbox_slug in LOCAL_MODEL_INVOCATION_SANDBOX_STAGE_BY_SLUG:
    globals()[f"build_{_local_model_invocation_sandbox_slug}"] = _make_local_model_invocation_sandbox_build(_local_model_invocation_sandbox_slug)
    globals()[f"print_{_local_model_invocation_sandbox_slug}"] = _make_local_model_invocation_sandbox_print(_local_model_invocation_sandbox_slug)

