def _model_assisted_patch_review_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _model_assisted_patch_review_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["model-assisted-patch-critique", "multi-model-review-synthesis", "patch-risk-remediation-synthesis", "model-review-quality-calibration", "model-assisted-patch-review-audit", "operator-governed-model-assisted-patch-review-and-synthesis-layer-v1"]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in MODEL_ASSISTED_PATCH_REVIEW_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, and smoke mention v245 model-assisted review surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in MODEL_ASSISTED_PATCH_REVIEW_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded review artifacts."},
        {"name": "no-model-authority", "status": "pass" if not any(MODEL_ASSISTED_PATCH_REVIEW_BOUNDARIES[key] for key in ["model_review_grants_approval", "model_output_treated_as_truth", "model_output_treated_as_proof", "patch_application_from_model_review", "source_mutation_from_model_review", "verification_commands_from_model_review", "release_created_from_model_review", "memory_mutation_from_model_review", "identity_mutation_from_model_review", "model_consensus_selects_roadmap"]) else "blocked", "message": "Model-assisted review remains advisory and cannot authorize action."},
        {"name": "operator-review", "status": "pass" if MODEL_ASSISTED_PATCH_REVIEW_BOUNDARIES["operator_review_required_for_actions"] else "blocked", "message": "Operator review remains required before any patch, verification, memory, identity, release, or roadmap action."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_model_assisted_patch_review_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, model_name: str | None = None, task_type: str | None = None, review_run_ids: list[str] | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = MODEL_ASSISTED_PATCH_REVIEW_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v245.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown model-assisted patch review stage: {slug}", "rows": []}
    docs = _model_assisted_patch_review_docs_text()
    rows = _model_assisted_patch_review_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v240.1-v245.0 Operator-Governed Model-Assisted Patch Review and Synthesis Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "model_name": model_name,
        "task_type": task_type,
        "review_run_ids": review_run_ids or [],
        "patch_critique_packet": {"fields": PATCH_CRITIQUE_PACKET_SEEDS, "requires_approved_model_run": True, "grants_approval": False, "applies_patch": False},
        "multi_model_review_synthesis": {"clusters": MULTI_MODEL_REVIEW_SYNTHESIS_SEEDS, "consensus_is_proof": False, "synthesis_grants_approval": False},
        "patch_risk_remediation_synthesis": {"items": PATCH_RISK_REMEDIATION_SEEDS, "executes_patch": False, "runs_verification": False},
        "model_review_quality_calibration": {"metrics": MODEL_REVIEW_QUALITY_SEEDS, "self_promotes_models": False, "expands_authority": False},
        "safe_next_action": "Operator may review the model-assisted patch review packet and separately approve any source edit, verification command, memory action, identity change, release action, or roadmap decision. This packet grants no authority.",
        "blockers": blockers,
        "boundaries": MODEL_ASSISTED_PATCH_REVIEW_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v245.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = MODEL_ASSISTED_PATCH_REVIEW_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _model_assisted_patch_review_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    critique = payload.get("patch_critique_packet", {})
    synthesis = payload.get("multi_model_review_synthesis", {})
    risk = payload.get("patch_risk_remediation_synthesis", {})
    quality = payload.get("model_review_quality_calibration", {})
    lines = [f"# {payload.get('stage', 'v240.1-v245.0')} {payload.get('name', 'Operator-Governed Model-Assisted Patch Review and Synthesis Layer v1')}", "", report.get("message", "Model-assisted patch review report."), "", "## Critique packet"]
    lines.append(f"- Requires approved model run: {critique.get('requires_approved_model_run', True)}")
    lines.append(f"- Grants approval: {critique.get('grants_approval', False)}")
    lines.append(f"- Applies patch: {critique.get('applies_patch', False)}")
    for item in critique.get("fields", PATCH_CRITIQUE_PACKET_SEEDS)[:5]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Multi-model review synthesis"])
    lines.append(f"- Consensus is proof: {synthesis.get('consensus_is_proof', False)}")
    lines.append(f"- Synthesis grants approval: {synthesis.get('synthesis_grants_approval', False)}")
    for item in synthesis.get("clusters", MULTI_MODEL_REVIEW_SYNTHESIS_SEEDS)[:4]:
        lines.append(f"- {item.get('cluster')}: {item.get('purpose')}")
    lines.extend(["", "## Risk and remediation synthesis"])
    lines.append(f"- Executes patch: {risk.get('executes_patch', False)}")
    lines.append(f"- Runs verification: {risk.get('runs_verification', False)}")
    for item in risk.get("items", PATCH_RISK_REMEDIATION_SEEDS)[:4]:
        lines.append(f"- {item.get('risk')}: {item.get('remediation')}")
    lines.extend(["", "## Review quality calibration"])
    lines.append(f"- Self-promotes models: {quality.get('self_promotes_models', False)}")
    lines.append(f"- Expands authority: {quality.get('expands_authority', False)}")
    for item in quality.get("metrics", MODEL_REVIEW_QUALITY_SEEDS)[:4]:
        lines.append(f"- {item.get('metric')}: {item.get('meaning')} self_promotes_model={item.get('self_promotes_model', False)}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", MODEL_ASSISTED_PATCH_REVIEW_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_model_assisted_patch_review_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, review_run_ids=None, save=True, **kwargs):
        return _build_model_assisted_patch_review_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, review_run_ids=review_run_ids, save=save, **kwargs)
    return _builder


def _make_model_assisted_patch_review_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, review_run_ids=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_model_assisted_patch_review_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, review_run_ids=review_run_ids, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_model_assisted_patch_review_text(report, full=full))
    return _printer


for _model_assisted_patch_review_slug in MODEL_ASSISTED_PATCH_REVIEW_STAGE_BY_SLUG:
    globals()[f"build_{_model_assisted_patch_review_slug}"] = _make_model_assisted_patch_review_build(_model_assisted_patch_review_slug)
    globals()[f"print_{_model_assisted_patch_review_slug}"] = _make_model_assisted_patch_review_print(_model_assisted_patch_review_slug)

