def _model_assisted_patch_draft_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _model_assisted_patch_draft_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["model-assisted-patch-draft", "file-impact-documentation-planner", "smoke-verification-suggestions", "sandbox-preparation-packet", "patch-draft-assembly-audit", "operator-governed-model-assisted-patch-draft-assembly-layer-v1"]
    forbidden_truth = ["model_output_treated_as_correctness_proof", "model_consensus_infers_approval", "draft_packets_write_files", "draft_packets_apply_patches", "draft_packets_run_commands", "draft_packets_approve_implementation", "file_impact_plans_execute_work", "documentation_updates_applied_automatically", "verification_suggestions_execute", "sandbox_packets_execute", "source_mutation_from_draft", "memory_mutation_from_draft", "identity_mutation_from_draft", "release_candidate_created_from_draft", "continuation_after_draft_assembly", "stale_or_out_of_scope_consent_reused"]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in MODEL_ASSISTED_PATCH_DRAFT_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, and smoke mention v250 model-assisted draft assembly surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in MODEL_ASSISTED_PATCH_DRAFT_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded draft assembly artifacts."},
        {"name": "no-draft-authority", "status": "pass" if not any(MODEL_ASSISTED_PATCH_DRAFT_BOUNDARIES[key] for key in forbidden_truth) else "blocked", "message": "Draft assembly remains review-only and cannot mutate, execute, approve, or continue work."},
        {"name": "operator-approval", "status": "pass" if MODEL_ASSISTED_PATCH_DRAFT_BOUNDARIES["operator_approval_required_for_execution"] else "blocked", "message": "Explicit operator approval remains required for any implementation, verification, sandbox, release, memory, or identity action."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_model_assisted_patch_draft_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, model_name: str | None = None, task_type: str | None = None, review_run_ids: list[str] | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = MODEL_ASSISTED_PATCH_DRAFT_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v250.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown model-assisted patch draft stage: {slug}", "rows": []}
    docs = _model_assisted_patch_draft_docs_text()
    rows = _model_assisted_patch_draft_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v245.1-v250.0 Operator-Governed Model-Assisted Patch Draft Assembly Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "model_name": model_name,
        "task_type": task_type,
        "review_run_ids": review_run_ids or [],
        "patch_draft_packet": {"fields": PATCH_DRAFT_PACKET_SEEDS, "writes_files": False, "applies_patch": False, "grants_approval": False},
        "file_impact_documentation_planner": {"items": FILE_IMPACT_DOCUMENTATION_SEEDS, "executes_changes": False, "updates_docs_automatically": False},
        "smoke_verification_suggestions": {"items": SMOKE_VERIFICATION_SUGGESTION_SEEDS, "runs_commands": False, "suggestions_are_approval": False},
        "sandbox_preparation_packet": {"items": SANDBOX_PREPARATION_SEEDS, "executes_sandbox": False, "requires_separate_approval": True},
        "safe_next_action": "Operator may review the model-assisted patch draft assembly packet and separately approve a specific sandbox or source execution packet. This packet grants no authority and writes no files.",
        "blockers": blockers,
        "boundaries": MODEL_ASSISTED_PATCH_DRAFT_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v250.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = MODEL_ASSISTED_PATCH_DRAFT_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _model_assisted_patch_draft_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    draft = payload.get("patch_draft_packet", {})
    impact = payload.get("file_impact_documentation_planner", {})
    verify = payload.get("smoke_verification_suggestions", {})
    sandbox = payload.get("sandbox_preparation_packet", {})
    lines = [f"# {payload.get('stage', 'v245.1-v250.0')} {payload.get('name', 'Operator-Governed Model-Assisted Patch Draft Assembly Layer v1')}", "", report.get("message", "Model-assisted patch draft assembly report."), "", "## Patch draft packet"]
    lines.append(f"- Writes files: {draft.get('writes_files', False)}")
    lines.append(f"- Applies patch: {draft.get('applies_patch', False)}")
    lines.append(f"- Grants approval: {draft.get('grants_approval', False)}")
    for item in draft.get("fields", PATCH_DRAFT_PACKET_SEEDS)[:5]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## File impact and documentation planner"])
    lines.append(f"- Executes changes: {impact.get('executes_changes', False)}")
    lines.append(f"- Updates docs automatically: {impact.get('updates_docs_automatically', False)}")
    for item in impact.get("items", FILE_IMPACT_DOCUMENTATION_SEEDS)[:4]:
        lines.append(f"- {item.get('surface')}: {item.get('requirement')}")
    lines.extend(["", "## Smoke and verification suggestions"])
    lines.append(f"- Runs commands: {verify.get('runs_commands', False)}")
    lines.append(f"- Suggestions are approval: {verify.get('suggestions_are_approval', False)}")
    for item in verify.get("items", SMOKE_VERIFICATION_SUGGESTION_SEEDS)[:4]:
        lines.append(f"- {item.get('check')}: {item.get('purpose')}")
    lines.extend(["", "## Sandbox preparation packet"])
    lines.append(f"- Executes sandbox: {sandbox.get('executes_sandbox', False)}")
    lines.append(f"- Requires separate approval: {sandbox.get('requires_separate_approval', True)}")
    for item in sandbox.get("items", SANDBOX_PREPARATION_SEEDS)[:4]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", MODEL_ASSISTED_PATCH_DRAFT_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_model_assisted_patch_draft_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, review_run_ids=None, save=True, **kwargs):
        return _build_model_assisted_patch_draft_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, review_run_ids=review_run_ids, save=save, **kwargs)
    return _builder


def _make_model_assisted_patch_draft_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, model_name=None, task_type=None, review_run_ids=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_model_assisted_patch_draft_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, model_name=model_name, task_type=task_type, review_run_ids=review_run_ids, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_model_assisted_patch_draft_text(report, full=full))
    return _printer


for _model_assisted_patch_draft_slug in MODEL_ASSISTED_PATCH_DRAFT_STAGE_BY_SLUG:
    globals()[f"build_{_model_assisted_patch_draft_slug}"] = _make_model_assisted_patch_draft_build(_model_assisted_patch_draft_slug)
    globals()[f"print_{_model_assisted_patch_draft_slug}"] = _make_model_assisted_patch_draft_print(_model_assisted_patch_draft_slug)

