def _patch_execution_packet_bridge_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _patch_execution_packet_bridge_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["draft-to-execution-packet", "patch-diff-preview-planner", "execution-approval-scope", "verification-rollback-packet", "patch-execution-packet-audit", "operator-governed-patch-execution-packet-bridge-v1"]
    forbidden_false = [
        "execution_packets_write_files", "execution_packets_apply_patches", "execution_packets_run_commands", "execution_packets_execute_sandboxes", "execution_packets_publish_releases", "execution_packets_mutate_memory", "execution_packets_alter_identity", "execution_packets_invoke_models_by_default", "execution_packets_self_approve", "approval_inferred_from_packet_readiness", "approval_inferred_from_model_output", "approval_inferred_from_model_consensus", "stale_or_vague_consent_reused", "diff_previews_mutate_source", "verification_packets_execute_commands", "rollback_packets_alter_files", "release_candidate_created_from_packet", "continuation_after_packet_assembly",
    ]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in PATCH_EXECUTION_PACKET_BRIDGE_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, and smoke mention v255 patch execution packet bridge surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in PATCH_EXECUTION_PACKET_BRIDGE_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded packet bridge artifacts."},
        {"name": "no-packet-authority", "status": "pass" if not any(PATCH_EXECUTION_PACKET_BRIDGE_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Execution packets remain review-only and cannot mutate, execute, approve, invoke, publish, or continue work."},
        {"name": "operator-approval", "status": "pass" if PATCH_EXECUTION_PACKET_BRIDGE_BOUNDARIES["operator_approval_required_for_execution"] and PATCH_EXECUTION_PACKET_BRIDGE_BOUNDARIES["approval_scope_must_be_fresh_and_exact"] else "blocked", "message": "Explicit, fresh, exact operator approval remains required for any execution."},
        {"name": "verification-rollback-plan-only", "status": "pass" if PATCH_EXECUTION_PACKET_BRIDGE_BOUNDARIES["verification_and_rollback_are_plans_only"] else "blocked", "message": "Verification and rollback packets are plans only."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_patch_execution_packet_bridge_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = PATCH_EXECUTION_PACKET_BRIDGE_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v255.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown patch execution packet bridge stage: {slug}", "rows": []}
    docs = _patch_execution_packet_bridge_docs_text()
    rows = _patch_execution_packet_bridge_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v250.1-v255.0 Operator-Governed Patch Execution Packet Bridge v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "execution_packet": {"fields": EXECUTION_PACKET_SCHEMA_SEEDS, "default_state": "blocked_pending_operator_approval", "writes_files": False, "applies_patch": False, "grants_approval": False},
        "diff_preview_plan": {"items": DIFF_PREVIEW_PLAN_SEEDS, "mutates_source": False, "updates_docs": False, "creates_release_candidate": False},
        "approval_scope_ledger": {"items": APPROVAL_SCOPE_LEDGER_SEEDS, "self_approves": False, "requires_fresh_exact_scope": True, "non_approval_phrases_remain_non_approval": True},
        "verification_rollback_packet": {"items": VERIFICATION_ROLLBACK_PACKET_SEEDS, "runs_commands": False, "alters_files": False, "requires_separate_approval": True},
        "safe_next_action": "Operator may review the approval-ready execution packet bridge and separately approve a specific sandbox/source/verification action. This packet grants no authority and performs no execution.",
        "blockers": blockers,
        "boundaries": PATCH_EXECUTION_PACKET_BRIDGE_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v255.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = PATCH_EXECUTION_PACKET_BRIDGE_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _patch_execution_packet_bridge_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    execution = payload.get("execution_packet", {})
    diff = payload.get("diff_preview_plan", {})
    approval = payload.get("approval_scope_ledger", {})
    verification = payload.get("verification_rollback_packet", {})
    lines = [f"# {payload.get('stage', 'v250.1-v255.0')} {payload.get('name', 'Operator-Governed Patch Execution Packet Bridge v1')}", "", report.get("message", "Patch execution packet bridge report."), "", "## Execution packet"]
    lines.append(f"- Default state: {execution.get('default_state', 'blocked_pending_operator_approval')}")
    lines.append(f"- Writes files: {execution.get('writes_files', False)}")
    lines.append(f"- Applies patch: {execution.get('applies_patch', False)}")
    lines.append(f"- Grants approval: {execution.get('grants_approval', False)}")
    for item in execution.get("fields", EXECUTION_PACKET_SCHEMA_SEEDS)[:4]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Diff preview plan"])
    lines.append(f"- Mutates source: {diff.get('mutates_source', False)}")
    lines.append(f"- Updates docs: {diff.get('updates_docs', False)}")
    lines.append(f"- Creates release candidate: {diff.get('creates_release_candidate', False)}")
    for item in diff.get("items", DIFF_PREVIEW_PLAN_SEEDS)[:4]:
        lines.append(f"- {item.get('surface')}: {item.get('requirement')}")
    lines.extend(["", "## Approval scope ledger"])
    lines.append(f"- Self-approves: {approval.get('self_approves', False)}")
    lines.append(f"- Requires fresh exact scope: {approval.get('requires_fresh_exact_scope', True)}")
    for item in approval.get("items", APPROVAL_SCOPE_LEDGER_SEEDS)[:4]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Verification and rollback packet"])
    lines.append(f"- Runs commands: {verification.get('runs_commands', False)}")
    lines.append(f"- Alters files: {verification.get('alters_files', False)}")
    lines.append(f"- Requires separate approval: {verification.get('requires_separate_approval', True)}")
    for item in verification.get("items", VERIFICATION_ROLLBACK_PACKET_SEEDS)[:4]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", PATCH_EXECUTION_PACKET_BRIDGE_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_patch_execution_packet_bridge_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, save=True, **kwargs):
        return _build_patch_execution_packet_bridge_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
    return _builder


def _make_patch_execution_packet_bridge_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_patch_execution_packet_bridge_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_patch_execution_packet_bridge_text(report, full=full))
    return _printer


for _patch_execution_packet_bridge_slug in PATCH_EXECUTION_PACKET_BRIDGE_STAGE_BY_SLUG:
    globals()[f"build_{_patch_execution_packet_bridge_slug}"] = _make_patch_execution_packet_bridge_build(_patch_execution_packet_bridge_slug)
    globals()[f"print_{_patch_execution_packet_bridge_slug}"] = _make_patch_execution_packet_bridge_print(_patch_execution_packet_bridge_slug)

