APPROVED_APPLICATION_PREP_STAGE_DEFS: list[dict[str, Any]] = []
for _arc in APPROVED_APPLICATION_PREP_ARCS:
    for _item in _arc["items"]:
        APPROVED_APPLICATION_PREP_STAGE_DEFS.append({
            "version": _item[0],
            "slug": _item[1],
            "label": _item[2],
            "focus": _item[3],
            "route": _item[4],
            "is_final": bool(_item[5]) if len(_item) > 5 else False,
            "final_label": _arc["final_label"],
            "api": _arc["api"],
            "dashboard": _arc["dashboard"],
            "runtime_key": _arc["runtime_key"],
            "theme": _arc["theme"],
            "stage": f"{_arc['version']} { _arc['final_label']}",
        })
APPROVED_APPLICATION_PREP_STAGE_BY_SLUG = {item["slug"]: item for item in APPROVED_APPLICATION_PREP_STAGE_DEFS}
APPROVED_APPLICATION_PREP_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in APPROVED_APPLICATION_PREP_STAGE_DEFS}
APPROVED_APPLICATION_PREP_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in APPROVED_APPLICATION_PREP_STAGE_DEFS}
APPROVED_APPLICATION_PREP_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in APPROVED_APPLICATION_PREP_STAGE_DEFS})


def _approved_application_prep_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _approved_application_prep_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["application-prep-intake", "source-edit-application-plan", "documentation-application-plan", "final-application-governance-gate", "application-prep-integration-audit", "operator-governed-approved-execution-packet-application-prep-v1"]
    forbidden_false = [
        "application_prep_writes_files", "application_prep_applies_source_edits", "application_prep_runs_commands", "application_prep_executes_sandboxes", "application_prep_publishes_releases", "application_prep_mutates_memory", "application_prep_alters_identity", "application_prep_invokes_models_by_default", "application_prep_self_approves", "application_prep_inferrs_approval_from_readiness", "application_prep_reuses_stale_consent", "source_edit_plans_mutate_source", "documentation_plans_update_docs_automatically", "final_gate_grants_authority", "verification_plans_execute_commands", "rollback_plans_alter_files", "release_candidate_created_from_application_prep", "continuation_after_application_prep",
    ]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in APPROVED_APPLICATION_PREP_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, and smoke mention v260 application prep surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in APPROVED_APPLICATION_PREP_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded application prep artifacts."},
        {"name": "no-application-authority", "status": "pass" if not any(APPROVED_APPLICATION_PREP_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Application prep remains review-only and cannot mutate, execute, approve, invoke, publish, or continue work."},
        {"name": "operator-approval", "status": "pass" if APPROVED_APPLICATION_PREP_BOUNDARIES["operator_approval_required_for_application"] and APPROVED_APPLICATION_PREP_BOUNDARIES["approval_scope_must_match_packet_exactly"] else "blocked", "message": "Explicit, exact operator approval remains required before application."},
        {"name": "documentation-obligation", "status": "pass" if APPROVED_APPLICATION_PREP_BOUNDARIES["documentation_updates_required_for_code_changes"] else "blocked", "message": "README and release-history planning remains required for code changes."},
        {"name": "tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips on nav tabs; custom data-tip hover remains active."},
    ]
    return rows


def _build_approved_application_prep_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = APPROVED_APPLICATION_PREP_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v260.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown approved application prep stage: {slug}", "rows": []}
    docs = _approved_application_prep_docs_text()
    rows = _approved_application_prep_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v255.1-v260.0 Operator-Governed Approved Execution Packet Application Prep v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "application_prep_intake": {"items": APPLICATION_PREP_INTAKE_SEEDS, "default_state": "ready_but_not_authorized_or_blocked_pending_review", "writes_files": False, "applies_edits": False, "grants_approval": False},
        "source_edit_application_plan": {"items": SOURCE_EDIT_APPLICATION_PLAN_SEEDS, "mutates_source": False, "applies_edits": False, "requires_later_explicit_application_approval": True},
        "documentation_application_plan": {"items": DOCUMENTATION_APPLICATION_PLAN_SEEDS, "updates_docs": False, "required_for_code_changes": True, "missing_docs_block_readiness": True},
        "final_application_governance_gate": {"items": FINAL_APPLICATION_GATE_SEEDS, "grants_authority": False, "readiness_is_not_authorization": True, "requires_fresh_exact_scope": True},
        "application_prep_integration_audit": {"items": APPLICATION_PREP_AUDIT_SEEDS, "executes_work": False, "continues_automatically": False, "model_output_is_not_proof": True},
        "safe_next_action": "Operator may review the application-prep packet and separately approve a specific source application workflow. This packet grants no authority, writes no files, and runs no commands.",
        "blockers": blockers,
        "boundaries": APPROVED_APPLICATION_PREP_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v260.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = APPROVED_APPLICATION_PREP_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _approved_application_prep_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    intake = payload.get("application_prep_intake", {})
    source = payload.get("source_edit_application_plan", {})
    docs = payload.get("documentation_application_plan", {})
    gate = payload.get("final_application_governance_gate", {})
    audit = payload.get("application_prep_integration_audit", {})
    lines = [f"# {payload.get('stage', 'v255.1-v260.0')} {payload.get('name', 'Operator-Governed Approved Execution Packet Application Prep v1')}", "", report.get("message", "Approved application prep report."), "", "## Application prep intake"]
    lines.append(f"- Default state: {intake.get('default_state', 'ready_but_not_authorized_or_blocked_pending_review')}")
    lines.append(f"- Writes files: {intake.get('writes_files', False)}")
    lines.append(f"- Applies edits: {intake.get('applies_edits', False)}")
    lines.append(f"- Grants approval: {intake.get('grants_approval', False)}")
    for item in intake.get("items", APPLICATION_PREP_INTAKE_SEEDS)[:4]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Source edit application plan"])
    lines.append(f"- Mutates source: {source.get('mutates_source', False)}")
    lines.append(f"- Applies edits: {source.get('applies_edits', False)}")
    for item in source.get("items", SOURCE_EDIT_APPLICATION_PLAN_SEEDS)[:4]:
        lines.append(f"- {item.get('surface')}: {item.get('requirement')}")
    lines.extend(["", "## Documentation and release metadata plan"])
    lines.append(f"- Updates docs: {docs.get('updates_docs', False)}")
    lines.append(f"- Required for code changes: {docs.get('required_for_code_changes', True)}")
    for item in docs.get("items", DOCUMENTATION_APPLICATION_PLAN_SEEDS)[:4]:
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Final application governance gate"])
    lines.append(f"- Grants authority: {gate.get('grants_authority', False)}")
    lines.append(f"- Readiness is authorization: {not gate.get('readiness_is_not_authorization', True)}")
    for item in gate.get("items", FINAL_APPLICATION_GATE_SEEDS)[:4]:
        lines.append(f"- {item.get('gate')}: {item.get('requirement')}")
    lines.extend(["", "## Integration audit"])
    lines.append(f"- Executes work: {audit.get('executes_work', False)}")
    lines.append(f"- Continues automatically: {audit.get('continues_automatically', False)}")
    for item in audit.get("items", APPLICATION_PREP_AUDIT_SEEDS)[:4]:
        lines.append(f"- {item.get('audit')}: {item.get('requirement')}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", APPROVED_APPLICATION_PREP_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_approved_application_prep_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, save=True, **kwargs):
        return _build_approved_application_prep_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
    return _builder


def _make_approved_application_prep_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_approved_application_prep_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_approved_application_prep_text(report, full=full))
    return _printer


for _approved_application_prep_slug in APPROVED_APPLICATION_PREP_STAGE_BY_SLUG:
    globals()[f"build_{_approved_application_prep_slug}"] = _make_approved_application_prep_build(_approved_application_prep_slug)
    globals()[f"print_{_approved_application_prep_slug}"] = _make_approved_application_prep_print(_approved_application_prep_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(APPROVED_APPLICATION_PREP_STAGE_DEFS)
SUPERVISED_RUNTIME_STAGE_BY_SLUG.update(APPROVED_APPLICATION_PREP_STAGE_BY_SLUG)
SUPERVISED_RUNTIME_CLI_MAP.update(APPROVED_APPLICATION_PREP_CLI_MAP)
SUPERVISED_RUNTIME_ROUTE_MAP.update(APPROVED_APPLICATION_PREP_ROUTE_MAP)

