def _structural_stabilization_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _structural_stabilization_file_inventory() -> list[dict[str, Any]]:
    tracked = ["conscious_agent/self_maintenance.py", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "tools/smoke_check.py", "conscious_agent/release_packaging.py"]
    rows: list[dict[str, Any]] = []
    for rel in tracked:
        path = ROOT_DIR / rel
        if not path.exists():
            rows.append({"file": rel, "exists": False, "bytes": 0, "lines": 0, "risk": "missing"})
            continue
        text = path.read_text(encoding="utf-8", errors="ignore")
        lines = text.count("\n") + 1
        size = len(text.encode("utf-8"))
        risk = "high" if lines > 20000 else "medium" if lines > 5000 else "watch" if lines > 1500 else "low"
        rows.append({"file": rel, "exists": True, "bytes": size, "lines": lines, "risk": risk})
    return rows


def _structural_stabilization_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["structural-inventory", "runtime-registry-prep", "dashboard-stabilization-audit", "dispatch-stabilization", "structural-stabilization-audit", "operator-governed-structural-stabilization-and-runtime-modularization-v1"]
    forbidden_false = [
        "structural_stabilization_writes_files", "structural_stabilization_applies_refactors", "structural_stabilization_rewrites_architecture", "structural_stabilization_removes_routes", "structural_stabilization_runs_commands", "structural_stabilization_invokes_models_by_default", "structural_stabilization_inferrs_approval_from_audit", "structural_stabilization_self_approves", "structural_stabilization_mutates_memory", "structural_stabilization_alters_identity", "structural_stabilization_publishes_release_candidates", "structural_stabilization_continues_automatically", "registry_prep_changes_dispatch", "dashboard_stabilization_changes_layout_contract", "dispatch_stabilization_executes_commands", "refactor_readiness_applies_refactor",
    ]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in STRUCTURAL_STABILIZATION_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, and smoke mention v265 structural stabilization surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in STRUCTURAL_STABILIZATION_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded structural stabilization artifacts."},
        {"name": "no-refactor-authority", "status": "pass" if not any(STRUCTURAL_STABILIZATION_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Structural stabilization remains review-only and cannot refactor, rewrite, execute, remove routes, publish, mutate, or continue work."},
        {"name": "operator-approval", "status": "pass" if STRUCTURAL_STABILIZATION_BOUNDARIES["operator_approval_required_for_refactor"] and STRUCTURAL_STABILIZATION_BOUNDARIES["runtime_registry_is_plan_only"] else "blocked", "message": "Explicit operator approval remains required before any modular extraction or refactor."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if STRUCTURAL_STABILIZATION_BOUNDARIES["dashboard_data_tip_required"] and STRUCTURAL_STABILIZATION_BOUNDARIES["native_nav_title_tooltips_forbidden"] else "blocked", "message": "Dashboard stabilization preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if STRUCTURAL_STABILIZATION_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]
    return rows


def _build_structural_stabilization_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = STRUCTURAL_STABILIZATION_STAGE_BY_SLUG.get(slug)
    if not definition:
        raise ValueError(f"Unknown structural stabilization stage: {slug}")
    docs = _structural_stabilization_docs_text()
    rows = _structural_stabilization_status_rows(definition, docs)
    ok = all(row.get("status") == "pass" for row in rows)
    blockers = [row for row in rows if row.get("status") != "pass"]
    inventory = _structural_stabilization_file_inventory()
    payload = {
        "name": definition["label"],
        "stage": definition["stage"],
        "arc": "v260.1-v265.0 Operator-Governed Structural Stabilization and Runtime Modularization v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "central_file_inventory": inventory,
        "structural_inventory": {"items": STRUCTURAL_INVENTORY_SEEDS, "observational_only": True, "applies_refactor": False, "changes_behavior": False},
        "runtime_registry_prep": {"items": RUNTIME_REGISTRY_PREP_SEEDS, "plan_only": True, "changes_dispatch": False, "replaces_runtime": False},
        "dashboard_stabilization": {"items": DASHBOARD_STABILIZATION_SEEDS, "preserve_data_tip": True, "native_nav_title_tooltips_forbidden": True, "changes_layout_contract": False},
        "dispatch_stabilization": {"items": DISPATCH_STABILIZATION_SEEDS, "executes_commands": False, "changes_dispatch": False, "auto_fixes": False},
        "structural_stabilization_audit": {"items": STRUCTURAL_STABILIZATION_AUDIT_SEEDS, "applies_refactor": False, "authorizes_refactor": False, "publishes_release": False},
        "safe_next_action": "Operator may review structural inventories, registry prep, dashboard stabilization, dispatch consolidation prep, and refactor risks. This packet grants no refactor authority, writes no files, and runs no commands.",
        "blockers": blockers,
        "boundaries": STRUCTURAL_STABILIZATION_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v265.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = STRUCTURAL_STABILIZATION_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _structural_stabilization_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    lines = [f"# {payload.get('stage', 'v260.1-v265.0')} {payload.get('name', 'Structural Stabilization')}", "", report.get("message", "Structural stabilization report."), "", "## Central file inventory"]
    for item in payload.get("central_file_inventory", []):
        lines.append(f"- {item.get('file')}: {item.get('lines')} lines, {item.get('bytes')} bytes, risk={item.get('risk')}")
    lines.extend(["", "## Structural inventory"])
    for item in payload.get("structural_inventory", {}).get("items", STRUCTURAL_INVENTORY_SEEDS):
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Runtime registry prep"])
    reg = payload.get("runtime_registry_prep", {})
    lines.append(f"- Plan only: {reg.get('plan_only', True)}")
    lines.append(f"- Changes dispatch: {reg.get('changes_dispatch', False)}")
    for item in reg.get("items", RUNTIME_REGISTRY_PREP_SEEDS):
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Dashboard stabilization"])
    dash = payload.get("dashboard_stabilization", {})
    lines.append(f"- Preserve data-tip: {dash.get('preserve_data_tip', True)}")
    lines.append(f"- Native nav title tooltips forbidden: {dash.get('native_nav_title_tooltips_forbidden', True)}")
    for item in dash.get("items", DASHBOARD_STABILIZATION_SEEDS):
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Dispatch stabilization"])
    disp = payload.get("dispatch_stabilization", {})
    lines.append(f"- Executes commands: {disp.get('executes_commands', False)}")
    lines.append(f"- Changes dispatch: {disp.get('changes_dispatch', False)}")
    for item in disp.get("items", DISPATCH_STABILIZATION_SEEDS):
        lines.append(f"- {item.get('field')}: {item.get('requirement')}")
    lines.extend(["", "## Checks"])
    for row in report.get("rows", []):
        lines.append(f"- {row.get('status','unknown').upper()} {row.get('name','check')}: {row.get('message','')}")
    lines.extend(["", "## Boundaries"])
    for key, value in payload.get("boundaries", STRUCTURAL_STABILIZATION_BOUNDARIES).items():
        lines.append(f"- {key}: {value}")
    if full:
        lines.extend(["", "## Payload", json.dumps(payload, indent=2)])
    return "\n".join(lines)


def _make_structural_stabilization_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, save=True, **kwargs):
        return _build_structural_stabilization_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, save=save, **kwargs)
    return _builder


def _make_structural_stabilization_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_structural_stabilization_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_structural_stabilization_text(report, full=full))
    return _printer


for _structural_stabilization_slug in STRUCTURAL_STABILIZATION_STAGE_BY_SLUG:
    globals()[f"build_{_structural_stabilization_slug}"] = _make_structural_stabilization_build(_structural_stabilization_slug)
    globals()[f"print_{_structural_stabilization_slug}"] = _make_structural_stabilization_print(_structural_stabilization_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(STRUCTURAL_STABILIZATION_STAGE_DEFS)
