def _module_extraction_docs_text() -> str:
    parts = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/runtime_registry.py", "conscious_agent/governance_reports.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _module_extraction_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = ["runtime-registry", "governance-report-builder-audit", "dashboard-registry-integration", "runtime-dispatch-registry-audit", "module-extraction-audit", "operator-governed-runtime-module-extraction-v1", "runtime_registry.py", "governance_reports.py"]
    forbidden_false = [
        "module_extraction_writes_files_automatically", "module_extraction_removes_routes", "module_extraction_changes_dashboard_behavior", "module_extraction_rewrites_architecture_aggressively", "module_extraction_inferrs_approval_from_success", "module_extraction_invokes_models_by_default", "module_extraction_runs_verification_automatically", "module_extraction_self_approves", "module_extraction_mutates_memory", "module_extraction_alters_identity", "module_extraction_publishes_releases", "module_extraction_continues_automatically",
    ]
    registry = module_extraction_registry_summary()
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in MODULE_EXTRACTION_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, smoke, and extracted modules mention v270 module extraction surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in MODULE_EXTRACTION_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded module extraction artifacts."},
        {"name": "registry-stage-count", "status": "pass" if registry.get("stage_count") == len(MODULE_EXTRACTION_STAGE_DEFS) == 50 else "blocked", "message": f"{registry.get('stage_count')} registry stage(s) defined."},
        {"name": "no-extraction-authority", "status": "pass" if not any(MODULE_EXTRACTION_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Module extraction remains operator-governed and cannot execute, approve, publish, mutate, remove routes, or continue work."},
        {"name": "compatibility", "status": "pass" if MODULE_EXTRACTION_BOUNDARIES["legacy_wrappers_required"] and MODULE_EXTRACTION_BOUNDARIES["existing_routes_preserved"] else "blocked", "message": "Legacy wrappers and existing routes remain required."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if MODULE_EXTRACTION_BOUNDARIES["dashboard_data_tip_required"] and MODULE_EXTRACTION_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard registry integration preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if MODULE_EXTRACTION_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]
    return rows


def _build_module_extraction_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = MODULE_EXTRACTION_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v270.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown module extraction stage: {slug}", "rows": []}
    docs = _module_extraction_docs_text()
    rows = _module_extraction_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    registry = module_extraction_registry_summary()
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v265.1-v270.0 Operator-Governed Runtime Module Extraction v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "registry_summary": registry,
        "module_extraction_seeds": MODULE_EXTRACTION_SEEDS.get(definition["runtime_key"], []),
        "extracted_modules": [
            {"path": "conscious_agent/runtime_registry.py", "purpose": "shared runtime metadata registry and compatibility adapters", "authorizes_execution": False},
            {"path": "conscious_agent/governance_reports.py", "purpose": "shared governance report rendering helpers", "authorizes_execution": False},
        ],
        "runtime_registry_rows": [row for row in MODULE_EXTRACTION_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "safe_next_action": "Operator may review module-extraction parity and later approve deeper decomposition. This layer preserves existing wrappers and grants no execution authority.",
        "blockers": blockers,
        "boundaries": MODULE_EXTRACTION_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v270.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = MODULE_EXTRACTION_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _module_extraction_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    registry = payload.get("registry_summary", {})
    seeds = payload.get("module_extraction_seeds", [])
    sections = [
        ("Extracted modules", [f"- {item.get('path')}: {item.get('purpose')} (authorizes execution: {item.get('authorizes_execution', False)})" for item in payload.get("extracted_modules", [])]),
        ("Registry summary", [
            f"- Version: {registry.get('version', '270.0')}",
            f"- Stage count: {registry.get('stage_count', len(MODULE_EXTRACTION_STAGE_DEFS))}",
            f"- Final routes: {', '.join(registry.get('final_routes', []))}",
            f"- Final CLI flags: {', '.join(registry.get('final_cli_flags', []))}",
        ]),
        ("Current layer seeds", render_seed_rows(seeds, limit=8)),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before deeper refactor.')}"]),
    ]
    title = f"{payload.get('stage', 'v265.1-v270.0')} {payload.get('name', 'Operator-Governed Runtime Module Extraction v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_module_extraction_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, save=True, **kwargs):
        return _build_module_extraction_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_module_extraction_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_module_extraction_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_module_extraction_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _module_extraction_slug in MODULE_EXTRACTION_STAGE_BY_SLUG:
    globals()[f"build_{_module_extraction_slug}"] = _make_module_extraction_build(_module_extraction_slug)
    globals()[f"print_{_module_extraction_slug}"] = _make_module_extraction_print(_module_extraction_slug)

