def build_self_maintenance_decomposition_stage_defs() -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for arc in SELF_MAINTENANCE_DECOMPOSITION_ARCS:
        for item in arc["items"]:
            rows.append({
                "version": item[0],
                "slug": item[1],
                "label": item[2],
                "focus": item[3],
                "route": item[4],
                "is_final": bool(item[5]) if len(item) > 5 else False,
                "final_label": arc["final_label"],
                "api": arc["api"],
                "dashboard": arc["dashboard"],
                "runtime_key": arc["runtime_key"],
                "theme": arc["theme"],
                "stage": f"{arc['version']} {arc['final_label']}",
            })
    return rows

