def _self_maintenance_decomposition_docs_text() -> str:
    parts = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py",
        "conscious_agent/package_integrity.py", "conscious_agent/version_state.py", "conscious_agent/surface_parity.py", "conscious_agent/verification_planning.py",
    ]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _self_maintenance_decomposition_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = [
        "self-maintenance-extraction-map", "package-version-integrity", "surface-parity-audit", "verification-planning-audit", "self-maintenance-decomposition-audit",
        "operator-governed-self-maintenance-decomposition-v1", "package_integrity.py", "version_state.py", "surface_parity.py", "verification_planning.py",
    ]
    forbidden_false = [
        "self_maintenance_decomposition_removes_legacy_wrappers", "self_maintenance_decomposition_changes_routes", "self_maintenance_decomposition_changes_cli_api_behavior", "self_maintenance_decomposition_executes_smoke_commands", "self_maintenance_decomposition_inferrs_approval_from_clean_audits", "self_maintenance_decomposition_invokes_models_by_default", "self_maintenance_decomposition_mutates_memory", "self_maintenance_decomposition_alters_identity", "self_maintenance_decomposition_self_approves", "self_maintenance_decomposition_publishes_release_candidates", "self_maintenance_decomposition_continues_automatically", "package_version_helpers_write_files", "surface_parity_helpers_add_routes", "verification_planning_helpers_run_commands",
    ]
    version_summary = version_marker_summary(ROOT_DIR, SELF_MAINTENANCE_VERSION)
    verification_plan = build_verification_readiness_plan()
    package_policy = source_only_entry_policy()
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION and version_summary.get("ok") else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}; marker rows={len(version_summary.get('rows', []))}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in SELF_MAINTENANCE_DECOMPOSITION_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, packaging, smoke, and extracted utility modules mention v275 surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in SELF_MAINTENANCE_DECOMPOSITION_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded self-maintenance decomposition artifacts."},
        {"name": "stage-count", "status": "pass" if len(SELF_MAINTENANCE_DECOMPOSITION_STAGE_DEFS) == 50 else "blocked", "message": f"{len(SELF_MAINTENANCE_DECOMPOSITION_STAGE_DEFS)} stage(s) defined."},
        {"name": "utility-modules", "status": "pass" if package_policy.get("version") == SELF_MAINTENANCE_VERSION and verification_plan.get("runs_commands") is False else "blocked", "message": "package_integrity.py, version_state.py, surface_parity.py, and verification_planning.py expose review-only helpers."},
        {"name": "no-decomposition-authority", "status": "pass" if not any(SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Decomposition cannot remove wrappers, change routes, run commands, approve, publish, mutate, invoke models, or continue automatically."},
        {"name": "compatibility", "status": "pass" if SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES["legacy_wrappers_required"] and SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES["existing_routes_preserved"] else "blocked", "message": "Legacy wrappers and existing routes remain required."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES["dashboard_data_tip_required"] and SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]
    return rows


def _build_self_maintenance_decomposition_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = SELF_MAINTENANCE_DECOMPOSITION_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v275.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown self-maintenance decomposition stage: {slug}", "rows": []}
    docs = _self_maintenance_decomposition_docs_text()
    rows = _self_maintenance_decomposition_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    dashboard_routes = [arc["dashboard"] for arc in SELF_MAINTENANCE_DECOMPOSITION_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in SELF_MAINTENANCE_DECOMPOSITION_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in SELF_MAINTENANCE_DECOMPOSITION_ARCS]
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="ignore")
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="ignore")
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v270.1-v275.0 Operator-Governed Self-Maintenance Decomposition v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "utility_modules": [
            {"path": "conscious_agent/package_integrity.py", "purpose": "source-only privacy and runtime path helpers", "authorizes_execution": False},
            {"path": "conscious_agent/version_state.py", "purpose": "version marker summary and compatibility helpers", "authorizes_execution": False},
            {"path": "conscious_agent/surface_parity.py", "purpose": "dashboard/API/CLI surface parity helpers", "authorizes_execution": False},
            {"path": "conscious_agent/verification_planning.py", "purpose": "review-only smoke and verification planning helpers", "authorizes_execution": False},
        ],
        "package_policy": source_only_entry_policy(),
        "version_summary": release_marker_compatibility_adapter(ROOT_DIR, "285.0"),
        "surface_parity": build_surface_parity_summary(dashboard_text, api_text, main_text, dashboard_routes=dashboard_routes, api_routes=api_routes, cli_flags=cli_flags),
        "verification_plan": build_verification_readiness_plan(),
        "seeds": SELF_MAINTENANCE_DECOMPOSITION_SEEDS.get(definition["runtime_key"], []),
        "runtime_registry_rows": [row for row in SELF_MAINTENANCE_DECOMPOSITION_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "safe_next_action": "Operator may review self-maintenance decomposition parity and later approve deeper extraction. This layer preserves wrappers and grants no execution authority.",
        "blockers": blockers,
        "boundaries": SELF_MAINTENANCE_DECOMPOSITION_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v275.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = SELF_MAINTENANCE_DECOMPOSITION_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _self_maintenance_decomposition_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    sections = [
        ("Utility modules", [f"- {item.get('path')}: {item.get('purpose')} (authorizes execution: {item.get('authorizes_execution', False)})" for item in payload.get("utility_modules", [])]),
        ("Current layer seeds", render_seed_rows(payload.get("seeds", []), limit=8)),
        ("Version markers", [f"- {row.get('path')}: {row.get('value')} ({row.get('status')})" for row in payload.get("version_summary", {}).get("rows", [])[:8]]),
        ("Surface parity", parity_summary_renderer(payload.get("surface_parity", {}))),
        ("Verification plan", verification_readiness_summary(payload.get("verification_plan", {}))[:8]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before deeper decomposition.')}"]),
    ]
    title = f"{payload.get('stage', 'v270.1-v275.0')} {payload.get('name', 'Operator-Governed Self-Maintenance Decomposition v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_self_maintenance_decomposition_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, save=True, **kwargs):
        return _build_self_maintenance_decomposition_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_self_maintenance_decomposition_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_self_maintenance_decomposition_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_self_maintenance_decomposition_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _self_maintenance_decomposition_slug in SELF_MAINTENANCE_DECOMPOSITION_STAGE_BY_SLUG:
    globals()[f"build_{_self_maintenance_decomposition_slug}"] = _make_self_maintenance_decomposition_build(_self_maintenance_decomposition_slug)
    globals()[f"print_{_self_maintenance_decomposition_slug}"] = _make_self_maintenance_decomposition_print(_self_maintenance_decomposition_slug)

