def _interface_modularization_docs_text() -> str:
    parts = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py",
        "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py",
        "conscious_agent/dashboard_components.py", "conscious_agent/api_surface.py", "conscious_agent/cli_surface.py",
    ]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _interface_modularization_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = [
        "dashboard-extraction-map", "dashboard-component-audit", "api-surface-audit", "cli-surface-audit", "interface-modularization-audit",
        "operator-governed-dashboard-api-cli-modularization-v1", "dashboard_components.py", "api_surface.py", "cli_surface.py",
    ]
    forbidden_false = [
        "interface_modularization_redesigns_dashboard", "interface_modularization_removes_routes", "interface_modularization_changes_api_cli_behavior",
        "interface_modularization_adds_autonomous_command_execution", "interface_modularization_invokes_models_by_default",
        "interface_modularization_inferrs_approval_from_clean_audits", "interface_modularization_mutates_memory",
        "interface_modularization_alters_identity", "interface_modularization_self_approves", "interface_modularization_publishes_releases",
        "interface_modularization_continues_automatically", "dashboard_components_change_visual_contract",
        "dashboard_components_use_native_title_tooltips", "api_surface_helpers_change_behavior", "cli_surface_helpers_execute_commands",
    ]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in INTERFACE_MODULARIZATION_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, API, CLI, packaging, smoke, and helper modules mention v280 interface modularization surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in INTERFACE_MODULARIZATION_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded interface modularization artifacts."},
        {"name": "stage-count", "status": "pass" if len(INTERFACE_MODULARIZATION_STAGE_DEFS) == 50 else "blocked", "message": f"{len(INTERFACE_MODULARIZATION_STAGE_DEFS)} interface stage(s) defined."},
        {"name": "helper-module-versions", "status": "pass" if DASHBOARD_COMPONENTS_VERSION == API_SURFACE_VERSION == CLI_SURFACE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"dashboard_components={DASHBOARD_COMPONENTS_VERSION}, api_surface={API_SURFACE_VERSION}, cli_surface={CLI_SURFACE_VERSION}"},
        {"name": "no-interface-authority", "status": "pass" if not any(INTERFACE_MODULARIZATION_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Interface modularization cannot redesign, remove routes, change API/CLI behavior, execute commands, approve, publish, mutate, invoke models, or continue work."},
        {"name": "compatibility", "status": "pass" if INTERFACE_MODULARIZATION_BOUNDARIES["legacy_wrappers_required"] and INTERFACE_MODULARIZATION_BOUNDARIES["existing_routes_preserved"] and INTERFACE_MODULARIZATION_BOUNDARIES["existing_api_cli_behavior_preserved"] else "blocked", "message": "Legacy wrappers, existing routes, and API/CLI behavior remain required."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if INTERFACE_MODULARIZATION_BOUNDARIES["dashboard_data_tip_required"] and INTERFACE_MODULARIZATION_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if INTERFACE_MODULARIZATION_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]
    return rows


def _build_interface_modularization_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = INTERFACE_MODULARIZATION_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v280.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown interface modularization stage: {slug}", "rows": []}
    docs = _interface_modularization_docs_text()
    rows = _interface_modularization_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    dashboard_text = (ROOT_DIR / "conscious_agent" / "dashboard.py").read_text(encoding="utf-8", errors="ignore")
    api_text = (ROOT_DIR / "conscious_agent" / "api_server.py").read_text(encoding="utf-8", errors="ignore")
    main_text = (ROOT_DIR / "conscious_agent" / "main.py").read_text(encoding="utf-8", errors="ignore")
    dashboard_routes = [arc["dashboard"] for arc in INTERFACE_MODULARIZATION_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in INTERFACE_MODULARIZATION_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in INTERFACE_MODULARIZATION_ARCS]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v275.1-v280.0 Operator-Governed Dashboard/API/CLI Modularization v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "helper_modules": [
            {"path": "conscious_agent/dashboard_components.py", "purpose": "tooltip-safe command-deck dashboard component helper metadata", "authorizes_execution": False},
            {"path": "conscious_agent/api_surface.py", "purpose": "API surface helper metadata and parity summaries", "authorizes_execution": False},
            {"path": "conscious_agent/cli_surface.py", "purpose": "CLI surface helper metadata and parity summaries", "authorizes_execution": False},
        ],
        "dashboard_component_summary": build_dashboard_component_summary(dashboard_text, dashboard_routes),
        "api_surface_summary": build_api_surface_summary(api_text, api_routes),
        "cli_surface_summary": build_cli_surface_summary(main_text, cli_flags),
        "surface_parity": build_surface_parity_summary(dashboard_text, api_text, main_text, dashboard_routes=dashboard_routes, api_routes=api_routes, cli_flags=cli_flags),
        "seeds": INTERFACE_MODULARIZATION_SEEDS.get(definition["runtime_key"], []),
        "runtime_registry_rows": [row for row in INTERFACE_MODULARIZATION_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "safe_next_action": "Operator may review interface modularization parity and later approve deeper interface cleanup. This layer preserves wrappers, routes, dashboard style, and grants no execution authority.",
        "blockers": blockers,
        "boundaries": INTERFACE_MODULARIZATION_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v280.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = INTERFACE_MODULARIZATION_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _interface_modularization_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    sections = [
        ("Helper modules", [f"- {item.get('path')}: {item.get('purpose')} (authorizes execution: {item.get('authorizes_execution', False)})" for item in payload.get("helper_modules", [])]),
        ("Current layer seeds", render_seed_rows(payload.get("seeds", []), limit=8)),
        ("Dashboard component summary", render_dashboard_component_lines(payload.get("dashboard_component_summary", {}))),
        ("API surface summary", api_surface_summary_lines(payload.get("api_surface_summary", {}))),
        ("CLI surface summary", cli_surface_summary_lines(payload.get("cli_surface_summary", {}))),
        ("Surface parity", parity_summary_renderer(payload.get("surface_parity", {}))),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before deeper interface cleanup.')}" ]),
    ]
    title = f"{payload.get('stage', 'v275.1-v280.0')} {payload.get('name', 'Operator-Governed Dashboard/API/CLI Modularization v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_interface_modularization_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, save=True, **kwargs):
        return _build_interface_modularization_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_interface_modularization_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_interface_modularization_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_interface_modularization_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


for _interface_modularization_slug in INTERFACE_MODULARIZATION_STAGE_BY_SLUG:
    globals()[f"build_{_interface_modularization_slug}"] = _make_interface_modularization_build(_interface_modularization_slug)
    globals()[f"print_{_interface_modularization_slug}"] = _make_interface_modularization_print(_interface_modularization_slug)

