def _application_execution_refinement_docs_text() -> str:
    parts = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/application_execution_refinement.py",
    ]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _application_execution_refinement_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = [
        "approved-application-binding", "operator-execution-checklist", "post-application-result-review", "application-outcome-learning", "application-execution-refinement-audit",
        "operator-approved-application-execution-refinement-v1", "application_execution_refinement.py",
    ]
    forbidden_false = [
        "application_refinement_applies_patches_automatically", "application_refinement_executes_shell_commands_automatically", "application_refinement_infers_approval_from_readiness", "application_refinement_reuses_stale_or_vague_consent",
        "application_refinement_runs_rollback_automatically", "application_refinement_mutates_memory", "application_refinement_alters_identity", "application_refinement_invokes_models_by_default",
        "application_refinement_publishes_release_candidates", "application_refinement_continues_automatically", "application_refinement_treats_outcome_learning_as_stored_memory",
    ]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "stage-definition", "status": "pass" if definition.get("slug") in APPLICATION_EXECUTION_REFINEMENT_STAGE_BY_SLUG else "blocked", "message": definition.get("label", "stage")},
        {"name": "docs", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, API, CLI, packaging, smoke, and helper module mention v285 application execution refinement surfaces."},
        {"name": "runtime-dirs", "status": "pass" if all(str(path).endswith(key) for key, path in APPLICATION_EXECUTION_REFINEMENT_RUNTIME_DIRS.items()) else "blocked", "message": "Runtime directories are source-only excluded application refinement artifacts."},
        {"name": "stage-count", "status": "pass" if len(APPLICATION_EXECUTION_REFINEMENT_STAGE_DEFS) == 50 else "blocked", "message": f"{len(APPLICATION_EXECUTION_REFINEMENT_STAGE_DEFS)} application execution refinement stage(s) defined."},
        {"name": "helper-module-version", "status": "pass" if APPLICATION_EXECUTION_REFINEMENT_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"application_execution_refinement={APPLICATION_EXECUTION_REFINEMENT_VERSION}"},
        {"name": "no-application-authority", "status": "pass" if not any(APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES[key] for key in forbidden_false) else "blocked", "message": "Application refinement cannot apply patches, run commands, infer approval, reuse stale consent, rollback, publish, mutate, invoke models, or continue work."},
        {"name": "approval-boundary", "status": "pass" if APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["application_refinement_requires_exact_current_scoped_approval"] and APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["application_refinement_is_review_only_until_operator_execution_approval"] else "blocked", "message": "Exact, current, scoped operator approval remains required before any application workflow."},
        {"name": "post-application-boundary", "status": "pass" if APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["application_refinement_requires_post_application_operator_result_intake"] and APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["application_refinement_recommends_rollback_review_only"] else "blocked", "message": "Post-application review requires operator-submitted results and rollback remains recommendation-only."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["dashboard_data_tip_required"] and APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]
    return rows


def _build_application_execution_refinement_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = APPLICATION_EXECUTION_REFINEMENT_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v285.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown application execution refinement stage: {slug}", "rows": []}
    docs = _application_execution_refinement_docs_text()
    rows = _application_execution_refinement_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    dashboard_routes = [arc["dashboard"] for arc in APPLICATION_EXECUTION_REFINEMENT_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in APPLICATION_EXECUTION_REFINEMENT_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in APPLICATION_EXECUTION_REFINEMENT_ARCS]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v280.1-v285.0 Operator-Approved Application Execution Refinement v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "application_binding_summary": build_application_binding_summary(packet_id=packet_id, approval_note=approval_note),
        "execution_checklist_summary": build_execution_checklist_summary(),
        "post_application_review_summary": build_post_application_review_summary(),
        "outcome_learning_summary": build_outcome_learning_summary(),
        "surface_summary": {"dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags},
        "seeds": APPLICATION_EXECUTION_REFINEMENT_SEEDS.get(definition["runtime_key"], []),
        "runtime_registry_rows": [row for row in APPLICATION_EXECUTION_REFINEMENT_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "safe_next_action": "Operator may review application execution refinement packets. Any real application, command execution, rollback, release, or memory write still requires separate exact operator approval.",
        "blockers": blockers,
        "boundaries": APPLICATION_EXECUTION_REFINEMENT_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v285.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = APPLICATION_EXECUTION_REFINEMENT_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _application_execution_refinement_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    sections = [
        ("Application binding", render_application_execution_lines(payload.get("application_binding_summary", {}))),
        ("Execution checklist", render_application_execution_lines(payload.get("execution_checklist_summary", {}))),
        ("Post-application review", render_application_execution_lines(payload.get("post_application_review_summary", {}))),
        ("Outcome learning", render_application_execution_lines(payload.get("outcome_learning_summary", {}))),
        ("Current layer seeds", render_seed_rows(payload.get("seeds", []), limit=8)),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('surface_summary', {}).get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('surface_summary', {}).get('api_routes', []))}", f"- cli: {', '.join(payload.get('surface_summary', {}).get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any execution refinement action.')}" ]),
    ]
    title = f"{payload.get('stage', 'v280.1-v285.0')} {payload.get('name', 'Operator-Approved Application Execution Refinement v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_application_execution_refinement_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, save=True, **kwargs):
        return _build_application_execution_refinement_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_application_execution_refinement_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_application_execution_refinement_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_application_execution_refinement_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_application_execution_refinement_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _application_execution_refinement_text(report or _build_application_execution_refinement_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _application_execution_refinement_slug in APPLICATION_EXECUTION_REFINEMENT_STAGE_BY_SLUG:
    globals()[f"build_{_application_execution_refinement_slug}"] = _make_application_execution_refinement_build(_application_execution_refinement_slug)
    globals()[f"print_{_application_execution_refinement_slug}"] = _make_application_execution_refinement_print(_application_execution_refinement_slug)
    globals()[f"{_application_execution_refinement_slug}_text"] = _make_application_execution_refinement_text(_application_execution_refinement_slug)

