def _rollback_recovery_docs_text() -> str:
    parts = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/rollback_recovery.py",
    ]:
        try:
            parts.append((ROOT_DIR / rel).read_text(encoding="utf-8"))
        except OSError:
            parts.append("")
    return "\n".join(parts)


def _rollback_recovery_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = [
        "rollback-scope-binding", "failure-damage-map", "recovery-checklist", "post-recovery-review", "rollback-recovery-audit", "operator-governed-rollback-and-recovery-intelligence-v1", "rollback_recovery.py",
    ]
    dashboard_routes = [arc["dashboard"] for arc in ROLLBACK_RECOVERY_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in ROLLBACK_RECOVERY_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in ROLLBACK_RECOVERY_ARCS]
    forbidden_false = [
        "rollback_recovery_runs_rollback_automatically", "rollback_recovery_edits_files_automatically", "rollback_recovery_executes_shell_commands_automatically", "rollback_recovery_infers_rollback_approval_from_failure", "rollback_recovery_infers_patch_approval_from_recovery_success", "rollback_recovery_mutates_memory", "rollback_recovery_alters_identity", "rollback_recovery_invokes_models_by_default", "rollback_recovery_publishes_release_candidates", "rollback_recovery_continues_automatically",
    ]
    return [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "helper-module-version", "status": "pass" if ROLLBACK_RECOVERY_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"rollback_recovery={ROLLBACK_RECOVERY_VERSION}"},
        {"name": "stage-registry", "status": "pass" if len(ROLLBACK_RECOVERY_STAGE_DEFS) == 50 and definition.get("slug") in ROLLBACK_RECOVERY_STAGE_BY_SLUG else "blocked", "message": f"{len(ROLLBACK_RECOVERY_STAGE_DEFS)} rollback/recovery substages registered."},
        {"name": "dashboard-routes", "status": "pass" if all(route in docs for route in dashboard_routes) else "blocked", "message": ", ".join(dashboard_routes)},
        {"name": "api-routes", "status": "pass" if all(route in docs for route in api_routes) else "blocked", "message": ", ".join(api_routes)},
        {"name": "cli-flags", "status": "pass" if all(flag in docs for flag in cli_flags) else "blocked", "message": ", ".join(cli_flags)},
        {"name": "docs-release-history", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, API, CLI, smoke, and package privacy mention v290 surfaces."},
        {"name": "runtime-dirs-private", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in ROLLBACK_RECOVERY_RUNTIME_DIRS) else "blocked", "message": "Rollback/recovery runtime dirs are documented as excluded/private."},
        {"name": "no-rollback-authority", "status": "pass" if all(ROLLBACK_RECOVERY_BOUNDARIES[key] is False for key in forbidden_false) else "blocked", "message": "Rollback recovery cannot rollback, edit files, run commands, infer approval, publish, mutate, invoke models, or continue work."},
        {"name": "operator-result-boundary", "status": "pass" if ROLLBACK_RECOVERY_BOUNDARIES["rollback_recovery_requires_operator_submitted_results"] and ROLLBACK_RECOVERY_BOUNDARIES["rollback_recovery_requires_explicit_rollback_approval"] and ROLLBACK_RECOVERY_BOUNDARIES["rollback_recovery_is_review_only"] else "blocked", "message": "Rollback/recovery requires operator-submitted results and explicit rollback approval."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if ROLLBACK_RECOVERY_BOUNDARIES["dashboard_data_tip_required"] and ROLLBACK_RECOVERY_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if ROLLBACK_RECOVERY_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]


def _build_rollback_recovery_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, failure_type: str | None = None, observed_status: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = ROLLBACK_RECOVERY_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v290.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown rollback/recovery stage: {slug}", "rows": []}
    docs = _rollback_recovery_docs_text()
    rows = _rollback_recovery_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    dashboard_routes = [arc["dashboard"] for arc in ROLLBACK_RECOVERY_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in ROLLBACK_RECOVERY_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in ROLLBACK_RECOVERY_ARCS]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v285.1-v290.0 Operator-Governed Rollback and Recovery Intelligence v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "rollback_scope_summary": build_rollback_scope_summary(packet_id=packet_id),
        "failure_damage_summary": build_failure_damage_map_summary(failure_type=failure_type),
        "recovery_checklist_summary": build_recovery_checklist_summary(),
        "post_recovery_review_summary": build_post_recovery_review_summary(observed_status=observed_status),
        "surface_summary": {"dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags},
        "seeds": ROLLBACK_RECOVERY_SEEDS.get(definition["runtime_key"], []),
        "runtime_registry_rows": [row for row in ROLLBACK_RECOVERY_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "safe_next_action": "Operator may review rollback/recovery intelligence packets. Any real rollback, source edit, command execution, release, memory write, model invocation, or continuation still requires separate exact operator approval.",
        "blockers": blockers,
        "boundaries": ROLLBACK_RECOVERY_BOUNDARIES,
    }
    message = f"{definition['version']} {definition['final_label']} is {'ready for operator review' if ok else 'blocked pending review'}: {definition['focus']}"
    report = {"version": "v290.0", "status": "pass" if ok else "blocked", "ok": ok, "checked_at": _now(), "project_id": project_id, "message": message, "payload": payload, "rows": rows}
    if save:
        outdir = ROLLBACK_RECOVERY_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2), encoding="utf-8")
    return report


def _rollback_recovery_text(report: dict[str, Any], full: bool = False) -> str:
    payload = report.get("payload", {})
    sections = [
        ("Rollback scope", render_rollback_recovery_lines(payload.get("rollback_scope_summary", {}))),
        ("Failure damage map", render_rollback_recovery_lines(payload.get("failure_damage_summary", {}))),
        ("Recovery checklist", render_rollback_recovery_lines(payload.get("recovery_checklist_summary", {}))),
        ("Post-recovery review", render_rollback_recovery_lines(payload.get("post_recovery_review_summary", {}))),
        ("Current layer seeds", render_seed_rows(payload.get("seeds", []), limit=8)),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('surface_summary', {}).get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('surface_summary', {}).get('api_routes', []))}", f"- cli: {', '.join(payload.get('surface_summary', {}).get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any rollback or recovery action.')}" ]),
    ]
    title = f"{payload.get('stage', 'v285.1-v290.0')} {payload.get('name', 'Operator-Governed Rollback and Recovery Intelligence v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_rollback_recovery_build(slug: str):
    def _builder(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, failure_type=None, observed_status=None, save=True, **kwargs):
        return _build_rollback_recovery_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, failure_type=failure_type, observed_status=observed_status, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_rollback_recovery_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, failure_type=None, observed_status=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_rollback_recovery_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, failure_type=failure_type, observed_status=observed_status, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_rollback_recovery_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_rollback_recovery_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _rollback_recovery_text(report or _build_rollback_recovery_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _rollback_recovery_slug in ROLLBACK_RECOVERY_STAGE_BY_SLUG:
    globals()[f"build_{_rollback_recovery_slug}"] = _make_rollback_recovery_build(_rollback_recovery_slug)
    globals()[f"print_{_rollback_recovery_slug}"] = _make_rollback_recovery_print(_rollback_recovery_slug)
    globals()[f"{_rollback_recovery_slug}_text"] = _make_rollback_recovery_text(_rollback_recovery_slug)

