def _memory_governance_docs_text() -> str:
    parts = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/memory_governance.py",
    ]:
        try:
            parts.append((ROOT_DIR / rel).read_text(encoding="utf-8"))
        except OSError:
            parts.append("")
    return "\n".join(parts)


def _memory_governance_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = [
        "memory-candidate-intake", "memory-candidate-classification", "memory-approval-packet", "memory-contradiction-review", "memory-governance-audit", "operator-governed-memory-candidate-governance-upgrade-v1", "memory_governance.py",
    ]
    dashboard_routes = [arc["dashboard"] for arc in MEMORY_GOVERNANCE_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in MEMORY_GOVERNANCE_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in MEMORY_GOVERNANCE_ARCS]
    forbidden_false = [
        "memory_governance_writes_memory_automatically", "memory_governance_alters_identity", "memory_governance_alters_personality", "memory_governance_rewrites_goals_or_purpose", "memory_governance_infers_approval_from_repeated_evidence", "memory_governance_infers_approval_from_operator_silence", "memory_governance_treats_lessons_as_stored_truth", "memory_governance_invokes_models_by_default", "memory_governance_executes_commands", "memory_governance_publishes_release_candidates", "memory_governance_continues_automatically",
    ]
    return [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "helper-module-version", "status": "pass" if MEMORY_GOVERNANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"memory_governance={MEMORY_GOVERNANCE_VERSION}"},
        {"name": "stage-registry", "status": "pass" if len(MEMORY_GOVERNANCE_STAGE_DEFS) == 50 and definition.get("slug") in MEMORY_GOVERNANCE_STAGE_BY_SLUG else "blocked", "message": f"{len(MEMORY_GOVERNANCE_STAGE_DEFS)} memory governance substages registered."},
        {"name": "dashboard-routes", "status": "pass" if all(route in docs for route in dashboard_routes) else "blocked", "message": ", ".join(dashboard_routes)},
        {"name": "api-routes", "status": "pass" if all(route in docs for route in api_routes) else "blocked", "message": ", ".join(api_routes)},
        {"name": "cli-flags", "status": "pass" if all(flag in docs for flag in cli_flags) else "blocked", "message": ", ".join(cli_flags)},
        {"name": "docs-release-history", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, API, CLI, smoke, and package privacy mention v295 surfaces."},
        {"name": "runtime-dirs-private", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in MEMORY_GOVERNANCE_RUNTIME_DIRS) else "blocked", "message": "Memory governance runtime dirs are documented as excluded/private."},
        {"name": "no-memory-authority", "status": "pass" if all(MEMORY_GOVERNANCE_BOUNDARIES[key] is False for key in forbidden_false) else "blocked", "message": "Memory governance cannot write memory, mutate identity/personality/purpose, infer approval, execute commands, publish, invoke models, or continue."},
        {"name": "operator-memory-approval-boundary", "status": "pass" if MEMORY_GOVERNANCE_BOUNDARIES["memory_governance_requires_operator_memory_approval"] and MEMORY_GOVERNANCE_BOUNDARIES["memory_governance_stages_candidates_only"] and MEMORY_GOVERNANCE_BOUNDARIES["memory_governance_sensitive_identity_boundary_required"] and MEMORY_GOVERNANCE_BOUNDARIES["memory_governance_contradiction_review_required"] else "blocked", "message": "Memory governance stages candidates only and requires explicit operator memory approval, sensitive review, and contradiction review."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if MEMORY_GOVERNANCE_BOUNDARIES["dashboard_data_tip_required"] and MEMORY_GOVERNANCE_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if MEMORY_GOVERNANCE_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]


def _build_memory_governance_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, source_type: str | None = None, candidate_type: str | None = None, conflict_type: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = MEMORY_GOVERNANCE_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "v295.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown memory governance stage: {slug}", "rows": []}
    docs = _memory_governance_docs_text()
    rows = _memory_governance_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    dashboard_routes = [arc["dashboard"] for arc in MEMORY_GOVERNANCE_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in MEMORY_GOVERNANCE_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in MEMORY_GOVERNANCE_ARCS]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v290.1-v295.0 Operator-Governed Memory Candidate Governance Upgrade v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "memory_candidate_intake_summary": build_memory_candidate_intake_summary(source_type=source_type),
        "memory_candidate_classification_summary": build_memory_candidate_classification_summary(candidate_type=candidate_type),
        "memory_approval_packet_summary": build_memory_approval_packet_summary(candidate_id=packet_id),
        "memory_contradiction_review_summary": build_memory_contradiction_review_summary(conflict_type=conflict_type),
        "seeds": MEMORY_GOVERNANCE_SEEDS.get(definition["runtime_key"], []),
        "dashboard_routes": dashboard_routes,
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in MEMORY_GOVERNANCE_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": MEMORY_GOVERNANCE_BOUNDARIES,
        "helper_lines": render_memory_governance_lines(build_memory_candidate_intake_summary(source_type=source_type)),
    }
    status = "pass" if ok else "blocked"
    report = {
        "version": "310.0",
        "checked_at": _now(),
        "project_id": project_id,
        "stage": definition["stage"],
        "status": status,
        "ok": ok,
        "message": (f"{definition['label']} passed v295 memory governance review-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"),
        "rows": rows,
        "payload": payload,
    }
    if save:
        outdir = MEMORY_GOVERNANCE_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _make_memory_governance_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_memory_governance_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _memory_governance_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    title = "v295.0 Operator-Governed Memory Candidate Governance Upgrade v1"
    if report and report.get("stage"):
        title = f"{report.get('stage')} {report.get('payload', {}).get('name', 'Memory Governance Stage')}"
    return _generic_text(title, report or _build_memory_governance_stage("memory_governance_audit", save=False), full)


def _make_memory_governance_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, source_type=None, candidate_type=None, conflict_type=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_memory_governance_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, source_type=source_type, candidate_type=candidate_type, conflict_type=conflict_type, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_memory_governance_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_memory_governance_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _memory_governance_text(report or _build_memory_governance_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _memory_governance_slug in MEMORY_GOVERNANCE_STAGE_BY_SLUG:
    globals()[f"build_{_memory_governance_slug}"] = _make_memory_governance_build(_memory_governance_slug)
    globals()[f"print_{_memory_governance_slug}"] = _make_memory_governance_print(_memory_governance_slug)
    globals()[f"{_memory_governance_slug}_text"] = _make_memory_governance_text(_memory_governance_slug)

