def _continuity_kernel_docs_text() -> str:
    parts = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/continuity_kernel.py",
    ]:
        try:
            parts.append((ROOT_DIR / rel).read_text(encoding="utf-8"))
        except OSError:
            parts.append("")
    return "\n".join(parts)


def _continuity_kernel_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required_tokens = [
        "continuity-state-intake", "self-model-snapshot-v2", "purpose-coherence-review", "supervised-growth-priorities", "continuity-kernel-v2-audit", "local-artificial-mind-continuity-kernel-v2", "continuity_kernel.py",
    ]
    dashboard_routes = [arc["dashboard"] for arc in CONTINUITY_KERNEL_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in CONTINUITY_KERNEL_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in CONTINUITY_KERNEL_ARCS]
    forbidden_false = [
        "continuity_kernel_mutates_memory", "continuity_kernel_alters_identity", "continuity_kernel_alters_personality", "continuity_kernel_rewrites_purpose", "continuity_kernel_self_approves_capabilities", "continuity_kernel_auto_selects_roadmaps", "continuity_kernel_starts_patches_automatically", "continuity_kernel_infers_approval_from_audits", "continuity_kernel_invokes_models_by_default", "continuity_kernel_executes_commands", "continuity_kernel_publishes_release_candidates", "continuity_kernel_treats_self_model_as_authority",
    ]
    return [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "helper-module-version", "status": "pass" if CONTINUITY_KERNEL_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"continuity_kernel={CONTINUITY_KERNEL_VERSION}"},
        {"name": "stage-registry", "status": "pass" if len(CONTINUITY_KERNEL_STAGE_DEFS) == 50 and definition.get("slug") in CONTINUITY_KERNEL_STAGE_BY_SLUG else "blocked", "message": f"{len(CONTINUITY_KERNEL_STAGE_DEFS)} continuity kernel substages registered."},
        {"name": "dashboard-routes", "status": "pass" if all(route in docs for route in dashboard_routes) else "blocked", "message": ", ".join(dashboard_routes)},
        {"name": "api-routes", "status": "pass" if all(route in docs for route in api_routes) else "blocked", "message": ", ".join(api_routes)},
        {"name": "cli-flags", "status": "pass" if all(flag in docs for flag in cli_flags) else "blocked", "message": ", ".join(cli_flags)},
        {"name": "docs-release-history", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, API, CLI, smoke, and package privacy mention v300 surfaces."},
        {"name": "runtime-dirs-private", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in CONTINUITY_KERNEL_RUNTIME_DIRS) else "blocked", "message": "Continuity kernel runtime dirs are documented as excluded/private."},
        {"name": "no-continuity-authority", "status": "pass" if all(CONTINUITY_KERNEL_BOUNDARIES[key] is False for key in forbidden_false) else "blocked", "message": "Continuity kernel cannot mutate memory/identity/personality/purpose, self-approve, auto-roadmap, start patches, infer approval, execute, publish, invoke models, or treat self-model as authority."},
        {"name": "operator-review-boundary", "status": "pass" if CONTINUITY_KERNEL_BOUNDARIES["continuity_kernel_review_only"] and CONTINUITY_KERNEL_BOUNDARIES["continuity_kernel_requires_operator_review"] and CONTINUITY_KERNEL_BOUNDARIES["continuity_kernel_connects_memory_candidates"] and CONTINUITY_KERNEL_BOUNDARIES["continuity_kernel_connects_recovery_lessons"] else "blocked", "message": "Continuity kernel is review-only and requires operator review while connecting memory candidates and recovery lessons."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if CONTINUITY_KERNEL_BOUNDARIES["dashboard_data_tip_required"] and CONTINUITY_KERNEL_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if CONTINUITY_KERNEL_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]


def _build_continuity_kernel_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, risk_level: str | None = None, priority_hint: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = CONTINUITY_KERNEL_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "310.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown continuity kernel stage: {slug}", "rows": []}
    docs = _continuity_kernel_docs_text()
    rows = _continuity_kernel_status_rows(definition, docs)
    submitted_policy_text = " ".join(str(part) for part in [improvement_goal, candidate_file, packet_id, approval_note, risk_level, priority_hint] if part)
    continuity_policy_decision = classify_identity_expression_request(submitted_policy_text, context="continuity kernel live-policy authorization guard")
    if submitted_policy_text and continuity_policy_decision.get("status") == "blocked":
        rows.append({"name": "submitted-policy-request", "status": "blocked", "message": continuity_policy_decision.get("message", "Submitted continuity request contains blocked live-policy language.")})
    blockers = [row["name"] for row in rows if row.get("status") != "pass"]
    ok = not blockers
    dashboard_routes = [arc["dashboard"] for arc in CONTINUITY_KERNEL_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in CONTINUITY_KERNEL_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in CONTINUITY_KERNEL_ARCS]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v295.1-v300.0 Local Artificial Mind Continuity Kernel v2",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "continuity_state_summary": build_continuity_state_summary(current_version="305.0"),
        "self_model_snapshot_v2_summary": build_self_model_snapshot_v2_summary(),
        "purpose_coherence_review_summary": build_purpose_coherence_review_summary(risk_level=risk_level, request_text=submitted_policy_text),
        "submitted_policy_decision": continuity_policy_decision,
        "supervised_growth_priority_summary": build_supervised_growth_priority_summary(priority_hint=priority_hint),
        "memory_candidate_link": build_memory_candidate_intake_summary(),
        "recovery_lesson_link": build_post_recovery_review_summary(),
        "seeds": CONTINUITY_KERNEL_SEEDS.get(definition["runtime_key"], []),
        "dashboard_routes": dashboard_routes,
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in CONTINUITY_KERNEL_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": CONTINUITY_KERNEL_BOUNDARIES,
        "helper_lines": render_continuity_kernel_lines(build_continuity_state_summary(current_version="305.0")),
    }
    status = "pass" if ok else "blocked"
    report = {
        "version": "310.0",
        "checked_at": _now(),
        "project_id": project_id,
        "stage": definition["stage"],
        "status": status,
        "ok": ok,
        "message": (f"{definition['label']} passed v300 continuity kernel review-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"),
        "rows": rows,
        "payload": payload,
    }
    if save:
        outdir = CONTINUITY_KERNEL_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _make_continuity_kernel_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_continuity_kernel_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _continuity_kernel_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    title = "v300.0 Local Artificial Mind Continuity Kernel v2"
    if report and report.get("stage"):
        title = f"{report.get('stage')} {report.get('payload', {}).get('name', 'Continuity Kernel Stage')}"
    return _generic_text(title, report or _build_continuity_kernel_stage("continuity_kernel_v2_audit", save=False), full)


def _make_continuity_kernel_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, risk_level=None, priority_hint=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_continuity_kernel_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, risk_level=risk_level, priority_hint=priority_hint, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_continuity_kernel_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_continuity_kernel_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _continuity_kernel_text(report or _build_continuity_kernel_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _continuity_kernel_slug in CONTINUITY_KERNEL_STAGE_BY_SLUG:
    globals()[f"build_{_continuity_kernel_slug}"] = _make_continuity_kernel_build(_continuity_kernel_slug)
    globals()[f"print_{_continuity_kernel_slug}"] = _make_continuity_kernel_print(_continuity_kernel_slug)
    globals()[f"{_continuity_kernel_slug}_text"] = _make_continuity_kernel_text(_continuity_kernel_slug)

