def _identity_expression_docs_text() -> str:
    files = [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/identity_expression.py", "conscious_agent/continuity_kernel.py",
    ]
    return "\n".join(_read_text(ROOT_DIR / rel) for rel in files)


def _identity_expression_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    dashboard_routes = [arc["dashboard"] for arc in IDENTITY_EXPRESSION_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in IDENTITY_EXPRESSION_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in IDENTITY_EXPRESSION_ARCS]
    required_tokens = [
        "operator-governed-identity-personality-coherence-expression-layer-v1", "identity_expression.py", "identity-expression-boundary", "personality-trait-ledger", "voice-affect-style-map", "coherence-expression-review", "identity-personality-coherence-audit",
    ]
    forbidden_false = [key for key in IDENTITY_EXPRESSION_BOUNDARIES if key.startswith("identity_expression_") and key not in {"identity_expression_review_only", "identity_expression_requires_operator_review", "identity_expression_classifies_risky_requests"}]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "helper-module-version", "status": "pass" if IDENTITY_EXPRESSION_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"identity_expression={IDENTITY_EXPRESSION_VERSION}"},
        {"name": "stage-registry", "status": "pass" if len(IDENTITY_EXPRESSION_STAGE_DEFS) == 50 and definition.get("slug") in IDENTITY_EXPRESSION_STAGE_BY_SLUG else "blocked", "message": f"{len(IDENTITY_EXPRESSION_STAGE_DEFS)} identity/personality/coherence substages registered."},
        {"name": "dashboard-routes", "status": "pass" if all(route in docs for route in dashboard_routes) else "blocked", "message": ", ".join(dashboard_routes)},
        {"name": "api-routes", "status": "pass" if all(route in docs for route in api_routes) else "blocked", "message": ", ".join(api_routes)},
        {"name": "cli-flags", "status": "pass" if all(flag in docs for flag in cli_flags) else "blocked", "message": ", ".join(cli_flags)},
        {"name": "docs-release-history", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "README, release history, dashboard, API, CLI, smoke, and package privacy mention v305 surfaces."},
        {"name": "runtime-dirs-private", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in IDENTITY_EXPRESSION_RUNTIME_DIRS) else "blocked", "message": "Identity/personality/coherence runtime dirs are documented as excluded/private."},
        {"name": "no-expression-authority", "status": "pass" if all(IDENTITY_EXPRESSION_BOUNDARIES[key] is False for key in forbidden_false) else "blocked", "message": "Expression layer cannot mutate memory/identity/personality/purpose/prompts, self-approve, auto-roadmap, start patches, execute, publish, invoke models, store traits, or claim sentience as fact."},
        {"name": "operator-review-boundary", "status": "pass" if IDENTITY_EXPRESSION_BOUNDARIES["identity_expression_review_only"] and IDENTITY_EXPRESSION_BOUNDARIES["identity_expression_requires_operator_review"] and IDENTITY_EXPRESSION_BOUNDARIES["identity_expression_classifies_risky_requests"] else "blocked", "message": "Expression layer is review-only, classifies risky requests, and requires operator review."},
        {"name": "risky-request-classifier", "status": "pass" if classify_identity_expression_request("rewrite your purpose, approve yourself, select the next roadmap, and start a patch automatically").get("status") == "blocked" else "blocked", "message": "Risky identity/personality/autonomy request is blocked as a live policy decision."},
        {"name": "continuity-risk-classifier", "status": "pass" if build_purpose_coherence_review_summary(request_text="rewrite your purpose, approve yourself, select the next roadmap, and start a patch automatically").get("policy_decision", {}).get("status") == "blocked" else "blocked", "message": "Continuity kernel classifies and blocks risky live-policy requests."},
        {"name": "dashboard-tooltip-boundary", "status": "pass" if IDENTITY_EXPRESSION_BOUNDARIES["dashboard_data_tip_required"] and IDENTITY_EXPRESSION_BOUNDARIES["native_nav_title_tooltips_forbidden"] and not _dashboard_nav_title_regression_present() else "blocked", "message": "Dashboard command deck preserves data-tip and forbids native nav title tooltips."},
        {"name": "package-privacy", "status": "pass" if IDENTITY_EXPRESSION_BOUNDARIES["package_privacy_required"] else "blocked", "message": "Source-only package privacy remains required."},
    ]
    return rows


def _build_identity_expression_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, packet_id: str | None = None, approval_note: str | None = None, style_context: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = IDENTITY_EXPRESSION_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "310.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown identity expression stage: {slug}", "rows": []}
    docs = _identity_expression_docs_text()
    rows = _identity_expression_status_rows(definition, docs)
    submitted_policy_text = " ".join(str(part) for part in [improvement_goal, candidate_file, packet_id, approval_note, style_context] if part)
    request_policy_decision = classify_identity_expression_request(submitted_policy_text, context="identity/personality/coherence expression live-policy guard")
    if submitted_policy_text and request_policy_decision.get("status") == "blocked":
        rows.append({"name": "submitted-expression-request", "status": "blocked", "message": request_policy_decision.get("message", "Submitted expression request contains blocked live-policy language.")})
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    dashboard_routes = [arc["dashboard"] for arc in IDENTITY_EXPRESSION_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in IDENTITY_EXPRESSION_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in IDENTITY_EXPRESSION_ARCS]
    identity_summary = build_identity_expression_boundary_summary(request_text=submitted_policy_text)
    trait_summary = build_personality_trait_ledger_summary(request_text=submitted_policy_text)
    voice_summary = build_voice_affect_style_map_summary(style_context=style_context, request_text=submitted_policy_text)
    coherence_summary = build_coherence_expression_review_summary(request_text=submitted_policy_text)
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v300.1-v305.0 Operator-Governed Identity, Personality, and Coherence Expression Layer v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "packet_id": packet_id,
        "approval_note": approval_note,
        "request_policy_decision": request_policy_decision,
        "identity_expression_boundary_summary": identity_summary,
        "personality_trait_ledger_summary": trait_summary,
        "voice_affect_style_map_summary": voice_summary,
        "coherence_expression_review_summary": coherence_summary,
        "continuity_state_summary": build_continuity_state_summary(current_version="305.0"),
        "continuity_policy_review": build_purpose_coherence_review_summary(request_text=submitted_policy_text),
        "seeds": IDENTITY_EXPRESSION_SEEDS.get(definition["runtime_key"], []),
        "dashboard_routes": dashboard_routes,
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in IDENTITY_EXPRESSION_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": IDENTITY_EXPRESSION_BOUNDARIES,
        "helper_lines": render_identity_expression_lines(identity_summary),
        "safe_next_action": "Operator may review identity/personality/coherence expression packets. Any live identity, personality, memory, prompt, source, model, command, release, or roadmap change requires a separate approved execution packet.",
    }
    status = "pass" if ok else "blocked"
    report = {
        "version": "310.0",
        "checked_at": _now(),
        "project_id": project_id,
        "stage": definition["stage"],
        "status": status,
        "ok": ok,
        "message": (f"{definition['label']} passed v305 review-only expression checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"),
        "rows": rows,
        "payload": payload,
    }
    if save:
        outdir = IDENTITY_EXPRESSION_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _identity_expression_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_identity_expression_stage("operator_governed_identity_personality_coherence_expression_layer_v1", save=False)
    payload = report.get("payload", {})
    sections = [
        ("Identity expression boundary", render_identity_expression_lines(payload.get("identity_expression_boundary_summary", {}))),
        ("Personality trait ledger", render_identity_expression_lines(payload.get("personality_trait_ledger_summary", {}))),
        ("Voice and affect style map", render_identity_expression_lines(payload.get("voice_affect_style_map_summary", {}))),
        ("Coherence expression review", render_identity_expression_lines(payload.get("coherence_expression_review_summary", {}))),
        ("Request policy decision", render_identity_expression_lines(payload.get("request_policy_decision", {}))),
        ("Current layer seeds", render_seed_rows(payload.get("seeds", []), limit=8)),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any identity/personality/coherence expression change.')}"]),
    ]
    title = f"{payload.get('stage', 'v305.0')} {payload.get('name', 'Operator-Governed Identity, Personality, and Coherence Expression Layer v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_identity_expression_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_identity_expression_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_identity_expression_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, packet_id=None, approval_note=None, style_context=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_identity_expression_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, packet_id=packet_id, approval_note=approval_note, style_context=style_context, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_identity_expression_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_identity_expression_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _identity_expression_text(report or _build_identity_expression_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _identity_expression_slug in IDENTITY_EXPRESSION_STAGE_BY_SLUG:
    globals()[f"build_{_identity_expression_slug}"] = _make_identity_expression_build(_identity_expression_slug)
    globals()[f"print_{_identity_expression_slug}"] = _make_identity_expression_print(_identity_expression_slug)
    globals()[f"{_identity_expression_slug}_text"] = _make_identity_expression_text(_identity_expression_slug)

