EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS: list[dict[str, Any]] = []
for _arc in EXPRESSION_RUNTIME_HEALTH_ARCS:
    for _item in _arc["items"]:
        _stage, _slug, _label, _focus, _route, *_rest = _item
        EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS.append({
            "stage": _stage,
            "slug": _slug,
            "label": _label,
            "version": _arc["version"],
            "final_label": _arc["final_label"],
            "api": _arc["api"],
            "route": _route,
            "dashboard": _arc["dashboard"],
            "runtime_key": _arc["runtime_key"],
            "theme": _arc["theme"],
            "focus": _focus,
            "is_final": bool(_rest and _rest[0]),
        })

EXPRESSION_RUNTIME_HEALTH_STAGE_BY_SLUG = {item["slug"]: item for item in EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS}
EXPRESSION_RUNTIME_HEALTH_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS}
EXPRESSION_RUNTIME_HEALTH_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS}
EXPRESSION_RUNTIME_HEALTH_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS})


def _expression_runtime_health_docs_text() -> str:
    chunks: list[str] = []
    for rel in [
        "README_NEXT_STEPS.md",
        "README_RELEASE_HISTORY.md",
        "conscious_agent/dashboard.py",
        "conscious_agent/api_server.py",
        "conscious_agent/main.py",
        "conscious_agent/release_packaging.py",
        "tools/smoke_check.py",
        "conscious_agent/route_health.py",
        "conscious_agent/behavioral_expression_preview.py",
    ]:
        try:
            chunks.append((ROOT_DIR / rel).read_text(encoding="utf-8"))
        except Exception:
            pass
    return "\n".join(chunks)


def _expression_runtime_health_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required = [
        "dashboard-route-health", "runtime-test-visibility", "behavioral-expression-preview", "style-delta-staging", "expression-runtime-health-audit",
        "operator-governed-behavioral-expression-preview-and-runtime-health-hardening-v1", "route_health.py", "behavioral_expression_preview.py",
        "dashboard_http_route_probe_required", "metadata_consistency_smoke_required", "timeout_aware_smoke_summary",
    ]
    runtime_tokens = ["data/autonomy/dashboard_route_health/", "data/autonomy/runtime_test_visibility/", "data/autonomy/behavioral_expression_preview/", "data/autonomy/style_delta_staging/", "data/autonomy/expression_runtime_health_audit/"]
    false_keys = [key for key, value in EXPRESSION_RUNTIME_HEALTH_BOUNDARIES.items() if value is False]
    true_keys = [key for key, value in EXPRESSION_RUNTIME_HEALTH_BOUNDARIES.items() if value is True]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION and ROUTE_HEALTH_VERSION == SELF_MAINTENANCE_VERSION and BEHAVIORAL_EXPRESSION_PREVIEW_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}; route={ROUTE_HEALTH_VERSION}; expression={BEHAVIORAL_EXPRESSION_PREVIEW_VERSION}"},
        {"name": "route-tokens", "status": "pass" if all(token in docs for token in required) else "blocked", "message": "v306-v310 dashboard/API/CLI/docs tokens are present."},
        {"name": "runtime-privacy-tokens", "status": "pass" if all(token in docs for token in runtime_tokens) else "blocked", "message": "v310 runtime data dirs remain source-only excluded."},
        {"name": "stage-count", "status": "pass" if len(EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS) == 50 else "blocked", "message": f"{len(EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS)} expression/runtime health stage defs."},
        {"name": "route-health-boundary", "status": "pass" if all(EXPRESSION_RUNTIME_HEALTH_BOUNDARIES.get(key) is False for key in false_keys) else "blocked", "message": "Route health cannot auto-fix, execute repair, or infer approval."},
        {"name": "review-only-boundary", "status": "pass" if all(EXPRESSION_RUNTIME_HEALTH_BOUNDARIES.get(key) is True for key in true_keys) else "blocked", "message": "Expression previews and runtime health are review-only."},
        {"name": "dashboard-tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips in nav tabs; custom data-tip remains active."},
    ]
    return rows


def _build_expression_runtime_health_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, style_context: str | None = None, target_surface: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = EXPRESSION_RUNTIME_HEALTH_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "310.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown expression/runtime health stage: {slug}", "rows": []}
    docs = _expression_runtime_health_docs_text()
    rows = _expression_runtime_health_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    submitted = " ".join(str(part) for part in [improvement_goal, candidate_file, style_context, target_surface] if part)
    route_summary = build_route_health_registry_summary(dashboard_text=docs)
    smoke_summary = build_smoke_visibility_summary()
    preview_summary = build_behavioral_expression_preview_summary(request_text=submitted, style_context=style_context)
    delta_summary = build_style_delta_staging_summary(target_surface=target_surface, request_text=submitted)
    audit_summary = build_expression_runtime_health_audit_summary(dashboard_text=docs, request_text=submitted)
    dashboard_routes = [arc["dashboard"] for arc in EXPRESSION_RUNTIME_HEALTH_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in EXPRESSION_RUNTIME_HEALTH_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in EXPRESSION_RUNTIME_HEALTH_ARCS]
    payload = {
        "stage": definition["stage"],
        "slug": definition["slug"],
        "name": definition["label"],
        "arc": "v305.1-v310.0 Operator-Governed Behavioral Expression Preview and Runtime Health Hardening v1",
        "version": definition["version"],
        "dashboard": definition["dashboard"],
        "api": f"/api/{definition['api']}/{definition['route']}",
        "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"],
        "focus": definition["focus"],
        "project_id": project_id,
        "improvement_goal": improvement_goal,
        "candidate_file": candidate_file,
        "style_context": style_context,
        "target_surface": target_surface,
        "route_health_summary": route_summary,
        "smoke_visibility_summary": smoke_summary,
        "behavioral_expression_preview_summary": preview_summary,
        "style_delta_staging_summary": delta_summary,
        "expression_runtime_health_audit_summary": audit_summary,
        "dashboard_routes": dashboard_routes,
        "api_routes": api_routes,
        "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": EXPRESSION_RUNTIME_HEALTH_BOUNDARIES,
        "safe_next_action": "Operator may review route health, smoke visibility, behavioral expression previews, and style deltas. Any live change requires a separate approved execution packet.",
    }
    status = "pass" if ok else "blocked"
    report = {"version": "310.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v310 review-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = EXPRESSION_RUNTIME_HEALTH_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _expression_runtime_health_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_expression_runtime_health_stage("operator_governed_behavioral_expression_preview_and_runtime_health_hardening_v1", save=False)
    payload = report.get("payload", {})
    sections = [
        ("Route health registry", render_route_health_lines(payload.get("route_health_summary", {}))),
        ("Smoke visibility", render_route_health_lines(payload.get("smoke_visibility_summary", {}))),
        ("Behavioral expression preview", render_behavioral_expression_lines(payload.get("behavioral_expression_preview_summary", {}))),
        ("Style delta staging", render_behavioral_expression_lines(payload.get("style_delta_staging_summary", {}))),
        ("Expression/runtime audit", render_behavioral_expression_lines(payload.get("expression_runtime_health_audit_summary", {}))),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any live change.')}"]),
    ]
    title = f"{payload.get('stage', 'v310.0')} {payload.get('name', 'Operator-Governed Behavioral Expression Preview and Runtime Health Hardening v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_expression_runtime_health_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_expression_runtime_health_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_expression_runtime_health_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, style_context=None, target_surface=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_expression_runtime_health_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, style_context=style_context, target_surface=target_surface, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_expression_runtime_health_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_expression_runtime_health_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _expression_runtime_health_text(report or _build_expression_runtime_health_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _expression_runtime_health_slug in EXPRESSION_RUNTIME_HEALTH_STAGE_BY_SLUG:
    globals()[f"build_{_expression_runtime_health_slug}"] = _make_expression_runtime_health_build(_expression_runtime_health_slug)
    globals()[f"print_{_expression_runtime_health_slug}"] = _make_expression_runtime_health_print(_expression_runtime_health_slug)
    globals()[f"{_expression_runtime_health_slug}_text"] = _make_expression_runtime_health_text(_expression_runtime_health_slug)

SUPERVISED_RUNTIME_STAGE_DEFS.extend(EXPRESSION_RUNTIME_HEALTH_STAGE_DEFS)
