def _conversational_expression_docs_text() -> str:
    chunks: list[str] = []
    for rel in [
        "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py",
        "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/route_health.py", "conscious_agent/behavioral_expression_preview.py", "conscious_agent/conversational_expression_sandbox.py",
    ]:
        try:
            chunks.append((ROOT_DIR / rel).read_text(encoding="utf-8"))
        except Exception:
            pass
    return "\n".join(chunks)


def _conversational_expression_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required = [
        "expression-profile-packets", "conversation-scenario-sandbox", "expression-regression-review", "expression-operator-review-console", "conversational-expression-sandbox-audit",
        "operator-governed-conversational-expression-sandbox-v1", "conversational_expression_sandbox.py", "scenario_sandbox_runs_live_chat=False", "operator_review_console_grants_approval=False",
        "sandbox_audit_promotes_to_live=False", "dashboard_http_route_probe_required", "data-tip", "command-deck",
    ]
    false_keys = [key for key, value in CONVERSATIONAL_EXPRESSION_SANDBOX_LAYER_BOUNDARIES.items() if value is False]
    true_keys = [key for key, value in CONVERSATIONAL_EXPRESSION_SANDBOX_LAYER_BOUNDARIES.items() if value is True]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"SELF_MAINTENANCE_VERSION={SELF_MAINTENANCE_VERSION}"},
        {"name": "docs-and-source-tokens", "status": "pass" if all(token in docs for token in required) else "blocked", "message": "Docs/source include v315 routes, module, smoke, and boundary tokens."},
        {"name": "runtime-dirs", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in CONVERSATIONAL_EXPRESSION_SANDBOX_RUNTIME_DIRS) else "blocked", "message": "Runtime data paths remain private and source-only excluded."},
        {"name": "stage-count", "status": "pass" if len(CONVERSATIONAL_EXPRESSION_SANDBOX_STAGE_DEFS) == 50 else "blocked", "message": f"{len(CONVERSATIONAL_EXPRESSION_SANDBOX_STAGE_DEFS)} conversational expression stage defs."},
        {"name": "false-boundaries", "status": "pass" if all(CONVERSATIONAL_EXPRESSION_SANDBOX_LAYER_BOUNDARIES.get(key) is False for key in false_keys) else "blocked", "message": "Sandbox cannot apply profiles, run live chat, mutate memory, rewrite prompts, approve, publish, or promote."},
        {"name": "true-boundaries", "status": "pass" if all(CONVERSATIONAL_EXPRESSION_SANDBOX_LAYER_BOUNDARIES.get(key) is True for key in true_keys) else "blocked", "message": "Sandbox remains review-only, sandbox-only, operator-reviewed, and package-private."},
        {"name": "dashboard-tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips in nav tabs; custom data-tip remains active."},
    ]
    return rows


def _build_conversational_expression_sandbox_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, style_context: str | None = None, target_surface: str | None = None, profile_name: str | None = None, scenario: str | None = None, sample_text: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = CONVERSATIONAL_EXPRESSION_SANDBOX_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "315.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown conversational expression sandbox stage: {slug}", "rows": []}
    docs = _conversational_expression_docs_text()
    rows = _conversational_expression_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    submitted = " ".join(str(part) for part in [improvement_goal, candidate_file, style_context, target_surface, profile_name, scenario, sample_text] if part)
    profile_summary = build_expression_profile_packet_summary(profile_name=profile_name, request_text=submitted)
    scenario_summary = build_conversation_scenario_sandbox_summary(scenario=scenario or style_context, request_text=submitted, profile_name=profile_name)
    regression_summary = build_expression_regression_review_summary(sample_text=sample_text, request_text=submitted)
    console_summary = build_expression_operator_review_console_summary(profile_name=profile_name, request_text=submitted)
    audit_summary = build_conversational_expression_sandbox_audit_summary(dashboard_text=docs, request_text=submitted, profile_name=profile_name)
    dashboard_routes = [arc["dashboard"] for arc in CONVERSATIONAL_EXPRESSION_SANDBOX_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in CONVERSATIONAL_EXPRESSION_SANDBOX_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in CONVERSATIONAL_EXPRESSION_SANDBOX_ARCS]
    payload = {
        "stage": definition["stage"], "slug": definition["slug"], "name": definition["label"],
        "arc": "v310.1-v315.0 Operator-Governed Conversational Expression Sandbox v1", "version": definition["version"],
        "dashboard": definition["dashboard"], "api": f"/api/{definition['api']}/{definition['route']}", "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"], "focus": definition["focus"], "project_id": project_id, "improvement_goal": improvement_goal, "candidate_file": candidate_file,
        "style_context": style_context, "target_surface": target_surface, "profile_name": profile_name, "scenario": scenario, "sample_text": sample_text,
        "expression_profile_packet": profile_summary, "conversation_scenario_sandbox": scenario_summary, "expression_regression_review": regression_summary,
        "operator_review_console": console_summary, "conversational_expression_sandbox_audit": audit_summary,
        "dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in CONVERSATIONAL_EXPRESSION_SANDBOX_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": CONVERSATIONAL_EXPRESSION_SANDBOX_LAYER_BOUNDARIES,
        "safe_next_action": "Operator may review sandboxed expression profiles and scenario outputs. Any live chat or prompt change requires a separate explicit approved execution packet.",
    }
    status = "pass" if ok else "blocked"
    report = {"version": "315.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v315 review-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = CONVERSATIONAL_EXPRESSION_SANDBOX_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _conversational_expression_sandbox_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_conversational_expression_sandbox_stage("operator_governed_conversational_expression_sandbox_v1", save=False)
    payload = report.get("payload", {})
    sections = [
        ("Expression profile packet", render_conversational_expression_lines(payload.get("expression_profile_packet", {}))),
        ("Conversation scenario sandbox", render_conversational_expression_lines(payload.get("conversation_scenario_sandbox", {}))),
        ("Expression regression review", render_conversational_expression_lines(payload.get("expression_regression_review", {}))),
        ("Operator review console", render_conversational_expression_lines(payload.get("operator_review_console", {}))),
        ("Conversational expression sandbox audit", render_conversational_expression_lines(payload.get("conversational_expression_sandbox_audit", {}))),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any live expression change.')}"]),
    ]
    title = f"{payload.get('stage', 'v315.0')} {payload.get('name', 'Operator-Governed Conversational Expression Sandbox v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_conversational_expression_sandbox_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_conversational_expression_sandbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_conversational_expression_sandbox_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, style_context=None, target_surface=None, profile_name=None, scenario=None, sample_text=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_conversational_expression_sandbox_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, style_context=style_context, target_surface=target_surface, profile_name=profile_name, scenario=scenario, sample_text=sample_text, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_conversational_expression_sandbox_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_conversational_expression_sandbox_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _conversational_expression_sandbox_text(report or _build_conversational_expression_sandbox_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _conversational_expression_sandbox_slug in CONVERSATIONAL_EXPRESSION_SANDBOX_STAGE_BY_SLUG:
    globals()[f"build_{_conversational_expression_sandbox_slug}"] = _make_conversational_expression_sandbox_build(_conversational_expression_sandbox_slug)
    globals()[f"print_{_conversational_expression_sandbox_slug}"] = _make_conversational_expression_sandbox_print(_conversational_expression_sandbox_slug)
    globals()[f"{_conversational_expression_sandbox_slug}_text"] = _make_conversational_expression_sandbox_text(_conversational_expression_sandbox_slug)

