def _expression_application_bridge_docs_text() -> str:
    rels = ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "conscious_agent/route_health.py", "conscious_agent/expression_application_bridge.py", "tools/smoke_check.py"]
    parts = []
    for rel in rels:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _expression_application_bridge_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    false_keys = [key for key, value in EXPRESSION_APPLICATION_BRIDGE_LAYER_BOUNDARIES.items() if value is False]
    true_keys = [key for key, value in EXPRESSION_APPLICATION_BRIDGE_LAYER_BOUNDARIES.items() if value is True]
    required_tokens = ["expression-approval-criteria", "expression-live-surface-impact-map", "expression-implementation-packet-draft", "expression-rollback-reversion-plan", "expression-application-bridge-audit", "operator-governed-conversational-expression-application-bridge-v1", "expression_application_bridge.py", "dashboard_http_route_probe_required"]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION and EXPRESSION_APPLICATION_BRIDGE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"self={SELF_MAINTENANCE_VERSION}; bridge={EXPRESSION_APPLICATION_BRIDGE_VERSION}"},
        {"name": "docs-tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Docs/source mention every v320 route, module, final CLI/API token, and route probe requirement."},
        {"name": "runtime-dirs", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in EXPRESSION_APPLICATION_BRIDGE_RUNTIME_DIRS) else "blocked", "message": "Runtime data paths remain private and source-only excluded."},
        {"name": "stage-count", "status": "pass" if len(EXPRESSION_APPLICATION_BRIDGE_STAGE_DEFS) == 50 else "blocked", "message": f"{len(EXPRESSION_APPLICATION_BRIDGE_STAGE_DEFS)} expression application bridge stage defs."},
        {"name": "false-boundaries", "status": "pass" if all(EXPRESSION_APPLICATION_BRIDGE_LAYER_BOUNDARIES.get(key) is False for key in false_keys) else "blocked", "message": "Bridge cannot approve, apply live expression, write source, mutate memory, rewrite prompts, or execute rollback."},
        {"name": "true-boundaries", "status": "pass" if all(EXPRESSION_APPLICATION_BRIDGE_LAYER_BOUNDARIES.get(key) is True for key in true_keys) else "blocked", "message": "Bridge remains review-only, packet-draft-only, operator-reviewed, and package-private."},
        {"name": "dashboard-tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips in nav tabs; custom data-tip remains active."},
    ]
    return rows


def _build_expression_application_bridge_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, style_context: str | None = None, target_surface: str | None = None, profile_name: str | None = None, scenario: str | None = None, sample_text: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = EXPRESSION_APPLICATION_BRIDGE_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "325.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown expression application bridge stage: {slug}", "rows": []}
    docs = _expression_application_bridge_docs_text()
    rows = _expression_application_bridge_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    submitted = " ".join(str(part) for part in [improvement_goal, candidate_file, style_context, target_surface, profile_name, scenario, sample_text] if part)
    approval_summary = build_expression_approval_criteria_summary(profile_name=profile_name, request_text=submitted)
    surface_summary = build_expression_live_surface_impact_map_summary(profile_name=profile_name, request_text=submitted)
    packet_summary = build_expression_implementation_packet_draft_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    rollback_summary = build_expression_rollback_reversion_plan_summary(profile_name=profile_name, request_text=submitted)
    audit_summary = build_expression_application_bridge_audit_summary(dashboard_text=docs, profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    dashboard_routes = [arc["dashboard"] for arc in EXPRESSION_APPLICATION_BRIDGE_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in EXPRESSION_APPLICATION_BRIDGE_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in EXPRESSION_APPLICATION_BRIDGE_ARCS]
    payload = {
        "stage": definition["stage"], "slug": definition["slug"], "name": definition["label"],
        "arc": "v315.1-v320.0 Operator-Governed Conversational Expression Application Bridge v1", "version": definition["version"],
        "dashboard": definition["dashboard"], "api": f"/api/{definition['api']}/{definition['route']}", "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"], "focus": definition["focus"], "project_id": project_id, "improvement_goal": improvement_goal, "candidate_file": candidate_file,
        "style_context": style_context, "target_surface": target_surface, "profile_name": profile_name, "scenario": scenario, "sample_text": sample_text,
        "expression_approval_criteria": approval_summary, "expression_live_surface_impact_map": surface_summary,
        "expression_implementation_packet_draft": packet_summary, "expression_rollback_reversion_plan": rollback_summary,
        "expression_application_bridge_audit": audit_summary, "dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in EXPRESSION_APPLICATION_BRIDGE_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": EXPRESSION_APPLICATION_BRIDGE_LAYER_BOUNDARIES,
        "safe_next_action": "Operator may review expression application bridge packets. Any live expression change still requires a separate explicit approved execution packet.",
    }
    status = "pass" if ok else "blocked"
    report = {"version": "325.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v320 review-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = EXPRESSION_APPLICATION_BRIDGE_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _expression_application_bridge_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_expression_application_bridge_stage("operator_governed_conversational_expression_application_bridge_v1", save=False)
    payload = report.get("payload", {})
    sections = [
        ("Expression approval criteria", render_expression_application_bridge_lines(payload.get("expression_approval_criteria", {}))),
        ("Live surface impact map", render_expression_application_bridge_lines(payload.get("expression_live_surface_impact_map", {}))),
        ("Implementation packet draft", render_expression_application_bridge_lines(payload.get("expression_implementation_packet_draft", {}))),
        ("Rollback reversion plan", render_expression_application_bridge_lines(payload.get("expression_rollback_reversion_plan", {}))),
        ("Expression application bridge audit", render_expression_application_bridge_lines(payload.get("expression_application_bridge_audit", {}))),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any live expression change.')}" ]),
    ]
    title = f"{payload.get('stage', 'v320.0')} {payload.get('name', 'Operator-Governed Conversational Expression Application Bridge v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_expression_application_bridge_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_expression_application_bridge_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_expression_application_bridge_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, style_context=None, target_surface=None, profile_name=None, scenario=None, sample_text=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_expression_application_bridge_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, style_context=style_context, target_surface=target_surface, profile_name=profile_name, scenario=scenario, sample_text=sample_text, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_expression_application_bridge_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_expression_application_bridge_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _expression_application_bridge_text(report or _build_expression_application_bridge_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _expression_application_bridge_slug in EXPRESSION_APPLICATION_BRIDGE_STAGE_BY_SLUG:
    globals()[f"build_{_expression_application_bridge_slug}"] = _make_expression_application_bridge_build(_expression_application_bridge_slug)
    globals()[f"print_{_expression_application_bridge_slug}"] = _make_expression_application_bridge_print(_expression_application_bridge_slug)
    globals()[f"{_expression_application_bridge_slug}_text"] = _make_expression_application_bridge_text(_expression_application_bridge_slug)

