EXPRESSION_PATCH_DRY_RUN_CLI_MAP = {item["slug"].replace("_", "-"): item["slug"] for item in EXPRESSION_PATCH_DRY_RUN_STAGE_DEFS}
EXPRESSION_PATCH_DRY_RUN_ROUTE_MAP = {f"{item['api']}/{item['route']}": item["slug"] for item in EXPRESSION_PATCH_DRY_RUN_STAGE_DEFS}
EXPRESSION_PATCH_DRY_RUN_ROUTE_MAP.update({item["slug"].replace("_", "-"): item["slug"] for item in EXPRESSION_PATCH_DRY_RUN_STAGE_DEFS})


def _expression_patch_dry_run_docs_text() -> str:
    rels = ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "conscious_agent/route_health.py", "conscious_agent/expression_patch_dry_run.py", "tools/smoke_check.py"]
    parts = []
    for rel in rels:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _expression_patch_dry_run_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    false_keys = [key for key, value in EXPRESSION_PATCH_DRY_RUN_LAYER_BOUNDARIES.items() if value is False]
    true_keys = [key for key, value in EXPRESSION_PATCH_DRY_RUN_LAYER_BOUNDARIES.items() if value is True]
    required_tokens = ["expression-patch-candidates", "expression-sandbox-diff-preview", "expression-dry-run-verification-plan", "expression-dry-run-review-packet", "expression-patch-dry-run-audit", "operator-governed-expression-patch-dry-run-sandbox-v1", "expression_patch_dry_run.py", "dashboard_http_route_probe_required"]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION and EXPRESSION_PATCH_DRY_RUN_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"self={SELF_MAINTENANCE_VERSION}; dry_run={EXPRESSION_PATCH_DRY_RUN_VERSION}"},
        {"name": "docs-tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Docs/source mention every v325 route, module, final CLI/API token, and route probe requirement."},
        {"name": "runtime-dirs", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in EXPRESSION_PATCH_DRY_RUN_RUNTIME_DIRS) else "blocked", "message": "Runtime data paths remain private and source-only excluded."},
        {"name": "stage-count", "status": "pass" if len(EXPRESSION_PATCH_DRY_RUN_STAGE_DEFS) == 50 else "blocked", "message": f"{len(EXPRESSION_PATCH_DRY_RUN_STAGE_DEFS)} expression patch dry-run stage defs."},
        {"name": "false-boundaries", "status": "pass" if all(EXPRESSION_PATCH_DRY_RUN_LAYER_BOUNDARIES.get(key) is False for key in false_keys) else "blocked", "message": "Dry-run cannot apply patches, write source, execute verification, grant approval, mutate memory, or rewrite prompts."},
        {"name": "true-boundaries", "status": "pass" if all(EXPRESSION_PATCH_DRY_RUN_LAYER_BOUNDARIES.get(key) is True for key in true_keys) else "blocked", "message": "Dry-run remains sandbox-only, review-only, operator-reviewed, and package-private."},
        {"name": "dashboard-tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips in nav tabs; custom data-tip remains active."},
    ]
    return rows


def _build_expression_patch_dry_run_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, style_context: str | None = None, target_surface: str | None = None, profile_name: str | None = None, scenario: str | None = None, sample_text: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = EXPRESSION_PATCH_DRY_RUN_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "325.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown expression patch dry-run stage: {slug}", "rows": []}
    docs = _expression_patch_dry_run_docs_text()
    rows = _expression_patch_dry_run_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    submitted = " ".join(str(part) for part in [improvement_goal, candidate_file, style_context, target_surface, profile_name, scenario, sample_text] if part)
    candidates_summary = build_expression_patch_candidate_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    diff_summary = build_expression_sandbox_diff_preview_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    verification_summary = build_expression_dry_run_verification_plan_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    review_summary = build_expression_dry_run_review_packet_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    audit_summary = build_expression_patch_dry_run_audit_summary(dashboard_text=docs, profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    dashboard_routes = [arc["dashboard"] for arc in EXPRESSION_PATCH_DRY_RUN_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in EXPRESSION_PATCH_DRY_RUN_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in EXPRESSION_PATCH_DRY_RUN_ARCS]
    payload = {
        "stage": definition["stage"], "slug": definition["slug"], "name": definition["label"],
        "arc": "v320.1-v325.0 Operator-Governed Expression Patch Dry-Run Sandbox v1", "version": definition["version"],
        "dashboard": definition["dashboard"], "api": f"/api/{definition['api']}/{definition['route']}", "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"], "focus": definition["focus"], "project_id": project_id, "improvement_goal": improvement_goal, "candidate_file": candidate_file,
        "style_context": style_context, "target_surface": target_surface, "profile_name": profile_name, "scenario": scenario, "sample_text": sample_text,
        "expression_patch_candidates": candidates_summary, "expression_sandbox_diff_preview": diff_summary,
        "expression_dry_run_verification_plan": verification_summary, "expression_dry_run_review_packet": review_summary,
        "expression_patch_dry_run_audit": audit_summary, "dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in EXPRESSION_PATCH_DRY_RUN_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": EXPRESSION_PATCH_DRY_RUN_LAYER_BOUNDARIES,
        "safe_next_action": "Operator may review expression dry-run packets. Any source application still requires a separate explicit approved execution packet.",
    }
    status = "pass" if ok else "blocked"
    report = {"version": "325.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v325 sandbox-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = EXPRESSION_PATCH_DRY_RUN_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _expression_patch_dry_run_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_expression_patch_dry_run_stage("operator_governed_expression_patch_dry_run_sandbox_v1", save=False)
    payload = report.get("payload", {})
    sections = [
        ("Expression patch candidates", render_expression_patch_dry_run_lines(payload.get("expression_patch_candidates", {}))),
        ("Sandbox diff preview", render_expression_patch_dry_run_lines(payload.get("expression_sandbox_diff_preview", {}))),
        ("Dry-run verification plan", render_expression_patch_dry_run_lines(payload.get("expression_dry_run_verification_plan", {}))),
        ("Dry-run review packet", render_expression_patch_dry_run_lines(payload.get("expression_dry_run_review_packet", {}))),
        ("Expression patch dry-run audit", render_expression_patch_dry_run_lines(payload.get("expression_patch_dry_run_audit", {}))),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before any source application.')}" ]),
    ]
    title = f"{payload.get('stage', 'v325.0')} {payload.get('name', 'Operator-Governed Expression Patch Dry-Run Sandbox v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_expression_patch_dry_run_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_expression_patch_dry_run_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_expression_patch_dry_run_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, style_context=None, target_surface=None, profile_name=None, scenario=None, sample_text=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_expression_patch_dry_run_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, style_context=style_context, target_surface=target_surface, profile_name=profile_name, scenario=scenario, sample_text=sample_text, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_expression_patch_dry_run_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_expression_patch_dry_run_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _expression_patch_dry_run_text(report or _build_expression_patch_dry_run_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _expression_patch_dry_run_slug in EXPRESSION_PATCH_DRY_RUN_STAGE_BY_SLUG:
    globals()[f"build_{_expression_patch_dry_run_slug}"] = _make_expression_patch_dry_run_build(_expression_patch_dry_run_slug)
    globals()[f"print_{_expression_patch_dry_run_slug}"] = _make_expression_patch_dry_run_print(_expression_patch_dry_run_slug)
    globals()[f"{_expression_patch_dry_run_slug}_text"] = _make_expression_patch_dry_run_text(_expression_patch_dry_run_slug)

