def _expression_sandbox_trial_docs_text() -> str:
    rels = ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "conscious_agent/route_health.py", "conscious_agent/expression_sandbox_trial_harness.py", "tools/smoke_check.py"]
    parts = []
    for rel in rels:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _expression_sandbox_trial_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    false_keys = [key for key, value in EXPRESSION_SANDBOX_TRIAL_LAYER_BOUNDARIES.items() if value is False]
    true_keys = [key for key, value in EXPRESSION_SANDBOX_TRIAL_LAYER_BOUNDARIES.items() if value is True]
    required_tokens = ["expression-sandbox-trial-packet", "expression-sandbox-workspace-plan", "expression-sandbox-verification-matrix", "expression-sandbox-result-review-prep", "expression-sandbox-trial-harness-audit", "operator-governed-expression-patch-sandbox-trial-harness-v1", "expression_sandbox_trial_harness.py", "dashboard_http_route_probe_required"]
    rows = [
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION and EXPRESSION_SANDBOX_TRIAL_HARNESS_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"self={SELF_MAINTENANCE_VERSION}; trial={EXPRESSION_SANDBOX_TRIAL_HARNESS_VERSION}"},
        {"name": "tokens", "status": "pass" if all(token in docs for token in required_tokens) else "blocked", "message": "Dashboard/API/CLI/docs/smoke tokens for v330 sandbox trial harness are present."},
        {"name": "runtime-dirs", "status": "pass" if all(f"data/autonomy/{key}/" in docs for key in EXPRESSION_SANDBOX_TRIAL_RUNTIME_DIRS) else "blocked", "message": "Runtime data paths remain private and source-only excluded."},
        {"name": "stage-count", "status": "pass" if len(EXPRESSION_SANDBOX_TRIAL_STAGE_DEFS) == 50 else "blocked", "message": f"{len(EXPRESSION_SANDBOX_TRIAL_STAGE_DEFS)} expression sandbox trial stage defs."},
        {"name": "false-boundaries", "status": "pass" if all(EXPRESSION_SANDBOX_TRIAL_LAYER_BOUNDARIES.get(key) is False for key in false_keys) else "blocked", "message": "Trial harness cannot create sandboxes, copy/write files, execute verification, promote, grant approval, mutate memory, or rewrite prompts."},
        {"name": "true-boundaries", "status": "pass" if all(EXPRESSION_SANDBOX_TRIAL_LAYER_BOUNDARIES.get(key) is True for key in true_keys) else "blocked", "message": "Trial harness remains prep-only, review-only, sandbox-isolated, operator-gated, and package-private."},
        {"name": "dashboard-tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips in nav tabs; custom data-tip remains active."},
    ]
    return rows


def _build_expression_sandbox_trial_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, style_context: str | None = None, target_surface: str | None = None, profile_name: str | None = None, scenario: str | None = None, sample_text: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = EXPRESSION_SANDBOX_TRIAL_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "335.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown expression sandbox trial stage: {slug}", "rows": []}
    docs = _expression_sandbox_trial_docs_text()
    rows = _expression_sandbox_trial_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    submitted = " ".join(str(part) for part in [improvement_goal, candidate_file, style_context, target_surface, profile_name, scenario, sample_text] if part)
    trial_packet_summary = build_expression_sandbox_trial_packet_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    workspace_plan_summary = build_expression_sandbox_workspace_plan_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    verification_matrix_summary = build_expression_sandbox_verification_matrix_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    result_review_summary = build_expression_sandbox_result_review_prep_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    audit_summary = build_expression_sandbox_trial_harness_audit_summary(dashboard_text=docs, profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    dashboard_routes = [arc["dashboard"] for arc in EXPRESSION_SANDBOX_TRIAL_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in EXPRESSION_SANDBOX_TRIAL_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in EXPRESSION_SANDBOX_TRIAL_ARCS]
    payload = {
        "stage": definition["stage"], "slug": definition["slug"], "name": definition["label"],
        "arc": "v325.1-v330.0 Operator-Governed Expression Patch Sandbox Trial Harness v1", "version": definition["version"],
        "dashboard": definition["dashboard"], "api": f"/api/{definition['api']}/{definition['route']}", "cli": f"--{definition['slug'].replace('_','-')}",
        "theme": definition["theme"], "focus": definition["focus"], "project_id": project_id, "improvement_goal": improvement_goal, "candidate_file": candidate_file,
        "style_context": style_context, "target_surface": target_surface, "profile_name": profile_name, "scenario": scenario, "sample_text": sample_text,
        "expression_sandbox_trial_packet": trial_packet_summary, "expression_sandbox_workspace_plan": workspace_plan_summary,
        "expression_sandbox_verification_matrix": verification_matrix_summary, "expression_sandbox_result_review_prep": result_review_summary,
        "expression_sandbox_trial_harness_audit": audit_summary, "dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags,
        "runtime_registry_rows": [row for row in EXPRESSION_SANDBOX_TRIAL_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]],
        "boundaries": EXPRESSION_SANDBOX_TRIAL_LAYER_BOUNDARIES,
        "safe_next_action": "Operator may review sandbox trial harness packets. Any sandbox creation, command execution, source application, or promotion still requires separate explicit approval.",
    }
    status = "pass" if ok else "blocked"
    report = {"version": "335.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v330 prep-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = EXPRESSION_SANDBOX_TRIAL_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _expression_sandbox_trial_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_expression_sandbox_trial_stage("operator_governed_expression_patch_sandbox_trial_harness_v1", save=False)
    payload = report.get("payload", {})
    sections = [
        ("Sandbox trial packet", render_expression_sandbox_trial_harness_lines(payload.get("expression_sandbox_trial_packet", {}))),
        ("Sandbox workspace plan", render_expression_sandbox_trial_harness_lines(payload.get("expression_sandbox_workspace_plan", {}))),
        ("Sandbox verification matrix", render_expression_sandbox_trial_harness_lines(payload.get("expression_sandbox_verification_matrix", {}))),
        ("Sandbox result review prep", render_expression_sandbox_trial_harness_lines(payload.get("expression_sandbox_result_review_prep", {}))),
        ("Sandbox trial harness audit", render_expression_sandbox_trial_harness_lines(payload.get("expression_sandbox_trial_harness_audit", {}))),
        ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]),
        ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before sandbox trial execution.')}"]),
    ]
    title = f"{payload.get('stage', 'v330.0')} {payload.get('name', 'Operator-Governed Expression Patch Sandbox Trial Harness v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_expression_sandbox_trial_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_expression_sandbox_trial_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_expression_sandbox_trial_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, style_context=None, target_surface=None, profile_name=None, scenario=None, sample_text=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_expression_sandbox_trial_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, style_context=style_context, target_surface=target_surface, profile_name=profile_name, scenario=scenario, sample_text=sample_text, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_expression_sandbox_trial_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_expression_sandbox_trial_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _expression_sandbox_trial_text(report or _build_expression_sandbox_trial_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _expression_sandbox_trial_slug in EXPRESSION_SANDBOX_TRIAL_STAGE_BY_SLUG:
    globals()[f"build_{_expression_sandbox_trial_slug}"] = _make_expression_sandbox_trial_build(_expression_sandbox_trial_slug)
    globals()[f"print_{_expression_sandbox_trial_slug}"] = _make_expression_sandbox_trial_print(_expression_sandbox_trial_slug)
    globals()[f"{_expression_sandbox_trial_slug}_text"] = _make_expression_sandbox_trial_text(_expression_sandbox_trial_slug)

