def _expression_sandbox_execution_bridge_docs_text() -> str:
    parts: list[str] = []
    for rel in ["README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/dashboard.py", "conscious_agent/api_server.py", "conscious_agent/main.py", "conscious_agent/release_packaging.py", "tools/smoke_check.py", "conscious_agent/route_health.py", "conscious_agent/expression_sandbox_execution_bridge.py"]:
        path = ROOT_DIR / rel
        if path.exists():
            parts.append(path.read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parts)


def _expression_sandbox_execution_bridge_status_rows(definition: dict[str, Any], docs: str) -> list[dict[str, str]]:
    required = ["expression-sandbox-execution-approval-gate", "expression-sandbox-workspace-execution-packet", "expression-sandbox-patch-bundle-packet", "expression-sandbox-verification-command-packet", "expression-sandbox-execution-packet-bridge-audit", "operator-governed-expression-sandbox-trial-execution-packet-bridge-v1", "expression_sandbox_execution_bridge.py", "approval_gate_grants_approval=False", "workspace_execution_packet_copies_files=False", "workspace_execution_packet_writes_files=False", "patch_bundle_applies_patch=False", "verification_command_packet_executes_commands=False", "execution_bridge_executes_sandbox=False", "dashboard_http_route_probe_required"]
    missing = [token for token in required if token not in docs]
    false_keys = [key for key, value in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_LAYER_BOUNDARIES.items() if value is False]
    true_keys = [key for key, value in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_LAYER_BOUNDARIES.items() if value is True]
    return [
        {"name": "stage-definition", "status": "pass" if definition["slug"] in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_STAGE_BY_SLUG else "blocked", "message": definition["label"]},
        {"name": "version-markers", "status": "pass" if SELF_MAINTENANCE_VERSION == SELF_MAINTENANCE_VERSION and EXPRESSION_SANDBOX_EXECUTION_BRIDGE_VERSION == SELF_MAINTENANCE_VERSION else "blocked", "message": f"self={SELF_MAINTENANCE_VERSION}; bridge={EXPRESSION_SANDBOX_EXECUTION_BRIDGE_VERSION}"},
        {"name": "docs-runtime-smoke-tokens", "status": "pass" if not missing else "blocked", "message": "All v335 tokens present." if not missing else "Missing: " + ", ".join(missing)},
        {"name": "runtime-stage-count", "status": "pass" if len(EXPRESSION_SANDBOX_EXECUTION_BRIDGE_STAGE_DEFS) == 50 else "blocked", "message": f"{len(EXPRESSION_SANDBOX_EXECUTION_BRIDGE_STAGE_DEFS)} v335 stage definitions registered."},
        {"name": "false-boundaries", "status": "pass" if all(EXPRESSION_SANDBOX_EXECUTION_BRIDGE_LAYER_BOUNDARIES.get(key) is False for key in false_keys) else "blocked", "message": "Execution bridge cannot approve, copy, write, apply patches, execute commands, promote, mutate memory, or rewrite prompts."},
        {"name": "true-boundaries", "status": "pass" if all(EXPRESSION_SANDBOX_EXECUTION_BRIDGE_LAYER_BOUNDARIES.get(key) is True for key in true_keys) else "blocked", "message": "Execution bridge remains packet-only, review-only, approval-gated, and package-private."},
        {"name": "dashboard-tooltip-regression", "status": "pass" if not _dashboard_nav_title_regression_present() else "blocked", "message": "No native title tooltips in nav tabs; custom data-tip remains active."},
    ]


def _build_expression_sandbox_execution_bridge_stage(slug: str, project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, style_context: str | None = None, target_surface: str | None = None, profile_name: str | None = None, scenario: str | None = None, sample_text: str | None = None, save: bool = True, **_: Any) -> dict[str, Any]:
    definition = EXPRESSION_SANDBOX_EXECUTION_BRIDGE_STAGE_BY_SLUG.get(slug)
    if not definition:
        return {"version": "335.0", "status": "blocked", "ok": False, "checked_at": _now(), "message": f"Unknown expression sandbox execution bridge stage: {slug}", "rows": []}
    docs = _expression_sandbox_execution_bridge_docs_text()
    rows = _expression_sandbox_execution_bridge_status_rows(definition, docs)
    blockers = [row["name"] for row in rows if row.get("status") not in {"pass", "warn"}]
    ok = not blockers
    submitted = " ".join(str(part) for part in [improvement_goal, candidate_file, style_context, target_surface, profile_name, scenario, sample_text] if part)
    approval_summary = build_expression_sandbox_execution_approval_gate_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    workspace_summary = build_expression_sandbox_workspace_execution_packet_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    patch_bundle_summary = build_expression_sandbox_patch_bundle_packet_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    verification_summary = build_expression_sandbox_verification_command_packet_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    audit_summary = build_expression_sandbox_execution_packet_bridge_audit_summary(dashboard_text=docs, profile_name=profile_name, request_text=submitted, target_surface=target_surface)
    dashboard_routes = [arc["dashboard"] for arc in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_ARCS]
    api_routes = [f"/api/{arc['api']}/layer" for arc in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_ARCS]
    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_ARCS]
    payload = {"stage": definition["stage"], "slug": definition["slug"], "name": definition["label"], "arc": "v330.1-v335.0 Operator-Governed Expression Sandbox Trial Execution Packet Bridge v1", "version": definition["version"], "dashboard": definition["dashboard"], "api": f"/api/{definition['api']}/{definition['theme']}", "cli": f"--{definition['slug'].replace('_','-')}", "theme": definition["theme"], "focus": definition["focus"], "project_id": project_id, "improvement_goal": improvement_goal, "candidate_file": candidate_file, "style_context": style_context, "target_surface": target_surface, "profile_name": profile_name, "scenario": scenario, "sample_text": sample_text, "expression_sandbox_execution_approval_gate": approval_summary, "expression_sandbox_workspace_execution_packet": workspace_summary, "expression_sandbox_patch_bundle_packet": patch_bundle_summary, "expression_sandbox_verification_command_packet": verification_summary, "expression_sandbox_execution_packet_bridge_audit": audit_summary, "dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags, "runtime_registry_rows": [row for row in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]], "boundaries": EXPRESSION_SANDBOX_EXECUTION_BRIDGE_LAYER_BOUNDARIES, "safe_next_action": "Operator may review sandbox execution bridge packets. Any workspace creation, patch application, command execution, or promotion still requires separate explicit approval."}
    status = "pass" if ok else "blocked"
    report = {"version": "335.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v335 packet-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = EXPRESSION_SANDBOX_EXECUTION_BRIDGE_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


def _expression_sandbox_execution_bridge_text(report: dict[str, Any] | None = None, full: bool = False) -> str:
    report = report or _build_expression_sandbox_execution_bridge_stage("operator_governed_expression_sandbox_trial_execution_packet_bridge_v1", save=False)
    payload = report.get("payload", {})
    sections = [("Approval gate", render_expression_sandbox_execution_bridge_lines(payload.get("expression_sandbox_execution_approval_gate", {}))), ("Workspace execution packet", render_expression_sandbox_execution_bridge_lines(payload.get("expression_sandbox_workspace_execution_packet", {}))), ("Patch bundle packet", render_expression_sandbox_execution_bridge_lines(payload.get("expression_sandbox_patch_bundle_packet", {}))), ("Verification command packet", render_expression_sandbox_execution_bridge_lines(payload.get("expression_sandbox_verification_command_packet", {}))), ("Execution packet bridge audit", render_expression_sandbox_execution_bridge_lines(payload.get("expression_sandbox_execution_packet_bridge_audit", {}))), ("Surfaces", [f"- dashboard: {', '.join(payload.get('dashboard_routes', []))}", f"- api: {', '.join(payload.get('api_routes', []))}", f"- cli: {', '.join(payload.get('cli_flags', []))}"]), ("Safe next action", [f"- {payload.get('safe_next_action', 'Operator review required before sandbox execution packet use.')}"])]
    title = f"{payload.get('stage', 'v335.0')} {payload.get('name', 'Operator-Governed Expression Sandbox Trial Execution Packet Bridge v1')}"
    return render_governance_packet(title, report, sections, full=full)


def _make_expression_sandbox_execution_bridge_build(slug: str):
    def _builder(project_id: str = "default", improvement_goal: str | None = None, candidate_file: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
        return _build_expression_sandbox_execution_bridge_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, save=save, **kwargs)
    _builder.__name__ = f"build_{slug}"
    return _builder


def _make_expression_sandbox_execution_bridge_print(slug: str):
    def _printer(project_id="default", improvement_goal=None, candidate_file=None, style_context=None, target_surface=None, profile_name=None, scenario=None, sample_text=None, full=False, json_output=False, save=False, **kwargs):
        report = _build_expression_sandbox_execution_bridge_stage(slug, project_id=project_id, improvement_goal=improvement_goal, candidate_file=candidate_file, style_context=style_context, target_surface=target_surface, profile_name=profile_name, scenario=scenario, sample_text=sample_text, save=save, **kwargs)
        if json_output:
            print(json.dumps(report, indent=2))
        else:
            print(_expression_sandbox_execution_bridge_text(report, full=full))
    _printer.__name__ = f"print_{slug}"
    return _printer


def _make_expression_sandbox_execution_bridge_text(slug: str):
    def _text(report: dict[str, Any] | None = None, full: bool = False) -> str:
        return _expression_sandbox_execution_bridge_text(report or _build_expression_sandbox_execution_bridge_stage(slug, save=False), full=full)
    _text.__name__ = f"{slug}_text"
    return _text


for _expression_sandbox_execution_bridge_slug in EXPRESSION_SANDBOX_EXECUTION_BRIDGE_STAGE_BY_SLUG:
    globals()[f"build_{_expression_sandbox_execution_bridge_slug}"] = _make_expression_sandbox_execution_bridge_build(_expression_sandbox_execution_bridge_slug)
    globals()[f"print_{_expression_sandbox_execution_bridge_slug}"] = _make_expression_sandbox_execution_bridge_print(_expression_sandbox_execution_bridge_slug)
    globals()[f"{_expression_sandbox_execution_bridge_slug}_text"] = _make_expression_sandbox_execution_bridge_text(_expression_sandbox_execution_bridge_slug)

