    comparison_summary = build_expression_sandbox_outcome_comparison_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface, evidence=sample_evidence)
    regression_summary = build_expression_sandbox_regression_result_review_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface, evidence=sample_evidence)
    revision_summary = build_expression_sandbox_revision_recommendations_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface, evidence=sample_evidence)
    promotion_summary = build_expression_sandbox_promotion_review_prep_summary(profile_name=profile_name, request_text=submitted, target_surface=target_surface, evidence=sample_evidence)
