    cli_flags = ["--" + arc["items"][-1][1].replace("_", "-") for arc in EXPRESSION_SANDBOX_RESULT_INTAKE_ARCS]
    payload = {"stage": definition["stage"], "slug": definition["slug"], "name": definition["label"], "arc": "v335.1-v340.0 Operator-Governed Expression Sandbox Trial Result Intake and Promotion Review Prep v1", "version": definition["version"], "dashboard": definition["dashboard"], "api": f"/api/{definition['api']}/{definition['theme']}", "cli": f"--{definition['slug'].replace('_','-')}", "theme": definition["theme"], "focus": definition["focus"], "project_id": project_id, "improvement_goal": improvement_goal, "candidate_file": candidate_file, "style_context": style_context, "target_surface": target_surface, "profile_name": profile_name, "scenario": scenario, "sample_text": sample_text, "expression_sandbox_trial_evidence_intake": evidence_intake_summary, "expression_sandbox_outcome_comparison": comparison_summary, "expression_sandbox_regression_result_review": regression_summary, "expression_sandbox_revision_recommendations": revision_summary, "expression_sandbox_promotion_review_prep": promotion_summary, "expression_sandbox_result_intake_promotion_review_audit": audit_summary, "dashboard_routes": dashboard_routes, "api_routes": api_routes, "cli_flags": cli_flags, "runtime_registry_rows": [row for row in EXPRESSION_SANDBOX_RESULT_INTAKE_STAGE_DEFS if row["runtime_key"] == definition["runtime_key"]], "boundaries": EXPRESSION_SANDBOX_RESULT_INTAKE_LAYER_BOUNDARIES, "safe_next_action": "Operator may review sandbox result evidence and promotion-review prep. Live promotion, source mutation, prompt changes, or approval still require separate explicit operator authorization."}
    status = "pass" if ok else "blocked"
    report = {"version": "345.0", "checked_at": _now(), "project_id": project_id, "stage": definition["stage"], "status": status, "ok": ok, "message": (f"{definition['label']} passed v340 review-only checks." if ok else f"{definition['label']} blocked by: {', '.join(blockers)}"), "rows": rows, "payload": payload}
    if save:
        outdir = EXPRESSION_SANDBOX_RESULT_INTAKE_RUNTIME_DIRS[definition["runtime_key"]]
        outdir.mkdir(parents=True, exist_ok=True)
        write_text_atomic((outdir / f"{definition['slug']}.json"), json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    return report


