def _promotion_items(prefix: str, final_slug: str, final_label: str, start_minor: int, final_version: str) -> list[tuple[Any, ...]]:
    names = ["schema", "binder", "scope", "risk", "verification", "rollback", "packet", "dashboard_api_cli", "safety_audit", "layer"]
    labels = ["Schema", "Binder", "Scope", "Risk", "Verification", "Rollback", "Packet", "Dashboard/API/CLI", "Safety Audit", final_label]
    items = []
    for i, (name, label) in enumerate(zip(names, labels), start=1):
        stage = final_version if i == 10 else f"v{start_minor + (i-1)/10:.1f}"
        slug = final_slug if i == 10 else f"{prefix}_{name}"
        focus = f"{label} for {final_label}; review-only and non-mutating."
        route = "layer" if i == 10 else name.replace("_", "-")
        items.append((stage, slug, label, focus, route, True) if i == 10 else (stage, slug, label, focus, route))
    return items

