def _build_v455_stage(slug: str, project_id: str = "eidolon", improvement_goal: str | None = None, save: bool = True, **kwargs: Any) -> dict[str, Any]:
    definition = next(item for item in V455_STAGE_DEFS if item["slug"] == slug)
